console.log("\n— Ponte Sentinella → Genesi: i referti per la legge di sito —");
// Il vincolo che conta più di tutti: la legge di sito decide le distanze di
// sicurezza, quindi una PPV inventata farebbe più danno di qualunque altro
// numero finto in tutta la piattaforma. Questi test esistono per quello.
test("una volata senza PPV misurata NON diventa un referto", () => {
  const r = sentinella.refertoDaVolata({ id: "v2", data: "2026-07-07", distanzaRicettore: 150, kgMaxRitardo: 25 });
  ok(r.pronto === false, "senza misura non può essere pronto");
  ok(r.motivi.includes("ppv"), `e il motivo va detto: ${JSON.stringify(r.motivi)}`);
});
test("PPV a zero, negativa, testuale o vuota vengono tutte rifiutate", () => {
  for (const brutta of [0, -1, "boh", "", null, undefined]) {
    const r = sentinella.refertoDaVolata({ id: "x", data: "2026-07-07", distanzaRicettore: 150, kgMaxRitardo: 25, ppvMisurata: brutta });
    ok(r.pronto === false, `PPV ${JSON.stringify(brutta)} accettata: falserebbe la legge di sito`);
  }
});
test("mancano distanza o carica per ritardo: niente referto, col motivo", () => {
  ok(sentinella.refertoDaVolata({ id: "a", data: "2026-07-08", kgMaxRitardo: 25, ppvMisurata: 4 }).pronto === false, "senza distanza");
  ok(sentinella.refertoDaVolata({ id: "b", data: "2026-07-08", distanzaRicettore: 150, ppvMisurata: 4 }).pronto === false, "senza carica");
  ok(sentinella.refertoDaVolata({}).motivi.length > 0, "volata vuota: motivi, non crash");
});
test("nel file per Genesi entrano SOLO le volate con la misura", () => {
  const V = [{ id: "v1", data: "2026-07-06", distanzaRicettore: 90, kgMaxRitardo: 5.2, ppvMisurata: 3.9, ppvFonte: "strumento" },
             { id: "v2", data: "2026-07-07", distanzaRicettore: 150, kgMaxRitardo: 25 },
             { id: "v3", data: "2026-07-08", distanzaRicettore: 420, kgMaxRitardo: 40, ppvMisurata: 1.35, ppvFonte: "manuale" }];
  const csv = sentinella.csvRefertiGenesi(V.map(v => sentinella.refertoDaVolata(v)));
  const righe = csv.trim().split("\n");
  ok(righe.length === 3, `${righe.length - 1} righe invece di 2: la volata senza misura non deve entrare`);
  ok(!/;150;/.test(csv), "la volata senza PPV è finita nel file");
  ok(righe[1].includes("2026-07-06") && righe[2].includes("2026-07-08"), "le righe vanno ordinate per data");
  ok(righe.every(r => r.split(";").length === righe[0].split(";").length), "una cella con ; spezzerebbe il file");
});
test("zero referti pronti: solo l'intestazione, nessuna riga inventata", () => {
  const solo = sentinella.csvRefertiGenesi([sentinella.refertoDaVolata({ id: "v", data: "2026-07-07", distanzaRicettore: 150, kgMaxRitardo: 25 })]);
  ok(solo.trim().split("\n").length === 1, "un file con righe finte è peggio di un file vuoto");
  ok(typeof sentinella.csvRefertiGenesi(undefined) === "string", "lista assente: stringa, non crash");
});
test("le soglie dichiarate della legge di sito: 3 referti per esistere, 8 per essere solida", () => {
  ok(sentinella.MIN_REFERTI === 3, `MIN_REFERTI ${sentinella.MIN_REFERTI}`);
  ok(sentinella.REFERTI_SOLIDI === 8, `REFERTI_SOLIDI ${sentinella.REFERTI_SOLIDI}`);
});

console.log("\n— Ponte Genesi → Sentinella: la volata prevista —");
// Una volata PROGETTATA non è una volata SPARATA. Tenerle distinte non è
// pedanteria: se una previsione entrasse fra i referti, falserebbe la legge
// di sito, cioè il calcolo da cui dipendono le distanze di sicurezza.
test("una volata senza il campo stato vale ESEGUITA (è ciò che è)", () => {
  ok(sentinella.statoVolata({}) === "eseguita", "le volate storiche non devono cambiare natura");
  ok(sentinella.statoVolata({ stato: "PREVISTA" }) === "prevista", "maiuscole e spazi non contano");
  ok(sentinella.statoVolata({ stato: "boh" }) === "eseguita", "uno stato illeggibile non deve far sparire una volata");
});
test("VINCOLO: una volata prevista non diventa mai un referto", () => {
  const prevista = { id: "p1", data: "2026-07-27", stato: "prevista", distanzaRicettore: 300, kgMaxRitardo: 58, ppvPrevista: 6.4 };
  const r = sentinella.refertoDaVolata(prevista);
  ok(r.pronto === false, "una previsione non è una misura");
  ok(r.motivi.includes("prevista"), `il motivo va detto: ${JSON.stringify(r.motivi)}`);
  ok(r.ppv === null, `la PPV del referto non deve prendere la prevista: ${r.ppv}`);
  const forzata = sentinella.refertoDaVolata({ ...prevista, ppvMisurata: 6.1 });
  ok(forzata.pronto === false, "nemmeno con una misura addosso, finché è prevista");
});
test("la guardia ridondante del CSV scarta comunque una prevista", () =>
  ok(sentinella.csvRefertiGenesi([{ pronto: true, prevista: true, d: 300, w: 58, ppv: 6.4, data: "2026-07-27" }])
       .trim().split("\n").length === 1, "due guardie indipendenti valgono più di una"));
test("una eseguita con misura entra, e porta la MISURA non la previsione", () => {
  const r = sentinella.refertoDaVolata({ id: "e1", data: "2026-07-17", distanzaRicettore: 320, kgMaxRitardo: 18,
                                         ppvMisurata: 5.6, ppvPrevista: 4.6 });
  ok(r.pronto === true, "questa è una misura vera");
  ok(r.ppv === 5.6, `deve valere 5,6 (misurato), non 4,6 (previsto): ${r.ppv}`);
  const csv = sentinella.csvRefertiGenesi([r]);
  ok(/5\.6/.test(csv) && !/4\.6/.test(csv), "nel file per Genesi la previsione non deve comparire");
});
test("una volata prevista non è un fatto avvenuto", () => {
  const prevista = { id: "p1", data: "2026-07-27", stato: "prevista" };
  ok(sentinella.volateDelGiorno([prevista], "2026-07-27").length === 0, "non è successo niente quel giorno");
  ok(sentinella.volateDelGiorno([{ data: "2026-07-27" }], "2026-07-27").length === 1, "una volata senza stato sì");
});
test("lo scarto fra previsto e misurato: è il confronto che dà valore al registro", () => {
  const sc = sentinella.scartoPpvVolata({ ppvPrevista: 4.6, ppvMisurata: 5.6 });
  ok(Math.abs(sc.delta - 1) < 0.005, `delta ${sc.delta} invece di 1`);
  ok(Math.abs(sc.pct - 21.7) < 0.05, `${sc.pct}% invece di 21,7`);
  ok(sc.verso === "sopra", `verso ${sc.verso}`);
  ok(sentinella.scartoPpvVolata({ ppvPrevista: 4.6 }) === null, "senza misura è null, non «scarto zero»");
});

console.log("\n— Ponte Terra → Conti: cavato contro venduto —");
// Il confronto ha senso solo se è onesto: metri cubi contro tonnellate senza
// la densità dichiarata non è una stima prudente, è un numero inventato.
const _RIL = [{ stato: "elaborato", volumeM3: 10000, data: "2026-07-10", metodo: "RTK" }];
const _pes = (netto, densita) => [{ data: "2026-07-15", prodotto: "Misto", netto, densita }];
test("i numeri tondi: 20.000 t a densità 2,5 fanno 8.000 m³, divario 2.000 (20%)", () => {
  const r = conti.riconciliazione(_RIL, _pes(20000, 2.5), "2026-07-01", "2026-07-31");
  ok(r.cav.m3 === 10000 && r.ven.t === 20000, `cavato ${r.cav.m3}, venduto ${r.ven.t} t`);
  ok(r.ven.m3 === 8000, `conversione ${r.ven.m3} invece di 8000`);
  ok(r.divario === 2000 && r.pct === 20, `divario ${r.divario} (${r.pct}%)`);
  ok(r.stato === "attenzione", `stato ${r.stato}`);
});
test("un divario piccolo è coerente, uno enorme è un errore da cercare", () => {
  ok(conti.riconciliazione(_RIL, _pes(24000, 2.5), "2026-07-01", "2026-07-31").stato === "coerente", "4% è sfrido");
  ok(conti.riconciliazione(_RIL, _pes(5000, 2.5), "2026-07-01", "2026-07-31").stato === "implausibile",
     "l'80% non è sfrido e non va chiamato «scorte»");
});
test("venduto più del cavato è un DISAVANZO, non una scorta", () => {
  const r = conti.riconciliazione(_RIL, _pes(30000, 2.5), "2026-07-01", "2026-07-31");
  ok(r.stato === "disavanzo", `stato ${r.stato}`);
  ok(r.divario < 0, "un divario negativo non può essere presentato come materiale a piazzale");
});
test("senza densità non converte e non stima: lo dichiara", () => {
  const r = conti.riconciliazione(_RIL, _pes(20000, undefined), "2026-07-01", "2026-07-31");
  ok(r.stato === "no-densita", `stato ${r.stato}`);
  ok(r.divario === null, "un divario calcolato senza densità sarebbe inventato");
  ok(r.ven.viaggiSenzaDensita === 1, "va detto quanti viaggi restano fuori dal conto");
});
test("con solo metà dei viaggi convertibili il confronto si dichiara parziale", () => {
  const r = conti.riconciliazione(_RIL, [{ data: "2026-07-15", prodotto: "A", netto: 10000, densita: 2.5 },
                                         { data: "2026-07-16", prodotto: "B", netto: 10000 }],
                                  "2026-07-01", "2026-07-31");
  ok(r.parziale === true, "un confronto parziale spacciato per completo è peggio di nessun confronto");
  ok(r.copertura === 50, `copertura ${r.copertura}%`);
});
test("la ripresa da cumulo non gonfia il cavato", () => {
  const r = conti.riconciliazione(_RIL.concat([{ stato: "elaborato", volumeM3: 5000, data: "2026-07-11", provenienza: "cumulo" }]),
                                  _pes(20000, 2.5), "2026-07-01", "2026-07-31");
  ok(r.cav.m3 === 10000, `scavo ${r.cav.m3}: il cumulo non è nuovo scavo`);
  ok(r.cav.cumuloM3 === 5000, `cumulo ${r.cav.cumuloM3}: va contato, ma a parte`);
});
test("archivi mancanti: stati che spiegano, non zeri", () => {
  ok(conti.riconciliazione([], _pes(20000, 2.5), "2026-07-01", "2026-07-31").stato === "no-cavato", "nessun rilievo");
  ok(conti.riconciliazione(_RIL, [], "2026-07-01", "2026-07-31").stato === "no-venduto", "nessun DDT");
  ok(conti.riconciliazione(undefined, _pes(20000, 2.5), "2026-07-01", "2026-07-31").stato === "no-terra", "Terra non risponde");
});
test("il valore del cavato non si inventa senza prezzo", () => {
  ok(conti.valoreCavato(10000, 12) === 120000, "10.000 m³ a 12 €/m³");
  ok(conti.valoreCavato(10000, null) === null && conti.valoreCavato(10000, 0) === null, "senza prezzo: null, non zero");
});

// ══════════════════════════════════════════════════════════════════════
// LA VIRGOLA DECIMALE — il difetto più pericoloso trovato finora
// ══════════════════════════════════════════════════════════════════════
// Misurato in Chromium: in un `input type="number"`, digitando «2,4» da
// tastiera, `.value` diventa «24» e `checkValidity()` risponde true. Il
// browser scarta la virgola e chiama valido il numero sbagliato: dieci volte
// tanto, salvato in silenzio. Su una PPV significa un falso superamento e un
// valore falso dentro la regressione della legge di sito, che decide le
// distanze di sicurezza. La correzione è `type=text inputmode=decimal` più
// una validazione nostra, e questa è la validazione.
test("numeroDaCampo: la virgola italiana è un decimale", () => {
  contiene(sentinella.numeroDaCampo("2,4"), { ok: true, valore: 2.4, vuoto: false }, "«2,4»");
  contiene(sentinella.numeroDaCampo("2.4"), { ok: true, valore: 2.4 }, "il punto vale quanto la virgola");
  ok(sentinella.numeroDaCampo("1.250,75").valore === 1250.75, "migliaia all'italiana");
  ok(sentinella.numeroDaCampo("1,250.75").valore === 1250.75, "migliaia all'inglese");
  ok(sentinella.numeroDaCampo("  2,4  ").valore === 2.4, "spazi intorno");
});
test("numeroDaCampo: vuoto non è zero, testo non è zero", () => {
  contiene(sentinella.numeroDaCampo(""), { vuoto: true, ok: false, valore: null, motivo: "vuoto" }, "campo vuoto");
  contiene(sentinella.numeroDaCampo(null), { vuoto: true, ok: false, valore: null }, "null");
  contiene(sentinella.numeroDaCampo("abc"), { ok: false, valore: null, motivo: "non-numero" }, "testo");
  ok(sentinella.numeroDaCampo("abc").valore === null, "non si salva zero al posto di un numero non capito");
});
test("numeroDaCampo: zero è una lettura valida ma non una soglia valida", () => {
  ok(sentinella.numeroDaCampo("0", { min: 0 }).ok === true, "zero passa dove il minimo è zero");
  ok(sentinella.numeroDaCampo("0", { positivo: true }).motivo === "non-positivo", "zero non passa dove serve positivo");
  ok(sentinella.numeroDaCampo("-3", { min: 0 }).motivo === "sotto-minimo", "sotto il minimo");
  ok(sentinella.numeroDaCampo("500", { max: 100 }).motivo === "sopra-massimo", "sopra il massimo");
});
test("numeroDaCampo: quattro decimali, gli stessi con cui la PPV viene salvata", () => {
  ok(sentinella.numeroDaCampo("2,44449").valore === 2.4445, "arrotondato a quattro decimali");
  ok(sentinella.numeroDaCampo("2,4", { decimali: 0 }).valore === 2, "decimali su richiesta");
});
test("la catena campo → record: 2,4 arriva sulla volata come 2,4", () => {
  const v = sentinella.numeroDaCampo("2,4").valore;
  const c = sentinella.campiPpvVolata(v, { fonte: sentinella.PPV_MANUALE });
  ok(c.ppvMisurata === 2.4, "sulla volata la PPV è 2,4, non 24 — era " + c.ppvMisurata);
});
test("conferma volata: i chili scritti con la virgola non decuplicano", () => {
  const prev = { id: "v1", stato: sentinella.VOL_PREVISTA, data: "2026-07-20",
    nFori: 18, kgTotali: 430, kgMaxRitardo: 20, distanzaRicettore: 240 };
  const r = sentinella.confermaVolataEseguita(prev,
    { kgTotali: "187,5", kgMaxRitardo: "12,5", distanzaRicettore: "312,5", data: "2026-07-25" },
    new Date("2026-07-30T12:00:00Z"));
  contiene(r.campi, { kgTotali: 187.5, kgMaxRitardo: 12.5, distanzaRicettore: 312.5 }, "le tre virgole");
  // svuotare un campo è una correzione, non una dimenticanza: era già così
  const z = sentinella.confermaVolataEseguita(prev, { kgTotali: "", data: "2026-07-25" },
    new Date("2026-07-30T12:00:00Z"));
  ok(z.campi.kgTotali === 0, "campo svuotato → zero, come nel form a mano");
  // chiave assente ≠ campo svuotato: resta il valore del progetto
  const t = sentinella.confermaVolataEseguita(prev, { data: "2026-07-25" },
    new Date("2026-07-30T12:00:00Z"));
  ok(t.campi.kgTotali === 430, "campo non toccato → resta il progetto");
});

test("numeroIt: il secondo argomento non cambia il comportamento di prima", () => {
  ok(sentinella.numeroIt(36.8) === "36,8", "sotto cento, due decimali di serie");
  ok(sentinella.numeroIt(312.5) === "313", "da cento in su arrotonda: regola di lettura dell'app, invariata");
  ok(sentinella.numeroIt(312.5, 1) === "312,5", "ma chi ha bisogno della misura la chiede — era " + sentinella.numeroIt(312.5, 1));
  ok(sentinella.numeroIt(1286) === "1.286", "migliaia col punto anche su Node");
});
test("numeroIt: un dato che manca non si scrive «0»", () => {
  // «0 µg/m³» è un fatto, e falso: dice che si è misurato zero. Il trattino
  // dice la verità. Che il vecchio «0» fosse un difetto e non una scelta lo
  // diceva l'incoerenza: undefined dava già il trattino, null no.
  ok(sentinella.numeroIt(null) === "—", "null → trattino, non «0» — era " + sentinella.numeroIt(null));
  ok(sentinella.numeroIt("") === "—", "stringa vuota → trattino — era " + sentinella.numeroIt(""));
  ok(sentinella.numeroIt(undefined) === "—", "undefined → trattino, come già faceva");
  ok(sentinella.numeroIt("abc") === "—", "testo → trattino");
  ok(sentinella.numeroIt(0) === "0" && sentinella.numeroIt("0") === "0", "ma uno zero VERO si scrive: è una misura");
});
test("la prima schermata non scrive i numeri col punto inglese", () => {
  const p = sentinella.prioritaConformita(
    [{ nome: "Polveri PM10", valore: 36.8, soglia: 40, unita: "µg/m³", nota: "media 7gg" }], [],
    new Date("2026-07-30T12:00:00Z"));
  ok(p.length === 1, "una voce di priorità");
  ok(p[0].dettaglio.startsWith("36,8 µg/m³"), "il valore con la virgola — era «" + p[0].dettaglio + "»");
  ok(!/\d\.\d/.test(p[0].dettaglio), "e nessun punto decimale da nessuna parte nella riga");
});

// ══════════════════════════════════════════════════════════════════════
// PIANO DI CARICO: le colonne si leggono per NOME, non per posizione
// ══════════════════════════════════════════════════════════════════════
// Il difetto è stato trovato per caso, sbagliando l'intestazione in una prova:
// un file con le colonne in ordine diverso si caricava COMUNQUE, senza errori,
// con la profondità nel borraggio e il ritardo nella carica progettata. La riga
// sembrava normale. Questo è il test che non lo lascia tornare.
test("piano CSV: le colonne in ordine diverso vengono lette per nome", () => {
  // stesso contenuto, ordine sconvolto e nomi con unità fra parentesi
  const csv = "foro;carica (kg);prof_m;borr_m;rit_ms;x_m;fila\n"
            + "1;40;13,20;3,00;25;0,00;A\n2;44,7;13,20;3,00;25;4,50;A";
  const out = campo.parsePianoCsv(csv);
  ok(out.length === 2, "due righe lette — erano " + out.length);
  contiene(out[0], { foro: 1, prog: 40 }, "prima riga");
  ok(out[0].prof === "13,20", "la profondità è la profondità — era " + JSON.stringify(out[0].prof));
  ok(out[0].borr === "3,00", "il borraggio è il borraggio — era " + JSON.stringify(out[0].borr));
  ok(out[0].rit === "25", "il ritardo è il ritardo — era " + JSON.stringify(out[0].rit));
  ok(out[0].x === "0,00", "la x è la x — era " + JSON.stringify(out[0].x));
  ok(out[1].prog === 44.7, "e la carica con la virgola vale 44,7 — era " + out[1].prog);
});
test("piano CSV: senza intestazione si legge per posizione, come prima", () => {
  // è il formato dei file vecchi: il contratto non cambia di una virgola
  const out = campo.parsePianoCsv("1;3.5;A;12;100;2;20\n2;4;B;12;80;2;18");
  ok(out.length === 2, "due righe");
  contiene(out[0], { foro: 1, x: "3.5", fila: "A", prof: "12", prog: 100, borr: "2", rit: "20" },
    "ordine posizionale storico");
});
test("piano CSV: l'app sa dire come ha letto il file", () => {
  const m = campo.mappaPianoCsv("foro;carica_kg;prof;borr;rit;x;fila\n1;40;12;2;20;0;A");
  ok(m.conIntestazione === true, "riconosce l'intestazione");
  ok(m.indici.prog === 1, "«carica_kg» è la carica progettata — era " + m.indici.prog);
  ok(m.indici.prof === 2 && m.indici.borr === 3, "profondità e borraggio al posto giusto");
  ok(m.mancanti.length === 0, "niente colonne mancanti — mancavano " + JSON.stringify(m.mancanti));
  const senza = campo.mappaPianoCsv("1;3.5;A;12;100;2;20");
  ok(senza.conIntestazione === false, "senza intestazione lo dichiara");
  // una colonna che non conosciamo va segnalata, non fatta sparire in silenzio
  const strana = campo.mappaPianoCsv("foro;prog;pinco;prof\n1;40;xx;12");
  ok(strana.ignorate.includes("pinco"), "la colonna sconosciuta è dichiarata — " + JSON.stringify(strana.ignorate));
  ok(strana.mancanti.includes("rit") && strana.mancanti.includes("borr"),
    "e quelle assenti pure — " + JSON.stringify(strana.mancanti));
});
test("piano CSV: senza la colonna della carica non si inventa niente", () => {
  // prog manca → nessuna riga passa il filtro, invece di righe con carica zero
  const out = campo.parsePianoCsv("foro;prof;borr\n1;12;2\n2;12;2");
  ok(out.length === 0, "nessuna riga: meglio un import vuoto che cariche a zero — erano " + out.length);
});

// Campo ha lo stesso lettore, e il caso che conta è la CARICA per foro: quel
// numero esce nel CSV del consuntivo e torna a Genesi a tarare la
// riconciliazione, quindi un fattore dieci non resta in Campo — avvelena la
// calibrazione dell'altra app.
test("Campo numeroDaCampo: la virgola sulla carica per foro", () => {
  contiene(campo.numeroDaCampo("44,7"), { ok: true, valore: 44.7, vuoto: false }, "«44,7» kg");
  ok(campo.numeroDaCampo("44.7").valore === 44.7, "il punto vale quanto la virgola");
  ok(campo.numeroDaCampo("1.250,75").valore === 1250.75, "migliaia all'italiana");
  ok(campo.numeroDaCampo("1,250.75").valore === 1250.75, "migliaia all'inglese");
  ok(campo.numeroDaCampo("44,7449").valore === 44.745, "tre decimali: al grammo si è già oltre il vero");
});
test("Campo numeroDaCampo: vuoto e incomprensibile non sono zero", () => {
  contiene(campo.numeroDaCampo(""), { vuoto: true, ok: false, valore: null, motivo: "vuoto" }, "vuoto");
  contiene(campo.numeroDaCampo("abc"), { ok: false, valore: null, motivo: "non-numero" }, "testo");
  ok(campo.numeroDaCampo(null).vuoto === true, "null è vuoto, non zero");
  ok(campo.numeroDaCampo("-3", { min: 0 }).motivo === "sotto-minimo", "chili negativi");
  ok(campo.numeroDaCampo("0", { min: 0 }).ok === true, "zero chili è una registrazione valida (foro non caricato)");
  ok(campo.numeroDaCampo("0", { positivo: true }).motivo === "non-positivo", "ma non un obiettivo di turno valido");
});
test("Campo: la catena carica → CSV → Genesi non cambia di un grammo", () => {
  // il consuntivo scrive il numero GREZZO col punto: è un dato, non testo
  const kg = campo.numeroDaCampo("44,7").valore;
  const csv = campo.pianoConsuntivoCsv([
    { n: 1, foro: 1, data: "2026-07-30", turno: "mattina", prog: 40, reale: kg, squadra: "A" },
  ]);
  ok(/;44\.7;/.test(csv), "nel CSV esce 44.7 col punto — era «" + csv.split("\n")[1] + "»");
  ok(!/;447;/.test(csv), "e NON 447: il fattore dieci non arriva a Genesi");
  ok(/;4\.7;/.test(csv), "e lo scarto col segno è +4.7");
});

// ══════════════════════════════════════════════════════════════════════
// FLOTTA: la tessera «Tagliandi 30gg» contava solo i tagliandi a data
// ══════════════════════════════════════════════════════════════════════
// Un tagliando programmato a ORE non entrava nel numero di testa, quindi la
// tessera diceva un numero più basso del vero senza dirlo. Ora il ritmo d'uso
// si MISURA dalle letture del contatore, e dove non si può misurare non si
// stima: si dichiara a parte.
const _OGGI_F = new Date("2026-07-30T12:00:00Z");
const _ind = (g) => { const d = new Date(_OGGI_F); d.setDate(d.getDate() - g); return d.toISOString().slice(0, 10); };
test("ritmo d'uso: due letture del contatore bastano, una no", () => {
  const r = flotta.ritmoOreMezzi([
    { mezzo: "E1", data: _ind(20), ore: 1000 },
    { mezzo: "E1", data: _ind(2), ore: 1080 },
  ], _OGGI_F)[0];
  ok(r.oreGiorno === 4.44, "80 ore in 18 giorni = 4,44 h/gg — era " + r.oreGiorno);
  const uno = flotta.ritmoOreMezzi([{ mezzo: "E1", data: _ind(5), ore: 1000 }], _OGGI_F)[0];
  ok(uno.oreGiorno === null, "una lettura sola non è un ritmo");
  ok(/seconda/.test(uno.perche), "e lo spiega nominando la seconda lettura: " + uno.perche);
});
test("ritmo d'uso: il confine è metà dell'orizzonte, 15 giorni su 30", () => {
  const f = (g) => flotta.ritmoOreMezzi([
    { mezzo: "E1", data: _ind(g), ore: 1000 }, { mezzo: "E1", data: _ind(0), ore: 1060 },
  ], _OGGI_F)[0];
  ok(f(15).oreGiorno !== null, "una finestra di 15 giorni si può proiettare a 30");
  ok(f(14).oreGiorno === null, "una di 14 no — proiettare 30 giorni da 14 è una moltiplicazione, non una stima");
  ok(/almeno 15/.test(f(14).perche), "e lo scrive: " + f(14).perche);
});
test("ritmo d'uso: contatore fermo, lettura vecchia, lettura nel futuro", () => {
  const fermo = flotta.ritmoOreMezzi([
    { mezzo: "E1", data: _ind(20), ore: 1000 }, { mezzo: "E1", data: _ind(0), ore: 1000 },
  ], _OGGI_F)[0];
  ok(fermo.oreGiorno === null && /non è salito/.test(fermo.perche), "contatore fermo: " + fermo.perche);
  const vecchio = flotta.ritmoOreMezzi([
    { mezzo: "E1", data: _ind(120), ore: 1000 }, { mezzo: "E1", data: _ind(90), ore: 1200 },
  ], _OGGI_F)[0];
  ok(vecchio.oreGiorno === null && /passato/.test(vecchio.perche), "storico vecchio: " + vecchio.perche);
  const futuro = flotta.ritmoOreMezzi([
    { mezzo: "E1", data: _ind(20), ore: 1000 }, { mezzo: "E1", data: _ind(2), ore: 1080 },
    { mezzo: "E1", data: _ind(-10), ore: 9999 },
  ], _OGGI_F)[0];
  ok(futuro.oreGiorno === 4.44 && futuro.letture === 2,
    "una lettura datata nel futuro non è un fatto e viene ignorata — " + futuro.oreGiorno + " su " + futuro.letture + " letture");
  ok(flotta.ritmoOreMezzi(null, _OGGI_F).length === 0 && flotta.ritmoOreMezzi([], _OGGI_F).length === 0, "niente letture, niente ritmi");
});
const _MEZZI_F = [{ nome: "Escavatore E1", ore: 1080, stato: "operativo" }];
const _LETT_F = [{ mezzo: "Escavatore E1", data: _ind(20), ore: 1000 },
  { mezzo: "Escavatore E1", data: _ind(2), ore: 1080 }];
test("tagliandi a ore: contati quando il ritmo si misura", () => {
  // 100 ore mancanti a 4,44 h/gg ⇒ 23 giorni: dentro i 30
  const t = flotta.tagliandiInScadenza([{ id: "m1", titolo: "Tagliando", mezzo: "Escavatore E1", orePreviste: 1180 }],
    _MEZZI_F, _LETT_F, _OGGI_F);
  contiene(t, { totale: 1, aOre: 1, aData: 0, nonStimabili: 0 }, "un tagliando a ore, ritmo noto");
  ok(t.voci[0].giorni === 23, "100 ore a 4,44 h/gg = 23 giorni — erano " + t.voci[0].giorni);
});
test("tagliandi a ore: senza storico NON si stima, si dichiara", () => {
  const t = flotta.tagliandiInScadenza([{ id: "m1", titolo: "Tagliando", mezzo: "Escavatore E1", orePreviste: 1180 }],
    _MEZZI_F, [], _OGGI_F);
  contiene(t, { totale: 0, aOre: 0, nonStimabili: 1 }, "niente letture: fuori dal conto, ma dichiarato");
  ok(t.daStimare.length === 1 && /Escavatore E1/.test(t.daStimare[0].mezzo + " " + (t.daStimare[0].perche || "")),
    "e il mezzo viene nominato, non nascosto");
});
test("tagliandi a ore: uno GIÀ oltre entra anche senza storico", () => {
  const t = flotta.tagliandiInScadenza([{ id: "m1", titolo: "Tagliando", mezzo: "Escavatore E1", orePreviste: 1000 }],
    _MEZZI_F, [], _OGGI_F);
  contiene(t, { totale: 1, aOre: 1, nonStimabili: 0 }, "il contatore è già a 1080 su 1000: è scaduto, non da stimare");
});
test("tagliandi a ore: uno lontano resta fuori, e non è «non stimabile»", () => {
  const t = flotta.tagliandiInScadenza([{ id: "m1", titolo: "Tagliando", mezzo: "Escavatore E1", orePreviste: 1600 }],
    _MEZZI_F, _LETT_F, _OGGI_F);
  contiene(t, { totale: 0, aOre: 0, nonStimabili: 0 }, "520 ore a 4,44 h/gg sono oltre 100 giorni: fuori, e si sa perché");
});
test("kpiFrom: il contratto a tre argomenti non è cambiato", () => {
  const k = flotta.kpiFrom(_MEZZI_F, [{ id: "m1", mezzo: "Escavatore E1", dataPrevista: _ind(-10) }], []);
  const chiavi = Object.keys(k).sort().join(",");
  ok(chiavi === "carburante,inManutenzione,operativi,tagliandi30",
    "esattamente le quattro chiavi storiche, nessuna in più — erano " + chiavi);
  ok(k.tagliandi30 === 1, "un tagliando a data fra dieci giorni");
});
test("kpiFrom: col quarto argomento il conto è onesto e si scompone", () => {
  const manut = [{ id: "m1", mezzo: "Escavatore E1", dataPrevista: _ind(-10) },
    { id: "m2", titolo: "Tagliando", mezzo: "Escavatore E1", orePreviste: 1180 }];
  const k = flotta.kpiFrom(_MEZZI_F, manut, [], { letture: _LETT_F, oggi: _OGGI_F });
  ok(k.tagliandi30 === 2, "uno a data più uno a ore — era " + k.tagliandi30);
  ok(k.tagliandi.aData + k.tagliandi.aOre === k.tagliandi.totale, "le due strade sommano al totale");
  const senza = flotta.kpiFrom(_MEZZI_F, manut, [], { letture: [], oggi: _OGGI_F });
  ok(senza.tagliandi30 === 1 && senza.tagliandi.nonStimabili === 1,
    "senza letture il numero non cresce, ma il non stimabile è dichiarato");
});

// ══════════════════════════════════════════════════════════════════════
// IL PUNTO AMBIGUO — quando NON si indovina al posto dell'utente
// ══════════════════════════════════════════════════════════════════════
// `numIt` è l'aiutante condiviso e legge i file delle MACCHINE, dove il
// decimale è il punto: «1.250» per lui è 1,25, ed è giusto per un CSV. Ma un
// italiano che digita «1.250» in un campo intende milleduecentocinquanta, e le
// due letture distano MILLE VOLTE. Su un imponibile di fattura è la differenza
// fra 1.250 € e 1,25 €.
// La regola che Flotta, Conti e Terra hanno adottato: se per quel campo una
// sola lettura è possibile (una densità di 1500 t/m³ non esiste) si risolve; se
// entrambe stanno nei limiti, l'app si FERMA e mostra le due letture invece di
// scegliere. Questi test proteggono quella scelta.
test("la convenzione vive in UN posto: le sei app leggono «1.250» allo stesso modo", async () => {
  const sh = await import("../../../shared/deepwork-id-client/dw-shell.js");
  // il lettore condiviso è la sorgente: le app ci delegano e aggiungono solo i
  // loro decimali. Se un domani una si riscrive la logica per conto suo, questo
  // test se ne accorge perché le risposte divergono.
  const base = sh.numeroScritto("1.250");
  for (const [nome, mod] of [["campo", campo], ["conti", conti], ["flotta", flotta],
                             ["sentinella", sentinella], ["terra", terra]]) {
    const r = mod.numeroDaCampo("1.250");
    ok(r.motivo === base.motivo, `${nome}: stesso motivo del condiviso («${base.motivo}») — era «${r.motivo}»`);
    contiene({ l: r.letture }, { l: base.letture }, `${nome}: stesse letture`);
  }
  // e dove una sola lettura è possibile, TUTTE risolvono allo stesso modo
  for (const [nome, mod] of [["campo", campo], ["conti", conti], ["flotta", flotta],
                             ["sentinella", sentinella], ["terra", terra]])
    ok(mod.numeroDaCampo("1.600", { min: 0.3, max: 5 }).valore === 1.6,
      `${nome}: «1.600» in un campo 0,3–5 vale 1,6 — era ${mod.numeroDaCampo("1.600", { min: 0.3, max: 5 }).valore}`);
});
test("il messaggio dell'ambiguo mostra le due letture, non dice «non valido»", async () => {
  const sh = await import("../../../shared/deepwork-id-client/dw-shell.js");
  const m = sh.messaggioNumero(sh.numeroScritto("1.250"), "i chili caricati", { unita: "kg" });
  ok(/1250 kg/.test(m) && /1,25 kg/.test(m), "entrambe le letture nel messaggio — era: " + m);
  ok(/non voglio indovinare/.test(m), "e dice che non indovina");
  // la lettura decimale di «5.875» è 5,875: con due decimali diventerebbe
  // «5,88», un terzo numero che nessuno ha scritto
  const m2 = sh.messaggioNumero(sh.numeroScritto("5.875"), "le ore", { unita: "h" });
  ok(/5,875 h/.test(m2), "tre decimali sulla lettura decimale — era: " + m2);
  // e i motivi che c'erano prima continuano a dire la cosa giusta
  ok(/negativo/.test(sh.messaggioNumero(sh.numeroScritto("-3", { min: 0 }), "i chili", { min: 0 })), "negativo");
  ok(/non è un numero/.test(sh.messaggioNumero(sh.numeroScritto("abc"), "la PPV")), "non-numero");
  ok(/Senza/.test(sh.messaggioNumero(sh.numeroScritto(""), "l'imponibile")), "vuoto");
});
test("«1.250» non si indovina: le due letture vengono dichiarate", () => {
  for (const [nome, mod] of [["flotta", flotta], ["conti", conti], ["terra", terra]]) {
    const r = mod.numeroDaCampo("1.250");
    ok(r.motivo === "ambiguo", `${nome}: motivo «ambiguo» — era «${r.motivo}»`);
    ok(r.valore === null, `${nome}: nessun valore scelto a caso — era ${r.valore}`);
    contiene({ l: r.letture }, { l: [1250, 1.25] }, `${nome}: le due letture`);
  }
});
test("ma dove una sola lettura è possibile, si risolve senza chiedere", () => {
  // una densità di 1500 t/m³ non esiste: «1.600» in quel campo è 1,6
  ok(terra.numeroDaCampo("1.600", { min: 0.3, max: 5 }).valore === 1.6,
    "densità «1.600» → 1,6 t/m³");
  // 32.500 tonnellate su una pesata non esistono: è 32,5
  ok(conti.numeroDaCampo("32.500", { max: 500 }).valore === 32.5, "lordo «32.500» → 32,5 t");
  // due punti = migliaia, nessun dubbio possibile
  ok(terra.numeroDaCampo("1.200.000").valore === 1200000, "«1.200.000» m³ concessi");
  ok(flotta.numeroDaCampo("1.234.567").valore === 1234567, "«1.234.567»");
  // e con le migliaia italiane più i decimali non c'è ambiguità
  ok(conti.numeroDaCampo("1.250,75").valore === 1250.75, "«1.250,75» → 1250,75");
});
test("vuoto e incomprensibile non sono zero, in nessuna delle tre app", () => {
  for (const [nome, mod] of [["flotta", flotta], ["conti", conti], ["terra", terra]]) {
    contiene(mod.numeroDaCampo(""), { vuoto: true, ok: false, valore: null }, `${nome}: vuoto`);
    ok(mod.numeroDaCampo("abc").valore === null, `${nome}: testo non è zero`);
    ok(mod.numeroDaCampo("-5", { min: 0 }).motivo === "sotto-minimo", `${nome}: sotto il minimo`);
  }
  // «2,4,5» non è 245: due virgole non sono un numero, sono un errore di battitura
  ok(flotta.numeroDaCampo("2,4,5").motivo === "non-numero", "«2,4,5» rifiutato");
  ok(flotta.numeroDaCampo("1e3").motivo === "non-numero", "la notazione esponenziale non è un numero da cava");
});
test("quello che arriva dal foglio di calcolo si legge comunque", () => {
  ok(flotta.numeroDaCampo("€ 12,50").valore === 12.5, "il simbolo dell'euro non è un errore");
  ok(flotta.numeroDaCampo("1 250,75").valore === 1250.75, "lo spazio come separatore di migliaia");
  ok(flotta.numeroDaCampo(",75").valore === 0.75, "«,75» → 0,75");
  ok(conti.numeroDaCampo("€ 1.250,75").valore === 1250.75, "euro più migliaia italiane");
});
test("Flotta: interoDaCampo non accetta un decimale travestito", () =>
  ok(flotta.interoDaCampo("2,4").motivo === "non-intero", "«2,4» giorni non è un numero di giorni"));

// ── le catene: dal campo al numero che l'utente legge ──────────────────
test("Conti: «1.250,75» imponibile → IVA 275,17 → totale 1.525,92", () => {
  contiene(conti.totaliDaRighe([{ imponibile: conti.numeroDaCampo("1.250,75").valore, aliquota: 22 }]),
    { imponibile: 1250.75, ivaImporto: 275.17, totale: 1525.92 }, "la fattura");
});
test("Conti: la pesata scritta con la virgola dà il netto giusto", () =>
  ok(conti.nettoPesata(conti.numeroDaCampo("42,6").valore, conti.numeroDaCampo("14,2").valore) === 28.4,
    "42,6 − 14,2 = 28,4 t"));
test("Flotta: le ore e la tariffa con la virgola fanno il costo giusto", () => {
  const ore = flotta.numeroDaCampo("2,5").valore, tar = flotta.numeroDaCampo("32,50").valore;
  ok(ore === 2.5 && tar === 32.5, "letti 2,5 h e 32,50 €");
  const c = flotta.costoOrdine({ manodopera: [{ chi: "Rossi", ore, tariffa: tar }] });
  ok(c.manodopera.costo === 81.25, "2,5 × 32,50 = 81,25 € — era " + c.manodopera.costo);
});
test("Flotta: il mezzo decimo del contatore non si perde", () => {
  // la firma è (manutenzione, oreAttuali, dataChiusura): il piano dice OGNI
  // quante ore, il contatore dice dove siamo. Al primo giro avevo passato il
  // mezzo al posto del piano e la funzione, giustamente, non ha inventato nulla.
  ok(flotta.prossimoTagliando({ titolo: "Tagliando", mezzo: "E1", ogniOre: 250 }, 5875.5).orePreviste === 6125.5,
    "contatore 5875,5 + ogni 250 h = 6125,5 h — era "
    + JSON.stringify(flotta.prossimoTagliando({ titolo: "T", mezzo: "E1", ogniOre: 250 }, 5875.5)));
  /* dal 02/08 l'etichetta raggruppa le migliaia — «1.234,5» — perché il
     raggruppamento nei moduli è scritto esplicito e non lasciato al motore:
     senza, Node scriveva «1234,5» e il browser dell'utente «1.234,5».
     docs/MIGLIAIA_NODE_CONTRO_CHROMIUM.md */
  ok(flotta.urgenzaOre(6500, 5265.5).label === "tra 1.234,5 h",
    "l'etichetta scrive 1.234,5 e non 1234.5 — era «" + flotta.urgenzaOre(6500, 5265.5).label + "»");
  ok(flotta.urgenzaOre(6500, 6520).label === "SCADUTA (+20 h)", "l'etichetta storica non cambia");
});
test("Terra: il GSD si legge sia numero sia testo, e si scrive con la virgola", () => {
  ok(terra.qualitaRilievo({ metodo: "RTK", gsd: 2.5 }) === "RTK · GSD 2,5 cm", "gsd numero");
  ok(terra.qualitaRilievo({ metodo: "RTK", gsd: "2.5" }) === "RTK · GSD 2,5 cm", "gsd dal CSV col punto");
  ok(terra.qualitaRilievo({ metodo: "RTK", gsd: "2" }) === "RTK · GSD 2 cm", "gsd intero invariato");
  // 2,5 cm sta SOPRA la soglia dei 2 cm, quindi «indicativo» è la risposta giusta
  ok(terra.classeAccuratezza({ metodo: "RTK+GCP", gsd: 2.5 }).classe === "indicativo", "2,5 cm → indicativo");
  ok(terra.classeAccuratezza({ metodo: "RTK+GCP", gsd: 1.8 }).classe === "survey-grade", "1,8 cm → survey-grade");
});
test("il ponte Terra ↔ Conti non cambia di un decimale", () => {
  const rilievi = [{ data: "2026-03-10", stato: "elaborato", volumeM3: 4200.5, provenienza: "scavo" }];
  ok(conti.cavatoPeriodo(rilievi, "2026-01-01", "2026-12-31").m3 === 4200.5,
    "un volume con la virgola arriva intero in cavatoPeriodo");
  const senza = conti.vendutoPeriodo(
    [{ data: "2026-03-11", netto: 28.4, quantita: 28.4, unitaVendita: "t", densita: null, prezzoUnitario: 8.5 }],
    "2026-01-01", "2026-12-31");
  contiene(senza, { tSenzaDensita: 28.4, m3: 0, copertura: 0 },
    "e senza densità NON si converte: le tonnellate restano dichiarate a parte");
});

/* ══════════════════════════════════════════════════════════════════════
   PONTE P2 — CAMPO → TERRA: il dichiarato dei turni, e le tre cose che
   non deve poter diventare.
   ══════════════════════════════════════════════════════════════════════ */
test("P2: le tre unità di Campo non si trattano allo stesso modo", () => {
  const rapp = [
    { data: "2026-03-02", turno: "Mattina", prodQta: 1300, prodUnita: "t" },
    { data: "2026-03-03", turno: "Mattina", prodQta: 500,  prodUnita: "m³" },
    { data: "2026-03-04", turno: "Notte",   prodQta: 12,   prodUnita: "viaggi" },
  ];
  const d = terra.produzioneDichiarata(rapp, "2026-03-01", "2026-03-31", 2.6);
  /* 1300 t / 2,6 = 500 m³, più i 500 m³ dichiarati direttamente = 1000 */
  contiene(d, { m3: 1000, m3Diretti: 500, m3DaTonnellate: 500, t: 1300, viaggi: 12, turni: 3 },
    "tonnellate convertite con la densità, metri cubi sommati, viaggi contati a parte");
  ok(d.parziale === true, "con dei viaggi dentro il totale in m³ è per difetto, e lo dichiara");
  /* i VIAGGI non si convertono MAI: servirebbe la portata del mezzo, che
     cambia da camion a camion. Nessuna densità li fa entrare nei m³. */
  const soloViaggi = terra.produzioneDichiarata([rapp[2]], "2026-03-01", "2026-03-31", 2.6);
  contiene(soloViaggi, { m3: 0, viaggi: 12, turni: 1 }, "dodici viaggi non diventano metri cubi");
});
test("P2: senza densità le tonnellate NON si convertono e non si stimano", () => {
  const rapp = [{ data: "2026-03-02", prodQta: 1300, prodUnita: "t" }];
  const d = terra.produzioneDichiarata(rapp, "2026-03-01", "2026-03-31", null);
  contiene(d, { m3: 0, t: 1300, tSenzaDensita: 1300, densita: null, parziale: true },
    "le tonnellate restano dichiarate a parte, come nel ponte Terra ↔ Conti");
  /* e una densità impossibile non vale come densità */
  for (const cattiva of [0, -2.6, NaN, "due virgola sei", null, undefined]) {
    const x = terra.produzioneDichiarata(rapp, "2026-03-01", "2026-03-31", cattiva);
    ok(x.m3 === 0 && x.tSenzaDensita === 1300, `densità ${JSON.stringify(cattiva)}: non si converte`);
  }
});
test("P2: «non lo so» e «zero» restano due risposte diverse", () => {
  ok(terra.produzioneDichiarata(null, "2026-03-01", "2026-03-31", 2.6) === null,
    "rapportini assenti → null, non un totale di zero");
  ok(terra.misuratoPeriodo(null, "", "") === null, "rilievi assenti → null");
  const vuoto = terra.produzioneDichiarata([], "2026-03-01", "2026-03-31", 2.6);
  contiene(vuoto, { m3: 0, turni: 0 }, "nessun rapportino nel periodo → zero turni, non null");
  eq(terra.riconciliazioneTurni([], null, "2026-03-01", "2026-03-31", 2.6).stato, "no-campo",
    "Campo non raggiungibile: si dice, non si confronta");
  eq(terra.riconciliazioneTurni(null, [{ data: "2026-03-02", prodQta: 900, prodUnita: "m³" }],
    "2026-03-01", "2026-03-31", 2.6).stato, "no-misura",
    "se manca Terra il dichiarato da solo non è un confronto: si dice quale metà manca");
});
test("P2: il misurato conta solo i rilievi elaborati, e lo scavo separato dal cumulo", () => {
  const rilievi = [
    { data: "2026-03-05", stato: "elaborato",   volumeM3: 900, provenienza: "scavo" },
    { data: "2026-03-06", stato: "pianificato", volumeM3: 500, provenienza: "scavo" },
    { data: "2026-03-07", stato: "elaborato",   volumeM3: 200, provenienza: "cumulo" },
    { data: "2026-02-01", stato: "elaborato",   volumeM3: 700, provenienza: "scavo" },
  ];
  const m = terra.misuratoPeriodo(rilievi, "2026-03-01", "2026-03-31");
  contiene(m, { m3: 900, rilievi: 1, m3Cumulo: 200, rilieviCumulo: 1, pianificati: 1 },
    "un pianificato è un'intenzione, un cumulo non è roccia uscita dal fronte, febbraio è fuori periodo");
});
test("P2: il confronto dice sempre COME va letto il numero", () => {
  const mis = [{ data: "2026-03-05", stato: "elaborato", volumeM3: 1000, provenienza: "scavo" }];
  const dichiara = (m3) => [{ data: "2026-03-10", prodQta: m3, prodUnita: "m³" }];
  const stato = (m3) => terra.riconciliazioneTurni(mis, dichiara(m3), "2026-03-01", "2026-03-31", 2.6).stato;
  eq(stato(950), "coerente", "5% sotto: dentro la tolleranza di una stima a occhio");
  eq(stato(800), "attenzione", "20% sotto: conviene andare a guardare");
  eq(stato(500), "implausibile", "metà: non è imprecisione di stima");
  eq(stato(1200), "sopra-misura", "dichiarato più del misurato: o le stime sono gonfie o il rilievo non copre tutto");
  eq(terra.riconciliazioneTurni([], dichiara(900), "2026-03-01", "2026-03-31", 2.6).stato, "no-misura",
    "senza rilievo elaborato non c'è niente contro cui confrontare");
  eq(terra.riconciliazioneTurni(mis, [], "2026-03-01", "2026-03-31", 2.6).stato, "no-dichiarato",
    "nessun turno ha dichiarato: si dice");
  eq(terra.riconciliazioneTurni(mis, [{ data: "2026-03-10", prodQta: 30, prodUnita: "viaggi" }],
    "2026-03-01", "2026-03-31", 2.6).stato, "no-densita",
    "solo viaggi: niente di convertibile, quindi non si confronta");
  /* il SEGNO dello scostamento non si arrotonda via: senza verso non si sa da
     che parte cercare. È la stessa scelta del ponte Campo → Genesi. */
  const sopra = terra.riconciliazioneTurni(mis, dichiara(1200), "2026-03-01", "2026-03-31", 2.6);
  ok(sopra.scostamento === -200 && sopra.pct === -20, `il segno resta: ${sopra.scostamento} / ${sopra.pct}%`);
});
test("P2: la banda di coerenza vale nei DUE sensi", () => {
  /* Trovato guardando lo stato renderizzato: qualunque eccesso, anche dell'1%,
     diventava un allarme rosso. Ma se una stima a occhio può stare quindici punti
     SOTTO la misura senza che sia un problema, può stare quindici punti SOPRA per
     la stessa ragione — è la stessa imprecisione nell'altro verso. Un allarme che
     scatta su una differenza normale insegna a non guardarlo più, che è
     esattamente ciò che queste soglie dovevano evitare. */
  const mis = [{ data: "2026-03-05", stato: "elaborato", volumeM3: 1000, provenienza: "scavo" }];
  const r = (m3) => terra.riconciliazioneTurni(mis, [{ data: "2026-03-10", prodQta: m3, prodUnita: "m³" }],
    "2026-03-01", "2026-03-31", 2.6);
  for (const [m3, stato, verso] of [
    [1000, "coerente", "sotto"],
    [1050, "coerente", "sopra"],       // 5% in più: imprecisione normale
    [1140, "coerente", "sopra"],       // 14%: ancora dentro la banda
    [1160, "sopra-misura", "sopra"],   // 16%: oltre, e il verso cambia il significato
    [1500, "sopra-misura", "sopra"],
    [950,  "coerente", "sotto"],
    [800,  "attenzione", "sotto"],
    [500,  "implausibile", "sotto"],
  ]) {
    const x = r(m3);
    eq([x.stato, x.verso], [stato, verso], `${m3} m³ dichiarati contro 1000 misurati`);
  }
  /* `verso` è una parola perché il segno da solo si legge male: «−16%» non dice
     se è il dichiarato o il misurato a essere più alto. */
  ok(r(1160).scostamento < 0 && r(1160).verso === "sopra", "il segno e la parola concordano");
  ok(r(800).scostamento > 0 && r(800).verso === "sotto", "e anche nell'altro verso");
});
test("P2: senza rilievi il dichiarato NON si perde", () => {
  /* Guardato a schermo: la sezione diventava due note grigie che dicono «non
     posso», mentre in archivio c'erano quindici rapportini con la produzione.
     È il caso in cui quel dato vale PIÙ di tutti — una cava che non ha ancora
     fatto volare il drone non ha nessun'altra fonte. */
  const rapp = [
    { data: "2026-03-02", prodQta: 1900, prodUnita: "t" },
    { data: "2026-03-05", prodQta: 1900, prodUnita: "t" },
  ];
  ok(terra.avanzamentoDaUltimoRilievo([], rapp, 1.9, new Date("2026-03-10T09:00:00Z")) === null,
    "senza rilievi non c'è un «da quando»");
  /* ...ma la produzione dichiarata del periodo si legge comunque, ed è quello
     che la pagina mostra al posto della nota grigia */
  const d = terra.produzioneDichiarata(rapp, "2026-02-09", "2026-03-10", 1.9);
  ok(d && d.turni === 2 && d.m3 === 2000, `due turni, 2000 m³ (ottenuti ${d && d.m3})`);
});
test("P2: le soglie NON sono quelle del ponte Terra ↔ Conti, ed è voluto", () => {
  /* là si confrontano due misure (un rilievo e una pesa), qui una misura con una
     stima a occhio di fine turno: pretendere la stessa precisione farebbe
     suonare l'allarme su una differenza normale. */
  ok(terra.SOGLIA_TURNI.coerente > conti.SOGLIA_DIVARIO.coerente,
    `la banda del dichiarato (${terra.SOGLIA_TURNI.coerente}%) deve essere più larga di quella fra due misure (${conti.SOGLIA_DIVARIO.coerente}%)`);
  ok(terra.SOGLIA_TURNI.attenzione > conti.SOGLIA_DIVARIO.attenzione,
    "e lo stesso vale per la soglia dell'implausibile");
  /* la controprova: un 12% qui è coerente, là sarebbe già attenzione */
  const mis = [{ data: "2026-03-05", stato: "elaborato", volumeM3: 1000, provenienza: "scavo" }];
  eq(terra.riconciliazioneTurni(mis, [{ data: "2026-03-10", prodQta: 880, prodUnita: "m³" }],
    "2026-03-01", "2026-03-31", 2.6).stato, "coerente", "12% di scostamento su una stima è normale");
});
test("P2: la stima corrente riempie SOLO il buco fra due voli del drone", () => {
  const rilievi = [{ data: "2026-03-10", stato: "elaborato", volumeM3: 5000, provenienza: "scavo" }];
  const rapp = [
    { data: "2026-03-09", prodQta: 400, prodUnita: "m³" },   // PRIMA del rilievo: già misurato
    { data: "2026-03-11", prodQta: 300, prodUnita: "m³" },
    { data: "2026-03-12", prodQta: 250, prodUnita: "m³" },
  ];
  const a = terra.avanzamentoDaUltimoRilievo(rilievi, rapp, 2.6, new Date("2026-03-13T09:00:00Z"));
  contiene(a, { dal: "2026-03-11", al: "2026-03-13", giorni: 3, dallUltimoRilievo: "2026-03-10" },
    "si parte dal giorno DOPO l'ultimo rilievo");
  ok(a.dich.m3 === 550, `solo i turni successivi al rilievo: 550, non 950 (ottenuti ${a.dich.m3})`);
  /* senza un rilievo da cui partire non è un avanzamento, è solo una somma */
  ok(terra.avanzamentoDaUltimoRilievo([], rapp, 2.6, new Date("2026-03-13T09:00:00Z")) === null,
    "nessun rilievo elaborato → null");
  ok(terra.avanzamentoDaUltimoRilievo([{ data: "2026-03-13", stato: "elaborato", volumeM3: 10 }],
    rapp, 2.6, new Date("2026-03-13T09:00:00Z")) === null,
    "rilievo di oggi: nessun buco da riempire");
});
test("P2: la tendina del periodo offre i confini dei voli, non date libere", () => {
  /* Una data libera permetterebbe di chiedere un periodo che non corrisponde a
     nessuna misura, e il numero che ne esce sarebbe uno scostamento nato solo
     dalle date. Meglio togliere la possibilità di fare la domanda sbagliata che
     spiegare dopo perché la risposta non vale. */
  const R = [
    { data: "2025-11-20", stato: "elaborato", volumeM3: 22000, provenienza: "scavo" },
    { data: "2026-05-15", stato: "elaborato", volumeM3: 20100, provenienza: "scavo" },
    { data: "2026-06-16", stato: "elaborato", volumeM3: 21300, provenienza: "scavo" },
    { data: "2026-06-25", stato: "elaborato", volumeM3: 5200,  provenienza: "cumulo" },
    { data: "2026-08-01", stato: "pianificato", volumeM3: null },
  ];
  const l = terra.intervalliFraRilievi(R);
  eq(l.length, 2, "tre voli di scavo fanno due intervalli");
  contiene(l[0], { dal: "2026-05-16", al: "2026-06-16", rilievoPrecedente: "2026-05-15" },
    "il più recente per primo, e si parte dal giorno DOPO il volo precedente");
  contiene(l[1], { dal: "2025-11-21", al: "2026-05-15" }, "poi quello prima");
  ok(!l.some((i) => i.al === "2026-06-25"), "una ripresa da cumulo non è un confine");
  ok(!l.some((i) => i.al === "2026-08-01"), "e un rilievo pianificato nemmeno");
  eq(terra.intervalliFraRilievi([R[0]]), [], "con un volo solo non c'è nessun intervallo");
  eq(terra.intervalliFraRilievi(null), [], "rilievi assenti → lista vuota, non un errore");
  /* il periodo naturale è il primo della lista: una sola verità, due nomi */
  contiene(terra.periodoFraUltimiRilievi(R), l[0], "il periodo naturale è l'intervallo più recente");
});
test("P2: il periodo del confronto è fra due voli, non un mese di calendario", () => {
  /* il volume di un rilievo è l'accumulo dall'ultimo volo: confrontarlo con un
     mese qualsiasi legge uno scostamento che nasce solo dalle date. */
  const R = [
    { data: "2026-07-01", stato: "elaborato", volumeM3: 18600, provenienza: "scavo" },
    { data: "2026-07-15", stato: "elaborato", volumeM3: 19400, provenienza: "scavo" },
    { data: "2026-08-01", stato: "pianificato", volumeM3: null },
  ];
  contiene(terra.periodoFraUltimiRilievi(R),
    { dal: "2026-07-02", al: "2026-07-15", rilievoPrecedente: "2026-07-01" },
    "si parte dal giorno DOPO il penultimo: quel giorno è già dentro la misura precedente");
  ok(terra.periodoFraUltimiRilievi([R[1]]) === null, "con un rilievo solo non c'è intervallo");
  ok(terra.periodoFraUltimiRilievi(null) === null, "rilievi assenti → null");
  /* un CUMULO non è un volo di scavo e non fa periodo */
  ok(terra.periodoFraUltimiRilievi([R[1], { data: "2026-07-20", stato: "elaborato", volumeM3: 500, provenienza: "cumulo" }]) === null,
    "una ripresa da cumulo non conta come rilievo di scavo");
  /* due rilievi nello STESSO giorno non fanno un intervallo */
  ok(terra.periodoFraUltimiRilievi([
    { data: "2026-07-15", stato: "elaborato", volumeM3: 100, provenienza: "scavo" },
    { data: "2026-07-15", stato: "elaborato", volumeM3: 200, provenienza: "scavo" }]) === null,
    "due rilievi dello stesso giorno: nessun intervallo fra cui confrontare");
});
test("P2: la dimostrazione di Terra è coerente coi suoi rilievi", () => {
  /* Se i numeri d'esempio non si parlano, la prima cosa che il fondatore vede è
     un allarme rosso che non significa niente. La densità è quella del
     materiale scritto nell'autorizzazione (sabbia e ghiaia, 1,9 t/m³). */
  const per = terra.periodoFraUltimiRilievi(terra.DEMO.rilievi);
  ok(per != null, "la dimostrazione ha almeno due rilievi di scavo");
  const dens = terra.presetDensita("sabbia-ghiaia").densita;
  const r = terra.riconciliazioneTurni(terra.DEMO.rilievi, terra.DEMO.rapportiniCampo, per.dal, per.al, dens);
  eq(r.stato, "coerente", "coi numeri d'esempio i due mondi si parlano");
  ok(Math.abs(r.pct) < 5, `e lo scostamento è piccolo (${r.pct}%)`);
  /* e la stima corrente ha qualcosa da dire, viaggi compresi */
  const a = terra.avanzamentoDaUltimoRilievo(terra.DEMO.rilievi, terra.DEMO.rapportiniCampo, dens,
    new Date("2026-07-30T09:00:00Z"));
  ok(a && a.dich.turni > 0 && a.dich.viaggi > 0,
    "la dimostrazione mostra sia i metri cubi stimati sia i viaggi che non si convertono");
});
test("P2 · LA GUARDIA: il dichiarato non può diventare un rilievo", () => {
  /* È il difetto peggiore che questo ponte poteva introdurre, per tre ragioni:
     i rilievi consumano il volume CONCESSO, finiscono nel riepilogo annuale che
     va agli ENTI, e portano metodo e GSD che li rendono difendibili in audit.
     Un conteggio di viaggi dichiarato da un preposto non ha niente di tutto
     questo. Qui si verifica che nessuna funzione del ponte produca un record
     che i lettori dei rilievi possano prendere per una misura. */
  const rapp = [{ data: "2026-03-11", prodQta: 900, prodUnita: "m³" }];
  const rilievi = [{ id: "r1", fronteId: "f1", data: "2026-03-05", stato: "elaborato", volumeM3: 1000, provenienza: "scavo" }];
  const esiti = [
    terra.produzioneDichiarata(rapp, "2026-03-01", "2026-03-31", 2.6),
    terra.riconciliazioneTurni(rilievi, rapp, "2026-03-01", "2026-03-31", 2.6),
    terra.avanzamentoDaUltimoRilievo(rilievi, rapp, 2.6, new Date("2026-03-13T09:00:00Z")),
  ];
  const testo = JSON.stringify(esiti);
  ok(!/"stato":"elaborato"/.test(testo.replace(/"stato":"(no-|coerente|attenzione|implausibile|sopra-misura)[^"]*"/g, "")),
    "nessun esito del ponte porta lo stato che rende un rilievo una misura");
  ok(!/"volumeM3"/.test(testo), "e nessuno porta il campo volumeM3: non somiglia a un rilievo");
  /* e la prova che conta: i lettori dei rilievi NON vedono il dichiarato */
  const prima = terra.volumeFronte(rilievi, "f1");
  const conPonte = terra.volumeFronte(rilievi.concat([]), "f1");
  ok(prima === 1000 && conPonte === 1000, "il volume del fronte resta quello misurato");
  const est = terra.estrattoComplessivo(rilievi, { volumeAutorizzatoM3: 100000 });
  ok(est.rilevato === 1000 && est.totale === 1000,
    `il volume concesso lo consuma solo il misurato (rilevato ${est.rilevato}, totale ${est.totale})`);
  /* e il riepilogo che va agli ENTI non conosce il dichiarato: si conta quante
     volte compare nel documento, e deve essere zero. */
  const rie = terra.riepilogoAnnuale(rilievi, 2026, { volumeAutorizzatoM3: 100000 }, new Date("2026-12-31T00:00:00Z"));
  ok(!JSON.stringify(rie).includes("dichiarat"),
    "il riepilogo annuale per gli enti non porta nessun numero dichiarato");
});
/* ══════════════════════════════════════════════════════════════════════
   PONTE P3 · CAMPO ↔ SCUDO — «chi è in turno è in regola?»
   ══════════════════════════════════════════════════════════════════════
   La regola più delicata scritta finora, perché una risposta sbagliata qui è
   peggio di nessuna risposta: chi non sa, controlla; chi crede di sapere, no. */
test("P3 · NON si accoppia per nome, mai", () => {
  /* la prova che conta più di tutte. Nei dati di esempio Campo aveva un «Marco
     Rossi» e Scudo un «Mario Rossi», Campo un'«Anna Conti» e Scudo un'«Anna Neri»
     e una «Sara Conti»: un accoppiamento per nome — anche «intelligente» —
     avrebbe dichiarato in regola una persona guardando i documenti di un'altra. */
  const lavoratori = [{ id: "d1", nome: "Mario Rossi", attivo: true }];
  const scadenze = [{ id: "s1", lavoratoreId: "d1", tipo: "Visita medica", dataScadenza: "2020-01-01" }];
  const omonimo = { id: "o1", nome: "Mario Rossi" };          // stesso nome, nessun id
  const r = ponti.idoneitaOperatore(omonimo, lavoratori, scadenze, new Date("2026-07-30"));
  ok(r.stato === "non-collegato",
    `stesso nome identico ma nessun collegamento: la risposta è «non lo so», non «scaduta» (${r.stato})`);
  ok(r.lavoratore === null, "e non si restituisce il lavoratore trovato per nome");
  /* e il caso opposto: nomi diversi ma id giusto → si guarda l'id */
  const r2 = ponti.idoneitaOperatore({ id: "o1", nome: "Tutt'altro Nome", lavoratoreId: "d1" },
    lavoratori, scadenze, new Date("2026-07-30"));
  ok(r2.stato === "scaduta", "col collegamento giusto si legge il documento, qualunque nome ci sia scritto");
});
test("P3 · i cinque stati, e nessuno che finge di sapere", () => {
  const oggi = new Date("2026-07-30T00:00:00");
  const lav = [{ id: "d1", nome: "A" }, { id: "d2", nome: "B" }, { id: "d3", nome: "C" }];
  const sca = [
    { lavoratoreId: "d1", tipo: "Visita medica", dataScadenza: "2026-07-02" },  // scaduta
    { lavoratoreId: "d1", tipo: "Patente", dataScadenza: "2028-05-30" },
    { lavoratoreId: "d2", tipo: "Formazione", dataScadenza: "2026-08-09" },     // entro 30 giorni
    { lavoratoreId: "d3", tipo: "Patente", dataScadenza: "2027-01-01" },        // lontana
  ];
  const st = (o) => ponti.idoneitaOperatore(o, lav, sca, oggi).stato;
  ok(st({ lavoratoreId: "d1" }) === "scaduta", "un documento scaduto vince su quelli validi");
  ok(st({ lavoratoreId: "d2" }) === "in-scadenza", "entro trenta giorni: in scadenza");
  ok(st({ lavoratoreId: "d3" }) === "regolare", "tutto valido: regolare");
  ok(st({ lavoratoreId: "d9" }) === "collegamento-rotto", "id che non esiste più in Scudo");
  ok(st({}) === "non-collegato", "senza id non si indovina");
  /* collegato ma senza nessun documento registrato: NON è «regolare», è un'altra
     cosa — in Scudo non c'è niente da controllare, e dirlo è diverso dal dire
     che è tutto a posto */
  const solo = ponti.idoneitaOperatore({ lavoratoreId: "d1" }, lav, [], oggi);
  ok(solo.stato === "senza-scadenze", "collegato ma senza documenti: si dice, non si assume");
});
test("P3 · il riepilogo del turno non trasforma un «non lo so» in un «sì»", () => {
  const oggi = new Date("2026-07-30T00:00:00");
  const lav = [{ id: "d1", nome: "A" }];
  const sca = [{ lavoratoreId: "d1", tipo: "Patente", dataScadenza: "2028-01-01" }];
  const q = ponti.idoneitaDiTurno(
    [{ id: "o1", lavoratoreId: "d1" }, { id: "o2" }], lav, sca, oggi);
  ok(q.regolari === 1 && q.nonCollegati === 1, "i due conti restano separati");
  /* e i DUE modi di non sapere restano distinti: «non collegato» è un lavoro non
     fatto, «collegamento rotto» è un dato da riparare. Il riepilogo che li chiamava
     entrambi «non collegate» diceva una cosa falsa della seconda. */
  ok(q.senzaCollegamento === 1 && q.collegamentiRotti === 0, "qui manca il collegamento, non è rotto");
  const rotto = ponti.idoneitaDiTurno([{ id: "o1", lavoratoreId: "d9" }], lav, sca, oggi);
  ok(rotto.collegamentiRotti === 1 && rotto.senzaCollegamento === 0,
    "un id che non esiste più è un collegamento ROTTO, non un collegamento assente");
  ok(rotto.nonCollegati === 1, "e la somma dei due resta il conto complessivo dei «non lo so»");
  ok(q.tuttoInRegola === false,
    "con una persona di cui non si sa niente, «tutto in regola» è FALSO");
  const tutti = ponti.idoneitaDiTurno([{ id: "o1", lavoratoreId: "d1" }], lav, sca, oggi);
  ok(tutti.tuttoInRegola === true, "se si sa tutto e va tutto bene, allora sì");
  ok(ponti.idoneitaDiTurno([], lav, sca, oggi).tuttoInRegola === false,
    "nessuno in elenco non è «tutto in regola»: è niente da dire");
  eq(ponti.idoneitaDiTurno(null, null, null, oggi).righe, [], "dati assenti: nessun errore");
});
test("P3 · UNA SOLA implementazione della soglia: Scudo ri-esporta, non riscrive", () => {
  /* la regola di ieri, applicata: `terra.X === ponti.X`. Qui vale per Scudo e per
     Campo, e si pretende l'IDENTITÀ, non il comportamento — due copie uguali oggi
     divergono domani senza che nessuno lo veda. */
  ok(scudo.statoScadenza === ponti.statoScadenzaHSE,
    "scudo.statoScadenza è la funzione di shared/, non una copia");
  ok(campo.idoneitaDiTurno === ponti.idoneitaDiTurno, "e Campo ri-esporta la stessa");
  ok(campo.idoneitaOperatore === ponti.idoneitaOperatore, "idem per il singolo operatore");
  ok(campo.statoScadenzaHSE === ponti.statoScadenzaHSE, "idem per la soglia");
});
test("P3 · le due dimostrazioni non si smentiscono a vicenda", () => {
  /* Campo porta una copia dei lavoratori e delle scadenze di Scudo per far vedere
     il ponte anche senza backend. Se quelle copie divergessero, la dimostrazione
     dell'ecosistema direbbe due cose diverse sulla stessa persona — ed è proprio
     ciò che il ponte serve a evitare. */
  const perId = new Map(scudo.DEMO.lavoratori.map(l => [l.id, l]));
  for (const l of campo.DEMO.lavoratoriScudo) {
    const vero = perId.get(l.id);
    ok(vero, `il lavoratore ${l.id} della copia di Campo esiste in Scudo`);
    if (vero) ok(vero.nome === l.nome, `e si chiama allo stesso modo (${l.nome} / ${vero && vero.nome})`);
  }
  /* la chiave (lavoratore + tipo) NON è univoca: in Scudo d3 ha due «Formazione»,
     e la prima versione di questa prova le confondeva accusando i dati di essere
     divergenti quando l'errore era suo. Si verifica quindi l'APPARTENENZA: ogni
     riga della copia di Campo deve esistere in Scudo con la stessa data. */
  const scaScudo = new Set(scudo.DEMO.scadenze.map(s => s.lavoratoreId + "|" + s.tipo + "|" + s.dataScadenza));
  for (const s of campo.DEMO.scadenzeScudo) {
    ok(scaScudo.has(s.lavoratoreId + "|" + s.tipo + "|" + s.dataScadenza),
      `la scadenza «${s.tipo} ${s.dataScadenza}» di ${s.lavoratoreId} esiste identica in Scudo`);
  }
  /* e gli operatori di Campo puntano a lavoratori che esistono */
  for (const o of campo.DEMO.operatori) {
    if (!o.lavoratoreId) continue;
    ok(perId.has(o.lavoratoreId), `l'operatore ${o.nome} punta a un lavoratore vero (${o.lavoratoreId})`);
    ok(perId.get(o.lavoratoreId).nome === o.nome,
      `e allo stesso nome: ${o.nome} / ${perId.get(o.lavoratoreId).nome}`);
  }
});
/* ── P3, l'altra metà: dal lato di SCUDO ────────────────────────────────── */
test("P3 · «sta lavorando adesso» = in forza IN UNA SQUADRA OPERATIVA", () => {
  const squadre = [
    { nome: "Squadra A — Perforazione", stato: "operativa" },
    { nome: "Squadra C — Impianto", stato: "ferma" },
  ];
  const oper = [
    { id: "o1", nome: "A", squadra: "Squadra A", stato: "in-forza" },
    { id: "o2", nome: "B", squadra: "Squadra A", stato: "non-disponibile" },
    { id: "o3", nome: "C", squadra: "Squadra C", stato: "in-forza" },
    { id: "o4", nome: "D", squadra: "Squadra Z", stato: "in-forza" },
  ];
  eq(ponti.inTurnoOggi(oper, squadre).map(o => o.id), ["o1"],
    "in forza in una squadra operativa: solo lui");
  /* IL NOME DELLA SQUADRA PORTA LA SPECIALITÀ dopo un trattino («Squadra A —
     Perforazione») mentre l'operatore ne tiene solo la prima parte. Senza
     riconoscerlo NESSUNO risulterebbe mai in turno — e il ponte direbbe che non
     lavora nessuno: l'errore silenzioso e rassicurante, il peggiore di tutti. */
  ok(ponti.inTurnoOggi([{ id: "x", squadra: "Squadra A", stato: "in-forza" }],
    [{ nome: "Squadra A — Perforazione", stato: "operativa" }]).length === 1,
    "«Squadra A» e «Squadra A — Perforazione» sono la stessa squadra");
  eq(ponti.inTurnoOggi(null, null), [], "dati assenti: nessuno, e nessun errore");
  eq(ponti.inTurnoOggi(oper, []), [], "nessuna squadra registrata: nessuno in turno");
});
test("P3 · lo scadenzario ordina per urgenza, e a parità viene prima chi è in turno", () => {
  const oggi = new Date("2026-07-30T00:00:00");
  const lav = [{ id: "d1", nome: "In turno" }, { id: "d2", nome: "A casa" }];
  const oper = [{ id: "o1", lavoratoreId: "d1", squadra: "Squadra A", stato: "in-forza" }];
  const squ = [{ nome: "Squadra A", stato: "operativa" }];
  const sca = [
    { id: "s1", lavoratoreId: "d2", tipo: "Visita", dataScadenza: "2026-07-01" }, // scaduta, a casa
    { id: "s2", lavoratoreId: "d1", tipo: "Visita", dataScadenza: "2026-07-01" }, // scaduta, in turno
    { id: "s3", lavoratoreId: "d1", tipo: "Corso", dataScadenza: "2027-01-01" },  // regolare
  ];
  const q = ponti.scadenzeDiChiLavora(sca, lav, oper, squ, oggi);
  eq(q.righe.map(r => r.scadenza.id), ["s2", "s1", "s3"],
    "prima le scadute, e fra due scadute uguali prima quella di chi è in turno");
  ok(q.daFermare === 1, "una sola riguarda chi sta lavorando adesso");
  ok(q.schierati === 1 && q.schieratiNonCollegati === 0, "e si sa di chi si sta parlando");
});
test("P3 · «nessuno da fermare» non vale se non si è guardato", () => {
  const oggi = new Date("2026-07-30T00:00:00");
  /* una persona schierata SENZA collegamento: il conto delle scadute in turno è
     zero, ma non perché sia tutto a posto — perché non si è potuto guardare.
     Il numero che lo dice esiste apposta. */
  const q = ponti.scadenzeDiChiLavora(
    [{ lavoratoreId: "d1", tipo: "Visita", dataScadenza: "2026-01-01" }],
    [{ id: "d1", nome: "X" }],
    [{ id: "o1", squadra: "Squadra A", stato: "in-forza" }],   // senza lavoratoreId
    [{ nome: "Squadra A", stato: "operativa" }], oggi);
  ok(q.daFermare === 0, "nessuna scaduta risulta in turno…");
  ok(q.schierati === 1 && q.schieratiNonCollegati === 1,
    "…ma c'è una persona schierata di cui non si sa niente, e il conto lo dice");
});
test("P3 · lato Scudo: la dimostrazione dice la stessa cosa dell'altra metà", () => {
  const oggi = new Date("2026-07-30T00:00:00");
  const q = scudo.scadenzeDiChiLavora(scudo.DEMO.scadenze, scudo.DEMO.lavoratori,
    scudo.DEMO.operatoriCampo, scudo.DEMO.squadreCampo, oggi);
  ok(q.schierati === 4, `quattro persone in turno nella dimostrazione (${q.schierati})`);
  ok(q.daFermare >= 1, "e almeno un documento scaduto le riguarda, se no non si vedrebbe niente");
  /* la copia che Scudo tiene di Campo deve coincidere con l'originale, altrimenti
     le due app raccontano due turni diversi */
  eq(scudo.DEMO.operatoriCampo.map(o => o.id + "|" + o.nome + "|" + (o.lavoratoreId || "")),
     campo.DEMO.operatori.map(o => o.id + "|" + o.nome + "|" + (o.lavoratoreId || "")),
     "gli operatori copiati in Scudo sono identici a quelli di Campo");
  eq(scudo.DEMO.squadreCampo.map(s => s.nome + "|" + s.stato),
     campo.DEMO.squadre.map(s => s.nome + "|" + s.stato),
     "e così le squadre, stato compreso");
  ok(scudo.inTurnoOggi === ponti.inTurnoOggi && scudo.scadenzeDiChiLavora === ponti.scadenzeDiChiLavora,
    "Scudo ri-esporta le funzioni di shared/, non ne tiene una copia");
});
test("Campo · le attività citano operatori che esistono davvero", () => {
  /* NASCE DA UN DIFETTO MIO, di un'ora prima: rinominando gli operatori della
     dimostrazione per allinearli a Scudo ho lasciato indietro le attività, che
     citavano ancora «Marco Rossi» e «Luca Ferrari». Campo lega l'attività alla
     persona PER NOME (`a.operatore === o.nome`), quindi il conto «N in carico
     oggi» era diventato zero per tutti — in silenzio, senza errori, e non l'ho
     visto nello screenshot perché il conto semplicemente spariva.
     Nota per il futuro: il legame interno per nome è fragile per la stessa ragione
     per cui il ponte con Scudo non lo usa. Qui però la stringa la scrive l'utente
     nel campo «operatore», e cambiarla in un id è un lavoro a parte: intanto la
     dimostrazione resta coerente per forza. */
  const nomi = new Set(campo.DEMO.operatori.map(o => String(o.nome).trim()));
  const orfane = campo.DEMO.attivita.filter(a => a.operatore && !nomi.has(String(a.operatore).trim()));
  ok(orfane.length === 0,
    `nessuna attività cita una persona fuori anagrafica (${orfane.map(a => a.operatore).join(", ")})`);
  /* e almeno una la cita, altrimenti la prova passerebbe su un elenco vuoto —
     è la trappola del `[].every` già pestata due volte */
  ok(campo.DEMO.attivita.some(a => a.operatore), "e almeno un'attività ha un operatore, se no non si prova niente");
});
test("P3 · la dimostrazione mostra TUTTI gli stati, altrimenti non dimostra", () => {
  const q = campo.idoneitaDiTurno(campo.DEMO.operatori, campo.DEMO.lavoratoriScudo,
    campo.DEMO.scadenzeScudo, new Date("2026-07-30T00:00:00"));
  ok(q.scadute > 0, "c'è almeno un documento scaduto da far vedere");
  ok(q.inScadenza > 0, "e almeno uno in scadenza");
  ok(q.regolari > 0, "e almeno una persona in regola");
  ok(q.nonCollegati > 0, "e almeno una non collegata: è lo stato che si dimentica");
  ok(q.tuttoInRegola === false, "quindi la dimostrazione non dice «tutto a posto»");
});

/* ══════════════════════════════════════════════════════════════════════
   TERRA · LA RIPARTIZIONE PER FRONTE, che è una REGOLA e non un disegno
   ══════════════════════════════════════════════════════════════════════
   Nata guardando la sezione renderizzata, non leggendo il codice. Due difetti
   che i numeri non mostravano:
    · una voce SENZA fronte e SENZA scavo prendeva una riga con badge «0 m³» e
      sembrava rotta. Non è un fronte mancante: è una ripresa da cumulo, che per
      definizione non esce da un fronte;
    · mancava la QUOTA, l'unico numero che un elenco di valori assoluti non dà. */
test("Terra · ripartizione per fronte: una ripresa da cumulo non è un fronte", () => {
  const R = {
    scavo: 79400,
    fronti: [
      { fronteId: "f1", scavo: 40700, cumulo: 0, rilievi: 2 },
      { fronteId: "f2", scavo: 38700, cumulo: 0, rilievi: 2 },
      { fronteId: null, scavo: 0, cumulo: 5200, rilievi: 1 },
    ],
  };
  const RF = terra.ripartizioneFronti(R);
  eq(RF.righe.map(r => r.fronteId), ["f1", "f2"], "la voce di solo cumulo esce dall'elenco");
  ok(RF.cumuliFuori === 5200, "e il suo volume torna a parte, per dirlo a parole");
  ok(RF.conCumuliInRiga === false, "nessuna riga porta cumuli: la nota non deve rimandarci");
  ok(RF.senzaFronte === 0, "e non c'è scavo da attribuire");
});
test("Terra · ripartizione per fronte: uno scavo senza fronte invece RESTA", () => {
  /* è il caso opposto e va distinto: qui manca davvero la ripartizione, ed è
     quella che il modulo dell'ente chiede */
  const R = {
    scavo: 59300,
    fronti: [
      { fronteId: "f1", scavo: 40700, cumulo: 0, rilievi: 2 },
      { fronteId: null, scavo: 18600, cumulo: 5200, rilievi: 2 },
    ],
  };
  const RF = terra.ripartizioneFronti(R);
  ok(RF.righe.length === 2, "la voce senza fronte ma con scavo resta in elenco");
  ok(RF.righe[1].senzaFronte === true, "ed è marcata come tale");
  ok(RF.cumuliFuori === 0, "i suoi cumuli non finiscono fuori: la riga c'è e li porta");
  ok(RF.conCumuliInRiga === true, "e la nota può rimandare alla riga");
  ok(RF.senzaFronte === 1, "c'è uno scavo da attribuire");
});
test("Terra · ripartizione per fronte: la quota, e quando non si può dare", () => {
  const R = { scavo: 79400, fronti: [
    { fronteId: "f1", scavo: 40700, cumulo: 0, rilievi: 2 },
    { fronteId: "f2", scavo: 38700, cumulo: 0, rilievi: 2 }] };
  const q = terra.ripartizioneFronti(R).righe.map(r => r.quotaPct);
  eq(q, [51.3, 48.7], "una cifra decimale, come il resto della denuncia");
  ok(Math.abs(q[0] + q[1] - 100) < 0.11, "e le quote fanno cento");
  /* su un totale zero la quota NON è zero: è una domanda senza senso, e un «0%»
     scritto accanto a un fronte direbbe una cosa falsa */
  const zero = terra.ripartizioneFronti({ scavo: 0, fronti: [{ fronteId: "f1", scavo: 0, cumulo: 0, rilievi: 1 }] });
  ok(zero.righe[0].quotaPct === null, "totale zero: nessuna quota, non «0%»");
  /* un fronte a zero dentro un anno che ha scavato: stessa risposta, per la stessa
     ragione — quel fronte non ha una quota, non ne ha una pari a zero */
  const misto = terra.ripartizioneFronti({ scavo: 1000, fronti: [
    { fronteId: "f1", scavo: 1000, cumulo: 0, rilievi: 1 },
    { fronteId: "f2", scavo: 0, cumulo: 0, rilievi: 1 }] });
  ok(misto.righe[1].quotaPct === null, "fronte senza scavo: nessuna quota");
  ok(misto.righe[0].quotaPct === 100, "e chi ha scavato tutto ha il cento per cento");
});
test("Terra · ripartizione per fronte: niente dati, niente errori", () => {
  eq(terra.ripartizioneFronti({ scavo: 0, fronti: [] }).righe, [], "elenco vuoto");
  eq(terra.ripartizioneFronti(null).righe, [], "riepilogo assente: non un errore");
  eq(terra.ripartizioneFronti({}).righe, [], "riepilogo senza fronti: non un errore");
  ok(terra.ripartizioneFronti(null).cumuliFuori === 0, "e nessun cumulo da dichiarare");
});
test("Terra · ripartizione per fronte: la controprova — prima usciva la riga rotta", () => {
  /* la versione di prima: tutte le voci in elenco, badge = scavo. Si rifà qui per
     mostrare che il difetto c'era davvero, e che la correzione lo toglie. Senza
     questo passaggio le prove qui sopra direbbero solo che la funzione fa quello
     che ho scritto io. */
  const fronti = [
    { fronteId: "f1", scavo: 40700, cumulo: 0, rilievi: 2 },
    { fronteId: null, scavo: 0, cumulo: 5200, rilievi: 1 },
  ];
  const vecchio = fronti.map(f => ({ nome: f.fronteId || "Senza fronte indicato", badge: f.scavo }));
  ok(vecchio.length === 2 && vecchio[1].badge === 0,
    "prima la ripresa da cumulo era una riga con badge «0 m³»");
  const RF = terra.ripartizioneFronti({ scavo: 40700, fronti });
  ok(RF.righe.length === 1, "adesso quella riga non c'è più");
  ok(RF.cumuliFuori === 5200, "e il suo volume non è andato perso: è nella nota");
});
test("Terra · ripartizione per fronte: la dimostrazione la esercita davvero", () => {
  /* una prova su dati inventati direbbe solo che la funzione fa quello che ho
     scritto. Questa passa dal riepilogo VERO della dimostrazione, dove c'è una
     ripresa da cumulo senza fronte: se un giorno sparisse dai dati finti, il caso
     che ha originato la correzione smetterebbe di essere coperto e nessuno lo
     saprebbe. */
  const R = terra.riepilogoAnnuale(terra.DEMO.rilievi, 2026,
    terra.DEMO.autorizzazioni[0], new Date("2026-07-30T00:00:00Z"));
  const RF = terra.ripartizioneFronti(R);
  ok(RF.cumuliFuori > 0,
    `la dimostrazione contiene una ripresa da cumulo senza fronte (${RF.cumuliFuori} m³)`);
  ok(RF.righe.length > 0 && RF.righe.every(r => r.fronteId),
    "e in elenco restano solo fronti veri");
  ok(RF.righe.every(r => r.quotaPct > 0), "tutti con la loro quota");
});
test("P2 · il grafico: la dimostrazione racconta una storia, e un buco", () => {
  /* Il grafico esiste per una domanda che il confronto di un periodo alla volta
     non poteva rispondere: «le stime dei turni stanno migliorando o
     peggiorando?». Se nella dimostrazione lo scarto fosse uguale in tutti gli
     intervalli, il grafico non mostrerebbe niente e la domanda resterebbe senza
     risposta anche con lui. */
  const iv = terra.intervalliFraRilievi(terra.DEMO.rilievi).slice().reverse();
  const scarti = [];
  let buchi = 0;
  for (const i of iv) {
    const m = terra.misuratoPeriodo(terra.DEMO.rilievi, i.dal, i.al);
    const d = terra.produzioneDichiarata(terra.DEMO.rapportiniCampo, i.dal, i.al, 1.9);
    if (!d || !d.turni || !(d.m3 > 0)) { buchi++; continue; }
    scarti.push(Math.round(100 * (m.m3 - d.m3) / m.m3 * 100) / 100);
  }
  ok(scarti.length >= 3, `servono almeno tre punti per vedere un andamento (ce ne sono ${scarti.length})`);
  /* e devono MIGLIORARE, cioè avvicinarsi a zero: è la storia che il grafico
     racconta, e va vista nei numeri prima che a schermo */
  for (let k = 1; k < scarti.length; k++) {
    ok(Math.abs(scarti[k]) < Math.abs(scarti[k - 1]),
      `lo scarto deve stringersi: ${scarti.join(" → ")}`);
  }
  ok(buchi >= 1, "e resta almeno un intervallo senza rapportini, per far vedere il BUCO");
  /* il buco NON è uno zero: la produzione dichiarata di quell'intervallo è
     assente, non nulla — la differenza è tutto il punto */
  const vecchio = iv[0];
  const d0 = terra.produzioneDichiarata(terra.DEMO.rapportiniCampo, vecchio.dal, vecchio.al, 1.9);
  ok(d0 !== null && d0.turni === 0, "nell'intervallo più vecchio non ci sono turni, e il lettore lo dice");
});
test("P2 · lato CAMPO: la dimostrazione di Campo è coerente coi rilievi finti", () => {
  /* Chi compila il rapportino deve vedere l'esito della propria stima. Se i
     numeri d'esempio non si parlano, la prima cosa che si vede è un avviso che
     non significa niente. */
  const per = ponti.periodoFraUltimiRilievi(campo.DEMO.rilieviTerra);
  ok(per != null, "la dimostrazione di Campo ha due rilievi di Terra");
  const vig = campo.DEMO.autorizzazioniTerra.find((a) => a.stato === "vigente");
  const d = ponti.densitaDelMateriale(vig && vig.materiale);
  ok(d && d.densita === 1.9, `la densità si ricava dal materiale dell'atto (${d && d.densita})`);
  const r = ponti.riconciliazioneTurni(campo.DEMO.rilieviTerra, campo.DEMO.rapportini, per.dal, per.al, d.densita);
  eq(r.stato, "coerente", "coi numeri d'esempio i due mondi si parlano");
  ok(Math.abs(r.pct) > 0.5 && Math.abs(r.pct) < 10,
    `e lo scostamento non è ZERO — uno scarto nullo in dimostrazione sembra costruito (${r.pct}%)`);
  ok(r.dich.turni >= 5, `e ci sono abbastanza turni nel periodo (${r.dich.turni})`);
});
test("P2 · «coerente» e «parziale» insieme: la combinazione che inganna", () => {
  /* Trovato guardando lo stato a schermo: con dei viaggi nel periodo il confronto
     diceva «i due numeri si parlano» e in coda ammetteva che i viaggi non erano nel
     conto. Ma se quei viaggi fossero contati il dichiarato salirebbe, e l'accordo
     apparente potrebbe sparire — dichiarare un accordo basandosi su metà dei dati è
     il numero comodo, che qui non si prende mai.
     Questa prova esiste perché la combinazione sia DOCUMENTATA: `stato: "coerente"`
     e `parziale: true` possono presentarsi insieme, e chi scrive un'interfaccia
     sopra `riconciliazioneTurni` deve guardare entrambi. */
  const mis = [{ data: "2026-03-05", stato: "elaborato", volumeM3: 1000, provenienza: "scavo" }];
  const r = terra.riconciliazioneTurni(mis, [
    { data: "2026-03-10", prodQta: 980, prodUnita: "m³" },
    { data: "2026-03-11", prodQta: 14, prodUnita: "viaggi" },
  ], "2026-03-01", "2026-03-31", 2.6);
  eq(r.stato, "coerente", "sui soli metri cubi lo scarto è del 2%");
  ok(r.parziale === true, "ma il conto è parziale: 14 viaggi restano fuori");
  ok(r.dich.viaggi === 14, "e i viaggi sono contati a parte, non convertiti");
  /* la stessa combinazione con delle tonnellate senza densità */
  const r2 = terra.riconciliazioneTurni(mis, [
    { data: "2026-03-10", prodQta: 980, prodUnita: "m³" },
    { data: "2026-03-11", prodQta: 500, prodUnita: "t" },
  ], "2026-03-01", "2026-03-31", null);
  eq(r2.stato, "coerente", "i metri cubi diretti si sommano anche senza densità");
  ok(r2.parziale === true && r2.dich.tSenzaDensita === 500,
    "e le tonnellate non convertibili rendono il conto parziale");
});
test("P2 · UNA SOLA implementazione: Terra ri-esporta, non riscrive", () => {
  /* La logica del ponte serve a Terra e a Campo, e non appartiene a nessuna delle
     due: vive in `shared/dw-ponti.js`. `terra-data.js` la ri-esporta col nome con
     cui Terra l'ha sempre chiamata. Qui si pretende che siano LA STESSA funzione,
     non due copie che si assomigliano — l'identità è l'unica prova che regge, il
     comportamento uguale oggi può divergere domani. */
  for (const nome of ["produzioneRapportino", "produzioneDichiarata", "riconciliazioneTurni",
    "misuratoPeriodo", "intervalliFraRilievi", "periodoFraUltimiRilievi",
    "avanzamentoDaUltimoRilievo"]) {
    ok(typeof ponti[nome] === "function", `shared/dw-ponti esporta ${nome}`);
    ok(terra[nome] === ponti[nome], `${nome}: Terra ri-esporta la funzione condivisa, non una copia`);
  }
  ok(terra.SOGLIA_TURNI === ponti.SOGLIA_TURNI, "e le soglie sono lo stesso oggetto");
  /* la regola del cumulo: era scritta in Terra e in Conti, ora la sorgente è una */
  ok(terra.provenienzaRilievo === ponti.provenienzaDi,
    "provenienzaRilievo di Terra È provenienzaDi di shared/");
  for (const [r, atteso] of [[{ provenienza: "cumulo" }, "cumulo"], [{ provenienza: "Cumulo " }, "cumulo"],
    [{ provenienza: "scavo" }, "scavo"], [{}, "scavo"], [null, "scavo"]]) {
    eq(ponti.provenienzaDi(r), atteso, `provenienzaDi(${JSON.stringify(r)})`);
  }
});
test("P2 · IL CONTRATTO con Campo: le due letture dicono la stessa cosa", () => {
  /* La forma del dato che attraversa il confine è {prodQta, prodUnita}. Terra la
     rilegge per conto suo, e questa è la stessa strada per cui la convenzione sui
     numeri era finita scritta quattro volte: qui il disallineamento deve
     FALLIRE, non restare in silenzio. */
  const casi = [
    { prodQta: 120, prodUnita: "t" }, { prodQta: 0.5, prodUnita: "m³" },
    { prodQta: 12, prodUnita: "viaggi" }, { prodQta: 0, prodUnita: "t" },
    { prodQta: -5, prodUnita: "t" }, { prodQta: null, prodUnita: "t" },
    { prodQta: 7, prodUnita: "tonnellate" },   // unità sconosciuta: ricade sulle t
    { prodQta: 7 },                            // unità assente
    {},
  ];
  for (const c of casi) {
    eq(terra.produzioneRapportino(c), campo.produzioneDi(c),
      `la lettura di Terra e quella di Campo devono coincidere su ${JSON.stringify(c)}`);
  }
  eq(campo.UNITA_PRODUZIONE, ["t", "m³", "viaggi"],
    "e le unità ammesse sono quelle su cui il ponte è costruito");
});

/* ══════════════════════════════════════════════════════════════════════
   LA CONVENZIONE CONDIVISA: due aggiunte per i file delle MACCHINE
   ══════════════════════════════════════════════════════════════════════ */
test("la notazione scientifica è ammessa solo a chi la chiede", () => {
  /* «1.5e3» non è un numero che una persona scrive in un modulo: accettarlo lì
     vorrebbe dire prendere per buono un «2e5» battuto per sbaglio e salvare
     duecentomila. Ma le macchine la scrivono — l'esportazione di una
     perforatrice mette l'energia specifica così, un sismografo può dare la
     velocità come «1.5E-2». Quindi è dietro un interruttore spento. */
  ok(shell.numeroScritto("1.5e3", { decimali: 6 }).ok === false,
    "in un campo scritto a mano resta rifiutata");
  eq(shell.numeroScritto("1.5e3", { decimali: 6 }).motivo, "non-numero", "e il motivo è chiaro");
  ok(shell.numeroScritto("1.5e3", { scientifica: true, decimali: 6 }).valore === 1500,
    "col permesso esplicito si legge");
  for (const [t, atteso] of [["1.5E-2", 0.015], ["2e5", 200000], ["1,5e3", 1500], ["-2.5e2", -250]]) {
    const r = shell.numeroScritto(t, { scientifica: true, decimali: 6 });
    ok(r.ok && r.valore === atteso, `${t} → ${atteso} (ottenuto ${r.valore})`);
  }
  /* il permesso NON apre la porta a tutto il resto */
  for (const t of ["2,4,5", "3x4", "e3", "1.5e", "1.5e3.2", "abc"]) {
    ok(shell.numeroScritto(t, { scientifica: true, decimali: 6 }).ok === false,
      `«${t}» resta rifiutato anche col permesso`);
  }
  /* e un esponente NON è ambiguo come «1.250»: non si chiede niente */
  ok(shell.numeroScritto("1.250e3", { scientifica: true, decimali: 6 }).valore === 1250,
    "«1.250e3» è 1250, non una domanda sulle migliaia");
});
test("l'arrotondamento non può peggiorare il numero", () => {
  /* `Math.round(n * 10^dec)` con molti decimali esce dagli interi esatti e
     restituisce spazzatura: una coordinata UTM chiesta a 10 decimali darebbe
     4,51234567e16, oltre 2^53. Quando succede si tiene il numero com'è. */
  const r = shell.numeroScritto("4512345,67", { decimali: 10 });
  ok(r.ok && r.valore === 4512345.67, `la coordinata resta se stessa (ottenuto ${r.valore})`);
  ok(shell.numeroScritto("2,4449", { decimali: 2 }).valore === 2.44,
    "e nel caso normale si arrotonda come prima");
  ok(shell.numeroScritto("13,25", { decimali: 1 }).valore === 13.3, "13,25 a un decimale è 13,3");
  /* la controprova: senza la guardia il conto andrebbe fuori */
  ok(!Number.isSafeInteger(Math.round(4512345.67 * 1e10)),
    "senza guardia Math.round(n·1e10) sarebbe fuori dagli interi esatti");
});

/* ══════════════════════════════════════════════════════════════════════
   IL MOTORE DEI GRAFICI: un valore mancante non si scavalca
   ══════════════════════════════════════════════════════════════════════
   Queste prove sono nate nel browser, perché è lì che si è SCOPERTO il difetto:
   `percorso` univa tutti i valori numerici in un tratto continuo, quindi
   [95, null, 140] veniva disegnata come una linea intera — un segmento che
   nessuno ha misurato, contro il commento della funzione stessa e contro la regola
   già scritta per gli altri grafici. Per TENERE la regola il browser non serve:
   dentro entrano numeri, fuori esce una stringa. Vivono qui perché una difesa che
   sta nello scratchpad alla prossima sessione non c'è più. */
{
  const { tratti, percorso } = grafici.geometria;
  const px = (i) => i * 100, py = (v) => 200 - v;
  const conta = (d, c) => (d.match(new RegExp("\\" + c, "g")) || []).length;

  test("grafici: i valori si spezzano in tratti di numeri consecutivi", () => {
    eq(tratti([95, null, 140, 290]), [[0], [2, 3]], "un buco separa due tratti");
    eq(tratti([10, 20, 15, 30]), [[0, 1, 2, 3]], "senza buchi un tratto solo");
    eq(tratti([null, 42, null]), [[1]], "un dato isolato è un tratto di un punto");
    eq(tratti([null, null]), [], "tutto mancante: nessun tratto");
    eq(tratti([]), [], "serie vuota: nessun tratto");
    eq(tratti(null), [], "serie assente: nessun tratto, non un errore");
    eq(tratti([10, NaN, 15, undefined, 7]), [[0], [2], [4]], "NaN e undefined fanno buco come null");
    eq(tratti([10, 0, 15]), [[0, 1, 2]],
      "uno ZERO NON è un buco: è una misura, e la linea resta intera");
  });
  test("grafici: la linea non attraversa il buco", () => {
    const d = percorso([95, null, 140, 290], px, py, false);
    ok(conta(d, "M") === 2, `due sottopercorsi, non uno: ${d}`);
    ok(conta(percorso([10, 20, 15, 30], px, py, false), "M") === 1, "senza buchi resta un percorso solo");
    ok(percorso([null, null], px, py, false) === "", "niente da disegnare → stringa vuota");
    /* un punto isolato resta VISIBILE: `l0 0` è un segmento di lunghezza zero, che
       il browser disegna come un puntino. Sparire sarebbe perdere un dato vero. */
    ok(/l0 0/.test(percorso([null, 42, null], px, py, false)), "un dato isolato resta un puntino");
    /* e con la curva morbida il comportamento è lo stesso */
    ok(conta(percorso([1, 2, 3, null, 5, 6, 7], px, py, true), "M") === 2,
      "anche con la curva i tratti restano due");
  });
  test("grafici: la controprova — senza la correzione la linea scavalcherebbe", () => {
    /* si rifà a mano quello che faceva la versione di prima: tutti i numeri in un
       tratto unico. Se un giorno `percorso` tornasse a comportarsi così, la prova
       qui sopra fallisce e questa spiega perché era sbagliato. */
    const vecchio = (valori) => {
      const pts = [];
      valori.forEach((v, i) => { if (Number.isFinite(+v) && v !== null && v !== "") pts.push([px(i), py(v)]); });
      let d = "M" + pts[0][0].toFixed(1) + " " + pts[0][1].toFixed(1);
      for (let i = 1; i < pts.length; i++) d += "L" + pts[i][0].toFixed(1) + " " + pts[i][1].toFixed(1);
      return d;
    };
    const v = [95, null, 140, 290];
    ok(conta(vecchio(v), "M") === 1, "la vecchia logica faceva un percorso solo");
    ok(conta(percorso(v, px, py, false), "M") === 2, "la nuova ne fa due");
  });
}

/* ══════════════════════════════════════════════════════════════════════
   LE ETICHETTE DELL'ASSE X NON SI SOVRAPPONGONO
   ══════════════════════════════════════════════════════════════════════
   Il difetto stava in questo: il motore scampionava le etichette col solo CONTO
   (una ogni `passo`) e poi aggiungeva l'ultima comunque, senza guardare se ci
   stava. Ma lo spazio che serve dipende da quanto è LUNGO il testo, e tutte le
   prove sui grafici usavano `A B C D`. Misurato a 390 px con quattro nomi di
   fronte veri («Gradone Nord-Est», «Gradone Sud-Ovest»): 12 px di sovrapposizione.
   Adesso il passo dà i candidati e la geometria decide chi resta. La decisione è
   in `tenuteX`, che riceve riquadri e torna indici: nessun DOM, quindi la regola
   si prova qui e non solo nel browser dello scratchpad — che alla sessione
   successiva non c'è più. Le larghezze vere, quelle, si misurano nel browser
   (`getBBox`): una stima le aveva sbagliate di un terzo. */
{
  const { tenuteX } = grafici.geometria;
  /* riquadri da sinistra a destra, come li passa il disegno */
  const sp = (sin, larg) => ({ sin, des: sin + larg });

  test("grafici: l'ultima etichetta non si butta mai", () => {
    eq(tenuteX([sp(0, 30)], 4), [0], "una sola etichetta resta");
    /* due attaccate: cade la PRIMA, non l'ultima — il dato più recente è quello
       che si guarda per primo, una tacca intermedia in meno si legge comunque */
    eq(tenuteX([sp(0, 40), sp(35, 40)], 4), [1], "di due sovrapposte resta la seconda");
    /* tre a catena NON si riducono a una: caduta la penultima, la prima non tocca
       più niente e torna a starci. Scartare a catena getterebbe informazione che
       c'è spazio per mostrare — la prima versione di questa prova si aspettava
       proprio quello, e si aspettava male. */
    eq(tenuteX([sp(0, 40), sp(38, 40), sp(76, 40)], 4), [0, 2],
      "tre a catena: cade quella in mezzo, la prima ci sta di nuovo");
  });
  test("grafici: chi ci sta resta, e nell'ordine da sinistra a destra", () => {
    eq(tenuteX([sp(0, 30), sp(50, 30), sp(100, 30)], 4), [0, 1, 2], "larghe abbastanza: tutte");
    /* fra la PRIMA e un'intermedia che si toccano cade l'intermedia: la prima dice
       da dove comincia l'asse, l'intermedia serve solo a leggere la scala */
    eq(tenuteX([sp(0, 30), sp(31, 30), sp(100, 30)], 4), [0, 2],
      "fra la prima e l'intermedia che si toccano cade l'intermedia");
    /* il respiro è un minimo, e «almeno 4» include 4: con 4 px di stacco l'etichetta
       resta, con 3 cade. Il confine va provato da entrambi i lati, altrimenti la
       prova starebbe zitta se un giorno diventasse 3 o 5. */
    eq(tenuteX([sp(0, 30), sp(34, 30)], 4), [0, 1], "4 px di stacco bastano: il respiro è un minimo");
    eq(tenuteX([sp(0, 30), sp(33, 30)], 4), [1], "3 px non bastano");
    eq(tenuteX([sp(0, 30), sp(34, 30)], 0), [0, 1], "senza respiro richiesto basta non toccarsi");
  });
  /* QUESTA PROVA NASCE DA UNO SCREENSHOT, non da un conto. La prima versione di
     `tenuteX` teneva solo l'ultima e scorreva verso sinistra: con quattro nomi di
     fronte a 390 px restavano la SECONDA e la QUARTA, e il lato sinistro dell'asse
     era vuoto — un grafico che non dice da dove comincia. Le sovrapposizioni erano
     zero, quindi nessuna misura automatica se ne sarebbe accorta: si è visto
     guardando. */
  test("grafici: l'asse dice sempre da dove comincia e dove finisce", () => {
    /* quattro etichette larghe, dove solo le due estremità ci stanno */
    const q = [sp(0, 100), sp(80, 100), sp(170, 100), sp(260, 100)];
    eq(tenuteX(q, 4), [0, 3], "restano le due estremità, non due tacche in mezzo");
    /* e se nemmeno le due estremità ci stanno, resta l'ultima: quella non cade mai */
    eq(tenuteX([sp(0, 100), sp(60, 100)], 4), [1], "se le estremità si toccano resta l'ultima");
    /* con tre, la prima e la terza prima della seconda */
    eq(tenuteX([sp(0, 60), sp(50, 60), sp(120, 60)], 4), [0, 2],
      "la tacca di mezzo cede il posto alle estremità");
  });
  test("grafici: niente etichette, niente da decidere", () => {
    eq(tenuteX([], 4), [], "lista vuota");
    eq(tenuteX(null, 4), [], "lista assente: non un errore");
    /* un riquadro non misurabile si SALTA invece di far cadere tutto quello che
       gli sta a sinistra: un'etichetta che non si sa dov'è non deve poter
       cancellare quelle che si sanno */
    eq(tenuteX([sp(0, 30), null, sp(100, 30)], 4), [0, 2], "un riquadro assente si salta");
    eq(tenuteX([sp(0, 30), { sin: NaN, des: NaN }, sp(100, 30)], 4), [0, 2],
      "un riquadro NaN si salta come uno assente");
  });
  /* ── il taglio delle etichette delle BARRE ────────────────────────────────
     Nelle barre i nomi lunghi sono la norma, non l'eccezione: mezzi, clienti,
     fronti. Misurato a 390 px sulla versione che tagliava a conto di caratteri
     (`banda / 6`), due difetti veri: nel verticale due nomi troncati si
     **toccavano** ancora (4 px) e «Bravo»/«Charl…» si leggevano come una parola
     sola; nell'orizzontale non c'era troncatura affatto e un nome lungo **usciva
     dal disegno**. Ora la larghezza si misura (`getComputedTextLength`) e il taglio
     — la parte che si può sbagliare senza accorgersene — sta in `tagliaA`, pura. */
  test("grafici: il taglio di un'etichetta lascia qualcosa da leggere", () => {
    const { tagliaA } = grafici.geometria;
    ok(tagliaA("Escavatore", 20) === "Escavatore", "se ci sta tutto non si tocca");
    ok(tagliaA("Escavatore", 10) === "Escavatore", "il caso al pelo non aggiunge i puntini");
    ok(tagliaA("Escavatore Komatsu", 10) === "Escavatore…", "taglia e mette i puntini");
    /* uno spazio appeso ai puntini legge male, e si vedeva a schermo */
    ok(tagliaA("Dumper Volvo A40", 7) === "Dumper…", "lo spazio prima dei puntini si toglie");
    ok(tagliaA("Cava di Monte Cerreto — settore", 24) === "Cava di Monte Cerreto…",
      "e così il trattino: «Cerreto —…» era il caso vero visto nello screenshot");
    ok(tagliaA("Fronte, Nord", 7) === "Fronte…", "anche la virgola");
    /* sotto una lettera i puntini non dicono niente: a quel punto è la FORMA del
       grafico che è sbagliata, non l'etichetta — ma non si restituisce «…» nudo */
    ok(tagliaA("Escavatore", 0) === "E…", "almeno una lettera prima dei puntini");
    ok(tagliaA("—Nord", 1) === "—…", "se la prima lettera è punteggiatura si tiene comunque");
    ok(tagliaA("", 5) === "", "testo vuoto: niente da tagliare");
    ok(tagliaA(null, 5) === "", "testo assente: non un errore");
  });
  test("grafici: la controprova — il vecchio taglio non bastava", () => {
    const { tagliaA } = grafici.geometria;
    /* la versione di prima: `et.slice(0, floor(banda/6)) + '…'`, senza respiro e
       senza togliere lo spazio. Con banda 60 dà 10 caratteri di «Dumper Volvo A40»
       cioè «Dumper Vol…» — e su «Gradone Nord-Est»/«Gradone Sud-Ovest» le due
       troncature restavano attaccate perché nessuno sottraeva il respiro. */
    const vecchio = (t, banda) => t.slice(0, Math.max(2, Math.floor(banda / 6))) + "…";
    ok(vecchio("Dumper Volvo A40", 60) === "Dumper Vol…", "il vecchio taglio contava i caratteri");
    /* banda 78 → 13 caratteri, e il tredicesimo di «Dumper Volvo A40» è lo SPAZIO */
    ok(vecchio("Dumper Volvo A40", 78) === "Dumper Volvo …",
      "e poteva lasciare uno spazio appeso ai puntini");
    ok(tagliaA("Dumper Volvo A40", 13) === "Dumper Volvo…", "il nuovo no");
  });
  /* ── il numero al centro della ciambella ──────────────────────────────────
     Stessa famiglia: una DIMENSIONE del carattere decisa da una stima per conto di
     caratteri. La stima è tarata sulle cifre, e su «1.111.110 m³/giorno» sbagliava
     per difetto — misurato, 127 px di testo in un buco da 120. Ora si parte dalla
     stima e si riduce in proporzione finché ci sta; la misura arriva da fuori,
     quindi la regola si prova qui con un carattere finto di larghezza nota. */
  test("grafici: il numero al centro si rimpicciolisce finché ci sta", () => {
    const { dimCheCiSta } = grafici.geometria;
    /* carattere finto: a dimensione d il testo è largo d · k */
    const largo = (k) => (d) => d * k;
    ok(dimCheCiSta(30, 120, largo(2)) === 30, "se ci sta già non si tocca");
    /* a 30 il testo è largo 150 in un buco da 120 → 30 · 120/150 = 24 */
    eq(Math.round(dimCheCiSta(30, 120, largo(5))), 24, "riduce in proporzione, in un giro");
    ok(largo(5)(dimCheCiSta(30, 120, largo(5))) <= 120 + 1e-9, "e dopo ci sta davvero");
    /* il pavimento vince sulla proporzione: meglio al limite del leggibile che
       microscopico. Con k=40 la proporzione chiederebbe 3 px. */
    ok(dimCheCiSta(30, 120, largo(40)) === 11, "sotto il minimo non si scende");
    ok(dimCheCiSta(30, 120, largo(40), 15) === 15, "e il minimo è dichiarabile");
    ok(dimCheCiSta(30, 0, largo(5)) === 30, "buco a zero: non si decide niente");
    ok(dimCheCiSta(30, 120, () => 0) === 30, "misura non disponibile: si tiene la stima");
    /* un carattere che NON scala in proporzione non deve far girare all'infinito:
       qui la larghezza resta 300 qualunque sia la dimensione */
    const fisso = dimCheCiSta(30, 120, () => 300);
    ok(fisso === 11, `col carattere che non scala si finisce al minimo, non in un ciclo (${fisso})`);
  });
  test("grafici: la controprova — la vecchia scelta si sovrapponeva", () => {
    /* la versione di prima: gli indici del passo, più l'ultimo, sempre.
       I numeri non sono inventati — sono quelli misurati a 390 px: il disegno va da
       38 a 378 unità di viewBox, e «Gradone Nord-Est» ne occupa circa 108 (86 px di
       schermo, che il viewBox scala a 108). Con quattro nomi così l'ultima entrava
       dentro la penultima. Una prima versione di questa prova usava 60 unità — la
       larghezza dello SCHERMO invece di quella del viewBox — e non conteneva
       nessuna sovrapposizione: la guardia qui sotto l'ha detto. */
    const larg = 108, x0 = 38, x1 = 378;
    const posti = [0, 1, 2, 3].map((i) => x0 + ((x1 - x0) * i) / 3);
    const riquadri = posti.map((X, i) =>
      i === 3 ? sp(X - larg, larg) : i === 0 ? sp(X, larg) : sp(X - larg / 2, larg));
    let sovrapposte = 0;
    for (let i = 1; i < riquadri.length; i++) if (riquadri[i].sin < riquadri[i - 1].des) sovrapposte++;
    ok(sovrapposte > 0, "il caso di prova contiene davvero una sovrapposizione");
    const tenute = tenuteX(riquadri, 4);
    let ancora = 0;
    for (let i = 1; i < tenute.length; i++) {
      if (riquadri[tenute[i]].sin < riquadri[tenute[i - 1]].des) ancora++;
    }
    ok(ancora === 0, `dopo la scelta nessuna si sovrappone (tenute: ${tenute.join(",")})`);
    ok(tenute[tenute.length - 1] === 3, "e l'ultima è fra quelle tenute");
  });
}

/* ── LA GUARDIA SUI CAMPI INTERI ───────────────────────────────────────────
   Fin qui era verificata solo controllando che fosse MONTATA nelle pagine: un
   controllo di montaggio dice che il pezzo c'è, non che funziona. La verifica
   vera si è fatta col browser, digitando davvero in tutti e dieci i campi
   interi di Genesi — e la controprova (stessa pagina con la guardia smontata)
   ha fatto cadere 20 asserzioni su 33, quindi la prova sapeva fallire.
   Quel banco però vive nello scratchpad, cioè alla sessione dopo non esiste:
   la DECISIONE è stata estratta in `decisioneIntero`, funzione pura, e le sue
   tre risposte si provano qui, dove girano sempre e senza browser.
   Il caso che conta davvero è «1.500»: senza guardia il campo `type="number"`
   lo legge all'inglese e vale 1,5 — millecinquecento diventa uno e mezzo, in
   silenzio. Misurato nel browser, non dedotto. */
{
  const { decisioneIntero, eCampoIntero } = shell;
  test("guardia interi: un separatore battuto a mano si rifiuta e si spiega", () => {
    for (const c of [",", "."]) {
      const d = decisioneIntero(c, "1");
      ok(d && d.blocca === true, `«${c}» viene bloccato`);
      ok(/intero/.test(d.messaggio), `«${c}»: il messaggio dice che qui va un intero`);
      ok(d.valore === undefined, `«${c}»: il campo non viene riscritto`);
    }
  });
  test("guardia interi: quello che non c'entra passa senza intralci", () => {
    ok(decisioneIntero("4", "") === null, "una cifra passa");
    ok(decisioneIntero("42", "") === null, "un incolla di sole cifre passa");
    ok(decisioneIntero(null, "") === null, "niente dato (un tasto che non scrive): niente da decidere");
    ok(decisioneIntero(undefined, "12") === null, "dato assente: niente da decidere");
    ok(decisioneIntero("", "12") === null, "dato vuoto: niente da decidere");
  });
  test("guardia interi: un incolla con separatori, a campo vuoto, si ripulisce", () => {
    const d = decisioneIntero("1.500", "");
    ok(d && d.blocca === true, "l'incolla viene fermato");
    eq(d.valore, "1500", "e il campo diventa millecinquecento, non uno e mezzo");
    ok(/separatori/.test(d.messaggio), "dicendo che i separatori sono stati tolti");
    eq(decisioneIntero("1 500.000", "").valore, "1500000", "punto e spazi insieme");
  });
  test("guardia interi: le migliaia separate da spazio le sistema già il browser", () => {
    /* misurato in Chromium, battendo e incollando davvero: «1 500 000» in un
       `type="number"` diventa 1500000, valido. Gli spazi li toglie da sé.
       Una prima versione di questa prova pretendeva che li togliesse la
       GUARDIA, e accusava il codice di non fare una cosa che non serve fare:
       intercettare anche gli spazi vorrebbe dire bloccare tasti che oggi
       funzionano già. Si lascia passare, e lo si scrive qui perché la
       prossima volta non venga «aggiustato». */
    ok(decisioneIntero("1 500 000", "") === null, "spazio normale: la guardia non interviene");
    ok(decisioneIntero("1 500", "") === null, "spazio unificatore: idem");
    ok(decisioneIntero("1 500", "") === null, "spazio stretto: idem");
  });
  test("guardia interi: a campo pieno si rifiuta invece di sovrascrivere", () => {
    /* su type=number non c'è cursore (selectionStart è null, misurato): non si
       può inserire nel punto giusto, e sovrascrivere quello che c'era sarebbe
       peggio del rifiuto */
    const d = decisioneIntero("1.500", "12");
    ok(d && d.blocca === true, "si ferma");
    ok(d.valore === undefined, "e NON tocca quello che c'era");
    ok(/senza separatori/.test(d.messaggio), "spiegando cosa fare");
  });
  test("guardia interi: si applica ai campi giusti e solo a quelli", () => {
    const finto = (attr, tipo) => ({
      tagName: "INPUT", type: tipo === undefined ? "number" : tipo,
      getAttribute: (n) => (n in attr ? attr[n] : null),
    });
    ok(eCampoIntero(finto({ step: "1" })) === true, "step intero: è un campo intero");
    ok(eCampoIntero(finto({})) === true, "senza step: è un campo intero");
    ok(eCampoIntero(finto({ step: "0.5" })) === false, "step decimale: non lo è");
    ok(eCampoIntero(finto({ inputmode: "decimal" })) === false, "inputmode decimale: non lo è");
    ok(eCampoIntero(finto({}, "text")) === false, "un campo di testo non lo è");
    ok(eCampoIntero(null) === false, "niente elemento: non è un errore");
  });
  test("guardia interi: la controprova — senza la guardia «1.500» vale 1,5", () => {
    /* quello che fa il browser da solo, misurato in Chromium: il punto è letto
       come separatore decimale. Se questa prova smette di fallire senza la
       guardia, la guardia non sta più servendo a niente. */
    ok(Number("1.500") === 1.5, "il lettore del browser fa 1,5 di «1.500»");
    eq(Number(decisioneIntero("1.500", "").valore), 1500, "con la guardia fa 1500");
  });
}

/* ── PONTE P2 — CAMPO → TERRA, FRONTE PER FRONTE ────────────────────────
   Terra sapeva quanto è stato cavato fra un rilievo e l'altro, ma non da dove.
   Il rischio grosso di questa funzione non è sbagliare una somma: è attribuire
   la produzione al fronte SBAGLIATO, che è un errore muto su un numero che
   finisce nella denuncia annuale. Per questo si accoppia per `fronteId` e mai
   per nome — e la prova qui sotto lo pretende. */
{
  const { produzionePerFronte } = ponti;
  const FRONTI = [{ id: "f1", nome: "Fronte Nord" }, { id: "f2", nome: "Fronte Est" }];
  const rap = (data, qta, unita, fronteId) => ({ data, prodQta: qta, prodUnita: unita, fronteId });

  test("P2: la produzione si divide per fronte, e la quota è sull'attribuito", () => {
    const r = produzionePerFronte([
      rap("2026-07-10", 1000, "t", "f1"),
      rap("2026-07-11", 500, "t", "f2"),
      rap("2026-07-12", 300, "t", undefined),
    ], FRONTI, "2026-07-01", "2026-07-31", 2.5);
    eq(r.righe.length, 2, "due fronti con produzione");
    eq(r.righe[0].nome, "Fronte Nord", "in testa quello che ha prodotto di più");
    eq(r.righe[0].m3, 400, "mille tonnellate a densità 2,5 fanno 400 m³");
    eq(r.m3Attribuito, 600, "attribuito: solo quello che ha un fronte");
    eq(r.m3Totale, 720, "totale: attribuito più quello che non ce l'ha");
    /* la quota è sull'ATTRIBUITO: dire «il Nord è il 55%» quando un pezzo non
       si sa da dove viene è un modo elegante di mentire */
    eq(r.righe[0].quotaPct, 66.7, "la quota si calcola su quello che si sa");
    eq(r.senzaFronte.m3, 120, "e quello che non si sa resta a parte, dichiarato");
  });

  test("P2: ⛔ NON si accoppia per nome, mai", () => {
    /* il rapportino porta il NOME del fronte al posto dell'identificativo:
       deve finire fra i non attribuiti, non su «Fronte Nord». Se un giorno
       qualcuno «migliora» la funzione facendole leggere i nomi, questa prova
       cade — ed è esattamente il suo mestiere. */
    const r = produzionePerFronte([
      { data: "2026-07-10", prodQta: 100, prodUnita: "m³", fronteId: "Fronte Nord" },
    ], FRONTI, "", "", 2.5);
    eq(r.righe.length, 0, "nessun fronte riconosciuto");
    eq(r.fronteSconosciuto.m3, 100, "finisce fra quelli con un fronte che non esiste");
    ok(r.senzaFronte.m3 === 0, "e non si confonde con chi il fronte non l'ha proprio indicato");
  });

  test("P2: «non indicato» e «fronte che non esiste» restano due cose diverse", () => {
    const r = produzionePerFronte([
      { data: "2026-07-10", prodQta: 50, prodUnita: "m³" },
      { data: "2026-07-11", prodQta: 70, prodUnita: "m³", fronteId: "f-cancellato" },
    ], FRONTI, "", "", 2.5);
    eq(r.senzaFronte.m3, 50, "chi non l'ha indicato");
    eq(r.fronteSconosciuto.m3, 70, "chi indica un fronte che non c'è più");
    eq(r.copertura, 0, "e la copertura dice che non si sa niente di dove venga");
  });

  test("P2: senza densità le tonnellate non diventano metri cubi", () => {
    const r = produzionePerFronte([rap("2026-07-10", 1000, "t", "f1")], FRONTI, "", "", 0);
    eq(r.righe[0].m3, 0, "niente conversione inventata");
    eq(r.righe[0].tSenzaDensita, 1000, "le tonnellate restano dichiarate come tali");
    ok(r.parziale === true, "e il conto si dichiara parziale");
    ok(r.densita === null, "la densità mancante è null, non zero");
  });

  test("P2: i viaggi si contano e non si convertono", () => {
    const r = produzionePerFronte([rap("2026-07-10", 6, "viaggi", "f1")], FRONTI, "", "", 2.5);
    eq(r.righe[0].viaggi, 6, "i viaggi si contano");
    eq(r.righe[0].m3, 0, "ma non diventano metri cubi: manca la portata del mezzo");
    ok(r.parziale === true, "e il conto è dichiaratamente per difetto");
  });

  test("P2: il periodo e i dati inutilizzabili", () => {
    const r = produzionePerFronte([
      rap("2026-06-30", 100, "m³", "f1"),          // prima
      rap("2026-08-01", 100, "m³", "f1"),          // dopo
      rap("2026-07-10", 100, "m³", "f1"),          // dentro
      { data: "non una data", prodQta: 9, prodUnita: "m³", fronteId: "f1" },
      { data: "2026-07-11", fronteId: "f1" },      // senza produzione
    ], FRONTI, "2026-07-01", "2026-07-31", 2.5);
    eq(r.m3Attribuito, 100, "solo quello dentro il periodo");
    eq(r.scartati, 2, "data illeggibile e turno senza produzione: contati, non nascosti");
  });

  test("P2: senza rapportini è «non lo so», non zero", () => {
    ok(produzionePerFronte(null, FRONTI, "", "", 2.5) === null, "null e non un oggetto a zero");
    const vuoto = produzionePerFronte([], FRONTI, "", "", 2.5);
    eq(vuoto.righe.length, 0, "elenco vuoto: nessuna riga");
    ok(vuoto.copertura === null, "e la copertura è «non pervenuta», non 0%");
  });

  test("P2: i fronti della dimostrazione di Campo sono quelli di Terra", async () => {
    /* Se qui inventassi altri identificativi il ponte funzionerebbe in
       dimostrazione e si romperebbe in produzione, che è il modo peggiore di
       sbagliare: nessuno se ne accorge finché non è davanti a un cliente. */
    const dC = await campo.campoData(), dT = await terra.terraData();
    const idC = (await dC.frontiTerra()).map((f) => f.id).sort();
    const idT = (await dT.fronti()).map((f) => f.id).sort();
    ok(idC.length > 0, "Campo ha dei fronti dimostrativi");
    eq(idC.join(","), idT.join(","), "gli stessi identificativi di Terra");
  });

  test("P2: la dimostrazione di Campo esercita davvero la ripartizione", async () => {
    /* dati d'esempio che non toccano il caso interessante sono dati che
       mentono: qui si pretende che ci sia sia produzione attribuita sia
       produzione senza fronte, altrimenti la nota «non attribuita» non si
       vedrebbe mai e nessuno saprebbe se funziona */
    const dC = await campo.campoData();
    const r = produzionePerFronte(await dC.rapportini(), await dC.frontiTerra(), "", "", 2.4);
    ok(r.righe.length >= 2, `almeno due fronti con produzione (${r.righe.length})`);
    ok(r.senzaFronte.m3 > 0, "e qualcosa che dichiaratamente non è attribuito");
    ok(r.copertura > 0 && r.copertura < 100, `copertura fra 0 e 100 (${r.copertura})`);
  });

  test("P2: la funzione vive in shared/ e le app la ri-esportano identica", () => {
    /* non «si comporta uguale»: È la stessa. Due copie uguali oggi divergono
       domani senza che nessuno lo veda. */
    ok(campo.produzionePerFronte === ponti.produzionePerFronte,
      "campo.produzionePerFronte è la stessa funzione di dw-ponti");
    ok(terra.produzionePerFronte === ponti.produzionePerFronte,
      "terra.produzionePerFronte è la stessa funzione di dw-ponti");
  });
}

/* ── L'UNITÀ DENTRO UN TESTO MAIUSCOLO ──────────────────────────────────
   Il 30/07 questa riga è nata in TRE app nello stesso pomeriggio, e nasceva
   già diversa: due accettavano «30gg» attaccato, la terza pretendeva lo
   spazio e su «30gg» non faceva niente. Tre copie che il primo giorno si
   comportano in due modi — il difetto che qui è già costato una giornata.
   Adesso è una sola, in shared/, e queste prove tengono ferma la differenza
   che le divideva. */
{
  const { avvolgiUnita } = shell;
  /* lo spazio di separazione sta DENTRO lo span (il perché è accanto ad
     `avvolgiUnita`): le prove lo scrivono come lo scrive la funzione */
  /* lo spazio di separazione sta DENTRO lo span ed è quello unificatore: il
     perché sta accanto ad `avvolgiUnita`. Le prove lo scrivono con l'escape,
     perché a occhio è identico a uno spazio normale. */
  const U = (u, sp = "") => `<span class="u">${sp ? "\u00A0" : ""}${u}</span>`;
  test("unità nel maiuscolo: col separatore e senza", () => {
    eq(avvolgiUnita("tra 13 gg"), `tra 13${U("gg", " ")}`, "con lo spazio");
    /* è ESATTAMENTE il caso su cui le tre copie divergevano */
    eq(avvolgiUnita("Tagliandi 30gg"), `Tagliandi 30${U("gg")}`, "e attaccato, che una delle tre non vedeva");
  });
  test("unità nel maiuscolo: si avvolge solo quello che è un'unità", () => {
    eq(avvolgiUnita("oggi"), "oggi", "«gg» dentro una parola non è un'unità");
    eq(avvolgiUnita("leggi 3 righe"), "leggi 3 righe", "e nemmeno preceduto da una cifra lontana");
    eq(avvolgiUnita("Squadra B"), "Squadra B", "un testo senza numeri non si tocca");
  });
  test("unità nel maiuscolo: più unità nella stessa frase", () => {
    eq(avvolgiUnita("21 gg e 4 mm"), `21${U("gg", " ")} e 4${U("mm", " ")}`, "tutte e due");
    eq(avvolgiUnita("1500 m³"), `1500${U("m³", " ")}`, "anche il metro cubo, che è il caso peggiore");
  });
  test("unità nel maiuscolo: niente testo, niente errori", () => {
    eq(avvolgiUnita(null), "", "null diventa vuoto, non «null»");
    eq(avvolgiUnita(""), "", "vuoto resta vuoto");
    eq(avvolgiUnita(42), "42", "un numero si accetta e si restituisce come testo");
  });
  /* L'ORA. Le etichette dei tagliandi di Flotta finiscono in una pastiglia, e la
     pastiglia è maiuscola: prima di oggi uscivano «TRA 24,5 H» e «SCADUTA (+20
     H)». Le due prove che contano davvero sono le ultime due: se «h» mangiasse
     la coda di «km/h» o di «m³/h», l'ora finirebbe dentro una velocità e dentro
     una portata — ed è per quello che sta in fondo all'elenco. */
  test("unità nel maiuscolo: l'ora", () => {
    eq(avvolgiUnita("tra 24,5 h"), `tra 24,5${U("h", " ")}`, "l'etichetta di un tagliando");
    eq(avvolgiUnita("SCADUTA (+20 h)"), `SCADUTA (+20${U("h", " ")})`, "e quella scaduta, dentro le parentesi");
    eq(avvolgiUnita("contatore 1.240 h"), `contatore 1.240${U("h", " ")}`, "col migliaio all'italiana");
    eq(avvolgiUnita("40 km/h"), `40${U("km/h", " ")}`, "«km/h» resta intera: l'ora non le stacca la coda");
    eq(avvolgiUnita("120 m³/h"), `120${U("m³/h", " ")}`, "e nemmeno a «m³/h», che è una portata");
    eq(avvolgiUnita("3 ha di piazzale"), "3 ha di piazzale", "«ha» non è un'ora");
  });
  /* ⚠️ QUESTE SONO LE PROVE DELL'ORDINE, e sono le uniche che cadono se qualcuno
     rimette l'elenco in ordine scritto a mano: ognuna è un'unità COMPOSTA che
     comincia con un'unità SEMPLICE già in elenco. Con l'ordine sbagliato non
     falliscono con un errore: restituiscono `<span>kg</span>/m³`, che sembra
     giusto finché non finisce in una pastiglia e diventa «kg/M³» — il metro cubo
     maiuscolo, cioè l'errore che questa funzione esiste per impedire. */
  test("unità nel maiuscolo: la composta batte la semplice", () => {
    eq(avvolgiUnita("2,6 kg/m³"), `2,6${U("kg/m³", " ")}`, "«kg/m³» non si spezza in «kg» più «/m³»");
    eq(avvolgiUnita("1,2 kg/foro"), `1,2${U("kg/foro", " ")}`, "né «kg/foro»");
    eq(avvolgiUnita("2,7 t/m³"), `2,7${U("t/m³", " ")}`, "né la densità");
    eq(avvolgiUnita("400 m³/giorno"), `400${U("m³/giorno", " ")}`, "né «m³/giorno», che comincia come «m³»");
    eq(avvolgiUnita("18 mm/s"), `18${U("mm/s", " ")}`, "né «mm/s», che comincia come «mm»");
  });
  /* Il costo orario di Flotta ha la valuta PRIMA del numero: non c'è nessun
     «€/h» preceduto da una cifra: l'unico pezzo da salvare è la coda. */
  /* ⛔ I SOLDI. Lo spazio dopo il simbolo è quello UNIFICATORE (U+00A0) e va
     chiesto per CODICE, non a occhio: a occhio è identico a uno spazio normale,
     e la differenza si vede solo il giorno in cui, su una colonna stretta, il
     simbolo resta a fine riga e la cifra va a capo da sola. Prima del 30/07 gli
     spazi erano tre: Conti l'unificatore, Terra quello normale, Flotta nessuno. */
  const { euro, euro0, conEuro } = shell;
  test("i soldi: una sola forma per tutto l'ecosistema", () => {
    eq(euro(48200), "€ 48.200,00", "il totale in colonna ha sempre due decimali");
    eq(euro0(48200), "€ 48.200", "l'indicatore arrotondato non ne ha nessuno");
    eq(euro(178.5), "€ 178,50", "«178,5» non è come si scrive una cifra");
    /* ⚠️ «8400,00» SENZA IL PUNTO NON È UN DIFETTO, ed è la prova che ha
       corretto me e non il codice. In italiano il separatore delle migliaia
       compare da cinque cifre in su (regola CLDR: `minimumGroupingDigits` vale
       2), quindi 8.400 si scrive «8400» e 48.200 si scrive «48.200». Avevo
       scritto l'asserzione col punto, dandolo per scontato, e la misura ha detto
       di no. È il comportamento che Conti ha sempre avuto: qui si stava
       unificando la convenzione, non cambiandola. Se un giorno si vorrà il punto
       anche sotto i diecimila — le fatture spesso lo mettono — è una decisione
       da prendere apposta, con `useGrouping: "always"`, e non da far scivolare
       dentro un'unità che parlava d'altro. */
    eq(euro(8400), "€ 8400,00", "sotto i diecimila l'italiano non mette il punto (CLDR)");
    eq(euro(9999.994), "€ 9999,99", "e i centesimi si troncano al centesimo, non si inventano");
    eq(euro(0), "€ 0,00", "zero è zero, non vuoto");
    eq(euro(null), "€ 0,00", "e un dato che manca non diventa «NaN» davanti a un cliente");
    eq(euro(-1234.5), "-€ 1234,50", "il meno sta DAVANTI al simbolo, non incastrato fra simbolo e cifre");
    eq(euro(-48200), "-€ 48.200,00", "e anche quando il punto delle migliaia c'è");
  });
  /* `conEuro` esiste perché il simbolo e il formato del numero sono due cose
     diverse: quando un'app formatta la cifra a modo suo per una ragione sua
     (l'indicatore di Flotta scrive «8,4k» per farla stare in una casella
     piccola) deve poter mettere il simbolo giusto SENZA riscriverne la regola —
     è da quella strada che erano nate le tre forme diverse. */
  test("i soldi: il simbolo si può mettere su un numero scritto a modo proprio", () => {
    eq(conEuro("8,4") + "k", "\u20AC\u00A08,4k", "l'indicatore compatto di Flotta");
    eq(conEuro("-8,4"), "-\u20AC\u00A08,4", "col meno davanti, come le altre due");
    eq(conEuro(""), "\u20AC\u00A0", "una stringa vuota non fa esplodere niente");
    eq(conEuro(null), "\u20AC\u00A0", "e nemmeno un valore che manca");
  });
  test("i soldi: lo spazio è quello unificatore, non quello normale", () => {
    ok(euro(1)[1].charCodeAt(0) === 0xA0, "euro: dopo «€» c'è U+00A0");
    ok(euro0(1)[1].charCodeAt(0) === 0xA0, "euro0: dopo «€» c'è U+00A0");
    /* ⚠️ questa riga era stata riscritta per sbaglio in «non contiene
       l'unificatore», che è l'opposto di quello che deve dire: qui lo spazio
       cercato è quello NORMALE, e infatti si scrive con l'escape. */
    ok(!euro(1).includes("\u20AC\u0020"), "e non c'è nessuno spazio normale dopo il simbolo");
  });
  test("unità nel maiuscolo: il costo orario, con la valuta davanti", () => {
    eq(avvolgiUnita("€19,02/h"), `€19,02${U("/h")}`, "«/h» si salva anche da sola");
    eq(avvolgiUnita("9,7 l/h"), `9,7${U("l/h", " ")}`, "e i litri all'ora restano interi");
    eq(avvolgiUnita("12,50 €/h"), `12,50${U("€/h", " ")}`, "e la forma con lo spazio davanti");
    eq(avvolgiUnita("40 km/h"), `40${U("km/h", " ")}`, "«/h» non stacca la coda a «km/h»");
    eq(avvolgiUnita("120 m³/h"), `120${U("m³/h", " ")}`, "né a «m³/h»");
  });
}


/* IL FORO RIPETUTO NEL PIANO DI CARICO — la decisione OPPOSTA a tutte le altre.
   Ovunque il doppione dentro il file si toglie; qui no. Due righe per lo stesso
   foro non sono un fastidio da ripulire, sono un errore nel PROGETTO della
   volata: toglierne una in silenzio farebbe sparire una carica e scendere il
   totale dell'esplosivo senza che nessuno sappia perché. Entrano entrambe, e
   l'app lo dichiara prima di scrivere. */
test("foriRipetuti: trova i numeri di foro che compaiono più volte", () => {
  const p = [{ foro: 1 }, { foro: 7 }, { foro: 2 }, { foro: 7 }, { foro: 3 }];
  eq(campo.foriRipetuti(p), [7], "il 7 c'è due volte");
});
test("foriRipetuti: un foro nominato tre volte si segnala UNA volta sola", () => {
  eq(campo.foriRipetuti([{ foro: 5 }, { foro: 5 }, { foro: 5 }]), [5],
     "l'avviso non deve dire «5, 5»");
});
test("foriRipetuti: l'ordine è quello del file, non quello dei numeri", () => {
  eq(campo.foriRipetuti([{ foro: 9 }, { foro: 2 }, { foro: 9 }, { foro: 2 }]), [9, 2],
     "chi legge ritrova i fori nell'ordine in cui li ha scritti");
});
test("foriRipetuti: niente doppioni, elenco vuoto o assente = nessun avviso", () => {
  eq(campo.foriRipetuti([{ foro: 1 }, { foro: 2 }]), [], "un piano pulito non avvisa");
  eq(campo.foriRipetuti([]), [], "elenco vuoto");
  eq(campo.foriRipetuti(null), [], "elenco che manca");
  eq(campo.foriRipetuti([{ foro: NaN }, { foro: NaN }]), [],
     "due righe senza numero di foro non sono «lo stesso foro»");
});
test("il piano NON perde righe: parsePianoCsv le tiene tutte e due", () => {
  /* la controprova del comportamento: se un giorno qualcuno applicasse qui la
     regola degli altri import, questo test cade — ed è quello che deve fare. */
  const righe = campo.parsePianoCsv(
    "foro;x;fila;prof;prog;borr;rit\n7;1,0;A;12;25;3;25\n7;1,5;A;12;30;3;42");
  eq(righe.length, 2, "due righe per il foro 7 restano due");
  eq(righe.map(r => r.prog), [25, 30], "e tutte e due le cariche restano nel totale");
  eq(campo.foriRipetuti(righe), [7], "ma il 7 viene segnalato");
});


/* ⛔ LE ORE DEL CONTATORE NON SI INVENTANO (31/07). Il contatore COMANDA la
   manutenzione: `tagliandiInScadenza` calcola quanto manca come «ore previste
   meno ore del mezzo». Un mezzo importato con le ore illeggibili, messo a zero,
   farebbe sembrare il tagliando lontanissimo proprio quando magari è già
   scaduto — e non comparirebbe nessun errore, solo una scadenza sbagliata.
   «Zero ore» e «non lo so» sono due cose diverse, e adesso l'app le distingue:
   il mezzo entra lo stesso, ma finisce fra quelli DA STIMARE, con il perché. */
test("parseMezziCsv: le ore illeggibili restano vuote, non diventano zero", () => {
  const p = flotta.parseMezziCsv("Escavatore 1;Fronte Nord;;operativo");
  eq(p.length, 1, "il mezzo entra lo stesso: esiste");
  eq(p[0].ore, null, "ma senza contatore");
  const q = flotta.parseMezziCsv("Pala 2;Piazzale;abc;operativo");
  eq(q[0].ore, null, "e nemmeno da un testo che non è un numero");
  const r = flotta.parseMezziCsv("Dumper 3;Pista;0;operativo");
  eq(r[0].ore, 0, "uno ZERO scritto apposta resta zero: è un mezzo nuovo");
});
test("un mezzo senza contatore non fa sembrare il tagliando lontano", () => {
  /* La prova che conta: due mezzi identici, uno col contatore e uno senza. */
  const manutenzioni = [{ id: "m1", titolo: "Tagliando 500 h", mezzo: "Pala 2", orePreviste: 500 }];
  const senza = flotta.tagliandiInScadenza(manutenzioni, [{ nome: "Pala 2", ore: null }], [],
    new Date(2026, 6, 31));
  eq(senza.voci.length, 0, "senza contatore non si promette una data");
  eq(senza.daStimare.length, 1, "va fra quelli da stimare");
  ok(/contatore/.test(senza.daStimare[0].perche), "e il perché nomina il contatore");
});


/* ⛔ LA BASE D'ASTA NON SI INVENTA (31/07). Viene SOMMATA: `gareRiepilogo`
   calcola quanto valgono le gare aperte, vinte e perse, ed è il numero che il
   titolare guarda per sapere «per quanto stiamo correndo». Una base illeggibile
   messa a zero abbassa quel totale in silenzio.
   A differenza del prezzo di un prodotto, però, una gara SENZA base è
   legittima: a volte la base non è ancora pubblicata. Quindi la gara entra, la
   base resta vuota, il totale la salta — e il riepilogo dice QUANTE sono, così
   chi legge sa che il totale è parziale. */
test("parseGareCsv: una base illeggibile resta vuota, non diventa zero", () => {
  const g = conti.parseGareCsv("Fornitura inerti 2026;;2026-09-01;aperta");
  eq(g.length, 1, "la gara entra: la scadenza serve comunque");
  eq(g[0].base, null, "ma senza base");
  eq(conti.parseGareCsv("Gara X;abc;2026-09-01;aperta")[0].base, null, "e nemmeno da un testo");
  eq(conti.parseGareCsv("Gara Y;0;2026-09-01;aperta")[0].base, 0, "uno zero scritto apposta resta zero");
});
test("gareRiepilogo: il totale salta le gare senza base, e lo dichiara", () => {
  const r = conti.gareRiepilogo([
    { stato: "aperta", base: 50000 },
    { stato: "aperta", base: null },
    { stato: "aperta", base: 30000 },
  ]);
  eq(r.aperte, 3, "sono tre gare aperte");
  eq(r.baseAperta, 80000, "il totale somma solo quelle con la base");
  eq(r.apertesenzaBase, 1, "e dice che una non ce l'ha: senza questo il totale inganna");
});


/* Terzo e ultimo zero di comodo tolto il 31/07 — e i due che RESTANO, con la
   ragione, perché la decisione va rifatta uguale la prossima volta:
   · `giorniAssenza` di un infortunio **resta zero**: la colonna vuota vuol dire
     davvero «nessuna assenza», che è il caso normale di un near-miss. Qui il
     valore di comodo è quello giusto, come la giacenza di un ricambio.
   · `quota` di un fronte **resta zero**: è un dato descrittivo, non entra in
     nessun conto — cambiarlo sposterebbe solo del rumore. */
test("parseSquadreCsv: «persone» non scritte restano vuote, non diventano zero", () => {
  const q = campo.parseSquadreCsv("Squadra A;;Fronte Nord;operativa");
  eq(q.length, 1, "la squadra entra: esiste e va assegnata");
  eq(q[0].persone, null, "ma senza numero di persone");
  eq(campo.parseSquadreCsv("Squadra B;0;Piazzale;operativa")[0].persone, 0,
     "uno zero scritto apposta resta zero: una squadra si può svuotare");
  eq(campo.parseSquadreCsv("Squadra C;4;Fronte Sud;operativa")[0].persone, 4, "e un numero vero passa");
});


/* LO STATO VUOTO È UNA REGOLA SOLA (31/07). Era scritta SEI volte, una per app,
   e non erano uguali: cinque prendevano il disegno dell'icona, Conti il suo
   NOME. È il difetto che la regola del fondatore vieta — la stessa cosa
   riscritta, che oggi si somiglia e domani no.
   Aggiunto il terzo pezzo che mancava a tutte e sei: COME SI COMINCIA. Misurato
   prima di scriverlo: 99 stati vuoti nelle sei app, ZERO con un modo di
   cominciare. È facoltativo di proposito — «Giornata tranquilla» non ha bisogno
   di un bottone. */
test("statoVuoto: i tre pezzi ci sono, e l'azione è facoltativa", () => {
  const senza = shell.statoVuoto("<svg/>", "Non hai ancora scadenze", "Ti avvisano prima che scadano.");
  ok(senza.includes("Non hai ancora scadenze"), "il titolo");
  ok(senza.includes("Ti avvisano prima che scadano."), "la spiegazione");
  ok(!senza.includes("empty-do"), "senza azione non c'è nemmeno il contenitore: niente spazio vuoto");
  const con = shell.statoVuoto("<svg/>", "Titolo", "Spiegazione", "<button>Aggiungi</button>");
  ok(con.includes('class="empty-do"'), "con l'azione compare il posto dove sta");
  ok(con.includes("<button>Aggiungi</button>"), "e l'azione dentro");
  ok(con.indexOf("empty-sub") < con.indexOf("empty-do"), "l'azione viene DOPO la spiegazione");
});
test("statoVuoto: la struttura è quella del core, invariata", () => {
  const v = shell.statoVuoto("ICONA", "T", "S");
  for (const classe of ["empty-state", "empty-icon", "empty-title", "empty-sub"])
    ok(v.includes(classe), `manca .${classe}: le sei app disegnavano questo`);
});

// ============================================================
// I MODELLI DI CSV DEL DOCUMENTO CARICANO DAVVERO
//
// `docs/ONBOARDING_DATI.md` è il documento che il primo cliente ha in mano
// mentre prepara i suoi file: per ogni import c'è un ESEMPIO da copiare. Fin
// qui nessuno legava quell'esempio al lettore che dovrà digerirlo — bastava
// cambiare una colonna nel codice e il documento restava a insegnare un
// formato che l'app rifiuta, senza che niente si lamentasse. Il difetto non
// farebbe rumore da noi: farebbe rumore il primo giorno, a casa del cliente,
// e sembrerebbe che l'app non funzioni.
//
// Il controllo prende gli esempi VERI dal documento (non copie: il file,
// letto adesso) e li dà alla funzione VERA dell'app, pretendendo che entrino
// TUTTE le righe di dati — non «almeno una»: una riga persa in silenzio è
// esattamente la cosa che nessuno nota.
//
// Controprovato due volte, il 31/07, rimettendo il difetto:
//  · cambiata l'intestazione delle gare nel documento → 3 righe invece di 2
//    (l'intestazione entra come dato, e in lista comparirebbe una gara che si
//    chiama «nome»);
//  · rotta l'estrazione dei blocchi → 17 controlli falliti invece di passare
//    a vuoto.
// ============================================================
{
  const { readFileSync } = await import("node:fs");
  const DOC = readFileSync(join(HERE, "../../../docs/ONBOARDING_DATI.md"), "utf8");

  /* Titolo della sezione → lettore che quella pagina usa davvero. Dal 31/07
     ci sono TUTTI: l'anagrafica dei lavoratori di Scudo era l'unico import
     scritto dentro la pagina, ed è stata portata in `parseLavoratoriCsv`
     proprio perché nessuna prova poteva guardarla. */
  const MAPPA = [
    ["Scudo — 1) anagrafica lavoratori", scudo.parseLavoratoriCsv],
    ["Scudo — 2) scadenzario", scudo.parseScadenzeCsv],
    ["Scudo — 3) registro infortuni", scudo.parseInfortuniCsv],
    ["Flotta — 1) parco mezzi", flotta.parseMezziCsv],
    ["Flotta — 2) ore motore", flotta.parseTelemetriaCsv],
    ["Flotta — 3) magazzino ricambi", flotta.parseRicambiCsv],
    ["Conti — 1) fatture", conti.parseFattureCsv],
    ["Conti — 2) gare", conti.parseGareCsv],
    ["Conti — 3) listino", conti.parseListinoCsv],
    ["Sentinella — sensori", sentinella.parseMonitoraggiCsv],
    ["Sentinella — 2) scadenze ambientali", sentinella.parseAdempimentiCsv],
    ["Sentinella — 3) registro volate", sentinella.parseVolateCsv],
    ["Sentinella — 4) ricettori", sentinella.parseRicettoriCsv],
    ["Terra — 1) fronti", terra.parseFrontiCsv],
    ["Terra — 2) rilievi drone", terra.parseRilieviCsv],
    ["Campo — 1) squadre", campo.parseSquadreCsv],
    ["Campo — 2) piano di carico", campo.parsePianoCsv],
  ];

  /* Primo blocco recintato di ogni sezione «## ...». */
  const esempi = new Map();
  {
    let sezione = null, dentro = false, buf = null;
    for (const r of DOC.split("\n")) {
      if (r.startsWith("## ")) { sezione = r.slice(3).trim(); dentro = false; buf = null; continue; }
      if (r.trim().startsWith("```")) {
        if (!dentro && sezione && !esempi.has(sezione)) { dentro = true; buf = []; }
        else if (dentro) { esempi.set(sezione, buf.join("\n")); dentro = false; buf = null; }
        continue;
      }
      if (dentro) buf.push(r);
    }
  }

  /* ⚠️ La rete di sicurezza del controllo stesso: se l'estrazione si rompe
     (il documento cambia forma, i blocchi non si chiudono più) la mappa resta
     vuota e TUTTI i controlli sotto passerebbero senza guardare niente. Qui si
     pretende che gli esempi si siano trovati, così un controllo inerte
     fallisce invece di mentire. */
  test("onboarding: gli esempi del documento si trovano tutti", () => {
    ok(esempi.size >= MAPPA.length,
       `esempi estratti ${esempi.size}, ne servono almeno ${MAPPA.length}`);
  });

  for (const [titolo, fn] of MAPPA) {
    test(`onboarding: l'esempio «${titolo}» entra tutto`, () => {
      const chiave = [...esempi.keys()].find(k => k.startsWith(titolo));
      ok(chiave, `nel documento non c'è nessuna sezione che inizia con «${titolo}»`);
      const testo = esempi.get(chiave);
      const attese = testo.split("\n").filter(Boolean).length - 1;   // meno l'intestazione
      ok(attese > 0, "l'esempio non ha nemmeno una riga di dati");
      const righe = fn(testo);
      ok(Array.isArray(righe), "il lettore non ha restituito un elenco");
      eq(righe.length, attese, "righe caricate dall'esempio del documento");
    });
  }
}

// ============================================================
// IL GIRO DI ANDATA E RITORNO: QUELLO CHE ESCE DEVE POTER RIENTRARE
//
// `ONBOARDING_DATI.md` promette a chi compra che **il file esportato si
// re-importa**: è la copia di sicurezza, ed è il modo di spostare i dati da
// una postazione all'altra. Una promessa del genere si rompe senza rumore —
// basta aggiungere una colonna all'export, o cambiarne l'ordine, e il file
// continua a scaricarsi benissimo. Ci si accorge il giorno in cui serve
// davvero, cioè il giorno peggiore.
//
// Misurato il 31/07 e trovato un caso vero: l'export delle **fatture** di
// Conti scrive `numero;cliente;emessa;imponibile;…`, mentre il lettore aspetta
// `numero;cliente;importo;emessa;…`. In terza posizione l'export mette una
// data e il lettore ci cerca un importo: `numIt("2026-07-15")` non è un
// numero, la riga cade, e ri-caricando il proprio export si ottengono **zero
// fatture**. Quell'export è un PROSPETTO (stato, incassato, residuo, giorni di
// pagamento: roba da commercialista), non un backup — ed è giusto che lo sia:
// quello che non va è la promessa scritta nel documento, corretta insieme a
// questo controllo.
//
// Qui si guardano i sette che il ri-caricamento lo promettono davvero.
// L'intestazione si legge dal SORGENTE della pagina, non da una copia: una
// copia invecchia in silenzio ed è precisamente il difetto che si sta
// cercando.
// ============================================================
{
  const { readFileSync } = await import("node:fs");
  const pagina = (app) => readFileSync(join(HERE, `../../${app}/index.html`), "utf8");

  /* Per ogni esportazione: il file che scarica, le colonne che il LETTORE
     legge in ordine, una riga d'esempio scritta come la scrive l'export, e
     quante righe deve restituire. */
  const GIRI = [
    { app: "campo", file: "campo_squadre.csv", fn: campo.parseSquadreCsv,
      colonne: ["nome", "persone", "area", "stato"],
      riga: "Squadra A;4;Fronte Nord;operativa" },
    { app: "conti", file: "conti_gare.csv", fn: conti.parseGareCsv,
      colonne: ["titolo", "base", "scadenza", "stato"],
      riga: "Fornitura inerti 2026;50000;2026-09-01;aperta" },
    { app: "conti", file: "conti_listino.csv", fn: conti.parseListinoCsv,
      colonne: ["nome", "unita", "prezzo", "densita", "iva"],
      riga: "Stabilizzato 0/30;t;8,50;1,9;22" },
    { app: "flotta", file: "flotta_ricambi.csv", fn: flotta.parseRicambiCsv,
      colonne: ["nome", "giacenza", "sogliaMin", "prezzo"],
      riga: "Filtro olio motore;6;4;48,00" },
    { app: "scudo", file: "scudo_registro_infortuni.csv", fn: scudo.parseInfortuniCsv,
      colonne: ["data", "tipo", "gravita", "giorniAssenza", "descrizione", "luogo"],
      riga: "2026-07-30;infortunio;lieve;3;taglio alla mano;officina" },
    { app: "scudo", file: "scudo_personale_scadenze.csv", fn: scudo.parseLavoratoriCsv,
      colonne: ["nome", "ruolo", "telefono"],   // le colonne dopo la terza non le legge
      riga: "Rossi Mario;operatore;333 1112222;idoneo;Visita medica;2026-12-01;ok" },
    { app: "sentinella", file: "sentinella_ricettori.csv", fn: sentinella.parseRicettoriCsv,
      colonne: ["nome", "tipo", "distanza", "classe", "soglia", "unita", "nota"],
      riga: "Casa Bianchi;abitazione;320;III;5;mm/s;la più vicina" },
  ];

  /* Trova l'intestazione dell'export che scarica QUEL file: si cerca il nome
     del file e si risale alla riga `csv = "…\n"` più vicina sopra di lui,
     perché è lì che l'export dichiara le proprie colonne. */
  function intestazioneExport(src, nomeFile) {
    const righe = src.split("\n");
    const giu = righe.findIndex(r => r.includes(`a.download = "${nomeFile}"`));
    if (giu < 0) return null;
    for (let k = giu; k >= 0 && k > giu - 40; k--) {
      const m = /csv = "([^"]*?)\\n"/.exec(righe[k]);
      if (m) return m[1];
    }
    return null;
  }

  for (const g of GIRI) {
    test(`giro completo: ${g.file} si ri-carica`, () => {
      const testa = intestazioneExport(pagina(g.app), g.file);
      ok(testa, `nella pagina di ${g.app} non si trova l'export che scarica ${g.file}`);
      const scritte = testa.split(";");
      /* le colonne che il lettore legge devono stare all'INIZIO e in
         quell'ordine: quelle dopo può ignorarle, quelle prima no. */
      eq(scritte.slice(0, g.colonne.length), g.colonne,
         `l'export scrive «${testa}», il lettore legge «${g.colonne.join(";")}»`);
      /* e poi la prova vera: una riga come la scrive l'export, riletta. */
      const righe = g.fn(testa + "\n" + g.riga);
      eq(righe.length, 1, "la riga esportata deve rientrare");
    });
  }


  /* IL VALORE CATTIVO DEVE TORNARE IDENTICO.
     Un nome di cliente con un punto e virgola dentro, o un'unità scritta
     «mm/s; dB(A)», sono cose che una persona scrive davvero. Se l'export non
     le protegge con csvCell, il punto e virgola spezza la riga e il pezzo dopo
     finisce nella colonna successiva — SILENZIOSAMENTE. Misurato il 31/07 su
     Sentinella: «mm/s; dB(A)» tornava con unità «mm/s» e la nota del ricettore
     diventava «dB(A)». Nessun errore, nessun avviso, un dato sbagliato.
     E l'apostrofo di guardia davanti a «=» (che impedisce a Excel di eseguire
     una formula) dev'essere tolto in lettura, altrimenti il nome cambia a ogni
     giro di export e import.
     Controprovato togliendo csvCell all'unità: la prova cade dicendo
     «atteso "mm/s; dB(A)", ottenuto "mm/s"». */
  const CATTIVI = [
    ["nome con punto e virgola", "Cava Rossi; & Figli"],
    ["nome che sembra una formula", "=SOMMA(A1:A9)"],
    ["nome con virgolette", 'Fronte "Nord"'],
  ];
  /* Il valore cattivo va provato su TUTTI e sette gli export che promettono di
     ri-caricarsi, non su uno solo: il buco di Sentinella stava proprio in uno
     che nessuno guardava. Per ognuno: il campo di testo che il cliente scrive
     (nome, titolo, descrizione) e la coda della riga come la scrive l'export. */
  const CODA = [
    ["squadre (Campo)", campo.parseSquadreCsv, ";4;Fronte Nord;operativa", "nome"],
    ["gare (Conti)", conti.parseGareCsv, ";50000;2026-09-01;aperta", "titolo"],
    ["listino (Conti)", conti.parseListinoCsv, ";t;8,50;1,9;22", "nome"],
    ["ricambi (Flotta)", flotta.parseRicambiCsv, ";6;4;48,00", "nome"],
    ["anagrafica (Scudo)", scudo.parseLavoratoriCsv, ";operatore;333 1112222", "nome"],
    ["ricettori (Sentinella)", sentinella.parseRicettoriCsv, ";abitazione;320;III;5;mm/s;", "nome"],
  ];
  for (const [che, valore] of CATTIVI) {
    for (const [dove, fn, coda, campoTesto] of CODA) {
      test(`giro completo: ${dove} — un ${che} torna identico`, () => {
        const letto = fn(shell.csvCell(valore) + coda);
        eq(letto.length, 1, "la riga non si spezza");
        eq(letto[0][campoTesto], valore, "il valore è quello di partenza, carattere per carattere");
      });
    }
  }
  /* Il registro infortuni ha il testo libero in mezzo, non in testa: la
     descrizione e il luogo sono le due colonne che il cliente scrive. */
  for (const [che, valore] of CATTIVI) {
    test(`giro completo: registro infortuni (Scudo) — un ${che} torna identico`, () => {
      const letto = scudo.parseInfortuniCsv(
        "2026-07-30;infortunio;lieve;3;" + shell.csvCell(valore) + ";" + shell.csvCell(valore));
      eq(letto.length, 1, "la riga non si spezza");
      eq(letto[0].descrizione, valore, "la descrizione resta intera");
      eq(letto[0].luogo, valore, "e anche il luogo");
    });
  }
  test("giro completo: l'unità del ricettore sopravvive al punto e virgola", () => {
    /* la riga esattamente come la scrive l'export di Sentinella */
    const c = shell.csvCell;
    const riga = [c("Casa Bianchi"), c("abitazione"), 320, c("III"), 5, c("mm/s; dB(A)"), c("vicina")].join(";");
    const r = sentinella.parseRicettoriCsv(riga)[0];
    eq(r.unita, "mm/s; dB(A)", "l'unità resta intera");
    eq(r.nota, "vicina", "e la nota non si prende il pezzo dell'unità");
  });


  /* ⛔ IL FILE SBAGLIATO NON DEVE ENTRARE. È il difetto più grosso trovato il
     31/07, e non faceva nessun rumore: ri-caricando nel listino il PROSPETTO
     dei prezzi — che è un altro file, con le colonne in un altro ordine —
     entravano tutti i prodotti con prezzo ZERO e con l'IVA presa dalla colonna
     del prezzo («Stabilizzato 0/30» con IVA 8,5%). Un listino intero
     sbagliato, pronto per finire in una fattura, senza un solo avviso.
     La difesa è semplice e non tocca i file buoni: senza un prezzo leggibile
     nella sua colonna la riga non entra. */
  test("giro completo: il prospetto dei prezzi NON entra nel listino", () => {
    const testa = intestazioneExport(pagina("conti"), "conti_listino_prezzi.csv");
    ok(testa, "l'export dei prezzi convertiti esiste");
    const letto = conti.parseListinoCsv(
      testa + "\nStabilizzato 0/30;8,5;t;1,9;8,5;16,15;22\nSabbia lavata;22;m3;1,6;13,75;22;22");
    eq(letto.length, 0, "nessuna riga: le colonne non sono quelle del listino");
  });
  test("il listino non inventa più uno zero al posto del prezzo", () => {
    /* stessa regola già scritta per i ricambi di Flotta: uno zero fa sembrare
       gratis una cosa che non lo è, e da lì passa in un DDT e in una fattura. */
    eq(conti.parseListinoCsv("Misto di cava;t;;1,9;22").length, 0,
       "una riga senza prezzo non entra");
    eq(conti.parseListinoCsv("Misto di cava;t;abc;1,9;22").length, 0,
       "e nemmeno una col prezzo illeggibile");
    const zero = conti.parseListinoCsv("Omaggio;t;0;1,9;22");
    eq(zero.length, 1, "lo zero SCRITTO APPOSTA entra: è una decisione di chi compila");
    eq(zero[0].prezzo, 0, "e vale zero");
  });


  /* ⚠️ LE PROVE QUI SOPRA GUARDANO IL LETTORE, NON L'EXPORT — e il difetto di
     Sentinella stava dall'altra parte. Costruendo la riga con `csvCell` si
     prova che il lettore sa disfare quello che `csvCell` ha fatto; NON si prova
     che l'export lo abbia usato. Per quello si guarda la riga vera nel
     sorgente, e si contano le protezioni: ogni colonna di TESTO ne vuole una.
     Sull'export dei ricettori ce n'erano 2 dove ne servivano 5, ed è così che
     l'unità usciva senza protezione. */
  const PROTEZIONI = [
    ["campo_squadre.csv", "campo", 2, "nome e area"],
    ["conti_gare.csv", "conti", 1, "titolo"],
    ["conti_listino.csv", "conti", 1, "nome"],
    ["flotta_ricambi.csv", "flotta", 1, "nome"],
    ["scudo_registro_infortuni.csv", "scudo", 2, "descrizione e luogo"],
    ["sentinella_ricettori.csv", "sentinella", 5, "nome, tipo, classe, unità, nota"],
  ];
  for (const [file, app, quante, quali] of PROTEZIONI) {
    test(`giro completo: ${file} protegge i campi di testo`, () => {
      const src = pagina(app).split("\n");
      const giu = src.findIndex(r => r.includes(`.download = "${file}"`));
      ok(giu >= 0, `non si trova l'export che scarica ${file}`);
      /* le righe che compongono il CSV stanno fra l'intestazione e il download */
      let inizio = -1;
      for (let k = giu; k >= 0 && k > giu - 40; k--) if (/csv = "/.test(src[k])) { inizio = k; break; }
      ok(inizio >= 0, "non si trova dove l'export dichiara le colonne");
      const corpo = src.slice(inizio, giu).join("\n");
      const trovate = (corpo.match(/csvCell\(/g) || []).length;
      ok(trovate >= quante,
         `${file}: ${trovate} protezioni csvCell, ne servono almeno ${quante} (${quali})`);
    });
  }

  /* Il caso trovato per strada, tenuto fermo perché non torni di nascosto:
     l'export delle fatture NON è un backup, e il documento non deve dire che
     lo sia. Se un giorno lo diventasse, questo controllo lo dice. */
  test("giro completo: l'export delle fatture di Conti resta un prospetto, non un backup", () => {
    const testa = intestazioneExport(pagina("conti"), "conti_situazione_fatture.csv");
    ok(testa, "l'export della situazione fatture esiste");
    const letto = conti.parseFattureCsv(
      testa + "\n2026/001;Edil Rossi Srl;2026-07-15;1000;22;220;1220;2026-08-14;aperta;0;1220;;;0");
    eq(letto.length, 0,
       "oggi non rientra: se qualcuno lo rende ri-caricabile, va aggiornato anche ONBOARDING_DATI.md");
  });
}

/* ══ I NUMERI CHE DIVENTANO SOLDI, E CHE NESSUNA PROVA GUARDAVA ══════════
   ────────────────────────────────────────────────────────────────────────
   Censite il 01/08 le funzioni esportate dai moduli dati e cercate una per una
   in TUTTE le suite. `importiFattura` — quella che decide imponibile, IVA e
   totale di una fattura — non compariva in nessuna. Con lei `convertiQuantita`
   (che trasforma tonnellate in metri cubi con la densità), `canonePeriodo`
   (quello che si deve all'ente per il materiale cavato) e i due prezzi per
   unità.

   Non è un buco di stile: è la parte che finisce su un documento fiscale e su
   una dichiarazione all'ente. Un errore lì non fa rumore — produce un numero
   plausibile e sbagliato, esattamente la categoria di difetto che questa suite
   esiste per prendere. */
{
  const imp = conti.importiFattura;

  test("fattura vecchia (solo `importo`): vale come imponibile, IVA zero", () => {
    const r = imp({ importo: 1000 });
    eq(r.imponibile, 1000, "l'importo diventa imponibile");
    eq(r.ivaImporto, 0, "nessuna IVA");
    eq(r.totale, 1000, "totale uguale all'imponibile");
    eq(r.conIva, false, "ed è dichiarata come fattura senza IVA");
    eq(r.aliquota, null, "senza aliquota: non se ne inventa una");
  });
  test("fattura con IVA: totale e aliquota si ricavano, non si indovinano", () => {
    const r = imp({ imponibile: 1000, ivaImporto: 220 });
    eq(r.totale, 1220, "totale = imponibile + IVA quando il totale non è scritto");
    eq(r.aliquota, 22, "l'aliquota si ricava dal rapporto IVA/imponibile");
    eq(r.conIva, true, "ed è una fattura con IVA");
  });
  test("l'aliquota scritta a mano vince su quella calcolata", () => {
    /* ⚠️ I NUMERI DI QUESTA PROVA SONO SCELTI PER DISCRIMINARE, e la prima
       versione non lo faceva: avevo scritto imponibile 1000 / IVA 100 /
       aliquota 10, ma lì il calcolo dà **anch'esso** 10 — la prova passava
       identica con e senza la riga che fa vincere l'aliquota dichiarata.
       L'ha scoperto la controprova, rimettendo il difetto: due difetti
       iniettati, uno solo trovato. Qui la scritta (10) e la calcolata (22)
       sono diverse apposta, così la prova dice davvero qualcosa.
       La ragione della regola: l'aliquota è un dato del documento, non una
       stima da ricavare per divisione. */
    const r = imp({ imponibile: 1000, ivaImporto: 220, aliquotaIva: 10 });
    eq(r.aliquota, 10, "vince l'aliquota dichiarata, non il 22 che verrebbe dal rapporto");
  });
  test("il totale scritto vince sulla somma, e non viene corretto di nascosto", () => {
    const r = imp({ imponibile: 1000, ivaImporto: 220, totale: 1219.99 });
    eq(r.totale, 1219.99, "il totale del documento resta quello del documento");
  });
  test("imponibile zero: nessuna divisione per zero, nessuna aliquota inventata", () => {
    const r = imp({ imponibile: 0, ivaImporto: 0 });
    eq(r.aliquota, null, "con imponibile zero l'aliquota non si può ricavare: null, non NaN");
    eq(r.totale, 0, "e il totale è zero");
  });
  test("una fattura assente non fa esplodere il conto", () => {
    const r = imp(null);
    eq(r.totale, 0, "totale zero");
    eq(r.conIva, false, "e nessuna IVA");
  });

  /* ── le conversioni: qui un errore cambia i metri cubi dichiarati ── */
  test("convertiQuantita: t → m³ divide per la densità, m³ → t moltiplica", () => {
    eq(conti.convertiQuantita(27, "t", "m3", 2.7), 10, "27 t a densità 2,7 fanno 10 m³");
    eq(conti.convertiQuantita(10, "m3", "t", 2.7), 27, "e 10 m³ tornano 27 t");
  });
  test("convertiQuantita: stessa unità, nessuna densità richiesta", () => {
    eq(conti.convertiQuantita(12.5, "t", "t", null), 12.5, "t → t resta uguale anche senza densità");
  });
  test("convertiQuantita senza densità utile risponde null, non zero", () => {
    /* zero sarebbe una misura, e sbagliata: null vuol dire «non lo so», ed è
       la convenzione che il resto del progetto già usa */
    eq(conti.convertiQuantita(27, "t", "m3", 0), null, "densità zero: non si sa");
    eq(conti.convertiQuantita(27, "t", "m3", -1), null, "densità negativa: non si sa");
    eq(conti.convertiQuantita(27, "t", "m3", undefined), null, "densità assente: non si sa");
  });

  /* ── il canone: è quello che si deve all'ente ── */
  const pesate = [
    { data: "2026-07-05", prodotto: "Misto", netto: 30, densita: 1.5 },
    { data: "2026-07-20", prodotto: "Misto", netto: 30, densita: 1.5 },
    { data: "2026-06-30", prodotto: "Misto", netto: 99, densita: 1.5 },   // fuori periodo
    { data: "2026-07-10", prodotto: "Sabbia", netto: 10 },                // senza densità
  ];
  test("canonePeriodo: somma solo il periodo chiesto", () => {
    const r = conti.canonePeriodo(pesate, { canoneUnita: "t", canoneAliquota: 1 }, "2026-07-01", "2026-07-31");
    eq(r.tonnellate, 70, "30 + 30 + 10, e le 99 di giugno restano fuori");
  });
  test("canonePeriodo a metri cubi: chi non ha densità NON conta come zero", () => {
    const r = conti.canonePeriodo(pesate, { canoneUnita: "m3", canoneAliquota: 2 }, "2026-07-01", "2026-07-31");
    eq(r.metriCubi, 40, "60 t a densità 1,5 fanno 40 m³; la sabbia senza densità non si somma");
    eq(r.senzaDensita, 1, "e viene CONTATA, così l'utente sa che manca un dato");
  });
  test("canonePeriodo: il dovuto è base × aliquota, per prodotto", () => {
    const r = conti.canonePeriodo(pesate, { canoneUnita: "t", canoneAliquota: 0.5 }, "2026-07-01", "2026-07-31");
    const misto = r.perProdotto.find((x) => x.prodotto === "Misto");
    eq(misto.dovuto, 30, "60 t × 0,50 €/t");
  });
  test("canonePeriodo senza aliquota non inventa un dovuto", () => {
    const r = conti.canonePeriodo(pesate, {}, "2026-07-01", "2026-07-31");
    eq(r.aliquota, 0, "aliquota assente vale zero");
    const misto = r.perProdotto.find((x) => x.prodotto === "Misto");
    eq(misto.dovuto, 0, "e il dovuto è zero, non NaN");
  });
}

/* ══ LA SOGLIA CHE DECIDE SE C'È UN SUPERAMENTO ═════════════════════════
   ────────────────────────────────────────────────────────────────────────
   `sogliaEfficace` era anche lei fra le funzioni che nessuna prova nominava, e
   non decide una sfumatura: decide **contro quale numero** si confronta una
   lettura, cioè se quella lettura diventa un superamento da mettere nel report
   che il cliente consegna all'ente.

   La regola è dichiarata anche nell'interfaccia: se il punto è collegato a un
   ricettore che ha una soglia propria **e la stessa unità**, vince quella del
   ricettore, perché è il limite scritto per quella casa. Il caso che conta
   davvero è però il terzo: unità **diverse**. Lì la funzione NON usa il numero
   del ricettore — confrontare mm/s con dB(A) darebbe un verdetto inventato —
   torna a quella del punto e alza `conflitto`, così l'interfaccia può dirlo. */
{
  const se = sentinella.sogliaEfficace;
  const casa = { id: "r1", nome: "Casa Bianchi", soglia: 3, unita: "mm/s" };

  test("soglia: vince quella del ricettore quando l'unità è la stessa", () => {
    const r = se({ ricettoreId: "r1", soglia: 5, unita: "mm/s" }, [casa]);
    eq(r.valore, 3, "il limite scritto per quella casa");
    eq(r.fonte, "ricettore", "e la fonte lo dice");
    eq(r.conflitto, false, "nessun conflitto");
  });
  test("soglia: senza ricettore collegato vale quella del punto", () => {
    const r = se({ soglia: 5, unita: "mm/s" }, [casa]);
    eq(r.valore, 5, "resta la soglia del punto");
    eq(r.fonte, "punto", "e la fonte lo dice");
  });
  test("soglia: unità DIVERSE non si confrontano, e il conflitto si dichiara", () => {
    /* è il caso per cui questa prova esiste: 3 mm/s e 55 dB(A) non sono
       confrontabili, e prendere il numero del ricettore darebbe un verdetto
       inventato su un documento che va all'ente */
    const r = se({ ricettoreId: "r1", soglia: 55, unita: "dB(A)" }, [casa]);
    eq(r.valore, 55, "si torna alla soglia del punto");
    eq(r.conflitto, true, "e si dichiara il conflitto invece di nasconderlo");
    eq(r.unitaRicettore, "mm/s", "dicendo anche quale unità aveva il ricettore");
  });
  test("soglia: un ricettore senza soglia propria non copre quella del punto", () => {
    const muto = { id: "r2", nome: "Scuola", unita: "mm/s" };
    const r = se({ ricettoreId: "r2", soglia: 4, unita: "mm/s" }, [muto]);
    eq(r.valore, 4, "vale quella del punto");
    eq(r.fonte, "punto", "e la fonte lo dice");
  });
  test("soglia: zero e negativi non sono soglie", () => {
    /* zero non è «nessun limite»: è un limite impossibile da rispettare, e
       preso sul serio farebbe risultare superata ogni singola lettura */
    const zero = { id: "r3", nome: "Cascina", soglia: 0, unita: "mm/s" };
    eq(se({ ricettoreId: "r3", soglia: 4, unita: "mm/s" }, [zero]).valore, 4,
       "una soglia zero sul ricettore non vince");
    eq(se({ soglia: -1, unita: "mm/s" }, []).valore, null,
       "e una soglia negativa sul punto non è una soglia: null");
  });
  test("soglia: un punto senza soglia e senza ricettore risponde null, non zero", () => {
    eq(se({ unita: "mm/s" }, []).valore, null, "null vuol dire «non lo so»");
  });
}

/* ══ IL PUNTO DI RIORDINO E LA VITA DELLA CAVA ══════════════════════════
   Due numeri su cui si prende una decisione vera, e nessuno dei due era
   provato: quanti pezzi tenere a magazzino prima che il fornitore consegni, e
   quanto materiale resta nella concessione. */
{
  test("punto di riordino: consumo × (consegna + sicurezza), arrotondato in su", () => {
    const r = flotta.puntoDiRiordino(0.5, 10, 4);
    eq(r.copertura, 14, "dieci giorni di consegna più quattro di sicurezza");
    eq(r.esatto, 7, "mezzo pezzo al giorno per quattordici giorni");
    eq(r.soglia, 7, "e la soglia è il numero intero di pezzi");
  });
  test("punto di riordino: si arrotonda SEMPRE in su, mai in giù", () => {
    /* mezzo pezzo non si ordina: arrotondare in giù vuol dire restare a secco
       proprio il giorno in cui il mezzo è fermo */
    const r = flotta.puntoDiRiordino(0.5, 11, 0);
    eq(r.esatto, 5.5, "il conto esatto ha i decimali");
    eq(r.soglia, 6, "ma la soglia sale a sei");
  });
  test("punto di riordino: mai sotto un pezzo", () => {
    const r = flotta.puntoDiRiordino(0.001, 1, 0);
    eq(r.soglia, 1, "un consumo piccolissimo dà comunque soglia 1, non 0");
  });
  test("punto di riordino: senza consumo o senza tempo di consegna risponde null", () => {
    /* null vuol dire «non lo so», e per un pezzo che non si sa quanto si usi è
       la risposta onesta: proporre zero sarebbe una proposta */
    eq(flotta.puntoDiRiordino(0, 10, 2), null, "nessun consumo: non si propone niente");
    eq(flotta.puntoDiRiordino(0.5, 0, 2), null, "nessun tempo di consegna: idem");
  });

  const oggi = new Date("2026-07-01T00:00:00Z");
  const aut = { volumeAutorizzatoM3: 100000, sogliaGuardiaPct: 80, anniRitmo: 3 };
  /* ⚠️ I rilievi devono avere `stato: "elaborato"`: `estrattoComplessivo`
     conta SOLO quelli, ed è giusto — un rilievo in calendario o ancora da
     elaborare non è materiale uscito dalla cava. La prima stesura di queste
     prove non lo sapeva e accusava il codice: prima di dire che c'è un
     difetto va letto come il codice si aspetta i dati. */
  const ril = (volumeM3) => [{ data: "2025-07-01", volumeM3, stato: "elaborato" }];
  test("vita cava: percentuale e residuo dal volume autorizzato", () => {
    const v = terra.vitaCava(aut, ril(25000), oggi);
    eq(v.pct, 25, "25.000 su 100.000 fanno il 25%");
    eq(v.residuo, 75000, "e restano 75.000 m³");
    eq(v.stato, "ok", "sotto la soglia di guardia");
  });
  test("vita cava: superata la soglia di guardia lo stato cambia", () => {
    const v = terra.vitaCava(aut, ril(85000), oggi);
    eq(v.stato, "warn", "85% è oltre la guardia dell'80%");
  });
  test("vita cava: il residuo non va sotto zero", () => {
    /* se si è cavato più dell'autorizzato il residuo è zero, non un numero
       negativo: un «-4.000 m³ residui» su un documento è peggio di un errore */
    const v = terra.vitaCava(aut, ril(104000), oggi);
    eq(v.residuo, 0, "residuo zero, non negativo");
    eq(v.stato, "danger", "e lo stato è rosso");
  });
  test("vita cava: senza volume autorizzato non si inventa una vita", () => {
    eq(terra.vitaCava({}, ril(1000), oggi), null,
       "null: senza il numero della concessione non c'è niente da dire");
  });
}

/* ══ IL TITOLO CHE VALE E IL RITMO CHE STIMA L'ESAURIMENTO ══════════════
   `autorizzazioneVigente` sceglie sotto quale titolo si sta cavando, e
   `ritmoMedioAnnuo` è il numero da cui esce l'anno di esaurimento della cava.
   Il ritmo ha una regola che vale la pena bloccare: conta **solo lo scavo**,
   perché il materiale ripreso da un cumulo era già stato scavato (e già
   scalato) prima — contarlo di nuovo consumerebbe due volte la concessione. */
{
  test("titolo vigente: vince quello dichiarato vigente, non il primo dell'elenco", () => {
    const scaduto = { id: "a1", numero: "111", stato: "scaduta" };
    const buono = { id: "a2", numero: "222", stato: "vigente" };
    eq(terra.autorizzazioneVigente([scaduto, buono]).numero, "222", "vince il vigente");
  });
  test("titolo vigente: senza nessun vigente si ripiega sul primo, e nulla si inventa", () => {
    eq(terra.autorizzazioneVigente([{ id: "a1", numero: "111", stato: "scaduta" }]).numero, "111",
       "si mostra quello che c'è");
    eq(terra.autorizzazioneVigente([]), null, "e con l'elenco vuoto: null");
    eq(terra.autorizzazioneVigente(null), null, "come con l'elenco assente");
  });

  const oggiR = new Date("2026-07-01T00:00:00Z");
  test("ritmo medio: volume di scavo diviso gli anni davvero coperti", () => {
    const r = terra.ritmoMedioAnnuo([
      { data: "2024-07-01", volumeM3: 10000, stato: "elaborato" },
      { data: "2026-07-01", volumeM3: 10000, stato: "elaborato" },
    ], 3, oggiR);
    eq(r.volume, 20000, "somma dei volumi elaborati nella finestra");
    eq(Math.round(r.durataAnni), 2, "dal primo rilievo a oggi: due anni");
    /* ⚠️ NON si pretende esattamente 10.000: l'anno qui dura 365,25 giorni
       (i bisestili), quindi due anni di calendario sono 1,9986 anni-media e
       il ritmo viene 10.007. È il codice ad avere ragione — pretendere il
       numero tondo avrebbe fatto passare per difetto la gestione corretta dei
       bisestili. Si controlla quindi la cosa che conta: che il ritmo sia
       quello, a meno dello scarto che i bisestili giustificano. */
    ok(Math.abs(r.annuo - 10000) < 20, `ritmo ~10.000 m³/anno, trovato ${Math.round(r.annuo)}`);
  });
  test("⛔ ritmo medio: la ripresa di CUMULI non consuma la concessione", () => {
    /* la stessa regola che `run-stile.mjs` difende alla regola 7: cumulo =
       già estratto. Se entrasse nel ritmo, l'anno di esaurimento verrebbe
       fuori prima del vero e si prenderebbero decisioni su un numero falso. */
    const r = terra.ritmoMedioAnnuo([
      { data: "2024-07-01", volumeM3: 10000, stato: "elaborato" },
      { data: "2026-07-01", volumeM3: 10000, stato: "elaborato" },
      { data: "2025-07-01", volumeM3: 50000, stato: "elaborato", provenienza: "cumulo" },
    ], 3, oggiR);
    eq(r.volume, 20000, "i 50.000 dal cumulo restano fuori dal ritmo");
  });
  test("ritmo medio: storico troppo corto non produce una media", () => {
    /* meno di tre mesi: una media su due settimane direbbe che la cava finisce
       il mese prossimo, ed è un numero peggiore di nessun numero */
    eq(terra.ritmoMedioAnnuo([{ data: "2026-06-20", volumeM3: 5000, stato: "elaborato" }], 3, oggiR),
       null, "null invece di una media senza senso");
  });
  test("ritmo medio: i rilievi non elaborati non contano", () => {
    eq(terra.ritmoMedioAnnuo([
      { data: "2024-07-01", volumeM3: 10000, stato: "in-calendario" },
      { data: "2026-07-01", volumeM3: 10000, stato: "in-calendario" },
    ], 3, oggiR), null, "un rilievo in calendario non è materiale uscito dalla cava");
  });
}

/* ══ CHI PUÒ SALIRE SU UN MEZZO ═════════════════════════════════════════
   `statoRequisito` legge, dalle scadenze di una persona, se un requisito
   (visita medica, formazione, abilitazione) è coperto. Da lì esce chi risulta
   idoneo. Non era provata.

   Due comportamenti che vanno bloccati, e sono quelli su cui un errore non fa
   rumore:
   · «nessuna riga in scadenzario» deve dare **mancante**, non «regolare» —
     l'assenza di un documento non è una conferma che va tutto bene;
   · con più rinnovi vale **l'ultimo**, cioè la data più lontana: se vincesse
     la più vecchia, una persona in regola risulterebbe scaduta e verrebbe
     tenuta ferma per niente. */
{
  const oggiS = new Date("2026-07-01T00:00:00Z");
  const req = { chiave: "visita-medica", etichetta: "Visita medica", parole: ["visita"] };

  test("requisito senza nessuna riga in scadenzario: MANCANTE, non regolare", () => {
    const r = scudo.statoRequisito(req, [], oggiS);
    eq(r.stato, "mancante", "l'assenza del documento non è una conferma");
    eq(r.scadenza, null, "e non si inventa una data");
  });
  test("requisito coperto e lontano: regolare", () => {
    const r = scudo.statoRequisito(req, [
      { id: "s1", preset: "visita-medica", dataScadenza: "2027-01-01" },
    ], oggiS);
    eq(r.stato, "regolare", "manca più di un mese");
    eq(r.scadenzaId, "s1", "e dice quale riga lo copre");
  });
  test("requisito scaduto: scaduta", () => {
    const r = scudo.statoRequisito(req, [
      { id: "s1", preset: "visita-medica", dataScadenza: "2026-06-01" },
    ], oggiS);
    eq(r.stato, "scaduta", "la data è passata");
  });
  test("⛔ con più rinnovi vale l'ULTIMO, non il primo trovato", () => {
    /* il caso vero: la visita del 2025 è stata rinnovata nel 2027. Se vincesse
       la vecchia, una persona in regola risulterebbe scaduta e resterebbe a
       terra senza motivo — un difetto che costa una giornata di lavoro a
       qualcuno e non dà nessun errore. */
    const r = scudo.statoRequisito(req, [
      { id: "vecchia", preset: "visita-medica", dataScadenza: "2025-06-01" },
      { id: "nuova", preset: "visita-medica", dataScadenza: "2027-06-01" },
    ], oggiS);
    eq(r.stato, "regolare", "vale il rinnovo più lontano");
    eq(r.scadenzaId, "nuova", "ed è quello indicato");
  });
  test("requisito riconosciuto anche per descrizione, non solo per chiave", () => {
    /* chi carica lo scadenzario da CSV non scrive le chiavi interne: scrive
       «Visita medica». Se il riconoscimento fosse solo per chiave, tutti i
       requisiti caricati da file risulterebbero mancanti. */
    const r = scudo.statoRequisito(req, [
      { id: "s9", descrizione: "Visita medica", dataScadenza: "2027-01-01" },
    ], oggiS);
    eq(r.stato, "regolare", "riconosciuto dalla descrizione");
    eq(r.scadenzaId, "s9", "ed è la riga giusta");
  });
}

/* ══ IL REPORT DI CONFORMITÀ — È IL DOCUMENTO CHE VA ALL'ENTE ═══════════
   ────────────────────────────────────────────────────────────────────────
   `reportConformita` non era provata, ed è la funzione che produce l'unica
   cosa che il cliente consegna davvero fuori dall'azienda. Qui un errore non
   fa perdere tempo: fa dichiarare il falso a un ente.

   Tre comportamenti da bloccare, tutti e tre nel verso che ASSOLVE — cioè
   quello pericoloso, perché un difetto che assolve non lo segnala nessuno:
   · la lettura **esattamente sulla soglia** conta come superamento (`>=`).
     Cambiarlo in `>` farebbe risultare conformi proprio i casi limite, che
     sono quelli su cui si discute;
   · un punto **senza letture** non è «conforme», è «senza-dati». Dire
     conforme dove non si è misurato è la bugia più facile da scrivere;
   · le letture **fuori periodo** non entrano: un report di luglio con dentro
     una misura di giugno non è il report di luglio.

   ⛔ Qui si MISURA il comportamento, non si tocca nessuna soglia: le soglie
   di sicurezza restano decisione del fondatore. */
{
  const casa = { id: "r1", nome: "Casa Bianchi", soglia: 3, unita: "mm/s" };
  const punto = (letture) => ({
    id: "m1", nome: "Vibrazioni P1", unita: "mm/s", soglia: 3, ricettoreId: "r1", letture,
  });
  const fai = (letture, extra) => sentinella.reportConformita({
    dal: "2026-07-01", al: "2026-07-31", ricettori: [casa],
    monitoraggi: [punto(letture)], ...(extra || {}),
  });

  test("report: una lettura sotto soglia è conforme", () => {
    const r = fai([{ data: "2026-07-10", valore: 2 }]);
    eq(r.esito, "conforme", "2 mm/s sotto una soglia di 3");
    eq(r.nSuperamenti, 0, "nessun superamento");
  });
  test("⛔ report: la lettura ESATTAMENTE sulla soglia è un superamento", () => {
    const r = fai([{ data: "2026-07-10", valore: 3 }]);
    eq(r.nSuperamenti, 1, "3 su soglia 3 conta come superamento");
    eq(r.esito, "non-conforme", "e il report lo dichiara");
  });
  test("⛔ report: senza letture NON è conforme, è senza-dati", () => {
    const r = fai([]);
    eq(r.esito, "senza-dati", "dire conforme dove non si è misurato sarebbe falso");
    eq(r.nLetture, 0, "e le letture sono zero");
  });
  test("⛔ report: le letture fuori periodo restano fuori", () => {
    const r = fai([
      { data: "2026-06-20", valore: 9 },   // giugno: fuori
      { data: "2026-07-10", valore: 2 },
    ]);
    eq(r.nLetture, 1, "una sola lettura nel periodo");
    eq(r.esito, "conforme", "il 9 di giugno non rende non conforme il report di luglio");
  });
  test("report: minimo, massimo e media si leggono dalle letture del periodo", () => {
    const r = fai([
      { data: "2026-07-05", valore: 1 },
      { data: "2026-07-15", valore: 2 },
    ]);
    const p = r.punti[0];
    eq(p.min, 1, "minimo");
    eq(p.max, 2, "massimo");
    eq(p.media, 1.5, "media");
  });
  test("report: filtrando per ricettore si guarda solo quel ricettore", () => {
    const altro = { id: "m2", nome: "Polveri P2", unita: "mm/s", soglia: 3,
                    ricettoreId: "r2", letture: [{ data: "2026-07-10", valore: 99 }] };
    const r = sentinella.reportConformita({
      dal: "2026-07-01", al: "2026-07-31", ricettori: [casa], ricettoreId: "r1",
      monitoraggi: [punto([{ data: "2026-07-10", valore: 2 }]), altro],
    });
    eq(r.punti.length, 1, "solo il punto di quel ricettore");
    eq(r.esito, "conforme", "e il 99 dell'altro ricettore non lo tocca");
  });
  test("report: un valore illeggibile non diventa zero, viene scartato", () => {
    /* zero sarebbe una misura, e per giunta rassicurante */
    const r = fai([{ data: "2026-07-10", valore: "non-un-numero" }]);
    eq(r.nLetture, 0, "scartata");
    eq(r.esito, "senza-dati", "e il report lo dice invece di dichiarare conforme");
  });
}

/* ══ CHI VA FERMATO, E CHI INVECE NO ════════════════════════════════════
   ────────────────────────────────────────────────────────────────────────
   `lavoratoriScoperti` è il numero che va in cima al Quadro di Scudo, perché è
   quello che **ferma il lavoro**. Sotto c'è `abilitazioneLavoratore`, che
   distingue fra ciò che BLOCCA e ciò che è solo un'attenzione.

   Quella distinzione è la cosa da difendere, e sbaglia in due modi opposti,
   tutti e due costosi:
   · se un'attenzione diventasse un blocco, si fermerebbe gente che può
     lavorare — e un'app che ferma per niente viene aggirata entro una
     settimana, che è il modo peggiore di perdere una difesa;
   · se un blocco diventasse un'attenzione, salirebbe su un mezzo chi non
     doveva. */
{
  const oggiL = new Date("2026-07-01T00:00:00Z");
  const rossi = { id: "L1", nome: "Rossi Mario", attivo: true };
  const mans = (extra) => ({ nome: "Escavatorista", lavoratoriIds: ["L1"],
                             requisiti: ["visita-medica"], dpi: [], ...(extra || {}) });
  const scad = (dataScadenza) => [{ id: "s1", lavoratoreId: "L1",
                                    preset: "visita-medica", dataScadenza }];

  test("scoperti: requisito in regola, nessuno da fermare", () => {
    const out = scudo.lavoratoriScoperti([mans()], [rossi], scad("2027-01-01"), [], oggiL);
    eq(out.length, 0, "Rossi può lavorare");
  });
  test("⛔ scoperti: requisito SCADUTO ferma la persona", () => {
    const out = scudo.lavoratoriScoperti([mans()], [rossi], scad("2026-01-01"), [], oggiL);
    eq(out.length, 1, "Rossi è scoperto");
    ok(out[0].motivi.some((m) => /scadut/i.test(m)), `il motivo lo dice: ${out[0].motivi.join(" · ")}`);
  });
  test("⛔ scoperti: requisito MANCANTE ferma la persona", () => {
    const out = scudo.lavoratoriScoperti([mans()], [rossi], [], [], oggiL);
    eq(out.length, 1, "senza la riga in scadenzario è scoperto");
    ok(out[0].motivi.some((m) => /manca/i.test(m)), "e il motivo dice che manca");
  });
  test("⛔ scoperti: «in scadenza» NON ferma — è un'attenzione, non un blocco", () => {
    /* fra venti giorni scade: va rinnovata, ma oggi la persona può lavorare.
       Fermarla sarebbe un falso allarme, e i falsi allarmi insegnano a
       ignorare anche quelli veri. */
    const out = scudo.lavoratoriScoperti([mans()], [rossi], scad("2026-07-20"), [], oggiL);
    eq(out.length, 0, "in scadenza non è scoperto");
  });
  test("⛔ scoperti: chi non è più in forza è fermo, qualunque carta abbia", () => {
    const uscito = { id: "L1", nome: "Rossi Mario", attivo: false };
    const out = scudo.lavoratoriScoperti([mans()], [uscito], scad("2027-01-01"), [], oggiL);
    eq(out.length, 1, "non è in forza");
    ok(out[0].motivi.some((m) => /forza/i.test(m)), "e il motivo lo dice");
  });
  test("⛔ scoperti: «non idoneo» ferma, «idoneo con prescrizioni» no", () => {
    const no = { id: "L1", nome: "Rossi Mario", attivo: true, idoneita: "non-idoneo" };
    const pres = { id: "L1", nome: "Rossi Mario", attivo: true, idoneita: "prescrizioni" };
    eq(scudo.lavoratoriScoperti([mans()], [no], scad("2027-01-01"), [], oggiL).length, 1,
       "il giudizio di non idoneità ferma");
    eq(scudo.lavoratoriScoperti([mans()], [pres], scad("2027-01-01"), [], oggiL).length, 0,
       "le prescrizioni no: si lavora, con le prescrizioni");
  });
  test("scoperti: una persona compare UNA volta sola, con tutte le sue mansioni", () => {
    const due = [mans(), mans({ nome: "Addetto brillamento" })];
    const out = scudo.lavoratoriScoperti(due, [rossi], [], [], oggiL);
    eq(out.length, 1, "una riga per persona, non una per mansione");
    eq(out[0].mansioni.length, 2, "ma le mansioni bloccate sono elencate tutte e due");
    eq(out[0].motivi.length, 1, "e il motivo, che è lo stesso, non si ripete");
  });
}

/* ══ IL GIRO MACCHINA: CHI L'HA FATTO E CHI HA TROVATO QUALCOSA ═════════
   `coperturaControlli` dice quanti mezzi hanno il giro fatto oggi, quali
   mancano, e **su quanti è stata trovata un'anomalia**. È il riquadro da cui
   si decide se un mezzo esce.

   ⚠️ L'ultimo dei tre numeri aveva un difetto che dipendeva dall'ORDINE
   dell'elenco, trovato il 01/08 misurando invece di leggere: il conteggio
   guardava solo il PRIMO giro di ogni mezzo. In cava un mezzo si controlla a
   ogni cambio turno, quindi il caso non è teorico — primo giro pulito, secondo
   giro con un'anomalia, e il riquadro diceva **zero anomalie**. Adesso il mezzo
   conta se l'anomalia c'è in QUALUNQUE giro della giornata. */
{
  const mezzi = [{ nome: "Dumper D4" }, { nome: "Pala PC210" }];
  const cc = flotta.coperturaControlli;

  test("giro macchina: chi non l'ha fatto finisce fra i mancanti", () => {
    const r = cc([{ data: "2026-07-01", mezzo: "Dumper D4", anomalie: 0 }], mezzi, "2026-07-01");
    eq(r.totale, 2, "due mezzi nel parco");
    eq(r.fatti, 1, "uno solo ha il giro fatto");
    eq(r.mancanti.join(","), "Pala PC210", "e si dice quale manca");
  });
  test("giro macchina: i giri di un altro giorno non contano per oggi", () => {
    const r = cc([{ data: "2026-06-30", mezzo: "Dumper D4", anomalie: 0 }], mezzi, "2026-07-01");
    eq(r.fatti, 0, "il giro di ieri non copre oggi");
    eq(r.mancanti.length, 2, "mancano tutti e due");
  });
  test("giro macchina: un giro su un mezzo non più nel parco non gonfia il conto", () => {
    const r = cc([{ data: "2026-07-01", mezzo: "Escavatore venduto", anomalie: 0 }], mezzi, "2026-07-01");
    eq(r.fatti, 0, "non è un mezzo del parco");
    eq(r.totale, 2, "e il totale resta quello del parco");
  });
  test("giro macchina: i mezzi con un'anomalia si contano una volta sola", () => {
    const r = cc([
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 2 },
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 1 },
    ], mezzi, "2026-07-01");
    eq(r.conAnomalie, 1, "un mezzo, non due giri");
  });
  test("⛔ giro macchina: l'anomalia del SECONDO turno non sparisce", () => {
    /* il difetto vero, che dipendeva dall'ordine: primo giro pulito, secondo
       giro con un'anomalia. Il riquadro diceva zero. */
    const r = cc([
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 0 },
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 3 },
    ], mezzi, "2026-07-01");
    eq(r.conAnomalie, 1, "l'anomalia trovata al secondo giro conta come il primo");
  });
  test("⛔ giro macchina: l'ordine dell'elenco non cambia il risultato", () => {
    const giri = [
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 0 },
      { data: "2026-07-01", mezzo: "Dumper D4", anomalie: 3 },
    ];
    eq(cc(giri, mezzi, "2026-07-01").conAnomalie,
       cc(giri.slice().reverse(), mezzi, "2026-07-01").conAnomalie,
       "stessa giornata, stesso numero, comunque siano ordinati i giri");
  });
}

/* ══ IL CONSUMO PER MEZZO: QUANDO SI PUÒ DIRE, E QUANDO NO ══════════════
   `consumoPerMezzo` calcola litri/ora dai rifornimenti. Il pregio da difendere
   non è la divisione — è che la funzione **si rifiuta di rispondere** quando i
   dati non bastano, e **dice perché**.

   Serve almeno un secondo rifornimento col contatore delle ore, altrimenti non
   si sa quante ore separano i due pieni. Rispondere lo stesso — con i litri
   diviso un'ora inventata — darebbe un numero su cui qualcuno deciderebbe se
   un mezzo consuma troppo. */
{
  const cpm = flotta.consumoPerMezzo;
  const p = (data, litri, ore, euro) => ({ data, mezzo: "Dumper D4", litri, ore, euro });

  test("consumo: con due pieni e il contatore si calcolano i litri/ora", () => {
    const r = cpm([p("2026-07-01", 100, 1000, 150), p("2026-07-10", 200, 1100, 300)]);
    const m = r.mezzi[0];
    eq(m.oreCoperte, 100, "cento ore fra il primo e l'ultimo pieno");
    ok(m.litriOra > 0, `litri/ora calcolati: ${m.litriOra}`);
  });
  test("⛔ consumo: con un solo contatore NON si inventa un numero", () => {
    const r = cpm([p("2026-07-01", 100, 1000, 150), p("2026-07-10", 200, null, 300)]);
    const m = r.mezzi[0];
    eq(m.litriOra, null, "null invece di un litri/ora inventato");
    /* ⚠️ È QUESTA la riga che discrimina, non quella sopra. Provato togliendo
       il ramo «dati insufficienti» su una COPIA del modulo: `litriOra` resta
       null lo stesso (con un contatore solo le ore coperte sono zero, e il
       calcolo non parte comunque), mentre la RAGIONE cambia — diventa «il
       contatore non è cambiato», che è una spiegazione sbagliata per il caso.
       Se un domani si tenesse solo l'asserzione sul numero, questa prova
       smetterebbe di misurare senza che il totale cali di uno. */
    ok(/secondo rifornimento/i.test(m.perche), `e si dice perché: ${m.perche}`);
  });
  test("⛔ consumo: senza nessun contatore si dice che manca il contatore", () => {
    const r = cpm([p("2026-07-01", 100, null, 150), p("2026-07-10", 200, null, 300)]);
    const m = r.mezzi[0];
    eq(m.litriOra, null, "niente numero");
    ok(/contatore/i.test(m.perche), `e la ragione è quella giusta: ${m.perche}`);
  });
  test("consumo: i litri comunque si sommano, anche senza contatore", () => {
    /* il consumo orario non si può dire, ma i litri messi nel serbatoio sì:
       sono un dato certo e servono per la spesa */
    const r = cpm([p("2026-07-01", 100, null, 150), p("2026-07-10", 200, null, 300)]);
    eq(r.mezzi[0].litri, 300, "trecento litri in tutto");
    eq(r.mezzi[0].euro, 450, "e quattrocentocinquanta euro");
  });
  test("consumo: un rifornimento senza litri non entra", () => {
    const r = cpm([p("2026-07-01", 0, 1000, 0), p("2026-07-10", 200, 1100, 300)]);
    eq(r.mezzi[0].litri, 200, "il pieno da zero litri non è un pieno");
  });
}

/* ══ IL PROSSIMO TAGLIANDO — DA DOVE RIPARTE IL CONTO ═══════════════════
   `prossimoTagliando` decide quando un mezzo andrà fermato per la
   manutenzione. La regola scritta nel modulo, e che qui si blocca:

   > si riparte dalle ore che il mezzo ha **adesso**, non da quelle previste.

   Se il tagliando dei 6000 h è stato fatto a **6040**, il prossimo cade a
   6040 + passo. Ripartire dalle 6000 previste vorrebbe dire che ogni ritardo
   si accumula in silenzio: dopo cinque tagliandi il mezzo gira con duecento
   ore di manutenzione arretrata, e il piano continua a dire che è a posto.

   E i decimi: i contaore contano i decimi, quindi 5875,5 non diventa 5876 —
   scriveremmo «il contatore segna adesso 5.876 ore», un numero che quel
   contatore non ha mai detto. */
{
  const pt = flotta.prossimoTagliando;

  test("⛔ tagliando a ore: si riparte dalle ore VERE, non da quelle previste", () => {
    const r = pt({ titolo: "Tagliando 500h", mezzo: "Dumper D4", ogniOre: 500 }, 6040, "2026-07-01");
    eq(r.orePreviste, 6540, "6040 (le ore vere) + 500, non 6000 + 500");
    eq(r.oreBase, 6040, "e si dichiara da quali ore si è ripartiti");
    eq(r.da, "ore", "il criterio è quello a ore");
  });
  test("tagliando a ore: i decimi del contatore non si arrotondano all'ora", () => {
    const r = pt({ titolo: "T", ogniOre: 500 }, 5875.5, "2026-07-01");
    eq(r.oreBase, 5875.5, "il contatore segna 5875,5 e resta 5875,5");
  });
  test("tagliando a calendario: dalla data di chiusura più i mesi del passo", () => {
    const r = pt({ titolo: "Revisione", ogniMesi: 12 }, null, "2026-07-01");
    eq(r.dataPrevista, "2027-07-01", "un anno dopo la chiusura");
    eq(r.da, "mesi", "il criterio è quello a calendario");
    eq(r.orePreviste, null, "e non si mette anche una soglia a ore");
  });
  test("tagliando: senza passo non si programma niente", () => {
    /* comportamento dichiarato: una manutenzione una tantum non genera il
       prossimo appuntamento, e inventarlo riempirebbe lo scadenzario di
       scadenze che nessuno ha chiesto */
    eq(pt({ titolo: "Riparazione una tantum" }, 6040, "2026-07-01"), null, "nessun passo, nessun piano");
  });
  test("tagliando a ore: senza il contatore non si programma a ore", () => {
    eq(pt({ titolo: "T", ogniOre: 500 }, null, "2026-07-01"), null,
       "senza le ore attuali il conto non si può fare, e non si tira a indovinare");
    eq(pt({ titolo: "T", ogniOre: 500 }, -1, "2026-07-01"), null, "e un contatore negativo non è un contatore");
  });
}

/* ══ LA NUMERAZIONE DELLE FATTURE ═══════════════════════════════════════
   `prossimoNumero` propone il numero della prossima fattura. Non era provata,
   ed è una di quelle cose in cui un errore non si vede subito e poi non si può
   più sistemare: due fatture con lo stesso numero sono un'irregolarità, e la
   correzione a posteriori richiede una nota di credito.

   Il comportamento che conta di più è quello sui **buchi**: se esistono la 001
   e la 005, la prossima è la **006**, non la 002. Riempire un buco vorrebbe
   dire riusare il numero di una fattura annullata — cioè creare il doppione
   che si voleva evitare. */
{
  const pn = conti.prossimoNumero;

  test("numerazione: il primo numero dell'anno", () => {
    eq(pn([], 2026), "2026/001", "si comincia da uno, con lo zero davanti");
  });
  test("numerazione: si continua dal più alto", () => {
    eq(pn(["2026/001", "2026/002"], 2026), "2026/003", "il massimo più uno");
  });
  test("⛔ numerazione: i buchi NON si riempiono", () => {
    /* la 002, 003 e 004 possono essere state annullate: riusarle creerebbe
       due documenti con lo stesso numero, che è l'irregolarità vera */
    eq(pn(["2026/001", "2026/005"], 2026), "2026/006", "si va oltre il massimo, non nel buco");
  });
  test("numerazione: gli anni diversi non si mescolano", () => {
    eq(pn(["2025/041", "2026/002"], 2026), "2026/003", "il 41 del 2025 non conta per il 2026");
    eq(pn(["2025/041"], 2026), "2026/001", "e un anno nuovo riparte da uno");
  });
  test("numerazione: si riconosce anche la forma «001/2026»", () => {
    /* chi arriva da un altro gestionale scrive spesso numero/anno: se non la
       riconoscessimo, la proposta ripartirebbe da 001 e sarebbe un doppione */
    eq(pn(["007/2026"], 2026), "2026/008", "letta anche al contrario");
  });
  test("numerazione: le righe che non sono numeri non spostano il conto", () => {
    eq(pn(["", null, "bozza", "2026/002"], 2026), "2026/003", "solo i numeri veri contano");
  });
  test("numerazione: le cifre di riempimento si rispettano", () => {
    eq(pn(["2026/009"], 2026, 5), "2026/00010", "cinque cifre se cinque sono chieste");
  });
}

/* ══ DAI DDT ALLA FATTURA: NIENTE VIAGGI FATTURATI DUE VOLTE ════════════
   È il flusso vero della cava: tanti viaggi documentati da DDT nel mese, UNA
   fattura riepilogativa. Due funzioni, nessuna delle due provata, e tutte e
   due su cose che diventano soldi:

   · `pesateDaFatturare` sceglie **quali** viaggi entrano. La riga che fa tutto
     il lavoro è `filter(p => !p.fatturaId)`: senza, un DDT già fatturato
     tornerebbe in una seconda fattura, e il cliente pagherebbe due volte lo
     stesso viaggio.
   · `righeDaPesate` raggruppa per prodotto — ma a **parità di prezzo, unità e
     aliquota**. Due prezzi diversi dello stesso prodotto restano due righe, ed
     è come deve essere: fonderle darebbe un prezzo medio che non è quello di
     nessun DDT, su un documento fiscale. */
{
  const ddt = (id, extra) => ({ id, numero: id, data: "2026-07-10", clienteId: "C1",
    prodotto: "Misto", prodottoId: "P1", netto: 10, prezzoUnitario: 5,
    unitaVendita: "t", aliquotaIva: 22, ...(extra || {}) });

  test("⛔ DDT: quelli già fatturati non tornano in una seconda fattura", () => {
    const out = conti.pesateDaFatturare([
      ddt("d1"),
      ddt("d2", { fatturaId: "F-2026-001" }),
    ], "C1");
    eq(out.length, 1, "solo quello non ancora fatturato");
    eq(out[0].id, "d1", "ed è quello giusto");
  });
  test("DDT: si prendono solo quelli del cliente e del periodo chiesti", () => {
    const tutti = [
      ddt("d1"),
      ddt("d2", { clienteId: "C2" }),
      ddt("d3", { data: "2026-06-01" }),
    ];
    eq(conti.pesateDaFatturare(tutti, "C1", "2026-07-01", "2026-07-31").length, 1,
       "un cliente, un periodo, un viaggio");
  });
  test("DDT: senza cliente si prendono quelli di tutti", () => {
    eq(conti.pesateDaFatturare([ddt("d1"), ddt("d2", { clienteId: "C2" })], "").length, 2,
       "il filtro cliente è facoltativo");
  });

  test("righe: i viaggi dello stesso prodotto si sommano in una riga sola", () => {
    const r = conti.righeDaPesate([ddt("d1"), ddt("d2")]);
    eq(r.length, 1, "una riga");
    eq(r[0].quantita, 20, "venti tonnellate in tutto");
    eq(r[0].imponibile, 100, "venti per cinque euro");
    eq(r[0].ddt.length, 2, "e la riga porta con sé i due numeri di DDT");
  });
  test("⛔ righe: prezzi diversi dello stesso prodotto NON si fondono", () => {
    /* fonderle darebbe un prezzo medio che non è quello di nessun DDT, su un
       documento fiscale in cui ogni riga deve essere verificabile */
    const r = conti.righeDaPesate([ddt("d1"), ddt("d2", { prezzoUnitario: 7 })]);
    eq(r.length, 2, "due prezzi, due righe");
  });
  test("⛔ righe: unità diverse non si sommano fra loro", () => {
    const r = conti.righeDaPesate([ddt("d1"), ddt("d2", { unitaVendita: "m3", quantita: 4 })]);
    eq(r.length, 2, "tonnellate e metri cubi restano separati");
  });
  test("righe: aliquote diverse restano righe diverse (serve al registro IVA)", () => {
    const r = conti.righeDaPesate([ddt("d1"), ddt("d2", { aliquotaIva: 10 })]);
    eq(r.length, 2, "ogni aliquota fa storia a sé");
  });
}

/* ══ LE LETTURE DEL SISMOGRAFO CHE ARRIVANO DA UN FILE ══════════════════
   `unisciLetture` mette insieme le letture importate e quelle già registrate.
   Da qui esce il report che va all'ente, quindi tre cose devono valere:

   · i doppioni si scartano — **anche quelli dentro lo stesso file**, che è la
     forma che sfuggiva a tutti gli import prima del 31/07;
   · quando si supera il tetto si tengono le letture **più recenti**, non le
     prime capitate;
   · e quante ne sono state **tagliate** si dice, invece di lasciarle sparire
     in silenzio. Una misura che scompare senza una riga è peggio di una misura
     mancante: nessuno la va a cercare. */
{
  const ul = sentinella.unisciLetture;
  const L = (data, valore, ora) => ({ data, valore, ...(ora ? { ora } : {}) });

  test("letture: le nuove si aggiungono a quelle che c'erano", () => {
    const r = ul([L("2026-07-01", 1)], [L("2026-07-02", 2)]);
    eq(r.aggiunte, 1, "una aggiunta");
    eq(r.letture.length, 2, "e in tutto sono due");
  });
  test("⛔ letture: il doppione di una già presente viene scartato e contato", () => {
    const r = ul([L("2026-07-01", 1)], [L("2026-07-01", 1)]);
    eq(r.aggiunte, 0, "niente aggiunte");
    eq(r.duplicati, 1, "e il doppione si dichiara");
  });
  test("⛔ letture: due righe uguali DENTRO lo stesso file entrano una volta sola", () => {
    /* è la forma di doppione che nel progetto era sfuggita a tutti e dieci gli
       import: si confrontava solo con l'archivio, che non si aggiorna mentre
       il file scorre */
    const r = ul([], [L("2026-07-01", 1), L("2026-07-01", 1)]);
    eq(r.aggiunte, 1, "una sola");
    eq(r.duplicati, 1, "e l'altra è dichiarata doppione");
  });
  test("letture: stessa data e ora ma valore diverso NON è un doppione", () => {
    const r = ul([], [L("2026-07-01", 1, "08:00"), L("2026-07-01", 2, "08:00")]);
    eq(r.aggiunte, 2, "sono due misure diverse");
  });
  test("letture: si riordinano per data e ora", () => {
    const r = ul([], [L("2026-07-03", 3), L("2026-07-01", 1), L("2026-07-02", 2)]);
    eq(r.letture.map((x) => x.valore).join(","), "1,2,3", "in ordine di tempo");
  });
  test("⛔ letture: oltre il tetto si tengono le PIÙ RECENTI, e si dice quante sono cadute", () => {
    const molte = Array.from({ length: 5 }, (_, i) => L(`2026-07-0${i + 1}`, i + 1));
    const r = ul([], molte, 3);
    eq(r.letture.length, 3, "tre tenute");
    eq(r.letture.map((x) => x.valore).join(","), "3,4,5", "le ultime tre, non le prime");
    eq(r.tagliate, 2, "e le due cadute si dichiarano");
  });
}

/* ══ LA PRODUZIONE DEL GIORNO, PER UNITÀ E PER TURNO ════════════════════
   `totaliProduzione` somma quanto è uscito dalla cava. La regola che va
   difesa è scritta anche nell'interfaccia: **tonnellate e metri cubi restano
   separati**. Sommarli darebbe un numero che non è né l'uno né l'altro, e che
   sembrerebbe comunque plausibile — la categoria peggiore.

   E la produzione **non dichiarata** non è zero: un rapportino senza quantità
   semplicemente non partecipa, invece di tirare giù la media. */
{
  const tp = campo.totaliProduzione;
  const rap = (turno, prodQta, prodUnita) => ({ turno, prodQta, prodUnita });

  test("⛔ produzione: tonnellate e metri cubi NON si sommano fra loro", () => {
    const r = tp([rap("Mattino", 100, "t"), rap("Mattino", 40, "m³")]);
    eq(r.perUnita.t, 100, "cento tonnellate");
    eq(r.perUnita["m³"], 40, "e quaranta metri cubi, separati");
  });
  test("produzione: i turni si sommano fra loro, unità per unità", () => {
    const r = tp([rap("Mattino", 100, "t"), rap("Pomeriggio", 50, "t")]);
    eq(r.perUnita.t, 150, "centocinquanta in giornata");
    eq(r.perTurno.length, 2, "e due turni distinti");
  });
  test("⛔ produzione: un rapportino senza quantità non conta come zero", () => {
    /* zero abbasserebbe la media di giornata; «non dichiarata» invece non
       partecipa, ed è la verità */
    const r = tp([rap("Mattino", 100, "t"), rap("Pomeriggio", null, "t")]);
    eq(r.perUnita.t, 100, "resta cento");
    eq(r.perTurno.length, 1, "e il turno senza produzione non compare fra i totali");
  });
  test("produzione: una quantità negativa o zero non è una produzione", () => {
    eq(Object.keys(tp([rap("Mattino", 0, "t"), rap("Sera", -5, "t")]).perUnita).length, 0,
       "nessun totale da dichiarare");
  });
  test("produzione: i turni escono nell'ordine della giornata, non alfabetico", () => {
    const r = tp([rap("Sera", 10, "t"), rap("Mattino", 20, "t")]);
    eq(r.perTurno[0].turno, "Mattino", "prima il mattino, anche se è arrivato dopo");
  });
  test("produzione: un turno non compilato finisce sotto «Senza turno»", () => {
    const r = tp([rap("", 10, "t")]);
    eq(r.perTurno[0].turno, "Senza turno", "detto, non nascosto");
  });
}

/* ══ L'IMPORT DAL SISMOGRAFO: LEGGERE IL FILE PRIMA DI FIDARSENE ════════
   `proponiMappa` indovina quale colonna è data, ora e valore; `preparaLetture`
   applica quella scelta e restituisce **una voce per ogni riga del file**,
   buona o scartata che sia. È il gemello di `unisciLetture`, e sta a monte:
   qui si decide *cosa* entra nella serie storica che finisce nel report per
   l'ente.

   Le regole che valgono il lavoro:

   · **nessuna riga sparisce in silenzio.** Ogni riga torna indietro con `ok` e,
     se scartata, con il motivo scritto in italiano. Un import muto è il modo
     migliore per perdere dati senza accorgersene: nessun errore, nessun
     avviso, solo una serie storica più corta di quella che si è caricata;
   · **il numero di riga è quello del FILE**, intestazione compresa. Chi legge
     «riga 5» va a cercarla nel foglio: se contassimo le righe di dati, la
     riga 5 dell'anteprima sarebbe la 6 del file e l'utente correggerebbe la
     cella sbagliata;
   · **due numeri di due cifre si leggono GIORNO/MESE**, mai mese/giorno. Su
     `07/12/2026` la differenza fra le due letture è di cinque mesi, su una
     data che va su un documento;
   · **una data impossibile si scarta, non si "corregge"**. Il 31/02 non
     diventa il 3 marzo: diventa una riga rossa con scritto perché. */
{
  const pl = sentinella.preparaLetture;
  const M = { colData: 0, colOra: -1, colValore: 2 };

  test("⛔ import: nessuna riga sparisce, ognuna torna col suo motivo", () => {
    const r = pl([
      ["12/07/2026", "", "2,5"],
      ["12/07/2026", "", ""],
      ["", "", "1"],
      ["12/07/2026", "", "abc"],
    ], M);
    eq(r.length, 4, "quattro righe dentro, quattro voci fuori");
    eq(r.map((x) => x.ok).join(","), "true,false,false,false", "una buona e tre scartate");
    eq(r.filter((x) => !x.ok).every((x) => x.motivo !== ""), true, "e ognuna dice perché");
  });
  test("⛔ import: il numero di riga è quello del file, intestazione compresa", () => {
    /* l'utente va a cercare «riga 2» nel foglio: se contassimo le righe di
       dati correggerebbe la cella sbagliata */
    const r = pl([["Data", "Ora", "PPV"], ["", "", "1"]], { ...M, conIntestazione: true });
    eq(r.length, 1, "l'intestazione non è un dato");
    eq(r[0].riga, 2, "ma la riga scartata è la 2 del file, non la 1");
  });
  test("⛔ import: 07/12/2026 è il 7 dicembre (giorno/mese), non il 12 luglio", () => {
    eq(pl([["07/12/2026", "", "1"]], M)[0].data, "2026-12-07", "regola italiana, dichiarata anche a schermo");
  });
  test("⛔ import: una data impossibile si scarta, non si «corregge»", () => {
    const r = pl([["31/02/2026", "", "1"]], M)[0];
    eq(r.data, "", "il 31 febbraio non diventa il 3 marzo");
    eq(r.motivo, "data non riconosciuta", "e lo dice");
  });
  test("import: data e ora nella stessa cella si leggono lo stesso", () => {
    /* molti strumenti scrivono «12/07/2026 10:30» in una casella sola */
    const r = pl([["12/07/2026 10:30", "", "2,5"]], M)[0];
    eq(r.data, "2026-07-12", "la data");
    eq(r.ora, "10:30", "e l'ora, senza chiedere una colonna che non c'è");
  });
  test("⛔ import: se la colonna dell'ora è vuota, l'ora si cerca nella cella della data", () => {
    /* il caso vero: il file scrive «12/07/2026 08:00» nella cella della data
       E ha una colonna Ora che per quelle righe è vuota. Prima l'ora veniva
       buttata, e allora due misure dello stesso giorno con lo stesso valore
       avevano la STESSA firma (data + ora + valore): la seconda spariva come
       doppione, e l'interfaccia annunciava «1 doppione scartato» — una frase
       sicura e non vera, su una serie storica che va all'ente */
    const r = pl([["12/07/2026 08:00", "", "0,5"], ["12/07/2026 14:00", "", "0,5"]],
                 { colData: 0, colOra: 1, colValore: 2 });
    eq(r.map((x) => x.ora).join(","), "08:00,14:00", "le due ore ci sono");
    const buone = r.filter((x) => x.ok).map((x) => ({ data: x.data, valore: x.valore, ora: x.ora }));
    const u = sentinella.unisciLetture([], buone);
    eq(u.aggiunte, 2, "e restano due misure");
    eq(u.duplicati, 0, "nessun doppione da annunciare");
  });
  test("import: la colonna dell'ora scelta vince su quella scritta nella data", () => {
    /* la ricerca nella cella della data è un RIPIEGO, non una sovrascrittura:
       se l'utente ha indicato dove sta l'ora, quella è l'ora */
    const r = pl([["12/07/2026 08:00", "14:30", "0,5"]], { colData: 0, colOra: 1, colValore: 2 })[0];
    eq(r.ora, "14:30", "quella della colonna");
  });
  test("import: la notazione scientifica dello strumento è un numero", () => {
    /* già costata una volta in questo progetto: gli export delle macchine
       scrivono 1.2e-3, e irrigidire il lettore fa sparire quelle righe */
    eq(pl([["12/07/2026", "", "1.2e-3"]], M)[0].valore, 0.0012, "0,0012 mm/s");
  });
  test("⛔ import: «manca» e «non è un numero» sono due motivi diversi", () => {
    /* suggeriscono due azioni diverse: la prima cella è da compilare, la
       seconda da correggere */
    eq(pl([["12/07/2026", "", ""]], M)[0].motivo, "valore mancante", "vuota");
    eq(pl([["12/07/2026", "", "n.d."]], M)[0].motivo, "valore non numerico", "scritta male");
  });
  test("import: un valore negativo non è una misura", () => {
    eq(pl([["12/07/2026", "", "-1"]], M)[0].motivo, "valore negativo", "una PPV negativa non esiste");
  });
  test("⛔ import: lo zero è una misura buona, non un dato mancante", () => {
    /* il fondo scala di una giornata senza volate è zero: scartarlo
       toglierebbe dal report proprio i giorni tranquilli */
    const r = pl([["12/07/2026", "", "0"]], M)[0];
    eq(r.ok, true, "accettata");
    eq(r.valore, 0, "e vale zero");
  });
  test("import: senza righe non si inventa niente", () => {
    eq(pl([], M).length, 0, "vuoto");
    eq(pl(null, null).length, 0, "e nemmeno con la mappa mancante");
  });

  const pm = sentinella.proponiMappa;
  test("mappa: l'intestazione dice quale colonna è quale", () => {
    eq(pm([["Data", "Time", "LAeq"], ["12/07/2026", "10:30", "61,2"]], true),
       { colData: 0, colOra: 1, colValore: 2 }, "data, ora e valore riconosciuti");
  });
  test("⛔ mappa: una colonna non fa due mestieri", () => {
    /* «Data/Ora» contiene sia «data» sia «ora»: senza l'esclusione finirebbe
       proposta per tutt'e due, e l'ora verrebbe letta due volte al posto del
       valore */
    const m = pm([["Data/Ora", "PPV"], ["12/07/2026 10:30", "2,5"]], true);
    eq(m.colData, 0, "è la data");
    eq(m.colOra !== m.colData, true, "e non è anche l'ora");
    eq(m.colValore, 1, "il valore è l'altra");
  });
  test("mappa: senza intestazione si va a colpo d'occhio sui dati", () => {
    /* prima colonna che sembra una data, ultima colonna numerica come valore */
    const m = pm([["2,5", "12/07/2026"]], false);
    eq(m.colData, 1, "la data è dove c'è una data, non dove capita");
    eq(m.colValore, 0, "e il valore è l'altra");
  });
  test("mappa: un'intestazione che non dice niente non blocca la proposta", () => {
    const m = pm([["A", "B", "C"], ["12/07/2026", "10:30", "2,5"]], true);
    eq(m.colData, 0, "ripiega sui dati");
    eq(m.colValore, 2, "e prende l'ultima numerica");
  });
}

/* ══ IL PROGRAMMA DI MONITORAGGIO: «SONO IN REGOLA CON LE MISURE?» ══════
   L'autorizzazione dice ogni quanto va misurato ogni punto. Queste funzioni
   rispondono alla domanda che l'azienda si fa davvero — *sono indietro?* — e
   accendono l'allerta nel quadro. Sbagliare qui non produce un numero storto:
   produce un **verde tranquillo su una misura che l'ente si aspettava**.

   Le regole bloccate:

   · **si riparte dall'ultima misura VERA, non da quella prevista.** Misura dei
     7 giorni fatta all'undicesimo → la prossima cade all'undicesimo + 7. È lo
     stesso principio del tagliando in Flotta, ed è quello che impedisce al
     ritardo di accumularsi in silenzio;
   · **la tolleranza separa il giallo dal rosso, e il confine è preciso**:
     scaduta da *tolleranza* giorni è ancora «da fare»; il giorno dopo è «in
     ritardo». Un confine spostato di uno cambia il colore di una tessera;
   · **«mai misurato» è un avviso, non un allarme**: può essere un punto appena
     creato, e un rosso che non serve insegna a ignorare i rossi;
   · **una riga che punta a un punto sparito resta visibile.** Sparire in
     silenzio toglierebbe dall'elenco proprio l'obbligo che nessuno sta più
     seguendo;
   · **l'ordine è l'urgenza, non l'alfabeto**: prima il ritardo più lungo. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const punto = (id, nome, ...date) => ({ id, nome, letture: date.map((d) => ({ data: d, valore: 1 })) });
  const riga = (o) => ({ monitoraggioId: "m1", ogniGiorni: 7, tolleranzaGiorni: 3, ...o });
  const stato = (r, m) => sentinella.statoRigaProgramma(r, m, OGGI);

  test("programma: la prossima misura si conta dall'ultima fatta", () => {
    const s = stato(riga(), punto("m1", "Casa", "2026-07-29"));
    eq(s.prossima, "2026-08-05", "ultima + sette giorni");
    eq(s.stato, "in-regola", "e per ora è in regola");
    eq(s.label, "Fra 5 giorni", "detto in giorni, non in date da tradurre");
  });
  test("⛔ programma: si riparte dalla misura VERA, non da quella prevista", () => {
    /* misura dei 7 giorni fatta all'undicesimo: la prossima cade
       all'undicesimo + 7, altrimenti ogni ritardo si somma al successivo e
       dopo cinque giri il punto è indietro di un mese col semaforo verde */
    const s = stato(riga({ dal: "2026-07-01" }), punto("m1", "Casa", "2026-07-12"));
    eq(s.prossima, "2026-07-19", "dal 12, non dall'8 che era la scadenza teorica");
  });
  test("⛔ programma: scaduta da quanto vale la tolleranza è ancora «da fare»", () => {
    const s = stato(riga(), punto("m1", "Casa", "2026-07-21"));   // prossima 28/07, oggi 31
    eq(s.stato, "da-fare", "tre giorni di ritardo, tolleranza tre");
    eq(s.cls, "warn", "giallo");
    eq(s.label, "Da fare da 3 giorni", "e si dice da quanto");
  });
  test("⛔ programma: il giorno dopo la tolleranza diventa «in ritardo»", () => {
    const s = stato(riga(), punto("m1", "Casa", "2026-07-20"));   // prossima 27/07, oggi 31
    eq(s.stato, "in-ritardo", "quattro giorni, tolleranza tre");
    eq(s.cls, "danger", "rosso");
    eq(s.label, "In ritardo di 4 giorni", "e si dice di quanto");
  });
  test("programma: scaduta oggi si dice «Da fare oggi», non «da 0 giorni»", () => {
    eq(stato(riga(), punto("m1", "Casa", "2026-07-24")).label, "Da fare oggi", "in italiano");
  });
  test("⛔ programma: «mai misurato» è un avviso, non un allarme", () => {
    /* può essere un punto appena creato: un rosso che non serve insegna a
       ignorare i rossi */
    const s = stato(riga(), punto("m1", "Casa"));
    eq(s.stato, "mai", "mai misurato");
    eq(s.cls, "warn", "giallo, non rosso");
    eq(s.maiMisurato, true, "e la pagina lo sa senza rileggere le letture");
  });
  test("programma: senza letture si parte dalla data di inizio, se c'è", () => {
    const s = stato(riga({ dal: "2026-07-01" }), punto("m1", "Casa"));
    eq(s.stato, "in-ritardo", "l'obbligo è partito il primo, la prima misura era l'8");
  });
  test("programma: una riga sospesa non è né in regola né in ritardo", () => {
    const s = stato(riga({ attivo: false }), punto("m1", "Casa", "2026-01-01"));
    eq(s.stato, "sospesa", "sospesa");
    eq(s.cls, "", "e niente semaforo: non chiede niente a nessuno");
  });
  test("programma: senza frequenza non si finge una scadenza", () => {
    const s = stato(riga({ ogniGiorni: 0 }), punto("m1", "Casa", "2026-01-01"));
    eq(s.stato, "senza-frequenza", "manca il dato, e si chiede");
    eq(s.prossima, null, "invece di inventare una data");
  });
  test("⛔ programma: l'ultima misura è quella più recente per data E ora", () => {
    const m = { letture: [
      { data: "2026-07-30", ora: "18:00", valore: 9 },
      { data: "2026-07-30", ora: "08:00", valore: 1 },
      { data: "2026-07-29", valore: 5 }] };
    eq(sentinella.ultimaLettura(m).valore, 9, "le 18, non l'ultima riga dell'elenco");
  });
  test("programma: una lettura senza valore leggibile non è l'ultima misura", () => {
    const m = { letture: [{ data: "2026-07-30", valore: "boh" }, { data: "2026-07-29", valore: 5 }] };
    eq(sentinella.ultimaLettura(m).data, "2026-07-29", "l'ultima buona");
  });

  const prog = [riga({ monitoraggioId: "m1" }), riga({ monitoraggioId: "m2" }), riga({ monitoraggioId: "sparito" })];
  const punti = [punto("m1", "Casa Rossi", "2026-07-01"), punto("m2", "Aaa scuola", "2026-07-10")];

  test("⛔ programma: l'ordine è l'urgenza, non l'alfabeto", () => {
    const v = sentinella.programmaEsteso(prog, punti, OGGI);
    eq(v[0].nome, "Casa Rossi", "23 giorni di ritardo prima di 14, anche se viene dopo nell'alfabeto");
    eq(v[1].nome, "Aaa scuola", "poi il ritardo più corto");
  });
  test("⛔ programma: la riga di un punto sparito resta visibile", () => {
    /* sparire in silenzio toglierebbe dall'elenco proprio l'obbligo che
       nessuno sta più seguendo */
    const v = sentinella.programmaEsteso(prog, punti, OGGI);
    eq(v.length, 3, "tre righe dentro, tre fuori");
    eq(v[2].nome, "Punto non più in elenco", "detto, non nascosto");
  });
  test("programma: il riepilogo conta tutte le righe, nessuna esclusa", () => {
    const r = sentinella.riepilogoProgramma(prog, punti, OGGI);
    eq(r.totale, 3, "il totale è il numero di righe");
    eq(r.inRitardo + r.daFare + r.mai + r.sospese + r.senzaFrequenza + r.inRegola, r.totale,
       "e la somma degli stati torna: nessuna riga cade fuori dal conto");
  });
  test("⛔ programma: nelle allerte finisce solo ciò che chiede un'azione", () => {
    const sospese = [riga({ monitoraggioId: "m1", attivo: false })];
    eq(sentinella.allerteProgramma(sospese, punti, OGGI).length, 0, "una riga sospesa non allerta nessuno");
    const a = sentinella.allerteProgramma(prog, punti, OGGI);
    eq(a.length, 3, "le altre tre sì");
    eq(a[0].categoria, "programma", "stessa forma delle allerte del quadro");
    eq(a[0].gravita, "danger", "il ritardo è rosso");
    eq(a[2].gravita, "warn", "il mai misurato è giallo");
  });
  test("programma: l'allerta dice ogni quanto e da quando non si misura", () => {
    const a = sentinella.allerteProgramma(prog, punti, OGGI)[0];
    eq(a.dettaglio.includes("ogni settimana"), true, "la frequenza in parole");
    eq(a.dettaglio.includes("01/07/2026"), true, "e la data dell'ultima misura");
  });
  test("programma: senza nessuna misura l'allerta lo scrive, non lascia il vuoto", () => {
    const a = sentinella.allerteProgramma([riga({ monitoraggioId: "sparito" })], punti, OGGI)[0];
    eq(a.dettaglio.includes("nessuna misura registrata"), true, "detto in italiano");
  });

  test("programma: la frequenza si dice in parole quando ha un nome", () => {
    eq(sentinella.etichettaFrequenza(30), "ogni mese", "trenta giorni");
    eq(sentinella.etichettaFrequenza(7), "ogni settimana", "sette");
    eq(sentinella.etichettaFrequenza(45), "ogni 45 giorni", "e quando un nome non c'è si dicono i giorni");
    eq(sentinella.etichettaFrequenza(0), "frequenza non impostata", "zero non è una frequenza");
  });
  test("⛔ programma: il conto dei giorni non inciampa nell'ora legale", () => {
    /* il 29 marzo 2026 l'ora legale toglie un'ora: contando in ora locale la
       somma scivolerebbe di un giorno, e la scadenza cadrebbe il giorno prima */
    eq(sentinella.piuGiorni("2026-03-28", 1), "2026-03-29", "il giorno del cambio");
    eq(sentinella.piuGiorni("2026-03-28", 2), "2026-03-30", "e quello dopo");
    eq(sentinella.piuGiorni("2026-02-28", 1), "2026-03-01", "il 2026 non è bisestile");
    eq(sentinella.piuGiorni("boh", 1), "", "e una data che non è una data non diventa oggi");
  });
}

/* ══ DAL SUPERAMENTO ALL'AZIONE: «E VOI COSA AVETE FATTO?» ══════════════
   È la domanda che l'ente fa dopo un superamento, e il ponte
   Sentinella → Scudo esiste per avere una risposta scritta. Le funzioni qui
   sotto decidono **quali superamenti sono ancora aperti**, **quali azioni
   appartengono a quale superamento** e **che colore ha la risposta**.

   Le regole bloccate:

   · **senza soglia non esiste superamento.** Non se ne inventa una: un punto
     senza soglia impostata non è né dentro né fuori, e dichiararlo fuori
     riempirebbe il quadro di rossi che nessuno può chiudere;
   · **un punto senza storico è comunque un superamento**, con la voce
     «valore-corrente» invece di una data. Farlo sparire perché non c'è una
     data da citare toglierebbe dall'elenco un superamento vero;
   · **«nessuna azione» è ROSSO**, non grigio. La casella vuota è esattamente
     la risposta che l'ente non vuole sentire;
   · **le azioni si legano al preciso superamento**, non solo al punto: quella
     chiusa a marzo non deve far sembrare gestito quello di luglio. */
{
  const punto = (o) => ({ id: "p1", nome: "Casa Rossi", tipo: "vibrazioni", valore: 12, soglia: 10, letture: [], ...o });

  test("⛔ superamenti: l'ultima lettura oltre è la più RECENTE, non la più alta", () => {
    /* la domanda è «quando è successo l'ultima volta», non «quanto è andata
       male la peggiore». Il caso è costruito perché le due risposte siano
       DIVERSE: il picco (50) è del 1° luglio, l'ultimo superamento (12) è del
       3. Con dati in cui coincidono la prova non proverebbe niente — ed è
       proprio così che era scritta la prima volta. */
    const l = sentinella.ultimaLetturaOltre({ letture: [
      { data: "2026-07-01", valore: 50 },
      { data: "2026-07-05", valore: 3 },
      { data: "2026-07-03", valore: 12 }] }, 10);
    eq(l.data, "2026-07-03", "l'ultima che ha superato, non la più alta");
    eq(l.valore, 12, "e con il suo valore, non col picco");
  });
  test("superamenti: «oltre» vuol dire anche «uguale», come il semaforo", () => {
    eq(sentinella.ultimaLetturaOltre({ letture: [{ data: "2026-07-01", valore: 10 }] }, 10).valore, 10,
       "il valore uguale alla soglia è già un superamento");
  });
  test("⛔ superamenti: senza soglia valida non se ne inventa una", () => {
    eq(sentinella.ultimaLetturaOltre({ letture: [{ data: "2026-07-01", valore: 99 }] }, 0), null, "soglia zero");
    eq(sentinella.superamentiAperti([punto({ soglia: null })], []).length, 0, "e il punto non finisce fra gli aperti");
  });
  test("⛔ superamenti: un punto senza storico è comunque un superamento", () => {
    /* il valore digitato a mano sulla scheda: la voce esiste, solo senza una
       data da citare */
    const s = sentinella.superamentiAperti([punto({})], [])[0];
    eq(s.voce, "valore-corrente", "la voce lo dice");
    eq(s.data, "", "e la data resta vuota invece di essere inventata");
  });
  test("superamenti: con lo storico la voce è la data della lettura che l'ha causato", () => {
    const s = sentinella.superamentiAperti([punto({ letture: [
      { data: "2026-07-01", valore: 11 },
      { data: "2026-07-09", valore: 12 },
      { data: "2026-07-05", valore: 4 }] })], [])[0];
    eq(s.voce, "2026-07-09", "l'ultima volta che è andata oltre");
  });
  test("⛔ superamenti: l'ordine è la gravità, non il nome", () => {
    const l = sentinella.superamentiAperti([
      punto({ id: "p1", nome: "Casa Rossi", valore: 12, soglia: 10 }),
      punto({ id: "p2", nome: "Aaa scuola", valore: 30, soglia: 10 })], []);
    eq(l[0].nome, "Aaa scuola", "tre volte la soglia prima di una volta e due decimi");
    eq(l.length, 2, "e sono due");
  });
  test("superamenti: quello che sta sotto soglia non è aperto", () => {
    eq(sentinella.superamentiAperti([punto({ valore: 2, soglia: 10 })], []).length, 0, "niente da chiudere");
  });

  test("⛔ ponte: le azioni si legano al preciso superamento, non solo al punto", () => {
    /* quella chiusa a marzo non deve far sembrare gestito quello di luglio */
    const az = [
      { origineTipo: sentinella.ORIGINE_SUPERAMENTO, origineId: "p5", origineVoce: "2026-07-09", stato: "aperta" },
      { origineTipo: sentinella.ORIGINE_SUPERAMENTO, origineId: "p5", origineVoce: "2026-03-01", stato: "chiusa" },
      { origineTipo: sentinella.ORIGINE_RECLAMO, origineId: "p5", origineVoce: "2026-07-09", stato: "chiusa" }];
    eq(sentinella.azioniDiOrigine(az, sentinella.ORIGINE_SUPERAMENTO, "p5", "2026-07-09").length, 1, "una sola è di questo");
    eq(sentinella.azioniDiOrigine(az, sentinella.ORIGINE_SUPERAMENTO, "p5").length, 2, "senza voce tornano tutte del punto");
    eq(sentinella.azioniDiOrigine(az, sentinella.ORIGINE_SUPERAMENTO, "").length, 0, "e senza id non si tira su niente");
  });
  test("⛔ ponte: «nessuna azione» è rosso, non grigio", () => {
    /* la casella vuota è esattamente la risposta che l'ente non vuole sentire */
    const p = sentinella.statoPonte([]);
    eq(p.cls, "danger", "rosso");
    eq(p.label, "Nessuna azione", "detto in chiaro");
  });
  test("ponte: tutte chiuse è verde, e si dice al singolare quando è una", () => {
    eq(sentinella.statoPonte([{ stato: "chiusa" }]).cls, "ok", "verde");
    eq(sentinella.statoPonte([{ stato: "chiusa" }]).label, "Azione chiusa", "una sola, non «1 azioni»");
    eq(sentinella.statoPonte([{ stato: "chiusa" }, { stato: "chiusa" }]).label, "2 azioni chiuse", "due");
  });
  test("ponte: una aperta su due resta gialla e dice quante ne mancano", () => {
    const p = sentinella.statoPonte([{ stato: "chiusa" }, { stato: "aperta" }]);
    eq(p.cls, "warn", "giallo: qualcosa è stato fatto, ma non è finita");
    eq(p.label, "1 azione da chiudere", "e si dice quante");
  });
  test("ponte: se sono tutte in corso si dice «in corso», non «da chiudere»", () => {
    eq(sentinella.statoPonte([{ stato: "in-corso" }]).label, "Azione in corso", "qualcuno ci sta lavorando");
  });

  test("⛔ bozza: l'azione porta con sé da dove viene", () => {
    /* senza la provenienza, in Scudo resterebbe un compito senza storia, e
       la domanda dell'ente non avrebbe una risposta collegata al fatto */
    const s = sentinella.superamentiAperti([punto({ id: "p5", nome: "Con storia",
      letture: [{ data: "2026-07-09", valore: 12 }] })], [])[0];
    const b = sentinella.bozzaAzioneSuperamento(s);
    eq(b.origineApp, sentinella.PONTE_APP, "l'app di partenza");
    eq(b.origineTipo, sentinella.ORIGINE_SUPERAMENTO, "il tipo di fatto");
    eq(b.origineId, "p5", "il punto");
    eq(b.origineVoce, "2026-07-09", "e il preciso superamento, non solo il punto");
    eq(b.stato, "aperta", "nasce aperta");
  });
  test("bozza: la nota cita il valore misurato e la soglia applicata", () => {
    const s = sentinella.superamentiAperti([punto({ id: "p5", nome: "Con storia",
      letture: [{ data: "2026-07-09", valore: 12 }] })], [])[0];
    const n = sentinella.bozzaAzioneSuperamento(s).origineNota;
    eq(n.includes("misurato 12 mm/s"), true, "quanto si è misurato");
    eq(n.includes("soglia applicata 10 mm/s"), true, "e contro cosa");
    eq(n.includes("09/07/2026"), true, "e quando, in italiano");
  });
  test("bozza: senza un superamento vero non si prepara niente", () => {
    eq(sentinella.bozzaAzioneSuperamento({ nome: "x" }), null, "manca l'id");
    eq(sentinella.bozzaAzioneSuperamento(null), null, "e manca tutto");
  });
}

/* ══ IL REFERTO DEL SISMOGRAFO CHE TARA LA LEGGE DI SITO ════════════════
   Da queste volate Genesi ricava K e β, e da K e β dipendono **le distanze di
   sicurezza**. È il posto in tutto l'ecosistema dove un numero finto fa più
   danno: non produce un report brutto, produce una distanza di sicurezza
   sbagliata.

   Il vincolo più importante è uno solo, ed è quello che queste prove
   difendono: **una volata PREVISTA non diventa mai un referto.** Nemmeno se
   porta una PPV prevista, nemmeno se ha distanza e carica. Se dentro la
   regressione entrasse un valore *previsto* al posto di uno *misurato*, la
   legge di sito confermerebbe sé stessa e le distanze uscirebbero da un
   calcolo circolare — un numero che sembra misurato e non lo è. */
{
  const vol = (o) => ({ id: "v1", data: "2026-07-10", fronte: "Fronte A",
    distanzaRicettore: 200, kgMaxRitardo: 50, ppvMisurata: 3.2, ppvFonte: "strumento",
    ppvPuntoId: "p1", ppvPuntoNome: "Casa Rossi", ppvData: "2026-07-10", ppvOra: "10:30", ...o });

  test("referto: una volata completa è pronta, con i suoi tre numeri", () => {
    const r = sentinella.refertoDaVolata(vol());
    eq(r.pronto, true, "pronta");
    eq(r.motivi.length, 0, "niente da chiedere");
    eq(r.ppv, 3.2, "la PPV misurata");
  });
  test("⛔ referto: una volata PREVISTA non è un referto, nemmeno con tutto il resto", () => {
    /* il vincolo T9: con una PPV prevista dentro la regressione, la legge di
       sito confermerebbe sé stessa e le distanze di sicurezza uscirebbero da
       un calcolo circolare */
    const r = sentinella.refertoDaVolata(vol({ stato: "prevista" }));
    eq(r.pronto, false, "non è un referto");
    eq(r.ppv, null, "e la PPV che porta con sé non viene nemmeno letta");
  });
  test("⛔ referto: alla volata prevista si chiede UNA cosa sola: che sia stata sparata", () => {
    /* elencarle anche gli altri dati mancanti chiederebbe di riempire una PPV
       che non può ancora esistere */
    const r = sentinella.refertoDaVolata(vol({ stato: "prevista", ppvMisurata: 0, distanzaRicettore: 0, kgMaxRitardo: 0 }));
    eq(r.motivi.join(","), "prevista", "un motivo solo, e dice il fatto che manca");
  });
  test("referto: quello che manca si dice tutto insieme, non uno alla volta", () => {
    const r = sentinella.refertoDaVolata({ id: "v9", data: "2026-01-01" });
    eq(r.motivi.join(","), "ppv,distanza,carica", "tre mancanze, tre motivi");
  });
  test("⛔ referto: una volata vecchia non porta una PPV finta", () => {
    /* registrata prima che quei campi esistessero: null, non zero */
    eq(sentinella.ppvDiVolata({ id: "v" }), null, "niente PPV");
    eq(sentinella.ppvDiVolata({ ppvMisurata: 0 }), null, "e zero non è una misura");
    eq(sentinella.ppvDiVolata({ ppvMisurata: -1 }), null, "nemmeno un valore negativo");
  });
  test("⛔ referto: la PPV a mano non si porta dietro una provenienza che non ha", () => {
    /* «trascritta dal referto» significa che il punto di misura non lo
       sappiamo: tenerne uno vecchio farebbe risalire alla casa sbagliata */
    const c = sentinella.campiPpvVolata(3.25, { fonte: "manuale", puntoId: "p1", punto: "Casa", ora: "10:30", data: "2026-07-10" });
    eq(c.ppvPuntoId, "", "nessun punto");
    eq(c.ppvPuntoNome, "", "nessun nome");
    eq(c.ppvOra, "", "nessuna ora");
    eq(c.ppvData, "2026-07-10", "la data invece resta: quella la sappiamo");
  });
  test("referto: la PPV dal sismografo tiene punto, nome e ora", () => {
    const c = sentinella.campiPpvVolata(3.25678, { fonte: "strumento", puntoId: "p1", punto: "Casa", ora: "10:30", data: "2026-07-10" });
    eq(c.ppvPuntoNome, "Casa", "il punto");
    eq(c.ppvMisurata, 3.2568, "e il valore a quattro decimali, come lo strumento");
  });
  test("⛔ referto: togliere una PPV azzera anche la sua provenienza", () => {
    /* mai il valore senza la sua provenienza, e mai la provenienza senza il
       valore: resterebbe un numero che dice di venire da un punto che non l'ha
       mai misurato */
    const v = Object.values(sentinella.CAMPI_PPV_VUOTI);
    eq(v.length, 6, "sei campi");
    eq(v.every((x) => x === "" || x === 0), true, "e si azzerano tutti insieme");
  });
  test("referto: da dove viene la PPV si dice sempre con le stesse parole", () => {
    eq(sentinella.testoFontePpv(sentinella.ppvDiVolata(vol())), "sismografo · Casa Rossi · 10:30", "dal sismografo");
    eq(sentinella.testoFontePpv(sentinella.ppvDiVolata(vol({ ppvFonte: "manuale" }))),
       "trascritta a mano dal referto", "a mano");
    eq(sentinella.testoFontePpv(null), "", "e senza PPV non si scrive niente");
  });
  test("referto: il riferimento permette di risalire alla volata dalla riga della regressione", () => {
    eq(sentinella.riferimentoReferto(sentinella.refertoDaVolata(vol())),
       "Volata 10/07/2026 · Fronte A · Casa Rossi", "data, fronte e punto");
  });

  test("⛔ candidate: solo le letture di VIBRAZIONE di quel giorno", () => {
    const mons = [
      { id: "p1", nome: "Casa", tipo: "vibrazioni", unita: "mm/s",
        letture: [{ data: "2026-07-10", valore: 3.2, ora: "10:30" }, { data: "2026-07-10", valore: 5.1 }, { data: "2026-07-09", valore: 9 }] },
      { id: "p2", nome: "Rumore", tipo: "rumore", letture: [{ data: "2026-07-10", valore: 70 }] }];
    const c = sentinella.lettureVibrazioniDelGiorno(mons, "2026-07-10");
    eq(c.length, 2, "due: il rumore non è una PPV e il giorno prima non è quel giorno");
    eq(c[0].valore, 5.1, "e in cima la più alta, che è quella che conta per la conformità");
  });
  test("⛔ candidate: un punto che non misura in mm/s è marcato, non silenziato", () => {
    /* il numero c'è ma NON è una PPV: la scheda lo mostra a parte invece di
       farlo scegliere, e nasconderlo lascerebbe l'utente a chiedersi dove è
       finita la sua lettura */
    const c = sentinella.lettureVibrazioniDelGiorno(
      [{ id: "p3", nome: "Altro", tipo: "vibrazioni", unita: "dB", letture: [{ data: "2026-07-10", valore: 99 }] }],
      "2026-07-10");
    eq(c.length, 1, "c'è");
    eq(c[0].unitaOk, false, "ma è marcato come non utilizzabile come PPV");
  });
  test("candidate: senza una data vera non si propone niente", () => {
    eq(sentinella.lettureVibrazioniDelGiorno([], "boh").length, 0, "elenco vuoto");
  });

  test("⛔ registro: prima ciò su cui c'è da lavorare, poi il fatto più recente", () => {
    const reg = sentinella.refertiDaVolate([
      vol({ id: "a", data: "2026-07-01" }), vol({ id: "b", data: "2026-07-20" }),
      vol({ id: "c", data: "2026-07-15", ppvMisurata: 0 }), vol({ id: "d", stato: "prevista" })]);
    eq(reg.tutti.map((r) => r.id).join(","), "c,d,b,a", "le due incomplete davanti, poi le pronte dalla più recente");
    eq(reg.nPronti, 2, "due pronte");
    eq(reg.motivi.ppv, 1, "e il conto di cosa manca, per dirlo una volta sola");
    eq(reg.motivi.prevista, 1, "compresa quella ancora da sparare");
  });
  test("⛔ registro: sotto tre referti si dice quanti ne mancano, non «non si può»", () => {
    const reg = sentinella.refertiDaVolate([vol({ id: "a" }), vol({ id: "b", data: "2026-07-02" })]);
    eq(reg.abbastanza, false, "due non bastano");
    eq(reg.mancanoAlMinimo, 1, "e ne manca uno: è un numero, non un muro");
  });
  test("⛔ registro: senza escursione di distanza scalata la pendenza non è ricavabile", () => {
    /* tre volate identiche danno tre volte lo stesso punto: da lì passa
       qualunque retta, e la legge uscirebbe da un calcolo che non ha misurato
       niente. Meglio dirlo prima dell'export che dopo il rifiuto */
    const uguali = sentinella.refertiDaVolate([vol({ id: "a" }), vol({ id: "b" }), vol({ id: "c" })]);
    eq(uguali.escursione, 1, "nessuna escursione");
    const diverse = sentinella.refertiDaVolate([
      vol({ id: "a", distanzaRicettore: 100 }), vol({ id: "b", distanzaRicettore: 400 }), vol({ id: "e" })]);
    eq(Math.round(diverse.escursione * 100) / 100, 4, "quattro volte fra la più vicina e la più lontana");
  });
  test("registro: ogni motivo dice anche come si rimedia", () => {
    eq(sentinella.MOTIVI_REFERTO.every((m) => m.come && m.etichetta && m.breve), true,
       "un elenco di mancanze senza il rimedio lascia l'utente fermo");
    eq(sentinella.motivoReferto("boh").etichetta, "Dato mancante", "e un motivo sconosciuto non rompe la pagina");
  });
}

/* ══ «COME STA ANDANDO DOVE ABITA LA GENTE» ═════════════════════════════
   Il confronto fra il mese in corso e quello prima, per ogni punto collegato
   a un ricettore. La regola di onestà è scritta nel modulo e va difesa qui:
   **se le letture non bastano NON si inventa una linea** — si dice quante ce
   ne sono.

   Le due che contano di più:

   · **«nessuna misura» non è «zero mm/s».** Senza letture media, massimo e
     minimo restano `null`: uno zero lì significherebbe «è andato benissimo»
     su un mese in cui non si è misurato niente;
   · **non si confronta un mese con il nulla.** Con un mese vuoto la
     variazione non esiste: dichiararla −100 % darebbe un miglioramento
     inventato dall'assenza di dati, che è esattamente il numero che un'azienda
     vorrebbe leggere e che non deve trovare. */
{
  const punto = { id: "p1", nome: "Casa", tipo: "vibrazioni", letture: [
    { data: "2026-06-10", valore: 2 }, { data: "2026-06-20", valore: 4 },
    { data: "2026-07-05", valore: 6, ora: "14:00" }, { data: "2026-07-05", valore: 3, ora: "08:00" },
    { data: "2026-07-25", valore: 12 }] };
  const OGGI = new Date("2026-07-31T12:00:00");

  test("periodo: il mese finisce quando finisce davvero", () => {
    eq(sentinella.limitiMese(2026, 2).al, "2026-02-28", "febbraio normale");
    eq(sentinella.limitiMese(2028, 2).al, "2028-02-29", "e quello bisestile");
    eq(sentinella.limitiMese(2026, 12).al, "2026-12-31", "dicembre");
  });
  test("⛔ periodo: gli estremi sono compresi", () => {
    /* un intervallo che escludesse il primo o l'ultimo giorno toglierebbe
       silenziosamente due letture da ogni mese */
    eq(sentinella.lettureNelPeriodo(punto, "2026-06-10", "2026-06-20").map((x) => x.valore).join(","),
       "2,4", "la prima e l'ultima ci sono");
  });
  test("periodo: le letture dello stesso giorno restano in ordine di ora", () => {
    eq(sentinella.lettureNelPeriodo(punto, "2026-07-01", "2026-07-10").map((x) => x.valore).join(","),
       "3,6", "le 8 prima delle 14");
  });
  test("periodo: senza estremi si prende tutto, invece di niente", () => {
    eq(sentinella.lettureNelPeriodo(punto, "", "").length, 5, "cinque letture");
  });

  test("statistiche: media, massimo, minimo e superamenti del periodo", () => {
    const st = sentinella.statPeriodo(punto, "2026-07-01", "2026-07-31", 10);
    eq(st.n, 3, "tre letture");
    eq(st.media, 7, "media sette");
    eq(st.max, 12, "massimo dodici");
    eq(st.min, 3, "minimo tre");
    eq(st.superamenti, 1, "e un solo superamento della soglia");
  });
  test("⛔ statistiche: «nessuna misura» non è «zero»", () => {
    /* uno zero lì significherebbe «è andato benissimo» su un mese in cui non
       si è misurato niente */
    const st = sentinella.statPeriodo(punto, "2027-01-01", "2027-01-31", 10);
    eq(st.n, 0, "nessuna lettura");
    eq(st.media, null, "e la media non esiste");
    eq(st.max, null, "né il massimo");
  });
  test("⛔ statistiche: senza soglia non si contano superamenti", () => {
    eq(sentinella.statPeriodo(punto, "2026-07-01", "2026-07-31", 0).superamenti, 0,
       "non se ne inventa una per poter contare");
  });
  test("⛔ statistiche: ZERO SUPERAMENTI SU ZERO MISURE non è un buon risultato", () => {
    /* media e massimo dicevano già «non lo so» su un mese vuoto; i superamenti
       dicevano «0», ed è la cifra che si guarda per prima — in tabella restava
       l'unico numero della riga, accanto a due trattini, su un mese in cui
       nessuno ha misurato niente. */
    const vuoto = sentinella.statPeriodo(punto, "2027-01-01", "2027-01-31", 10);
    eq(vuoto.n, 0, "nessuna lettura nel periodo");
    eq(vuoto.superamenti, null, "e allora nemmeno i superamenti si possono contare");
    eq(sentinella.statPeriodo(punto, "2026-07-01", "2026-07-31", 10).superamenti, 1,
       "dove invece si è misurato, il conto resta un numero");
    eq(sentinella.statPeriodo(punto, "2026-07-01", "2026-07-31", 100).superamenti, 0,
       "e uno zero MISURATO resta uno zero: la differenza è fra «nessuno» e «nessuna misura»");
  });
  test("⛔ confronto: senza uno dei due mesi non c'è nemmeno una differenza di superamenti", () => {
    /* con due mesi vuoti la sottrazione faceva 0 − 0 = 0, cioè «nessun
       peggioramento» ricavato dal nulla; con un mese solo pieno faceva un
       numero che si spacciava per un confronto */
    const nessuno = sentinella.confrontoMesi({ letture: [] }, 10, OGGI);
    eq(nessuno.confrontabile, false, "non c'è niente da confrontare");
    eq(nessuno.deltaSuperamenti, null, "e quindi nessuna differenza da dichiarare");
    const soloUno = sentinella.confrontoMesi({ letture: [{ data: "2026-07-05", valore: 60 }] }, 10, OGGI);
    eq(soloUno.confrontabile, false, "il mese prima è vuoto");
    eq(soloUno.deltaSuperamenti, null, "un mese solo non fa un confronto");
    eq(sentinella.confrontoMesi(punto, 10, OGGI).deltaSuperamenti, 1,
       "con tutt'e due i mesi pieni la differenza si dice ancora");
  });
  test("⛔ un punto MAI MISURATO non ha un rapporto da mettere in classifica", () => {
    /* `ratio: null` non è un dettaglio: la lista dei punti ci ordina sopra
       «Criticità» e «Margine», e una sottrazione legge `null` come ZERO
       (`null - 0.9` fa −0,9). Se questo campo tornasse a essere 0, il punto mai
       misurato uscirebbe primo fra «i più tranquilli» e ultimo fra «i più
       critici»: in tutt'e due gli ordinamenti nel posto dei più sereni. */
    const st = sentinella.statoMisura({ valore: 0, soglia: 5, unita: "mm/s", letture: [] });
    eq(st.stato, "mai", "punto appena creato: nessuno ha misurato");
    eq(st.ratio, null, "e nessun rapporto valore/soglia da mettere in fila");
    eq(sentinella.statoMisura({ valore: 1, soglia: 5 }).ratio, 0.2, "dove c'è una misura il rapporto c'è");
  });
  test("⛔ priorità: sulla riga di un punto mai misurato non si scrive nessuna cifra di misura", () => {
    /* il badge diceva «Mai misurato» e il dettaglio accanto «0 mm/s / soglia 5»:
       lo zero con cui il punto NASCE letto come una misura. Due frasi opposte
       sulla stessa riga, e quella con la cifra è la sola che si guarda. */
    const p = sentinella.prioritaConformita(
      [{ nome: "Sismografo Sud", valore: 0, soglia: 5, unita: "mm/s", letture: [], nota: "appena installato" }],
      [], new Date(2026, 6, 21));
    eq(p.length, 1, "il punto compare fra le allerte (è la cosa da fare)");
    eq(p[0].badge, "Mai misurato", "col suo badge");
    ok(/nessuna misura registrata/.test(p[0].dettaglio), "e la riga lo dice a parole — era «" + p[0].dettaglio + "»");
    ok(!/\b0\s*mm\/s/.test(p[0].dettaglio), "senza nessun «0 mm/s» spacciato per misura");
    ok(/soglia 5/.test(p[0].dettaglio), "la soglia impostata invece è un dato vero e resta");
    ok(/appena installato/.test(p[0].dettaglio), "e la nota dell'utente resta dov'era");
  });

  test("⛔ confronto: non si confronta un mese con il nulla", () => {
    /* dichiarare −100 % darebbe un miglioramento inventato dall'assenza di
       dati: esattamente il numero che un'azienda vorrebbe leggere */
    const c = sentinella.confrontoMesi({ letture: [{ data: "2026-07-05", valore: 6 }] }, 10, OGGI);
    eq(c.confrontabile, false, "il mese prima è vuoto");
    eq(c.deltaPct, null, "quindi nessuna variazione");
    eq(c.deltaMedia, null, "e nessuna differenza di media");
  });
  test("confronto: con due mesi pieni la variazione si calcola e si dice in percento", () => {
    const c = sentinella.confrontoMesi(punto, 10, OGGI);
    eq(c.confrontabile, true, "confrontabile");
    eq(c.deltaMedia, 4, "quattro in più di media");
    eq(c.deltaPct, 133.3, "cioè +133,3 %");
    eq(c.deltaSuperamenti, 1, "e un superamento in più");
  });
  test("⛔ confronto: una media su UNA lettura sola viene dichiarata debole", () => {
    /* è un confronto legittimo ma fragile: nasconderlo farebbe prendere per
       tendenza quello che è un caso */
    const c = sentinella.confrontoMesi(
      { letture: [{ data: "2026-06-10", valore: 2 }, { data: "2026-07-05", valore: 6 }] }, 10, OGGI);
    eq(c.confrontabile, true, "confrontabile");
    eq(c.debole, true, "ma dichiarato debole");
    eq(sentinella.confrontoMesi(punto, 10, OGGI).debole, false, "con più letture no");
  });

  test("andamento: si guardano solo i punti collegati a quel ricettore", () => {
    const a = sentinella.andamentoRicettore(
      [{ ...punto, ricettoreId: "r1" }, { id: "p2", nome: "Altro", ricettoreId: "r2", letture: [] }],
      [{ id: "r1", nome: "Casa Rossi" }], "r1", { oggi: OGGI });
    eq(a.punti.length, 1, "uno solo è di questo ricettore");
    eq(a.ricettore.nome, "Casa Rossi", "e il ricettore si ritrova");
    eq(a.dal + "→" + a.al, "2026-02-01→2026-07-31", "sei mesi, mese in corso compreso");
  });
  test("⛔ andamento: sotto tre letture non si disegna una linea", () => {
    /* da due punti passa qualunque linea: mostrarla darebbe una tendenza che
       i dati non contengono */
    const a = sentinella.andamentoRicettore(
      [{ id: "p3", nome: "Poche", ricettoreId: "r1",
         letture: [{ data: "2026-07-01", valore: 1 }, { data: "2026-07-02", valore: 2 }] }],
      [{ id: "r1", nome: "X" }], "r1", { oggi: OGGI });
    eq(a.punti[0].n, 2, "due letture");
    eq(a.punti[0].abbastanza, false, "non bastano");
    eq(a.minLetture, 3, "e si dice qual è il minimo, invece di lasciare il vuoto");
  });
}

/* ══ «OGGI» È UNA SOLA COSA, E VIVE IN shared/ ══════════════════════════
   `oggiISO` era scritta **sei volte** nel progetto in **tre** versioni: cinque
   giuste e una — quella di Conti — che prendeva il giorno da `toISOString()`,
   cioè il giorno UTC. In Italia sono una o due ore avanti, e fra mezzanotte e
   le due (il turno di notte) quella versione data i documenti **al giorno
   prima**. Vedi `docs/RICERCA_GIORNO_LOCALE_202607.md`.

   Il test pretende l'**IDENTITÀ**, non il comportamento: due copie uguali oggi
   divergono domani senza che nessuno se ne accorga. È la stessa regola già
   costata una giornata con la convenzione sui numeri. */
{
  test("⛔ oggi: Campo ri-esporta la funzione di shared, non ne tiene una sua", () => {
    eq(campo.oggiISO === shell.oggiISO, true, "è la stessa funzione, non una copia che si comporta uguale");
  });
  test("⛔ oggi: e nemmeno Flotta, che ne aveva la settima copia", () => {
    /* l'ha trovata la regola 15 di run-stile.mjs, non una lettura del codice:
       si chiamava `oggiIso` e stava nel modulo dati */
    eq(flotta.oggiIso === shell.oggiISO, true, "stessa funzione, nome di sempre");
  });
  test("⛔ oggi: il giorno si legge dall'orologio LOCALE, non da quello di Greenwich", () => {
    /* mezzanotte e mezza del 2 giugno a Roma: `toISOString()` scriverebbe il
       1° giugno, e il rapportino del turno di notte finirebbe nel giorno prima */
    eq(shell.oggiISO(new Date(2026, 5, 2, 0, 30)), "2026-06-02", "il 2, non il 1°");
    eq(shell.oggiISO(new Date(2026, 0, 1, 0, 30)), "2026-01-01", "e a capodanno l'anno è quello nuovo");
  });
  test("⛔ oggi: il MESE di una data si legge nello stesso modo", () => {
    /* la chiave con cui si raggruppano i grafici: presa da `toISOString()`
       sposta ogni barra di un mese intero */
    eq(shell.meseLocale(new Date(2026, 4, 1)), "2026-05", "maggio è maggio, anche il primo giorno");
    eq(shell.meseLocale(new Date(2026, 0, 1)), "2026-01", "e gennaio è gennaio");
  });
  test("oggi: una data che non è una data non diventa oggi", () => {
    eq(shell.isoLocale("boh"), "", "stringa vuota, invece di un giorno inventato");
  });
  test("oggi: mezzogiorno e mezzanotte dello stesso giorno danno lo stesso giorno", () => {
    eq(shell.isoLocale(new Date(2026, 6, 31, 12, 0)), shell.isoLocale(new Date(2026, 6, 31, 0, 0)),
       "l'ora non sposta il calendario");
  });
}

/* ══ LA PROPOSTA DEL TAGLIANDO, E LO ZERO CHE NON ESISTE ════════════════
   Scegliendo un piano nel form, l'app propone a quante ore mettere il prossimo
   tagliando. Prima faceva `Math.round(+m.ore || 0) + p.ogniOre` e scriveva
   «X ha 0 ore: il tagliando è proposto a 500». Su un mezzo **senza contaore**
   quella frase asserisce un numero che il contatore non ha mai dato: non è
   imprecisa, è **falsa**. È il terzo `+null === 0` di questo progetto — dopo la
   base d'asta delle gare in Conti e la finestra del prossimo tagliando. */
{
  const pt = flotta.propostaTagliando;
  const p500 = flotta.pianoTagliando("500");

  test("proposta: con le ore note si somma il passo", () => {
    const r = pt("CAT 320", 5875, p500);
    eq(r.oreProposte, 6375, "5875 più cinquecento");
    eq(r.oreNote, true, "le ore si sanno");
    /* ⚠️ CORRETTA IL 02/08, e vale la pena tenere la storia.
       La prima stesura pretendeva «6.375» e cadeva; la seconda ne concluse che
       «in italiano 6375 si scrive senza il punto, la lingua raggruppa solo da
       cinque cifre in su». Mezza verità: è la preferenza CLDR per l'italiano
       (`minimumGroupingDigits: 2`), ma NON è quello che vede l'utente — misurato
       affiancando i motori, con le opzioni di serie **Chromium scrive «6.375» e
       Node «6375»**. La prova stava quindi blindando la stringa che si vede solo
       nelle prove. Adesso il raggruppamento è scritto esplicito nei moduli e i
       due motori dicono la stessa cosa: «6.375», che è anche la convenzione già
       scelta in Campo e in Sentinella. docs/MIGLIAIA_NODE_CONTRO_CHROMIUM.md */
    eq(r.testo.includes("il tagliando è proposto a 6.375"), true, "e lo dice come lo legge l'utente");
    eq((1234567).toLocaleString("it-IT", { useGrouping: true }), "1.234.567", "e i milioni col punto");
  });
  test("⛔ proposta: senza contaore NON si propone zero più il passo", () => {
    /* `+null` fa 0 e `Number.isFinite(0)` risponde true: è la forma sbagliata,
       non `Number.isFinite(x)` ma `Number.isFinite(+x)` su un valore nullo */
    for (const vuoto of [null, undefined, ""]) {
      const r = pt("CAT 320", vuoto, p500);
      eq(r.oreProposte, null, "niente da precompilare");
      eq(r.oreNote, false, "e si sa di non sapere");
      /* ⚠️ non basta cercare «0 ore»: la coda della frase contiene «+500 ore».
         Quello che non deve esistere è l'ASSERZIONE sul mezzo */
      eq(r.testo.includes("CAT 320 ha 0 ore"), false, "la frase «X ha 0 ore» non compare");
      eq(/\bha 0 ore\b/.test(r.testo), false, "in nessuna forma");
    }
  });
  test("⛔ proposta: senza contaore si dice cosa fare, non si lascia il vuoto", () => {
    const r = pt("CAT 320", null, p500);
    eq(r.testo.includes("non sappiamo le ore"), true, "si dichiara l'ignoranza");
    eq(r.testo.includes("programma il tagliando per data"), true, "e si offre la via d'uscita vera");
  });
  test("proposta: un contaore illeggibile vale come mancante, non come zero", () => {
    eq(pt("CAT 320", "boh", p500).oreProposte, null, "non è un numero");
    eq(pt("CAT 320", -5, p500).oreProposte, null, "e un contaore non va indietro");
  });
  test("proposta: senza mezzo scelto si spiega il piano e basta", () => {
    const r = pt("", 5875, p500);
    eq(r.oreProposte, null, "non c'è un mezzo a cui proporlo");
    eq(r.testo.includes("Tagliando 500 h"), true, "ma il piano si spiega lo stesso");
  });
  test("proposta: le ore si arrotondano solo per la proposta, mai in silenzio sul dato", () => {
    eq(pt("CAT 320", 5875.6, p500).oreProposte, 6376, "5876 più cinquecento");
  });
}

/* ══ DAL PROGETTO ALLO SPARO: LA CONFERMA DI UNA VOLATA ═════════════════
   Genesi manda a Sentinella una volata **prevista**. Dopo lo sparo qualcuno la
   conferma come eseguita, correggendo quello che in cava è andato diversamente
   dal progetto — fori saltati, carica ridotta, data spostata.

   Le due regole che reggono tutto il ponte:

   · **la previsione non si tocca.** I dati si correggono, il numero previsto
     resta scritto com'era: altrimenti il confronto previsto→misurato sarebbe un
     confronto con un numero **aggiustato dopo**, cioè con niente;
   · **una volata eseguita è un fatto avvenuto**, quindi la sua data non può
     stare nel futuro. È la stessa regola del registro a mano, per lo stesso
     motivo. */
{
  const cv = sentinella.confermaVolataEseguita;
  const OGGI = new Date("2026-07-31T12:00:00");
  const prevista = { id: "v1", stato: "prevista", data: "2026-07-20", fronte: "A",
    nFori: 20, kgTotali: 400, kgMaxRitardo: 50, distanzaRicettore: 200,
    ppvPrevista: 4.2, ppvPrevLimite: 5, ppvPrevNorma: "UNI 9916",
    ppvPrevFonte: "genesi-sito", airblastPrevisto: 120 };

  test("stato: il silenzio del registro significa ESEGUITA", () => {
    /* un registro compilato a mano è un elenco di fatti avvenuti: senza la
       colonna dello stato non si dà per «prevista» ciò che è già successo */
    eq(sentinella.statoVolata({}), "eseguita", "senza stato");
    eq(sentinella.statoVolata({ stato: "progetto" }), "prevista", "e i sinonimi si riconoscono");
    eq(sentinella.statoDaTesto("sparata"), "eseguita", "anche dall'altra parte");
    eq(sentinella.statoDaTesto("boh"), "", "una parola che non dice niente non decide");
  });
  test("⛔ conferma: la previsione NON viene toccata", () => {
    /* correggere anche il previsto renderebbe il confronto un confronto con un
       numero aggiustato dopo lo sparo */
    const r = cv(prevista, { nFori: "18", kgMaxRitardo: "45,5" }, OGGI);
    eq(r.ok, true, "la conferma va a buon fine");
    eq(Object.keys(r.campi).filter((k) => /^ppvPrev|^airblast|^ppvMisurata/.test(k)).length, 0,
       "nessun campo della previsione né della misura viene riscritto");
  });
  test("⛔ conferma: la data non può essere nel futuro", () => {
    const r = cv(prevista, { data: "2026-08-05" }, OGGI);
    eq(r.ok, false, "rifiutata");
    eq(r.errori[0].campo, "data", "e si dice quale campo");
    eq(r.errori[0].testo.includes("lasciala prevista"), true, "con la via d'uscita, non solo il no");
  });
  test("conferma: una volata già eseguita non si conferma due volte", () => {
    const r = cv({ ...prevista, stato: "eseguita" }, {}, OGGI);
    eq(r.ok, false, "niente da confermare");
    eq(r.errori[0].testo.includes("già registrata come eseguita"), true, "e lo dice in italiano");
  });
  test("⛔ conferma: un campo non toccato resta quello del progetto, uno svuotato vale zero", () => {
    /* svuotare è una CORREZIONE («quei fori non li abbiamo fatti»), non una
       dimenticanza: trattarla come «lascia com'era» ribalterebbe la volontà */
    eq(cv(prevista, {}, OGGI).campi.nFori, 20, "non toccato: resta il progetto");
    eq(cv(prevista, { nFori: "" }, OGGI).campi.nFori, 0, "svuotato: vale zero");
  });
  test("⛔ conferma: si dice che cosa è cambiato rispetto al progetto", () => {
    /* una correzione silenziosa su un documento è un problema: prima di
       salvare l'utente deve vedere che cosa sta cambiando */
    const c = cv(prevista, { nFori: "18", kgMaxRitardo: "45,5" }, OGGI).cambi;
    eq(c.map((x) => x.campo).join(","), "nFori,kgMaxRitardo", "due cose cambiate, due righe");
    eq(c[0].da + "→" + c[0].a, "20→18", "da quanto a quanto");
    eq(cv(prevista, {}, OGGI).cambi.length, 0, "e senza correzioni non si elenca niente");
  });
  test("conferma: la virgola italiana vale quanto il punto", () => {
    eq(cv(prevista, { kgMaxRitardo: "45,5" }, OGGI).campi.kgMaxRitardo, 45.5, "45,5 kg");
  });

  test("⛔ previsione: si dice su che base Genesi ha previsto", () => {
    /* una previsione calibrata sul sito vale più di una da manuale, e l'utente
       ha il diritto di sapere quale delle due sta leggendo */
    eq(sentinella.previsioneDiVolata(prevista).calibrata, true, "legge di sito");
    eq(sentinella.testoFontePrevisione(sentinella.previsioneDiVolata(prevista)),
       "da Genesi · legge di sito calibrata", "detto in chiaro");
    eq(sentinella.testoFontePrevisione(sentinella.previsioneDiVolata({ ...prevista, ppvPrevFonte: "genesi-litologia" })),
       "da Genesi · stima dalla litologia", "e l'altra base si distingue");
  });
  test("previsione: una volata registrata a mano non ne ha una calcolata qui", () => {
    eq(sentinella.previsioneDiVolata({ id: "v" }), null, "niente previsione");
    eq(sentinella.testoFontePrevisione(null), "", "e niente da scrivere");
  });
  test("⛔ previsione: i campi del progetto non entrano MAI in quelli della misura", () => {
    const c = sentinella.campiPrevisioneVolata(4.2, { limite: 5, norma: "UNI 9916", fonte: "genesi-sito", airblast: 120 });
    eq(Object.keys(c).some((k) => /^ppvMisurata|^ppvFonte$|^ppvPunto/.test(k)), false,
       "una previsione messa accanto a una misura, in una settimana, diventa indistinguibile da essa");
    eq(c.ppvPrevista, 4.2, "il previsto sta nel suo campo");
  });

  test("⛔ scarto: il confronto previsto→misurato esiste solo con ENTRAMBI i numeri", () => {
    eq(sentinella.scartoPpvVolata(prevista), null, "manca la misura");
    eq(sentinella.scartoPpvVolata({ ppvMisurata: 5, ppvFonte: "strumento" }), null, "manca la previsione");
  });
  test("scarto: con entrambi si dice di quanto e da che parte", () => {
    const s = sentinella.scartoPpvVolata({ ...prevista, stato: "eseguita", ppvMisurata: 5.1, ppvFonte: "strumento" });
    eq(s.delta, 0.9, "nove decimi in più");
    eq(s.pct, 21.4, "cioè +21,4 %");
    eq(s.verso, "sopra", "sopra il previsto");
  });

  test("⛔ firma: col codice di Genesi il doppione si riconosce anche dopo la conferma", () => {
    /* la conferma può aver corretto fori, chili e persino la data: senza il
       codice, reimportare il file del progetto creerebbe una riga fantasma */
    eq(sentinella.firmaVolata({ codiceVolata: "G-77", data: "2026-07-20", nFori: 20 }),
       sentinella.firmaVolata({ codiceVolata: "G-77", data: "2026-07-21", nFori: 18 }),
       "stessa volata, stessa firma");
  });
  test("firma: senza codice si torna a data, fronte, fori e chili", () => {
    eq(sentinella.firmaVolata({ data: "2026-07-20", fronte: "A", nFori: 20, kgTotali: 400 }),
       "2026-07-20|a|20|400", "i file già in giro si deduplicano come prima");
  });

  const registro = [{ id: "a", stato: "prevista", data: "2026-08-10" },
    { id: "b", stato: "prevista", data: "2026-07-20" },
    { id: "c", data: "2026-07-01" }, { id: "d", data: "2026-07-25" }];
  test("⛔ registro: prima le previste in ordine di calendario, poi le eseguite dalla più recente", () => {
    /* le previste con la data già passata vengono per prime: sono quelle da
       confermare, ed è l'unica cosa che chiede un'azione */
    eq(sentinella.volateOrdinate(registro).map((v) => v.id).join(","), "b,a,d,c", "l'ordine del registro");
  });
  test("⛔ registro: si conta quante previste aspettano la conferma", () => {
    /* una volata sparata e mai confermata lascia un buco nel brogliaccio */
    const r = sentinella.riepilogoPreviste(registro, OGGI);
    eq(r.totale, 2, "due previste");
    eq(r.daConfermare, 1, "e una la cui data è già arrivata");
    eq(r.prossima, "2026-08-10", "l'altra è la prossima in calendario");
  });
}

/* ══ IL GIRO EXPORT → IMPORT DEL REGISTRO VOLATE ════════════════════════
   Il CSV è il modo in cui i dati **escono** dall'app e **rientrano**: nel
   backup dell'azienda, nel file che Genesi manda a Sentinella, nel foglio che
   qualcuno apre per controllare. Una colonna spostata o un'intestazione che
   non combacia con quello che il lettore si aspetta è il modo più **silenzioso**
   di perdere un registro: nessun errore, solo righe che rientrano diverse da
   come sono uscite.

   La prova più forte è quindi una sola: **si scrive, si rilegge, e si pretende
   che torni identico** — campo per campo, non «più o meno».

   ⚠️ Ma il giro da solo NON basta, e la controprova l'ha fatto vedere: scritti
   i numeri con la virgola italiana invece che col punto, il giro resta
   **identico** — perché il lettore usa `numIt`, che la virgola la legge. Il
   giro dimostra che scrittore e lettore vanno d'accordo fra loro, **non** che
   il formato sia quello giusto per chi il file lo apre con un altro programma.
   Per quello serve un'asserzione sul TESTO del file, ed è la penultima qui
   sotto. Vale in generale: **una prova di andata e ritorno resta verde anche
   se le due metà sbagliano insieme.** */
{
  const volate = [
    { id: "v1", data: "2026-07-20", fronte: 'Fronte "A"; nord', nFori: 20, kgTotali: 400,
      kgMaxRitardo: 50, distanzaRicettore: 200, esito: "regolare", note: "tutto ok",
      ppvMisurata: 3.2, ppvFonte: "strumento", ppvPuntoId: "p1", ppvPuntoNome: "Casa Rossi",
      ppvData: "2026-07-20", ppvOra: "10:30", stato: "eseguita", codiceVolata: "G-77" },
    { id: "v2", data: "2026-08-10", fronte: "B", nFori: 15, kgTotali: 300, kgMaxRitardo: 40,
      distanzaRicettore: 180, stato: "prevista", ppvPrevista: 4.2, ppvPrevLimite: 5,
      ppvPrevNorma: "UNI 9916", ppvPrevFonte: "genesi-sito", airblastPrevisto: 120, codiceVolata: "G-78" },
  ];
  const CAMPI = ["data", "fronte", "nFori", "kgTotali", "kgMaxRitardo", "distanzaRicettore",
    "esito", "note", "ppvMisurata", "ppvFonte", "ppvPuntoNome", "ppvOra", "stato",
    "ppvPrevista", "ppvPrevLimite", "ppvPrevNorma", "ppvPrevFonte", "airblastPrevisto", "codiceVolata"];
  const giro = sentinella.parseVolateCsv(sentinella.csvRegistroVolate(volate));

  test("⛔ csv: quello che esce rientra IDENTICO, campo per campo", () => {
    eq(giro.length, 2, "due righe fuori, due dentro");
    for (const orig of volate) {
      const r = giro.find((x) => x.codiceVolata === orig.codiceVolata) || {};
      const diversi = CAMPI.filter((c) => orig[c] !== undefined
        && String(orig[c]) !== String(r[c] === undefined ? "" : r[c]));
      eq(diversi.join(","), "", `la volata ${orig.codiceVolata} torna com'era`);
    }
  });
  test("⛔ csv: un punto e virgola DENTRO un campo non spacca il file", () => {
    /* il separatore è il punto e virgola, e «Fronte "A"; nord» ne contiene uno
       insieme a due virgolette: senza le regole delle virgolette la riga si
       spezzerebbe e tutte le colonne dopo scivolerebbero di uno */
    eq(giro[0].fronte, 'Fronte "A"; nord', "il testo torna esattamente com'era");
  });
  test("⛔ csv: una cella che comincia per «=» non diventa una formula", () => {
    /* aperto in Excel, «=SOMMA(A1:A9)» in una cella di testo verrebbe ESEGUITO:
       è la strada con cui un file di dati diventa un programma */
    const riga = sentinella.csvRegistroVolate([{ data: "2026-07-01", fronte: "=SOMMA(A1:A9)", nFori: 1 }]).split("\n")[1];
    eq(riga.includes("'=SOMMA(A1:A9)"), true, "l'apice davanti la disinnesca");
  });
  test("⛔ csv: lo stato attraversa il giro, così progetto ed evento restano distinti", () => {
    eq(giro.find((x) => x.codiceVolata === "G-78").stato, "prevista", "la prevista resta prevista");
    eq(giro.find((x) => x.codiceVolata === "G-77").stato, "eseguita", "e l'eseguita eseguita");
  });
  test("⛔ csv: la PPV PREVISTA non rientra nelle colonne della misurata", () => {
    /* sono due colonne diverse perché sono due cose diverse: una previsione
       messa dove sta una misura, dopo una settimana, non si distingue più */
    const prevista = giro.find((x) => x.codiceVolata === "G-78");
    eq(prevista.ppvMisurata, undefined, "nessuna misura su una volata non ancora sparata");
    eq(prevista.ppvPrevista, 4.2, "il previsto sta nel suo campo");
  });
  test("csv: l'id del punto di misura non viaggia nel file", () => {
    /* un id è vero solo dentro l'organizzazione che l'ha scritto: nel file
       resta il NOME, che è quello che un'altra azienda può leggere */
    eq(giro[0].ppvPuntoId, "", "nessun id");
    eq(giro[0].ppvPuntoNome, "Casa Rossi", "ma il nome sì");
  });
  test("⛔ csv: un file vecchio, senza le colonne in coda, si importa come prima", () => {
    /* le undici colonne della PPV e della previsione sono nate dopo: un
       registro esportato prima deve rientrare uguale, non a metà */
    const vecchio = "data;fronte;nFori;kgTotali;kgMaxRitardo;distanzaRicettore;esito;note\n"
      + "2026-07-01;A;12;250;30;150;regolare;niente\n";
    const v = sentinella.parseVolateCsv(vecchio);
    eq(v.length, 1, "la riga entra");
    eq(v[0].nFori, 12, "coi suoi numeri");
    eq(sentinella.statoVolata(v[0]), "eseguita", "e resta un fatto avvenuto, che è quello che è");
  });
  test("csv: una riga senza una data vera si scarta", () => {
    eq(sentinella.parseVolateCsv("data;fronte\n;A\n2026-07-01;B").length, 1, "solo quella con la data");
  });
  test("⛔ csv: un registro vuoto è l'intestazione da sola, non un file vuoto", () => {
    /* chi lo apre vede le colonne e capisce che il registro è vuoto, invece di
       un file di zero byte che sembra un export fallito */
    const c = sentinella.csvRegistroVolate([]);
    eq(c.startsWith("data;fronte;"), true, "c'è l'intestazione");
    eq(sentinella.parseVolateCsv(c).length, 0, "e nessuna riga");
  });
  test("csv: le righe escono in ordine di data", () => {
    const righe = sentinella.csvRegistroVolate(volate).split("\n").slice(1).filter(Boolean);
    eq(righe[0].startsWith("2026-07-20"), true, "prima luglio");
    eq(righe[1].startsWith("2026-08-10"), true, "poi agosto");
  });
  test("⛔ csv: una casella VUOTA non diventa uno zero, in nessuno dei due versi", () => {
    /* ⛔ Il difetto stava su tutt'e due i lati e nessuno dei due lo vedeva,
       perché si annullavano fra loro: `csvRegistroVolate` scriveva
       `n(+v.distanzaRicettore || 0)` e `parseVolateCsv` leggeva
       `Number.isFinite(n) ? … : 0`. Il giro di andata e ritorno restava
       IDENTICO — 0 andava, 0 tornava — ed è esattamente la trappola scritta in
       `CLAUDE.md`: due metà che sbagliano insieme tengono la prova verde. Per
       questo qui si asserisce anche sul TESTO del file, dove la cella vuota o
       lo «0» si vedono. Perché conta: il report per l'ente stampava
       «distanza 0 m», che si legge come il ricettore dentro il fronte. */
    const v = [{ data: "2026-07-20", fronte: "F1", nFori: null, kgTotali: 400,
                 kgMaxRitardo: 20, distanzaRicettore: null, esito: "regolare" }];
    const riga = sentinella.csvRegistroVolate(v).split("\n")[1];
    eq(riga, "2026-07-20;F1;;400;20;;regolare;;;;;;eseguita;;;;;;",
      "le due caselle non dichiarate escono VUOTE, non a zero");
    const back = sentinella.parseVolateCsv(sentinella.csvRegistroVolate(v))[0];
    eq(back.nFori, null, "e rientrano come «non dichiarato»");
    eq(back.distanzaRicettore, null, "anche la distanza");
    eq(back.kgTotali, 400, "mentre il numero dichiarato non si tocca");
    const r = sentinella.refertoDaVolata(back);
    eq(r.motivi.includes("distanza"), true, "e il referto sa che la distanza manca");
    eq(r.sd, null, "quindi la distanza scalata non si calcola");
  });
  test("⛔ csv: uno ZERO scritto da qualcuno resta uno zero", () => {
    /* la guardia sta sull'ASSENZA, non sul valore: chi dichiara zero fori ha
       dichiarato qualcosa, e cancellarglielo sarebbe l'errore opposto */
    const riga = sentinella.csvRegistroVolate([{ data: "2026-07-20", nFori: 0, kgTotali: 0 }]).split("\n")[1];
    eq(riga.split(";")[2], "0", "zero fori dichiarati restano «0»");
    eq(sentinella.parseVolateCsv(sentinella.csvRegistroVolate([{ data: "2026-07-20", nFori: 0 }]))[0].nFori, 0,
      "e rientrano come zero, non come «non dichiarato»");
  });
  test("⛔ csv: i numeri per un'altra macchina escono col PUNTO decimale", () => {
    /* il file lo legge un programma, non una persona: la virgola italiana
       sarebbe un separatore di colonna in mezzo a un numero */
    eq(sentinella.csvRegistroVolate(volate).includes(";3.2;"), true, "3.2, non 3,2");
  });

  test("⛔ csv referti: a Genesi vanno i tre numeri e da dove vengono", () => {
    const pronti = sentinella.refertiDaVolate([{ id: "r1", data: "2026-07-20", fronte: "A",
      distanzaRicettore: 200, kgMaxRitardo: 50, ppvMisurata: 3.2, ppvFonte: "strumento",
      ppvPuntoNome: "Casa" }]).pronti;
    const c = sentinella.csvRefertiGenesi(pronti).split("\n");
    eq(c[0], sentinella.CSV_REFERTI_INTESTAZIONE, "l'intestazione è quella dichiarata");
    eq(c[1].startsWith("200;50;3.2;"), true, "distanza, carica per ritardo, PPV");
    eq(c[1].includes("Volata 20/07/2026"), true, "e il riferimento per risalire alla volata");
  });
}

/* ══ IL RECLAMO DI UN RESIDENTE, E LA COINCIDENZA CHE NON È UNA CAUSA ═══
   Il reclamo è l'altro ingresso del ponte verso Scudo: non finisce quando è
   stato registrato, richiede che qualcuno faccia qualcosa entro una data.

   La regola più delicata di tutte non è un calcolo, è una **frase**. Un
   superamento nello stesso giorno di una volata va **guardato**, non
   **spiegato**: due fatti nello stesso giorno sono due fatti nello stesso
   giorno. Scrivere «causato dalla volata» dentro un documento che finisce
   all'ente è un autogol — e spesso è anche falso. */
{
  const reclami = [
    { id: "r1", data: "2026-07-10", tipo: "rumore", stato: "aperto",
      chi: "Sig. Rossi", descrizione: "rumore alle 6", ora: "06:15" },
    { id: "r2", data: "2026-07-20", tipo: "polvere", stato: "chiuso" },
    { id: "r3", data: "boh", tipo: "altro" }];

  test("reclami: quanti in tutto, quanti ancora aperti, e l'ultimo", () => {
    const r = sentinella.riepilogoReclami(reclami);
    eq(r.totale, 3, "tre in tutto");
    eq(r.aperti, 2, "due aperti: chi non ha stato non è chiuso");
    eq(r.ultimo, "2026-07-20", "e una data impossibile non diventa «l'ultimo»");
  });
  test("reclami: senza reclami non si inventa una data", () => {
    eq(sentinella.riepilogoReclami([]).ultimo, null, "nessun ultimo");
    eq(sentinella.riepilogoReclami(null).totale, 0, "e nemmeno con la lista mancante");
  });
  test("reclami: un tipo sconosciuto finisce sotto «Altro», non sparisce", () => {
    eq(sentinella.etichettaReclamo("POLVERE"), "Polvere", "il maiuscolo non conta");
    eq(sentinella.etichettaReclamo("boh"), "Altro", "e l'ignoto ha un posto dove stare");
  });

  test("⛔ bozza reclamo: l'azione porta con sé il fatto, scritto in italiano", () => {
    /* Scudo non può leggere le collezioni di Sentinella: un'azione che dicesse
       solo «origine: reclamo xyz» sarebbe illeggibile per l'RSPP */
    const b = sentinella.bozzaAzioneReclamo(reclami[0], { id: "ric1", nome: "Casa Rossi" });
    eq(b.origineTipo, sentinella.ORIGINE_RECLAMO, "il tipo di fatto");
    eq(b.origineApp, sentinella.PONTE_APP, "e da quale app arriva");
    eq(b.origineNota.includes("Sig. Rossi"), true, "chi ha segnalato");
    eq(b.origineNota.includes("«rumore alle 6»"), true, "e le sue parole, fra virgolette");
    eq(b.origineNota.includes("Casa Rossi"), true, "col ricettore");
  });
  test("bozza reclamo: la descrizione proposta dice già cosa fare", () => {
    const b = sentinella.bozzaAzioneReclamo(reclami[0], { id: "ric1", nome: "Casa Rossi" });
    eq(b.descrizione, "Dare seguito al reclamo per rumore a Casa Rossi del 10/07/2026",
       "un compito, non un'etichetta");
    eq(b.stato, "aperta", "e nasce aperta");
  });
  test("⛔ bozza reclamo: senza data la voce non resta vuota", () => {
    /* `origineVoce` è la chiave con cui si riconosce il doppione: vuota,
       due reclami diversi sembrerebbero lo stesso */
    eq(sentinella.bozzaAzioneReclamo({ id: "r9", tipo: "altro" }, null).origineVoce, "reclamo",
       "una parola al posto del vuoto");
    eq(sentinella.bozzaAzioneReclamo({ tipo: "rumore" }), null, "e senza id non si prepara niente");
  });

  const volate = [{ id: "v1", data: "2026-07-10", fronte: "A" },
    { id: "v2", data: "2026-07-10", fronte: "B" }, { id: "v3", data: "2026-07-11", fronte: "A" }];
  test("⛔ coincidenza: si dice che c'era una volata, NON che è stata la causa", () => {
    /* «causato dalla volata» dentro un documento che va all'ente è un autogol,
       e spesso è anche falso: servono la misura strumentale, l'ora e una
       valutazione tecnica */
    const c = sentinella.coincidenzaVolata(volate, "2026-07-10");
    eq(c.n, 2, "due volate quel giorno");
    eq(c.testo.includes("causa"), false, "il testo non parla di cause");
    eq(c.avviso.includes("non una causa dimostrata"), true, "e l'avviso lo dice esplicitamente");
  });
  test("coincidenza: si dice quante e su quali fronti", () => {
    eq(sentinella.coincidenzaVolata(volate, "2026-07-10").testo,
       "Quel giorno sono state registrate 2 volate (A, B).", "al plurale");
    eq(sentinella.coincidenzaVolata(volate, "2026-07-11").testo,
       "Quel giorno è stata registrata una volata (A).", "e al singolare, in italiano");
  });
  test("⛔ coincidenza: senza volate quel giorno non si scrive niente", () => {
    /* un riquadro vuoto accanto a un superamento suggerirebbe un legame che
       nessuno ha misurato */
    eq(sentinella.coincidenzaVolata(volate, "2026-07-12"), null, "niente da dire");
  });

  test("esito del report: le tre facce sono quelle del semaforo di tutta l'app", () => {
    eq(sentinella.ESITI["conforme"].cls, "ok", "verde");
    eq(sentinella.ESITI["non-conforme"].cls, "danger", "rosso");
    eq(sentinella.ESITI["senza-dati"].cls, "warn", "e «senza dati» è giallo, non verde");
  });
  test("⛔ esito del report: «senza dati» non dice che il limite è stato rispettato", () => {
    /* è la differenza fra «abbiamo misurato e va bene» e «non abbiamo
       misurato»: su un documento per l'ente confonderle è il difetto peggiore */
    const t = sentinella.ESITI["senza-dati"].testo;
    eq(t.includes("non può dire se il limite è stato rispettato"), true, "lo dichiara");
    eq(t.includes("nessuna lettura ha raggiunto la soglia"), false, "e non si spaccia per conforme");
  });
}

/* ══ IL REGISTRO DELLE AZIONI CORRETTIVE (CAPA) ═════════════════════════
   È l'altra sponda dei due ponti di Sentinella, ed è quello che la legge chiede
   di tracciare insieme agli eventi: **segnala → correggi → verifica**. Un
   infortunio, un near-miss, una voce non conforme di un'ispezione, un
   superamento ambientale, il reclamo di un residente: tutti finiscono qui, e da
   qui esce la risposta alla domanda «e voi cosa avete fatto?».

   La scelta di fondo che le prove difendono: **l'avanzamento si salva, il
   semaforo si calcola.** «Aperta / in corso / chiusa» è un dato scritto da
   qualcuno; «scaduta / in scadenza / regolare» viene dalla data, ogni volta.
   Salvare anche quello significherebbe avere nel database un'azione «regolare»
   che nel frattempo è scaduta — un dato derivato che invecchia in silenzio. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const az = (o) => ({ id: "a1", descrizione: "x", stato: "aperta", scadenza: "2026-08-15", ...o });

  test("azioni: l'avanzamento gira col tocco, e si richiude in cerchio", () => {
    eq(scudo.azioneStatoSuccessivo("aperta"), "in-corso", "aperta → in corso");
    eq(scudo.azioneStatoSuccessivo("in-corso"), "chiusa", "in corso → chiusa");
    eq(scudo.azioneStatoSuccessivo("chiusa"), "aperta", "e si può riaprire, perché a volte non era finita");
    eq(scudo.azioneStatoSuccessivo("boh"), "in-corso", "uno stato sconosciuto vale «aperta»");
  });
  test("⛔ azioni: un'azione senza stato è APERTA, non chiusa", () => {
    /* il valore di partenza deve essere quello che chiede attenzione: il
       contrario nasconderebbe un compito che nessuno ha preso in carico */
    eq(scudo.azioneLabel(undefined).label, "Aperta", "aperta");
    eq(scudo.azioneLabel(undefined).cls, "danger", "e in rosso");
  });
  test("⛔ azioni: il semaforo della scadenza NON è lo stato salvato", () => {
    /* è calcolato dalla data ogni volta: salvarlo darebbe un'azione «regolare»
       nel database che nel frattempo è scaduta */
    eq(scudo.statoAzione(az({ scadenza: "2026-07-30" }), OGGI), "scaduta", "ieri");
    eq(scudo.statoAzione(az({ scadenza: "2026-07-31" }), OGGI), "in-scadenza", "oggi non è ancora scaduta");
    eq(scudo.statoAzione(az({ scadenza: "2026-08-30" }), OGGI), "in-scadenza", "trenta giorni: preavviso");
    eq(scudo.statoAzione(az({ scadenza: "2026-08-31" }), OGGI), "regolare", "trentuno: ancora lontana");
  });
  test("⛔ azioni: un'azione CHIUSA non scade più, nemmeno se la data è passata", () => {
    /* il lavoro è finito: tenerla rossa riempirebbe il quadro di allarmi che
       nessuno può togliere, e allora si smette di guardarli */
    eq(scudo.statoAzione(az({ scadenza: "2026-01-01", stato: "chiusa" }), OGGI), "regolare", "chiusa a gennaio");
  });
  /* ⛔ «SENZA DATA» NON È «REGOLARE». La prova diceva «non si allarma» e
     pretendeva il verde: giusto il primo pezzo (è un avviso, non un allarme),
     sbagliato il secondo. Corretta il 04/08 come `livelloScadenza` il 03/08, e
     col termine che le altre app usano già. */
  test("⛔ azioni: un'azione aperta senza scadenza è «senza data», non regolare", () => {
    eq(scudo.statoAzione(az({ scadenza: "" }), OGGI), "senza data", "manca la data: non si sa, e si dice");
    eq(scudo.statoAzione(az({ scadenza: null }), OGGI), "senza data", "e vale anche per il null");
    eq(scudo.statoAzione(az({ scadenza: "2026-13-45" }), OGGI), "senza data", "forma giusta, data impossibile");
    ok(scudo.statoAzione(az({ scadenza: "" }), OGGI) !== "regolare",
       "il verde su un'azione di cui nessuno sa l'entro-quando è il difetto difeso qui");
    ok(scudo.statoAzione(az({ scadenza: "" }), OGGI) !== "scaduta",
       "e non si inventa dall'altra parte: non è scaduta, non si sa");
    // una CHIUSA resta regolare anche senza data: il lavoro è finito
    eq(scudo.statoAzione(az({ scadenza: "", stato: "chiusa" }), OGGI), "regolare", "chiusa senza data");
  });

  const elenco = [az({ id: "a1", scadenza: "2026-08-30" }), az({ id: "a2", scadenza: "2026-07-01" }),
    az({ id: "a3", scadenza: "2027-01-01" }), az({ id: "a4", scadenza: "2026-07-02", stato: "chiusa" }),
    az({ id: "a5", scadenza: "", stato: "in-corso" })];

  test("⛔ azioni: le urgenti sono solo quelle DA CHIUDERE e con la data addosso", () => {
    const u = scudo.azioniUrgenti(elenco, OGGI);
    eq(u.map((a) => a.id).join(","), "a2,a1", "la scaduta e quella in scadenza");
    eq(u[0].scadenza < u[1].scadenza, true, "prima la più vecchia, che è la più urgente");
  });
  test("azioni: la chiusa e quella senza data non entrano fra le urgenti", () => {
    const u = scudo.azioniUrgenti(elenco, OGGI).map((a) => a.id);
    eq(u.includes("a4"), false, "chiusa a luglio, era scaduta");
    eq(u.includes("a5"), false, "e quella senza scadenza");
  });
  test("⛔ azioni: il riepilogo conta ogni azione una volta sola", () => {
    const r = scudo.riepilogoAzioni(elenco, OGGI);
    eq(r.totale, 5, "cinque azioni");
    eq(r.aperte + r.inCorso + r.chiuse, r.totale, "e i tre stati fanno il totale: nessuna cade fuori");
    eq(r.daChiudere, 4, "quattro non sono chiuse");
    eq(r.scadute, 1, "una scaduta");
    eq(r.inScadenza, 1, "e una in scadenza");
  });

  const miste = [{ origineTipo: "evento", origineId: "e1" }, { origineTipo: "ispezione", origineId: "i1" },
    { origineTipo: "superamento", origineId: "p1", stato: "aperta" },
    { origineTipo: "reclamo", origineId: "r1", stato: "chiusa" }];

  test("⛔ azioni: si risale dall'evento alle sue azioni, e solo alle sue", () => {
    /* è la catena che l'ispettore percorre al contrario: questo infortunio,
       che cosa avete fatto? */
    eq(scudo.azioniDiEvento(miste, "e1").length, 1, "quella dell'evento");
    eq(scudo.azioniDiEvento(miste, "i1").length, 0, "non quella dell'ispezione, che ha lo stesso ruolo ma altra origine");
    eq(scudo.azioniDiEvento(miste, "").length, 0, "e senza id non si tira su tutto");
  });
  test("azioni: e allo stesso modo dall'ispezione", () => {
    eq(scudo.azioniDiIspezione(miste, "i1").length, 1, "quella dell'ispezione");
    eq(scudo.azioniDiIspezione(miste, "e1").length, 0, "non quella dell'evento");
  });
  test("⛔ ambiente: un'azione che arriva da Sentinella si riconosce", () => {
    /* serve a scrivere l'origine giusta e a NON farla cancellare da una
       modifica fatta dal form di Scudo, che non sa da dove viene */
    eq(miste.map((a) => scudo.daAmbiente(a)).join(","), "false,false,true,true", "le due ambientali");
    eq(scudo.etichettaAmbiente(miste[2]), "Superamento", "e si dice quale delle due è");
    eq(scudo.etichettaAmbiente(miste[3]), "Reclamo", "l'altra");
  });
  test("ambiente: il riepilogo separa i superamenti dai reclami", () => {
    const r = scudo.riepilogoAmbiente(miste);
    eq(r.totale, 2, "due ambientali");
    eq(r.superamenti, 1, "un superamento");
    eq(r.reclami, 1, "e un reclamo");
    eq(r.daChiudere, 1, "una sola resta da chiudere");
  });
  test("ambiente: senza nessuna azione ambientale tutti zero, niente si rompe", () => {
    eq(scudo.riepilogoAmbiente([]).totale, 0, "vuoto");
    eq(scudo.riepilogoAmbiente(null).daChiudere, 0, "e nemmeno con la lista mancante");
  });
}

/* ══ «CHI PUÒ FARE QUEL LAVORO DOMANI MATTINA» ══════════════════════════
   È la funzione con la posta più alta di tutta la piattaforma: dice se una
   persona può stare in cava a fare un certo lavoro. Tre risposte sole, perché
   di mattina non c'è tempo di leggere una tabella — **può / attenzione / no**.

   La scelta dichiarata nel modulo, e che queste prove blindano:

   · **bloccano** la persona non in forza, l'idoneità sanitaria negativa e un
     corso richiesto **mancante o scaduto**;
   · **i DPI NON bloccano, ma pesano.** L'app sa se la consegna è
     *registrata*, non se il lavoratore ha l'elmetto **in mano**: dirlo come
     certezza sarebbe una bugia. Restano in evidenza, non nascosti.

   ⛔ Qui non si tocca nulla di quello che l'app decide: si scrive soltanto la
   prova che continui a deciderlo così. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const REQ = scudo.REQUISITI_FORMAZIONE[0];      // la visita medica periodica
  const lav = (o) => ({ id: "L1", nome: "Mario Rossi", attivo: true, idoneita: "idoneo", ...o });
  const mansione = { id: "m1", nome: "Fochino", lavoratoriIds: ["L1"], requisiti: [REQ.chiave], dpi: [] };
  const inRegola = [{ lavoratoreId: "L1", preset: REQ.chiave, dataScadenza: "2027-06-01" }];

  test("⛔ requisito: una scadenza lo copre in tre modi, dal più sicuro al più tollerante", () => {
    /* i dati veri arrivano da fogli diversi: pretendere solo il campo `preset`
       lascerebbe fuori tutte le righe scritte a mano prima che esistesse */
    eq(scudo.scadenzaCopreRequisito({ preset: REQ.chiave, descrizione: "qualsiasi" }, REQ), true, "nata da quell'adempimento");
    eq(scudo.scadenzaCopreRequisito({ descrizione: REQ.etichetta.toUpperCase() }, REQ), true, "stessa descrizione, maiuscole a parte");
    eq(scudo.scadenzaCopreRequisito({ descrizione: "corso " + REQ.parole[0] }, REQ), true, "o una parola che lo identifica");
    eq(scudo.scadenzaCopreRequisito({ descrizione: "revisione estintori" }, REQ), false, "e un'altra cosa non lo copre");
  });
  test("⛔ requisito: con più rinnovi vale l'ULTIMO, non il primo trovato", () => {
    /* il primo trovato sarebbe il corso del 2026 già scaduto, e la persona
       risulterebbe non abilitata pur avendo rinnovato */
    const due = [{ lavoratoreId: "L1", preset: REQ.chiave, dataScadenza: "2026-01-01" },
      { lavoratoreId: "L1", preset: REQ.chiave, dataScadenza: "2027-06-01" }];
    const st = scudo.statoRequisito(REQ, due, OGGI);
    eq(st.scadenza, "2027-06-01", "il rinnovo più lontano");
    eq(st.stato, "regolare", "quindi in regola");
  });
  test("requisito: senza nessuna riga lo stato è MANCANTE, non «regolare»", () => {
    /* «non risulta» non è «va bene»: è la stessa differenza fra «senza dati» e
       «conforme» del report ambientale */
    eq(scudo.statoRequisito(REQ, [], OGGI).stato, "mancante", "mancante");
  });
  test("requisito: una chiave sconosciuta non rompe la schermata", () => {
    const r = scudo.requisitoSicuro("corso-inventato");
    eq(r.etichetta, "corso-inventato", "meglio l'etichetta grezza che una pagina rotta");
    eq(scudo.requisitoFormazione("corso-inventato"), null, "ma si sa che non è dell'elenco");
  });

  test("abilitazione: con tutto a posto la risposta è «può»", () => {
    eq(scudo.abilitazioneLavoratore(lav(), mansione, inRegola, [], OGGI).esito, "puo", "può andare");
  });
  test("⛔ abilitazione: un corso richiesto che manca BLOCCA", () => {
    const a = scudo.abilitazioneLavoratore(lav(), mansione, [], [], OGGI);
    eq(a.esito, "no", "non può");
    eq(a.bloccanti.length > 0, true, "e si dice perché");
  });
  test("⛔ abilitazione: bloccano anche il non in forza e il non idoneo", () => {
    eq(scudo.abilitazioneLavoratore(lav({ attivo: false }), mansione, inRegola, [], OGGI).bloccanti.join(""),
       "non è in forza", "chi non è in forza non va in cava");
    eq(scudo.abilitazioneLavoratore(lav({ idoneita: "non-idoneo" }), mansione, inRegola, [], OGGI).bloccanti.join(""),
       "giudicato non idoneo alla visita medica", "e nemmeno chi il medico ha giudicato non idoneo");
  });
  test("⛔ abilitazione: «idoneo con prescrizioni» avvisa, non blocca", () => {
    /* il medico l'ha dichiarato idoneo: bloccarlo sarebbe l'app che decide al
       posto del medico competente */
    const a = scudo.abilitazioneLavoratore(lav({ idoneita: "prescrizioni" }), mansione, inRegola, [], OGGI);
    eq(a.esito, "attenzione", "può andare, con qualcosa da sapere");
    eq(a.attenzioni.join(""), "idoneo con prescrizioni", "e lo si legge");
  });
  test("⛔ abilitazione: un DPI mai consegnato NON blocca, ma resta in evidenza", () => {
    /* l'app sa se la consegna è REGISTRATA, non se il lavoratore ha l'elmetto
       in mano: dirlo come certezza sarebbe una bugia in tutte e due le
       direzioni — bloccare chi ce l'ha, o assolvere chi non ce l'ha */
    const dpi = scudo.TIPI_DPI[0];
    const a = scudo.abilitazioneLavoratore(lav(), { ...mansione, dpi: [dpi.chiave] }, inRegola, [], OGGI);
    eq(a.esito, "attenzione", "non «no»");
    eq(a.attenzioni.some((x) => x.includes("consegna mai registrata")), true,
       "e la frase dice REGISTRATA, non «non ce l'ha»");
  });

  test("⛔ matrice: prima chi può andare, poi chi no — non l'alfabeto", () => {
    /* di mattina si guarda la prima riga: deve essere una persona che può
       lavorare, non la prima in ordine alfabetico */
    const righe = scudo.matriceMansione({ ...mansione, lavoratoriIds: ["L1", "L2"] },
      [lav({ id: "L1", nome: "Zeta" }), lav({ id: "L2", nome: "Anna" })], inRegola, [], OGGI);
    eq(righe.map((r) => r.lavoratore.nome + ":" + r.esito).join(","), "Zeta:puo,Anna:no",
       "Zeta può e viene prima, Anna no e viene dopo");
  });
  test("matrice: una persona non più in elenco non fa sparire la riga delle altre", () => {
    const righe = scudo.matriceMansione({ ...mansione, lavoratoriIds: ["L1", "sparito"] },
      [lav({ id: "L1" })], inRegola, [], OGGI);
    eq(righe.length, 1, "resta quella che c'è");
  });
  test("matrice: il riepilogo conta le tre risposte, e la somma torna", () => {
    const r = scudo.riepilogoMansioni([{ ...mansione, lavoratoriIds: ["L1", "L2"] }],
      [lav({ id: "L1" }), lav({ id: "L2", nome: "Anna" })], inRegola, [], OGGI)[0];
    eq(r.puo + r.attenzione + r.no, r.totale, "nessuna persona cade fuori dal conto");
    eq(r.puo, 1, "una può");
    eq(r.no, 1, "e una no");
  });
}

/* ══ L'ORGANIGRAMMA DELLA SICUREZZA: CHI HA QUEL RUOLO, DAVVERO ═════════
   Sorvegliante, direttore, preposto, RSPP, medico competente, RLS, primo
   soccorso, antincendio: otto ruoli **obbligatori**, e sono fra le prime cose
   che un ispettore chiede. L'organigramma dice per ognuno chi c'è e com'è messa
   la sua formazione.

   ⛔ La regola che queste prove hanno trovato mancante: **una nomina copre un
   ruolo solo se la persona c'è ancora.** Una nomina che punta a un lavoratore
   cancellato dall'anagrafica — o non più in forza — non copre niente: il ruolo
   è scoperto, e dirlo verde è un semaforo che mente su un obbligo di legge. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  /* La nomina di riferimento porta la sua DATA, come quelle che scrive il form
     (`dal || oggiISO()`): senza, ogni prova di questo blocco misurava anche il
     giallo del «senza data di nomina», che ha una prova sua qui sotto. */
  const rspp = (o) => ({ id: "n1", ruolo: "rspp", lavoratoreId: "L1", dal: "2025-01-15", ...o });
  const LAV = [{ id: "L1", nome: "Mario", attivo: true }, { id: "L2", nome: "Anna", attivo: false }];
  const bloccoDi = (nomine, scadenze = []) =>
    scudo.organigrammaSicurezza(nomine, LAV, scadenze, OGGI).find((x) => x.ruolo.chiave === "rspp");

  test("nomina: è attiva quando è già decorsa e non è ancora finita", () => {
    eq(scudo.nominaAttiva({ ruolo: "rspp" }, OGGI), true, "senza date è in corso");
    eq(scudo.nominaAttiva({ dal: "2026-09-01" }, OGGI), false, "una che deve ancora partire");
    eq(scudo.nominaAttiva({ al: "2026-06-01" }, OGGI), false, "e una già finita");
    eq(scudo.nominaAttiva({ dal: "2026-07-31" }, OGGI), true, "il giorno in cui comincia conta");
    eq(scudo.nominaAttiva({ al: "2026-07-31" }, OGGI), true, "e anche quello in cui finisce");
  });
  test("⛔ organigramma: un ruolo obbligatorio senza nessuno è ROSSO", () => {
    const o = bloccoDi([]);
    eq(o.mancante, true, "nessuno è nominato");
    eq(o.stato, "danger", "e si vede");
    eq(scudo.NOMINE_RUOLI.filter((r) => r.obbligatoria).length, 8, "gli obbligatori sono otto");
  });
  test("⛔ organigramma: una nomina su una persona NON PIÙ IN ANAGRAFICA non copre il ruolo", () => {
    /* è un semaforo verde su una sedia vuota, e su un obbligo di legge */
    const o = bloccoDi([rspp({ lavoratoreId: "sparito" })]);
    eq(o.stato, "danger", "il ruolo resta da sistemare");
    eq(scudo.nomineDaSistemare([o]).length, 1, "e finisce nelle urgenze del quadro");
  });
  test("⛔ organigramma: una nomina su chi NON È PIÙ IN FORZA non copre il ruolo", () => {
    /* la persona esiste ancora in anagrafica ma ha lasciato l'azienda: la
       nomina resta scritta, il ruolo però è scoperto */
    const o = bloccoDi([rspp({ lavoratoreId: "L2" })]);
    eq(o.stato, "danger", "da sistemare");
    eq(o.persone.length, 1, "la nomina resta visibile: si deve poter capire chi era");
  });
  test("organigramma: con la persona in forza il ruolo è coperto", () => {
    const o = bloccoDi([rspp()]);
    eq(o.stato, "ok", "verde");
    eq(o.mancante, false, "coperto");
    eq(scudo.nomineDaSistemare([o]).length, 0, "niente da sistemare");
  });
  test("⛔ organigramma: nominato ma senza la formazione richiesta è ROSSO", () => {
    /* il preposto ha un corso obbligatorio con aggiornamento biennale: averlo
       nominato senza il corso è una nomina che non regge */
    const org = scudo.organigrammaSicurezza([{ id: "n2", ruolo: "preposto", lavoratoreId: "L1" }],
      LAV, [], OGGI).find((x) => x.ruolo.chiave === "preposto");
    eq(org.senzaFormazione, 1, "una persona senza il corso");
    eq(org.stato, "danger", "e il blocco è rosso");
  });
  test("organigramma: col corso in regola il preposto è a posto", () => {
    const org = scudo.organigrammaSicurezza([{ id: "n2", ruolo: "preposto", lavoratoreId: "L1", dal: "2025-01-15" }],
      LAV, [{ lavoratoreId: "L1", preset: "form-preposto", dataScadenza: "2027-06-01" }],
      OGGI).find((x) => x.ruolo.chiave === "preposto");
    eq(org.senzaFormazione, 0, "il corso c'è");
    eq(org.stato, "ok", "verde");
  });
  /* ⛔ UNA NOMINA SENZA LA DATA DA CUI DECORRE NON SI PUÒ DIMOSTRARE, e usciva
     verde con la pastiglia «Nomina attiva». È un avviso, non un allarme — la
     persona c'è — quindi giallo: il rosso qui direbbe «da nominare» su un ruolo
     che qualcuno ce l'ha, e insegnerebbe a ignorare i rossi. */
  test("⛔ organigramma: una nomina SENZA DATA non è un ruolo in regola", () => {
    const o = bloccoDi([rspp({ dal: "" })]);
    eq(o.senzaData, 1, "una nomina di cui non si sa da quando");
    eq(o.stato, "warn", "giallo: c'è qualcuno, ma il dato non c'è");
    ok(o.stato !== "ok", "il verde su una data mai scritta è il difetto difeso qui");
    eq(o.mancante, false, "e non è «da nominare»: la persona c'è");
    eq(scudo.nomineDaSistemare([o]).length, 0, "non entra fra le urgenze rosse del Quadro");
    // una data IMPOSSIBILE è illeggibile quanto una mancante (stessa regola di statoScadenza)
    eq(bloccoDi([rspp({ dal: "2025-02-30" })]).senzaData, 1, "31 febbraio: non esiste");
    // e la nomina con la sua data resta verde
    eq(bloccoDi([rspp()]).senzaData, 0, "con la data non si conta niente");
    eq(bloccoDi([rspp()]).stato, "ok", "e il ruolo è coperto");
  });
  test("organigramma: un ruolo NON obbligatorio senza nessuno non è un allarme", () => {
    /* il dirigente delegato è una figura che può non esserci: un rosso lì
       insegnerebbe a ignorare i rossi */
    const o = scudo.organigrammaSicurezza([], LAV, [], OGGI).find((x) => !x.ruolo.obbligatoria);
    eq(o.mancante, false, "non manca: non è dovuto");
    eq(o.stato, "mute", "e resta spento");
  });
}

/* ══ I DPI: UN ELENCO DI CONSEGNE CHE DICE CHI È SCOPERTO ═══════════════
   Il registro dei dispositivi di protezione non serve a niente se dice solo
   quello che è stato consegnato: la domanda vera è **chi è scoperto**. Qui si
   incrociano le mansioni (che dicono quali DPI servono) con le consegne
   registrate.

   ⚠️ Nota di parentela: `allarmiDpi` **salta** i lavoratori non più in forza
   (`if (!l || l.attivo === false) continue`), ed è la guardia che
   nell'organigramma delle nomine **mancava** — il difetto corretto un'unità fa.
   Qui c'era già: si scrive la prova perché resti. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const ELMETTO = scudo.TIPI_DPI[0];
  const OTO = scudo.TIPI_DPI.find((t) => t.addestramento);   // otoprotettori: addestramento obbligatorio
  const LAV = [{ id: "L1", nome: "Mario", attivo: true }, { id: "L2", nome: "Anna", attivo: false },
    { id: "L3", nome: "Bruno", attivo: true }];
  const MANS = [{ id: "m1", nome: "Fochino", lavoratoriIds: ["L1", "L2", "L3"],
    dpi: [ELMETTO.chiave, OTO.chiave] }];

  test("⛔ dpi: chi non ha mai ricevuto un dispositivo richiesto è scoperto, in rosso", () => {
    const a = scudo.allarmiDpi(MANS, LAV, [], OGGI);
    eq(a.length, 4, "due persone in forza per due dispositivi");
    eq(a.every((x) => x.gravita === "danger"), true, "e «mai consegnato» è rosso");
  });
  test("⛔ dpi: chi non è più in forza non compare fra gli scoperti", () => {
    /* è la guardia che nell'organigramma delle nomine mancava: qui c'era già,
       e questa prova serve a tenerla */
    const a = scudo.allarmiDpi(MANS, LAV, [], OGGI);
    eq(a.some((x) => x.lavoratoreId === "L2"), false, "Anna ha lasciato l'azienda");
  });
  test("⛔ dpi: due problemi sullo stesso dispositivo stanno in UNA riga sola", () => {
    /* due righe uguali una sotto l'altra sembrano un errore del programma, e
       chi legge non capisce se sono due elmetti o due volte lo stesso */
    const c = [{ id: "c1", lavoratoreId: "L1", tipo: OTO.chiave, dataConsegna: "2020-01-01",
      scadenza: "2024-01-01", addestramento: false }];
    const righe = scudo.allarmiDpi(MANS, LAV, c, OGGI)
      .filter((x) => x.lavoratoreId === "L1" && x.tipo === OTO.chiave);
    eq(righe.length, 1, "una riga");
    eq(righe[0].motivo, "da sostituire · addestramento non registrato", "coi due motivi dentro");
    eq(righe[0].gravita, "danger", "e il più grave dei due vince");
  });
  test("dpi: con tutto consegnato e addestrato non si allarma nessuno", () => {
    const c = [{ id: "c2", lavoratoreId: "L1", tipo: ELMETTO.chiave, dataConsegna: "2026-01-01", scadenza: "2028-01-01" },
      { id: "c3", lavoratoreId: "L1", tipo: OTO.chiave, dataConsegna: "2026-01-01", scadenza: "2028-01-01", addestramento: true }];
    eq(scudo.allarmiDpi(MANS, LAV, c, OGGI).filter((x) => x.lavoratoreId === "L1").length, 0, "niente da sistemare");
  });
  test("⛔ dpi: l'addestramento mancante emerge anche FUORI da una mansione", () => {
    /* un dispositivo che richiede addestramento consegnato senza è una cosa
       fuori posto comunque, anche se nessuna mansione lo richiede */
    const c = [{ id: "c4", lavoratoreId: "L3", tipo: OTO.chiave, dataConsegna: "2026-01-01",
      scadenza: "2028-01-01", addestramento: false }];
    const a = scudo.allarmiDpi([], LAV, c, OGGI);
    eq(a.length, 1, "una riga anche senza mansioni");
    eq(a[0].motivo, "addestramento non registrato", "col suo motivo");
  });
  test("dpi: la consegna che conta è l'ULTIMA, non la prima registrata", () => {
    const c = [{ id: "x1", lavoratoreId: "L1", tipo: "elmetto", dataConsegna: "2024-01-01" },
      { id: "x2", lavoratoreId: "L1", tipo: "elmetto", dataConsegna: "2026-01-01" }];
    eq(scudo.ultimaConsegnaDpi(c, "L1", "elmetto").id, "x2", "quella del 2026");
  });
  test("dpi: il riepilogo separa i tre motivi", () => {
    const c = [{ id: "c1", lavoratoreId: "L1", tipo: OTO.chiave, dataConsegna: "2020-01-01",
      scadenza: "2024-01-01", addestramento: false }];
    const r = scudo.riepilogoDpi(c, scudo.allarmiDpi(MANS, LAV, c, OGGI));
    eq(r.mancanti, 3, "tre mai consegnati");
    eq(r.daSostituire, 1, "uno da sostituire");
    eq(r.addestramenti, 1, "e un addestramento non registrato");
  });
  test("⛔ verbale: il foglio della persona parte dalla consegna più recente", () => {
    /* è il documento che in ispezione viene chiesto per primo: in cima ci va
       quello che vale adesso */
    const c = [{ id: "x1", lavoratoreId: "L1", tipo: "elmetto", dataConsegna: "2024-01-01" },
      { id: "x2", lavoratoreId: "L1", tipo: "elmetto", dataConsegna: "2026-01-01" }];
    const v = scudo.verbaleDpi({ id: "L1" }, c, OGGI);
    eq(v.righe[0].consegna.id, "x2", "la più recente in cima");
    eq(v.righe.length, 2, "e la storia resta tutta");
  });
}

/* ══ LE ISPEZIONI PERIODICHE ════════════════════════════════════════════
   Il terzo ingresso del registro delle azioni correttive, dopo gli eventi e i
   due ponti ambientali: da una voce **non conforme** nasce un'azione.

   La regola più importante non riguarda i conteggi, riguarda il **tempo**: le
   voci del modello vengono **copiate dentro** l'ispezione. Un modello che
   cambia domani non deve riscrivere le ispezioni già fatte — **un controllo
   firmato non si modifica a posteriori**, e un'ispezione che cambiasse forma
   dopo la firma non varrebbe niente davanti a nessuno. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const CHIAVE = scudo.MODELLI_ISPEZIONE[0].chiave;

  test("⛔ ispezione: le voci del modello sono COPIATE, non collegate", () => {
    /* la copia è quello che rende il controllo un documento e non una vista su
       un modello che intanto è cambiato */
    const isp = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-07-31" });
    const modello = scudo.modelloIspezione(CHIAVE);
    eq(isp.voci.length, modello.voci.length, "tutte le voci del modello");
    eq(isp.voci[0].testo, modello.voci[0], "col loro testo");
    eq(isp.voci[0].id, "v1", "e un id proprio dell'ispezione");
    eq(Array.isArray(isp.voci) && isp.voci !== modello.voci, true, "un elenco nuovo, non lo stesso oggetto");
  });
  test("ispezione: nasce in corso, senza esiti e senza data di chiusura", () => {
    const isp = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-07-31" });
    eq(isp.stato, "in-corso", "in corso");
    eq(Object.keys(isp.esiti).length, 0, "nessun esito già messo");
    eq(isp.dataChiusura, null, "e nessuna chiusura");
  });
  test("ispezione: un modello che non esiste non produce un'ispezione vuota", () => {
    eq(scudo.nuovaIspezioneDaModello("inventato"), null, "null, non un guscio senza voci");
  });
  test("⛔ ispezione: quello che manca si conta, non si dà per conforme", () => {
    /* una voce non ancora spuntata è «da fare»: contarla come conforme
       renderebbe completo un controllo che nessuno ha finito */
    const isp = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-07-31" });
    isp.esiti[isp.voci[0].id] = { esito: "conforme" };
    isp.esiti[isp.voci[1].id] = { esito: "non-conforme", nota: "sbarramento caduto" };
    const r = scudo.riepilogoIspezione(isp);
    eq(r.conformi, 1, "una conforme");
    eq(r.nonConformi, 1, "una no");
    eq(r.daFare, isp.voci.length - 2, "e tutte le altre restano da fare");
    eq(r.completa, false, "quindi non è completa");
  });
  test("ispezione: «non applicabile» è una risposta data, non una mancante", () => {
    const isp = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-07-31" });
    for (const v of isp.voci) isp.esiti[v.id] = { esito: "na" };
    const r = scudo.riepilogoIspezione(isp);
    eq(r.na, isp.voci.length, "tutte non applicabili");
    eq(r.completa, true, "il controllo è comunque finito");
    eq(r.percento, 100, "e si vede");
  });
  test("⛔ ispezione: le voci non conformi portano con sé la nota", () => {
    /* la nota è quello che diventa la descrizione dell'azione correttiva:
       perderla lascerebbe un compito senza il fatto che l'ha generato */
    const isp = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-07-31" });
    isp.esiti[isp.voci[1].id] = { esito: "non-conforme", nota: "  sbarramento caduto  " };
    const nc = scudo.vociNonConformi(isp);
    eq(nc.length, 1, "una voce");
    eq(nc[0].nota, "sbarramento caduto", "con la nota, ripulita dagli spazi");
    eq(nc[0].testo, isp.voci[1].testo, "e col testo della voce");
  });
  test("⛔ ispezione: un'ispezione COMPLETATA non è più in ritardo", () => {
    /* è finita: tenerla rossa è lo stesso allarme che nessuno può togliere
       delle azioni correttive */
    eq(scudo.statoIspezione({ stato: "completata", data: "2026-01-01" }, OGGI), "regolare", "fatta a gennaio");
    eq(scudo.statoIspezione({ stato: "in-corso", data: "2026-01-01" }, OGGI), "scaduta", "una non finita invece sì");
  });
  test("⛔ ispezione: senza data programmata è «senza data», non regolare", () => {
    // stessa correzione di `statoAzione`: un'ispezione di cui non si sa quando
    // va fatta non è un'ispezione in ordine
    eq(scudo.statoIspezione({ stato: "in-corso", data: "" }, OGGI), "senza data", "manca la data");
    eq(scudo.statoIspezione({ stato: "programmata", data: null }, OGGI), "senza data", "e il null");
    ok(scudo.statoIspezione({ stato: "in-corso", data: "" }, OGGI) !== "regolare", "niente verde");
    // una COMPLETATA resta regolare: è finita, la sua data non conta più
    eq(scudo.statoIspezione({ stato: "completata", data: "" }, OGGI), "regolare", "completata senza data");
  });
  test("⛔ ispezioni: il riepilogo somma le non conformità di TUTTE, anche delle chiuse", () => {
    /* una non conformità trovata resta un fatto anche dopo che l'ispezione è
       stata chiusa: è da lì che nascono le azioni */
    const a = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-01-01", stato: "completata" });
    a.esiti[a.voci[0].id] = { esito: "non-conforme", nota: "x" };
    const b = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-01-15" });
    b.esiti[b.voci[0].id] = { esito: "non-conforme", nota: "y" };
    const r = scudo.riepilogoIspezioni([a, b], OGGI);
    eq(r.totale, 2, "due ispezioni");
    eq(r.completate, 1, "una completata");
    eq(r.scadute, 1, "e una non finita che era di gennaio");
    eq(r.nonConformi, 2, "le non conformità si contano tutte e due");
  });
  /* ⛔ UNA VOCE SENZA ESITO NON È UNA VOCE CONFORME. Un'ispezione si chiude
     anche con delle voci indietro (la modale lo dice, «resteranno così»), ma
     dopo restava solo il verde «Completata» e il conto delle non conformi
     TROVATE: zero non conformi su una checklist guardata a metà è il numero
     tranquillo dove non è stato misurato niente. */
  test("⛔ ispezioni: le voci chiuse senza esito si contano, non spariscono nel verde", () => {
    const a = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-01-01", stato: "completata" });
    a.esiti[a.voci[0].id] = { esito: "conforme", nota: "" };   // una sola voce su tutte
    const tot = a.voci.length;
    const r = scudo.riepilogoIspezioni([a], OGGI);
    eq(r.completate, 1, "risulta completata");
    eq(r.parziali, 1, "ma è una di quelle chiuse a metà");
    eq(r.senzaEsito, tot - 1, "e le voci mai giudicate si contano tutte");
    eq(r.nonConformi, 0, "le non conformi TROVATE restano zero: è vero, ed è il punto");
    ok(r.senzaEsito > 0, "senza questo conto lo zero qui sopra sembra un'ispezione a posto");
    // una chiusa DAVVERO completa non conta niente
    const b = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-01-01", stato: "completata" });
    for (const v of b.voci) b.esiti[v.id] = { esito: "na", nota: "" };
    const rb = scudo.riepilogoIspezioni([b], OGGI);
    eq(rb.parziali, 0, "tutte le voci hanno un esito, anche se è «non applicabile»");
    eq(rb.senzaEsito, 0, "niente da dichiarare");
    // e una ancora APERTA non è una mancanza: è lavoro in corso
    const c = scudo.nuovaIspezioneDaModello(CHIAVE, { data: "2026-01-15" });
    eq(scudo.riepilogoIspezioni([c], OGGI).senzaEsito, 0, "un'ispezione in corso non si accusa");
  });
  test("ispezioni: i tre esiti hanno il colore del semaforo di tutta l'app", () => {
    eq(scudo.esitoLabel("conforme").cls, "ok", "verde");
    eq(scudo.esitoLabel("non-conforme").cls, "danger", "rosso");
    eq(scudo.esitoLabel("na").cls, "tag", "e «non applicabile» non è né l'uno né l'altro");
    eq(scudo.esitoLabel("boh"), null, "un esito inventato non esiste");
  });
}

/* ══ IL NEAR-MISS, E IL MURO DELLE SCADENZE ═════════════════════════════
   Un mancato infortunio si segnala **in piedi sul piazzale, con i guanti**, in
   pochi secondi — o non lo segnala nessuno. Da lì la scelta: si TOCCA una
   categoria e un luogo invece di scrivere, e la segnalazione è già completa.

   Le funzioni qui sotto sono quello che rende possibile quella scelta: la
   descrizione si compone da sola, e il riepilogo **dichiara quando i numeri
   sono troppo pochi** per leggerci una tendenza invece di disegnare un grafico
   che suggerisce andamenti inesistenti. */
{
  const OGGI = new Date("2026-07-31T12:00:00");

  test("⛔ near-miss: da due tocchi esce già una frase leggibile", () => {
    /* la segnalazione deve restare leggibile nel registro anche se è costata
       tre tocchi: una riga vuota nel registro degli eventi non serve a nessuno */
    eq(scudo.descrizioneNearMiss({ categoria: "caduta-massi", luogoTipo: "fronte" }),
       "Caduta massi — Fronte", "categoria e luogo");
    eq(scudo.descrizioneNearMiss({ categoria: "caduta-massi" }), "Caduta massi", "o la sola categoria");
    eq(scudo.descrizioneNearMiss({}), "Near-miss segnalato", "e senza niente resta comunque una frase");
  });
  test("near-miss: quello che scrive la persona vince su quello che compone l'app", () => {
    eq(scudo.descrizioneNearMiss({ categoria: "caduta-massi", luogoTipo: "fronte",
      dettaglio: "  masso caduto vicino alla pala  " }), "masso caduto vicino alla pala",
      "le sue parole, ripulite dagli spazi");
  });
  test("near-miss: il luogo scritto a mano vale quanto quello toccato", () => {
    eq(scudo.descrizioneNearMiss({ categoria: "caduta-massi", luogo: "Fronte nord" }),
       "Caduta massi — Fronte nord", "il registro di sempre continua a funzionare");
  });

  const eventi = [
    { id: "e1", tipo: "near-miss", data: "2026-07-20", categoria: "caduta-massi", luogoTipo: "fronte" },
    { id: "e2", tipo: "near-miss", data: "2026-07-25", categoria: "caduta-massi", luogo: "Piazzale ovest" },
    { id: "e3", tipo: "near-miss", data: "2026-01-01", categoria: "mezzi", luogoTipo: "pista" },
    { id: "e4", tipo: "infortunio", data: "2026-07-10", categoria: "mezzi" },
    { id: "e5", tipo: "near-miss", data: "2026-07-28", anonimo: true }];
  const azioni = [{ origineTipo: "evento", origineId: "e1" }, { origineTipo: "evento", origineId: "e1" },
    { origineTipo: "ispezione", origineId: "e2" }];

  test("⛔ near-miss: il riepilogo guarda SOLO i near-miss, non gli infortuni", () => {
    /* sono due registri diversi con due significati diversi: mescolarli
       gonfierebbe un conteggio che la legge chiede separato */
    const r = scudo.riepilogoNearMiss(eventi, azioni, 90, OGGI);
    eq(r.totale, 3, "tre nel periodo");
    eq(r.totaleStorico, 4, "quattro in tutto: l'infortunio resta fuori da entrambi");
  });
  test("near-miss: fuori dal periodo si conta nello storico, non nel periodo", () => {
    eq(scudo.riepilogoNearMiss(eventi, azioni, null, OGGI).totale, 4, "senza finestra ci sono tutti");
  });
  test("⛔ near-miss: una segnalazione senza categoria non sparisce dal conto", () => {
    /* finisce sotto «Non classificato»: toglierla farebbe sembrare che si
       segnali meno di quanto si segnala */
    const r = scudo.riepilogoNearMiss(eventi, azioni, 90, OGGI);
    eq(r.perTipo.some((x) => x.etichetta === "Non classificato"), true, "c'è, e si vede che manca il dato");
    eq(r.perTipo.reduce((s, x) => s + x.valore, 0), r.totale, "e la somma torna col totale");
    eq(r.perLuogo.reduce((s, x) => s + x.valore, 0), r.totale, "anche per luogo");
  });
  test("⛔ near-miss: due azioni sullo stesso evento sono UN evento con azione", () => {
    /* «quante segnalazioni hanno prodotto un'azione» è un conto di eventi, non
       di azioni: contare le azioni farebbe sembrare seguito un registro dove
       una sola segnalazione ne ha generate due */
    const r = scudo.riepilogoNearMiss(eventi, azioni, 90, OGGI);
    eq(r.conAzione, 1, "un evento seguito");
    eq(r.azioni, 2, "da due azioni");
    eq(r.senzaAzione, 2, "e due segnalazioni restate senza");
  });
  test("⛔ near-miss: con pochi numeri lo si DICE, invece di disegnare una tendenza", () => {
    eq(scudo.riepilogoNearMiss(eventi, azioni, 90, OGGI).pochi, true,
       "tre segnalazioni non sono un andamento");
  });
  test("near-miss: le anonime si contano, perché è la garanzia che le fa arrivare", () => {
    eq(scudo.riepilogoNearMiss(eventi, azioni, 90, OGGI).anonime, 1, "una anonima");
  });

  test("⛔ muro: una scadenza già passata non finisce in un mese futuro", () => {
    /* metterla nel mese in cui cadeva la nasconderebbe fra le cose da fare più
       avanti: le scadute hanno un contatore tutto loro */
    const sc = [{ dataScadenza: "2026-06-01" }, { dataScadenza: "2026-08-15" },
      { dataScadenza: "2026-08-20" }, { dataScadenza: "2028-01-01" }, { dataScadenza: "boh" }];
    const m = scudo.muroScadenze(sc, OGGI, 12);
    eq(m.scadute, 1, "quella di giugno è scaduta");
    eq(m.fuori, 1, "quella del 2028 è oltre l'orizzonte, e si dice");
    eq(m.totale, 4, "la data illeggibile non si conta nemmeno");
    eq(m.mesi.find((x) => x.chiave === "2026-08").totale, 2, "e due cadono ad agosto");
  });
  test("muro: i mesi ci sono tutti, anche quelli vuoti", () => {
    /* un mese saltato farebbe sembrare il muro più basso di com'è */
    const m = scudo.muroScadenze([], OGGI, 12);
    eq(m.mesi.length, 12, "dodici mesi");
    eq(m.da, "2026-07", "dal mese in corso");
  });
  test("⛔ periodicità: la data proposta non cade in un giorno che non esiste", () => {
    /* dal 31 gennaio, «fra un mese» non è il 31 febbraio */
    eq(scudo.dataDaPeriodicita(1, new Date("2026-01-31T12:00:00")), "2026-02-28", "l'ultimo giorno che c'è");
    eq(scudo.dataDaPeriodicita(12, OGGI), "2027-07-31", "e a dodici mesi è lo stesso giorno dell'anno dopo");
  });
  test("periodicità: senza un numero di mesi non si propone una data", () => {
    eq(scudo.dataDaPeriodicita(0, OGGI), null, "zero non è una periodicità");
    eq(scudo.dataDaPeriodicita("boh", OGGI), null, "e nemmeno una parola");
  });
}

/* ══ LA CHIUSURA DEL TURNO: LA FIRMA DELLA CONSEGNA ═════════════════════
   Il rapporto di fine turno diventa un **documento** quando porta un nome e
   un'ora: chi consegna, chi riceve, quando. È quello che, in caso di
   contestazione, distingue un appunto da una consegna fatta.

   E una firma vale qualcosa **solo se dopo la firma il documento non cambia
   più**: `turnoChiuso` è la funzione che ogni punto di salvataggio deve
   chiedere prima di scrivere. Con due regole che tirano in direzioni opposte e
   vanno tenute insieme:

   · **chiuso vuol dire chiuso** — nessuno ci scrive più sopra;
   · **i dati vecchi restano modificabili.** Una registrazione senza giorno o
     senza turno — salvata prima che quei campi esistessero — non appartiene a
     nessun turno chiuso. Nessuna azienda si ritrova i propri dati bloccati
     dall'oggi al domani per un aggiornamento del programma. */
{
  const chiusure = [
    { id: "c1", data: "2026-07-30", turno: "Mattina", consegna: "Mario", ricevuta: "Anna", ora: "14:05" },
    { id: "c2", data: "2026-07-31", turno: "Mattina", consegna: "Bruno", ricevuta: "", ora: "" },
    { id: "c3", data: "2026-07-30", turno: "Mattina", consegna: "Mario", ricevuta: "Carla", ora: "14:20",
      riaperture: [{ da: "Mario Bianchi", il: "2026-07-30", ora: "15:10", motivo: "dimenticati i minuti di fermo" }] },
    /* una chiusura VECCHIA, salvata prima che esistessero giorno e turno.
       Senza questa riga la prova qui sotto non proverebbe niente: la guardia
       `if (!d || !t) return null` non avrebbe niente da fermare, e il filtro su
       una data vuota basterebbe da solo. È lo stesso difetto già trovato oggi
       sulla lettura «più recente, non più alta». */
    { id: "c0", data: "", turno: "", consegna: "Vecchio", ricevuta: "Registro", ora: "12:00" }];

  test("⛔ chiusura: un turno con la firma e l'ora è CHIUSO", () => {
    eq(campo.turnoChiuso(chiusure, "2026-07-30", "Mattina").id, "c3", "chiuso, e vale l'ultima registrata");
  });
  test("⛔ chiusura: senza l'ORA il turno non è chiuso", () => {
    /* la riga c'è ma la firma no: è un foglio compilato a metà, e bloccarci
       sopra le scritture fermerebbe il lavoro senza che nessuno abbia firmato */
    eq(campo.turnoChiuso(chiusure, "2026-07-31", "Mattina"), null, "aperto");
  });
  test("⛔ chiusura: i dati vecchi senza giorno o turno restano modificabili", () => {
    /* regola ferrea di compatibilità: nessuna azienda si ritrova i propri dati
       bloccati dall'oggi al domani per un aggiornamento del programma */
    eq(campo.turnoChiuso(chiusure, "", "Mattina"), null, "senza giorno non appartiene a nessun turno chiuso");
    eq(campo.turnoChiuso(chiusure, "2026-07-30", ""), null, "e nemmeno senza turno");
  });
  test("chiusura: fra due chiusure dello stesso turno vale l'ULTIMA", () => {
    eq(campo.chiusuraDi(chiusure, "2026-07-30", "Mattina").ricevuta, "Carla", "la consegna corretta");
  });
  test("⛔ chiusura: il riassunto dice chi consegna, a chi e a che ora", () => {
    eq(campo.riassuntoChiusura(chiusure[2]), "Consegnato da Mario a Carla alle 14:20", "la frase intera");
    eq(campo.riassuntoChiusura({ consegna: "Mario", ora: "14:00" }), "Consegnato da Mario alle 14:00",
       "e con un nome solo non resta una preposizione appesa");
    eq(campo.riassuntoChiusura(chiusure[1]), "", "senza ora non c'è niente da riassumere");
  });

  test("⛔ riapertura: la traccia resta, sempre", () => {
    /* è quello che rende la correzione alla luce del sole invece che di
       nascosto: le riaperture non si cancellano mai */
    eq(campo.riaperture(chiusure[2]).length, 1, "una riapertura");
    eq(campo.riaperture(chiusure[0]).length, 0, "e chi non ne ha non ne inventa");
    eq(campo.riaperture(null).length, 0, "nemmeno senza chiusura");
  });
  test("riapertura: la riga dice chi, quando e perché", () => {
    eq(campo.riassuntoRiapertura(chiusure[2].riaperture[0], (d) => d.split("-").reverse().join("/")),
       "Riaperto da Mario Bianchi il 30/07/2026 alle 15:10 — dimenticati i minuti di fermo",
       "tutto quello che serve a capire la correzione");
    eq(campo.riassuntoRiapertura({ da: "Anna", ora: "09:00" }), "Riaperto da Anna alle 09:00",
       "e senza motivo non resta un trattino sospeso");
  });
  test("riapertura: l'ultima è quella che conta per lo stato attuale", () => {
    eq(campo.ultimaRiapertura(chiusure[2]).ora, "15:10", "la più recente");
    eq(campo.ultimaRiapertura(chiusure[0]), null, "e senza riaperture è null, non un oggetto vuoto");
  });

  test("⛔ turno: quello suggerito segue l'ora, e la notte attraversa la mezzanotte", () => {
    /* chi registra non deve sceglierlo ogni volta: 6-14 mattina, 14-22
       pomeriggio, il resto notte — e alle 3 si è ancora nel turno di notte */
    eq(campo.turnoCorrente(new Date(2026, 6, 31, 6, 0)), "Mattina", "le sei");
    eq(campo.turnoCorrente(new Date(2026, 6, 31, 13, 59)), "Mattina", "fino alle due meno un minuto");
    eq(campo.turnoCorrente(new Date(2026, 6, 31, 14, 0)), "Pomeriggio", "le quattordici");
    eq(campo.turnoCorrente(new Date(2026, 6, 31, 22, 0)), "Notte", "le ventidue");
    eq(campo.turnoCorrente(new Date(2026, 6, 31, 3, 0)), "Notte", "e le tre di mattina sono ancora notte");
  });
  test("turno: i tre turni sono quelli che usa il rapportino", () => {
    eq(campo.TURNI.join(","), "Mattina,Pomeriggio,Notte", "e nient'altro");
  });
}

/* ══ L'INIZIO DEL TURNO: LA CHECKLIST E L'APPELLO ═══════════════════════
   Due cose si fanno prima di cominciare: si controlla che il posto sia sicuro,
   e si guarda **chi c'è**.

   ⛔ La regola più affilata di tutta l'app sta nell'appello, ed è scritta nel
   modulo: **«non lo so» è una risposta diversa da «non c'è».** Chi non è ancora
   stato spuntato non viene contato né presente né assente — perché se suona
   l'allarme e si va al punto di raccolta, l'appello si fa su questa lista, e
   contare per assente qualcuno che nessuno ha guardato vuol dire non andarlo a
   cercare. */
{
  const OGGI = "2026-07-31";
  const operatori = [
    { id: "o1", nome: "Anna", squadra: "Squadra A — Perforazione", stato: "in-forza" },
    { id: "o2", nome: "Bruno", squadra: "Squadra A", stato: "in-forza" },
    { id: "o3", nome: "Carla", squadra: "Squadra A", stato: "non-disponibile" },
    { id: "o4", nome: "Dario", squadra: "Squadra B", stato: "in-forza" }];
  const presenze = [{ data: OGGI, turno: "Mattina", operatoreId: "o1", stato: "presente", ora: "06:05" }];

  test("⛔ appello: chi non è stato spuntato NON è un assente", () => {
    /* su un appello di emergenza la differenza è tutto: contare per assente
       qualcuno che nessuno ha guardato vuol dire non andarlo a cercare */
    const a = campo.appelloTurno(operatori, presenze, OGGI, "Mattina", "Squadra A");
    eq(a.presenti, 1, "una presente");
    eq(a.assenti, 0, "nessun assente");
    eq(a.daFare, 1, "e uno ancora da guardare");
    eq(a.completo, false, "quindi l'appello non è finito");
  });
  test("⛔ appello: chi non è disponibile non entra nella lista da spuntare", () => {
    /* è in anagrafica ma oggi non è al lavoro: chiederne la presenza
       allungherebbe la lista con una domanda che non ha risposta */
    const a = campo.appelloTurno(operatori, presenze, OGGI, "Mattina", "Squadra A");
    eq(a.righe.some((r) => r.operatore.id === "o3"), false, "Carla non c'è nell'elenco");
    eq(a.totale, 2, "restano due persone da spuntare");
  });
  test("appello: la squadra si riconosce anche col nome esteso", () => {
    /* «Squadra A — Perforazione» e «Squadra A» sono la stessa squadra: chi
       scrive il nome per esteso non deve sparire dall'appello */
    const a = campo.appelloTurno(operatori, presenze, OGGI, "Mattina", "Squadra A");
    eq(a.righe.some((r) => r.operatore.nome === "Anna"), true, "Anna c'è");
  });
  test("appello: senza squadra si guarda tutta la cava", () => {
    eq(campo.appelloTurno(operatori, presenze, OGGI, "Mattina", "").totale, 3,
       "tutti quelli in forza, di ogni squadra");
  });
  test("appello: fra due spunte della stessa persona vale l'ULTIMA", () => {
    const due = [{ data: OGGI, turno: "Mattina", operatoreId: "o1", stato: "presente", ora: "06:05" },
      { data: OGGI, turno: "Mattina", operatoreId: "o1", stato: "assente", ora: "06:40" }];
    eq(campo.presenzaDi(due, OGGI, "Mattina", "o1").stato, "assente", "la correzione conta");
  });
  test("appello: un appello vuoto non è un appello completo", () => {
    eq(campo.appelloTurno([], [], OGGI, "Mattina", "").completo, false,
       "zero persone spuntate su zero non è «fatto»");
  });

  test("⛔ checklist: quello che non è stato spuntato NON risulta a posto", () => {
    /* stessa regola delle ispezioni di Scudo: un controllo mai finito non deve
       sembrare un controllo superato */
    const st = campo.statoChecklist({ 0: "ok", 1: "no" });
    eq(st.ok, 1, "una a posto");
    eq(st.no, 1, "una no");
    eq(st.mancanti, campo.CHECKLIST_INIZIO.length - 2, "e tutte le altre mancano");
    eq(st.completa, false, "quindi non è completa");
  });
  test("⛔ checklist: le voci NON a posto escono con il loro testo", () => {
    /* è quello che il preposto legge e su cui decide se si comincia: un numero
       non dice che cosa non va */
    const st = campo.statoChecklist({ 1: "no" });
    eq(st.problemi.length, 1, "un problema");
    eq(st.problemi[0], campo.CHECKLIST_INIZIO[1].testo, "col testo della voce, non l'indice");
  });
  test("checklist: «non applicabile» è una risposta data, e chiude il controllo", () => {
    const esiti = {};
    campo.CHECKLIST_INIZIO.forEach((_, i) => { esiti[i] = "na"; });
    const st = campo.statoChecklist(esiti);
    eq(st.completa, true, "il controllo è finito");
    eq(st.problemi.length, 0, "e non c'è niente da segnalare");
    eq(st.pct, 100, "cento per cento");
  });
  test("checklist: gli esiti si leggono sia con la chiave testo sia con quella numero", () => {
    /* come sono salvati nel database, senza costringere la pagina a
       normalizzare prima di chiedere */
    eq(campo.statoChecklist({ "0": "ok" }).ok, 1, "chiave testo");
    eq(campo.statoChecklist({ 0: "ok" }).ok, 1, "chiave numero");
  });

  test("⛔ giorno: una registrazione SENZA data appartiene a tutti i giorni", () => {
    /* i dati salvati prima che la data esistesse non devono sparire dagli
       elenchi: è la stessa compatibilità del turno chiuso */
    eq(campo.eDelGiorno({ titolo: "vecchia" }, OGGI), true, "una riga senza data si vede");
    eq(campo.eDelGiorno({ data: "2026-07-30" }, OGGI), false, "una di ieri no");
    eq(campo.diGiorno([{ data: OGGI }, { data: "2026-07-30" }, {}], OGGI).length, 2, "oggi e la senza data");
  });
  test("giorno: quante righe sono ancora senza data si dice, invece di nasconderle", () => {
    eq(campo.senzaData([{ data: OGGI }, {}, { data: "  " }]), 2, "due da sistemare");
  });
}

/* ══ IL BADGE DEL TAGLIANDO A ORE: L'ULTIMO ZERO DI COMODO ══════════════
   `tagliandiInScadenza` lo aveva già capito, e l'aveva scritto nel commento:
   *«zero ore» e «non lo so» sono due cose diverse: con `|| 0` un mezzo senza
   contatore diventava un mezzo nuovo di fabbrica, e il tagliando sembrava
   lontano.* Là il mezzo senza contatore finisce fra quelli **da stimare**, con
   il perché.

   Ma il **badge della lista Manutenzioni** passava ancora da `urgenzaOre` con
   le ore convertite a zero: su un mezzo di cui non sappiamo il contatore
   mostrava **«tra 500 h» in verde** — un colore tranquillo dove non è stato
   misurato niente. È il principio scritto in `CLAUDE.md`, e il terzo `+null`
   della giornata. */
{
  test("⛔ tagliando a ore: senza contatore NON si dice che manca tanto", () => {
    for (const ignoto of [null, undefined, ""]) {
      const u = flotta.urgenzaOre(500, ignoto);
      eq(u.mancano, null, "non si sa quanto manca");
      eq(u.oreNote, false, "e si sa di non saperlo");
      eq(u.cls, "", "niente verde rassicurante");
    }
  });
  test("⛔ tagliando a ore: il badge dice comunque a quante ore è previsto", () => {
    /* la stessa frase che la pagina usa quando il mezzo non è nel parco: chi
       guarda deve capire che il tagliando c'è, non che è lontano */
    eq(flotta.urgenzaOre(500, null).label, "a 500 h", "il dato che abbiamo, e nient'altro");
  });
  test("tagliando a ore: con il contatore noto il conto è quello di sempre", () => {
    eq(flotta.urgenzaOre(6000, 5990).cls, "warn", "dieci ore: preavviso");
    eq(flotta.urgenzaOre(6000, 5990).mancano, 10, "e quante ne mancano");
    eq(flotta.urgenzaOre(6000, 6040).cls, "danger", "già passate: scaduta");
    eq(flotta.urgenzaOre(6000, 5000).cls, "ok", "mille ore: lontano davvero");
  });
  test("tagliando a ore: un contatore di ZERO è un dato, non un'assenza", () => {
    /* una macchina nuova ha davvero zero ore: la differenza fra «zero» e «non
       lo so» va tenuta in tutte e due le direzioni */
    const u = flotta.urgenzaOre(500, 0);
    eq(u.oreNote, true, "lo zero è una lettura");
    eq(u.mancano, 500, "e il conto si fa");
  });
}

/* ══ TERRA: LO SCAVO CONSUMA IL CONCESSO, LA RIPRESA NO ═════════════════
   È la distinzione che regge tutta l'app, e sta anche nei moduli degli enti:
   il materiale **tolto dal fronte** consuma il volume autorizzato; quello
   **ripreso da un cumulo** era già stato estratto e si conta a parte. Contarli
   insieme farebbe risultare esaurita una concessione che non lo è — o, peggio,
   nasconderebbe un esaurimento vero sotto un numero gonfiato dai cumuli. */
{
  const OGGI = new Date("2026-07-31T12:00:00");
  const R = (o) => ({ id: "r1", data: "2026-07-01", stato: "elaborato", volumeM3: 10000, fronteId: "f1", ...o });
  const rilievi = [
    R({ id: "a", data: "2026-05-01", volumeM3: 5000 }),
    R({ id: "b", data: "2026-06-01", volumeM3: 8000 }),
    R({ id: "c", data: "2026-07-01", volumeM3: 12000 }),
    R({ id: "d", data: "2026-07-15", volumeM3: 50000, provenienza: "cumulo" }),
    R({ id: "e", data: "2026-07-20", volumeM3: 3000, fronteId: "f2" }),
    R({ id: "f", data: "2026-07-25", volumeM3: 1000, stato: "da-elaborare" })];

  test("⛔ provenienza: la ripresa dai cumuli si separa dallo scavo", () => {
    eq(terra.soloCumulo(rilievi).map((r) => r.id).join(","), "d", "solo quello dal cumulo");
    eq(terra.soloScavo(rilievi).some((r) => r.id === "d"), false, "e lo scavo non lo comprende");
  });
  test("provenienza: senza il campo, un rilievo è SCAVO", () => {
    /* è il valore che consuma il concesso: dare per «cumulo» quello che non è
       dichiarato farebbe sparire volume vero dal conto della concessione */
    eq(terra.etichettaProvenienza(""), "Scavo dal fronte", "il valore di partenza");
    eq(terra.etichettaProvenienza("boh"), "Scavo dal fronte", "e anche una parola sconosciuta");
    eq(terra.etichettaProvenienza("cumulo"), "Ripresa da un cumulo", "il cumulo va dichiarato");
  });
  test("⛔ ritmo: il grafico mensile conta lo SCAVO, non i cumuli ripresi", () => {
    /* i 50.000 m³ ripresi dal cumulo a luglio raddoppierebbero la barra e
       farebbero sembrare che si stia scavando il triplo */
    const m = terra.volumiPerMese(rilievi, 12, OGGI);
    eq(m.find((x) => x.ym === "2026-07").volume, 15000, "luglio: 12.000 dal fronte f1 più 3.000 da f2");
    eq(m.map((x) => x.ym).join(","), "2026-05,2026-06,2026-07", "e si parte dal primo mese con dati");
  });
  test("ritmo: i mesi vuoti in mezzo restano, quelli davanti no", () => {
    /* un mese a zero in mezzo è un'informazione (non si è scavato); dodici mesi
       vuoti prima del primo rilievo sono solo un grafico che comincia lontano */
    const soloLuglio = terra.volumiPerMese([R({ id: "z", data: "2026-07-10", volumeM3: 100 })], 12, OGGI);
    eq(soloLuglio.length, 1, "un mese solo");
  });

  test("⛔ confronto: fra due rilievi si somma quello scavato IN MEZZO", () => {
    /* la differenza fra i due volumi non è quanto si è scavato: è quanto è
       cambiato il volume del fronte. Lo scavato è la somma dei rilievi
       intermedi, ed è quello che consuma la concessione */
    const c = terra.confrontoRilievi(rilievi, "a", "c");
    eq(c.giorni, 61, "due mesi fra i due voli");
    eq(c.scavato, 20000, "8.000 di giugno più 12.000 di luglio");
    eq(c.rilieviInMezzo, 2, "due rilievi in mezzo");
    eq(c.delta, 7000, "e la differenza fra i due volumi è un'altra cosa");
  });
  test("confronto: l'ordine in cui si scelgono i due rilievi non conta", () => {
    eq(terra.confrontoRilievi(rilievi, "c", "a").giorni, 61, "si mette in ordine da solo");
  });
  test("⛔ confronto: due fronti diversi non si confrontano", () => {
    /* sarebbe una differenza fra due posti diversi della cava: un numero che
       non significa niente e che sembra un avanzamento */
    eq(terra.confrontoRilievi(rilievi, "a", "e"), null, "fronti diversi");
    eq(terra.confrontoRilievi(rilievi, "a", "a"), null, "e lo stesso rilievo con sé stesso");
    eq(terra.confrontoRilievi(rilievi, "a", "f"), null, "né uno ancora da elaborare");
  });

  test("⛔ scadenze: «senza data» non è «a posto» per caso, ed è dichiarato", () => {
    const l = terra.livelloScadenzaTerra("", 30, OGGI);
    eq(l.label, "senza data", "lo dice");
    eq(l.giorni, null, "e non inventa un conto alla rovescia");
  });
  test("scadenze: il preavviso lo decide l'utente, e il confine è preciso", () => {
    /* periodicità e termini cambiano da regione a regione: Terra non li
       indovina, li applica */
    eq(terra.statoScadenzaTerra("2026-08-15", 30, OGGI), "in-scadenza", "quindici giorni, preavviso trenta");
    eq(terra.statoScadenzaTerra("2026-08-15", 0, OGGI), "a-posto", "col preavviso a zero è ancora lontana");
    eq(terra.statoScadenzaTerra("2026-07-31", 0, OGGI), "in-scadenza", "ma il giorno stesso sì");
    eq(terra.statoScadenzaTerra("2026-07-30", 30, OGGI), "scaduta", "e ieri è scaduta");
  });
  test("scadenze: la frase dice da quanto è scaduta o quanto manca", () => {
    eq(terra.livelloScadenzaTerra("2026-07-01", 30, OGGI).label, "scaduta da 30 gg", "da quanto");
    eq(terra.livelloScadenzaTerra("2026-08-15", 30, OGGI).label, "tra 15 gg", "quanto manca");
    eq(terra.livelloScadenzaTerra("2026-07-31", 30, OGGI).label, "scade oggi", "e oggi si dice oggi");
  });
  test("scadenze: il riepilogo conta ogni scadenza una volta sola", () => {
    const sc = [{ dataScadenza: "2026-07-01", preavvisoGiorni: 30 }, { dataScadenza: "2026-08-15", preavvisoGiorni: 30 },
      { dataScadenza: "2027-01-01", preavvisoGiorni: 30 }, { dataScadenza: "", preavvisoGiorni: 30 }];
    const r = terra.riepilogoScadenze(sc, OGGI);
    eq(r.scadute + r.inScadenza + r.senzaData + r.aPosto, r.totale, "la somma torna");
    eq(r.totale, 4, "e nessuna cade fuori, nemmeno quella senza data");
    /* ⛔ Corretta il 03/08. Prima la somma era `scadute + inScadenza + aPosto`
       e tornava lo stesso — perché la riga senza data finiva fra le «a posto».
       Il conto quadrava e diceva una cosa falsa: è il modo in cui una riga
       illeggibile spariva dentro il verde. Adesso ha un contatore suo, e la
       prova pretende che ci finisca. */
    eq(r.senzaData, 1, "la riga senza data ha un contatore suo");
    eq(r.aPosto, 1, "e fra le «a posto» resta solo quella davvero a posto");
  });
  test("scadenze: una data con la forma giusta ma impossibile non è «a posto»", () => {
    eq(terra.statoScadenzaTerra("2026-13-45", 30, OGGI), "senza data", "mese 13");
    eq(terra.statoScadenzaTerra("2026-02-30", 30, OGGI), "senza data", "30 febbraio: Date.parse lo accetterebbe");
    eq(terra.livelloScadenzaTerra("", 30, OGGI).cls, "warn", "e il badge non è verde");
    // guardia: le date buone non cambiano
    eq(terra.statoScadenzaTerra("2027-01-01", 30, OGGI), "a-posto", "lontana");
    eq(terra.statoScadenzaTerra("2026-07-01", 30, OGGI), "scaduta", "passata");
  });
  test("⛔ scadenze: i tipi preimpostati dichiarano di essere da verificare", () => {
    /* periodicità e termini stanno nell'atto e nella legge regionale: un
       preset che si desse per certo sarebbe una consulenza sbagliata */
    eq(terra.presetScadenzaTerra("autorizzazione").daVerificare, true, "sempre da verificare");
    eq(terra.presetScadenzaTerra("boh"), null, "e un tipo inventato non esiste");
  });
  test("scadenze: la ricorrenza non propone un giorno che non esiste", () => {
    eq(terra.prossimaData("2026-01-31", 1), "2026-02-28", "dal 31 gennaio, fra un mese");
    eq(terra.prossimaData("2026-07-31", 12), "2027-07-31", "e a dodici mesi lo stesso giorno");
    eq(terra.prossimaData("boh", 1), null, "senza una data vera non si propone niente");
    eq(terra.prossimaData("2026-01-31", 0), null, "e senza ricorrenza nemmeno");
  });
}

/* ══ LE SCADENZE DI LEGGE DEI MEZZI ═════════════════════════════════════
   Revisione alla Motorizzazione, verifica periodica dell'attrezzatura, funi e
   catene, assicurazione. Un mezzo che gira in cava con la verifica scaduta è
   la stessa famiglia del lavoratore senza il corso: un obbligo non rispettato
   che l'app deve far vedere prima che lo veda un ispettore.

   ⛔ E qui il principio di `CLAUDE.md` — **l'assenza di un dato non è un dato
   favorevole** — è già applicato bene, ed è quello che queste prove tengono:
   una scadenza **senza data** è **gialla**, non verde, e nel conteggio sta
   insieme a quelle in scadenza. «Non so quando scade la revisione» è un
   problema, non una tranquillità. */
{
  const OGGI = new Date("2026-07-31T12:00:00");

  test("⛔ scadenze mezzi: «senza data» è GIALLA, non verde", () => {
    /* è la stessa idea di «senza dati» ≠ «conforme»: non sapere quando scade
       la revisione di un mezzo che gira è un problema aperto */
    for (const vuota of ["", null, undefined]) {
      const st = flotta.statoScadenzaMezzo(vuota, OGGI);
      eq(st.stato, "senza-data", "lo dichiara");
      eq(st.cls, "warn", "e resta gialla");
      eq(st.giorni, null, "senza inventare un conto alla rovescia");
    }
  });
  test("⛔ scadenze mezzi: «senza data» si conta con le cose da fare, non con quelle a posto", () => {
    const c = flotta.contaScadenzeMezzi([{ mezzo: "CAT 320", dataScadenza: "" }], OGGI);
    eq(c.inScadenza, 1, "sta fra quelle da sistemare");
    eq(c.aPosto, 0, "e non fra quelle a posto");
  });
  test("scadenze mezzi: il semaforo segue la data, e il giorno stesso è rosso", () => {
    /* una revisione che scade oggi non è «fra poco»: o si fa oggi o domani il
       mezzo non può circolare */
    eq(flotta.statoScadenzaMezzo("2026-07-01", OGGI).label, "scaduta da 30 gg", "da quanto");
    eq(flotta.statoScadenzaMezzo("2026-07-31", OGGI).cls, "danger", "oggi è rosso, non giallo");
    eq(flotta.statoScadenzaMezzo("2026-08-15", OGGI).cls, "warn", "quindici giorni: preavviso");
    eq(flotta.statoScadenzaMezzo("2027-01-01", OGGI).cls, "ok", "cinque mesi: lontana");
  });
  test("scadenze mezzi: il preavviso lo decide l'utente", () => {
    eq(flotta.statoScadenzaMezzo("2026-08-15", OGGI, 0).stato, "a-posto", "col preavviso a zero");
    eq(flotta.statoScadenzaMezzo("2026-08-15", OGGI, 30).stato, "in-scadenza", "e con trenta giorni no");
  });

  const scadenze = [
    { id: "s1", mezzo: "CAT 320", tipo: "Revisione", dataScadenza: "2026-08-15" },
    { id: "s2", mezzo: "Aaa", tipo: "Assicurazione", dataScadenza: "2026-07-01" },
    { id: "s3", mezzo: "Zeta", tipo: "Verifica", dataScadenza: "" },
    { id: "s4", mezzo: "CAT 320", tipo: "Funi", dataScadenza: "2027-06-01" }];

  test("⛔ scadenze mezzi: in cima quelle senza data e le scadute, non l'alfabeto", () => {
    /* la prima riga che si guarda deve essere quella che ferma un mezzo: una
       senza data viene prima di tutto perché non si sa nemmeno quanto tempo c'è */
    eq(flotta.scadenzeOrdinate(scadenze, OGGI).map((x) => x.id).join(","), "s3,s2,s1,s4",
       "senza data, scaduta, in scadenza, a posto");
  });
  test("scadenze mezzi: il conteggio torna, e dice quanti MEZZI sono coinvolti", () => {
    const c = flotta.contaScadenzeMezzi(scadenze, OGGI);
    eq(c.scadute + c.inScadenza + c.aPosto, c.totale, "nessuna cade fuori");
    eq(c.mezzi, 3, "tre mezzi, anche se le scadenze sono quattro");
  });

  test("⛔ scadenze mezzi: un anno digitato male si ferma prima di salvare", () => {
    /* è l'errore più frequente su un campo data, e una revisione datata 2010
       farebbe risultare il mezzo fermo da anni */
    eq(flotta.validaScadenzaMezzo({ mezzo: "x", tipo: "y", dataScadenza: "2010-01-01" }, OGGI).errori.dataScadenza
       .includes("controlla l'anno"), true, "dieci anni indietro");
    eq(flotta.validaScadenzaMezzo({ mezzo: "x", tipo: "y", dataScadenza: "2060-01-01" }, OGGI).errori.dataScadenza
       .includes("controlla l'anno"), true, "e quindici avanti");
  });
  test("scadenze mezzi: quello che manca si dice campo per campo", () => {
    const e = flotta.validaScadenzaMezzo({}, OGGI).errori;
    eq(Object.keys(e).join(","), "mezzo,tipo,dataScadenza", "tre campi, tre messaggi");
    eq(e.mezzo.startsWith("Scegli"), true, "e ognuno dice che cosa fare");
  });
  test("scadenze mezzi: una scadenza buona passa", () => {
    eq(flotta.validaScadenzaMezzo({ mezzo: "x", tipo: "y", dataScadenza: "2026-12-01" }, OGGI).ok, true, "ok");
  });

  test("⛔ ricorrenza: la prossima scadenza non cade in un giorno che non esiste", () => {
    eq(flotta.aggiungiMesi("2026-01-31", 1), "2026-02-28", "dal 31 gennaio, fra un mese");
    eq(flotta.aggiungiMesi("2026-07-31", 12), "2027-07-31", "e a dodici mesi lo stesso giorno");
    eq(flotta.aggiungiMesi("boh", 1), null, "senza una data vera non si propone niente");
    eq(flotta.aggiungiMesi("2026-01-31", 0), null, "e senza periodicità nemmeno");
  });
  test("ricorrenza: i preset portano la norma che li giustifica", () => {
    /* «ogni 12 mesi» detto senza dire perché è una regola che nessuno può
       controllare: qui accanto c'è l'articolo */
    eq(flotta.SCADENZE_MEZZO_PRESET.every((p) => p.etichetta && p.norma !== undefined), true,
       "ognuno ha etichetta e riferimento");
    eq(flotta.presetScadenzaMezzo("revisione").mesi, 60, "la revisione è ogni cinque anni");
    eq(flotta.presetScadenzaMezzo("funi-catene").mesi, 3, "funi e catene ogni tre mesi");
    eq(flotta.presetScadenzaMezzo("boh"), null, "e un tipo inventato non esiste");
  });
}

/* ══ CONTI: LA FATTURA E IL SUO CLIENTE ═════════════════════════════════
   È il punto in cui i soldi trovano un nome. Una fattura attaccata al cliente
   sbagliato è un sollecito mandato a chi ha già pagato — e un'esposizione che
   sembra sotto controllo mentre è concentrata su uno solo.

   Il problema vero non è tecnico, è di **dati veri**: le fatture vecchie hanno
   solo il testo libero, e la stessa azienda è scritta in cinque modi («Cave
   S.r.l.», «CAVE SRL», «Cave  Srl»). Se ogni variante diventa una riga, il
   credito guarda cinque clienti piccoli invece di uno grosso. */
{
  const clienti = [{ id: "c1", ragioneSociale: "Cave del Nord S.r.l.", fido: 10000 },
    { id: "c2", ragioneSociale: "Edil Rossi" }];

  test("⛔ cliente: le varianti di scrittura sono lo stesso nome", () => {
    /* accenti, punteggiatura, maiuscole e spazi doppi: quello che cambia fra
       due modi di scrivere la stessa azienda, e non fra due aziende */
    eq(conti.chiaveNome("Cave S.r.l."), conti.chiaveNome("CAVE SRL"), "punteggiatura e maiuscole");
    eq(conti.chiaveNome("  Società   Anonima  "), conti.chiaveNome("Societa Anonima"), "accenti e spazi doppi");
    eq(conti.chiaveNome(""), "", "e il vuoto resta vuoto");
  });
  test("⛔ cliente: una fattura vecchia col solo testo si riconosce dal nome", () => {
    /* è quello che rende possibile la migrazione senza toccare le fatture
       già emesse */
    eq(conti.clienteDiFattura({ cliente: "CAVE DEL NORD SRL" }, clienti).id, "c1", "riconosciuto");
    eq(conti.clienteDiFattura({ cliente: "Tizio" }, clienti), null, "e chi non c'è resta senza");
  });
  test("⛔ cliente: un collegamento ROTTO non viene sostituito da un nome simile", () => {
    /* la fattura punta a un cliente cancellato: ripiegare sul nome la
       attaccherebbe a un'anagrafica che nessuno ha scelto, e i soldi
       finirebbero sul conto di un altro */
    eq(conti.clienteDiFattura({ clienteId: "cancellato", cliente: "Edil Rossi" }, clienti), null,
       "meglio nessun cliente che quello sbagliato");
  });
  test("cliente: il nome mostrato è quello dell'anagrafica quando c'è", () => {
    /* così correggere la ragione sociale in un posto la corregge ovunque */
    eq(conti.nomeCliente({ cliente: "cave del nord srl" }, clienti), "Cave del Nord S.r.l.", "dall'anagrafica");
    eq(conti.nomeCliente({ cliente: "Tizio" }, clienti), "Tizio", "altrimenti il testo salvato");
    eq(conti.nomeCliente({}, clienti), "—", "e senza niente un trattino, non una riga vuota");
  });
  test("⛔ cliente: le fatture si raggruppano per anagrafica, non per come è scritto il nome", () => {
    eq(conti.chiaveCliente({ cliente: "CAVE DEL NORD SRL" }, clienti), "id:c1", "quello collegato");
    eq(conti.chiaveCliente({ cliente: "Cave del Nord S.r.l." }, clienti),
       conti.chiaveCliente({ cliente: "CAVE DEL NORD SRL" }, clienti), "due scritture, una riga sola");
    eq(conti.chiaveCliente({ cliente: "Tizio" }, clienti), "nome:tizio", "e chi non è in anagrafica sta sul nome normalizzato");
  });

  const fatture = [{ id: "f1", cliente: "Tizio S.p.A.", importo: 1000 },
    { id: "f2", cliente: "TIZIO SPA", importo: 500 }, { id: "f3", cliente: "Edil Rossi", importo: 200 },
    { id: "f4", cliente: "", importo: 99 }, { id: "f5", cliente: "Caio", importo: 300 }];

  test("⛔ migrazione: l'elenco da collegare unisce le varianti e porta gli id", () => {
    /* è la lista di lavoro: «questi nomi vanno collegati». Le due scritture di
       Tizio sono una voce sola, e porta gli id di tutte e due le fatture così
       si collegano in un colpo */
    const l = conti.clientiDaCollegare(fatture, clienti);
    eq(l.length, 2, "Tizio e Caio: Edil Rossi è già in anagrafica");
    eq(l[0].conto, 2, "Tizio ha due fatture");
    eq(l[0].importo, 1500, "per millecinquecento euro");
    eq(l[0].ids.join(","), "f1,f2", "e si collegano insieme");
  });
  test("migrazione: prima chi ha più fatture, e una fattura senza nome non entra", () => {
    const l = conti.clientiDaCollegare(fatture, clienti);
    eq(l[0].nome, "Tizio S.p.A.", "il più grosso in cima");
    eq(l.some((x) => x.ids.includes("f4")), false, "e su una fattura senza nome non c'è niente da collegare");
  });

  test("⛔ prezzo: senza la densità non si inventa una conversione", () => {
    /* il listino è in €/m³ e la pesa dà tonnellate: senza il peso di volume
       quel prezzo non si può portare a tonnellata, e tirare a indovinare
       vorrebbe dire fatturare un numero inventato */
    eq(conti.prezzoPerTonnellata({ prezzo: 30, unitaPrezzo: "m3" }), null, "manca la densità");
    eq(conti.prezzoPerTonnellata({ prezzo: 30, unitaPrezzo: "m3", densita: 1.6 }), 18.75, "con la densità si converte");
    eq(conti.prezzoPerTonnellata({ prezzo: 12.5, unitaPrezzo: "t" }), 12.5, "e se è già in tonnellate resta");
  });
  test("prezzo: una densità di zero o negativa non è una densità", () => {
    for (const d of [0, -1, "boh", null]) eq(conti.densitaValida({ densita: d }), null, "scartata");
    eq(conti.densitaValida({ densita: 1.6 }), 1.6, "e quella buona passa");
  });

  test("⛔ mora: gli interessi si contano solo su un ritardo vero", () => {
    /* su una fattura non ancora scaduta il conto è zero: chiedere interessi
       prima della scadenza è la cosa che fa perdere un cliente */
    eq(conti.interessiMora(10000, 0, 12).interessi, 0, "nessun ritardo");
    /* ⚠️ il caso che la guardia difende davvero è il ritardo NEGATIVO: con
       zero giorni l'aritmetica dà già zero da sola, e la prova non provava
       niente. Con -10 giorni, senza guardia, gli interessi diventerebbero
       NEGATIVI — cioè l'app farebbe uno sconto per aver pagato in anticipo,
       che è l'opposto di quello che significa la mora */
    eq(conti.interessiMora(10000, -10, 12).interessi, 0, "e su una fattura ancora da scadere nemmeno");
    eq(conti.interessiMora(10000, -10, 12).giorni, 0, "i giorni di ritardo non vanno sottozero");
    eq(conti.interessiMora(0, 90, 12).interessi, 0, "e su zero euro nemmeno");
    eq(conti.interessiMora(10000, 90, 12).interessi, 295.89, "novanta giorni al 12%");
  });
  test("mora: il sollecito sale per fasce, e prima della scadenza non esiste", () => {
    eq(conti.livelloSollecito(0).livello, 0, "non scaduta: nessun sollecito");
    eq(conti.livelloSollecito(1).livello, 1, "il giorno dopo, il primo");
    eq(conti.livelloSollecito(16).livello, 2, "dopo due settimane, il secondo");
    eq(conti.livelloSollecito(46).livello, 3, "e dopo un mese e mezzo, l'ultimo avviso");
    eq(conti.livelloSollecito(46).cls, "danger", "che è rosso");
  });
  test("mora: le spese di recupero sono quelle di legge", () => {
    eq(conti.SPESE_RECUPERO_231, 40, "quaranta euro forfettari, art. 6 D.Lgs 231/2002");
  });
}

// ── Campo: chi fa cosa, obiettivo di turno, fermi ─────────────────────
/* Il censimento della copertura dava Campo come la meno difesa delle sei
   (39 funzioni su 73). Queste sono le funzioni che rispondono alle tre
   domande che un preposto fa a inizio e a fine turno: «di chi è questa
   attività», «quanto manca all'obiettivo», «quanto ci siamo fermati».
   Le regole bloccate qui sono TUTTE dichiarate nei commenti del modulo:
   il test serve a impedire che una riscrittura le contraddica in silenzio. */
{
  console.log("\n— Campo: assegnazione, obiettivo di turno, fermi —");

  const SQU_A = "Squadra A — Perforazione", SQU_B = "Squadra B — Carico";
  const ATT = [
    { data: "2026-07-31", turno: "Mattino", squadra: SQU_A, operatore: "Mario Rossi", stato: "conclusa" },
    { data: "2026-07-31", turno: "Mattino", squadra: SQU_A, operatore: "", stato: "in-corso" },
    { data: "2026-07-31", turno: "Mattino", squadra: SQU_A, operatore: "Luca Bianchi", stato: "anomalia", fermoMin: 45 },
    { data: "2026-07-31", turno: "Mattino", squadra: SQU_B, operatore: "Anna Neri", stato: "in-corso" },
    { data: "2026-07-31", turno: "Mattino", squadra: "", operatore: "", stato: "in-corso" },
  ];
  const SQUADRE = [{ nome: SQU_A }, { nome: SQU_B }, { nome: "Squadra C — Impianto" }];

  test("eMia: il mio nome vince sulla squadra (se me l'hanno data, tocca a me)", () => {
    ok(campo.eMia({ squadra: "Squadra Z", operatore: "Mario Rossi" },
      { squadra: "Squadra A", operatore: "Mario Rossi" }),
      "un'attività col mio nome è mia anche se è di un'altra squadra");
  });
  test("eMia: della mia squadra senza nome è mia, con il nome di un altro no", () => {
    ok(campo.eMia({ squadra: SQU_A, operatore: "" }, { squadra: "Squadra A", operatore: "Mario Rossi" }),
      "senza nome tocca a chiunque della squadra");
    ok(!campo.eMia({ squadra: "Squadra A", operatore: "Luca" }, { squadra: "Squadra A", operatore: "Mario Rossi" }),
      "col nome di un altro non è mia");
  });
  test("eMia: chi dichiara solo la squadra vede il lavoro di TUTTA la squadra", () => {
    /* è il caposquadra: se filtrasse anche a lui per nome non vedrebbe niente */
    ok(campo.eMia({ squadra: "Squadra A", operatore: "Luca" }, { squadra: "Squadra A" }),
      "senza il mio nome guardo tutta la squadra");
  });
  test("eMia: se non ho detto qual è la mia squadra non è mia niente", () => {
    ok(!campo.eMia({ squadra: "Squadra A", operatore: "" }, { operatore: "Mario Rossi" }),
      "nessuna squadra dichiarata: nessuna attività mia");
    ok(!campo.eMia(null, { squadra: "Squadra A" }), "attività assente");
    ok(!campo.eMia({ squadra: "Squadra A" }, null), "io assente");
  });

  test("caricoSquadre: le attività senza squadra sono contate A PARTE", () => {
    /* il commento del modulo: «sono il vero problema: non le fa nessuno».
       Se finissero in una squadra qualsiasi sparirebbero dal conto. */
    const c = campo.caricoSquadre(ATT, SQUADRE);
    eq(c.nonAssegnate, 1, "una attività senza squadra");
    eq(c.righe.reduce((n, r) => n + r.aperte + r.concluse, 0), 4,
      "e non entra nel carico di nessuna squadra");
  });
  test("caricoSquadre: un'anomalia è ancora aperta (non è una conclusa)", () => {
    const a = campo.caricoSquadre(ATT, SQUADRE).righe.find(r => r.squadra === "Squadra A");
    contiene(a, { squadra: "Squadra A", nome: SQU_A, aperte: 2, concluse: 1, anomalie: 1 },
      "l'anomalia conta fra le aperte e in più come anomalia");
  });
  test("caricoSquadre: una squadra senza attività resta in elenco a zero", () => {
    /* farla sparire direbbe «non esiste»; a zero dice «non ha niente in mano» */
    const c = campo.caricoSquadre(ATT, SQUADRE);
    contiene(c.righe.find(r => r.squadra === "Squadra C") || {},
      { aperte: 0, concluse: 0 }, "la squadra ferma si vede");
    eq(c.righe.length, 3, "tutte e tre le squadre in elenco");
    eq(c.righe.map(r => r.squadra), ["Squadra A", "Squadra B", "Squadra C"],
      "ordinate per aperte in giù, poi per nome");
  });
  test("caricoSquadre: senza dati non inventa righe", () =>
    eq(campo.caricoSquadre([], []), { righe: [], nonAssegnate: 0 }, "vuoto"));

  const OBIETTIVI = [
    { data: "2026-07-31", turno: "Mattino", unita: "t", valore: 100 },
    { data: "2026-07-31", turno: "Mattino", unita: "t", valore: 120 },
    { data: "2026-07-31", turno: "Mattino", unita: campo.UNITA_ATTIVITA, valore: 3 },
  ];
  const RAP = [
    { data: "2026-07-31", turno: "Mattino", stato: "bozza",   prodQta: 60, prodUnita: "t" },
    { data: "2026-07-31", turno: "Mattino", stato: "inviato", prodQta: 45, prodUnita: "t" },
    { data: "2026-07-31", turno: "Pomeriggio", stato: "inviato", prodQta: 500, prodUnita: "t" },
    { data: "2026-07-31", turno: "Mattino", stato: "inviato", prodQta: 9, prodUnita: "m³" },
  ];

  test("obiettivoDi: l'ultimo salvato vince (si corregge riscrivendolo)", () => {
    eq(campo.obiettivoDi(OBIETTIVI, "2026-07-31", "Mattino", "t").valore, 120,
      "120 salvato dopo 100");
  });
  test("obiettivoDi: cerca per giorno, turno e unità, e non ne inventa uno", () => {
    eq(campo.obiettivoDi(OBIETTIVI, "2026-07-31", "Notte", "t"), null, "turno senza obiettivo");
    eq(campo.obiettivoDi(OBIETTIVI, "2026-07-31", "Mattino", "m³"), null, "unità senza obiettivo");
    eq(campo.obiettivoDi([], "2026-07-31", "Mattino", "t"), null, "nessun obiettivo salvato");
  });

  test("statoObiettivo: la produzione conta BOZZE COMPRESE (la produzione è produzione)", () => {
    /* 60 in bozza + 45 inviato = 105: contare solo l'inviato direbbe al preposto
       che è più indietro di quanto è, e lo farebbe correre per niente */
    contiene(campo.statoObiettivo(OBIETTIVI[1], RAP, ATT),
      { obiettivo: 120, fatto: 105, mancante: 15, scarto: -15, pct: 88, livello: "warn" },
      "105 su 120");
  });
  test("statoObiettivo: le unità non si mescolano, e gli altri turni nemmeno", () => {
    /* i 9 m³ e i 500 t del pomeriggio non entrano in un obiettivo di mattino in t */
    eq(campo.statoObiettivo(OBIETTIVI[1], RAP, ATT).fatto, 105,
      "solo i t di quel turno");
  });
  test("statoObiettivo: a zero il livello è «atteso», non un allarme", () => {
    /* a inizio turno essere a zero è normale: un rosso lì dentro insegna a
       ignorare i rossi, ed è il modo migliore per non vedere quelli veri */
    const s = campo.statoObiettivo({ data: "2026-07-30", turno: "Notte", unita: "t", valore: 100 }, RAP, ATT);
    contiene(s, { fatto: 0, pct: 0, livello: "atteso" }, "zero all'inizio non è un allarme");
    ok(s.livello !== "danger", "e non deve mai diventare danger");
  });
  test("statoObiettivo: raggiunto e superato si vedono nello scarto", () => {
    const s = campo.statoObiettivo({ data: "2026-07-31", turno: "Mattino", unita: "t", valore: 100 }, RAP, ATT);
    contiene(s, { fatto: 105, mancante: 0, scarto: 5, pct: 105, livello: "ok" },
      "sopra l'obiettivo: mancante a zero, scarto positivo");
  });
  test("statoObiettivo: un obiettivo sulle attività conta quelle concluse", () => {
    contiene(campo.statoObiettivo(OBIETTIVI[2], RAP, ATT),
      { unita: campo.UNITA_ATTIVITA, obiettivo: 3, fatto: 1, pct: 33 }, "una conclusa su tre");
  });
  test("statoObiettivo: senza un numero positivo non risponde niente", () => {
    /* meglio nessuno stato che uno stato costruito su un obiettivo che non c'è */
    eq(campo.statoObiettivo(null, RAP, ATT), null, "nessun obiettivo");
    eq(campo.statoObiettivo({ data: "x", turno: "y", unita: "t", valore: 0 }, RAP, ATT), null, "zero");
    eq(campo.statoObiettivo({ data: "x", turno: "y", unita: "t", valore: "" }, RAP, ATT), null, "vuoto");
    eq(campo.statoObiettivo({ data: "x", turno: "y", unita: "t", valore: -5 }, RAP, ATT), null, "negativo");
  });

  const ATT_FERMI = [
    { data: "2026-07-29", stato: "anomalia", fermoMin: 5 },
    { data: "2026-07-31", stato: "anomalia", fermoMin: 30 },
    { data: "2026-07-31", stato: "anomalia", fermoMin: 15 },
    { data: "2026-07-31", stato: "conclusa" },
    { data: "", stato: "anomalia", fermoMin: 999 },
    { data: "2026-08-05", stato: "anomalia", fermoMin: 777 },
  ];
  const OGGI = new Date("2026-07-31T12:00:00");

  test("fermiPerGiorno: i giorni PRIMA della prima registrazione restano fuori", () => {
    /* disegnarli a zero direbbe «quel giorno non ci siamo fermati», mentre la
       verità è che non c'era ancora nessuno a registrare — è la stessa regola
       che dice che l'assenza di un dato non è un dato favorevole */
    const g = campo.fermiPerGiorno(ATT_FERMI, 14, OGGI);
    eq(g[0].data, "2026-07-29", "la finestra parte dalla prima registrazione, non 14 giorni fa");
    eq(g.length, 3, "tre giorni, non quattordici");
  });
  test("fermiPerGiorno: un giorno DENTRO la finestra senza fermi vale zero", () => {
    /* e questo invece è un dato vero: quel giorno c'eravamo e non ci siamo fermati */
    eq(campo.fermiPerGiorno(ATT_FERMI, 14, OGGI)[1], { data: "2026-07-30", minuti: 0, fermi: 0 },
      "il 30 luglio a zero");
  });
  test("fermiPerGiorno: somma i minuti del giorno e conta i fermi", () => {
    eq(campo.fermiPerGiorno(ATT_FERMI, 14, OGGI)[2], { data: "2026-07-31", minuti: 45, fermi: 2 },
      "30 + 15 minuti, due fermi; la conclusa non è un fermo");
  });
  test("fermiPerGiorno: senza data o nel futuro non entrano", () => {
    /* i 999 minuti senza data e i 777 del 5 agosto non compaiono da nessuna parte */
    const tot = campo.fermiPerGiorno(ATT_FERMI, 14, OGGI).reduce((n, g) => n + g.minuti, 0);
    eq(tot, 50, "5 + 45, e basta");
    eq(campo.fermiPerGiorno([], 14, OGGI), [], "nessuna registrazione: nessuna finestra");
    eq(campo.fermiPerGiorno([{ data: "", stato: "anomalia", fermoMin: 10 }], 14, OGGI), [],
      "solo registrazioni senza data: idem");
  });

  test("storicoSettimana: le giornate vuote restano in elenco (un giorno vuoto è un'informazione)", () => {
    const st = campo.storicoSettimana(ATT, RAP, 3, OGGI);
    eq(st.map(g => g.data), ["2026-07-29", "2026-07-30", "2026-07-31"], "tre giornate in ordine");
    contiene(st[0], { attTot: 0, rapTot: 0, minutiFermo: 0 }, "il 29 è vuoto e si vede");
    contiene(st[2], { attTot: 5, attConcluse: 1, minutiFermo: 45, fermi: 1, rapInviati: 3, rapTot: 4 },
      "il 31 ha tutto");
    eq(st[2].prod, { "t": 605, "m³": 9 }, "produzione tenuta separata per unità");
  });
  test("totaliSettimana: t e m³ non si sommano, e i giorni con dati si contano", () => {
    const t = campo.totaliSettimana(campo.storicoSettimana(ATT, RAP, 3, OGGI));
    contiene(t, { giorni: 3, giorniConDati: 1, minutiFermo: 45, fermi: 1, attTot: 5, attConcluse: 1, pctConcluse: 20 },
      "totali della finestra");
    eq(t.prod, { "t": 605, "m³": 9 }, "due unità, due totali");
  });
  test("totaliSettimana: senza attività la percentuale è vuota, non cento", () => {
    /* zero attività su zero non è «tutto concluso»: è «non c'è niente da dire» */
    eq(campo.totaliSettimana(campo.storicoSettimana([], [], 3, OGGI)).pctConcluse, null, "null, non 100");
  });
  test("unitaPrevalente: sceglie l'unità che pesa di più, e null se non c'è produzione", () => {
    /* tonnellate e metri cubi non si sommano: il grafico ne disegna una sola */
    eq(campo.unitaPrevalente(campo.storicoSettimana(ATT, RAP, 3, OGGI)), "t", "605 t contro 9 m³");
    eq(campo.unitaPrevalente(campo.storicoSettimana([], [], 3, OGGI)), null, "nessuna produzione");
  });

  test("etichettaAssegnazione e operatoriDi: nome breve della squadra e ordine alfabetico", () => {
    eq(campo.etichettaAssegnazione({ squadra: SQU_A, operatore: "Mario Rossi" }), "Squadra A · Mario Rossi", "squadra e persona");
    eq(campo.etichettaAssegnazione({ squadra: SQU_A }), "Squadra A", "solo squadra");
    eq(campo.etichettaAssegnazione({}), "", "non assegnata: stringa vuota, non «nessuno»");
    eq(campo.operatoriDi([{ nome: "Zeno", squadra: SQU_A }, { nome: "Anna", squadra: "Squadra A" },
      { nome: "Bruno", squadra: "Squadra B" }], "Squadra A").map(o => o.nome),
      ["Anna", "Zeno"], "la squadra si riconosce dal nome breve, in ordine alfabetico");
  });
}

// ── Campo: la foto dell'anomalia, il meteo, la checklist ──────────────
/* Secondo gruppo di funzioni scoperte di Campo. Due famiglie molto diverse:
   · la FOTO è anche una questione di sicurezza — `eFotoValida` è l'ultima
     cosa che sta fra un `data:` costruito a mano e un tag <img> della
     pagina (docs/AUDIT_SICUREZZA.md), e le misure decidono se una foto da
     8 MB entra o no in un documento Firestore da 1 MB;
   · il METEO è la voce che «spiega i fermi»: qui conta soprattutto che
     quando NON è stato registrato niente non esca un giudizio tranquillo. */
{
  console.log("\n— Campo: foto dell'anomalia, meteo, checklist —");

  test("eImmagine: passano le foto del telefono (HEIC compreso), non i documenti", () => {
    ok(campo.eImmagine({ type: "image/jpeg" }), "jpeg");
    ok(campo.eImmagine({ type: "IMAGE/HEIC" }), "heic dell'iPhone, anche scritto in maiuscolo");
    ok(!campo.eImmagine({ type: "application/pdf" }), "un pdf non è una foto");
    ok(!campo.eImmagine({ type: "image/svg+xml" }), "un SVG può contenere codice: fuori");
    ok(!campo.eImmagine({}), "senza tipo non si indovina");
    ok(!campo.eImmagine(null), "senza file nemmeno");
  });
  test("⛔ eFotoValida: solo data URL di immagine in base64, mai «javascript:», mai SVG", () => {
    /* è l'ultimo controllo prima di un <img> della pagina: se cede qui, cede
       in tutte le anomalie salvate da chiunque nell'organizzazione */
    ok(campo.eFotoValida("data:image/jpeg;base64,AAAA"), "jpeg");
    ok(campo.eFotoValida("data:image/png;base64,AAA="), "png col padding");
    ok(!campo.eFotoValida("data:image/svg+xml;base64,AAAA"), "SVG: no");
    ok(!campo.eFotoValida("data:image/gif;base64,AAAA"), "gif: no (il canvas riscrive in JPEG)");
    ok(!campo.eFotoValida("javascript:alert(1)"), "javascript: no");
    ok(!campo.eFotoValida("https://esterno/foto.jpg"), "un indirizzo esterno non è una foto salvata");
    ok(!campo.eFotoValida(""), "vuoto: no");
  });
  test("byteFoto: conta i byte del file, non i caratteri del base64", () => {
    /* il base64 è un terzo più lungo del file: leggere la lunghezza del testo
       farebbe credere che una foto da 210 kB ne pesi 280, e la scaletta dei
       tentativi rimpicciolirebbe per niente */
    eq(campo.byteFoto("data:image/jpeg;base64," + "A".repeat(100)), 75, "100 caratteri = 75 byte");
    eq(campo.byteFoto("data:image/jpeg;base64," + "A".repeat(98) + "=="), 73, "il riempimento finale non conta");
  });
  test("byteFoto: quello che non è un data URL pesa zero", () => {
    eq(campo.byteFoto("robaccia"), 0, "senza virgola non c'è nessun contenuto");
    eq(campo.byteFoto(""), 0, "vuoto");
    eq(campo.byteFoto(null), 0, "niente");
  });
  test("formattaByte: kB fin sotto il mega, poi MB con la virgola italiana", () => {
    eq(campo.formattaByte(245760), "240 kB", "240 kB");
    eq(campo.formattaByte(3355443), "3,2 MB", "virgola, non punto");
    /* il pavimento a 1 kB è voluto: una foto da 300 byte esiste, e «0 kB»
       direbbe che non c'è. Non è un numero inventato su un dato mancante —
       lì la pagina non disegna proprio la riga della foto. */
    eq(campo.formattaByte(300), "1 kB", "un file piccolo non pesa «0 kB»");
  });
  test("misuraRidotta: rimpicciolisce tenendo le proporzioni, sul lato lungo", () => {
    eq(campo.misuraRidotta(4000, 3000, 1280), { w: 1280, h: 960 }, "orizzontale");
    eq(campo.misuraRidotta(3000, 4000, 1024), { w: 768, h: 1024 }, "verticale: il lato lungo è l'altezza");
  });
  test("misuraRidotta: non ingrandisce mai una foto piccola", () => {
    /* stirarla non aggiunge niente e fa pesare di più lo stesso dettaglio */
    eq(campo.misuraRidotta(800, 600, 1280), { w: 800, h: 600 }, "resta com'è");
  });
  test("misuraRidotta: misure assenti o assurde danno 1×1, non zero né NaN", () => {
    eq(campo.misuraRidotta(0, 0, 1280), { w: 1, h: 1 }, "zero per zero");
    eq(campo.misuraRidotta(-5, -5, 1280), { w: 1, h: 1 }, "negative");
    eq(campo.misuraRidotta("", "", 1280), { w: 1, h: 1 }, "vuote");
  });
  test("la scaletta dei tentativi scende, e il tetto sta ben sotto il mega di Firestore", () => {
    /* un documento Firestore non può superare 1 MB IN TUTTO: se il tetto della
       sola foto ci arrivasse vicino, l'anomalia non si salverebbe più */
    ok(campo.FOTO_MAX_BYTE < 1048576 * 0.35, "il tetto lascia spazio agli altri campi");
    const lati = campo.FOTO_TENTATIVI.map(t => t.lato);
    const qual = campo.FOTO_TENTATIVI.map(t => t.qualita);
    eq(lati, [...lati].sort((a, b) => b - a), "i lati scendono");
    eq(qual, [...qual].sort((a, b) => b - a), "e anche la qualità");
    ok(campo.FOTO_TENTATIVI.length >= 3, "più di un tentativo, se no non è una scaletta");
  });

  const METEO = [
    { data: "2026-07-31", turno: "Mattino", cielo: "Sereno" },
    { data: "2026-07-31", turno: "Mattino", cielo: "Pioggia", piste: "Fangose", visibilita: "Ridotta" },
    { data: "2026-07-31", turno: "Pomeriggio", cielo: "Nuvoloso" },
  ];
  test("meteoDi: l'ultimo registrato vince, e per un turno senza niente non inventa", () => {
    contiene(campo.meteoDi(METEO, "2026-07-31", "Mattino"), { cielo: "Pioggia" }, "la correzione vale");
    eq(campo.meteoDi(METEO, "2026-07-31", "Notte"), null, "turno mai registrato");
    eq(campo.meteoDi([], "2026-07-31", "Mattino"), null, "niente registrato");
  });
  test("riassuntoMeteo: una riga sola, e vuota se non c'è niente", () => {
    eq(campo.riassuntoMeteo(METEO[1]), "Pioggia · piste fangose · visibilità ridotta", "la riga intera");
    eq(campo.riassuntoMeteo({ cielo: "Sereno" }), "Sereno", "solo quello che è stato detto");
    eq(campo.riassuntoMeteo({}), "", "registrazione vuota");
    eq(campo.riassuntoMeteo(null), "", "nessuna registrazione");
  });
  test("meteoAvverso: le condizioni che da sole spiegano un fermo", () => {
    ok(campo.meteoAvverso({ cielo: "Pioggia" }), "pioggia");
    ok(campo.meteoAvverso({ cielo: "Neve o gelo" }), "neve o gelo");
    ok(campo.meteoAvverso({ cielo: "Caldo estremo" }), "caldo estremo");
    ok(campo.meteoAvverso({ cielo: "Sereno", piste: "Ghiacciate" }), "col sole ma le piste ghiacciate");
    ok(campo.meteoAvverso({ cielo: "Sereno", visibilita: "Scarsa" }), "visibilità scarsa");
  });
  test("meteoAvverso: «Ridotta» non è «Scarsa», e il sereno non è avverso", () => {
    /* allargare la soglia farebbe suonare l'allarme quasi sempre, e un
       allarme quasi sempre acceso non è un allarme */
    ok(!campo.meteoAvverso({ cielo: "Sereno", visibilita: "Ridotta" }), "ridotta no");
    ok(!campo.meteoAvverso({ cielo: "Sereno", piste: "Asciutte", visibilita: "Buona" }), "giornata buona");
    ok(!campo.meteoAvverso({ cielo: "Nuvoloso" }), "nuvoloso non ferma niente");
  });
  test("⛔ meteo non registrato: nessun giudizio, e il cartellone non si disegna", () => {
    /* meteoAvverso(null) è false, ma NON significa «bel tempo»: la pagina
       disegna il cartellone solo quando riassuntoMeteo dice qualcosa, e
       l'export scrive «non registrato». Le due cose vanno insieme: se un
       giorno il cartellone comparisse anche a riassunto vuoto, un turno mai
       compilato si mostrerebbe come un turno senza problemi. */
    ok(!campo.meteoAvverso(null), "senza registrazione non c'è nessun giudizio");
    eq(campo.riassuntoMeteo(null), "", "e nemmeno niente da scrivere: è questo che spegne il cartellone");
    eq(campo.riassuntoMeteo(campo.meteoDi([], "2026-07-31", "Notte")), "", "turno mai compilato");
  });

  test("checklistDi: l'ultima salvata vince e la squadra si riconosce dal nome breve", () => {
    const CHK = [
      { data: "2026-07-31", turno: "Mattino", squadra: "Squadra A", esiti: { "0": "ok" } },
      { data: "2026-07-31", turno: "Mattino", squadra: "Squadra A — Perforazione", esiti: { "0": "no" } },
    ];
    eq(campo.checklistDi(CHK, "2026-07-31", "Mattino", "Squadra A — Perforazione").esiti, { "0": "no" },
      "«Squadra A» e «Squadra A — Perforazione» sono la stessa squadra");
    eq(campo.checklistDi(CHK, "2026-07-31", "Mattino", "Squadra B"), null, "un'altra squadra non eredita");
    eq(campo.checklistDi([], "2026-07-31", "Mattino", "Squadra A"), null, "mai compilata");
  });
  test("statoChecklist: «non risposto» non è «a posto», e i problemi si leggono", () => {
    /* una voce lasciata in bianco che contasse come ok trasformerebbe la
       checklist in una firma finta: è esattamente ciò che deve impedire */
    const s = campo.statoChecklist({ "0": "ok", "1": "no", "2": "na" });
    contiene(s, { ok: 1, no: 1, na: 1, risposte: 3, completa: false }, "tre risposte su nove");
    eq(s.mancanti, s.totale - s.risposte, "le mancanti sono quelle non toccate");
    eq(s.problemi.length, 1, "un problema elencato");
    ok(s.problemi[0].length > 3, "e nominato per esteso, non per numero");
  });
  test("statoChecklist: mai compilata è 0%, non «completa»", () => {
    const s = campo.statoChecklist({});
    contiene(s, { ok: 0, no: 0, na: 0, risposte: 0, completa: false, pct: 0 }, "vuota");
    eq(s.problemi, [], "nessun problema TROVATO non vuol dire nessun problema");
    eq(campo.statoChecklist(null).risposte, 0, "senza esiti non esplode");
  });
  test("le liste a scelta rapida restano quelle previste (si tocca, non si scrive)", () => {
    eq(campo.ESITI_CHECK, ["ok", "no", "na"], "fatto / non a posto / non applicabile");
    eq(campo.STATI_PRESENZA, ["presente", "assente"], "e «non spuntato» non è uno stato: è l'assenza di risposta");
    ok(campo.METEO_CIELO.includes("Pioggia") && campo.METEO_CIELO.includes("Neve o gelo"), "cielo");
    ok(campo.METEO_PISTE.includes("Ghiacciate"), "piste");
    eq(campo.METEO_VISIBILITA, ["Buona", "Ridotta", "Scarsa"], "visibilità");
  });
}

// ── Flotta: i fermi, i costi per mese, la disponibilità registrata ────
/* Flotta era rimasta la meno difesa (34 funzioni su 71). Il blocco dei
   FERMI è quello che pesa di più: da lì esce la disponibilità del parco,
   cioè il numero con cui si decide se una macchina si ripara ancora o si
   sostituisce. Tutte le regole qui sotto sono scritte nei commenti del
   modulo come «regole di onestà»: qui diventano asserzioni. */
{
  console.log("\n— Flotta: fermi, costi per mese, disponibilità —");
  const OGGI = new Date("2026-07-31T10:00:00");

  test("causali di fermo: la lista è chiusa, e un motivo non riconosciuto si vede", () => {
    /* servono categorie confrontabili nel tempo, se no la disponibilità non
       si può nemmeno calcolare; ma una chiave sconosciuta non diventa mai
       «Altro» in silenzio: viene ripetuta com'è */
    eq(flotta.etichettaCausale("attesa-ricambi"), "Attesa ricambi", "chiave nota");
    eq(flotta.etichettaCausale("pippo"), "pippo", "chiave sconosciuta: si mostra com'è");
    eq(flotta.etichettaCausale(""), "Motivo non indicato", "e senza motivo lo dice");
    eq(flotta.causaleFermo("x"), null, "causaleFermo non inventa una voce");
    ok(flotta.CAUSALI_FERMO.every(c => c.chiave && c.etichetta && c.nota),
      "ogni causale ha chiave, etichetta e spiegazione");
  });
  test("⚠️ `CAUSALI_FERMO` esiste in DUE app e NON è la stessa cosa", () => {
    /* Trovato scrivendo questa prova, con un'asserzione buttata lì che è
       caduta: Campo esporta anche lui `CAUSALI_FERMO`. Non è la regola
       riscritta due volte — sono due tassonomie di soggetti diversi:
       Campo dice perché si è fermata UN'ATTIVITÀ di turno (testo semplice:
       «Mancanza materiale», «Attesa mezzo», «Cambio turno»), Flotta perché
       è fuori servizio UNA MACCHINA (voci con chiave, per calcolare la
       disponibilità: «attesa-ricambi», «gomme-cingoli»).
       La prova sta qui perché il nome uguale è una trappola per chi arriva
       dopo: se un giorno le due liste diventassero davvero la stessa cosa,
       il posto è `shared/`, non una copia. */
    ok(Array.isArray(campo.CAUSALI_FERMO) && typeof campo.CAUSALI_FERMO[0] === "string",
      "Campo: testo semplice, sono voci da scegliere in un elenco");
    ok(typeof flotta.CAUSALI_FERMO[0] === "object" && flotta.CAUSALI_FERMO[0].chiave,
      "Flotta: voci con chiave, perché ci si calcola sopra la disponibilità");
    ok(campo.CAUSALI_FERMO.includes("Attesa mezzo"), "Campo parla di attività di turno");
    ok(flotta.CAUSALI_FERMO.some(c => c.chiave === "gomme-cingoli"), "Flotta parla di macchine");
  });

  test("giorniFermo: una giornata persa è persa tutta (conteggio inclusivo)", () => {
    /* ferma il 3 e ripartita il 3 = un giorno, non zero: in cava mezza
       giornata di escavatore fermo non è mezza giornata di lavoro */
    eq(flotta.giorniFermo({ inizio: "2026-07-03", fine: "2026-07-03" }, "2026-07-01", "2026-07-31"), 1,
      "stesso giorno = 1");
  });
  test("giorniFermo: un fermo aperto conta fino alla fine della finestra", () => {
    eq(flotta.giorniFermo({ inizio: "2026-07-29" }, "2026-07-01", "2026-07-31"), 3, "29, 30, 31");
  });
  test("giorniFermo: un fermo più vecchio pesa solo per la parte che ci sta dentro", () => {
    /* un fermo di due mesi non può pesare due mesi su una finestra di trenta
       giorni: il denominatore non lo reggerebbe e la percentuale mentirebbe */
    eq(flotta.giorniFermo({ inizio: "2026-05-01", fine: "2026-07-05" }, "2026-07-01", "2026-07-31"), 5, "1→5 luglio");
    eq(flotta.giorniFermo({ inizio: "2026-01-01", fine: "2026-01-05" }, "2026-07-01", "2026-07-31"), 0, "fuori finestra");
    eq(flotta.giorniFermo({ fine: "2026-07-05" }, "2026-07-01", "2026-07-31"), 0, "senza inizio non è un fermo");
  });
  test("durataFermo: un fermo aperto conta fino a oggi E LO DICHIARA", () => {
    /* «3 giorni» su un fermo ancora aperto è un numero che cresce: il flag
       `aperto` è quello che impedisce di leggerlo come un fermo finito */
    contiene(flotta.durataFermo({ inizio: "2026-07-29" }, OGGI), { giorni: 3, aperto: true, fine: null }, "aperto");
    contiene(flotta.durataFermo({ inizio: "2026-07-28", fine: "2026-07-30" }, OGGI),
      { giorni: 3, aperto: false, fine: "2026-07-30" }, "chiuso");
  });
  test("durataFermo: senza inizio non inventa una durata", () => {
    /* zero giorni direbbe «non si è fermata»: qui la risposta è «non lo so» */
    contiene(flotta.durataFermo({}, OGGI), { giorni: null }, "nessun inizio");
    contiene(flotta.durataFermo({ inizio: "2026-07-30", fine: "2026-07-28" }, OGGI), { giorni: null },
      "ripartita prima di fermarsi: nessuna durata, non una negativa");
  });

  test("validaFermo: mezzo, motivo e giorno sono obbligatori, con la frase che dice cosa fare", () => {
    const v = flotta.validaFermo({}, OGGI);
    eq(v.ok, false, "non si salva");
    eq(Object.keys(v.errori).sort(), ["causale", "inizio", "mezzo"], "tre cose mancanti");
    ok(/Scegli il mezzo/.test(v.errori.mezzo), "e l'errore dice cosa fare, non «campo non valido»");
  });
  test("validaFermo: un fermo non comincia domani e non riparte nel futuro", () => {
    /* la data futura è il modo più facile per falsare la disponibilità:
       giorni persi che non sono ancora successi */
    ok(!flotta.validaFermo({ mezzo: "X", causale: "altro", inizio: "2026-08-01" }, OGGI).ok, "inizio domani");
    const f = flotta.validaFermo({ mezzo: "X", causale: "altro", inizio: "2026-07-29", fine: "2026-08-05" }, OGGI);
    ok(!f.ok && /futuro/.test(f.errori.fine), "ripartenza nel futuro");
    ok(!flotta.validaFermo({ mezzo: "X", causale: "altro", inizio: "2026-07-29", fine: "2026-07-28" }, OGGI).ok,
      "ripartita prima di essersi fermata");
    ok(!flotta.validaFermo({ mezzo: "X", causale: "altro", inizio: "1990-01-01" }, OGGI).ok,
      "oltre dieci anni fa: quasi sempre un anno sbagliato");
  });
  test("validaFermo: un fermo aperto è valido (la macchina è ferma adesso)", () => {
    contiene(flotta.validaFermo({ mezzo: "CAT 320", causale: "guasto-meccanico", inizio: "2026-07-29" }, OGGI),
      { ok: true, inizio: "2026-07-29", fine: null }, "senza ripartenza si salva");
  });

  test("fermiOrdinati: prima gli aperti dal più lungo, poi i chiusi dal più recente", () => {
    /* l'ordine è la risposta a «di cosa mi devo occupare adesso»: una
       macchina ferma da dodici giorni non può stare sotto a una riparata */
    const FERMI = [
      { mezzo: "B", causale: "attesa-ricambi", inizio: "2026-07-20" },
      { mezzo: "A", causale: "guasto-meccanico", inizio: "2026-07-29" },
      { mezzo: "C", causale: "operatore", inizio: "2026-07-10", fine: "2026-07-12" },
      { mezzo: "D", causale: "verifica", inizio: "2026-07-25", fine: "2026-07-26" },
    ];
    eq(flotta.fermiOrdinati(FERMI, OGGI).map(f => f.mezzo), ["B", "A", "D", "C"], "ordine");
    contiene(flotta.fermiOrdinati(FERMI, OGGI)[0], { aperto: true, giorni: 12, causaleTx: "Attesa ricambi" },
      "la riga porta con sé durata, stato e motivo per esteso");
  });

  test("etichettaMese: «lug 2026», e un mese che non esiste non diventa gennaio", () => {
    eq(flotta.etichettaMese("2026-07"), "lug 2026", "mese normale");
    eq(flotta.etichettaMese("boh"), "—", "non è un mese");
    eq(flotta.etichettaMese("2026-13"), "? 2026", "mese fuori scala: si vede che è storto");
  });
  test("costiPerMese: le voci senza data non finiscono in nessun mese, e si dichiarano", () => {
    /* attribuirle a «oggi» sarebbe inventare un mese di competenza; farle
       sparire sarebbe peggio, perché quei soldi sono stati spesi davvero */
    const c = flotta.costiPerMese([
      { data: "2026-05-10", importo: 100 }, { data: "2026-07-01", importo: 250 },
      { data: "2026-07-20", importo: 50 }, { data: "", importo: 999 },
    ]);
    eq(c.senzaData, { voci: 1, importo: 999 }, "una voce senza data, dichiarata");
    eq(c.totale, 400, "e non entra nel totale dei mesi");
    eq(c.mesi.map(m => [m.ym, m.importo, m.voci]), [["2026-05", 100, 1], ["2026-07", 300, 2]], "mesi");
  });
  test("costiPerMese: un mese senza registrazioni NON è un mese a zero euro", () => {
    /* non compare fra i mesi — disegnarlo a zero direbbe «quel mese non
       abbiamo speso niente» — ma `mancanti` lo conta, così si può scrivere */
    const c = flotta.costiPerMese([{ data: "2026-05-10", importo: 100 }, { data: "2026-07-01", importo: 250 }]);
    eq(c.mesi.length, 2, "maggio e luglio");
    eq(c.mancanti, 1, "giugno manca, e lo dice");
    eq(flotta.costiPerMese([]).mancanti, 0, "senza dati non manca niente");
  });
  test("⛔ costiPerMese: «2026-02-30» non è un giorno, e non scivola al 2 marzo", () => {
    /* ⚠️ QUI LA REGOLA DELLE DATE ERA SCRITTA UNA SECONDA VOLTA E PIÙ DEBOLE:
       `/^\d{4}-\d{2}-\d{2}$/` più `Date.parse`, che un giorno inesistente non
       lo rifiuta — lo fa SCORRERE. Il 30 febbraio diventava il 2 marzo, e una
       spesa finiva attribuita a un mese in cui non è mai stata fatta, senza
       che niente lo segnalasse. La versione giusta (`dataISOEsiste`) è in
       `shared/` da mesi e la usa già `costoOrarioMezzo` nello stesso file.
       ⚠️ Misurato PRIMA di cambiarla: sulle 7 voci della dimostrazione le due
       regole danno lo stesso esito, quindi nessuna riga d'esempio si muove —
       il difetto c'era e non aveva ancora sporcato niente di quello che si
       vede. */
    const c = flotta.costiPerMese([{ data: "2026-02-30", importo: 500 },
                                   { data: "2026-03-05", importo: 100 }]);
    eq(c.senzaData, { voci: 1, importo: 500 },
       "il 30 febbraio vale come nessuna data: si dichiara, non si colloca");
    eq(c.mesi.map((m) => [m.ym, m.importo]), [["2026-03", 100]],
       "e marzo non si porta dentro 500 € spesi in un giorno che non esiste");
    // la controprova della permissività: le date vere continuano a passare
    eq(flotta.costiPerMese([{ data: "2026-02-29", importo: 10 }]).mesi.length, 0,
       "il 2026 non è bisestile: nemmeno il 29 febbraio esiste");
    eq(flotta.costiPerMese([{ data: "2024-02-29", importo: 10 }]).mesi[0].ym, "2024-02",
       "ma il 2024 sì, e quel giorno è buono");
  });

  test("disponibilitaStorico: dello stesso giorno vale l'ultima registrazione", () => {
    const s = flotta.disponibilitaStorico([
      { data: "2026-07-31", operativi: 9, totale: 10 },
      { data: "2026-07-31", operativi: 7, totale: 10 },
    ], 30, OGGI);
    eq(s.punti.length, 1, "un giorno, un punto");
    contiene(s.punti[0], { operativi: 7, pct: 70 }, "l'ultima situazione nota del giorno");
  });
  test("disponibilitaStorico: una riga incoerente si scarta, non si aggiusta", () => {
    /* 12 operativi su 10 non è un 120% da disegnare, ed è la ragione per cui
       il giorno finisce fra quelli SENZA registrazione invece che nel grafico */
    const s = flotta.disponibilitaStorico([
      { data: "2026-07-29", operativi: 8, totale: 10 },
      { data: "2026-07-30", operativi: 12, totale: 10 },
      { data: "2026-07-30", operativi: 3, totale: 0 },
    ], 30, OGGI);
    eq(s.punti.map(p => p.data), ["2026-07-29"], "resta solo il giorno buono");
    eq(s.giorniSenza, 29, "e i giorni senza registrazione si contano");
  });
  test("disponibilitaStorico: niente riempimenti, e la finestra taglia il passato", () => {
    /* un giorno senza registrazione non vale «tutto operativo»: semplicemente
       non c'è, e quanti sono si scrive accanto al grafico */
    const s = flotta.disponibilitaStorico([
      { data: "2026-06-01", operativi: 5, totale: 10 },
      { data: "2026-07-29", operativi: 8, totale: 10 },
    ], 30, OGGI);
    eq(s.punti.map(p => p.data), ["2026-07-29"], "il 1° giugno è fuori dai 30 giorni");
    contiene(s, { finestra: 30, giorniSenza: 29 }, "finestra e giorni senza");
    eq(flotta.disponibilitaStorico([], 30, OGGI).punti, [], "senza registrazioni nessun punto");
  });

  test("costoOfficinaPerMezzo: dal più caro, e conta anche QUANTE volte", () => {
    /* «3.000 € in un colpo» e «3.000 € in dieci volte» sono due storie
       diverse: la prima è un guasto, la seconda è una macchina da sostituire */
    const c = flotta.costoOfficinaPerMezzo([
      { mezzo: "CAT 320", costo: 3000 }, { mezzo: "CAT 320", costo: 1000 },
      { mezzo: "Volvo", costo: 500 }, { mezzo: "", costo: 200 },
      { mezzo: "Volvo", costo: 0 }, { mezzo: "Volvo", costo: -50 },
    ]);
    eq(c.totale, 4700, "totale");
    eq(c.mezzi.map(m => [m.mezzo, m.costo, m.interventi]),
      [["CAT 320", 4000, 2], ["Volvo", 500, 1], ["Senza mezzo", 200, 1]],
      "gli interventi a costo zero o negativo non entrano, e chi non ha mezzo si vede");
    eq(c.mezzi[0].pct, 85, "e il peso di ciascuno");
  });
  test("costoOfficinaPerMezzo: senza interventi non c'è nessuna percentuale da dare", () => {
    eq(flotta.costoOfficinaPerMezzo([]), { totale: 0, mezzi: [] }, "vuoto");
  });
}

// ── Flotta: ordini di lavoro, consumo ricambi, punto di riordino ──────
/* Qui stanno i soldi dell'officina e le scorte di magazzino: è la parte
   di Flotta dove un numero sbagliato costa davvero. Due idee la reggono, e
   sono tutt'e due nei commenti del modulo:
   · il costo di un ordine NON si scrive, si somma — così non può mai
     smentire le righe che uno ha davanti;
   · la soglia di riordino non è un numero che qualcuno ha scritto una
     volta: è consumo al giorno × giorni di consegna + margine, e quando il
     consumo non c'è la soglia NON si propone. */
{
  console.log("\n— Flotta: officina, ricambi, punto di riordino —");
  const OGGI = new Date("2026-07-31T10:00:00");

  test("statoOrdine: una manutenzione scritta prima di oggi è «da fare», non un errore", () => {
    /* è esattamente quello che era: la riga non deve cambiare aspetto
       perché è stata introdotta una colonna nuova */
    eq(flotta.statoOrdine({}).chiave, "da-fare", "senza stato");
    eq(flotta.statoOrdine({ stato: "boh" }).chiave, "da-fare", "stato non riconosciuto");
    eq(flotta.STATI_ORDINE.map(s => s.chiave), ["da-fare", "in-corso", "attesa-ricambi"], "i tre stati");
    ok(flotta.STATI_ORDINE.every(s => s.etichetta && s.breve && s.nota), "ognuno spiegato");
  });
  test("il rosso resta a chi aspetta un pezzo, non a chi sta lavorando", () => {
    /* un colore, un significato: se «in lavorazione» fosse rosso, il rosso
       non vorrebbe più dire niente */
    eq(flotta.STATI_ORDINE.find(s => s.chiave === "attesa-ricambi").cls, "danger", "attesa pezzi");
    eq(flotta.STATI_ORDINE.find(s => s.chiave === "in-corso").cls, "accent", "in lavorazione: colore dell'app");
  });

  test("costoOrdine: il costo si somma dalle righe, e non si scrive da nessuna parte", () => {
    const q = flotta.costoOrdine({
      manodopera: [{ chi: "Mario", ore: 2.5, tariffa: 35 }, { chi: "Luca", ore: 3, tariffa: 0 }],
      ricambi: [{ nome: "Filtro", qta: 2, prezzo: 24.5 }, { nome: "Olio", qta: 10, prezzo: 0 }],
      altreSpese: 120,
    });
    eq(q.totale, 256.5, "87,50 di manodopera + 49 di ricambi + 120 di spese");
    contiene(q.manodopera, { ore: 5.5, costo: 87.5, senzaTariffa: 1 }, "manodopera");
    contiene(q.ricambi, { pezzi: 12, costo: 49, senzaPrezzo: 1 }, "ricambi");
    eq(q.persone, 2, "due persone ci hanno messo le mani");
  });
  test("⛔ costoOrdine: quello che non ha prezzo si DICHIARA, non passa per gratis", () => {
    /* tre ore senza tariffa non sono tre ore gratis: sono tre ore di cui non
       si sa il costo, e l'app deve poterlo dire invece di sommare zero */
    const q = flotta.costoOrdine({
      manodopera: [{ chi: "Luca", ore: 3 }],
      ricambi: [{ nome: "Olio", qta: 10 }],
    });
    eq(q.manodopera.senzaTariffa, 1, "una riga di manodopera senza costo orario");
    eq(q.ricambi.senzaPrezzo, 1, "un ricambio senza prezzo");
    eq(q.totale, 0, "il totale è zero PERCHÉ non si sa, e i due contatori lo spiegano");
  });
  test("costoOrdine: un ordine vuoto non è un ordine da zero euro sbagliato", () => {
    const q = flotta.costoOrdine({});
    contiene(q, { totale: 0, persone: 0 }, "vuoto");
    contiene(q.manodopera, { senzaTariffa: 0 }, "niente da dichiarare");
  });

  test("ordineDaManutenzione: chi aveva collegato un pezzo lo ritrova già pronto", () => {
    /* la manutenzione vecchia aveva UN `ricambioId` e nessuna manodopera:
       diventa una riga con quantità 1 e il prezzo del magazzino */
    const CAT = [{ id: "r1", nome: "Filtro olio", prezzo: 24.5 }];
    eq(flotta.ordineDaManutenzione({ ricambioId: "r1" }, CAT).ricambi,
      [{ id: "r1", nome: "Filtro olio", qta: 1, prezzo: 24.5 }], "riga pronta dal catalogo");
    eq(flotta.ordineDaManutenzione({ ricambioId: "zz" }, CAT).ricambi[0].prezzo, 0,
      "un pezzo non più a catalogo non inventa un prezzo");
  });
  test("ordineDaManutenzione: le righe nuove tengono i decimali e ripuliscono i nomi", () => {
    const CAT = [{ id: "r2", nome: "Olio idraulico", prezzo: 3.2 }];
    const o = flotta.ordineDaManutenzione({
      stato: "in-corso", ricambiUsati: [{ id: "r2", qta: 12.5 }],
      manodopera: [{ chi: " Mario ", ore: "2.5", tariffa: 35 }],
      altreSpese: 120, noteLavoro: " sostituito ",
    }, CAT);
    eq(o.stato, "in-corso", "lo stato resta");
    contiene(o.ricambi[0], { nome: "Olio idraulico", qta: 12.5, prezzo: 3.2 }, "12,5 litri restano 12,5");
    eq(o.manodopera, [{ chi: "Mario", ore: 2.5, tariffa: 35 }], "spazi tolti, mezz'ora tenuta");
    eq(o.noteLavoro, "sostituito", "note ripulite");
  });

  test("validaRigaManodopera: «2,5» sono due ore e mezza, non venticinque", () => {
    /* è la convenzione dei numeri di tutto l'ecosistema: la virgola è
       decimale, e un campo che la mangiasse moltiplicherebbe per dieci */
    contiene(flotta.validaRigaManodopera({ chi: "Mario", ore: "2,5", tariffa: "35" }),
      { ok: true, ore: 2.5, tariffa: 35 }, "due ore e mezza");
  });
  test("validaRigaManodopera: senza nome no, oltre 24 ore in una riga no", () => {
    ok(/Scrivi chi/.test(flotta.validaRigaManodopera({ ore: 2 }).errori.chi), "una riga senza nome non serve");
    ok(/24 ore/.test(flotta.validaRigaManodopera({ chi: "Mario", ore: 25 }).errori.ore),
      "venticinque ore in un colpo è un errore di dito");
    ok(flotta.validaRigaManodopera({ chi: "Mario" }).errori.ore, "e le ore servono");
  });
  test("validaRigaManodopera: il costo orario può mancare, le ore restano registrate", () => {
    /* buttare via la riga perché non si sa la tariffa perderebbe il dato
       vero (chi ci ha lavorato e quanto) per colpa di uno che non si sa */
    contiene(flotta.validaRigaManodopera({ chi: "Mario", ore: 2 }), { ok: true, ore: 2, tariffa: 0 }, "senza tariffa si salva");
    ok(flotta.validaRigaManodopera({ chi: "Mario", ore: 2, tariffa: 5000 }).errori.tariffa, "mille euro l'ora no");
  });
  test("validaRigaRicambio: la quantità NON è per forza intera (olio e grasso a litri)", () => {
    /* con un campo type=number «12,5» diventava 125: dieci volte l'olio */
    contiene(flotta.validaRigaRicambio({ nome: "Olio", qta: "12,5", prezzo: "3,20" }),
      { ok: true, qta: 12.5, prezzo: 3.2 }, "dodici litri e mezzo");
    ok(flotta.validaRigaRicambio({ qta: 1 }).errori.nome, "senza nome no");
    ok(flotta.validaRigaRicambio({ nome: "Olio" }).errori.qta, "senza quantità no");
    contiene(flotta.validaRigaRicambio({ nome: "Olio", qta: 2 }), { ok: true, prezzo: 0 }, "senza prezzo si salva");
  });

  test("riepilogoOrdini: la stessa persona su due ordini è una persona sola", () => {
    /* «Mario» e «mario» sono lo stesso meccanico: contarlo due volte
       gonfierebbe la squadra che sta lavorando */
    const r = flotta.riepilogoOrdini([
      { stato: "in-corso", manodopera: [{ chi: "Mario", ore: 2 }] },
      { stato: "attesa-ricambi" }, {},
      { stato: "in-corso", manodopera: [{ chi: "mario", ore: 1.5 }, { chi: "Luca", ore: 1 }] },
    ]);
    contiene(r, { totale: 4, "da-fare": 1, "in-corso": 2, "attesa-ricambi": 1, oreAperte: 4.5, personeAperte: 2 },
      "riepilogo dell'officina");
  });

  const INT = [
    { data: "2026-07-01", ricambiUsati: [{ id: "r1", nome: "Filtro olio", qta: 2 }] },
    { data: "2026-06-01", ricambiUsati: [{ id: "r1", nome: "Filtro olio", qta: 1 }] },
    { data: "2026-05-01", ricambio: "Cinghia" },
    { data: "2020-01-01", ricambiUsati: [{ id: "r1", nome: "Filtro olio", qta: 99 }] },
    { data: "", ricambiUsati: [{ id: "r1", nome: "Filtro olio", qta: 50 }] },
  ];
  test("consumoRicambi: si legge dagli interventi, non si stima; e la finestra taglia", () => {
    const c = flotta.consumoRicambi(INT, 180, OGGI);
    contiene(c, { finestra: 180, da: "2026-02-02", a: "2026-07-31", interventi: 3 }, "finestra dichiarata");
    contiene(c.righe[0], { nome: "Filtro olio", pezzi: 3, episodi: 2 }, "i 99 pezzi del 2020 e i 50 senza data restano fuori");
  });
  test("consumoRicambi: con un episodio solo la media si dà, ma si dichiara fragile", () => {
    /* «un pezzo in sei mesi» non è una media: è un fatto capitato una volta,
       e su quello non si dimensiona un magazzino senza saperlo */
    const c = flotta.consumoRicambi(INT, 180, OGGI);
    eq(c.righe.find(r => r.nome === "Filtro olio").affidabile, true, "due episodi: si può guardare");
    eq(c.righe.find(r => r.nome === "Cinghia").affidabile, false, "un episodio: fragile");
  });
  test("consumoRicambi: gli interventi vecchi valgono un pezzo, e si contano a parte", () => {
    /* è quello che l'app scaricava dal magazzino allora: dire zero
       cancellerebbe un consumo vero, dire di più sarebbe inventato */
    const c = flotta.consumoRicambi(INT, 180, OGGI);
    eq(c.daInterventiVecchi, 1, "uno solo, e dichiarato");
    eq(c.righe.find(r => r.nome === "Cinghia").pezzi, 1, "un pezzo");
  });

  test("puntoDiRiordino: consumo al giorno × (consegna + margine), arrotondato in su", () => {
    /* è un conto che chiunque può rifare a mano, ed è per questo che l'app
       restituisce anche il valore esatto e la copertura */
    contiene(flotta.puntoDiRiordino(0.5, 15, 5), { soglia: 10, esatto: 10, copertura: 20 }, "mezzo pezzo al giorno per venti giorni");
    eq(flotta.puntoDiRiordino(0.0167, 15, 5).soglia, 1, "mai sotto un pezzo, se un consumo c'è");
  });
  test("⛔ puntoDiRiordino: senza consumo o senza tempi di consegna NON si propone niente", () => {
    /* proporre una soglia per un pezzo che non si sa quanto si usi è
       inventare un numero e poi difenderlo */
    eq(flotta.puntoDiRiordino(0, 15, 5), null, "nessun consumo");
    eq(flotta.puntoDiRiordino(0.5, 0, 5), null, "nessun tempo di consegna");
    eq(flotta.puntoDiRiordino(0.5, -3, 5), null, "una consegna negativa non è una consegna");
  });
  test("propostaScorte: chi non ha consumi resta A PARTE, non a soglia zero", () => {
    const p = flotta.propostaScorte(
      [{ id: "r1", nome: "Filtro olio", giacenza: 1, sogliaMin: 2, prezzo: 24.5 },
       { id: "r9", nome: "Mai usato", giacenza: 5, sogliaMin: 1, prezzo: 10 }],
      INT, { consegnaGiorni: 15, sicurezzaGiorni: 5, oggi: OGGI });
    eq(p.righe.map(r => r.nome), ["Filtro olio"], "solo chi ha un consumo misurato");
    eq(p.senzaConsumo.map(r => r.nome), ["Mai usato"], "l'altro è dichiarato, non proposto a zero");
    contiene(p, { consegna: 15, sicurezza: 5, finestra: 180, interventi: 3, daInterventiVecchi: 1 },
      "la proposta porta con sé su cosa è stata fatta");
  });
}

// ── Flotta: giro macchina, anagrafica del mezzo, libretto ─────────────
/* Il giro macchina è quello che porta in Flotta CHI GUIDA, non solo chi sta
   in ufficio: è il controllo di dieci minuti prima di salire, ed è da lì
   che nasce una manutenzione. Il libretto (`fascicoloMezzo`) è invece la
   pagina che un compratore guarda per prima.
   Tutto il blocco si regge su una convenzione sola — il NOME BREVE del
   mezzo — e su una distinzione: indovinare la checklist dal nome è
   innocuo, scrivere un dato indovinato nell'anagrafica non lo sarebbe. */
{
  console.log("\n— Flotta: giro macchina, anagrafica, libretto —");
  const OGGI = new Date("2026-07-31T10:00:00");

  test("nomeBreve: «Escavatore E1 — CAT 352» è il mezzo «Escavatore E1»", () => {
    /* è la chiave con cui manutenzioni, scadenze, interventi, controlli,
       fermi e rifornimenti si ritrovano: se cambia, si scollega tutto */
    eq(flotta.nomeBreve("Escavatore E1 — CAT 352"), "Escavatore E1", "il modello serve solo a leggere");
    eq(flotta.nomeBreve("  Pala P2  "), "Pala P2", "spazi tolti");
    eq(flotta.nomeBreve(null), "", "niente");
  });
  test("tipoMezzoDi: quello salvato vince, poi si indovina dal nome, poi «altro»", () => {
    eq(flotta.tipoMezzoDi({ tipo: "dumper", nome: "Escavatore E1" }).chiave, "dumper",
      "quello che l'utente ha SCELTO batte quello che il nome suggerisce");
    eq(flotta.tipoMezzoDi({ nome: "Escavatore E1 — CAT 352" }).chiave, "escavatore", "indovinato");
    eq(flotta.tipoMezzoDi({ nome: "Frantoio primario" }).chiave, "impianto", "indovinato dall'indizio");
    eq(flotta.tipoMezzoDi({ nome: "Macchina X" }).chiave, "altro", "non indovinabile");
    eq(flotta.tipoMezzoDi(null).chiave, "altro", "nessun mezzo");
    eq(flotta.tipoMezzo("zzz"), null, "un tipo che non esiste non diventa il primo dell'elenco");
  });
  test("checklistPreUso: sette voci per tutti, più quelle del tipo", () => {
    eq(flotta.checklistPreUso("altro").length, 7, "solo le comuni");
    eq(flotta.checklistPreUso("zzz").length, 7, "un tipo sconosciuto non aggiunge voci a caso");
    eq(flotta.checklistPreUso("perforatrice").length, 11, "sette comuni + quattro della perforatrice");
    ok(flotta.checklistPreUso("perforatrice").some(v => v.chiave === "polveri" && v.critica),
      "l'abbattimento polveri è una voce critica: è silice");
  });
  test("checklistPreUso: ogni chiamata torna un elenco NUOVO", () => {
    /* la pagina ci scrive dentro gli esiti: una lista condivisa farebbe
       comparire nel giro di domani le risposte di oggi */
    const a = flotta.checklistPreUso("pala");
    a.pop();
    eq(flotta.checklistPreUso("pala").length, 10, "l'originale non si è accorciato");
  });

  const VOCI = [
    { chiave: "livelli", esito: "ok", critica: false },
    { chiave: "freni", esito: "no", critica: true, etichetta: "Freni, sterzo e comandi" },
    { chiave: "luci", esito: "no", critica: false, etichetta: "Luci" },
    { chiave: "cabina", critica: false },
  ];
  test("⛔ riepilogoControllo: un giro con voci senza risposta NON è completo", () => {
    /* un controllo in cui non hai guardato non è un controllo, ed è il
       motivo per cui non si può salvare: `primaMancante` serve a portarci
       sopra chi compila invece di dirgli solo «no» */
    const r = flotta.riepilogoControllo(VOCI);
    contiene(r, { totali: 4, ok: 1, no: 2, mancanti: 1, completo: false, primaMancante: "cabina" }, "riepilogo");
    eq(flotta.riepilogoControllo([]).completo, false, "un giro vuoto non è un giro fatto");
  });
  test("riepilogoControllo: una voce di sicurezza «non va» fa scattare il rosso", () => {
    /* le altre anomalie sono un avviso; una voce critica è una macchina che
       non deve lavorare finché non è sistemata */
    const r = flotta.riepilogoControllo(VOCI);
    eq(r.gravita, "danger", "c'è una critica");
    eq(r.critiche.map(v => v.chiave), ["freni"], "e si sa quale");
    eq(flotta.riepilogoControllo([{ chiave: "luci", esito: "no" }]).gravita, "warn", "senza critiche resta un avviso");
    eq(flotta.riepilogoControllo([{ chiave: "a", esito: "ok" }]).gravita, "ok", "tutto a posto");
  });
  test("manutenzioniDaControllo: una manutenzione per ogni «non va», e si sa da dove viene", () => {
    const m = flotta.manutenzioniDaControllo({ mezzo: "Escavatore E1", data: "2026-07-30", voci: VOCI }, OGGI);
    eq(m.length, 2, "due voci segnate «non va»");
    contiene(m[0], { titolo: "Giro macchina: Freni, sterzo e comandi", mezzo: "Escavatore E1",
      dataPrevista: "2026-07-30", origine: "controllo" }, "la prima");
    ok(/sicurezza/.test(m[0].nota), "e la nota dice che era una voce di sicurezza");
    eq(flotta.manutenzioniDaControllo({ mezzo: "E1", voci: [{ esito: "ok" }] }, OGGI), [],
      "un giro pulito non apre niente");
  });
  test("manutenzioniDaControllo: senza data del giro vale oggi (vanno guardate subito)", () => {
    eq(flotta.manutenzioniDaControllo({ mezzo: "E1", voci: [{ esito: "no", etichetta: "Perdite" }] }, OGGI)[0].dataPrevista,
      "2026-07-31", "oggi");
  });
  test("controlliDelMezzo: si riconosce dal nome breve, dal più recente", () => {
    const CTRL = [
      { mezzo: "Escavatore E1 — CAT 352", data: "2026-07-29" },
      { mezzo: "Escavatore E1", data: "2026-07-31" },
      { mezzo: "Pala P2", data: "2026-07-31" },
    ];
    eq(flotta.controlliDelMezzo(CTRL, "Escavatore E1 — CAT 352").map(c => c.data),
      ["2026-07-31", "2026-07-29"], "nome lungo e nome breve sono lo stesso mezzo");
    eq(flotta.controlliDelMezzo(CTRL, "Dumper D9"), [], "un mezzo senza giri");
  });

  test("validaRifornimento: «45,8» litri e «1.250,75 €» arrivano interi", () => {
    /* quello che non si capisce viene DETTO, mai salvato come zero: su una
       spesa di gasolio uno zero è un buco nei costi che nessuno ritrova */
    contiene(flotta.validaRifornimento({ mezzo: "E1", litri: "45,8", euro: "1.250,75", ore: "1234,8", data: "2026-07-31" }, 1200),
      { ok: true, litri: 45.8, euro: 1250.75, ore: 1234.8 }, "i tre numeri");
  });
  test("validaRifornimento: il contatore non può tornare indietro", () => {
    /* un contaore che scende è quasi sempre una cifra saltata, e da lì
       esce un consumo orario senza senso */
    const v = flotta.validaRifornimento({ mezzo: "E1", litri: 40, data: "2026-07-31", ore: 900 }, 1200);
    ok(!v.ok && /1\.200 ore già registrate/.test(v.errori.ore), "lo dice col numero che ha già, raggruppato");
  });
  test("validaRifornimento: mezzo, litri e giorno servono; la spesa può mancare", () => {
    const e = flotta.validaRifornimento({}, null).errori;
    eq(Object.keys(e).sort(), ["data", "litri", "mezzo"], "tre cose");
    contiene(flotta.validaRifornimento({ mezzo: "E1", litri: 40, data: "2026-07-31" }, null),
      { ok: true, euro: 0, ore: null }, "senza spesa e senza contatore si salva lo stesso");
    ok(flotta.validaRifornimento({ mezzo: "E1", litri: 99999, data: "2026-07-31" }, null).errori.litri,
      "ventimila litri in un rifornimento no");
  });

  test("fotografiaDaRegistrare: una riga sola al giorno, e nessuna su un parco vuoto", () => {
    /* la funzione decide da sola se scrivere: è chiamata a ogni apertura e
       dopo ogni cambio di stato */
    const MEZZI = [{ nome: "E1", stato: "operativo" }, { nome: "P2", stato: "fermo" }];
    eq(flotta.fotografiaDaRegistrare([], [], "2026-07-31"), null, "niente parco, niente da fotografare");
    eq(flotta.fotografiaDaRegistrare([], MEZZI, "2026-07-31"),
      { azione: "aggiungi", dati: { data: "2026-07-31", operativi: 1, totale: 2 } }, "prima riga del giorno");
    eq(flotta.fotografiaDaRegistrare([{ id: "x", data: "2026-07-31", operativi: 1, totale: 2 }], MEZZI, "2026-07-31"),
      null, "riga già uguale: non si tocca niente");
    contiene(flotta.fotografiaDaRegistrare([{ id: "x", data: "2026-07-31", operativi: 2, totale: 2 }], MEZZI, "2026-07-31"),
      { azione: "aggiorna", id: "x" }, "un mezzo è stato fermato: la fotografia del giorno è l'ULTIMA nota");
    eq(flotta.fotografiaDaRegistrare([], MEZZI, "boh"), null, "senza un giorno valido non si scrive");
  });

  test("fascicoloMezzo: nel libretto entra solo quel mezzo, e il fermo c'è", () => {
    /* «tenuta bene» è una parola finché non ci sono i fermi accanto */
    const CTRL = [{ mezzo: "Escavatore E1 — CAT 352", data: "2026-07-29" }, { mezzo: "Pala P2", data: "2026-07-31" }];
    const F = flotta.fascicoloMezzo({ nome: "Escavatore E1 — CAT 352" }, {
      manutenzioni: [{ mezzo: "Escavatore E1", dataPrevista: "2026-08-10" }, { mezzo: "Pala P2", dataPrevista: "2026-08-01" }],
      interventi: [{ mezzo: "Escavatore E1", data: "2026-07-01", costo: 300, oreManodopera: 4 }],
      controlli: CTRL,
      rifornimenti: [{ mezzo: "Escavatore E1", data: "2026-07-01", litri: 100, euro: 150, ore: 1000 }],
      fermi: [{ mezzo: "Escavatore E1", causale: "guasto-meccanico", inizio: "2026-07-20", fine: "2026-07-22" }],
    }, OGGI);
    contiene(F, { nome: "Escavatore E1" }, "il nome breve");
    eq(F.tipo.chiave, "escavatore", "tipo indovinato dal nome");
    eq([F.manutenzioni.length, F.interventi.length, F.controlli.length], [1, 1, 1],
      "le righe della Pala P2 non entrano");
    contiene(F.officina, { totale: 300, interventi: 1, ore: 4 }, "officina");
    contiene(F.fermo, { episodi: 1, giorni: 3, aperti: 0 }, "un fermo di tre giorni, chiuso");
    eq(F.speso, 450, "300 di officina + 150 di gasolio");
  });
  test("fascicoloMezzo: un mezzo senza storia non inventa una storia", () => {
    const F = flotta.fascicoloMezzo({ nome: "Nuovo N1" }, {}, OGGI);
    eq([F.manutenzioni.length, F.interventi.length, F.controlli.length, F.fermi.length], [0, 0, 0, 0], "tutto vuoto");
    contiene(F, { speso: 0 }, "zero speso perché non c'è niente, e la pagina ha i contatori per dirlo");
    eq(F.ultimoControllo, null, "nessun giro fatto: null, non una data di comodo");
  });
  test("ritmoDelMezzo: si cerca col nome breve, e se non c'è risponde null", () => {
    eq(flotta.ritmoDelMezzo([{ mezzo: "Escavatore E1", oreGiorno: 7 }], "Escavatore E1 — CAT 352").oreGiorno, 7, "trovato");
    eq(flotta.ritmoDelMezzo([{ mezzo: "Pala P2" }], "Escavatore E1"), null, "non c'è: null, non un ritmo medio");
  });
  test("i piani di tagliando sono a ore motore, e uno sconosciuto non diventa il primo", () => {
    eq(flotta.PIANI_TAGLIANDO.map(p => p.ogniOre), [250, 500, 1000, 2000], "la scaletta");
    eq(flotta.pianoTagliando(500).chiave, "500", "si può cercare anche col numero");
    eq(flotta.pianoTagliando("999"), null, "un piano che non esiste");
    eq(flotta.ORIZZONTE_TAGLIANDI, 30, "l'orizzonte è di trenta giorni");
  });
}

// ── Conti: incassi veri, tempi di pagamento, DDT e fattura differita ──
/* Due parti, tenute insieme da una regola sola: **quello che non ha una
   data non entra in una media, e viene detto a parte.**
   · gli INCASSI: quanto è entrato davvero e in quanti giorni. Le fatture
     segnate «incassata» prima che esistesse la data d'incasso non hanno un
     giorno: contarle a zero giorni farebbe sembrare i clienti puntuali;
   · le PESATE/DDT: il netto NON si digita, è sempre lordo − tara, perché è
     il numero che va in fattura. E i pesi sono in TONNELLATE. */
{
  console.log("\n— Conti: incassi, tempi di pagamento, DDT —");
  const OGGI = new Date("2026-07-15T10:00:00");

  const FATT = [
    { id: "f1", cliente: "Rossi", emessa: "2026-06-01", scadenza: "2026-07-01", importo: 1000 },
    { id: "f2", cliente: "Rossi", emessa: "2026-05-01", scadenza: "2026-05-31", importo: 500,
      incassata: true, dataIncasso: "2026-06-10" },
    { id: "f3", cliente: "Bianchi", emessa: "2026-04-01", scadenza: "2026-05-01", importo: 300, incassata: true },
    { id: "f4", cliente: "Bianchi", emessa: "2026-07-01", scadenza: "2026-07-31",
      imponibile: 1000, ivaImporto: 220, totale: 1220 },
  ];
  const INC = [
    { fatturaId: "f1", data: "2026-07-10", importo: 400 },
    { fatturaId: "f1", data: "2026-06-20", importo: 600 },
    { fatturaId: "f9", data: "2026-07-01", importo: 999 },   // orfano: la fattura non c'è più
  ];

  test("movimentiDiFattura: solo i suoi, in ordine di data, a centesimi", () => {
    eq(flotta.nomeBreve("x"), "x", "guardia: siamo nel blocco di Conti, non di Flotta");
    eq(conti.movimentiDiFattura("f1", INC).map(m => [m.data, m.importo]),
      [["2026-06-20", 600], ["2026-07-10", 400]], "i due acconti in ordine");
    eq(conti.movimentiDiFattura("", INC), [], "senza id non si prende niente");
    eq(conti.movimentiDiFattura("f4", INC), [], "una fattura senza acconti");
  });
  test("statoIncasso: due acconti che coprono il totale saldano la fattura", () => {
    /* la somma degli acconti deve tornare col totale AL CENTESIMO, e il
       giorno del saldo è quello dell'ULTIMO movimento, non del primo */
    contiene(conti.statoIncasso(FATT[0], INC),
      { totale: 1000, incassato: 1000, residuo: 0, saldata: true, parziale: false,
        dataSaldo: "2026-07-10", giorniPagamento: 39, ritardoPagamento: 9 }, "f1 saldata");
  });
  test("⛔ statoIncasso: «incassata» senza data resta senza giorni, e lo dichiara", () => {
    /* è la fattura marcata incassata prima che la data esistesse: metterle
       zero giorni la farebbe entrare nelle medie come un pagamento
       immediato, cioè farebbe sembrare i clienti più puntuali di quanto sono */
    contiene(conti.statoIncasso(FATT[2], INC),
      { saldata: true, incassato: 300, dataSaldo: null, senzaData: true,
        giorniPagamento: null, ritardoPagamento: null }, "f3 senza data");
  });
  test("incassatoPeriodo: un movimento orfano non conta, e il periodo taglia", () => {
    /* i 999 € di «f9» non hanno più una fattura: sommarli gonfierebbe
       l'incassato di un numero che non si può nemmeno aprire */
    contiene(conti.incassatoPeriodo(FATT, INC, "2026-07-01", "2026-07-31"),
      { importo: 400, daMovimenti: 400, movimenti: 1 }, "solo l'acconto di luglio");
    contiene(conti.incassatoPeriodo(FATT, INC, "2026-06-01", "2026-06-30"),
      { daMovimenti: 600, senzaMovimenti: 500, fattureVecchie: 1 }, "giugno: l'acconto più la vecchia");
  });
  test("incassatoPeriodo: l'incassata senza data entra solo nel totale d'archivio", () => {
    /* non è databile: in un periodo non può stare, ma sparire sarebbe
       peggio — `senzaData` e `importoSenzaData` servono a scriverlo */
    contiene(conti.incassatoPeriodo(FATT, INC, "", ""),
      { importo: 1800, senzaData: 1, importoSenzaData: 300 }, "tutto l'archivio: i 300 ci sono");
    contiene(conti.incassatoPeriodo(FATT, INC, "2026-07-01", "2026-07-31"),
      { senzaData: 1, importoSenzaData: 300 }, "e in un periodo si dichiarano lo stesso");
  });
  test("tempiPagamentoClienti: la media si fa solo sulle date vere", () => {
    /* una media su date inventate sarebbe peggio di nessuna media */
    const t = conti.tempiPagamentoClienti(FATT, INC);
    contiene(t.find(x => x.cliente === "Rossi"),
      { conto: 2, importo: 1500, conGiorni: 2, giorniMedi: 40, ritardoMedio: 10 }, "Rossi");
    contiene(t.find(x => x.cliente === "Bianchi"),
      { conto: 1, senzaData: 1, giorniMedi: null, ritardoMedio: null },
      "Bianchi ha una fattura saldata ma senza data: nessuna media, e si vede");
  });
  test("tempoMedioPagamento: conta le saldate con data e dichiara le altre", () => {
    contiene(conti.tempoMedioPagamento(FATT, INC), { giorni: 40, conto: 2, senzaData: 1, ritardo: 10 }, "media");
    contiene(conti.tempoMedioPagamento([], []), { giorni: null, conto: 0, ritardo: null },
      "senza fatture non esiste un tempo medio: null, non zero giorni");
  });
  test("emessoIncassato: l'incassato sta nel mese in cui i soldi sono ENTRATI", () => {
    /* prima della data vera dell'incasso questo confronto non si poteva
       fare: l'incassato finiva nel mese di emissione, cioè copiava l'altra
       serie e il grafico mostrava due linee identiche */
    const e = conti.emessoIncassato(FATT, INC, 4, OGGI);
    eq(e.mesi.map(m => m.mese), ["2026-04", "2026-05", "2026-06", "2026-07"], "quattro mesi fino a oggi");
    contiene(e.mesi[2], { mese: "2026-06", emesso: 1000, incassato: 1100 },
      "giugno: emessa f1, entrati 600 di acconto + i 500 della f2 saldata il 10");
    contiene(e.mesi[3], { mese: "2026-07", emesso: 1220, incassato: 400 }, "luglio");
    contiene(e, { conDato: 4, emesso: 3020, incassato: 1500, senzaData: 1, importoSenzaData: 300 }, "totali");
  });

  const P_T = { prezzo: 12.5, unitaPrezzo: "t", densita: 1.6, iva: 22 };
  const P_M3 = { prezzo: 20, unitaPrezzo: "m3", densita: 1.6, iva: 22 };
  test("rigaPesata: il netto è lordo − tara, e i pesi sono in tonnellate", () => {
    /* il netto NON si digita: è il numero che va in fattura, quindi deve
       venire dal calcolo e non dalla mano di chi scrive */
    contiene(conti.rigaPesata(P_T, 32.5, 14.2), { netto: 18.3, unitaVendita: "t", quantita: 18.3, valore: 228.75 },
      "32,5 meno 14,2");
    contiene(conti.rigaPesata(P_T, 100, 500), { netto: 0, valore: 0 }, "una tara più grande del lordo non fa un netto negativo");
  });
  test("rigaPesata: se il prodotto si vende a metro cubo si converte con la densità", () => {
    contiene(conti.rigaPesata(P_M3, 32.5, 14.2), { unitaVendita: "m3", densita: 1.6, quantita: 11.438, valore: 228.76 },
      "18,3 t diviso 1,6");
  });
  test("⛔ rigaPesata: senza densità non si inventa una conversione", () => {
    /* meglio nessun numero che un numero falso: qui il valore è null e la
       pagina lo mostra come «manca la densità», non come «0 €» */
    contiene(conti.rigaPesata({ prezzo: 20, unitaPrezzo: "m3", iva: 22 }, 32.5, 14.2),
      { unitaVendita: "m3", densita: null, quantita: null, valore: null }, "niente conversione");
  });
  test("quantitaPesata: le tonnellate sono sempre vere, i metri cubi solo con la densità", () => {
    /* le tonnellate le ha pesate la bilancia; i m³ sono un conto */
    eq(conti.quantitaPesata({ netto: 18.3, quantita: 18.3, unitaVendita: "t", densita: 1.6 }),
      { t: 18.3, m3: 11.438 }, "con densità");
    eq(conti.quantitaPesata({ netto: 5, quantita: 5, unitaVendita: "t" }), { t: 5, m3: null }, "senza densità");
  });
  test("prezzoPerMetroCubo: si converte solo se la densità c'è", () => {
    eq(conti.prezzoPerMetroCubo(P_T), 20, "12,50 €/t × 1,6");
    eq(conti.prezzoPerMetroCubo(P_M3), 20, "già in €/m³");
    eq(conti.prezzoPerMetroCubo({ prezzo: 12.5, unitaPrezzo: "t" }), null, "senza densità: null");
    eq(conti.UNITA_LABEL.m3, "m³", "e l'unità si scrive col cubo, mai «M3»");
  });

  const PES = [
    { id: "p1", numero: "1", data: "2026-07-02", prodotto: "Misto", prodottoId: "m", netto: 18, quantita: 18, unitaVendita: "t", prezzoUnitario: 12.5, aliquotaIva: 22, densita: 1.6 },
    { id: "p2", numero: "2", data: "2026-07-03", prodotto: "Misto", prodottoId: "m", netto: 10, quantita: 10, unitaVendita: "t", prezzoUnitario: 12.5, aliquotaIva: 22, densita: 1.6 },
    { id: "p3", numero: "3", data: "2026-07-04", prodotto: "Misto", prodottoId: "m", netto: 10, quantita: 10, unitaVendita: "t", prezzoUnitario: 14, aliquotaIva: 22, densita: 1.6 },
    { id: "p4", numero: "4", data: "2026-07-05", prodotto: "Sabbia", prodottoId: "s", netto: 5, quantita: 5, unitaVendita: "t", prezzoUnitario: 20, aliquotaIva: 22 },
  ];
  test("fatturaDaPesate: stesso prodotto a prezzo diverso resta una riga diversa", () => {
    /* raggrupparli darebbe un prezzo unitario medio che non compare su
       nessun DDT e non si potrebbe spiegare al cliente */
    const F = conti.fatturaDaPesate(PES);
    eq(F.righe.map(r => [r.descrizione, r.prezzoUnitario, r.quantita, r.imponibile]),
      [["Misto", 12.5, 28, 350], ["Misto", 14, 10, 140], ["Sabbia", 20, 5, 100]], "tre righe");
    eq(F.righe[0].ddt, ["1", "2"], "e ogni riga porta i numeri dei DDT che la compongono");
  });
  test("fatturaDaPesate: totali, IVA e periodo dei documenti", () => {
    const F = conti.fatturaDaPesate(PES);
    contiene(F, { imponibile: 590, ivaImporto: 129.8, totale: 719.8, conto: 4,
      dal: "2026-07-02", al: "2026-07-05" }, "riepilogo");
  });
  test("fatturaDaPesate: senza nessun DDT non c'è nessuna fattura", () => {
    /* null, non una fattura vuota da zero euro che qualcuno può emettere */
    eq(conti.fatturaDaPesate([]), null, "nessun documento");
    eq(conti.fatturaDaPesate([null, undefined]), null, "e nemmeno righe finte");
  });
  test("venditePerProdotto: il materiale senza densità porta le tonnellate ma non i metri cubi", () => {
    /* le sue tonnellate sono vere (le ha pesate la bilancia), i suoi metri
       cubi no — e quindi nemmeno il valore per metro cubo può comprenderlo */
    const v = conti.venditePerProdotto(PES, "2026-07-01", "2026-07-31");
    contiene(v.find(r => r.prodotto === "Misto"), { t: 38, m3: 23.75, valore: 490, viaggi: 3, senzaDensita: 0 }, "Misto");
    contiene(v.find(r => r.prodotto === "Sabbia"),
      { t: 5, m3: 0, valore: 100, senzaDensita: 1, tSenzaDensita: 5, valoreConvertibile: 0 },
      "Sabbia: tonnellate sì, metri cubi no, e il valore resta fuori dai €/m³");
    eq(conti.venditePerProdotto(PES, "2026-08-01", "2026-08-31"), [], "fuori periodo: niente");
  });
}

// ── Sentinella: la strada da cui entrano i numeri dello strumento ─────
/* Il file del sismografo è la sorgente dei numeri che finiscono nel report
   per l'ente. Il 31/07 proprio da qui è uscito un difetto vero — una misura
   che spariva, annunciata all'utente come «1 doppione scartato» — e quindi
   questo pezzo va tenuto stretto riga per riga: il lettore CSV, il
   riconoscimento della data all'italiana, l'ora, la firma con cui si
   riconosce un doppione, e il taglio a MAX_LETTURE. */
{
  console.log("\n— Sentinella: import dallo strumento e serie storica —");

  test("leggiCsv: riconosce da solo il punto e virgola, la virgola e il TAB", () => {
    eq(sentinella.leggiCsv("Data;Ora;PPV\n12/07/2026;10:30;4,8\n").delim, ";", "punto e virgola");
    eq(sentinella.leggiCsv("Data\tOra\tPPV\n12/07/2026\t10:30\t4,8").delim, "\t", "TAB");
    eq(sentinella.leggiCsv("a,b,c\n1,2,3").delim, ",", "virgola");
  });
  test("leggiCsv: le virgolette proteggono il separatore e sé stesse", () => {
    /* senza questo, «b;c» dentro un campo diventerebbe due colonne e tutta
       la riga scivolerebbe: la data finirebbe nella colonna dell'ora */
    eq(sentinella.leggiCsv('a;"b;c";d').righe, [["a", "b;c", "d"]], "separatore dentro le virgolette");
    eq(sentinella.leggiCsv('a;"lui ha detto ""ok""";c').righe, [["a", 'lui ha detto "ok"', "c"]],
      "virgolette raddoppiate");
    eq(sentinella.leggiCsv('a;"riga1\nriga2";c').righe, [["a", "riga1\nriga2", "c"]], "a capo dentro un campo");
  });
  test("leggiCsv: BOM, fine riga Windows e righe vuote non fanno danni", () => {
    /* il BOM è il carattere invisibile che Excel mette in testa al file:
       senza toglierlo, la prima intestazione non verrebbe riconosciuta.
       ⚠️ Il BOM è protetto da DUE guardie indipendenti: il `replace` in
       testa a leggiCsv e il `trim()` su ogni cella — U+FEFF per
       `String.prototype.trim()` è uno spazio. Togliendone una sola la prova
       NON cade: misurato scrivendola. Chi domani volesse «semplificare»
       togliendo il replace deve sapere che a reggere resta il trim. */
    eq(sentinella.leggiCsv("﻿a;b\r\nc;d\r\n").righe, [["a", "b"], ["c", "d"]], "BOM + CRLF");
    eq(sentinella.leggiCsv("a;b\n\n\nc;d").righe, [["a", "b"], ["c", "d"]], "righe vuote via");
    eq(sentinella.leggiCsv("").righe, [], "file vuoto");
    eq(sentinella.leggiCsv(null).righe, [], "niente");
  });
  test("paresIntestazione: una riga che contiene un numero non è un'intestazione", () => {
    ok(sentinella.paresIntestazione([["Data", "Ora", "PPV"]]), "titoli");
    ok(!sentinella.paresIntestazione([["12/07/2026", "10:30", "4,8"]]), "già dati");
    ok(!sentinella.paresIntestazione([]), "niente righe");
    ok(!sentinella.paresIntestazione([["", "", ""]]), "riga vuota");
  });

  test("⛔ dataIso: due numeri di due cifre si leggono GIORNO/MESE, all'italiana", () => {
    /* è la regola dichiarata anche nella schermata. Leggerla all'americana
       sposterebbe le misure di mesi interi dentro un documento per l'ente */
    eq(sentinella.dataIso("12/07/2026"), "2026-07-12", "12 luglio, non 7 dicembre");
    eq(sentinella.dataIso("07/12/2026"), "2026-12-07", "e il 7 dicembre si scrive così");
  });
  test("dataIso: tutti i formati che si trovano negli export dello strumento", () => {
    for (const d of ["2026-07-12", "2026/07/12", "12/07/2026", "12-07-2026", "12.07.2026", "12/07/26"])
      eq(sentinella.dataIso(d), "2026-07-12", d);
    eq(sentinella.dataIso("12/07/2026 10:30"), "2026-07-12", "data e ora nella stessa cella");
    eq(sentinella.dataIso("12/07/68"), "2068-07-12", "l'anno a due cifre gira sul 70");
  });
  test("⛔ dataIso: una data che non esiste viene SCARTATA, non «corretta»", () => {
    /* il 31 febbraio non è il 3 marzo: correggerlo in silenzio metterebbe
       nel registro una misura in un giorno in cui non è stata fatta */
    eq(sentinella.dataIso("31/02/2026"), "", "31 febbraio");
    eq(sentinella.dataIso("13/13/2026"), "", "mese tredici");
    eq(sentinella.dataIso("boh"), "", "non è una data");
    eq(sentinella.dataIso(""), "", "vuoto");
  });
  test("oraHm: solo i due punti separano l'ora, e le ore impossibili non passano", () => {
    /* col punto «12.07» sarebbe la data, non le dodici e sette */
    eq(sentinella.oraHm("10:30"), "10:30", "ora e minuti");
    eq(sentinella.oraHm("10:30:12"), "10:30", "i secondi si buttano");
    eq(sentinella.oraHm("12/07/2026 10:30"), "10:30", "dentro una data completa");
    eq(sentinella.oraHm("12.07"), "", "col punto è una data");
    eq(sentinella.oraHm("25:00"), "", "le 25 non esistono");
    eq(sentinella.oraHm("10:75"), "", "e nemmeno il minuto 75");
    eq(sentinella.oraHm(null), "", "niente");
  });

  test("chiaveOrdine: una lettura senza ora resta all'inizio del suo giorno", () => {
    /* è il comportamento di prima dell'import: nessuna serie storica già
       salvata cambia forma perché è stata aggiunta la colonna dell'ora */
    ok(sentinella.chiaveOrdine({ data: "2026-07-12" }) < sentinella.chiaveOrdine({ data: "2026-07-12", ora: "00:01" }),
      "senza ora viene prima");
    ok(sentinella.chiaveOrdine({ data: "2026-07-12", ora: "23:59" }) < sentinella.chiaveOrdine({ data: "2026-07-13" }),
      "e mai dopo il giorno seguente");
  });
  test("⛔ firmaLettura: stessa data, stessa ora, stesso valore = stessa lettura", () => {
    /* è la firma che ha causato il difetto del 31/07: quando l'ora veniva
       persa, due misure diverse dello stesso giorno diventavano un doppione
       e la seconda spariva dal report per l'ente, annunciata come «1
       doppione scartato». La difesa vera sta a monte (l'ora si legge anche
       dalla cella della data); qui si blinda che l'ORA ENTRI nella firma. */
    const a = { data: "2026-07-12", ora: "10:30", valore: 4.8 };
    const b = { data: "2026-07-12", ora: "11:00", valore: 4.8 };
    ok(sentinella.firmaLettura(a) !== sentinella.firmaLettura(b),
      "stesso giorno e stesso valore, ORE diverse: sono due misure");
    eq(sentinella.firmaLettura(a), sentinella.firmaLettura({ ...a }), "la stessa lettura ha la stessa firma");
  });
  test("unisciLetture: scarta i doppioni anche DENTRO lo stesso file", () => {
    /* reimportare il file della settimana che si sovrappone alla precedente
       non deve raddoppiare la serie: su un documento per l'ente è un falso */
    const r = sentinella.unisciLetture(
      [{ data: "2026-07-12", ora: "10:30", valore: 4.8 }],
      [{ data: "2026-07-12", ora: "10:30", valore: 4.8 },
       { data: "2026-07-12", ora: "11:00", valore: 5.2 },
       { data: "2026-07-12", ora: "11:00", valore: 5.2 }]);
    contiene(r, { aggiunte: 1, duplicati: 2, tagliate: 0 }, "uno già c'era, uno era ripetuto nel file");
    eq(r.letture.length, 2, "restano due letture");
  });
  test("unisciLetture: oltre il tetto si tengono le ULTIME, e il taglio si dichiara", () => {
    /* buttare le più recenti sarebbe assurdo; buttarle in silenzio anche */
    const r = sentinella.unisciLetture([], Array.from({ length: 5 }, (_, i) => ({ data: "2026-07-1" + i, valore: i + 1 })), 3);
    eq(r.letture.length, 3, "il tetto vale");
    eq(r.letture[0].data, "2026-07-12", "sono le tre più recenti");
    contiene(r, { aggiunte: 5, tagliate: 2 }, "e quante ne sono state tagliate si sa");
    eq(sentinella.MAX_LETTURE, 500, "il tetto vero è 500: 50 butterebbe quasi tutto un file appena importato");
  });

  test("unitaMisura: l'unità scritta dall'utente ha sempre la priorità", () => {
    /* il ripiego per tipo serve solo quando l'utente non ha detto niente:
       se ha scritto lui l'unità, è quella dell'autorizzazione */
    eq(sentinella.unitaMisura({ unita: "mm/s ", tipo: "rumore" }), "mm/s", "vince quella scritta");
    eq(sentinella.unitaMisura({ tipo: "Rumore" }), "dB(A)", "ripiego per tipo, anche col maiuscolo");
    eq(sentinella.unitaMisura({ tipo: "boh" }), "", "tipo sconosciuto: nessuna unità inventata");
    eq(sentinella.UNITA_TIPO.polveri, "µg/m³", "e le unità si scrivono per esteso, mai in maiuscolo");
  });
  test("serieStorica: le letture si ordinano per data E ORA", () => {
    /* con l'import arrivano molte letture nello stesso giorno: una serie
       fuori ordine racconterebbe un andamento che non è mai esistito */
    const g = sentinella.serieStorica({ tipo: "vibrazioni", soglia: 5, letture: [
      { data: "2026-07-12", ora: "11:00", valore: 5.2 },
      { data: "2026-07-12", ora: "10:30", valore: 4.8 },
      { data: "2026-07-10", valore: 2.1 },
      { data: "2026-07-11", valore: "x" },
    ] }, {});
    contiene(g, { vuoto: false, n: 3, unita: "mm/s", soglia: 5, superamenti: 1, max: 5.2, ultimo: 5.2 },
      "tre letture buone, una scartata perché il valore non è un numero");
    ok(g.path.startsWith("M"), "e la geometria della linea esiste");
  });
  test("serieStorica: senza letture non c'è nessuna linea da disegnare", () => {
    const g = sentinella.serieStorica({ tipo: "rumore" }, {});
    contiene(g, { vuoto: true, n: 0, unita: "dB(A)", soglia: null, path: "", superamenti: 0 }, "vuota");
    eq(g.punti, [], "nessun punto");
  });
  test("⛔ serieStorica: la soglia è quella impostata, e se schiaccia i dati lo dice", () => {
    /* la soglia non si inventa mai: senza, è null. E una soglia molto più
       alta dei dati appiattirebbe la linea a filo dell'asse — allora resta
       segnata come `fuoriScala` invece di rendere illeggibile il grafico */
    eq(sentinella.serieStorica({ tipo: "vibrazioni", letture: [{ data: "2026-07-10", valore: 1 }] }, {}).soglia, null,
      "nessuna soglia impostata: nessuna soglia disegnata");
    const g = sentinella.serieStorica({ tipo: "vibrazioni", soglia: 500, letture: [{ data: "2026-07-10", valore: 1 }] }, {});
    contiene(g.lineaSoglia, { valore: 500, fuoriScala: true }, "soglia dichiarata fuori scala");
  });
  test("i tipi di ricettore sono una lista chiusa, e uno sconosciuto non diventa «abitazione»", () => {
    eq(sentinella.TIPI_RICETTORE.map(t => t.chiave),
      ["abitazione", "scuola", "ospedale", "confine", "storico", "altro"], "i sei tipi");
    eq(sentinella.etichettaTipo("scuola"), "Scuola", "noto");
    eq(sentinella.etichettaTipo("zzz"), "Ricettore", "sconosciuto: generico, non il primo dell'elenco");
  });
}

// ── Scudo: liste da toccare, DPI, e la data di «fra N giorni» ─────────
/* Le liste di Scudo non sono decorazione: un near miss «o lo segnali in
   pochi secondi o non lo segnala nessuno», e si segnala TOCCANDO una
   categoria e un luogo. Una chiave sconosciuta non deve mai diventare la
   prima voce dell'elenco — su un registro di sicurezza vorrebbe dire
   attribuire un evento a un rischio che non è quello. */
{
  console.log("\n— Scudo: liste, DPI, date proposte —");

  test("near miss: categorie e luoghi sono liste chiuse, e l'ignoto resta vuoto", () => {
    eq(scudo.categoriaNearMiss("caduta-massi"), "Caduta massi", "categoria nota");
    eq(scudo.categoriaNearMiss("zzz"), "", "sconosciuta: stringa vuota, MAI la prima dell'elenco");
    eq(scudo.luogoNearMiss("fronte"), "Fronte", "luogo noto");
    eq(scudo.luogoNearMiss("zzz"), "", "sconosciuto");
    ok(scudo.NEARMISS_CATEGORIE.some(c => c.chiave === "volata"), "la volata c'è: è un rischio di cava");
    ok(scudo.NEARMISS_LUOGHI.some(l => l.chiave === "fronte"), "e il fronte pure");
    ok(scudo.NEARMISS_CATEGORIE.every(c => c.chiave && c.etichetta), "ogni voce ha chiave ed etichetta");
  });
  test("esiti dell'ispezione: tre soli, e «non applicabile» non è «conforme»", () => {
    /* segnare N/A come conforme farebbe risultare controllata una cosa che
       in quella cava non esiste nemmeno */
    eq(scudo.ESITI_ISPEZIONE.map(e => e.chiave), ["conforme", "non-conforme", "na"], "i tre esiti");
    eq(scudo.ESITI_ISPEZIONE.find(e => e.chiave === "non-conforme").cls, "danger", "la non conformità è rossa");
    eq(scudo.ESITI_ISPEZIONE.find(e => e.chiave === "na").cls, "tag", "e N/A è neutro, non verde");
    eq(scudo.esitoLabel("zzz"), null, "un esito che non esiste non diventa «conforme»");
  });
  test("i tipi di documento coprono il doppio binario 81/2008 + 624/1996", () => {
    /* il DSS è il documento di sicurezza e salute dell'attività estrattiva:
       senza, Scudo non sarebbe un'app per cave */
    for (const t of ["DSS", "DVR", "POS", "DUVRI", "Nomina"]) ok(scudo.TIPI_DOCUMENTO.includes(t), t);
    eq(scudo.TIPI_DOCUMENTO[scudo.TIPI_DOCUMENTO.length - 1], "Altro", "«Altro» in fondo, non in mezzo");
    eq(scudo.ORIGINI_AMBIENTE, ["superamento", "reclamo"], "le due origini che arrivano da Sentinella");
  });

  test("dataPiuGiorni: conta in giorni di CALENDARIO LOCALI, non in ore", () => {
    /* è la stessa regola del giorno locale che il 31/07 è costata quaranta
       correzioni: costruire la data con i pezzi locali e non passare da
       toISOString, se no fra mezzanotte e le due si scivola al giorno prima */
    eq(scudo.dataPiuGiorni(30, new Date("2026-07-15T10:00:00")), "2026-08-14", "trenta giorni avanti");
    eq(scudo.dataPiuGiorni(0, new Date("2026-05-01T00:30:00")), "2026-05-01",
      "mezzanotte e mezza del primo maggio è ancora il primo maggio");
    eq(scudo.dataPiuGiorni(-10, new Date("2026-07-15T10:00:00")), "2026-07-05", "e si può andare indietro");
  });
  test("⛔ dataPiuGiorni: senza un numero di giorni non propone NESSUNA data", () => {
    /* La trappola c'era, ed è stata chiusa il 02/08 nel passaggio a `shared/`.
       `Number(null)` è **0** — la famiglia di `+null === 0` già costata due
       volte qui dentro — e quindi «nessun numero di giorni» diventava «scade
       oggi»: su un'azione correttiva, una scadenza che qualcuno firma.
       Non era raggiungibile (i punti che la chiamano passano un 30 scritto a
       mano, o guardano prima `i.periodicitaGiorni`), ma stava in DUE copie
       identiche — Scudo e Sentinella — e chiuderla in un posto solo l'ha
       chiusa in tutt'e due. */
    eq(scudo.dataPiuGiorni("boh", new Date("2026-07-15T10:00:00")), null, "una parola: nessuna data");
    eq(scudo.dataPiuGiorni(null, new Date("2026-07-15T10:00:00")), null, "e nemmeno il niente");
    eq(scudo.dataPiuGiorni("", new Date("2026-07-15T10:00:00")), null, "né il vuoto");
  });
  test("normalizzaTesto: «Idoneità» e «idoneita» sono la stessa cosa", () => {
    /* serve a riconoscere che «Corso antincendio» e «Antincendio —
       aggiornamento addetti» parlano dello stesso obbligo */
    eq(scudo.normalizzaTesto("Corso Antincendio — aggiornamento addetti!"),
      "corso antincendio aggiornamento addetti", "minuscole, senza accenti né punteggiatura");
    eq(scudo.normalizzaTesto("Idoneità"), "idoneita", "accento tolto");
    eq(scudo.normalizzaTesto(null), "", "niente");
  });
  test("MESI_NOMI: dodici mesi in italiano, minuscoli", () => {
    eq(scudo.MESI_NOMI.length, 12, "dodici");
    eq([scudo.MESI_NOMI[0], scudo.MESI_NOMI[11]], ["gennaio", "dicembre"], "primo e ultimo");
    ok(scudo.MESI_NOMI.every(m => m === m.toLowerCase()), "minuscoli: vanno dentro una frase");
  });

  test("tipoDpi: un DPI sconosciuto non prende i requisiti di un altro", () => {
    /* `tipoDpiSicuro` serve a non far sparire dalla tabella un dispositivo
       scritto a mano: gli dà un guscio neutro, NON quello del primo tipo */
    eq(scudo.tipoDpi("zzz"), null, "non c'è");
    const s = scudo.tipoDpiSicuro("zzz");
    contiene(s, { chiave: "zzz", cat: "II", addestramento: false, mesi: null }, "guscio neutro");
    contiene(scudo.tipoDpi("maschera"), { cat: "III", addestramento: true },
      "la maschera è III categoria: l'addestramento è obbligatorio (art. 77)");
  });
  test("⛔ statoConsegnaDpi: un DPI mai consegnato è «mancante», non «regolare»", () => {
    contiene(scudo.statoConsegnaDpi(null), { stato: "mancante", scadenza: null, addestramentoMancante: false },
      "nessuna consegna");
    contiene(scudo.statoConsegnaDpi({ tipo: "elmetto", scadenza: "2020-01-01" }, new Date("2026-07-15")),
      { stato: "scaduta" }, "consegnato ma da sostituire");
  });
  test("statoConsegnaDpi: l'addestramento non fatto si vede anche se il DPI è in corso", () => {
    /* un facciale filtrante consegnato senza addestramento è una consegna
       incompleta, non una consegna a posto con un dettaglio in meno */
    contiene(scudo.statoConsegnaDpi({ tipo: "maschera", scadenza: "2099-01-01" }, new Date("2026-07-15")),
      { stato: "regolare", addestramentoMancante: true }, "manca l'addestramento");
    contiene(scudo.statoConsegnaDpi({ tipo: "maschera", scadenza: "2099-01-01", addestramento: true }, new Date("2026-07-15")),
      { addestramentoMancante: false }, "fatto");
  });
  test("⚠️ statoConsegnaDpi: una consegna SENZA data di sostituzione risulta regolare", () => {
    /* Comportamento di oggi, scritto qui perché è una DOMANDA APERTA, non
       una regola decisa (punto 14 di DECISIONI_WEEKEND.md).
       Il form propone da sé la scadenza dai mesi del tipo, ma l'utente può
       svuotarla: da lì in poi una maschera di III categoria non produce
       nessun allarme di sostituzione, mai. Le due letture sono:
       (a) l'ha svuotata apposta, quel dispositivo non scade → regolare;
       (b) nessuno ha detto entro quando va sostituito → non è un verde.
       Finché non è deciso, la prova blinda quello che il codice fa DAVVERO,
       così se cambia si sa che è stato scelto e non successo. */
    contiene(scudo.statoConsegnaDpi({ tipo: "maschera" }, new Date("2026-07-15")),
      { stato: "regolare", scadenza: null }, "oggi: regolare");
    eq(scudo.tipoDpi("maschera").mesi, 12, "eppure il tipo dice dodici mesi");
  });
  test("MANSIONI_PRESET: sono una base di partenza, e ogni mansione porta requisiti e DPI", () => {
    /* «base da adattare al DVR e al DSS della propria cava, non un elenco
       di verità di legge»: la prova blinda la forma, non i contenuti */
    ok(scudo.MANSIONI_PRESET.length >= 5, "abbastanza mansioni da partire");
    for (const m of scudo.MANSIONI_PRESET) {
      ok(m.chiave && m.nome, "chiave e nome: " + m.chiave);
      ok(Array.isArray(m.requisiti) && Array.isArray(m.dpi), "requisiti e dpi sono elenchi: " + m.chiave);
    }
    const f = scudo.MANSIONI_PRESET.find(m => m.chiave === "fochino");
    ok(f.requisiti.includes("fochino"), "il fochino ha bisogno del suo titolo");
    ok(f.dpi.includes("otoprotettori"), "e degli otoprotettori");
  });
  test("ruoloNomina: un ruolo che non esiste non diventa RSPP", () => {
    contiene(scudo.ruoloNomina("rspp"), { chiave: "rspp", obbligatoria: true }, "l'RSPP c'è ed è obbligatorio");
    eq(scudo.ruoloNomina("zzz"), null, "un ruolo inventato non prende il posto di uno vero");
  });
}

// ── Terra: la denuncia annuale dei volumi e le scadenze del titolo ────
/* Il numero che esce da qui va all'ente, e la distinzione che lo regge è
   una sola: lo SCAVO consuma il volume concesso, la RIPRESA DA UN CUMULO
   no — è materiale già estratto in passato. Sommarli è «l'errore che si
   vede fare più spesso sui fogli di calcolo», e su una denuncia significa
   dichiarare di aver consumato titolo che non è stato consumato. */
{
  console.log("\n— Terra: denuncia annuale e scadenze del titolo —");
  const OGGI = new Date("2026-07-15T10:00:00");
  const RIL = [
    { id: "r1", data: "2026-03-10", stato: "elaborato", volumeM3: 1000, fronteId: "f1" },
    { id: "r2", data: "2026-05-20", stato: "elaborato", volumeM3: 800, fronteId: "f1" },
    { id: "r3", data: "2025-11-05", stato: "elaborato", volumeM3: 500, fronteId: "f1" },
    { id: "r4", data: "2026-06-01", stato: "elaborato", volumeM3: 300, fronteId: null, provenienza: "cumulo" },
    { id: "r5", data: "2026-04-01", stato: "bozza", volumeM3: 999, fronteId: "f1" },
    { id: "r6", data: "2026-04-02", stato: "elaborato", volumeM3: null, fronteId: "f1" },
    { id: "r7", data: "boh", stato: "elaborato", volumeM3: 100, fronteId: "f1" },
    { id: "r8", data: "2026-02-01", stato: "elaborato", volumeM3: 200, fronteId: "f2" },
  ];
  const AUT = { volumeAutorizzatoM3: 10000, estrattoPregressoM3: 1000 };

  test("⛔ rilievoUsabile: «questo rilievo si può usare» è UNA condizione sola", () => {
    /* Era scritta DIECI volte in terra-data.js, in tre varianti. Un rilievo in
       bozza che cominciasse a contare in UNO solo dei dieci punti non darebbe
       nessun errore: darebbe un numero diverso, in un documento che va
       all'ente. La prova blinda la condizione, non i dieci punti. */
    ok(terra.rilievoUsabile({ stato: "elaborato", volumeM3: 100 }), "elaborato con volume");
    ok(!terra.rilievoUsabile({ stato: "bozza", volumeM3: 100 }), "una bozza non è un numero da usare");
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: null }), "senza volume non c'è niente da contare");
    ok(!terra.rilievoUsabile({ stato: "elaborato" }), "e nemmeno col campo assente");
    ok(!terra.rilievoUsabile(null), "niente");
    /* uno ZERO scritto è un volume vero: si è misurato, e faceva zero */
    ok(terra.rilievoUsabile({ stato: "elaborato", volumeM3: 0 }), "un volume di zero è comunque una misura");
    /* ⛔ E «con un volume» vuol dire CON UN NUMERO. Fino al 01/08 la condizione
       era `volumeM3 != null`, che lascia passare la stringa vuota e il testo:
       quei rilievi risultavano usabili e ogni somma li leggeva `+v || 0`, cioè
       li contava come una misura di ZERO. Un volume che non si legge non è un
       volume misurato zero. */
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: "" }), "stringa vuota: non è una misura di zero");
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: "   " }), "e nemmeno spazi");
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: "abc" }), "un testo non è un volume");
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: {} }), "né un oggetto");
    ok(!terra.rilievoUsabile({ stato: "elaborato", volumeM3: NaN }), "né NaN");
    /* un numero scritto come stringa resta un numero: gli import lo producono */
    ok(terra.rilievoUsabile({ stato: "elaborato", volumeM3: "1200" }), "«1200» è un volume");
  });
  /* ── L'ONERE DI ESCAVAZIONE (docs/RICERCA_DOCUMENTI_ENTI_202607.md, 2°) ── */
  const RIL_ONERE = [
    { id: "a", data: "2026-03-01", stato: "elaborato", volumeM3: 12000, provenienza: "scavo" },
    { id: "b", data: "2026-06-01", stato: "elaborato", volumeM3: 8000, provenienza: "scavo" },
    { id: "c", data: "2026-07-01", stato: "elaborato", volumeM3: 3000, provenienza: "cumulo" },
  ];
  const AUT_ONERE = { volumeAutorizzatoM3: 1200000, estrattoPregressoM3: 100000, dataRilascio: "2020-01-01" };
  const riepOnere = (ril, anno = 2026) =>
    terra.riepilogoAnnuale(ril, anno, AUT_ONERE, new Date("2026-08-01T00:00:00"));

  test("baseOnereEscavazione: si paga lo SCAVO, non il cumulo ripreso", () => {
    const o = terra.baseOnereEscavazione(riepOnere(RIL_ONERE));
    eq(o.calcolabile, true, "con i rilievi di scavo la base si dichiara");
    eq(o.lordo, 20000, "i 3.000 m³ di cumulo NON entrano: è materiale già estratto");
    eq(o.imponibile, 20000, "senza detrazioni l'imponibile è il lordo");
  });
  test("baseOnereEscavazione: il volume recuperato si detrae, e se eccede lo dice", () => {
    const o = terra.baseOnereEscavazione(riepOnere(RIL_ONERE), { volumeDetrattoM3: 2000 });
    eq(o.imponibile, 18000, "20.000 − 2.000");
    const troppo = terra.baseOnereEscavazione(riepOnere(RIL_ONERE), { volumeDetrattoM3: 99999 });
    eq(troppo.imponibile, 0, "l'imponibile non va sotto zero");
    ok(troppo.avvisi.length === 1 && /supera lo scavo/.test(troppo.avvisi[0]),
      "ma non lo fa in silenzio: uno dei due numeri va rivisto");
  });
  test("⛔ serieAnnuale: un anno senza rilievi di SCAVO non vale «scavati 0 m³»", () => {
    /* Trovato guardando lo scatto: la riga dell'anno 2024 (sole riprese da
       cumulo) diceva «Scavati 0 m³» accanto a una pastiglia tranquilla. Quello
       zero l'ente lo legge come una dichiarazione di non-estrazione, mentre la
       verità è che il fronte non l'ha rilevato nessuno.
       ⚠️ `misurabile` NON copre questo caso: parla del titolo nel suo insieme
       e resta vero mentre il singolo anno è cieco — per questo serve
       `rilieviScavo` sulla riga. */
    const S = terra.serieAnnuale(RIL_ONERE, AUT_ONERE, new Date("2026-08-01T00:00:00"));
    const y = S.find(x => x.anno === 2026);
    ok(y && y.rilieviScavo === 2, `l'anno misurato porta la conta dei rilievi di scavo: ${y && y.rilieviScavo}`);
    const soloCumulo = terra.serieAnnuale([RIL_ONERE[2]], AUT_ONERE, new Date("2026-08-01T00:00:00"));
    eq(soloCumulo.length, 1, "l'anno di solo cumulo compare comunque nello storico");
    eq(soloCumulo[0].rilieviScavo, 0, "ma con ZERO rilievi di scavo: la pagina scrive «Scavo non misurato»");
    ok(soloCumulo[0].cumulo > 0, "e il cumulo ripreso resta, perche' quello e' stato misurato davvero");
  });

  test("⛔ TERRA NON FA EURO: la base è in metri cubi, l'aliquota vive in Conti", () => {
    /* La prima versione moltiplicava per una tariffa €/m³ e restituiva un
       importo: era la TERZA scrittura della regola di `canonePeriodo` (Conti),
       che l'aliquota ce l'ha davvero, sa scegliere fra €/t e €/m³ e per lo
       scavato legge `misuratoPeriodo` di shared/. E la pagina di Terra scrive
       al cliente «il conto in euro non lo fa Terra»: il modulo contraddiceva
       in silenzio una decisione dichiarata a schermo.
       ⚠️ `nomi-doppi.mjs` non poteva vederlo: i nomi erano diversi. Quel
       controllo prende lo stesso NOME in due app, non la stessa REGOLA. */
    const o = terra.baseOnereEscavazione(riepOnere(RIL_ONERE), { volumeDetrattoM3: 2000 });
    for (const k of ["importo", "tariffa", "euro", "dovuto"])
      eq(o[k], undefined, `la base non porta «${k}»: l'euro non si calcola qui`);
    const f = terra.descriviBaseOnere(o);
    ok(!/€/.test(f), `e la frase non nomina nessun importo: «${f}»`);
    ok(/Conti/.test(f), "ma dice dove si fa il conto, invece di lasciare un buco");
  });
  test("⛔ baseOnereEscavazione: un anno con SOLO CUMULO non vale «zero dovuto»", () => {
    /* È il caso che ha cambiato il disegno. Un rilievo di cumulo misura IL
       MUCCHIO, non il fronte: di quanto sia stato tolto dal fronte quell'anno
       non si sa niente. Scrivere «0 m³» all'ente sarebbe dichiarare in difetto
       una cosa che nessuno ha misurato. */
    const soloCumulo = terra.baseOnereEscavazione(riepOnere([RIL_ONERE[2]]));
    eq(soloCumulo.calcolabile, false, "un rilievo c'è, ma non misura il fronte");
    eq(soloCumulo.imponibile, null, "quindi niente imponibile: un trattino, non zero");
    ok(/non misurato/.test(soloCumulo.motivo),
      "e il motivo deve dire che «zero misurato» e «non misurato» non sono la stessa cosa");
    const nessunRilievo = terra.baseOnereEscavazione(riepOnere([], 2025));
    eq(nessunRilievo.calcolabile, false, "e un anno senza nessun rilievo idem");
  });

  test("descriviBaseOnere: la frase che va all'ente la scrive il modulo, non la pagina", () => {
    const o = terra.baseOnereEscavazione(riepOnere(RIL_ONERE), { volumeDetrattoM3: 2000 });
    const f = terra.descriviBaseOnere(o);
    ok(/18\.000 m³/.test(f), `l'imponibile va scritto all'italiana: «${f}»`);
    ok(/2\.000 m³ detratti/.test(f), "e la detrazione va detta, non nascosta nel totale");
    // ⛔ e quando non si dichiara, la frase E' il motivo: non «0 m³», non un vuoto
    const senza = terra.descriviBaseOnere(terra.baseOnereEscavazione(riepOnere([], 2025)));
    ok(/non misurato/.test(senza) && !/^Volume scavato/.test(senza),
      `senza rilievi la frase dice perche': «${senza}»`);
  });

  test("⛔ volumeMisuratoDiLotto usa rilievoUsabile, non una sesta copia a mano", () => {
    /* La condizione era riscritta qui a mano, ed era la QUINTA variante: senza
       la guardia su `null` (che `Number.isFinite(+null)` lascia passare, perché
       `+null` fa 0). La prova pretende l'IDENTITÀ del comportamento con la
       funzione, non che «funzioni»: due copie uguali oggi divergono domani. */
    const lotto = { id: "L1", frontiId: ["f1"] };
    const rilievi = [
      { id: "a", fronteId: "f1", stato: "elaborato", volumeM3: 500, provenienza: "scavo" },
      { id: "b", fronteId: "f1", stato: "elaborato", volumeM3: null, provenienza: "scavo" },
      { id: "c", fronteId: "f1", stato: "elaborato", volumeM3: "", provenienza: "scavo" },
      { id: "d", fronteId: "f1", stato: "bozza", volumeM3: 900, provenienza: "scavo" },
    ];
    const v = terra.volumeMisuratoDiLotto(lotto, rilievi);
    eq(v.m3, 500, "conta solo il rilievo che ha davvero un volume");
    eq(v.rilievi, 1, "e ne conta UNO: gli altri tre non hanno misurato niente");
    // l'identità: chi passa il filtro del lotto è esattamente chi passa la funzione
    const attesi = rilievi.filter((r) => terra.rilievoUsabile(r)).length;
    eq(v.rilievi, attesi, "il filtro del lotto e `rilievoUsabile` devono dire la STESSA cosa");
  });
  test("rilievoUsabileConData: chi ordina nel tempo pretende anche una data vera", () => {
    /* senza data non si sa dove sta nella serie: entrerebbe in un confronto
       «fra due rilievi» senza che si possa dire quale viene prima */
    ok(terra.rilievoUsabileConData({ stato: "elaborato", volumeM3: 100, data: "2026-07-12" }), "con data ISO");
    ok(!terra.rilievoUsabileConData({ stato: "elaborato", volumeM3: 100, data: "12/07/2026" }), "non è ISO");
    ok(!terra.rilievoUsabileConData({ stato: "elaborato", volumeM3: 100 }), "senza data");
    ok(!terra.rilievoUsabileConData({ stato: "bozza", volumeM3: 100, data: "2026-07-12" }),
      "e resta la condizione di prima: una bozza non passa neanche con la data");
  });
  test("PROVENIENZE: due sole, e ognuna dice in italiano che cosa cambia", () => {
    eq(terra.PROVENIENZE.map(p => p.chiave), ["scavo", "cumulo"], "scavo e cumulo");
    ok(/consuma il volume concesso/.test(terra.PROVENIENZE[0].nota), "lo scavo consuma");
    ok(/non consuma il volume concesso/.test(terra.PROVENIENZE[1].nota), "la ripresa no");
  });
  test("etichettaProvenienza: quello che non è dichiarato «cumulo» è scavo", () => {
    /* la scelta prudente: un rilievo vecchio senza il campo vale scavo,
       cioè consuma titolo. Dare per «cumulo» quello che non si sa
       farebbe risultare più titolo residuo di quanto ce n'è. */
    eq(terra.etichettaProvenienza("cumulo"), "Ripresa da un cumulo", "cumulo");
    eq(terra.etichettaProvenienza("scavo"), "Scavo dal fronte", "scavo");
    eq(terra.etichettaProvenienza(""), "Scavo dal fronte", "non dichiarata");
    eq(terra.etichettaProvenienza("zzz"), "Scavo dal fronte", "parola sconosciuta");
  });

  test("rilieviScavoFronte: solo elaborati, con volume, con data vera, di QUEL fronte", () => {
    /* un rilievo in bozza o senza volume non è confrontabile, e mescolare
       due fronti sarebbe sommare cose diverse */
    eq(terra.rilieviScavoFronte(RIL, "f1").map(r => r.id), ["r2", "r1", "r3"], "dal più recente");
    eq(terra.rilieviScavoFronte(RIL, "f2").map(r => r.id), ["r8"], "l'altro fronte per conto suo");
    eq(terra.rilieviScavoFronte(RIL, null), [], "il rilievo senza fronte qui è di cumulo, e non entra");
  });
  test("rilievoPrecedente: il primo rilievo non ha un prima", () => {
    /* «un volume senza il rilievo di partenza non dice da dove è stato
       misurato»: meglio null che il rilievo di un altro fronte */
    eq(terra.rilievoPrecedente(RIL, RIL[1]).id, "r1", "prima di r2 c'è r1");
    eq(terra.rilievoPrecedente(RIL, RIL[2]), null, "r3 è il primo");
    eq(terra.rilievoPrecedente(RIL, RIL[6]), null, "una data storta non trova nessun precedente");
    eq(terra.rilievoPrecedente(RIL, null), null, "nessun rilievo");
  });

  test("⛔ anniConVolumi: l'anno in corso c'è SEMPRE, anche a volumi zero", () => {
    /* la denuncia si prepara anche quando l'anno non è finito, e va
       inviata anche se non si è scavato: se l'anno non comparisse
       nell'elenco, non ci sarebbe modo di prepararla */
    eq(terra.anniConVolumi(RIL, OGGI), [2026, 2025], "dal più recente");
    eq(terra.anniConVolumi([], OGGI), [2026], "nessun rilievo: c'è comunque l'anno in corso");
  });
  test("⛔ serieAnnuale: lo scavo consuma il titolo, la ripresa dai cumuli NO", () => {
    /* 300 m³ ripresi da un cumulo restano fuori dal cumulato: sono
       materiale già estratto, e contarli vorrebbe dire dichiarare di aver
       consumato titolo che non è stato consumato */
    const s = terra.serieAnnuale(RIL, AUT, OGGI);
    eq(s.map(a => a.anno), [2025, 2026], "in ordine di tempo, come le denunce");
    contiene(s[0], { anno: 2025, scavo: 500, cumulo: 0, cumulato: 1500, pct: 15, inCorso: false },
      "2025: 500 scavati sopra 1.000 di pregresso");
    contiene(s[1], { anno: 2026, scavo: 2000, cumulo: 300, cumulato: 3500, pct: 35, inCorso: true },
      "2026: 2.000 scavati, e i 300 del cumulo restano fuori dal cumulato");
    eq(s[1].cumulato - s[0].cumulato, s[1].scavo, "la differenza fra i due cumulati è esattamente lo scavo");
  });
  test("serieAnnuale: bozze, rilievi senza volume e date storte non entrano", () => {
    /* r5 è in bozza (999), r6 non ha volume, r7 ha una data illeggibile:
       nessuno dei tre deve finire in un numero che va all'ente */
    const s = terra.serieAnnuale(RIL, AUT, OGGI);
    eq(s[1].scavo, 2000, "1.000 + 800 + 200, e basta");
    eq(s[1].rilievi, 4, "quattro rilievi contati nell'anno");
  });

  test("TIPI_SCADENZA_TERRA: nessuna periodicità cablata, perché è materia regionale", () => {
    /* è la regola vincolante del progetto: le scadenze e i termini cambiano
       da regione a regione e da atto ad atto, e li mette sempre l'utente */
    for (const p of terra.TIPI_SCADENZA_TERRA) {
      ok(p.chiave && p.etichetta, "chiave ed etichetta: " + p.chiave);
      ok(!("giorni" in p) && !("mesi" in p) && !("preavviso" in p),
        "nessuna periodicità dentro la voce: " + p.chiave);
    }
    ok(terra.TIPI_SCADENZA_TERRA.some(p => p.chiave === "autorizzazione"), "il titolo c'è");
    ok(terra.TIPI_SCADENZA_TERRA.some(p => p.chiave === "fideiussione"), "e la fideiussione anche");
  });
  test("presetScadenzaTerra: quello che propone è SEMPRE «da verificare»", () => {
    /* Terra non può indovinare i termini: la proposta esce già marcata */
    contiene(terra.presetScadenzaTerra("fideiussione"), { chiave: "fideiussione", daVerificare: true }, "marcata");
    eq(terra.presetScadenzaTerra("zzz"), null, "un tipo che non esiste non diventa il primo dell'elenco");
  });
  test("etichettaTipoScadenza: nell'elenco si legge solo la parte prima del trattino", () => {
    eq(terra.etichettaTipoScadenza("autorizzazione"), "Autorizzazione / concessione", "corta");
    eq(terra.etichettaTipoScadenza("altro"), "Altro adempimento", "senza trattino resta intera");
    eq(terra.etichettaTipoScadenza("zzz"), "zzz", "una chiave sconosciuta si mostra com'è");
    eq(terra.etichettaTipoScadenza(""), "Altro", "e senza chiave si dice «Altro»");
  });
}

// ── Sentinella: prevista o eseguita, reclami, periodicità ────────────
/* Il registro delle volate contiene DUE nature di riga: una volata
   PREVISTA (progettata da Genesi, non ancora sparata) e una ESEGUITA (un
   evento successo). Confonderle vorrebbe dire mettere un progetto in un
   registro che va all'ente. Le funzioncine qui sotto sono quelle che
   tengono in piedi la distinzione dappertutto — filtri, etichetta,
   colonne del CSV — e finora nessuna era chiamata per nome da una prova. */
{
  console.log("\n— Sentinella: prevista o eseguita, reclami, periodicità —");

  const VOLATE = [
    { data: "2026-07-01", stato: "prevista", ppvPrevista: 3.2 },
    { data: "2026-07-02", stato: "eseguita", ppvMisurata: 4.1 },
    { data: "2026-07-03" },                                  // dati vecchi: nessuno stato
    { data: "2026-07-04", stato: "progetto" },               // scritto a mano
    { data: "2026-07-05", stato: "sparata" },
  ];
  test("⛔ una volata senza stato vale ESEGUITA (è ciò che era, nel brogliaccio)", () => {
    /* regola dura di compatibilità: nessun conteggio esistente cambia e
       nessuna riga d'archivio va convertita. Il contrario — dare per
       «prevista» quello che non lo dichiara — farebbe sparire dal registro
       le volate vere di tutti gli anni passati. */
    ok(!sentinella.volataPrevista(VOLATE[2]), "senza stato: eseguita");
    ok(sentinella.volataPrevista(VOLATE[0]), "prevista");
    ok(sentinella.volataPrevista(VOLATE[3]), "«progetto» scritto a mano vale prevista");
    ok(!sentinella.volataPrevista(VOLATE[4]), "«sparata» vale eseguita");
  });
  test("volatePreviste e volateEseguite dividono l'elenco senza perdere righe", () => {
    /* è la proprietà che conta: una riga sta di qua o di là, mai in
       tutt'e due e mai in nessuna delle due */
    const p = sentinella.volatePreviste(VOLATE), e = sentinella.volateEseguite(VOLATE);
    eq(p.map(v => v.data), ["2026-07-01", "2026-07-04"], "le previste");
    eq(e.map(v => v.data), ["2026-07-02", "2026-07-03", "2026-07-05"], "le eseguite");
    eq(p.length + e.length, VOLATE.length, "nessuna riga persa e nessuna contata due volte");
    eq(sentinella.volatePreviste([]), [], "elenco vuoto");
    eq(sentinella.volateEseguite(null), [], "niente");
  });
  test("⛔ etichettaStatoVolata: la prevista NON prende i colori del semaforo", () => {
    /* verde/giallo/rosso in questa app vogliono dire conforme / al limite /
       superato: una volata prevista non è un giudizio di conformità, è
       un'altra natura di riga, e prende il colore dell'app */
    contiene(sentinella.etichettaStatoVolata(VOLATE[0]), { stato: "prevista", cls: "accent", label: "Prevista" },
      "prevista");
    contiene(sentinella.etichettaStatoVolata(VOLATE[2]), { stato: "eseguita", cls: "", label: "Eseguita" },
      "eseguita: nessuna classe di colore");
    for (const v of VOLATE) ok(!/^(ok|warn|danger)$/.test(sentinella.etichettaStatoVolata(v).cls),
      "mai una classe del semaforo");
  });
  test("CAMPI_PREVISIONE_VUOTI: la previsione si toglie TUTTA INSIEME", () => {
    /* mai il numero senza la sua provenienza: una PPV prevista senza
       sapere da dove viene è un numero orfano dentro un registro */
    const c = sentinella.CAMPI_PREVISIONE_VUOTI;
    eq(Object.keys(c).sort(), ["airblastPrevisto", "ppvPrevFonte", "ppvPrevLimite", "ppvPrevNorma", "ppvPrevista"],
      "cinque campi, sempre gli stessi");
    ok(!sentinella.previsioneDiVolata({ ...VOLATE[0], ...c }), "applicandoli la previsione sparisce davvero");
  });
  test("CSV_VOLATE_INTESTAZIONE: le colonne dell'export sono quelle che l'import rilegge", () => {
    /* due elenchi di colonne in due punti diversi si scollano: qui stanno
       nello stesso file di proposito, e la prova pretende che il giro
       export → import non perda lo stato */
    const cols = sentinella.CSV_VOLATE_INTESTAZIONE.split(";");
    for (const c of ["data", "stato", "ppvMisurata", "ppvPrevista", "codiceVolata"]) ok(cols.includes(c), c);
    eq(cols[0], "data", "la data per prima");
    eq(new Set(cols).size, cols.length, "nessuna colonna ripetuta");
    const csv = sentinella.csvRegistroVolate(VOLATE);
    eq(csv.split("\n")[0], sentinella.CSV_VOLATE_INTESTAZIONE, "l'export scrive esattamente quell'intestazione");
    ok(csv.includes(";prevista;"), "e la riga prevista si dichiara prevista");
  });
  test("PPV_STRUMENTO: la misura letta dal sismografo ha una provenienza sua", () => {
    /* serve a distinguerla da quella scritta a mano: nel report per l'ente
       «l'ha detto lo strumento» e «l'ha scritto qualcuno» non sono uguali */
    eq(sentinella.PPV_STRUMENTO, "strumento", "la chiave");
    eq(sentinella.VOL_ESEGUITA, "eseguita", "e lo stato di una volata sparata");
  });

  test("reclami: cinque tipi, e uno sconosciuto finisce in «Altro»", () => {
    /* qui il ripiego è giusto: un reclamo va comunque registrato, e
       «Altro» non afferma niente di falso sul suo contenuto */
    eq(sentinella.TIPI_RECLAMO.map(t => t.chiave), ["rumore", "polvere", "vibrazione", "acque", "altro"], "i cinque");
    eq(sentinella.etichettaReclamo("POLVERE"), "Polvere", "anche col maiuscolo");
    eq(sentinella.etichettaReclamo("zzz"), "Altro", "sconosciuto");
    eq(sentinella.etichettaReclamo(""), "Altro", "vuoto");
  });
  test("riepilogoReclami: aperto è tutto ciò che non è chiuso", () => {
    /* un reclamo senza stato è aperto: dare per chiuso quello che nessuno
       ha chiuso è la solita risposta tranquilla su un dato che non c'è */
    const r = sentinella.riepilogoReclami([
      { data: "2026-07-01", stato: "chiuso" }, { data: "2026-07-05" }, { data: "boh", stato: "aperto" },
    ]);
    contiene(r, { totale: 3, aperti: 2, ultimo: "2026-07-05" }, "riepilogo");
    contiene(sentinella.riepilogoReclami([]), { totale: 0, aperti: 0, ultimo: null }, "nessun reclamo");
  });

  test("PERIODICITA: scorciatoie per scrivere i giorni, non regole di legge", () => {
    /* frequenze e tolleranze cambiano da autorizzazione a autorizzazione:
       «mensile» qui vale 30 giorni ed è scritto anche nell'interfaccia,
       perché un mese di calendario non ha una durata fissa */
    ok(sentinella.PERIODICITA.every(p => p.chiave && p.etichetta && p.giorni > 0), "ogni voce ha i suoi giorni");
    eq(sentinella.PERIODICITA.find(p => p.chiave === "mensile").giorni, 30, "mensile = 30 giorni");
    eq(sentinella.PERIODICITA.map(p => p.giorni), [...sentinella.PERIODICITA.map(p => p.giorni)].sort((a, b) => a - b),
      "in ordine crescente");
  });
  test("etichettaFrequenza: il nome se coincide, altrimenti i giorni; e se manca lo dice", () => {
    eq(sentinella.etichettaFrequenza(30), "ogni mese", "coincide con una periodicità tipica");
    eq(sentinella.etichettaFrequenza(45), "ogni 45 giorni", "non coincide");
    eq(sentinella.etichettaFrequenza(0), "frequenza non impostata", "non impostata: lo dice invece di dire «ogni 0 giorni»");
    eq(sentinella.etichettaFrequenza(null), "frequenza non impostata", "niente");
  });
  test("trovaRicettore e le classi acustiche: nessun limite dedotto dalla classe", () => {
    /* la classe acustica DESCRIVE la zona che il Comune ha assegnato; il
       limite lo scrive l'autorizzazione e lo imposta l'utente */
    const R = [{ id: "a", nome: "Casa Rossi" }, { id: "b", nome: "Scuola" }];
    eq(sentinella.trovaRicettore(R, "b").nome, "Scuola", "trovato");
    eq(sentinella.trovaRicettore(R, "zzz"), null, "non c'è: null, non il primo");
    eq(sentinella.trovaRicettore(null, "a"), null, "nessun ricettore");
    eq(sentinella.CLASSI_ACUSTICHE.map(c => c.chiave), ["I", "II", "III", "IV", "V", "VI"], "le sei classi del DPCM");
    ok(sentinella.CLASSI_ACUSTICHE.every(c => !("limite" in c) && !("db" in c)),
      "nessun numero di limite dentro la classe");
  });
}

// ── Campo: come si SCRIVE un numero, e il piano di carico ────────────
/* Ultimo gruppo scoperto di Campo. Sono le funzioni che decidono come un
   numero arriva sotto gli occhi di chi lavora — ed è lì che una carica
   non registrata può diventare «0 kg», cioè un fatto, e falso. */
{
  console.log("\n— Campo: come si scrive un numero, e il piano di carico —");

  test("⛔ numeroIt: `null` e stringa vuota NON sono zero", () => {
    /* `+null` fa 0: senza il controllo, una carica non registrata
       comparirebbe come «0 kg». Qui la risposta è la stringa vuota, così
       chi la mostra decide cosa metterci al posto. */
    eq(campo.numeroIt(null), "", "null");
    eq(campo.numeroIt(""), "", "vuoto");
    eq(campo.numeroIt(undefined), "", "niente");
    eq(campo.numeroIt("boh"), "", "non è un numero");
    eq(campo.numeroIt(0), "0", "ma uno zero SCRITTO è uno zero, e si vede");
  });
  test("numeroIt: raggruppa le migliaia sempre allo stesso modo", () => {
    /* `useGrouping: true` è scritto a mano di proposito: al valore di
       default 1286 esce «1.286» su Chromium e «1286» su Node, cioè lo
       stesso numero in due modi a seconda di dove gira */
    eq(campo.numeroIt(1286), "1.286", "mille duecentottantasei");
    eq(campo.numeroIt(1234567), "1.234.567", "e i milioni");
    eq(campo.numeroIt(60), "60", "senza decimali inutili");
    eq(campo.numeroIt(1250.5), "1.250,5", "virgola decimale");
  });
  test("segnoIt: il verso davanti, col segno meno tipografico", () => {
    /* «−» è U+2212, non il trattino: negli scostamenti il verso è metà
       dell'informazione, e un trattino si confonde con una lineetta */
    eq(campo.segnoIt(-15.3), "−15,3", "meno tipografico");
    eq(campo.segnoIt(4.7), "+4,7", "più esplicito");
    eq(campo.segnoIt(0), "+0", "lo zero è «in pari», non negativo");
    eq(campo.segnoIt(null), "", "e il dato che manca resta vuoto anche qui");
  });
  test("numeroItDa: legge un numero di un file e lo riscrive all'italiana", () => {
    /* le colonne del piano che Campo non converte arrivano come testo:
       «13.20» e «13,20» sono lo stesso numero, e quello che numero non è
       torna com'era — è roba di un file, non la si indovina */
    eq(campo.numeroItDa("13.20"), "13,2", "punto decimale");
    eq(campo.numeroItDa("13,20"), "13,2", "virgola decimale");
    eq(campo.numeroItDa("ciao"), "ciao", "non è un numero: resta com'era");
    eq(campo.numeroItDa(""), "", "vuoto");
  });
  test("⚠️ `numeroIt` esiste in DUE app, e risponde diverso in mezzo dei casi", () => {
    /* Misurato: su dodici valori provati, SEI risposte diverse.
       Le differenze sono volute e dichiarate nei commenti dei due moduli:
       · sul dato che manca Campo scrive "" e Sentinella "—", perché in un
         rapporto di monitoraggio il trattino dice «non è stato misurato»;
       · da cento in su Sentinella arrotonda all'unità di serie («1.286,00
         letture» non aggiunge niente), Campo no.
       Non sono quindi la stessa regola scritta due volte, e non vanno in
       `shared/` così come sono. Ma il NUCLEO è lo stesso in tutt'e due —
       «null e "" non sono zero», il raggruppamento fissato a mano — ed è
       la parte che, se un giorno viene corretta in una sola delle due,
       resta indietro nell'altra senza che nessuno lo veda.
       Questa prova esiste per rendere visibile quel confine. */
    ok(campo.numeroIt !== sentinella.numeroIt, "sono due funzioni diverse, non un alias");
    eq([campo.numeroIt(null), sentinella.numeroIt(null)], ["", "—"], "il dato che manca");
    eq([campo.numeroIt(312.5), sentinella.numeroIt(312.5)], ["312,5", "313"], "da cento in su");
    /* il nucleo condiviso: nessuna delle due scrive «0» per un dato assente */
    for (const f of [campo.numeroIt, sentinella.numeroIt])
      ok(!/0/.test(f(null)) && !/0/.test(f("")), "né l'una né l'altra scrive zero su un dato che manca");
  });

  test("squadraBase: «Squadra A — Perforazione» è la squadra «Squadra A»", () => {
    eq(campo.squadraBase("Squadra A — Perforazione"), "Squadra A", "il mestiere resta fuori dalla chiave");
    eq(campo.squadraBase("  Squadra B "), "Squadra B", "spazi tolti");
    eq(campo.squadraBase(null), "", "niente");
  });
  test("RUOLI: lista corta da toccare, perché in cava coi guanti non si scrive", () => {
    ok(campo.RUOLI.length <= 12, "corta: se è lunga nessuno la usa");
    ok(campo.RUOLI.includes("Fochino") && campo.RUOLI.includes("Caposquadra"), "i ruoli di cava ci sono");
    eq(campo.RUOLI[campo.RUOLI.length - 1], "Altro", "«Altro» in fondo");
  });
  test("formattaProduzione: numero all'italiana e unità accanto, mai in maiuscolo", () => {
    /* «m³» e «M³» non sono la stessa cosa */
    eq(campo.formattaProduzione(1250.5, "t"), "1.250,5 t", "tonnellate");
    eq(campo.formattaProduzione(0, null), "0 t", "senza unità vale la prima delle tre");
    eq(campo.formattaProduzione("boh", "m³"), "0 m³", "un numero illeggibile non fa sparire l'unità");
  });

  test("normalizzaPiano: butta le righe senza foro o senza carica, e ordina per foro", () => {
    /* una riga senza numero di foro o senza carica prevista non è una riga
       del piano: tenerla farebbe un consuntivo su fori che non esistono */
    const p = campo.normalizzaPiano([
      { foro: "3", prog: "100", reale: "" },
      { foro: "1", prog: "80", reale: "75" },
      { foro: "0", prog: "50" },
      { foro: "2", prog: "0" },
      { foro: "2", prog: "90", reale: null },
    ]);
    eq(p.map(x => x.foro), [1, 2, 3], "in ordine di foro, e le due righe storte fuori");
    eq(p.map(x => x.prog), [80, 90, 100], "le cariche previste lette come numeri");
  });
  test("⛔ normalizzaPiano: «carica reale non ancora registrata» è null, non zero", () => {
    /* zero chili di esplosivo in un foro è un fatto — e se non è vero,
       falsa lo scarto e quindi la riconciliazione con Genesi */
    const p = campo.normalizzaPiano([
      { foro: "1", prog: "80", reale: "" }, { foro: "2", prog: "80", reale: null },
      { foro: "3", prog: "80", reale: "0" }, { foro: "4", prog: "80", reale: "75" },
    ]);
    eq(p.map(x => x.reale), [null, null, 0, 75], "vuoto e null restano null; uno zero SCRITTO resta zero");
  });
  test("CONSUNTIVO_COLONNE: le colonne del consuntivo dicono le unità nel nome", () => {
    /* «carica_prog_kg» e non «carica_prog»: chi apre il file in un foglio
       di calcolo non ha nessun altro posto dove leggere l'unità */
    eq(campo.CONSUNTIVO_COLONNE[0], "data", "la data per prima");
    ok(campo.CONSUNTIVO_COLONNE.includes("carica_prog_kg"), "prevista in kg");
    ok(campo.CONSUNTIVO_COLONNE.includes("carica_reale_kg"), "reale in kg");
    ok(campo.CONSUNTIVO_COLONNE.includes("scarto_pct") && campo.CONSUNTIVO_COLONNE.includes("scarto_kg"),
      "lo scarto in percentuale E in chili: sono due letture diverse dello stesso fatto");
    eq(new Set(campo.CONSUNTIVO_COLONNE).size, campo.CONSUNTIVO_COLONNE.length, "nessuna colonna ripetuta");
  });
}

// ── Conti: i centesimi, e il valore di una pesata già emessa ─────────
{
  console.log("\n— Conti: i centesimi e la pesata già emessa —");

  test("⛔ round2: i soldi si fermano al centesimo, sempre", () => {
    /* è la funzione da cui passa OGNI importo di Conti: se la somma degli
       acconti non torna col totale al centesimo, una fattura risulta non
       saldata per un millesimo e parte un sollecito a un cliente in regola */
    eq(conti.round2(10.005), 10.01, "il mezzo centesimo sale");
    eq(conti.round2(1 / 3), 0.33, "un terzo di euro");
    eq(conti.round2(0.1 + 0.2), 0.3, "e il rumore binario di 0,1 + 0,2 sparisce");
    eq(conti.round2(-4.567), -4.57, "anche in negativo");
  });
  test("round2: quello che non è un numero vale zero, e qui è giusto così", () => {
    /* è un arrotondatore, non un lettore: chi legge un importo scritto a
       mano passa da numeroDaCampo, che invece DICE quando non capisce */
    eq(conti.round2(null), 0, "null");
    eq(conti.round2("boh"), 0, "non è un numero");
    eq(conti.round2("12,5"), 0, "e nemmeno un numero all'italiana: quello lo legge un'altra funzione");
  });
  test("valorePesata: legge i dati FOTOGRAFATI sul documento, non il listino di oggi", () => {
    /* un DDT già emesso vale quello che è stato consegnato e fatturato:
       se domani il listino cambia, il documento non deve cambiare con lui */
    eq(conti.valorePesata({ quantita: 18.3, prezzoUnitario: 12.5 }), 228.75, "quantità × prezzo del documento");
    eq(conti.valorePesata({ quantita: 10, prezzoUnitario: 0 }), 0, "senza prezzo scritto: zero euro");
    eq(conti.valorePesata({ prezzoUnitario: 12.5 }), 0, "senza quantità non c'è nessun valore");
    eq(conti.valorePesata(null), 0, "nessuna pesata");
    /* ⛔ il caso che conta, e che la prima stesura non aveva: una pesata
       venduta a METRO CUBO ma SENZA densità ha il netto in tonnellate e la
       quantità a null. Ripiegare sul netto la valuterebbe a 18,3 × 20 €/m³,
       cioè moltiplicando tonnellate per un prezzo al metro cubo. Zero è la
       risposta giusta, e la pagina lì scrive «manca la densità». */
    eq(conti.valorePesata({ netto: 18.3, quantita: null, unitaVendita: "m3", prezzoUnitario: 20 }), 0,
      "il netto NON è un ripiego della quantità venduta");
  });
}

// ── Le regole che servono a due app: UNA sola, e le app la ri-esportano ──
/* ⛔ Queste prove pretendono l'IDENTITÀ, non il comportamento. La differenza
   non è formale: due copie che si comportano uguale OGGI divergono domani
   senza che nessuno lo veda, ed è esattamente quello che era successo —
   `messaggioNumero` scritta due volte con tre messaggi diversi su dieci, e
   `dataPiuGiorni` scritta identica in due app ma già staccata sul caso
   d'errore (`null` di qua, `""` di là).
   Misura e racconto: docs/NUMERI_MESSAGGIO_DOPPIO_202608.md e
   docs/LA_STESSA_REGOLA_SCRITTA_DUE_VOLTE.md */
{
  console.log("\n— Una regola, un posto solo (identità, non comportamento) —");

  test("⛔ messaggioNumero: una sola implementazione, e Flotta la RI-ESPORTA", () => {
    ok(flotta.messaggioNumero === shell.messaggioNumero, "è lo stesso oggetto, non una copia");
  });
  test("⛔ le due frasi degli avvisi vengono tutte dallo stesso posto", () => {
    for (const app of [conti, flotta, sentinella, terra])
      ok(app.AVVISO_DECIMALE === shell.AVVISO_DECIMALE, "AVVISO_DECIMALE");
    ok(flotta.AVVISO_MIGLIAIA === shell.AVVISO_MIGLIAIA, "AVVISO_MIGLIAIA");
  });
  test("la frase sull'ambiguo dice anche COME si scrive", () => {
    /* era la versione di Flotta, ed era la migliore delle due: quella dello
       shell si fermava a «senza il punto delle migliaia» e lasciava indovinare
       la forma giusta, proprio dove l'app ha appena detto di non voler indovinare */
    ok(/«1250».*«1\.250»/.test(shell.AVVISO_MIGLIAIA), "con l'esempio dentro");
    const r = shell.numeroScritto("1.250", { decimali: 2 });
    ok(/1250.*1,25/.test(shell.messaggioNumero(r, "il numero")), "e la frase scioglie l'ambiguità");
  });
  test("⛔ uno ZERO scritto si vede nel messaggio (non «hai scritto «»»)", () => {
    /* era il difetto della copia di Flotta: `(r.grezzo || "")`, e `0 || ""`
       è `""` — l'utente ha scritto zero e l'app gli rispondeva che non aveva
       scritto niente */
    ok(/«0»/.test(flotta.messaggioNumero({ motivo: "non-positivo", grezzo: 0 }, "le ore")),
      "lo zero compare nella frase");
  });

  test("⛔ dataPiuGiorni: una sola, e senza un numero non propone nessuna data", () => {
    ok(scudo.dataPiuGiorni === shell.dataPiuGiorni, "Scudo la ri-esporta");
    ok(sentinella.dataPiuGiorni === shell.dataPiuGiorni, "e Sentinella pure");
    /* irrigidita nel passaggio: `Number(null)` è 0, quindi «nessun numero di
       giorni» diventava «scade oggi» — una scadenza che qualcuno firma */
    eq(shell.dataPiuGiorni(null, new Date("2026-07-15T10:00:00")), null, "null non è zero giorni");
    eq(shell.dataPiuGiorni("", new Date("2026-07-15T10:00:00")), null, "e nemmeno il vuoto");
    eq(shell.dataPiuGiorni("boh", new Date("2026-07-15T10:00:00")), null, "né una parola");
    eq(shell.dataPiuGiorni(30, new Date("2026-07-15T10:00:00")), "2026-08-14", "e trenta giorni sono trenta giorni");
  });
  test("⛔ perCampo: una sola, e Flotta la RI-ESPORTA", () => {
  ok(flotta.perCampo === shell.perCampo, "è lo stesso oggetto, non una copia identica");
  /* Che cosa regge quella riga, perché l'identità da sola non lo dice: dentro
     un CAMPO il punto delle migliaia non ci va. Se ci finisse, rientrerebbe dal
     lettore come ambiguo e l'app rifiuterebbe un valore che ha proposto lei. */
  eq(shell.perCampo(1250.5), "1250,5", "virgola decimale, e nessun punto di migliaia");
  eq(shell.perCampo(6375), "6375", "quattro cifre: nessun raggruppamento, in Node come in Chromium");
  eq(shell.perCampo(12.345, 1), "12,3", "i decimali si tagliano a quelli chiesti");
  eq(shell.perCampo(null), "", "un numero che manca lascia il campo vuoto, non «0»");
  eq(shell.perCampo(""), "", "e nemmeno una stringa vuota diventa zero");
});
test("giorni: alias di giorniTra in tutt'e due le app che lo usavano", () => {
    ok(conti.giorni === shell.giorniTra, "Conti");
    ok(sentinella.giorni === shell.giorniTra, "Sentinella");
  });

  test("⛔ le migliaia si raggruppano allo stesso modo in Node e nel browser", () => {
    /* misurato: sui numeri di quattro cifre Chromium scrive «6.375» e Node
       «6375». I moduli dati li leggono tutt'e due, quindi il raggruppamento
       va SCRITTO. docs/MIGLIAIA_NODE_CONTRO_CHROMIUM.md */
    eq(campo.numeroIt(6375, 0), "6.375", "Campo");
    eq(sentinella.numeroIt(6375, 0), "6.375", "Sentinella");
    /* Terra accorcia le migliaia («6k») e i milioni li scrive raggruppati:
       12.500.000 m³ deve leggersi «12,5M», non «12.5M» col punto inglese */
    eq(terra.fmtM3(6375), "6k", "Terra accorcia le migliaia");
    eq(terra.fmtM3(12500000), "12,5M", "e i milioni con la virgola");
  });
}

/* ══ CAMPO: LA DISPONIBILITÀ DI TURNO ══
   Le sei funzioni sono arrivate col cantiere in parallelo, che per scelta non
   tocca questo file (è condiviso: due cantieri che ci scrivono insieme si
   scontrano). Le prove le scrivo qui, e guardano i punti in cui un difetto
   NON si vedrebbe: i modi in cui il numero non si può fare. */
test("oreMinuti: si legge come lo direbbe una persona", () => {
  eq(campo.oreMinuti(0), "0 min", "zero minuti sono zero minuti, non «0 h»");
  eq(campo.oreMinuti(59), "59 min", "sotto l'ora non si scrivono le ore");
  eq(campo.oreMinuti(60), "1 h", "e un'ora tonda non si scrive «1 h 0 min»");
  eq(campo.oreMinuti(90), "1 h 30 min", "un'ora e mezza");
  eq(campo.oreMinuti(480), "8 h", "il turno pieno");
  eq(campo.oreMinuti(-5), "", "un tempo negativo non si scrive: non esiste");
  eq(campo.oreMinuti(null), "", "e nemmeno un tempo che manca");
  eq(campo.oreMinuti("abc"), "", "quello che non è un numero non è un tempo");
});
test("durataTurnoDi: se il turno viene ridichiarato vince l'ULTIMA", () => {
  const d = [{ data: "2026-07-20", turno: "Mattino", minuti: 480 },
             { data: "2026-07-20", turno: "Pomeriggio", minuti: 300 },
             { data: "2026-07-20", turno: "Mattino", minuti: 420 }];
  eq(campo.durataTurnoDi(d, "2026-07-20", "Mattino").minuti, 420,
    "chi corregge la durata si aspetta che valga la correzione, non la prima");
  eq(campo.durataTurnoDi(d, "2026-07-20", "Pomeriggio").minuti, 300, "gli altri turni non si toccano");
  eq(campo.durataTurnoDi(d, "2026-07-21", "Mattino"), null, "un giorno senza dichiarazione è null, non zero");
  eq(campo.durataTurnoDi(null, "2026-07-20", "Mattino"), null, "e un elenco che manca non fa cadere niente");
});
test("ultimaDurataTurno: la più recente per giorno E per ordine del turno", () => {
  const d = [{ data: "2026-07-19", turno: "Notte", minuti: 480 },
             { data: "2026-07-20", turno: "Mattino", minuti: 420 },
             { data: "2026-07-20", turno: "Notte", minuti: 400 },
             { data: "2026-07-20", turno: "Pomeriggio", minuti: 300 }];
  const u = campo.ultimaDurataTurno(d);
  eq(u.data + "|" + u.turno, "2026-07-20|Notte",
    "stessa data: conta l'ordine dei turni, non quello in cui sono stati scritti");
  eq(campo.ultimaDurataTurno([{ data: "2026-07-20", turno: "Mattino", minuti: 0 }]), null,
    "una durata a zero non è una durata dichiarata");
  eq(campo.ultimaDurataTurno([]), null, "e senza niente non si propone niente");
});
test("⛔ disponibilità: i tre modi in cui il numero NON si fa", () => {
  const D = [{ data: "2026-07-20", turno: "Mattino", minuti: 480 }];
  const att = (x) => [{ data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Guasto", ...x }];
  const senzaDurata = campo.disponibilitaTurno(att({ fermoMin: 30 }), [], "2026-07-20", "Mattino");
  eq(senzaDurata.pct, null, "senza la durata dichiarata non c'è denominatore");
  ok(senzaDurata.mancano.includes("durata"), "e si dice che manca la durata");
  const senzaAttivita = campo.disponibilitaTurno([], D, "2026-07-20", "Mattino");
  eq(senzaAttivita.pct, null, "un turno senza nessuna attività non è un turno perfetto");
  ok(senzaAttivita.mancano.includes("attività"), "e si dice così");
  /* Il caso insidioso: dei fermi ci sono, ma nessuno ha i minuti. La somma
     farebbe 0 minuti persi e quindi il 100% — il voto più alto proprio al
     turno che ha registrato guasti e non li ha misurati. */
  const fermiMuti = campo.disponibilitaTurno(att({ fermoMin: 0 }), D, "2026-07-20", "Mattino");
  eq(fermiMuti.pct, null, "fermi senza minuti non fanno «100%»");
  ok(fermiMuti.mancano.includes("minuti"), "e il motivo lo nomina");
  /* ⚠️ La prima stesura cercava «fermo è senza minuti» e il testo vero dice
     «L'unico fermo registrato è senza minuti»: era la prova a indovinare la
     frase, non il codice a sbagliarla. */
  ok(/senza minuti/.test(fermiMuti.motivo), "a parole: " + fermiMuti.motivo.slice(0, 50));
});
test("⛔ disponibilità: una misura PARZIALE non prende mai il verde", () => {
  /* Con alcuni fermi misurati e altri no la percentuale è un MASSIMO: quella
     vera può stare sotto la soglia. Un colore tranquillo direbbe «è andata
     bene» su un turno che non sappiamo com'è andato. */
  const D = [{ data: "2026-07-20", turno: "Mattino", minuti: 480 }];
  const att = [
    { data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Guasto", fermoMin: 20 },
    { data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Attesa mezzo", fermoMin: 0 },
    { data: "2026-07-20", turno: "Mattino", stato: "fatta" },
  ];
  const r = campo.disponibilitaTurno(att, D, "2026-07-20", "Mattino");
  eq(r.parziale, true, "è parziale: un fermo su due è senza minuti");
  eq(r.pct, 96, "il numero c'è (480 − 20 su 480), ma è un massimo");
  ok(r.pct >= campo.DISPONIBILITA_OK, "e senza la regola sarebbe sopra la soglia del verde");
  eq(r.stato, "warn", "invece non è «ok»: una misura incompleta non prende il verde");
  eq(r.fermiSenzaMinuti, 1, "e si dice quanti fermi non sono stati misurati");
});
test("⛔ disponibilità: i fermi che superano il turno non danno una percentuale negativa", () => {
  const D = [{ data: "2026-07-20", turno: "Mattino", minuti: 120 }];
  const att = [{ data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Guasto", fermoMin: 200 }];
  const r = campo.disponibilitaTurno(att, D, "2026-07-20", "Mattino");
  eq(r.stato, "oltre", "succede davvero, con due fermi sovrapposti contati due volte");
  eq(r.pct, null, "e una percentuale negativa sarebbe una bugia con l'aria di un dato");
  ok(r.motivo.length > 20, "si spiega invece: " + r.motivo.slice(0, 50));
});
test("disponibilità: quando i numeri ci sono tutti, il conto è quello", () => {
  const D = [{ data: "2026-07-20", turno: "Mattino", minuti: 480 }];
  const att = [
    { data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Attesa mezzo", fermoMin: 60 },
    { data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Guasto", fermoMin: 30 },
    { data: "2026-07-21", turno: "Mattino", stato: "anomalia", causale: "Guasto", fermoMin: 999 },
  ];
  const r = campo.disponibilitaTurno(att, D, "2026-07-20", "Mattino");
  eq(r.parziale, false, "tutti i fermi hanno i minuti");
  eq(r.fermiMin, 90, "il giorno dopo non entra nel conto di oggi");
  eq(r.lavoratiMin, 390, "480 − 90");
  eq(r.pct, 81, "cioè l'81%");
  eq(r.stato, "warn", "sotto 85 ma sopra 70");
  eq(r.peggiore.causale, "Attesa mezzo", "la causale su cui si è perso più tempo");
  eq(r.peggiore.minuti, 60, "e quanto");
  ok(campo.DISPONIBILITA_OK > campo.DISPONIBILITA_WARN, "le due soglie sono in ordine");
});

test("⛔ Flotta: senza le ore, il costo orario NON è zero", () => {
  /* Il numero con cui un titolare decide se tenere una macchina. Candidato
     uscito dalla ricerca continua e rimisurato: gli ingredienti c'erano già
     tutti — `costoOfficinaPerMezzo` e `consumoPerMezzo`, che sa pure le ore —
     mancava la somma. E il caso che conta è quello in cui non si può
     rispondere: nella dimostrazione il Dumper D3 ha 5.090 € di officina e
     nessun rifornimento col contatore. Uno «0 €/h» lì lo farebbe sembrare la
     macchina che costa meno. */
  const r = flotta.costoOrarioMezzo(flotta.DEMO.interventi, flotta.DEMO.rifornimenti);
  ok(r.length >= 3, "la dimostrazione ha abbastanza mezzi per misurare");
  const senzaOre = r.filter(x => x.ore === null);
  ok(senzaOre.length > 0, "e ha almeno un mezzo di cui non si sanno le ore");
  for (const x of senzaOre) {
    eq(x.euroOra, null, x.mezzo + ": senza ore l'euro/ora non si calcola");
    ok(x.perche.length > 10, x.mezzo + ": e dice che cosa manca");
    ok(x.totale > 0 || x.officina === 0, x.mezzo + ": il totale speso resta comunque leggibile");
  }
  const conOre = r.filter(x => x.ore !== null);
  ok(conOre.length > 0, "e almeno uno di cui si sanno");
  for (const x of conOre) {
    eq(x.perche, "", x.mezzo + ": se si calcola non c'è niente da spiegare");
    /* ⚠️ ASSERZIONE CORRETTA IL 05/08, e nella direzione più giusta non più
       permissiva: prima diceva `(officina + carburante) / ore` e quindi
       blindava il difetto — l'officina DA SEMPRE divisa le ore di una finestra
       corta. Adesso il numeratore è quello della finestra. */
    eq(x.euroOra, Math.round(100 * x.spesaInFinestra / x.ore) / 100,
       x.mezzo + ": la spesa DELLA FINESTRA diviso le ore della stessa finestra");
    /* ⚠️ SECONDA CORREZIONE, la sera del 05/08: qui c'era `x.carburante`, cioè
       TUTTO il gasolio del mezzo — primo pieno compreso, che ha alimentato ore
       precedenti alla finestra. Stessa famiglia del difetto dell'officina, e
       più grossa (+93,7% sulla Pala P1). Il numeratore del gasolio è
       `carburanteInFinestra`, che `consumoPerMezzo` calcola già per il suo
       `euroOra`: si legge, non si rifà. */
    eq(x.spesaInFinestra, Math.round(100 * (x.officinaInFinestra + x.carburanteInFinestra)) / 100,
       x.mezzo + ": e la spesa della finestra è l'officina collocata dentro più il gasolio della finestra");
    ok(x.euroOra >= x.euroOraOfficina, x.mezzo + ": il totale non è meno della sola officina");
    ok(x.totale >= x.spesaInFinestra,
       x.mezzo + ": il totale speso resta quello vero, da sempre — non scende perché il rapporto si è stretto");
    /* ⛔ L'IDENTITÀ CHE PRIMA NON TORNAVA, ed è la prova che i due conti del
       gasolio sono tornati uno solo: officina all'ora + carburante all'ora
       DEVE fare il €/h. Fino a stamattina `euroOraCarburante` veniva da
       `consumoPerMezzo` (primo pieno scartato) e `euroOra` da un conto suo
       (primo pieno dentro): su E1 26,11 contro 38,96, cioè la stessa riga che
       si smentiva da sola. Tolleranza di 2 centesimi, che è il massimo che tre
       arrotondamenti al centesimo possono produrre. */
    const somma = (x.euroOraOfficina || 0) + (x.euroOraCarburante || 0);
    ok(Math.abs(x.euroOra - somma) <= 0.02,
       x.mezzo + ": €/h " + x.euroOra + " = officina " + x.euroOraOfficina
       + " + carburante " + x.euroOraCarburante + " (somma " + Math.round(100 * somma) / 100 + ")");
  }
  /* ⚠️ le ore NON sono ricalcolate qui: vengono da `consumoPerMezzo`, e devono
     essere le STESSE. Due conti delle stesse ore un giorno divergono. */
  const car = flotta.consumoPerMezzo(flotta.DEMO.rifornimenti);
  for (const x of conOre) {
    const c = car.mezzi.find(m => m.mezzo === x.mezzo);
    eq(x.ore, c.oreCoperte, x.mezzo + ": le ore sono quelle di consumoPerMezzo, non una seconda copia");
  }
  /* un intervento senza costo rende il totale un MINIMO, e lo dichiara */
  const conVuoto = flotta.costoOrarioMezzo(
    [{ mezzo: "Pala P1", costo: 500 }, { mezzo: "Pala P1", costo: 0 }],
    flotta.DEMO.rifornimenti);
  const pala = conVuoto.find(x => x.mezzo === "Pala P1");
  eq(pala.parziale, true, "un intervento senza costo rende il totale parziale");
  eq(pala.interventiSenzaCosto, 1, "e si sa quanti sono");
});

/* ══ IL €/h SI CALCOLA SU UNA FINESTRA SOLA, E DICHIARATA (05/08) ═══════
   Il difetto che queste prove chiudono, misurato sulla dimostrazione prima di
   toccare una riga: numeratore e denominatore coprivano DUE PERIODI DIVERSI.
   Sopra tutta l'officina del mezzo, da sempre; sotto le ore, che si sanno solo
   fra il primo e l'ultimo rifornimento col contatore.

     mezzo            €/h prima   ore   finestra                fuori finestra
     Dumper D1          63,03      61   12/07 → 30/07           2.100 €  → 28,61  (+120%)
     Pala P1            51,21      33   16/07 → 28/07             760 €  → 28,18  (+82%)
     Escavatore E1      46,46      56   14/07 → 29/07             420 €  → 38,96  (+19%)

   Tre mezzi su sei, e su uno il numero era più del doppio della verità. Il
   verso dell'errore è sempre lo stesso: GONFIA — e gonfia il numero con cui un
   titolare decide se rottamare una macchina.
   Le prove sono scritte attorno alle tre cose che non devono tornare indietro:
   la finestra c'è ed è dichiarata; quello che ci sta fuori si CONTA invece di
   sparire; e il totale speso resta quello vero, da sempre. */
{
  const F = flotta.DEMO;
  // due letture del contatore a un mese di distanza: 100 ore, finestra 01→31/07
  const RIF = [{ data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
               { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }];
  const uno = (interventi, rif = RIF) =>
    flotta.costoOrarioMezzo(interventi, rif).find((r) => r.mezzo === "Pala X");

  test("⛔ Flotta · €/h: la finestra è dichiarata, e l'officina fuori NON entra nel rapporto", () => {
    const r = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 },
                   { mezzo: "Pala X", data: "2026-06-01", costo: 900 }]);
    eq([r.da, r.a], ["2026-07-01", "2026-07-31"], "la finestra è quella delle letture del contatore");
    eq(r.ore, 100, "e le ore sono quelle di quella finestra");
    eq(r.officinaInFinestra, 300, "dell'officina entra solo l'intervento che ci cade dentro");
    eq(r.fuori, { interventi: 1, costo: 900 }, "e quello di giugno si conta a parte, non sparisce");
    eq(r.carburanteInFinestra, 150,
       "e del gasolio entra solo quello messo DOPO la prima lettura: il primo pieno ha alimentato ore che la finestra non conta");
    eq(r.carburante, 300, "mentre il gasolio comprato su questa macchina è tutto, e resta leggibile");
    eq(r.euroOra, 4.5, "(300 di officina + 150 di gasolio) / 100 ore");
    /* ⚠️ LE DUE RIGHE CHE DISCRIMINANO, una per metà della frazione. Col
       difetto dell'officina rimesso dentro verrebbe 10,50; con quello del
       gasolio 6,00; con tutti e due 15,00 — tre volte e mezzo il vero. Senza
       queste asserzioni la prova sopra passerebbe anche con un numeratore
       diverso che per caso desse lo stesso arrotondamento. */
    eq(Math.round(100 * (r.officina + r.carburante) / r.ore) / 100, 15,
       "il conto di ieri l'altro — tutta l'officina e tutto il gasolio diviso le ore della finestra — dava 15");
    eq(Math.round(100 * (r.officinaInFinestra + r.carburante) / r.ore) / 100, 6,
       "quello di ieri — officina sistemata, gasolio ancora tutto — dava 6");
  });

  test("⛔ Flotta · €/h: il TOTALE SPESO resta quello vero, da sempre", () => {
    /* «Quanto ho speso su questa macchina» e «quanto mi costa un'ora» sono due
       domande diverse. Aggiustare la seconda non deve far scendere la prima, o
       chi guarda la spesa vede sparire dei soldi che ha pagato davvero. */
    const r = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 },
                   { mezzo: "Pala X", data: "2026-06-01", costo: 900 }]);
    eq(r.officina, 1200, "l'officina del mezzo è tutta, dal primo intervento registrato");
    eq(r.carburante, 300, "il gasolio comprato è tutto quello messo nel serbatoio, primo pieno compreso");
    eq(r.totale, 1500, "e il totale speso è officina + carburante, senza nessuna finestra");
    eq(r.spesaInFinestra, 450, "mentre il numeratore del rapporto è un'altra cosa, e ha un nome suo");
    eq(r.officina, r.officinaInFinestra + r.fuori.costo + r.senzaData.costo,
       "e i tre pezzi tornano: dentro + fuori + non collocabile = tutta l'officina, nessun euro perso per strada");
    ok(r.carburante > r.carburanteInFinestra,
       "e il gasolio di tutta la vita è più di quello della finestra: " + r.carburante + " contro " + r.carburanteInFinestra
       + " — sono due domande diverse, e nessuna delle due cancella l'altra");
  });

  test("⛔ Flotta · €/h: un intervento SENZA DATA non è «dentro per comodità»", () => {
    /* Non si sa se sia dentro o fuori la finestra: metterlo dentro gonfierebbe
       il €/h, lasciarlo cadere lo sgonfierebbe. Non entra nel rapporto E non
       si finge che non esista: si dichiara, e finché c'è il €/h è un MINIMO. */
    const r = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 },
                   { mezzo: "Pala X", costo: 900 }]);
    eq(r.senzaData, { interventi: 1, costo: 900 }, "l'intervento senza data si conta a parte");
    eq(r.fuori, { interventi: 0, costo: 0 }, "e NON viene messo fuori: fuori vuol dire «so che è fuori»");
    eq(r.officinaInFinestra, 300, "nel rapporto entra solo quello che si sa collocare");
    eq(r.euroOra, 4.5, "quindi il €/h non si muove per colpa sua");
    eq(r.parziale, true, "ma il €/h è dichiarato parziale: c'è una spesa che non ha potuto contare");
    ok(/senza data/.test(r.percheParziale), "e la ragione è scritta: " + r.percheParziale);
    ok(/minimo/.test(r.percheParziale), "col verso giusto — è un minimo, non un numero definitivo");
    /* ⚠️ UNA BANDIERA SOLA PER LE DUE RAGIONI, non due che dicono la stessa
       cosa: un intervento senza costo e uno senza data fanno tutt'e due del
       €/h un minimo, e la seconda bandiera sarebbe solo una parola in più. */
    const due = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 },
                     { mezzo: "Pala X", costo: 900 }, { mezzo: "Pala X", data: "2026-07-20", costo: 0 }]);
    eq(due.parziale, true, "con tutt'e due le ragioni la bandiera resta una");
    eq(due.interventiSenzaCosto, 1, "e i due conti restano distinti");
    eq(due.senzaData.interventi, 1, "uno per ragione");
    ok(/senza costo e .*senza data/.test(due.percheParziale), "la frase le dice tutt'e due: " + due.percheParziale);
    eq(uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 }]).percheParziale, "",
       "e dove non c'è niente da dichiarare la frase è vuota, non «nessuna ragione»");
  });

  test("⛔ Flotta · €/h: una data che NON ESISTE non colloca niente", () => {
    /* «2026-02-30» passa qualunque controllo di forma, e `Date.parse` non la
       rifiuta: la fa SCORRERE al 2 marzo. Collocata così, una spesa finirebbe
       dentro o fuori la finestra per un giorno che non c'è mai stato. */
    const r = uno([{ mezzo: "Pala X", data: "2026-02-30", costo: 900 }]);
    eq(r.senzaData, { interventi: 1, costo: 900 }, "una data impossibile vale come nessuna data");
    eq(r.officinaInFinestra, 0, "e non entra nel rapporto");
    eq(r.parziale, true, "che resta dichiarato parziale");
  });

  test("Flotta · €/h: gli estremi della finestra sono compresi", () => {
    /* Il giorno del primo e dell'ultimo rifornimento sono giorni in cui la
       macchina ha lavorato dentro le ore contate: escluderli toglierebbe una
       spesa vera dal numeratore giusto. */
    const r = uno([{ mezzo: "Pala X", data: "2026-07-01", costo: 100 },
                   { mezzo: "Pala X", data: "2026-07-31", costo: 100 }]);
    eq(r.officinaInFinestra, 200, "il primo e l'ultimo giorno stanno dentro");
    eq(r.fuori.interventi, 0, "e non finisce niente fuori");
    const bordi = uno([{ mezzo: "Pala X", data: "2026-06-30", costo: 100 },
                       { mezzo: "Pala X", data: "2026-08-01", costo: 100 }]);
    eq(bordi.officinaInFinestra, 0, "il giorno prima e il giorno dopo invece no");
    eq(bordi.fuori, { interventi: 2, costo: 200 }, "e si contano fuori");
  });

  test("⛔ Flotta · €/h: le ore ci sono ma le letture non hanno data → non si risponde", () => {
    /* Senza le date non si sa che PERIODO coprano quelle ore, quindi non si sa
       quale spesa appartenga al rapporto. È lo stesso principio del Dumper D3
       («senza ore non si risponde 0 €/h») applicato all'altra metà: un numero
       qui sarebbe un rapporto fra due periodi che nessuno conosce. */
    const r = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 }],
      [{ mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
       { mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }]);
    eq(r.euroOra, null, "niente €/h");
    eq([r.da, r.a], [null, null], "e nessuna finestra inventata");
    eq(r.ore, null, "le ore ci sarebbero, ma da sole non bastano a fare un rapporto");
    ok(/non portano la data/.test(r.perche), "e si dice quale delle due cose manca: " + r.perche);
    eq(r.totale, 600, "la spesa registrata invece resta leggibile, come per il Dumper D3");
  });

  test("⛔ Flotta · €/h: il PRIMO PIENO non entra nel rapporto — ha alimentato ore precedenti", () => {
    /* Il metodo pieno-a-pieno: fra due letture del contatore, il gasolio
       consumato è quello messo DOPO la prima. Il primo pieno il serbatoio lo
       riempie all'inizio — quelle ore la macchina le ha già fatte, e non sono
       nelle ore contate. `consumoPerMezzo` lo scartava da sempre per il suo
       `litriOra`; `costoOrarioMezzo` se lo riprendeva dentro, perché sommava
       `euro` (tutto il gasolio del mezzo). Due conti della stessa cosa che
       divergevano — la regola che CLAUDE.md chiama la più costosa. */
    const rif = [{ data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 400 },
                 { data: "2026-07-16", mezzo: "Pala X", litri: 100, ore: 1050, euro: 100 },
                 { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 100 }];
    const r = uno([], rif);
    eq(r.carburante, 600, "il gasolio comprato è tutto: 400 + 100 + 100");
    eq(r.carburanteInFinestra, 200, "quello della finestra è solo il dopo-il-primo: 100 + 100");
    eq(r.ore, 100, "le ore sono quelle fra la prima e l'ultima lettura");
    eq(r.euroOra, 2, "quindi 200 / 100 ore, non 600 / 100");
    /* ⚠️ IL PRIMO PIENO È GRANDE APPOSTA (400 su 600). Con tre pieni uguali il
       conto giusto e quello sbagliato darebbero 200 contro 300, cioè la prova
       distinguerebbe lo stesso ma sarebbe fragile: sbilanciandolo, il difetto
       triplica il numero invece di aumentarlo di metà. */
    eq(Math.round(100 * (r.officinaInFinestra + r.carburante) / r.ore) / 100, 6,
       "col primo pieno dentro verrebbe 6: tre volte tanto");
    const c = flotta.consumoPerMezzo(rif).mezzi[0];
    eq(r.carburanteInFinestra, c.euroInFinestra, "e il numero è LO STESSO di consumoPerMezzo, non una copia");
    eq(c.euroOra, 2, "che è anche il suo euro/ora del gasolio: le due schermate non si smentiscono più");
    eq(c.litriInFinestra, 200, "e i litri della finestra seguono la stessa regola degli euro");
    eq(c.pieniInFinestra, 2, "due pieni nella finestra, il primo escluso");
  });

  test("⛔ Flotta · €/h: un pieno registrato SENZA la spesa fa del €/h un minimo", () => {
    /* L'euro del rifornimento è FACOLTATIVO — `validaRifornimento` lo lascia
       vuoto senza protestare, e ci sono buone ragioni (la fattura del gasolio
       arriva dopo). Ma allora quel gasolio c'è e i suoi euro no: il numeratore
       scende e il €/h esce più BASSO del vero. È l'assenza di un dato che si
       traveste da dato favorevole — «questa macchina costa poco» — nel punto in
       cui qualcuno decide se tenerla. Non si inventa un prezzo: si dichiara. */
    const r = uno([], [{ data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
                       { data: "2026-07-16", mezzo: "Pala X", litri: 100, ore: 1050 },
                       { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }]);
    eq(r.carburanteInFinestra, 150, "si conta il gasolio di cui si sa la spesa");
    eq(r.euroOra, 1.5, "e il €/h che ne esce è più basso del vero");
    eq(r.rifornimentiSenzaEuro, 1, "ma il pieno senza spesa è contato");
    eq(r.parziale, true, "e la bandiera dice che il numero è un minimo");
    ok(/rifornimento senza la spesa/.test(r.percheParziale), "con la ragione scritta: " + r.percheParziale);
    /* ⛔ E LA BANDIERA RESTA UNA SOLA per tutte e tre le ragioni: dicono la
       stessa cosa («questo numero è un minimo»), e una seconda bandiera
       accanto sarebbe solo una parola in più da leggere. */
    const tre = uno([{ mezzo: "Pala X", data: "2026-07-15", costo: 300 }, { mezzo: "Pala X", costo: 900 },
                     { mezzo: "Pala X", data: "2026-07-20", costo: 0 }],
      [{ data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
       { data: "2026-07-16", mezzo: "Pala X", litri: 100, ore: 1050 },
       { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }]);
    eq([tre.interventiSenzaCosto, tre.senzaData.interventi, tre.rifornimentiSenzaEuro], [1, 1, 1],
       "i tre conti restano distinti, uno per ragione");
    eq(tre.parziale, true, "la bandiera è una");
    ok(/senza costo e .*senza data e .*senza la spesa/.test(tre.percheParziale),
       "e la frase le dice tutte e tre: " + tre.percheParziale);
    // e dove non manca niente non si dichiara niente
    eq(uno([], RIF).parziale, false, "un mezzo con tutto a posto non è parziale");
    eq(uno([], RIF).rifornimentiSenzaEuro, 0, "e non ha pieni senza spesa");
  });

  test("⛔ Flotta · €/h: la finestra la fanno le letture COL CONTATORE, non tutti i rifornimenti", () => {
    /* ⚠️ QUESTA PROVA È NATA DA UNA CONTROPROVA CHE NON DISTINGUEVA, ed è la
       quinta delle cause: il caso difeso non stava nei dati. Rimettendo il
       difetto (la finestra presa da TUTTI i pieni invece che da quelli col
       contatore) la suite restava verde, perché nella dimostrazione e in tutte
       le prove scritte fin lì ogni rifornimento aveva la sua lettura.
       Il difetto vero che il caso nasconde: un pieno di gennaio senza
       contatore allargherebbe la finestra a sei mesi che NON stanno nelle 100
       ore contate, e ci farebbe rientrare l'officina di gennaio. Cioè
       esattamente il difetto che tutto questo lavoro chiude, rientrato dalla
       finestra. Il denominatore lo fanno le letture del contatore: la finestra
       deve venire dalle STESSE. */
    const r = uno([{ mezzo: "Pala X", data: "2026-01-20", costo: 900 }],
      [{ data: "2026-01-05", mezzo: "Pala X", litri: 100, euro: 150 },      // niente contatore
       { data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
       { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }]);
    eq([r.da, r.a], ["2026-07-01", "2026-07-31"],
       "il pieno di gennaio non allarga la finestra: non porta nessuna ora con sé");
    eq(r.ore, 100, "le ore restano quelle fra le due letture");
    eq(r.officinaInFinestra, 0, "e l'officina di gennaio resta fuori");
    eq(r.fuori, { interventi: 1, costo: 900 }, "contata, dichiarata, non nascosta");
    eq(r.carburante, 450, "il gasolio di gennaio invece è speso davvero e resta nel conto del carburante");
    const c = flotta.consumoPerMezzo([{ data: "2026-01-05", mezzo: "Pala X", litri: 100, euro: 150 },
                                      { data: "2026-07-01", mezzo: "Pala X", litri: 100, ore: 1000, euro: 150 },
                                      { data: "2026-07-31", mezzo: "Pala X", litri: 100, ore: 1100, euro: 150 }]).mezzi[0];
    eq([c.da, c.a], [r.da, r.a], "e la finestra è quella di consumoPerMezzo, non una seconda copia");
  });

  test("Flotta · €/h: la finestra è quella di consumoPerMezzo, non un secondo conto", () => {
    /* Stessa regola che la funzione si è già data sulle ore: due conti delle
       stesse letture un giorno divergono senza che nessuno se ne accorga. */
    const righe = flotta.costoOrarioMezzo(F.interventi, F.rifornimenti).filter((r) => r.ore !== null);
    const car = flotta.consumoPerMezzo(F.rifornimenti);
    ok(righe.length >= 3, righe.length + " mezzi della dimostrazione hanno una finestra");
    for (const r of righe) {
      const c = car.mezzi.find((m) => m.mezzo === r.mezzo);
      eq([r.da, r.a], [c.da, c.a], r.mezzo + ": la finestra è quella delle letture, non una seconda copia");
      ok(r.da <= r.a, r.mezzo + ": e va nel verso giusto (" + r.da + " → " + r.a + ")");
      /* ⛔ E NEMMENO IL GASOLIO È UNA SECONDA COPIA: si pretende l'IDENTITÀ col
         numero di `consumoPerMezzo`, non un comportamento uguale. Due copie
         uguali oggi divergono domani senza che nessuno lo veda — ed è
         esattamente quello che era successo qui, dove il gasolio veniva rifatto
         a mano su `euro` invece che letto. */
      eq(r.carburanteInFinestra, c.euroInFinestra,
         r.mezzo + ": il gasolio della finestra è quello di consumoPerMezzo, non un secondo conto");
      ok(r.carburanteInFinestra !== r.carburante,
         r.mezzo + ": e non è il gasolio di tutta la vita (" + r.carburanteInFinestra + " contro " + r.carburante
         + "): se fossero uguali questa prova non distinguerebbe niente");
      /* ⚠️ e nemmeno ricavato da `euroOra × ore`, che sarebbe un TERZO conto:
         si controlla che i due tornino, non che uno nasca dall'altro. */
      ok(Math.abs(c.euroOra * r.ore - r.carburanteInFinestra) <= 0.5,
         r.mezzo + ": e torna con l'euro/ora del gasolio (" + c.euroOra + " × " + r.ore + " h)");
    }
  });

  test("⛔ Flotta · €/h: sulla dimostrazione il numero SCENDE, e si sa di quanto", () => {
    /* La prova che il difetto era quello e non un'impressione. I tre mezzi
       toccati, con lo scarto misurato prima della correzione. */
    const righe = flotta.costoOrarioMezzo(F.interventi, F.rifornimenti);
    /* ⚠️ I NUMERI SONO SCESI DUE VOLTE, IN DUE PASSAGGI, E VANNO LETTI COSÌ:
         mezzo          prima   officina in finestra   + gasolio in finestra
         Dumper D1      63,03   → 28,61 (−2.100 €)     → 19,02 (−585 € di primo pieno)
         Pala P1        51,21   → 28,18 (−760 €)       → 14,55 (−450 €)
         Escavatore E1  46,46   → 38,96 (−420 €)       → 26,11 (−720 €)
       La seconda metà è più grossa della prima su due mezzi su tre. */
    const atteso = { "Dumper D1": [19.02, 2100], "Pala P1": [14.55, 760], "Escavatore E1": [26.11, 420] };
    let toccati = 0;
    for (const r of righe) {
      if (!atteso[r.mezzo]) continue;
      const [eh, fuori] = atteso[r.mezzo];
      eq(r.euroOra, eh, r.mezzo + ": il €/h sulla finestra");
      eq(r.fuori.costo, fuori, r.mezzo + ": e l'officina che cade fuori, dichiarata");
      ok(r.fuori.interventi === 1, r.mezzo + ": un intervento solo, ma pesante");
      toccati++;
    }
    eq(toccati, 3, "tre mezzi su sei della dimostrazione avevano il numero gonfiato: sono questi");
  });
}

test("⛔ Campo: un turno ANCORA APERTO non prende il verde, e il 100% dice perché", () => {
  /* I fermi si registrano DURANTE il turno. Su un turno non ancora chiuso
     «100%» non vuol dire «è andato tutto bene»: vuol dire «finora nessuno ha
     scritto niente». È il principio del fondatore nel punto in cui l'assenza è
     soltanto il fatto che il turno non è ancora finito.
     Candidato uscito dalla ricerca continua su Campo e RIMISURATO prima di
     essere creduto: la ricerca diceva «il numero è tranquillo», la misura ha
     detto che la funzione non sapeva nemmeno se il turno fosse chiuso. */
  const D = [{ data: "2026-07-20", turno: "Mattino", minuti: 480 }];
  const lavoro = [{ data: "2026-07-20", turno: "Mattino", titolo: "Perforazione", stato: "in-corso" }];
  const CHIUSO = [{ data: "2026-07-20", turno: "Mattino", da: "Rossi", a: "Bianchi", ora: "14:05" }];

  const aperto = campo.disponibilitaTurno(lavoro, D, "2026-07-20", "Mattino", []);
  eq(aperto.pct, 100, "il conto resta 100: nessun fermo registrato");
  eq(aperto.provvisorio, true, "ma il turno è ancora aperto");
  eq(aperto.stato, "warn", "e allora NON prende il verde");
  ok(/non è ancora chiuso/.test(aperto.motivo), "e lo dice");
  ok(/non che il turno stia andando bene/.test(aperto.motivo),
     "col caso peggiore nominato: zero fermi su un turno aperto");

  const chiuso = campo.disponibilitaTurno(lavoro, D, "2026-07-20", "Mattino", CHIUSO);
  eq(chiuso.provvisorio, false, "a turno chiuso non è più provvisorio");
  eq(chiuso.stato, "ok", "e il verde è meritato: qualcuno ha dichiarato finito il turno");
  eq(chiuso.motivo, "", "e non c'è niente da spiegare");

  /* ⚠️ E se chi chiama NON passa le chiusure, la funzione non si inventa una
     risposta rassicurante: dice «non lo so». Vale per lei come per il
     prodotto. */
  const nonDetto = campo.disponibilitaTurno(lavoro, D, "2026-07-20", "Mattino");
  eq(nonDetto.provvisorio, null, "senza chiusure: non lo so, non «è chiuso»");
  eq(nonDetto.stato, "ok", "e il comportamento di prima resta invariato");

  /* un turno aperto CON un fermo misurato: il numero può solo scendere */
  const conFermo = campo.disponibilitaTurno(
    lavoro.concat([{ data: "2026-07-20", turno: "Mattino", stato: "anomalia", causale: "Guasto", fermoMin: 48 }]),
    D, "2026-07-20", "Mattino", []);
  eq(conFermo.pct, 90, "480 − 48");
  eq(conFermo.stato, "warn", "aperto: niente verde");
  ok(/può solo scendere/.test(conFermo.motivo), "e la ragione è quella giusta, non quella dello zero");
});

/* ══ FLOTTA: LA SEGNALAZIONE DI UN GUASTO ══ */
test("GRAVITA_GUASTO: tre livelli, una sola «alta», tutti spiegati", () => {
  const g = flotta.GRAVITA_GUASTO;
  eq(g.length, 3, "non si può usare / lavora ma male / piccola cosa");
  eq(new Set(g.map(x => x.chiave)).size, 3, "chiavi uniche");
  eq(g.filter(x => x.alta).length, 1, "una sola gravità fa scattare la proposta di fermare");
  eq(g[0].alta, true, "ed è la prima: l'elenco va dal più grave al meno");
  for (const x of g) {
    ok(x.etichetta && x.etichetta.length > 5, `${x.chiave}: l'etichetta si legge`);
    ok(x.aiuto && x.aiuto.length > 30, `${x.chiave}: c'è la spiegazione sotto`);
    ok(x.nota && x.nota.length > 20, `${x.chiave}: e la nota che finisce sulla manutenzione`);
  }
  eq(flotta.gravitaGuasto("inventata"), null, "una chiave che non c'è è null, non la prima della lista");
});
test("⛔ validaGuasto: ogni rifiuto dice che cosa fare, non «campo obbligatorio»", () => {
  const buono = { mezzo: "Escavatore E1", descrizione: "perde olio dal braccio", gravita: "limita" };
  eq(flotta.validaGuasto(buono).ok, true, "il caso normale passa");
  eq(flotta.validaGuasto({ ...buono, mezzo: "" }).ok, false, "senza mezzo no");
  eq(flotta.validaGuasto({ ...buono, descrizione: "" }).ok, false, "senza descrizione no");
  eq(flotta.validaGuasto({ ...buono, descrizione: "x" }).ok, false, "una sigla di una lettera non dice niente a chi ripara");
  eq(flotta.validaGuasto({ ...buono, descrizione: "abc" }).ok, true, "tre lettere bastano");
  eq(flotta.validaGuasto({ ...buono, descrizione: "a".repeat(120) }).ok, true, "centoventi è il limite, e ci sta");
  eq(flotta.validaGuasto({ ...buono, descrizione: "a".repeat(121) }).ok, false, "centoventuno no");
  eq(flotta.validaGuasto({ ...buono, gravita: "" }).ok, false, "senza gravità no: serve a decidere se il turno si finisce");
  eq(flotta.validaGuasto({ ...buono, descrizione: "  perde olio  " }).descrizione, "perde olio",
    "gli spazi ai bordi si tolgono, se no due segnalazioni uguali sembrano diverse");
  for (const [campo_, rotto] of [["mezzo", { mezzo: "" }], ["descrizione", { descrizione: "" }], ["gravita", { gravita: "" }]]) {
    const e = flotta.validaGuasto({ ...buono, ...rotto }).errori[campo_];
    ok(e && e.length > 40, `«${campo_}»: il messaggio spiega invece di sgridare (${(e || "").slice(0, 40)}…)`);
  }
});
test("⛔ manutenzioneDaGuasto: «non si sa chi» si scrive, non si tace", () => {
  const base = { mezzo: "Escavatore E1", descrizione: "perde olio dal braccio", gravita: "ferma" };
  eq(flotta.manutenzioneDaGuasto({ ...base, descrizione: "" }), null,
    "da una segnalazione non valida non nasce niente");
  const m = flotta.manutenzioneDaGuasto({ ...base, segnalatoDa: "Rossi" }, new Date("2026-07-20T09:00:00"));
  eq(m.origine, "guasto", "l'origine la distingue dalle altre manutenzioni");
  ok(/^Guasto: /.test(m.titolo), "il titolo dice subito che cos'è: " + m.titolo);
  ok(/perde olio dal braccio/.test(m.titolo), "e riporta quello che è stato scritto");
  ok(/Rossi/.test(m.nota), "chi ha segnalato finisce nella nota");
  /* Senza il nome NON si tace: chi legge in officina deve sapere che non
     risulta, non credere che il campo non esista. */
  const anonimo = flotta.manutenzioneDaGuasto(base, new Date("2026-07-20T09:00:00"));
  ok(/non risulta chi/.test(anonimo.nota), "e se manca, lo dice: " + anonimo.nota.slice(-40));
});

/* ══ SU QUALE MATERIALE SI PAGA IL CANONE ══
   Terra scriveva al titolare «la base di calcolo sono N m³ di scavo misurato»
   e lo mandava in Conti; Conti calcolava sul VENDUTO, ricavato dalle pesate.
   Fra scavato e venduto ci sono le scorte di piazzale, gli scarti e il
   materiale usato per il ripristino: il numero che Terra prometteva non lo
   produceva nessuno. */
test("⛔ canone: la base è una scelta dichiarata, e la risposta dice quale ha usato", () => {
  const pesate = [{ data: "2026-03-10", prodotto: "Misto", netto: 20, quantita: 12,
                    unitaVendita: "m3", densita: 1.6 }];
  const rilievi = [{ data: "2026-03-15", stato: "elaborato", volumeM3: 900, provenienza: "scavo" },
                   { data: "2026-03-20", stato: "elaborato", volumeM3: 100, provenienza: "cumulo" }];
  const base = { canoneUnita: "m3", canoneAliquota: 0.5 };
  const v = conti.canonePeriodo(pesate, base, "2026-01-01", "2026-12-31");
  eq(v.baseScelta, "venduto", "senza scelta si resta sul venduto, come prima");
  eq(v.base, 12, "i metri cubi venduti");
  eq(v.dovuto, 6, "12 × 0,50");
  const s = conti.canonePeriodo(pesate, { ...base, canoneBase: "scavato" }, "2026-01-01", "2026-12-31", rilievi);
  eq(s.baseScelta, "scavato", "la scelta si vede nella risposta");
  eq(s.base, 900, "i metri cubi SCAVATI, non i dodici venduti");
  eq(s.dovuto, 450, "900 × 0,50");
  eq(s.m3DaCumuli, 100, "e i cento ripresi dai cumuli restano fuori: erano già stati scavati");
  eq(s.metriCubi, 12, "il venduto resta scritto lo stesso, per poter confrontare");
});
test("⛔ canone: senza rilievi il dovuto è «non lo so», non zero", () => {
  /* L'asimmetria è voluta: nessuna PESATA vuol dire che non è stato venduto
     niente, ed è un fatto. Nessun RILIEVO non vuol dire che non è stato
     scavato niente — vuol dire che nessuno ha misurato. */
  const cfg = { canoneUnita: "m3", canoneAliquota: 0.5, canoneBase: "scavato" };
  const vuoto = conti.canonePeriodo([], cfg, "2026-01-01", "2026-12-31", []);
  eq(vuoto.base, null, "la base non c'è");
  eq(vuoto.dovuto, null, "e il dovuto nemmeno: uno zero direbbe «non devi niente»");
  ok(/nessuno ha misurato/.test(vuoto.motivo), "e la frase lo dice: " + vuoto.motivo.slice(0, 60));
  const staccato = conti.canonePeriodo([], cfg, "2026-01-01", "2026-12-31", null);
  eq(staccato.dovuto, null, "e nemmeno se Terra non è raggiungibile");
  ok(/non sono raggiungibili/.test(staccato.motivo), "che è un motivo diverso, e va detto diverso");
  /* Sul VENDUTO invece lo zero è la risposta giusta. */
  const senzaPesate = conti.canonePeriodo([], { canoneUnita: "m3", canoneAliquota: 0.5 }, "2026-01-01", "2026-12-31");
  eq(senzaPesate.dovuto, 0, "nessuna pesata = non è stato venduto niente, e zero è un fatto");
});
test("⛔ canone: l'aliquota a tonnellata sui rilievi non si inventa una densità", () => {
  /* I rilievi misurano metri cubi IN POSTO. Convertirli in tonnellate vorrebbe
     la densità del banco, che non è quella del materiale sciolto del listino:
     usare quella darebbe un numero plausibile e sbagliato su un documento che
     va all'ente. */
  const r = conti.canonePeriodo([], { canoneUnita: "t", canoneAliquota: 1.2, canoneBase: "scavato" },
    "2026-01-01", "2026-12-31", [{ data: "2026-03-15", stato: "elaborato", volumeM3: 900, provenienza: "scavo" }]);
  eq(r.dovuto, null, "non si risponde");
  eq(r.scavatoM3, 900, "ma i metri cubi si dicono lo stesso");
  ok(/densità del banco/.test(r.motivo), "e si spiega che cosa manca");
});
test("BASI_CANONE: due scelte, ognuna con la sua spiegazione", () => {
  eq(conti.BASI_CANONE.length, 2, "venduto e scavato");
  for (const b of conti.BASI_CANONE) {
    ok(b.chiave && b.etichetta && b.spiega, `«${b.chiave}» ha etichetta e spiegazione`);
    ok(b.spiega.length > 40, `e la spiegazione dice qualcosa (${b.chiave})`);
  }
  eq(conti.BASI_CANONE[0].chiave, "venduto", "il venduto è il primo: è il comportamento di sempre");
});

/* ══ SENTINELLA: LE VOLATE NEL REPORT DI CONFORMITÀ ══ */
test("⛔ report: nelle volate del periodo entrano solo le ESEGUITE", () => {
  /* la sezione previsto/misurato marca «non misurata» ciò che non ha PPV: su una
     volata soltanto PREVISTA sarebbe una dichiarazione falsa a un ente — l'evento
     non è avvenuto, non è che nessuno l'ha misurato */
  const r = sentinella.reportConformita({ dal: "2026-07-01", al: "2026-07-31",
    monitoraggi: [], ricettori: [], volate: [
      { id: "a", data: "2026-07-10", stato: "eseguita" },
      { id: "c", data: "2026-07-20", stato: "prevista" },
      { id: "d", data: "2026-06-10", stato: "eseguita" }] });
  eq(r.nVolate, 1, "una sola");
  eq(r.volate.map(v => v.id).join(","), "a", "la prevista e quella di giugno restano fuori");
});
test("⛔ previsione: un limite a zero è «non dichiarato», non un limite di zero", () => {
  /* la cella del report scrive il limite solo se non è null: se qui uscisse 0,
     il documento citerebbe all'ente un limite di 0 mm/s, cioè il falso peggiore */
  eq(sentinella.previsioneDiVolata({ ppvPrevista: 3.4, ppvPrevLimite: 0 }).limite, null, "zero non è un limite");
  eq(sentinella.previsioneDiVolata({ ppvPrevista: 3.4, ppvPrevLimite: 5 }).limite, 5, "cinque sì");
});
test("⛔ previsione: la norma si riporta com'è registrata, non riscritta", () => {
  eq(sentinella.previsioneDiVolata({ ppvPrevista: 4.6, ppvPrevNorma: "  DIN 4150-3 residenziale @ 25 Hz  " }).norma,
     "DIN 4150-3 residenziale @ 25 Hz", "solo gli spazi ai bordi");
  eq(sentinella.previsioneDiVolata({ ppvPrevista: 4.6 }).norma, "", "e se non c'è resta vuota");
});
test("scarto: sotto la previsione il segno resta negativo, in mm/s e in percentuale", () => {
  /* provato solo il verso «sopra»: è il caso in cui delta e pct sono positivi e
     un segno perso non si vedrebbe */
  const s = sentinella.scartoPpvVolata({ ppvPrevista: 3.4, ppvMisurata: 3.35, ppvFonte: "strumento" });
  eq(s.delta, -0.05, "cinque centesimi in meno");
  eq(s.pct, -1.5, "cioè -1,5 %");
  eq(s.verso, "sotto", "sotto il previsto");
});

/* ══ LO SCONTO DEL CLIENTE ENTRA NEL PREZZO ══
   Fino al 03/08 la scheda cliente diceva «sconto 5%» e ogni DDT usciva al
   prezzo PIENO di listino: `rigaPesata` il cliente non lo riceveva proprio.
   Misurato su una differita vera — 2.230 t a 12,34 €/t — erano **1.375,91 €**
   fatturati in più di quello che il cliente vedeva scritto sulla sua scheda. */
test("⛔ lo sconto del cliente arriva fino al valore della pesata", () => {
  const prod = { prezzo: 12.34, unitaPrezzo: "t", iva: 22 };
  const pieno = conti.rigaPesata(prod, 30.5, 8.2);
  eq(pieno.scontoPct, 0, "senza cliente lo sconto è zero, non «non lo so»");
  eq(pieno.valore, 275.18, "e il valore è quello di listino");
  const scontato = conti.rigaPesata(prod, 30.5, 8.2, { sconto: 5 });
  eq(scontato.scontoPct, 5, "lo sconto viene fotografato sulla pesata");
  eq(scontato.prezzoUnitario, 12.34, "il prezzo resta il LISTINO: il DDT lo deve scrivere");
  eq(scontato.valore, 261.42, "e lo sconto si vede nel valore");
  eq(conti.valorePesata(scontato), 261.42, "il valore ricalcolato da un documento salvato è lo stesso");
});
test("⛔ un DDT salvato PRIMA che lo sconto esistesse non cambia di un centesimo", () => {
  /* La compatibilità all'indietro non è un dettaglio: sono documenti già
     consegnati. Un record senza `scontoPct` deve valere esattamente quanto
     valeva ieri. */
  const vecchio = { quantita: 22.3, prezzoUnitario: 12.34, unitaVendita: "t" };
  eq(conti.valorePesata(vecchio), 275.18, "nessuno sconto scritto = nessuno sconto applicato");
  eq(conti.valorePesata({ ...vecchio, scontoPct: null }), 275.18, "e nemmeno uno sconto nullo");
});
test("⛔ lo sconto si toglie dall'IMPONIBILE, non dal prezzo unitario", () => {
  /* Piegarlo dentro il prezzo obbligherebbe ad arrotondarlo ai centesimi, e
     l'errore si moltiplica per la quantità: sulla stessa differita fa 6,69 €
     in meno del dovuto. Su un documento fiscale i centesimi non sono un
     dettaglio, e il conto lo rifà chi riceve la fattura. */
  eq(conti.imponibileRiga(2230, 12.34, 5), 26142.29, "sconto sull'imponibile");
  const prezzoPiegato = Math.round(12.34 * 0.95 * 100) / 100;   // 11,72
  eq(Math.round(2230 * prezzoPiegato * 100) / 100, 26135.60, "sconto piegato nel prezzo: 6,69 € in meno");
  eq(conti.imponibileRiga(2230, 12.34, 0), 27518.20, "senza sconto è il pieno");
});
test("scontoValido: una percentuale, non un numero qualunque", () => {
  eq(conti.scontoValido({ sconto: 5 }), 5, "il caso normale");
  eq(conti.scontoValido({ sconto: 2.5 }), 2.5, "i mezzi punti si tengono");
  eq(conti.scontoValido({ sconto: 0 }), 0, "zero è zero");
  eq(conti.scontoValido({}), 0, "un cliente senza sconto non ne ha");
  eq(conti.scontoValido(null), 0, "e nemmeno un cliente che manca");
  eq(conti.scontoValido({ sconto: -3 }), 0, "uno sconto negativo sarebbe un RINCARO: non passa");
  eq(conti.scontoValido({ sconto: 150 }), 100, "e oltre il 100% si regala, non si paga: si ferma a 100");
  eq(conti.scontoValido({ sconto: "abc" }), 0, "quello che non è un numero non è uno sconto");
});
test("⛔ la fattura differita porta lo sconto, e non mescola sconti diversi", () => {
  const ddt = [
    { id: "p1", numero: "1", prodotto: "Misto", prodottoId: "m", quantita: 100, unitaVendita: "t",
      prezzoUnitario: 12.34, scontoPct: 5, aliquotaIva: 22 },
    { id: "p2", numero: "2", prodotto: "Misto", prodottoId: "m", quantita: 50, unitaVendita: "t",
      prezzoUnitario: 12.34, scontoPct: 5, aliquotaIva: 22 },
    /* stesso prodotto, stesso prezzo, sconto DIVERSO: succede quando le
       condizioni cambiano a metà mese. Non si possono unire — unirle vuol dire
       scegliere quale dei due sconti raccontare. */
    { id: "p3", numero: "3", prodotto: "Misto", prodottoId: "m", quantita: 40, unitaVendita: "t",
      prezzoUnitario: 12.34, scontoPct: 0, aliquotaIva: 22 },
  ];
  const righe = conti.righeDaPesate(ddt);
  eq(righe.length, 2, "due righe: uno sconto per riga");
  const conSconto = righe.find(r => r.scontoPct === 5);
  eq(conSconto.quantita, 150, "i due DDT scontati si sommano");
  eq(conSconto.imponibile, 1758.45, "150 × 12,34 − 5%");
  eq(conSconto.ddt.sort().join(","), "1,2", "e la riga dice da quali DDT viene");
  const senza = righe.find(r => r.scontoPct === 0);
  eq(senza.imponibile, 493.60, "40 × 12,34, pieno");
  const f = conti.fatturaDaPesate(ddt);
  eq(f.imponibile, 2252.05, "il totale della fattura tiene conto dello sconto");
  eq(f.ivaImporto, 495.45, "e l'IVA si calcola sull'imponibile scontato, non sul pieno");
});

/* ══ GLI ULTIMI SEI EXPORT CHE NESSUNA PROVA NOMINAVA ══
   Il censimento (`copertura-funzioni.mjs`) diceva 405 su 411, e i sei
   scoperti erano tutti della stessa famiglia: **alias e costanti**, cioè
   proprio le cose che sembrano non aver bisogno di una prova. Ma un alias è
   esattamente ciò che si rompe in silenzio — basta che qualcuno rimetta un
   `export const AVVISO_DECIMALE = "…"` e la frase torna a essere due. */
/* ⚠️ QUI L'IDENTITÀ NON DIMOSTRA QUELLO CHE DIMOSTRA ALTROVE, e la
   controprova me l'ha fatto vedere: rimettendo in Terra una COPIA della frase
   scritta a mano, `terra.AVVISO_DECIMALE === shell.AVVISO_DECIMALE` resta
   **vero** — due stringhe uguali sono `===` anche quando sono due copie. Per
   le funzioni l'identità è la prova buona; per le costanti di testo no, e il
   controllo che sa vederlo guarda il SORGENTE (`FRASI_UNICHE` in
   `nomi-doppi.mjs`). Questa prova serve a un'altra cosa: che la frase arrivi
   dappertutto e che DICA quello che deve dire. */
test("AVVISO_DECIMALE: la stessa frase in quattro app, e con l'esempio dentro", () => {
  ok(conti.AVVISO_DECIMALE === shell.AVVISO_DECIMALE, "Conti");
  ok(flotta.AVVISO_DECIMALE === shell.AVVISO_DECIMALE, "Flotta");
  ok(sentinella.AVVISO_DECIMALE === shell.AVVISO_DECIMALE, "Sentinella");
  ok(terra.AVVISO_DECIMALE === shell.AVVISO_DECIMALE, "Terra");
  /* La frase deve NOMINARE tutt'e due le forme con un esempio: «va bene la
     virgola» detto in astratto non dice a chi compila che può battere il
     punto della tastiera numerica. */
  ok(/2,4/.test(shell.AVVISO_DECIMALE) && /2\.4/.test(shell.AVVISO_DECIMALE),
    "la frase mostra l'esempio in tutt'e due le scritture");
});
test("⛔ AVVISO_MIGLIAIA: dice di NON scriverlo, e lo fa vedere", () => {
  ok(flotta.AVVISO_MIGLIAIA === shell.AVVISO_MIGLIAIA, "Flotta la ri-esporta");
  ok(/1250/.test(shell.AVVISO_MIGLIAIA) && /1\.250/.test(shell.AVVISO_MIGLIAIA),
    "mostra la forma giusta e quella sbagliata: senza l'esempio la frase non si capisce");
  ok(shell.AVVISO_MIGLIAIA !== shell.AVVISO_DECIMALE, "sono due avvisi diversi");
});
test("TIPI_MEZZO: chiavi uniche, «altro» è l'ultimo e non indovina niente", () => {
  const chiavi = flotta.TIPI_MEZZO.map(t => t.chiave);
  eq(new Set(chiavi).size, chiavi.length, "nessuna chiave ripetuta");
  eq(chiavi[chiavi.length - 1], "altro", "«altro» sta in fondo: si arriva lì solo se nessun indizio ha preso");
  eq(flotta.TIPI_MEZZO[flotta.TIPI_MEZZO.length - 1].indizi.length, 0,
    "e non ha indizi, altrimenti prenderebbe al posto di un tipo vero");
  for (const t of flotta.TIPI_MEZZO) {
    ok(t.etichetta && t.etichetta.length > 2, `${t.chiave} ha un'etichetta leggibile`);
    for (const i of t.indizi) eq(i, i.toLowerCase(), `l'indizio «${i}» è minuscolo: il confronto lo è`);
  }
  /* Nessun indizio deve essere il PREFISSO di un altro tipo: l'ordine di
     TIPI_MEZZO deciderebbe il tipo al posto del nome, e cambiando una riga
     dell'elenco cambierebbe la checklist di macchine già registrate. */
  const tutti = flotta.TIPI_MEZZO.flatMap(t => t.indizi.map(i => [t.chiave, i]));
  for (const [c1, i1] of tutti) for (const [c2, i2] of tutti) {
    if (c1 === c2) continue;
    ok(!i2.includes(i1), `«${i1}» (${c1}) è dentro «${i2}» (${c2}): il tipo lo deciderebbe l'ordine`);
  }
});
test("TIPI_MEZZO: `tipoMezzo` e `tipoMezzoDi` restituiscono sempre una voce dell'elenco", () => {
  eq(flotta.tipoMezzo("escavatore").etichetta, "Escavatore", "per chiave");
  eq(flotta.tipoMezzo("inventato"), null, "una chiave che non c'è è null, non «altro»");
  const dentro = (v) => flotta.TIPI_MEZZO.includes(v);
  ok(dentro(flotta.tipoMezzoDi({ tipo: "pala" })), "il tipo salvato vince");
  ok(dentro(flotta.tipoMezzoDi({ nome: "Miniescavatore 3t" })), "indovinato dal nome");
  eq(flotta.tipoMezzoDi({ nome: "Miniescavatore 3t" }).chiave, "escavatore", "e lo indovina giusto");
  eq(flotta.tipoMezzoDi({ tipo: "dumper", nome: "Escavatore vecchio" }).chiave, "dumper",
    "il dato scritto batte l'indizio nel nome: indovinare non deve sovrascrivere l'anagrafica");
  eq(flotta.tipoMezzoDi({ nome: "Coso senza nome noto" }).chiave, "altro", "nessun indizio → altro");
  eq(flotta.tipoMezzoDi(null).chiave, "altro", "e un mezzo che manca non fa cadere niente");
  eq(flotta.tipoMezzoDi({}).chiave, "altro", "nemmeno uno senza nome né tipo");
});

/* ────────────────────────────────────────────────────────────────────────
   CAMPO · L'ASSENZA DI UN DATO NON È UN DATO FAVOREVOLE
   Tre punti in cui Campo rispondeva con un numero (o un colore) tranquillo
   dove non era stato misurato niente. Il censimento e le misure stanno nel
   racconto del cantiere; qui restano le prove.
   ──────────────────────────────────────────────────────────────────────── */
test("⛔ pianoRiepilogo: nessun foro pesato non è «in linea col progetto»", () => {
  /* Con zero cariche reali lo stimato È il progettato per costruzione: la
     differenza faceva 0, scartoLivello rispondeva «ok» e la pillola usciva
     VERDE a +0% su una volata in cui nessuno aveva ancora pesato un foro. */
  const piano = [{ foro: 1, prog: 40, reale: null },
                 { foro: 2, prog: 50, reale: null },
                 { foro: 3, prog: 60, reale: null }];
  const r = campo.pianoRiepilogo(piano);
  eq(r.pct, null, "niente percentuale: non c'è nessuna misura da confrontare");
  eq(r.livello, "da-registrare", "e nemmeno un livello tranquillo: la stessa parola del badge del singolo foro");
  eq(r.registrati, 0, "zero registrati");
  eq(r.progettatoKg, 150, "il progettato resta: quello è scritto nel piano");
});
test("⛔ pianoRiepilogo: basta UN foro pesato e la percentuale torna a esserci", () => {
  /* la guardia non deve spegnere il conto quando la misura c'è davvero */
  const r = campo.pianoRiepilogo([{ foro: 1, prog: 100, reale: 130 },
                                  { foro: 2, prog: 100, reale: null }]);
  eq(r.pct, 15, "+15%: 30 kg in più su 200 progettati");
  eq(r.livello, "warn", "e il livello è quello vero, non «da-registrare»");
});
test("⛔ minutiFermoTesto: «0 min» solo quando lo zero è una misura", () => {
  /* `+null` fa zero e `Number.isFinite(0)` risponde true: la guardia sta
     PRIMA della conversione, se no «non lo so» diventa «zero minuti persi» */
  eq(campo.minutiFermoTesto(0, 0, 0), "0 min", "nessun fermo: lo zero è vero, c'eravamo e non ci siamo fermati");
  eq(campo.minutiFermoTesto(45, 1, 0), "45 min", "un fermo misurato: il numero com'è");
  eq(campo.minutiFermoTesto(0, 2, 2), "senza minuti", "due fermi e nessun minuto: NON «0 min»");
  eq(campo.minutiFermoTesto(30, 3, 2), "almeno 30 min", "misurato uno su tre: il tempo perso è almeno questo");
  eq(campo.minutiFermoTesto(null, 1, 1), "senza minuti", "e null non diventa zero");
  eq(campo.minutiFermoTesto(undefined, 0, 0), "senza minuti", "nemmeno undefined");
  eq(campo.minutiFermoTesto("", 0, 0), "senza minuti", "nemmeno la stringa vuota");
});
test("⛔ storicoSettimana: la giornata coi fermi mai misurati si distingue da quella senza fermi", () => {
  const OGGI = new Date("2026-07-31T12:00:00");
  const att = [
    { data: "2026-07-30", stato: "conclusa" },                                    // giornata senza fermi
    { data: "2026-07-31", stato: "anomalia", causale: "Guasto meccanico" },       // fermo senza minuti
    { data: "2026-07-31", stato: "anomalia", causale: "Meteo" },                  // idem
    { data: "2026-07-31", stato: "conclusa" },
  ];
  const st = campo.storicoSettimana(att, [], 2, OGGI);
  contiene(st[0], { data: "2026-07-30", fermi: 0, fermiSenzaMinuti: 0, minutiFermo: 0 },
    "il 30 non ha fermi: lo zero è una misura");
  contiene(st[1], { data: "2026-07-31", fermi: 2, fermiSenzaMinuti: 2, minutiFermo: 0 },
    "il 31 ha due fermi e nessun minuto: stessi zero minuti, fatto diverso");
  eq(campo.minutiFermoTesto(st[0].minutiFermo, st[0].fermi, st[0].fermiSenzaMinuti), "0 min",
    "e a schermo le due giornate non si scrivono uguale");
  eq(campo.minutiFermoTesto(st[1].minutiFermo, st[1].fermi, st[1].fermiSenzaMinuti), "senza minuti",
    "il 31 non dice «0 min»");
  const tot = campo.totaliSettimana(st);
  contiene(tot, { fermi: 2, fermiSenzaMinuti: 2, minutiFermo: 0 },
    "e il cartellone della settimana porta lo stesso conto");
});
test("⛔ storicoSettimana: un fermo misurato e uno no fanno «almeno»", () => {
  const OGGI = new Date("2026-07-31T12:00:00");
  const att = [
    { data: "2026-07-31", stato: "anomalia", fermoMin: 20 },
    { data: "2026-07-31", stato: "anomalia" },
  ];
  const st = campo.storicoSettimana(att, [], 1, OGGI);
  contiene(st[0], { fermi: 2, fermiSenzaMinuti: 1, minutiFermo: 20 }, "uno misurato, uno no");
  eq(campo.minutiFermoTesto(st[0].minutiFermo, st[0].fermi, st[0].fermiSenzaMinuti), "almeno 20 min",
    "il tempo perso è ALMENO 20 min, non esattamente 20");
});

/* ══════════════════════════════════════════════════════════════════════════
   ⛔ FLOTTA — IL CONTATORE CHE NESSUNO HA LETTO NON SEGNA ZERO (01/08)
   Censimento dei punti in cui Flotta riassume, colora o conta qualcosa a
   partire dalle ore motore. Due righe facevano lo stesso lavoro — dentro
   `prioritaOperative` e dentro `tagliandiInScadenza` — ed erano scritte tutt'e
   due `Number.isFinite(+m.ore)`, con sopra il commento «chi non ha il
   contatore torna null». Misurato: `+null` fa **0** e `Number.isFinite(0)`
   risponde **true**, quindi un mezzo con `ore: null` (che è esattamente quello
   che `parseMezziCsv` scrive quando il contatore è illeggibile, per una regola
   scritta il 31/07) valeva **zero ore**.
   La prova che c'era già — «un mezzo senza contatore non fa sembrare il
   tagliando lontano» — passava lo stesso, ma per un motivo diverso dal suo
   nome: non passava nessuna lettura del contatore, quindi il ritmo mancava
   comunque e le due risposte coincidevano. È il caso (1) di CLAUDE.md: i dati
   della prova fanno coincidere la risposta giusta con quella sbagliata. Qui
   sotto le letture ci sono, ed è lì che il difetto si vede.
   ══════════════════════════════════════════════════════════════════════════ */
test("⛔ Flotta: con ore ignote e ritmo misurabile il tagliando NON viene contato", () => {
  const oggi = new Date(2026, 7, 1, 10, 0, 0);
  const g = (n) => new Date(Date.parse("2026-08-01T12:00:00Z") - n * 86400000).toISOString().slice(0, 10);
  const mezzi = [{ id: "m1", nome: "Dumper D1 — CAT 745", ore: null, stato: "operativo" }];
  // due letture del contatore a 18 giorni di distanza: il ritmo si MISURA
  const letture = [{ mezzo: "Dumper D1", data: g(20), ore: 8355 },
                   { mezzo: "Dumper D1", data: g(2), ore: 8416 }];
  const man = [{ id: "n1", titolo: "Tagliando 250h", mezzo: "Dumper D1", dataPrevista: null, orePreviste: 100 }];
  const t = flotta.tagliandiInScadenza(man, mezzi, letture, oggi);
  eq(t.totale, 0, "col contatore ignoto non si conta un tagliando «fra 30 giorni»");
  eq(t.aOre, 0, "e non lo si conta nemmeno fra quelli a ore");
  eq(t.nonStimabili, 1, "va dichiarato a parte, che è la strada onesta");
  eq(t.daStimare[0].mancano, null, "e «quante ore mancano» resta null: 100 − 0 era un numero inventato");
});
test("⛔ Flotta: «non è nel parco» e «senza contatore» sono due frasi diverse", () => {
  const oggi = new Date(2026, 7, 1, 10, 0, 0);
  const man = [{ id: "n1", titolo: "Tagliando 500h", mezzo: "Pala P1", dataPrevista: null, orePreviste: 6000 }];
  const dentro = flotta.tagliandiInScadenza(man, [{ nome: "Pala P1 — CAT 980", ore: null }], [], oggi);
  const fuori = flotta.tagliandiInScadenza(man, [], [], oggi);
  ok(!/non è nel parco/.test(dentro.daStimare[0].perche),
    "il mezzo C'È: dire che non è nel parco manda a cercare una macchina che sta lì — «"
    + dentro.daStimare[0].perche + "»");
  ok(/ore del contatore/.test(dentro.daStimare[0].perche), "si dice quale dato manca");
  ok(/non è nel parco/.test(fuori.daStimare[0].perche), "e quando davvero non c'è, lo si dice");
});
test("⛔ Flotta: un mezzo senza contatore non fa comparire un avviso nel Quadro", () => {
  const oggi = new Date(2026, 7, 1, 10, 0, 0);
  const mezzi = [{ id: "m1", nome: "Dumper D1 — CAT 745", ore: null, stato: "operativo" }];
  // 40 ore previste: con lo zero di comodo uscivano «tra 40 h» in GIALLO
  const man = [{ id: "n9", titolo: "Tagliando 50h", mezzo: "Dumper D1", dataPrevista: null, orePreviste: 40 }];
  eq(flotta.prioritaOperative(mezzi, man, [], oggi), [],
    "nessuna riga: un avviso su un contatore mai letto è un allarme inventato");
  // e il contatore che c'è continua a funzionare come sempre
  const conOre = flotta.prioritaOperative([{ nome: "Dumper D1 — CAT 745", ore: 20, stato: "operativo" }], man, [], oggi);
  eq(conOre.length, 1, "col contatore noto l'avviso c'è");
  eq(conOre[0].badge, "tra 20 h", "e dice le ore vere");
});
test("⛔ Flotta: lo ZERO scritto apposta resta uno zero, non diventa «non lo so»", () => {
  const oggi = new Date(2026, 7, 1, 10, 0, 0);
  const man = [{ id: "n1", titolo: "Tagliando 250h", mezzo: "Pala P1", dataPrevista: null, orePreviste: 40 }];
  // una macchina NUOVA ha davvero zero ore: la correzione non deve mangiarsi
  // anche questo caso, che è un dato come un altro
  const p = flotta.prioritaOperative([{ nome: "Pala P1 — CAT 980", ore: 0, stato: "operativo" }], man, [], oggi);
  eq(p.length, 1, "il mezzo nuovo entra nel conto");
  eq(p[0].badge, "tra 40 h", "con le sue 40 ore di distanza dal tagliando");
  /* Senza letture del contatore il RITMO non si può misurare, quindi il
     tagliando resta fra i non stimabili anche col contatore noto: quello che
     conta è che il perché parli del ritmo, non delle ore del mezzo — sono due
     assenze diverse e devono restare distinguibili. */
  const t = flotta.tagliandiInScadenza(man, [{ nome: "Pala P1 — CAT 980", ore: 0 }], [], oggi);
  eq(t.daStimare[0].mancano, 40, "le ore mancanti si sanno: 40 − 0 è una sottrazione vera");
  ok(!/ore del contatore del mezzo|non risultano le ore/.test(t.daStimare[0].perche),
    "e il perché non accusa un contatore che c'è — «" + t.daStimare[0].perche + "»");
});
test("⛔ Flotta: previsioneGiorni non risponde «adesso» a chi non ha misurato niente", () => {
  /* `null <= 0` è **true** in JavaScript: la prima riga rispondeva 0, cioè
     «il tagliando è da fare adesso», a chi non sapeva quante ore mancassero.
     È la stessa forma di `avanzamentoLotto` che diceva «0%» di un lotto mai
     misurato: un numero tranquillo dove non è stato misurato niente. */
  eq(flotta.previsioneGiorni(null, 8), null, "quante ore mancano non si sa → non si stima");
  eq(flotta.previsioneGiorni(undefined, 8), null, "e nemmeno con undefined");
  eq(flotta.previsioneGiorni("", 8), null, "né con un campo vuoto");
  eq(flotta.previsioneGiorni("boh", 8), null, "né con qualcosa che non è un numero");
  eq(flotta.previsioneGiorni(0, 8), 0, "ma uno zero misurato resta «adesso»");
  eq(flotta.previsioneGiorni(-10, 8), 0, "e un tagliando già passato pure");
  eq(flotta.previsioneGiorni(80, 8), 10, "il conto di sempre non cambia");
  eq(flotta.previsioneGiorni(80, null), null, "e il ritmo ignoto resta non stimabile");
});
test("⛔ Flotta: le ore ignote arrivano ignote anche a chi le chiede due volte", () => {
  /* La stessa regola stava scritta in due funzioni, con lo stesso difetto in
     tutt'e due: adesso è una sola, e questa prova pretende che le due strade
     rispondano nello stesso modo — se un giorno divergono, si vede qui. */
  const oggi = new Date(2026, 7, 1, 10, 0, 0);
  const man = [{ id: "n1", titolo: "Tagliando", mezzo: "Pala P1", dataPrevista: null, orePreviste: 30 }];
  for (const ignoto of [null, undefined, "", "abc"]) {
    const mezzi = [{ nome: "Pala P1 — CAT 980", ore: ignoto, stato: "operativo" }];
    eq(flotta.prioritaOperative(mezzi, man, [], oggi), [],
      `ore=${JSON.stringify(ignoto)}: nessun avviso nel Quadro`);
    eq(flotta.tagliandiInScadenza(man, mezzi, [], oggi).nonStimabili, 1,
      `ore=${JSON.stringify(ignoto)}: dichiarato fra i non stimabili`);
  }
});

/* ══════════════════════════════════════════════════════════════════════
   ⛔ TERRA — L'ASSENZA DI UN DATO NON È UN DATO FAVOREVOLE, SUL CONTATORE
   CHE SI GUARDA PER PRIMO
   ----------------------------------------------------------------------
   Terra ne aveva già pagati due (il KPI dell'avanzamento verde con zero
   rilievi, il badge «senza collaudo» dove il collaudo non era dovuto). Il
   censimento del 01/08 ne ha misurati altri tre, e tutti e tre stavano sul
   percorso che finisce davanti a un ente:
    1. `vitaCava` rispondeva stato «ok» — pastiglia verde «Nei limiti», «0%
       consumato», «1.200.000 m³ residui» — su una cava dove non era stato
       registrato NESSUN rilievo e non era dichiarato nessun pregresso;
    2. `estrattoComplessivo` faceva di un pregresso mai dichiarato uno zero
       dichiarato, cioè la lettura più favorevole possibile, e il foglio da
       consegnare stampava «0 m³»;
    3. `kpiFrom` rispondeva «0%» di avanzamento senza nessun rilievo
       dell'anno: uno 0% si legge «non ancora cominciato» dove la verità è
       «nessuno ha misurato» (la stessa trappola di `avanzamentoLotto`).
   La riga di confine, in tutt'e tre: uno zero MISURATO resta uno zero, e si
   scrive. Quello che non si scrive è lo zero che nessuno ha misurato. */
{
  const oggiT = new Date("2026-08-01T10:00:00");
  const attoT = { volumeAutorizzatoM3: 100000, sogliaGuardiaPct: 80, anniRitmo: 3 };
  const scavo = (v, d) => ({ data: d || "2026-01-15", volumeM3: v, stato: "elaborato" });

  test("⛔ Terra: un pregresso mai dichiarato non è uno zero dichiarato", () => {
    /* la guardia sta PRIMA della conversione: `+null` fa zero e
       `Number.isFinite(0)` risponde true */
    for (const vuoto of [undefined, null, ""]) {
      const e = terra.estrattoComplessivo([], { estrattoPregressoM3: vuoto });
      eq(e.pregressoDichiarato, false, `pregresso ${JSON.stringify(vuoto)}: non dichiarato`);
      eq(e.pregresso, 0, "il numero resta zero: non c'è niente di meglio da sommare");
    }
    eq(terra.estrattoComplessivo([], {}).pregressoDichiarato, false, "campo assente: non dichiarato");
    eq(terra.estrattoComplessivo([], { estrattoPregressoM3: "boh" }).pregressoDichiarato, false,
       "un testo che non è un numero non è una dichiarazione");
    eq(terra.estrattoComplessivo([], { estrattoPregressoM3: 0 }).pregressoDichiarato, true,
       "⛔ lo ZERO scritto apposta dall'utente resta una dichiarazione");
    eq(terra.estrattoComplessivo([], { estrattoPregressoM3: 340000 }).pregressoDichiarato, true,
       "e un numero vero pure");
  });

  test("⛔ Terra: `rilieviScavo` conta solo i rilievi che reggono il numero", () => {
    const ril = [
      scavo(10000, "2026-01-10"),                                                  // conta
      { data: "2026-02-10", volumeM3: 5200, stato: "elaborato", provenienza: "cumulo" }, // no: già cavato
      { data: "2026-03-10", volumeM3: null, stato: "elaborato" },                  // no: senza volume
      { data: "2026-04-10", volumeM3: 900, stato: "pianificato" },                 // no: in calendario
      scavo(0, "2026-05-10"),                                                      // SÌ: zero misurato è una misura
    ];
    const e = terra.estrattoComplessivo(ril, {});
    eq(e.rilieviScavo, 2, "il volume misurato a zero conta, il cumulo e il pianificato no");
    eq(e.rilevato, 10000, "e la somma non cambia");
    eq(terra.estrattoComplessivo(ril, { dataRilascio: "2026-12-01" }).rilieviScavo, 0,
       "i rilievi precedenti al rilascio appartengono a un altro titolo");
  });

  test("⛔ Terra: la vita cava non risponde «nei limiti» a chi non ha misurato niente", () => {
    const v = terra.vitaCava(attoT, [], oggiT);
    eq(v.misurabile, false, "nessun rilievo e nessun pregresso: non c'è niente da misurare");
    ok(v.stato !== "ok", "e allora lo stato NON è quello che colora la pastiglia di verde");
    eq(v.stato, "senza-misure", "si dice quale delle due cose manca, invece di tacere");
    /* i numeri restano al loro posto: il conto va fatto lo stesso, è la
       PAGINA che non deve mostrarli come una misura */
    eq(v.pct, 0, "il conto resta zero");
    eq(v.residuo, 100000, "e il residuo resta il concesso intero");
  });

  test("⛔ Terra: che cosa fa tornare misurabile la vita cava", () => {
    eq(terra.vitaCava(attoT, [scavo(25000)], oggiT).stato, "ok",
       "un rilievo di scavo: misura, e sotto la soglia è «ok»");
    eq(terra.vitaCava({ ...attoT, estrattoPregressoM3: 25000 }, [], oggiT).stato, "ok",
       "oppure un pregresso dichiarato dall'utente");
    eq(terra.vitaCava(attoT, [scavo(0)], oggiT).stato, "ok",
       "⛔ e un rilievo che ha misurato ZERO è una misura: 0% è vero e si scrive");
    eq(terra.vitaCava(attoT, [{ data: "2026-01-15", volumeM3: 9000, stato: "elaborato", provenienza: "cumulo" }], oggiT).stato,
       "senza-misure",
       "una ripresa da cumulo NO: non è scavo sotto questo titolo, e infatti non lo consuma");
    eq(terra.vitaCava(attoT, [{ data: "2026-01-15", volumeM3: 9000, stato: "pianificato" }], oggiT).stato,
       "senza-misure", "e un rilievo in calendario nemmeno: non è ancora una misura");
    eq(terra.vitaCava({ ...attoT, estrattoPregressoM3: 85000 }, [], oggiT).stato, "warn",
       "e quando misura, le soglie funzionano come prima");
  });

  test("⛔ Terra: la vita cava dice se il pregresso è dichiarato", () => {
    /* il consumato calcolato senza il pregresso è un MINIMO, e la scheda lo
       deve poter dire: senza questa bandiera il residuo si legge come la
       cifra vera invece che come la più alta possibile */
    eq(terra.vitaCava(attoT, [scavo(25000)], oggiT).pregressoDichiarato, false, "campo mai compilato");
    eq(terra.vitaCava({ ...attoT, estrattoPregressoM3: 0 }, [scavo(25000)], oggiT).pregressoDichiarato, true,
       "zero scritto apposta: dichiarato");
  });

  test("⛔ Terra: l'avanzamento dell'anno è «—», non «0%», senza rilievi dell'anno", () => {
    const pianoT = [{ pianificatoAnnuoM3: 12000 }];
    eq(terra.kpiFrom([], [], pianoT, oggiT).avanzamento, null, "nessun rilievo: non è 0%, è ignoto");
    eq(terra.kpiFrom([], [scavo(9000, "2025-12-31")], pianoT, oggiT).avanzamento, null,
       "rilievi solo dell'anno prima: quest'anno non è stato misurato");
    eq(terra.kpiFrom([], [{ data: "2026-03-01", volumeM3: 9000, stato: "elaborato", provenienza: "cumulo" }], pianoT, oggiT).avanzamento,
       null, "solo cumuli: non consumano il piano annuo, quindi non lo misurano");
    eq(terra.kpiFrom([], [scavo(0, "2026-03-01")], pianoT, oggiT).avanzamento, 0,
       "⛔ ma un rilievo che ha misurato zero dà 0%, che è vero");
    eq(terra.kpiFrom([], [scavo(3000, "2026-03-01")], pianoT, oggiT).avanzamento, 25,
       "e il conto normale non cambia");
  });

  test("⛔ Terra: il riepilogo annuale non colora un consumo mai misurato", () => {
    const R = terra.riepilogoAnnuale([], 2026, attoT, oggiT);
    eq(R.misurabile, false, "nessun rilievo sotto il titolo e nessun pregresso");
    eq(R.pregressoDichiarato, false, "e lo dice anche separatamente, per il foglio da consegnare");
    eq(R.pctFineAnno, 0, "il conto resta zero: è la pagina a non doverlo colorare");
    const conMisura = terra.riepilogoAnnuale([scavo(25000)], 2026, attoT, oggiT);
    eq(conMisura.misurabile, true, "con un rilievo di scavo il cumulato è misurato");
    eq(conMisura.pctFineAnno, 25, "e la percentuale è quella");
    eq(terra.riepilogoAnnuale([], 2026, { ...attoT, estrattoPregressoM3: 40000 }, oggiT).misurabile, true,
       "oppure basta il pregresso dichiarato");
  });

  test("⛔ Terra: lo storico anno per anno porta con sé la bandiera", () => {
    /* la riga «0% del concesso» in verde su un anno senza nessun rilievo era
       la stessa buona notizia, in formato badge */
    const s = terra.serieAnnuale([], attoT, oggiT);
    eq(s.length, 1, "l'anno in corso c'è sempre: la denuncia si prepara comunque");
    eq(s[0].misurabile, false, "e dichiara che sotto non c'è nessuna misura");
    eq(terra.serieAnnuale([scavo(25000)], attoT, oggiT)[0].misurabile, true, "con un rilievo, sì");
  });
}

// ── Terra · volume per banco ────────────────────────────────────────────────
// «Quanto ho cavato dal banco 3 quest'anno». La catena c'era già tutta — il
// rilievo dichiara il fronte, il fronte dichiara il banco — e nessun conto la
// leggeva: `banco` era un campo scritto e mai usato.
{
  const AUT_B = { volumeAutorizzatoM3: 1200000, estrattoPregressoM3: 340000, dataRilascio: "2021-03-15" };
  const OGGI_B = new Date("2026-08-01T00:00:00");
  const rieB = (ril, anno = 2026) => terra.riepilogoAnnuale(ril, anno, AUT_B, OGGI_B);
  const RB = (ril, fro, anno = 2026) => terra.ripartizioneBanchi(rieB(ril, anno), fro);

  test("⛔ Terra: la conta dei rilievi per fronte è spezzata per provenienza", () => {
    /* senza `rilieviScavo` per fronte, chi legge la voce ha solo `scavo > 0` per
       distinguere «misurato zero» da «mai misurato» — cioè la scorciatoia che il
       principio dell'assenza vieta */
    const v = rieB(terra.DEMO.rilievi).fronti;
    const f1 = v.find((x) => x.fronteId === "f1"), nes = v.find((x) => x.fronteId === null);
    eq(f1.rilieviScavo, 2, "f1: due rilievi di scavo nel 2026");
    eq(f1.rilieviCumulo, 0, "e nessuna ripresa da cumulo");
    eq(nes.rilieviCumulo, 1, "la voce senza fronte è una ripresa da cumulo");
    eq(nes.rilieviScavo, 0, "e non ha nessun rilievo di scavo");
    eq(nes.rilievi, nes.rilieviScavo + nes.rilieviCumulo, "il totale resta la somma dei due");
  });

  test("⛔ Terra: il volume si ripartisce per banco leggendo rilievo → fronte → banco", () => {
    const B = RB(terra.DEMO.rilievi, terra.DEMO.fronti);
    eq(B.righe.map((r) => r.etichetta), ["banco 2", "banco 1", "banco 3"], "in ordine di scavo");
    eq(B.righe.map((r) => r.scavo), [40700, 38700, null], "i m³ del banco 2 e del banco 1 sono la somma dei loro fronti");
    eq(B.righe[0].fronti, ["Fronte Nord"], "e la riga dice quali fronti ci stanno sopra");
    eq(B.righe.map((r) => r.quotaPct), [51.3, 48.7, null], "la quota sullo scavo dell'anno");
    eq(B.misurabile, true, "almeno un banco è stato misurato");
    eq(B.totale, 79400, "il totale è lo scavo dell'anno, cumuli esclusi");
  });

  test("⛔ Terra: un banco senza rilievi dice «mai misurato», non «0 m³»", () => {
    /* è la trappola già pagata da `avanzamentoLotto`: uno zero tranquillo dove
       nessuno ha volato dice «fermo» a chi guarda, e non è quello che si sa */
    const B = RB(terra.DEMO.rilievi, terra.DEMO.fronti);
    const b3 = B.righe.find((r) => r.etichetta === "banco 3");
    eq(b3.scavo, null, "⛔ non 0: nessuno l'ha misurato");
    eq(b3.misurabile, false, "e la bandiera lo dichiara");
    eq(b3.quotaPct, null, "una quota su un volume mai misurato non esiste");
    ok(/non è stato misurato/.test(b3.motivo), "e la ragione è scritta: " + b3.motivo);
  });

  test("⛔ Terra: «misurato zero» e «mai misurato» restano due cose diverse", () => {
    /* il caso che `scavo > 0` avrebbe confuso: un rilievo che ha misurato zero
       è una misura, e vale zero; un banco senza rilievi non è una misura */
    const fro = [{ id: "f1", nome: "A", banco: "banco 1" }, { id: "f2", nome: "B", banco: "banco 2" }];
    const B = RB([{ id: "r1", data: "2026-03-04", stato: "elaborato", volumeM3: 0, fronteId: "f1" }], fro);
    const b1 = B.righe.find((r) => r.etichetta === "banco 1");
    const b2 = B.righe.find((r) => r.etichetta === "banco 2");
    eq(b1.scavo, 0, "il banco rilevato a zero vale zero");
    eq(b1.misurabile, true, "ed è una misura");
    eq(b2.scavo, null, "il banco senza rilievi resta ignoto");
    eq(b2.misurabile, false, "e non è una misura");
  });

  test("⛔ Terra: un banco con solo cumuli non ha scavato, e lo dice con la sua ragione", () => {
    const fro = [{ id: "f1", nome: "A", banco: "banco 1" }];
    const B = RB([{ id: "r1", data: "2026-03-04", stato: "elaborato", volumeM3: 5000,
                   fronteId: "f1", provenienza: "cumulo" }], fro);
    eq(B.righe[0].scavo, null, "una ripresa da cumulo non è scavo del banco");
    eq(B.righe[0].cumulo, 5000, "ma il cumulo resta scritto nella riga");
    ok(/solo riprese da cumulo/.test(B.righe[0].motivo), "e la ragione è quella giusta: " + B.righe[0].motivo);
    eq(B.misurabile, false, "nessun banco misurato in quest'anno");
    ok(/non è stato misurato/.test(B.motivo), "e il riepilogo lo dichiara");
  });

  test("⛔ Terra: i tre secchi che non sono un banco non spariscono", () => {
    const fro = [...terra.DEMO.fronti, { id: "f9", nome: "Fronte Ovest", banco: "", quota: 300 }];
    const ril = [...terra.DEMO.rilievi,
      { id: "r9", data: "2026-03-04", stato: "elaborato", volumeM3: 1000, fronteId: "f9" },
      { id: "r8", data: "2026-03-05", stato: "elaborato", volumeM3: 700, fronteId: "fX" }];
    const B = RB(ril, fro);
    eq(B.righe.length, 3, "il fronte senza banco non diventa una quarta riga finta");
    eq(B.nonDichiarato.scavo, 1000, "il suo scavo va nel secchio «banco non dichiarato»");
    eq(B.nonDichiarato.fronti, 1, "e si conta il fronte da compilare");
    eq(B.fuoriElenco.scavo, 700, "il rilievo su un fronte cancellato si conta a parte");
    eq(B.senzaFronte.cumulo, 5200, "e le riprese senza fronte restano fuori, dichiarate");
    const dentro = B.righe.reduce((t, r) => t + (+r.scavo || 0), 0);
    eq(dentro + B.nonDichiarato.scavo + B.fuoriElenco.scavo + B.senzaFronte.scavo, B.totale,
       "⛔ e la somma torna: niente si perde per strada");
  });

  test("⛔ Terra: «Banco 2» e «banco  2» sono lo stesso banco, e si dichiara", () => {
    const fro = [{ id: "f1", nome: "A", banco: "Banco 2" }, { id: "f2", nome: "B", banco: "banco  2" }];
    const B = RB(terra.DEMO.rilievi, fro);
    eq(B.righe.length, 1, "una riga sola");
    eq(B.righe[0].scavo, 79400, "e i volumi dei due fronti si sommano");
    eq(B.grafieDoppie, [["Banco 2", "banco 2"]], "le grafie trovate si dichiarano, non si nascondono");
    eq(terra.ripartizioneBanchi(rieB(terra.DEMO.rilievi), terra.DEMO.fronti).grafieDoppie, [],
       "e quando la grafia è una sola non si dichiara niente");
  });

  test("⛔ Terra: senza fronti (o senza banchi) la ripartizione non è zero, è impossibile", () => {
    const senzaFro = terra.ripartizioneBanchi(rieB(terra.DEMO.rilievi), []);
    eq(senzaFro.misurabile, false, "nessun fronte registrato");
    eq(senzaFro.righe, [], "nessuna riga inventata");
    ok(/Nessun fronte registrato/.test(senzaFro.motivo), "e la ragione lo dice: " + senzaFro.motivo);
    const senzaBanco = terra.ripartizioneBanchi(rieB(terra.DEMO.rilievi), [{ id: "f1", nome: "A", banco: "" }]);
    eq(senzaBanco.misurabile, false, "fronti che non dichiarano nessun banco");
    ok(/dichiara un banco/.test(senzaBanco.motivo), "e la ragione è un'altra: " + senzaBanco.motivo);
    eq(terra.ripartizioneBanchi(null, null).righe, [], "argomenti nulli: non un errore");
    eq(terra.ripartizioneBanchi(null, null).misurabile, false, "e nemmeno una buona notizia");
  });

  test("⛔ Terra: l'anno di solo cumulo non fa comparire nessun banco a zero", () => {
    /* stessa ragione di `baseOnereEscavazione`: nel 2024 la demo ha una sola
       ripresa da cumulo e nessun rilievo del fronte */
    const B = RB(terra.DEMO.rilievi, terra.DEMO.fronti, 2024);
    eq(B.righe.every((r) => r.scavo === null), true, "nessun banco scrive uno zero");
    eq(B.misurabile, false, "e il riepilogo dichiara che il 2024 non è misurato");
    ok(/2024/.test(B.motivo), "citando l'anno: " + B.motivo);
  });
}

// ── Terra · il banco DA SEMPRE ──────────────────────────────────────────────
// `ripartizioneBanchi` è annuale per costruzione. «Quale gradone si sto
// consumando» non si ferma al 1° gennaio, e sommando gli anni nasce il caso
// che il principio del fondatore rende insidioso: un anno NON MISURATO dentro
// una somma non vale zero, e il totale che ne esce non è un fatto.
{
  const AUT_S = { volumeAutorizzatoM3: 1200000, estrattoPregressoM3: 340000, dataRilascio: "2021-03-15" };
  const OGGI_S = new Date("2026-08-01T00:00:00");
  const FRO_S = [{ id: "f1", nome: "A", banco: "banco 1" }, { id: "f2", nome: "B", banco: "banco 2" }];
  const ril = (v, data, fronteId, provenienza) =>
    ({ id: data + fronteId + v, data, stato: "elaborato", volumeM3: v, fronteId, provenienza });
  const DS = (r, f = terra.DEMO.fronti, a = AUT_S) => terra.banchiDaSempre(r, f, a, OGGI_S);

  test("⛔ Terra: il banco da sempre somma gli anni con le funzioni che ci sono già", () => {
    const D = DS(terra.DEMO.rilievi);
    eq(D.anni, [2024, 2025, 2026], "la finestra va dal primo anno con volumi a oggi");
    const b2 = D.righe.find((r) => r.etichetta === "banco 2");
    eq(b2.scavo, 62700, "banco 2 = 19.400 + 21.300 (2026) + 22.000 (2025)");
    eq(b2.anniMisurati, [2025, 2026], "e dice in quali anni è stato misurato");
    eq(D.righe.find((r) => r.etichetta === "banco 1").scavo, 38700, "banco 1 = 18.600 + 20.100, tutti nel 2026");
    eq(D.totale, 101400, "il totale è lo scavo misurato di tutta la finestra, cumuli esclusi");
    eq(D.righe.map((r) => r.etichetta), ["banco 2", "banco 1", "banco 3"],
       "in ordine di scavo, e i mai misurati in fondo");
  });

  test("⛔ Terra: un anno non misurato dentro la somma non vale zero — è un «almeno»", () => {
    /* la domanda «tetto o quantità parziale» ha una risposta sola: il volume di
       un anno cieco è ignoto ma non può essere NEGATIVO, quindi la somma dei
       soli anni misurati è un PAVIMENTO. Mai un tetto. */
    const D = DS(terra.DEMO.rilievi);
    const b2 = D.righe.find((r) => r.etichetta === "banco 2");
    eq(b2.limite, "almeno", "⛔ nel 2024 nessuno ha rilevato questo banco: 62.700 è un pavimento");
    eq(b2.anniCiechi, [2024], "e l'anno cieco è dichiarato, non nascosto");
    eq(b2.misurabile, true, "resta una misura: è parziale, non assente");
    ok(/questo o di più, mai di meno/.test(b2.motivo), "e la ragione dice il verso: " + b2.motivo);
    eq(D.limite, "almeno", "e la testata porta la stessa bandiera");
    // finestra piena: un anno solo, tutti i banchi misurati, pregresso dichiarato
    const pieno = DS([ril(100, "2026-05-01", "f1"), ril(300, "2026-06-01", "f2")], FRO_S,
      { estrattoPregressoM3: 0 });
    eq(pieno.limite, "", "quando tutti gli anni sono misurati il totale è una misura");
    eq(pieno.righe.map((r) => r.limite), ["", ""], "riga per riga");
    eq(pieno.completo, true, "e il quadro si dichiara completo");
  });

  test("⛔ Terra: un anno SENZA RILIEVI non sparisce dalla finestra, è cieco", () => {
    /* il difetto che il prototipo ha preso in flagrante: `anniConVolumi` dà gli
       anni CHE HANNO un rilievo, quindi 2022 e 2026 davano «due anni su due,
       quadro completo» mentre 2023, 2024 e 2025 non li aveva guardati nessuno */
    const D = DS([ril(500, "2022-05-01", "f1"), ril(700, "2026-05-01", "f1")], FRO_S,
      { estrattoPregressoM3: 0 });
    eq(D.anni, [2022, 2023, 2024, 2025, 2026], "⛔ la finestra è continua, non l'elenco degli anni con dati");
    const b1 = D.righe.find((r) => r.etichetta === "banco 1");
    eq(b1.anniCiechi, [2023, 2024, 2025], "i tre anni di mezzo sono ciechi");
    eq(b1.scavo, 1200, "il totale resta la somma dei due anni misurati");
    eq(b1.limite, "almeno", "ma è un pavimento");
    eq(D.completo, false, "e il quadro non è completo");
  });

  test("⛔ Terra: «misurato zero» e «mai misurato» restano diversi anche sommando", () => {
    const D = DS([ril(0, "2025-05-01", "f1"), ril(0, "2026-05-01", "f1")], FRO_S,
      { estrattoPregressoM3: 0 });
    const b1 = D.righe.find((r) => r.etichetta === "banco 1");
    const b2 = D.righe.find((r) => r.etichetta === "banco 2");
    eq(b1.scavo, 0, "due anni rilevati a zero fanno zero");
    eq(b1.misurabile, true, "ed è una misura");
    eq(b1.limite, "", "senza anni ciechi: è un fatto, non un pavimento");
    eq(b2.scavo, null, "⛔ il banco che nessuno ha mai rilevato resta ignoto");
    eq(b2.misurabile, false, "e non è una misura");
    ok(/non l'ha misurato nessuno/.test(b2.motivo), "con la sua ragione: " + b2.motivo);
    eq(terra.banchiDaSempre([], FRO_S, null, OGGI_S).misurabile, false,
       "una cava senza nessun rilievo non ha banchi a zero");
  });

  test("⛔ Terra: la quota % di un banco con anni ciechi non esiste", () => {
    /* il suo scavo è un pavimento, ma il denominatore contiene gli anni in cui
       sono stati misurati ALTRI banchi: il rapporto non è né un tetto né un
       pavimento, non è niente */
    const D = DS(terra.DEMO.rilievi);
    eq(D.righe.map((r) => r.quotaPct), [null, null, null], "nella demo nessun banco ha la storia intera");
    const pieno = DS([ril(100, "2026-05-01", "f1"), ril(300, "2026-06-01", "f2")], FRO_S,
      { estrattoPregressoM3: 0 });
    eq(pieno.righe.map((r) => [r.etichetta, r.quotaPct]), [["banco 2", 75], ["banco 1", 25]],
       "con la finestra piena la quota si calcola");
  });

  test("⛔ Terra: quello che nessun banco può reclamare si dichiara", () => {
    const D = DS(terra.DEMO.rilievi);
    eq(D.pregresso, 340000, "il già estratto prima di Terra è per CAVA, non per banco");
    eq(D.completo, false, "quindi il quadro non copre tutto lo scavo");
    eq(D.perche.length, 2, "e le ragioni sono elencate, non lasciate dedurre");
    ok(D.perche.some((p) => /non l'ha rilevato nessuno/.test(p)), "gli anni ciechi");
    ok(D.perche.some((p) => /nessun banco può reclamare/.test(p)), "e il pregresso");
    ok(D.perche.every((p) => !/\d{5}/.test(p)),
       "⛔ e nessuna frase porta un numero grosso: i separatori delle migliaia sono della pagina");
    // pregresso NON dichiarato: peggio, perché non si sa nemmeno se ci sia
    const senza = DS(terra.DEMO.rilievi, terra.DEMO.fronti, { volumeAutorizzatoM3: 1200000 });
    eq(senza.pregressoDichiarato, false, "senza pregresso dichiarato");
    ok(senza.perche.some((p) => /non è dichiarato/.test(p)), "la ragione cambia: " + senza.perche.join(" · "));
  });

  test("⛔ Terra: da sempre, i tre secchi si sommano e la somma torna", () => {
    const fro = [...terra.DEMO.fronti, { id: "f9", nome: "Ovest", banco: "" }];
    const D = DS([...terra.DEMO.rilievi, ril(1000, "2025-03-04", "f9"), ril(700, "2024-03-05", "fX")], fro);
    eq(D.nonDichiarato.scavo, 1000, "lo scavo di un fronte senza banco resta nel suo secchio");
    eq(D.nonDichiarato.fronti, 1, "⛔ e il conto dei fronti da compilare è di OGGI: non si somma per anno");
    eq(D.fuoriElenco.scavo, 700, "il rilievo su un fronte cancellato si conta a parte");
    eq(D.senzaFronte.cumulo, 8300, "le riprese senza fronte di tutti gli anni: 5.200 + 3.100");
    const dentro = D.righe.reduce((t, r) => t + (+r.scavo || 0), 0);
    eq(dentro + D.nonDichiarato.scavo + D.fuoriElenco.scavo + D.senzaFronte.scavo, D.totale,
       "⛔ e la somma torna su tutta la finestra: niente si perde per strada");
  });

  test("⛔ Terra: da sempre, le grafie e i due casi in cui non si può ripartire", () => {
    const D = DS(terra.DEMO.rilievi, [{ id: "f1", nome: "A", banco: "Banco 2" },
                                      { id: "f2", nome: "B", banco: "banco  2" }]);
    eq(D.righe.length, 1, "«Banco 2» e «banco  2» sono lo stesso banco");
    eq(D.righe[0].scavo, 101400, "e i volumi di tutti gli anni si sommano");
    eq(D.grafieDoppie, [["Banco 2", "banco 2"]], "le grafie si dichiarano");
    const senzaFro = terra.banchiDaSempre(terra.DEMO.rilievi, [], AUT_S, OGGI_S);
    eq(senzaFro.righe, [], "senza fronti nessuna riga inventata");
    ok(/Nessun fronte registrato/.test(senzaFro.motivo), "col motivo di sempre: " + senzaFro.motivo);
    const senzaBanco = terra.banchiDaSempre(terra.DEMO.rilievi, [{ id: "f1", nome: "A", banco: "" }], AUT_S, OGGI_S);
    ok(/dichiara un banco/.test(senzaBanco.motivo), "e l'altro caso è un altro motivo: " + senzaBanco.motivo);
    eq(terra.banchiDaSempre(null, null, null, OGGI_S).misurabile, false,
       "argomenti nulli: non un errore, e nemmeno una buona notizia");
  });
}

/* ══ SENTINELLA · LA TARATURA DELLO STRUMENTO ══
   Il report va all'ente e dice «conforme» sulla base di numeri scritti da uno
   strumento. Se quello strumento non era tarato IL GIORNO DELLA MISURA, il
   numero non è riferibile — e fino a ieri il prodotto non sapeva nemmeno la
   domanda. Qui si difende che la risposta non sia mai tranquilla per
   default. */
{
  const OGGI_T = new Date("2026-08-01T09:00:00");
  const cert = (data, scadenza) => ({ data, scadenza, ente: "Centro LAT n. 118", certificato: "C-1" });
  const stato = (tarature, data) => sentinella.coperturaTaratura(tarature, data).stato;

  test("Sentinella: una lettura dentro la validità del certificato è coperta", () => {
    const uno = [cert("2026-01-15", "2027-01-14")];
    eq(stato(uno, "2026-06-01"), "coperta", "in mezzo");
    eq(stato(uno, "2026-01-15"), "coperta", "il primo giorno è compreso");
    eq(stato(uno, "2027-01-14"), "coperta", "e anche l'ultimo");
    eq(sentinella.coperturaTaratura(uno, "2026-06-01").certificato.certificato, "C-1",
       "e il certificato che copre torna a chi lo deve scrivere nel documento");
  });

  test("⛔ Sentinella: nessuna taratura registrata NON vuol dire taratura a posto", () => {
    eq(stato([], "2026-06-01"), "non-dichiarata", "elenco vuoto");
    eq(stato(undefined, "2026-06-01"), "non-dichiarata", "campo mai creato: uguale");
    eq(sentinella.taratureDelReport([{ nome: "A", m: { tarature: [] }, letture: [{ data: "2026-06-01" }] }], OGGI_T).stato,
       "non-dichiarata", "e il report intero non risponde «coperte»");
    eq(sentinella.DICHIARAZIONI_TARATURA["non-dichiarata"].cls, "warn",
       "il colore non è quello tranquillo");
  });

  test("⛔ Sentinella: «non coperta» si divide in due, e non si dicono allo stesso modo", () => {
    const uno = [cert("2026-01-15", "2027-01-14")];
    eq(stato(uno, "2027-01-15"), "scoperta", "il giorno dopo la scadenza è un problema vero");
    eq(stato(uno, "2025-12-31"), "prima-dello-storico",
       "prima della prima taratura registrata: lo strumento poteva essere tarato, qui non risulta");
    ok(/non risulta/.test(sentinella.coperturaTaratura(uno, "2025-12-31").perche),
       "e il perché lo dice senza accusare chi compila");
  });

  test("Sentinella: il buco fra due tarature è scoperto, e l'ordine in ingresso non conta", () => {
    const due = [cert("2024-03-01", "2025-02-28"), cert("2025-06-01", "2026-05-31")];
    eq(stato(due, "2025-04-01"), "scoperta", "in mezzo ai due certificati");
    eq(stato(due, "2025-07-01"), "coperta", "dentro il secondo");
    eq(stato([due[1], due[0]], "2025-04-01"), "scoperta", "elenco disordinato: stessa risposta");
  });

  test("⛔ Sentinella: una data che non esiste non allunga nessuna copertura", () => {
    /* `Date.parse` il 30 febbraio non lo rifiuta: lo fa scivolare al 2 marzo.
       Una taratura scritta male coprirebbe due giorni in più in silenzio. */
    eq(stato([cert("2026-02-30", "2027-02-28")], "2026-06-01"), "non-dichiarata", "taratura col 30 febbraio");
    eq(stato([cert("2026-01-01", "2026-13-45")], "2026-06-01"), "non-dichiarata", "scadenza inesistente");
    eq(stato([cert("2026-06-01", "2026-01-01")], "2026-06-15"), "non-dichiarata", "intervallo alla rovescia");
    eq(sentinella.coperturaTaratura([cert("2026-02-30", "2027-01-01")], "2026-06-01").scartate, 1,
       "e quante ne ha scartate si vede, invece di sparire");
    eq(stato([cert("2026-02-30", "2027-01-01"), cert("2026-01-15", "2027-01-14")], "2026-06-01"), "coperta",
       "una rotta e una buona: vale la buona");
    eq(stato([cert("2026-01-15", "2027-01-14")], ""), "non-dichiarata",
       "e una lettura senza data non si può attribuire a nessuna taratura");
  });

  test("Sentinella: lo stato di oggi lo dice la funzione condivisa, non una quarta copia", () => {
    const s = (tar) => sentinella.statoTaraturaStrumento({ tarature: tar }, OGGI_T).stato;
    eq(s([]), "non-dichiarata", "il caso che `statoScadenzaHSE` non può conoscere");
    eq(s([cert("2026-01-01", "2027-01-01")]), "regolare", "valida a lungo");
    eq(s([cert("2025-08-11", "2026-08-11")]), "in-scadenza", "scade fra dieci giorni");
    eq(s([cert("2024-01-01", "2025-01-01")]), "scaduta", "già scaduta");
    eq(s([cert("2026-01-01", "2027-01-01"), cert("2024-01-01", "2025-01-01")]), "regolare",
       "vale l'ULTIMA taratura, non la prima dell'elenco");
    for (const sc of ["2027-01-01", "2026-08-11", "2025-01-01"])
      eq(sentinella.statoTaraturaStrumento({ tarature: [cert("2024-01-01", sc)] }, OGGI_T).stato,
         ponti.statoScadenzaHSE(sc, OGGI_T),
         `la risposta è la stessa di ponti.statoScadenzaHSE per ${sc}`);
    ok(Object.keys(sentinella.STATI_TARATURA).length === 5,
       "e la mappa dei badge copre tutti gli stati che la funzione sa dire (regola 18)");
    for (const k of ["regolare", "in-scadenza", "scaduta", "senza data", "non-dichiarata"])
      ok(sentinella.STATI_TARATURA[k], `manca il badge per «${k}»: la pagina morirebbe al disegno`);
  });

  test("Sentinella: il riepilogo delle tarature del report, caso per caso", () => {
    const p = (nome, tarature, date) => ({ nome, m: { nome, tarature }, letture: date.map(d => ({ data: d })) });
    const buono = [cert("2026-01-01", "2027-01-01")];
    eq(sentinella.taratureDelReport([], OGGI_T).stato, "senza-letture", "niente da verificare");
    eq(sentinella.taratureDelReport([p("A", buono, ["2026-06-01"])], OGGI_T).stato, "coperte", "tutte coperte");
    eq(sentinella.taratureDelReport([p("A", [cert("2026-01-01", "2026-05-01")], ["2026-06-01"])], OGGI_T).stato,
       "scoperte", "una fuori copertura");
    eq(sentinella.taratureDelReport([p("A", buono, ["2026-06-01"]), p("B", [], ["2026-06-01"])], OGGI_T).stato,
       "parziale", "metà coperte e metà non note");
    eq(sentinella.taratureDelReport([p("A", buono, ["2026-06-01"]), p("B", [cert("2020-01-01", "2020-02-01")], ["2026-06-01"])], OGGI_T).stato,
       "scoperte", "⛔ una sola scoperta batte tutte le coperte: è quella che va detta");
    eq(sentinella.taratureDelReport([p("A", buono, ["2026-06-01", "2025-01-01"])], OGGI_T).perPunto[0],
       { nome: "A", coperte: 1, scoperte: 0, nonNote: 1, oggi: "regolare" },
       "e il conto punto per punto");
    for (const k of ["coperte", "parziale", "non-dichiarata", "scoperte", "senza-letture"])
      ok(sentinella.DICHIARAZIONI_TARATURA[k], `manca la frase per «${k}»`);
  });

  test("⛔ Sentinella: la taratura sta ACCANTO all'esito, non dentro", () => {
    /* Sono due domande diverse — «le misure hanno superato il limite?» e «di
       chi erano quelle misure?». Mescolarle vorrebbe dire cambiare un
       giudizio di conformità per un dato amministrativo. */
    const mon = [{ id: "x", nome: "P", soglia: 10, unita: "mm/s",
                   letture: [{ data: "2026-06-10", valore: 2 }] }];
    const senza = sentinella.reportConformita({ monitoraggi: mon, dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" });
    const con = sentinella.reportConformita({
      monitoraggi: [{ ...mon[0], tarature: [cert("2026-01-01", "2027-01-01")] }],
      dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" });
    eq([senza.esito, con.esito], ["conforme", "conforme"], "l'esito sulle soglie non si muove");
    eq(senza.tarature.stato, "non-dichiarata", "ma senza certificati il report lo dichiara");
    eq(con.tarature.stato, "coperte", "e con il certificato pure");
  });

  test("Sentinella: la dimostrazione contiene il caso che questa difesa serve a raccontare", () => {
    /* `run-demo` pretende dati integri, non dati SENZA STATI: una fattura
       senza scadenza e uno strumento con un buco di taratura sono cose che il
       prodotto sa dire, e toglierle dalla demo vorrebbe dire non mostrarle. */
    const r = sentinella.reportConformita({ monitoraggi: sentinella.DEMO.monitoraggi, ricettori: sentinella.DEMO.ricettori,
                                            dal: "2026-06-01", al: "2026-07-31", oggi: "2026-08-01" });
    eq(r.tarature.stato, "scoperte", "c'è una lettura nel buco fra le due tarature di V2");
    eq(r.tarature.scoperte, 1, "una sola, quella del 06/07");
    ok(r.tarature.nonNote > 0, "e ci sono punti senza nessuna taratura registrata, che è l'altro caso vero");
    ok(r.tarature.coperte > 0, "insieme a letture regolarmente coperte");
    eq(r.tarature.coperte + r.tarature.scoperte + r.tarature.nonNote, r.nLetture,
       "⛔ e i tre conti coprono TUTTE le letture: nessuna sparisce per strada");
  });
}

// ── Sentinella · import delle tarature ───────────────────────────────
/* I certificati arrivano dal centro di taratura già in elenco, e una cava con
   otto strumenti li ricopiava a mano otto volte l'anno. Qui si difendono due
   cose: che dal file non entri niente di inventato, e che quello che NON entra
   si veda — un import che scarta metà del file senza dirlo è peggio di un
   import che fallisce, perché chi lo lancia crede di aver caricato tutto. */
{
  const OGGI_I = new Date("2026-08-01T09:00:00");
  const MONI = [
    { id: "v1", nome: "Vibrazioni V1 — abitato Sud", tarature: [{ data: "2025-01-01", scadenza: "2026-01-01" }],
      letture: [{ data: "2026-06-01", valore: 2 }, { data: "2026-03-01", valore: 3 }] },
    { id: "p1", nome: "Polveri PM10 — confine Est", tarature: [], letture: [] },
  ];
  const leggi = (t, mon = MONI) => sentinella.abbinaTarature(sentinella.parseTaratureCsv(t), mon);
  const una = (t, mon = MONI) => leggi(t, mon).voci[0];

  test("Sentinella · import tarature: una riga buona trova il suo strumento", () => {
    const r = leggi("strumento;data;scadenza;centro;certificato;nota\n"
      + "Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14;Centro LAT n. 118;LAT-2026/77;terna");
    contiene(r.voci[0], { riga: 2, data: "2026-01-15", scadenza: "2027-01-14",
      ente: "Centro LAT n. 118", certificato: "LAT-2026/77", nota: "terna",
      puntoId: "v1", ok: true, motivo: "" }, "riga letta e abbinata");
    contiene(r.riepilogo, { letti: 1, pronte: 1, scartate: 0 }, "e il riepilogo la conta");
    eq(una("polveri pm10;12/04/2026;12/04/2027").puntoId, "p1",
       "il nome corto e le maiuscole non contano: chi scrive a mano scrive «polveri pm10»");
    eq(una("Vibrazioni V1 — abitato Sud;12/04/2026;12/04/2027").data, "2026-04-12",
       "e la data all'italiana la legge, perché il file lo scrive un ufficio italiano");
  });

  test("⛔ Sentinella · import tarature: nessuna riga sparisce in silenzio", () => {
    const r = leggi([
      "strumento;data;scadenza;centro;certificato;nota",
      "Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14;;;",
      ";2026-01-15;2027-01-14;;;",
      "Vibrazioni V1 — abitato Sud;;2027-01-14;;;",
      "Vibrazioni V1 — abitato Sud;non lo so;2027-01-14;;;",
      "Vibrazioni V1 — abitato Sud;2026-01-15;;;;",
    ].join("\n"));
    eq(r.riepilogo.letti, 5, "cinque righe con dei dati dentro");
    eq(r.riepilogo.pronte + r.riepilogo.scartate, r.riepilogo.letti,
       "⛔ pronte + scartate torna sempre uguale a lette: è così che si vede se il file è entrato tutto");
    eq(r.voci.map(v => v.motivo), ["", "manca il nome dello strumento", "manca la data della taratura",
       "la data della taratura non è una data", "manca la scadenza"],
       "e ogni scarto porta il suo motivo scritto in italiano");
    eq(r.voci.map(v => v.riga), [2, 3, 4, 5, 6],
       "⛔ col numero di riga VERO del file: chi deve correggerlo apre il foglio a quella riga");
    ok(r.riepilogo.motivi.every(x => x.n === 1) && r.riepilogo.motivi.length === 4,
       "quanti scarti per motivo, contati: " + r.riepilogo.motivi.map(x => x.n + " " + x.motivo).join(", "));
  });

  test("⛔ Sentinella · import tarature: il 30 febbraio non entra, e non scivola al 2 marzo", () => {
    /* `Date.parse("2026-02-30")` non è NaN: JavaScript lo fa scorrere al 2
       marzo. Una copertura allungata di due giorni farebbe risultare
       «coperte» letture che non lo sono — l'esatto contrario di T2b. */
    eq(una("Vibrazioni V1 — abitato Sud;2026-02-30;2027-01-01").motivo,
       "la data della taratura non è una data", "il 30 febbraio è scartato");
    eq(una("Vibrazioni V1 — abitato Sud;2026-01-01;2026-13-45").motivo,
       "la scadenza non è una data", "e il 45 del tredicesimo mese pure");
    eq(una("Vibrazioni V1 — abitato Sud;2026-02-30;2027-01-01").data, "",
       "⛔ e non resta nessuna data scivolata: il campo è vuoto, non «2026-03-02»");
    for (const v of leggi("Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14").voci)
      ok(shell.dataISOEsiste(v.data) && shell.dataISOEsiste(v.scadenza),
         "quello che entra è sempre una data che esiste, così `coperturaTaratura` la ritrova buona");
  });

  /* ══════════════════════════════════════════════════════════════════
     T2d · LA CATENA DI CUSTODIA DEL DATO DI MISURA (Sentinella)
     «Da dove viene questo numero, e chi può dire di averlo visto entrare?»
     Il report di Sentinella va a un ente: un valore di PPV o di dB vale
     quanto la sua provenienza, e prima di questa unità il documento
     affiancava numeri usciti dal file dello strumento e numeri digitati a
     mano senza distinguerli.
     La prova che conta più di tutte è la prima: **l'assenza non ripiega su
     "a mano"**. È il principio del fondatore, ed è nato in questa app.
     ══════════════════════════════════════════════════════════════════ */
  const lImp = (file, quando) => ({ data: "2026-06-01", ora: "10:00", valore: 3.2,
    origine: { da: "import", file, quando: quando || "2026-07-01T08:44:00" } });
  const lMano = (quando) => ({ data: "2026-06-02", ora: "11:00", valore: 4.4,
    origine: { da: "manuale", quando: quando || "2026-06-02T17:10:00" } });

  test("⛔ Sentinella · custodia: una provenienza che non c'è NON è «a mano» — è non dichiarata", () => {
    /* ⛔ IL CUORE DELL'UNITÀ. Il ripiego comodo sarebbe contare fra le misure
       inserite a mano quelle di cui non si sa niente: sono le più vecchie, ed
       è pure probabile. Sarebbe un'invenzione scritta in un documento verso
       un ente. Il ripiego opposto — contarle fra le strumentali — è peggio. */
    eq(sentinella.provenienzaMisura({ data: "2026-06-01", valore: 3 }).da, sentinella.FONTE_IGNOTA,
       "una lettura senza `origine` non dichiara la sua provenienza");
    eq(sentinella.provenienzaMisura({ data: "2026-06-01", valore: 3 }).noto, false,
       "e la bandiera lo dice: `noto` è false");
    eq(sentinella.provenienzaMisura({ origine: { da: "sismografo" } }).da, sentinella.FONTE_IGNOTA,
       "⛔ e una parola fuori dal vocabolario non diventa una fonte: ricade su «non dichiarata», non su «manuale»");
    eq(sentinella.provenienzaMisura({ origine: "import" }).da, sentinella.FONTE_IGNOTA,
       "e nemmeno una stringa al posto dell'oggetto");
    eq(sentinella.provenienzaMisura(null).da, sentinella.FONTE_IGNOTA, "né una lettura che non c'è");
    eq(sentinella.provenienzaMisura(lImp("V2.csv")).da, sentinella.FONTE_IMPORT, "il file dello strumento si riconosce");
    eq(sentinella.provenienzaMisura(lMano()).da, sentinella.FONTE_MANO, "e la digitazione a mano pure");
    ok(sentinella.provenienzaMisura(lImp("V2.csv")).noto && sentinella.provenienzaMisura(lMano()).noto,
       "tutt'e due sono provenienze NOTE: il terzo stato è solo per ciò che non si sa");
  });

  test("⛔ Sentinella · custodia: la frase del documento non fa sembrare tracciato ciò che non lo è", () => {
    /* Stessa ragione di `descriviOrigine` di Terra: il verbale va a un ente,
       e una riga che tace lascia credere che il numero sia verificabile. */
    const punto = { nome: "Vibrazioni V2 — confine Nord" };
    const dImp = sentinella.descriviProvenienza(lImp("V2_giugno.csv"), punto);
    ok(dImp.includes("V2_giugno.csv"), "il file c'è: è quello che permette di risalire al documento");
    ok(dImp.includes("01/07/2026 alle 08:44"), "e il momento dell'import, scritto come lo legge una persona");
    ok(dImp.includes("Vibrazioni V2 — confine Nord"), "e lo strumento a cui la misura è attribuita");
    const dIgn = sentinella.descriviProvenienza({ data: "2026-06-01", valore: 3 }, punto);
    ok(/^Provenienza non dichiarata/.test(dIgn),
       "⛔ la frase di una misura senza custodia COMINCIA dichiarandolo, non lo nasconde in coda");
    ok(!/^Misura inserita a mano/.test(dIgn) && !/^Misura importata/.test(dIgn),
       "⛔ e non afferma nessuna delle due strade");
    ok(dIgn.includes("Vibrazioni V2 — confine Nord"),
       "ma lo strumento lo dice lo stesso: quello si sa, ed è l'unica cosa che si sa");
    ok(/inserita a mano/.test(sentinella.descriviProvenienza(lMano(), punto)),
       "la misura battuta a mano lo dichiara");
    ok(/non proviene da un file/.test(sentinella.descriviProvenienza(lMano(), punto)),
       "e dice a chi legge che cosa comporta, invece di lasciarglielo dedurre");
    ok(/testo incollato/.test(sentinella.descriviProvenienza(lImp(""), punto)),
       "⛔ un import senza nome del file NON inventa un file: dice che era un testo incollato");
    ok(sentinella.descriviProvenienza(lImp("V2.csv"), null).includes("al punto di misura"),
       "e senza il punto la frase regge lo stesso");
  });

  test("⛔ Sentinella · custodia: una misura corretta non può sembrare quella originale", () => {
    const l0 = lImp("V2.csv");
    const l1 = sentinella.correggiLettura(l0, 4.1, "2026-08-01T10:00:00");
    eq(l1.valore, 4.1, "il valore nuovo entra");
    eq(sentinella.provenienzaMisura(l1).corretta.prima, 3.2,
       "⛔ e il numero registrato in ORIGINE resta scritto: è quello che un ispettore può chiedere");
    eq(sentinella.provenienzaMisura(l1).corretta.quando, "2026-08-01T10:00:00", "col momento della correzione");
    eq(sentinella.provenienzaMisura(l1).da, sentinella.FONTE_IMPORT,
       "la strada d'ingresso non cambia: la misura viene ancora da quel file, è il valore a essere stato ritoccato");
    eq(sentinella.provenienzaMisura(l1).file, "V2.csv", "e il file resta citabile");
    const l2 = sentinella.correggiLettura(l1, 4.5, "2026-08-02T10:00:00");
    eq(sentinella.provenienzaMisura(l2).prima, undefined, "il valore d'origine non finisce alla radice");
    eq(sentinella.provenienzaMisura(l2).corretta.prima, 3.2,
       "⛔ correggendo due volte resta il PRIMO valore, non il penultimo: è quello che dice «questo non è il numero che è entrato»");
    eq(sentinella.provenienzaMisura(l2).corretta.quando, "2026-08-02T10:00:00", "e l'ultima correzione è quella recente");
    eq(sentinella.provenienzaMisura(sentinella.correggiLettura(l0, 3.2)).corretta, null,
       "⛔ riscrivere lo STESSO numero non produce una correzione finta: non è successo niente");
    eq(sentinella.correggiLettura(l0, "quattro"), null, "un valore illeggibile non si registra");
    eq(sentinella.correggiLettura(l0, -1), null, "e nemmeno uno negativo: uno strumento non misura meno di zero");
    eq(sentinella.correggiLettura(null, 4), null, "né si corregge una lettura che non c'è");
    eq(sentinella.correggiLettura(l0, 0).valore, 0, "zero invece è una misura valida, e si può correggere a zero");
    /* ⛔ CORREGGERE UNA MISURA DI PROVENIENZA IGNOTA NON LE DÀ UNA
       PROVENIENZA. Il ripiego sarebbe marcarla «manuale» perché qualcuno l'ha
       toccata: sarebbe dire che il valore è entrato a mano, che non si sa. */
    const lIgn = sentinella.correggiLettura({ data: "2026-06-01", valore: 2 }, 5, "2026-08-01T10:00:00");
    eq(sentinella.provenienzaMisura(lIgn).da, sentinella.FONTE_IGNOTA,
       "⛔ resta non dichiarata: la correzione non è la strada d'ingresso");
    eq(sentinella.provenienzaMisura(lIgn).corretta.prima, 2, "ma la correzione sì, col valore d'origine");
    /* ⛔ E UNA CORREZIONE SU UN VALORE ILLEGGIBILE RESTA UNA CORREZIONE:
       pretendere che `prima` fosse un numero l'avrebbe fatta sparire proprio
       nel caso più sospetto. */
    const lRotta = sentinella.correggiLettura({ data: "2026-06-01", valore: "boh" }, 5, "2026-08-01T10:00:00");
    eq(sentinella.provenienzaMisura(lRotta).corretta.prima, null, "`prima` vale null, non zero");
    ok(sentinella.provenienzaMisura(lRotta).corretta !== null,
       "⛔ ma la correzione si vede lo stesso: sparire sarebbe stato il difetto");
    ok(/non è leggibile/.test(sentinella.descriviProvenienza(lRotta, { nome: "V2" })),
       "e la frase lo dice invece di scrivere «era 0»");
    ok(/CORRETTO/.test(sentinella.descriviProvenienza(l1, { nome: "V2" }))
       && /4,2|3,2/.test(sentinella.descriviProvenienza(l1, { nome: "V2" })),
       "la frase del documento porta la correzione e il numero d'origine, scritto all'italiana");
  });

  test("⛔ Sentinella · custodia: la composizione del report tiene i tre conti separati", () => {
    const punti = (n) => ({ letture: Array.from({ length: n }, () => ({ data: "2026-06-01", valore: 1 })) });
    const conOrig = (n, o) => ({ letture: Array.from({ length: n }, () => ({ data: "2026-06-01", valore: 1, origine: { ...o } })) });
    const c = sentinella.composizioneProvenienza([conOrig(3, { da: "import", file: "a.csv" }), conOrig(2, { da: "manuale" }), punti(1)]);
    eq([c.importate, c.aMano, c.nonDichiarate, c.n], [3, 2, 1, 6], "i tre conti, e il totale");
    eq(c.fuori, 3, "«non strumentali» sono le a mano PIÙ le non dichiarate: le seconde non si regalano alle prime");
    eq(sentinella.composizioneProvenienza([punti(5)]).aMano, 0,
       "⛔ cinque letture senza provenienza NON diventano cinque letture a mano");
    eq(sentinella.composizioneProvenienza([punti(5)]).importate, 0,
       "⛔ e nemmeno cinque letture strumentali");
    eq(sentinella.composizioneProvenienza([punti(5)]).stato, "non-dichiarata", "lo stato lo dice");
    eq(sentinella.composizioneProvenienza([]).stato, "senza-letture", "senza misure non c'è composizione");
    eq(sentinella.composizioneProvenienza([]).quota, null,
       "⛔ e la quota è `null`, non 0: «zero per cento a mano» sarebbe la buona notizia mai misurata");
    eq(sentinella.composizioneProvenienza([conOrig(4, { da: "import" })]).stato, "tracciata", "tutte da file");
    eq(sentinella.composizioneProvenienza([conOrig(19, { da: "import" }), conOrig(1, { da: "manuale" })]).stato,
       "mista", "una su venti a mano: si dice, ma senza alzare la voce");
    eq(sentinella.composizioneProvenienza([conOrig(8, { da: "import" }), conOrig(2, { da: "manuale" })]).stato,
       "non-trascurabile", "due su dieci: la quota non è più trascurabile e il documento non tace");
    eq(sentinella.composizioneProvenienza([conOrig(8, { da: "import" }), punti(2)]).stato,
       "non-trascurabile", "⛔ e ci si arriva anche con sole misure NON DICHIARATE: non è un problema di digitazione, è di custodia");
    /* la soglia è dichiarata e si legge dal modulo: se un giorno cambia, la
       prova cambia con lei invece di restare a blindare un vecchio numero */
    ok(sentinella.QUOTA_NON_STRUMENTALE > 0 && sentinella.QUOTA_NON_STRUMENTALE < 1,
       "la soglia della quota è una frazione dichiarata");
    const corr = sentinella.composizioneProvenienza([{ letture: [sentinella.correggiLettura(lImp("a.csv"), 9)] }]);
    eq([corr.corrette, corr.importate], [1, 1],
       "⛔ una misura corretta si conta a parte E resta nella sua fonte: sono due fatti diversi");
  });

  test("⛔ Sentinella · custodia: la mappa delle dichiarazioni copre tutti gli stati (regola 18)", () => {
    /* Una mappa più corta di quello che la funzione sa dire ucciderebbe la
       pagina AL DISEGNO, senza nessun errore di sintassi da vedere. */
    for (const s of ["tracciata", "mista", "non-trascurabile", "non-dichiarata", "senza-letture"]) {
      ok(sentinella.DICHIARAZIONI_PROVENIENZA[s], "dichiarazione per «" + s + "»");
      ok(String(sentinella.DICHIARAZIONI_PROVENIENZA[s].testo || "").length > 40,
         "e non è un segnaposto: «" + s + "»");
    }
    for (const f of [sentinella.FONTE_IMPORT, sentinella.FONTE_MANO, sentinella.FONTE_IGNOTA]) {
      ok(sentinella.FONTI_MISURA[f], "etichetta per «" + f + "»");
      ok(String(sentinella.FONTI_MISURA[f].breve || "").length > 0, "con la forma breve per la tabella");
    }
    eq(sentinella.FONTI_MISURA[sentinella.FONTE_IGNOTA].cls, "warn",
       "⛔ giallo lo prende SOLO ciò che non si sa");
    eq(sentinella.FONTI_MISURA[sentinella.FONTE_MANO].cls, "",
       "⛔ «a mano» NON è un allarme: è una pratica legittima, e un giallo su ogni riga si impara a non guardare");
  });

  test("⛔ Sentinella · custodia: la provenienza non si perde all'ingresso né dentro il report", () => {
    /* ⛔ I DUE PUNTI IN CUI LA CATENA SI SPEZZEREBBE IN SILENZIO, e sono
       tutt'e due funzioni che RICOSTRUISCONO la riga campo per campo. */
    const u = sentinella.unisciLetture([], [lImp("V2_giugno.csv")]);
    eq(sentinella.provenienzaMisura(u.letture[0]).file, "V2_giugno.csv",
       "⛔ `unisciLetture` porta dentro la provenienza: perderla qui vorrebbe dire dichiarare «non so» su misure appena importate");
    eq(sentinella.provenienzaMisura(u.letture[0]).da, sentinella.FONTE_IMPORT, "con la sua fonte");
    /* ⛔ E NON SI RIEMPIE ALL'INDIETRO: la firma coincide, ma «lo stesso
       numero lo stesso giorno» non dimostra che quella riga venga da lì. */
    const gia = { data: "2026-06-01", ora: "10:00", valore: 3.2 };
    const u2 = sentinella.unisciLetture([gia], [lImp("V2_giugno.csv")]);
    eq(u2.duplicati, 1, "il doppione resta scartato");
    eq(sentinella.provenienzaMisura(u2.letture[0]).da, sentinella.FONTE_IGNOTA,
       "⛔ e la lettura che c'era NON eredita il file: sarebbe inventare una custodia");
    const R = sentinella.reportConformita({
      monitoraggi: [{ id: "m1", nome: "V2", unita: "mm/s", soglia: 5,
        letture: [lImp("V2.csv"), lMano(), { data: "2026-06-03", valore: 1 }] }],
      ricettori: [], dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" });
    eq([R.provenienza.importate, R.provenienza.aMano, R.provenienza.nonDichiarate], [1, 1, 1],
       "il report conta le tre strade sulle letture DEL PERIODO");
    eq(sentinella.provenienzaMisura(R.punti[0].letture[0]).file, "V2.csv",
       "⛔ e la provenienza arriva fino alla riga della tabella: senza, la colonna del documento sarebbe muta");
    /* ⛔ LA CUSTODIA STA ACCANTO ALL'ESITO, NON DENTRO: cambiare la strada
       d'ingresso non cambia un giudizio di conformità, in nessuno dei due
       versi. È la stessa decisione già presa per le tarature. */
    const senzaProv = sentinella.reportConformita({
      monitoraggi: [{ id: "m1", nome: "V2", unita: "mm/s", soglia: 5,
        letture: [{ data: "2026-06-01", ora: "10:00", valore: 3.2 }] }],
      ricettori: [], dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" });
    const conProv = sentinella.reportConformita({
      monitoraggi: [{ id: "m1", nome: "V2", unita: "mm/s", soglia: 5, letture: [lImp("V2.csv")] }],
      ricettori: [], dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" });
    eq(senzaProv.esito, conProv.esito, "⛔ l'esito è lo stesso: la provenienza non assolve e non condanna");
    eq([senzaProv.provenienza.stato, conProv.provenienza.stato], ["non-dichiarata", "tracciata"],
       "ma la dichiarazione cambia, ed è lì che si legge la differenza");
  });

  test("⛔ Sentinella · custodia: i campi di una misura nuova, e il momento scritto all'italiana", () => {
    const i = sentinella.campiProvenienza(sentinella.FONTE_IMPORT, { file: " V2.csv ", quando: "2026-08-01T09:12:00" });
    eq(i.origine, { da: "import", file: "V2.csv", quando: "2026-08-01T09:12:00" }, "l'import porta file e momento");
    const m = sentinella.campiProvenienza(sentinella.FONTE_MANO, { quando: "2026-08-01T09:12:00" });
    eq(m.origine, { da: "manuale", quando: "2026-08-01T09:12:00" }, "la mano porta solo il momento: non c'è nessun file da citare");
    eq(sentinella.campiProvenienza("qualcosaltro", { quando: "2026-08-01T09:12:00" }).origine.da, "manuale",
       "e ciò che non è import è la mano: il vocabolario è chiuso a due strade d'ingresso");
    ok(String(sentinella.campiProvenienza(sentinella.FONTE_MANO).origine.quando).length >= 16,
       "senza `quando` se lo scrive da sola, con l'istante locale di shared/");
    /* ⛔ IL MOMENTO SI LEGGE, E UNA DATA CHE NON ESISTE NON SI SCRIVE. Il
       `dataIt` di questo modulo su una data impossibile risponde «—», e un
       «il —» in mezzo alla frase di un documento sarebbe peggio del silenzio. */
    const rotta = sentinella.descriviProvenienza({ origine: { da: "import", file: "a.csv", quando: "2026-02-30T09:00:00" } }, { nome: "V2" });
    /* ⚠️ L'ASSERZIONE GIUSTA È «NESSUNA DATA», non «non questa data». La
       prima stesura vietava «—», «2026-02-30» e «02/03» — e la controprova
       ha risposto «non distingue»: togliendo la guardia esce «30/02/2026»,
       che non è nessuna delle tre. Il `dataIt` di questo modulo è un
       rigiro di regex, quindi il 30 febbraio non SCIVOLA al 2 marzo (quello
       lo farebbe `Date.parse`): lo ristampa all'italiana, impossibile e
       tranquillo, dentro un documento che va a un ente. È la prima delle
       cinque cause — i dati della prova non arrivavano al difetto. */
    ok(!/\d{2}\/\d{2}\/\d{4}/.test(rotta),
       "⛔ un momento con un giorno che non esiste NON si scrive: nessuna data compare nella frase");
    ok(!/—/.test(rotta), "e nemmeno un trattino appeso in mezzo alla riga");
    ok(/dal file «a\.csv»/.test(rotta), "ma il resto della frase c'è tutto: si perde il momento, non la provenienza");
    ok(/il 01\/07\/2026/.test(sentinella.descriviProvenienza(lImp("a.csv"), { nome: "V2" })),
       "e un momento vero invece si legge, così la prova qui sopra vieta un'assenza e non tutto");
  });

  test("⛔ Sentinella · custodia: la dimostrazione contiene i casi per cui la difesa esiste", () => {
    /* Stessa ragione per cui `run-demo.mjs` distingue il dato CORROTTO dal
       dato ASSENTE: se la dimostrazione non può contenere il caso, il
       prodotto non lo mostra mai a chi guarda. */
    const tutte = sentinella.DEMO.monitoraggi.flatMap((m) => (m.letture || []).map((l) => sentinella.provenienzaMisura(l)));
    ok(tutte.some((p) => p.da === sentinella.FONTE_IMPORT), "c'è una misura arrivata dal file dello strumento");
    ok(tutte.some((p) => p.da === sentinella.FONTE_MANO), "e una battuta a mano");
    ok(tutte.some((p) => p.da === sentinella.FONTE_IGNOTA),
       "⛔ e una di provenienza NON dichiarata: è il caso di tutto l'archivio esistente il giorno in cui questa unità arriva al cliente");
    ok(tutte.some((p) => p.corretta && p.corretta.prima != null),
       "e una corretta dopo l'inserimento, col valore d'origine");
    const conFile = tutte.filter((p) => p.da === sentinella.FONTE_IMPORT);
    ok(conFile.every((p) => p.file && p.quando), "ogni misura importata d'esempio porta il file E il momento");
  });

  test("⛔ Sentinella · import tarature: la scadenza prima della taratura si scarta, non si raddrizza", () => {
    const v = una("Vibrazioni V1 — abitato Sud;2026-06-01;2026-05-01");
    eq(v.motivo, "la scadenza viene prima della taratura", "intervallo alla rovescia");
    eq([v.data, v.scadenza], ["2026-06-01", "2026-05-01"],
       "⛔ e le due date restano come le ha scritte l'utente: girarle vorrebbe dire inventare quale ha sbagliato");
    eq(una("Vibrazioni V1 — abitato Sud;2026-06-01;2026-06-01").ok, true,
       "stesso giorno invece va bene: è un certificato che copre un giorno solo");
  });

  test("⛔ Sentinella · import tarature: uno strumento che non esiste NON si crea", () => {
    /* Un punto di misura porta una SOGLIA, ed è la soglia a decidere se una
       misura è conforme. Un certificato di taratura non la sa. Crearne uno da
       qui vorrebbe dire fabbricare un giudizio di conformità da un file
       amministrativo. */
    const r = leggi("Sismografo Nomad;2026-01-15;2027-01-14;;;\nSismografo Nomad;2026-02-01;2027-02-01;;;");
    eq(r.riepilogo.pronte, 0, "nessuna delle due entra");
    eq(r.voci[0].motivo, "nessuno strumento si chiama così", "e il motivo lo dice");
    eq(r.voci[0].puntoId, "", "senza attaccarla a nessuno");
    eq(r.riepilogo.sconosciuti, ["Sismografo Nomad"],
       "⛔ e il nome che non si è trovato viene DETTO una volta sola, così si sa se correggere il file o creare prima il punto");
    eq(leggi("Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14", []).voci[0].motivo,
       "nessuno strumento si chiama così", "senza nemmeno un punto di misura, stessa risposta");
  });

  test("⛔ Sentinella · import tarature: un nome che vale per due strumenti non si assegna al primo", () => {
    const due = [{ id: "a", nome: "Polveri P2 — nord" }, { id: "b", nome: "Polveri P2 — sud" }];
    eq(una("Polveri P2;2026-01-15;2027-01-14", due).motivo, "il nome corrisponde a più di uno strumento",
       "il nome corto è di tutt'e due: attaccarlo a uno a caso dichiarerebbe riferibili le letture dello strumento sbagliato");
    eq(una("Polveri P2 — nord;2026-01-15;2027-01-14", due).puntoId, "a", "col nome intero invece si sa quale");
  });

  test("Sentinella · import tarature: il doppione si cerca in due posti, e sono due domande", () => {
    eq(una("Vibrazioni V1 — abitato Sud;2025-01-01;2026-01-01").motivo, "già registrata su questo strumento",
       "contro l'archivio: stesse due date sullo stesso strumento");
    const r = leggi("Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14;;A;\n"
                  + "Vibrazioni V1 — abitato Sud;2026-01-15;2027-01-14;;B;");
    eq(r.voci.map(v => v.ok), [true, false], "dentro il file: vale la PRIMA scrittura");
    eq(r.voci[1].motivo, "ripetuta nel file", "e la seconda lo dichiara invece di sparire");
    eq(una("Polveri PM10 — confine Est;2025-01-01;2026-01-01").ok, true,
       "le stesse due date su un ALTRO strumento non sono un doppione: è un altro certificato");
  });

  test("Sentinella · import tarature: il giro export → import non perde niente", () => {
    const mon = [{ id: "v1", nome: "Vibrazioni V1 — abitato Sud", tarature: [
      { data: "2026-01-15", scadenza: "2027-01-14", ente: "Centro LAT; Milano", certificato: "LAT-2026/77", nota: "terna" }] }];
    const testo = sentinella.csvTarature(mon);
    /* ⚠️ IL GIRO DA SOLO NON BASTA. Scrittore e lettore possono sbagliare
       insieme: `dataIso` legge anche 15/01/2026, quindi un export all'italiana
       tornerebbe identico e nessuno se ne accorgerebbe. Serve l'asserzione sul
       TESTO del file, che è quello che legge chi lo apre con un altro
       programma. */
    ok(testo.startsWith(sentinella.CSV_TARATURE_INTESTAZIONE + "\n"),
       "l'intestazione è quella dichiarata, e la scrive una costante sola: " + sentinella.CSV_TARATURE_INTESTAZIONE);
    ok(testo.includes(";2026-01-15;2027-01-14;"), "le date escono in ISO, non all'italiana");
    ok(testo.includes('"Centro LAT; Milano"'),
       "⛔ e il punto e virgola dentro il nome del centro esce fra virgolette: senza, la riga si spezzerebbe in silenzio");
    const giro = leggi(testo, [{ id: "v1", nome: "Vibrazioni V1 — abitato Sud", tarature: [] }]);
    eq(giro.riepilogo, { letti: 1, pronte: 1, scartate: 0, motivi: [], sconosciuti: [] }, "e rientra tutto");
    contiene(giro.voci[0], { data: "2026-01-15", scadenza: "2027-01-14", ente: "Centro LAT; Milano",
      certificato: "LAT-2026/77", nota: "terna", puntoId: "v1" }, "campo per campo, identico");
  });

  test("⛔ Sentinella · export tarature: escono anche i certificati con le date rotte", () => {
    /* Esportare solo i leggibili vorrebbe dire che chi fa un backup si ritrova
       un archivio più corto senza che nessuno glielo abbia detto. A dire che
       una riga non si può usare ci pensa l'import, che lo dichiara. */
    const testo = sentinella.csvTarature([{ id: "x", nome: "S", tarature: [
      { data: "2026-02-30", scadenza: "2027-01-01" }, { data: "2026-01-01", scadenza: "2027-01-01" }] }]);
    eq(testo.trim().split("\n").length, 3, "intestazione più DUE righe, non una");
    eq(leggi(testo, [{ id: "x", nome: "S", tarature: [] }]).riepilogo.scartate, 1,
       "ed è l'import a scartarne una, dicendolo");
    eq(sentinella.csvTarature(null), sentinella.CSV_TARATURE_INTESTAZIONE + "\n",
       "senza strumenti resta la sola intestazione: un file vuoto ha comunque le sue colonne");
  });

  /* ══ LE TARATURE NELLE ALLERTE DEL QUADRO ══
     Fino a ieri lo stato si vedeva solo entrando nella sezione, cioè lo
     scopriva chi era già andato a cercarlo. Ma dal giorno dopo la scadenza
     ogni lettura di quello strumento risulta scoperta, e un certificato non si
     fa fare a ritroso. La decisione difesa qui è QUANTO entra: il Quadro è già
     denso, e una lista che dice tutto non la legge nessuno. */
  const strum = (nome, scad) => ({ id: nome, nome, tarature: scad ? [{ data: "2024-01-01", scadenza: scad }] : [] });

  test("Sentinella · allerte: la taratura scaduta e quella in scadenza entrano nel Quadro", () => {
    const a = sentinella.allerteTaratura([strum("A", "2026-06-15"), strum("B", "2026-08-20")], OGGI_I);
    eq(a.length, 2, "due righe");
    contiene(a[0], { gravita: "danger", categoria: "taratura", titolo: "A", badge: "scaduta da 47 gg" },
       "la scaduta è rossa come un adempimento mancato");
    contiene(a[1], { gravita: "warn", categoria: "taratura", titolo: "B", badge: "19 gg" },
       "quella in scadenza è gialla, con i giorni che mancano");
    ok(/non più coperte/.test(a[0].dettaglio), "e il dettaglio dice la conseguenza: " + a[0].dettaglio);
    for (const x of a) ok(x.dettaglio.length <= 60,
      "⚠️ corto: la riga di dettaglio è tagliata a due righe, " + x.dettaglio.length + " caratteri");
    for (const x of a) eq(Object.keys(x).sort(), ["badge", "categoria", "dettaglio", "gravita", "puntoId", "titolo"],
      "i cinque campi delle altre allerte, così si mescolano senza casi particolari, più `puntoId`");
    eq(a.map(x => x.puntoId), ["A", "B"],
       "⚠️ e `puntoId` c'è perché questa allerta porta a una SEZIONE che parla di uno strumento alla volta: "
       + "senza, si atterra su una tendina che mostra i certificati di un altro");
  });

  test("⛔ Sentinella · allerte: «non dichiarata» NON è un'allerta, ed è una decisione", () => {
    /* Non è una scadenza arrivata: è un archivio che non è ancora cominciato.
       Metterla qui vorrebbe dire che il primo giorno l'app apre con una riga
       per OGNI strumento, per sempre, finché qualcuno non carica tutti i
       certificati — il Quadro illeggibile proprio per chi non ha ancora
       niente da leggerci. Lo dicono già il badge sulla riga del punto, il
       conto della sezione e la dichiarazione del report. */
    eq(sentinella.allerteTaratura([strum("A", ""), strum("B", ""), strum("C", "")], OGGI_I), [],
       "⛔ un archivio senza nessun certificato aggiunge ZERO righe al Quadro");
    eq(sentinella.statoTaraturaStrumento(strum("A", ""), OGGI_I).stato, "non-dichiarata",
       "e non perché lo stato non si sappia: si sa, e la sezione lo dice");
    eq(sentinella.allerteTaratura([strum("A", "2027-06-01")], OGGI_I), [],
       "nemmeno una taratura valida a lungo: non c'è niente da fare");
    eq(sentinella.allerteTaratura([{ id: "r", nome: "R", tarature: [{ data: "2026-02-30", scadenza: "2027-01-01" }] }], OGGI_I), [],
       "e un certificato con le date rotte non è una scadenza: per la sezione quello strumento è «non dichiarato»");
    eq(sentinella.allerteTaratura(null, OGGI_I), [], "chiamata senza strumenti non esplode");
  });

  test("⛔ Sentinella · allerte: la finestra dei 30 giorni la decide `shared/`, non un numero riscritto qui", () => {
    for (const sc of ["2026-08-31", "2026-09-01", "2026-07-31", "2027-01-01"]) {
      const dentro = sentinella.allerteTaratura([strum("X", sc)], OGGI_I).length === 1;
      const st = ponti.statoScadenzaHSE(sc, OGGI_I);
      eq(dentro, st === "scaduta" || st === "in-scadenza",
         `per ${sc} l'allerta c'è se e solo se statoScadenzaHSE dice scaduta/in-scadenza (dice «${st}»)`);
    }
    eq(sentinella.allerteTaratura([strum("X", "2026-08-31")], OGGI_I).length, 1, "l'ultimo giorno della finestra c'è");
    eq(sentinella.allerteTaratura([strum("X", "2026-09-01")], OGGI_I).length, 0, "il primo fuori no");
  });

  test("⛔ Sentinella · allerte: la taratura non muove nessun giudizio di conformità", () => {
    /* Questa unità sposta pezzi di carta: non legge soglie, non legge curve.
       Vale identica la decisione di T2b — accanto all'esito, mai dentro. */
    const mon = [{ id: "x", nome: "P", soglia: 10, unita: "mm/s", letture: [{ data: "2026-06-10", valore: 2 }] }];
    const arg = { dal: "2026-06-01", al: "2026-06-30", oggi: "2026-08-01" };
    const senza = sentinella.reportConformita({ monitoraggi: mon, ...arg });
    const conScaduta = sentinella.reportConformita({
      monitoraggi: [{ ...mon[0], tarature: [{ data: "2024-01-01", scadenza: "2026-06-15" }] }], ...arg });
    eq([senza.esito, conScaduta.esito], ["conforme", "conforme"],
       "una taratura scaduta — che nel Quadro è un'allerta rossa — non rende non conforme una cava che ha rispettato i limiti");
    eq(sentinella.allerteTaratura([{ ...mon[0], tarature: [{ data: "2024-01-01", scadenza: "2026-06-15" }] }], OGGI_I).length, 1,
       "l'allerta però c'è: sono due frasi affiancate, non una che decide dell'altra");
  });

  test("Sentinella · allerte: sulla dimostrazione, oggi, nessuna taratura è in scadenza", () => {
    /* Il numero non è deciso a mente: se un giorno la demo cambia, questa
       riga lo dice invece di lasciare che una schermata si svuoti in
       silenzio. */
    const a = sentinella.allerteTaratura(sentinella.DEMO.monitoraggi, OGGI_I);
    eq(a.length, 0, "i due strumenti con certificato sono in regola, gli altri tre non ne hanno nessuno");
    eq(sentinella.DEMO.monitoraggi.filter(m => (m.tarature || []).length).length, 2,
       "e quanti strumenti hanno almeno un certificato, contati: 2 su " + sentinella.DEMO.monitoraggi.length);
  });
}

/* ══ SHARED · LA DATA COME SI SCRIVE IN ITALIA ══
   Sei pagine su sei se la scrivevano da sole, con quattro nomi diversi e —
   misurato — comportamenti diversi su quattro casi su sette. Due di quelle
   righe erano difetti che l'utente VEDE. */
{
  test("⛔ shared: una data che NON ESISTE non si stampa come se fosse un fatto", () => {
    /* `split("-").reverse().join("/")` non guarda cosa sta girando: gira e
       basta, e su «2026-02-30» scriveva «30/02/2026» — un giorno che non c'è
       mai stato, mostrato con la stessa faccia di uno vero */
    eq(shell.dataIt("2026-02-30"), "—", "il 30 febbraio");
    eq(shell.dataIt("2026-13-45"), "—", "il quarantacinque tredici");
    eq(shell.dataIt("2026-00-10"), "—", "il mese zero");
    eq(shell.dataIt("31/07/2026"), "—", "e una data già italiana non si rigira");
  });

  test("⛔ shared: un ISTANTE diventa il suo giorno, non spazzatura", () => {
    /* tre app su sei scrivevano «31T10:00/07/2026» ogni volta che a quella
       funzione arrivava un istante invece di un giorno */
    eq(shell.dataIt("2026-07-31T10:00"), "31/07/2026", "con la T");
    eq(shell.dataIt("2026-07-31 10:00"), "31/07/2026", "con lo spazio");
    eq(shell.dataIt("2026-07-31T10:00:00.000Z"), "31/07/2026", "e in forma completa");
  });

  test("shared: la data normale, e il vuoto con la parola che l'app ha scelto", () => {
    eq(shell.dataIt("2026-07-31"), "31/07/2026", "il caso di tutti i giorni");
    eq(shell.dataIt("2026-01-01"), "01/01/2026", "gli zeri davanti restano");
    for (const niente of ["", null, undefined])
      eq(shell.dataIt(niente), "—", `${mostra(niente)}: il trattino`);
    eq(shell.dataIt("", "senza data"), "senza data",
       "⛔ e la PAROLA resta dell'app: «senza data» dove la mancanza è essa stessa un'informazione");
    eq(shell.dataIt("2026-02-29"), "—", "il 2026 non è bisestile");
    eq(shell.dataIt("2024-02-29"), "29/02/2024", "il 2024 sì");
  });
}

/* ══ GENESI · COME SCRIVE UN NUMERO — le prime prove pure di Genesi ══
   Genesi era l'unica parte del prodotto con ZERO prove pure: le sue 192
   funzioni stanno dentro `genesi.html`, e `node` non importa un file .html.
   Queste sei scrivono quasi trecento numeri della pagina — spalla, maglia,
   consumo specifico, tempi di sparo, chili di esplosivo — e sono il primo
   pezzo che esce. */
{
  const g = await app("genesi", "genesi-formato.js");

  test("⛔ Genesi: su un dato che manca si scrive «—», non «0»", () => {
    /* uno zero è un fatto («qui non c'è esplosivo»); un dato mancante è
       l'assenza di un fatto, e in una pagina di progettazione di volata i due
       si leggono in modo opposto */
    for (const vuoto of [null, undefined, "", NaN, Infinity, -Infinity])
      eq(g.gnum(vuoto), "—", `gnum(${mostra(vuoto)})`);
    for (const vuoto of [null, undefined, "", NaN])
      eq(g.gfix(vuoto), "—", `gfix(${mostra(vuoto)})`);
    eq(g.gseg(null), "—", "e anche il numero col segno");
    eq(g.gnum(0), "0", "⛔ ma lo ZERO si scrive: è un fatto, non un'assenza");
    eq(g.gfix(0, 2), "0,00", "idem con i decimali fissi");
  });

  test("Genesi: i numeri si scrivono all'italiana, e il raggruppamento è dichiarato", () => {
    eq(g.gnum(1234.5), "1.234,5", "migliaia col punto, decimali con la virgola");
    eq(g.gnum(1234.5678), "1.234,57", "due decimali di massimo, per difetto");
    eq(g.gnum(1234.5678, 4), "1.234,5678", "e si possono chiedere di più");
    eq(g.gfix(2, 1), "2,0", "gfix TIENE i decimali chiesti: «2,0» non è «2»");
    eq(g.gfix(2), "2,0", "un decimale di suo");
    /* ⚠️ `useGrouping` è esplicito nel modulo: senza, questa riga darebbe
       «6375» in Node e «6.375» in Chromium, e la prova sarebbe verde qui e
       falsa dove l'utente guarda */
    eq(g.gnum(6375, 0), "6.375", "quattro cifre: raggruppate anche in Node");
  });

  test("Genesi: i decimali si fermano dove ha senso, non dove capita", () => {
    eq(g.gnum(1.23456789, 99), "1,234568", "al massimo sei: oltre è rumore, non precisione");
    eq(g.gnum(1.5, -3), "2", "un numero di decimali negativo non esiste: si legge zero");
    eq(g.gfix(1.23456789, 99), "1,234568", "stesso tetto");
  });

  test("Genesi: il segno davanti, per gli scarti", () => {
    eq(g.gseg(3.2), "+3,2", "il più si scrive: uno scarto senza segno non si legge");
    eq(g.gseg(-3.2), "−3,2", "e il meno è il segno tipografico (−), non il trattino");
    eq(g.gseg(0), "+0", "lo zero è uno scarto nullo, non un'assenza");
  });

  test("Genesi: la data tecnica diventa una data che un italiano legge", () => {
    eq(g.gdata("2026-07-30 01:38"), "30/07/2026 alle 01:38", "con l'ora");
    eq(g.gdata("2026-07-30"), "30/07/2026", "senza");
    eq(g.gdata("2026-07-30T01:38"), "30/07/2026 alle 01:38", "anche in forma ISO con la T");
    eq(g.gdata(""), "", "niente resta niente");
    eq(g.gdata("boh"), "boh", "⛔ e quello che non è una data torna com'è: non si inventa un giorno");
  });

  test("⛔ Genesi: sotto l'unità i chili prendono un decimale in più", () => {
    /* i consumi specifici stanno sotto l'unità: con due decimali «0,05» e
       «0,054» diventerebbero lo stesso numero, e quello è il valore da cui
       dipende quanto esplosivo va nel foro */
    eq(g.fmtKg(1.234), "1,23", "da un chilo in su, due decimali");
    eq(g.fmtKg(0.05), "0,050", "sotto l'unità, tre");
    eq(g.fmtKg(0.0999), "0,100", "il confine è a un decimo");
    eq(g.fmtKg(0.1), "0,10", "e a un decimo esatto si torna a due");
    eq(g.fmtMs(25), "25,0", "i millisecondi di ritardo, un decimale");
  });
}

/* ══ GENESI · LA VIBRAZIONE AL RECETTORE — il secondo pezzo fuori dalla pagina ══
   `apps/genesi/genesi-data.js`. Dodici funzioni spostate parola per parola da
   `genesi.html`: dal file del sismografo alla legge di sito, dalla legge al
   limite di norma, e la sovrappressione d'aria. È il numero che decide se una
   volata si può sparare, e fino a oggi girava senza una sola prova pura perché
   `node` non importa un `.html`. */
{
  const v = await app("genesi", "genesi-data.js");

  /* referti finti che stanno ESATTAMENTE su PPV = K·SD^−β: così una prova che
     fallisce accusa il calcolo, non i dati */
  const referto = (d, w, K = 700, b = 1.6) => ({ d, w, ppv: K * Math.pow(d / Math.sqrt(w), -b) });
  const OTTO = [referto(100, 50), referto(200, 50), referto(400, 50), referto(300, 20),
                referto(150, 80), referto(500, 100), referto(80, 40), referto(250, 60)];

  test("Genesi · dai referti del sismografo esce la legge del sito", () => {
    const f = v.sitoFit(OTTO);
    eq([f.n, f.K, f.beta, f.r2], [8, 700, 1.6, 1],
       "otto referti presi da PPV = 700·SD^−1,6 devono restituire proprio quel K e quel β");
    eq([f.sdMin, f.sdMax], [12.6, 67.1],
       "e l'intervallo di distanza scalata su cui la legge è tarata: fuori da lì è estrapolazione");
    eq(f.K95, f.K, "su dati senza dispersione la riga di progetto coincide con la media");
    ok(!f.errore, "una legge fisica e ben condizionata non porta errori");
  });

  test("⛔ Genesi · il progetto si fa sulla riga al 95°, non sulla media", () => {
    /* sulla retta media metà delle volate finirebbe sopra il limite: la riga di
       conformità è media + 1,645 × scarto dei residui. Un referto fuori scala
       la deve allontanare dalla media, non lasciarla dov'era. */
    const conScarto = v.sitoFit([...OTTO, { d: 120, w: 50, ppv: 40 }]);
    ok(conScarto.K95 > conScarto.K,
       `con dei residui la riga di progetto sta SOPRA la media (K ${conScarto.K}, K95 ${conScarto.K95})`);
    ok(conScarto.r2 < 1, "e la bontà del fit scende sotto 1: il punto fuori scala si vede");
    ok(v.sitoFit(OTTO).s === 0 || v.sitoFit(OTTO).s < 1e-12,
       "mentre su dati perfetti lo scarto dei residui è nullo");
  });

  test("⛔ Genesi · quando la legge NON si può usare, il modulo lo dice invece di rispondere un numero", () => {
    /* è il principio del fondatore sul dato che decide le distanze di
       sicurezza: senza abbastanza referti non esce un K piccolo e rassicurante,
       esce il motivo per cui non c'è nessun K */
    const pochi = v.sitoFit(OTTO.slice(0, 2));
    eq(pochi.errore, "pochi", "meno di tre referti: da due punti passa qualunque retta");
    eq([pochi.K, pochi.K95, pochi.beta, pochi.r2], [undefined, undefined, undefined, undefined],
       "⛔ e nell'oggetto non c'è NESSUN numero da leggere per sbaglio: né K, né β, né r²");

    eq(v.sitoFit([{ d: 100, w: 25, ppv: 5 }, { d: 200, w: 100, ppv: 6 }, { d: 400, w: 400, ppv: 7 }]).errore,
       "stessaSD",
       "tre referti tutti alla stessa distanza scalata: la pendenza non è determinabile");
    eq(v.sitoFit([{ d: 100, w: 50, ppv: 5 }, { d: 200, w: 50, ppv: 5.1 }, { d: 400, w: 50, ppv: 5.2 }]).errore,
       "pendenza",
       "una PPV che non cala con la distanza non descrive un'attenuazione fisica: referti di siti diversi mescolati");
    for (const niente of [[], null, undefined])
      eq(v.sitoFit(niente), { n: 0, errore: "pochi" }, `${mostra(niente)}: zero referti, e lo scrive`);
  });

  test("Genesi · i referti illeggibili si scartano, e `n` conta quelli veri", () => {
    /* `n` finisce sotto gli occhi dell'utente («la legge è tarata su n referti»):
       se contasse le righe del file invece dei punti usati, direbbe una legge
       più solida di quella che è */
    const f = v.sitoFit([...OTTO.slice(0, 3),
      { d: 0, w: 50, ppv: 3 }, { d: 100, w: 0, ppv: 3 }, { d: 100, w: 50, ppv: 0 }, null]);
    eq(f.n, 3, "quattro righe buttate: tre punti, non sette");
    eq(f.avviso, "pochi",
       "e sotto gli otto referti la legge si dichiara PROVVISORIA — l'avviso che la pagina legge accanto a K e β");
    ok(!v.sitoFit(OTTO).avviso, "con otto l'avviso sparisce");
  });

  test("Genesi · le soglie di vibrazione sono quelle delle norme, per fascia di frequenza", () => {
    /* DIN 4150-3 e USBM RI8507. Le frequenze scelte cadono DENTRO le fasce;
       i confini si provano a parte, perché è lì che un `<` scritto `<=` si
       nasconde senza far cadere niente. */
    const a = (n) => [v.ppvLimit(n, 5), v.ppvLimit(n, 25), v.ppvLimit(n, 60)];
    eq(a("din-res"), [5, 15, 20], "DIN residenziale");
    eq(a("din-ind"), [20, 40, 50], "DIN industriale");
    eq(a("din-sens"), [3, 8, 10], "DIN edificio sensibile/storico");
    eq(a("usbm-old"), [12.7, 12.7, 50.8], "USBM intonaco: una sola soglia sotto i 40 Hz");
    eq(a("usbm-modern"), [19, 19, 50.8], "USBM cartongesso");
    eq([v.ppvLimit("din-ind", 9.99), v.ppvLimit("din-ind", 10)], [20, 40], "il confine DIN è a 10 Hz esatti");
    eq([v.ppvLimit("din-ind", 49.99), v.ppvLimit("din-ind", 50)], [40, 50], "e il secondo a 50");
    eq([v.ppvLimit("usbm-old", 39.99), v.ppvLimit("usbm-old", 40)], [12.7, 50.8], "quello USBM a 40");
    eq([...new Set(Object.keys(v.NORME_PPV).map((n) => v.ppvLimit(n, 25)))].length,
       Object.keys(v.NORME_PPV).length,
       "e a 25 Hz le cinque norme danno cinque numeri DIVERSI: scegliere la norma sbagliata "
       + "non è un dettaglio di etichetta, cambia la soglia");
  });

  test("⛔ Genesi: su una frequenza illeggibile la soglia NON esiste — e non è la più permissiva", () => {
    /* Il difetto, misurato prima di correggerlo: con una frequenza non
       numerica si cadeva nell'ultimo ramo di ogni `switch`, cioè nella fascia
       ALTA — 50,8 invece di 12,7, 20 invece di 15. Il numero tranquillo dove
       non è stato misurato niente, sul valore che decide se si spara. */
    const ILLEGGIBILI = [undefined, null, NaN, "", "  ", "venticinque", "25,5", {}, []];
    const norme = Object.keys(v.NORME_PPV);
    const risposte = [];
    for (const n of norme) for (const f of ILLEGGIBILI) risposte.push(v.ppvLimit(n, f));
    eq([...new Set(risposte)], [null],
       `${norme.length} norme × ${ILLEGGIBILI.length} frequenze illeggibili: devono rispondere tutte null`);
    /* ⛔ e i due casi che una guardia scritta con `Number.isFinite(+f)` da sola
       lascerebbe passare: `+null` e `+""` fanno ZERO, che è finito — e zero
       Hz darebbe la fascia più SEVERA. Sempre un numero inventato, solo nella
       direzione che non spaventa. Bocciati dal prototipo prima del modulo. */
    eq([v.ppvLimit("din-res", null), v.ppvLimit("din-res", "")], [null, null],
       "null e stringa vuota non diventano 0 Hz");
    /* e la controparte: le soglie vere non sono cambiate di un decimale */
    eq([v.ppvLimit("usbm-old", "40"), v.ppvLimit("din-res", " 25 ")], [50.8, 15],
       "una frequenza scritta come stringa numerica resta leggibile (i progetti salvati tornano da JSON)");
  });

  test("⛔ Genesi: una norma che non conosciamo non prende in silenzio la soglia residenziale", () => {
    /* `normaPpvLab('boh')` rispondeva onestamente «boh» e `ppvLimit('boh', 25)`
       rispondeva **15**: sullo stesso schermo l'etichetta e il numero
       raccontavano due cose diverse, e chi legge «boh · 15 mm/s» crede che 15
       sia la soglia di «boh». Il `default:` del `switch` resta la DIN
       residenziale — è giusto, è la norma di riferimento — ma ci si arriva solo
       col codice `din-res`. */
    for (const n of ["boh", "", null, undefined, "DIN-RES", "din_res", 0])
      eq(v.ppvLimit(n, 25), null, `«${String(n)}» non è un codice di norma che conosciamo`);
    /* e i cinque veri rispondono ancora */
    eq(Object.keys(v.NORME_PPV).map((n) => v.ppvLimit(n, 25) === null).filter(Boolean).length, 0,
       "le cinque norme dell'elenco hanno tutte la loro soglia");
    /* ⛔ e l'etichetta e il numero non possono più scostarsi: dove la soglia
       non c'è, l'etichetta ripete il codice invece di battezzarlo */
    eq(v.normaPpvLab("boh"), "boh", "un codice sconosciuto si ripete, non si traduce");
    eq(v.normaPpvLab("din-res"), "DIN residenziale", "e uno vero si traduce");
  });

  test("⛔ Genesi: r² non calcolabile è `null`, non `0` — e la pagina è difesa due volte", () => {
    /* con tutte le PPV uguali `sst` è nullo e r² non esiste. Scriverlo 0 vuol
       dire «la legge non spiega niente»: un'affermazione, non un'ammissione. */
    const f = v.sitoFit([{ d: 100, w: 25, ppv: 10 }, { d: 200, w: 25, ppv: 10 }, { d: 400, w: 25, ppv: 10 }]);
    eq(f.r2, null, "r² non calcolabile");
    /* ⚠️ e la seconda metà della prova è l'onestà su quanto pesa: quel caso
       esce SEMPRE anche con `errore: 'pendenza'` (PPV uguali ⇒ β = 0, fuori da
       0,5–3), e la modale disegna il riquadro di r² solo nel ramo senza errore.
       Difesa in profondità, non innocuità — la difesa stava in un'altra riga. */
    eq(f.errore, "pendenza", "e lo stesso caso porta già l'errore che la pagina legge");
    eq(f.beta, 0, "perché la pendenza è zero");
    /* e su dati veri r² resta un numero */
    eq(v.sitoFit([{ d: 100, w: 25, ppv: 30 }, { d: 200, w: 25, ppv: 15 }, { d: 400, w: 25, ppv: 7.5 }]).r2, 1,
       "una legge perfetta ha r² = 1");
  });

  test("Genesi · ogni codice di norma che la pagina propone ha un nome scritto per esteso", () => {
    /* il nome finisce nel rapporto e nel file per Sentinella, accanto al numero:
       un limite citato senza dire QUALE limite non è verificabile da nessuno */
    eq(Object.keys(v.NORME_PPV).sort(),
       ["din-ind", "din-res", "din-sens", "usbm-modern", "usbm-old"],
       "i cinque codici");
    for (const k of Object.keys(v.NORME_PPV))
      ok(/[A-Z]/.test(v.normaPpvLab(k)) && v.normaPpvLab(k) !== k,
         `«${k}» si scrive «${v.normaPpvLab(k)}», non col suo codice`);
    eq(v.normaPpvLab("boh"), "boh",
       "un codice sconosciuto torna com'è: meglio una sigla strana che una norma inventata");
    eq([v.normaPpvLab(null), v.normaPpvLab(undefined)], ["", ""], "e senza codice non si scrive niente");
  });

  test("Genesi · l'airblast segue la radice CUBICA della carica, non la quadrata", () => {
    /* SD₃ = distanza / ∛(carica per ritardo): raddoppiare la distanza e
       moltiplicare per otto la carica devono costare/rendere lo STESSO numero
       di dB — 24·log₁₀2. È l'invariante che casca subito se qualcuno scrive
       `sqrt` al posto di `cbrt`, e leggendo il codice non si vedrebbe. */
    const passo = 24 * Math.log10(2);
    const arr = (x) => Math.round(x * 1e9) / 1e9;
    eq(arr(v.airblastDb(150, 60) - v.airblastDb(300, 60)), arr(passo), "distanza raddoppiata: −7,22 dB");
    eq(arr(v.airblastDb(300, 80) - v.airblastDb(300, 10)), arr(passo), "carica per otto: +7,22 dB");
    ok(v.airblastDb(300, 60) > 120 && v.airblastDb(300, 60) < 130,
       "e l'ordine di grandezza è quello di una volata di cava a 300 m (~127 dB)");
  });

  test("⛔ Genesi · un referto senza provenienza lo dichiara, non passa per «inserito a mano»", () => {
    /* K e β decidono le distanze di sicurezza: chi li guarda deve sapere da
       dove vengono. Un referto vecchio, salvato prima che il campo esistesse,
       non va riscritto a posteriori dandogli un'origine che nessuno ha detto. */
    eq(["mano", "csv", "sentinella"].map((f) => v._sitoFonte({ fonte: f }).et),
       ["a mano", "sismografo", "Sentinella"], "le tre provenienze note");
    for (const senza of [{}, null, undefined, { fonte: "" }, { fonte: "boh" }])
      eq([v._sitoFonte(senza).et, v._sitoFonte(senza).cls],
         ["origine non registrata", "ign"], `${mostra(senza)}: si dichiara, e con una classe sua`);
    ok(Object.keys(v._SITO_FONTI).every((k) => v._SITO_FONTI[k].et && v._SITO_FONTI[k].lungo),
       "ogni provenienza ha sia l'etichetta corta della pillola sia la frase del riepilogo");
  });

  test("Genesi · la colonna «origine» del file si legge, e il caso non conta", () => {
    eq(["Sentinella", "dal registro SENTINELLA", "a mano", "Manuale"].map(v._sitoFonteDaTesto),
       ["sentinella", "sentinella", "mano", "mano"], "le parole che riconosciamo");
    eq(["Instantel", "", null, undefined].map(v._sitoFonteDaTesto), ["csv", "csv", "csv", "csv"],
       "tutto il resto è il file di uno strumento: è da lì che il file è arrivato");
  });

  test("Genesi · «Distanza_m» e «DISTANZA (m)» sono la stessa intestazione", () => {
    eq(["Distanza_m", "DISTANZA (m)", " Distanza.m ", "distanza[m]"].map(v._sitoNormH),
       ["distanza m", "distanza m", "distanza m", "distanza m"],
       "maiuscole, underscore, punti, parentesi e quadre: tutti separatori");
    eq(v._sitoNormH('"PPV"'), "ppv", "e le virgolette che certi export lasciano dentro");
    eq([v._sitoNormH(null), v._sitoNormH(undefined)], ["", ""], "niente resta niente");
  });

  test("⛔ Genesi · la colonna sbagliata darebbe una legge sbagliata: le due trappole si evitano", () => {
    /* «distanza scalata» e «carica totale» sono le due colonne che i sismografi
       scrivono ACCANTO a quelle giuste. Prese per buone, la regressione gira
       lo stesso e produce un K e un β dall'aria plausibile: nessun errore, solo
       distanze di sicurezza sbagliate. */
    eq(v._sitoMappaColonne(["distanza scalata", "distanza (m)", "carica max kg", "ppv mm/s"]),
       { d: 1, w: 2, p: 3, rif: -1, data: -1, org: -1 },
       "la distanza SCALATA non è la distanza");
    eq(v._sitoMappaColonne(["dist", "carica totale kg", "carica per ritardo kg", "velocita mm/s"]),
       { d: 0, w: 2, p: 3, rif: -1, data: -1, org: -1 },
       "e la carica TOTALE della volata non è la carica per ritardo");
    eq(v._sitoMappaColonne(["distanza_m", "carica_kg", "ppv_mm_s", "riferimento", "data", "origine"]),
       { d: 0, w: 1, p: 2, rif: 3, data: 4, org: 5 },
       "il nostro export rientra da solo, colonne facoltative comprese");
  });

  test("Genesi · quando l'intestazione non si riconosce si torna all'ordine di prima, non si indovina", () => {
    const ordine = { d: 0, w: 1, p: 2, rif: -1, data: -1, org: -1 };
    eq(v._sitoMappaColonne(["a", "b", "c"]), ordine, "tre colonne senza nome");
    for (const niente of [null, undefined, []])
      eq(v._sitoMappaColonne(niente), ordine, `${mostra(niente)}: nessuna intestazione`);
    eq(v._sitoMappaColonne(["ppv distanza", "ppv", "carica kg"]), ordine,
       "e se due riconoscimenti cadono sulla STESSA colonna la proposta si annulla tutta, "
       + "invece di mappare due grandezze sullo stesso numero");
  });

  test("Genesi · l'asse logaritmico non resta muto sugli intervalli stretti", () => {
    /* è la ragione per cui questa funzione non usa 1-2-5 sempre: su un
       intervallo come 14–39 m/kg^½ uscirebbe la sola tacca del 20 */
    eq(v._sitoTicks(0, 2), [1, 2, 5, 10, 20, 50, 100], "due decadi: 1-2-5 per decade");
    const stretto = v._sitoTicks(Math.log10(14), Math.log10(39));
    eq(stretto, [15, 20, 25, 30], "14–39: quattro tacche, non una");
    ok(stretto.every((t) => t >= 14 && t <= 39), "e nessuna tacca fuori dall'intervallo chiesto");
    eq(v._sitoTicks(2, 1), [], "un intervallo rovesciato non produce tacche inventate");
  });

  test("Genesi · sul diagramma i decimali scalano con l'ordine di grandezza", () => {
    /* la stessa scala porta 0,12 mm/s e 1.235 m/kg^½: due decimali fissi
       renderebbero illeggibili tutt'e due, uno per rumore e l'altro per larghezza */
    eq([0.123456, 5.678, 12.34, 123.4, 1234.5].map(v._sitoNum),
       ["0,12", "5,68", "12,3", "123", "1.235"], "due sotto la decina, uno sotto il centinaio, zero sopra");
    for (const vuoto of [null, undefined, "", NaN])
      eq(v._sitoNum(vuoto), "—", `${mostra(vuoto)}: il trattino, come tutto il resto di Genesi`);
  });
}

/* ══ SHARED · IL LETTORE DI CSV, UNO SOLO ══
   `parseCsvLine` legge UNA riga e va benissimo finché il file ha una riga per
   record. Un estratto conto bancario no: la descrizione lunga la banca la
   scrive su PIÙ RIGHE dentro le virgolette. Misurato il 01/08 — spezzando il
   file sugli a-capo, un bonifico da 12.300 € diventava due righe rotte e
   veniva scartato: lo scarto era dichiarato, quindi non silenzioso, ma il
   pagamento non si abbinava e la fattura restava aperta con la sua mora. */
{
  const conACapo = (testo) => {
    /* mette un a-capo DENTRO la causale della prima riga di movimento, che è
       esattamente come lo scrive una banca */
    const righe = testo.split("\n");
    const i = righe.findIndex((r, k) => k > 0 && r.includes(";"));
    const cel = righe[i].split(";");
    cel[2] = '"' + cel[2].replace(/^"|"$/g, "") + '\nSALDO FATTURA 2026/034"';
    righe[i] = cel.join(";");
    return { testo: righe.join("\n"), riga: i };
  };

  test("⛔ shared: il lettore di CSV è UNO, e Sentinella lo ri-esporta", () => {
    ok(sentinella.leggiCsv === shell.leggiCsv,
       "deve ESSERE quello di shared, non una copia che si comporta uguale");
  });

  test("⛔ Conti: una causale su due righe non fa sparire l'incasso", () => {
    const base = conti.parseMovimentiCsv(conti.ESTRATTO_ESEMPIO);
    eq(base.filter(x => x.scarto).length, 0, "il file d'esempio si legge tutto");
    const { testo, riga } = conACapo(conti.ESTRATTO_ESEMPIO);
    const dopo = conti.parseMovimentiCsv(testo);
    eq(dopo.length, base.length,
       "⛔ stesso numero di movimenti: l'a-capo dentro le virgolette NON è una riga nuova");
    eq(dopo.filter(x => x.scarto).length, 0, "e nessuno viene scartato");
    const tocc = dopo[riga - 1];
    ok(tocc.descrizione.includes("\n"), "la causale arriva intera, a capo compreso");
    eq(tocc.importo, base[riga - 1].importo, "e l'importo è quello di prima, non perso");
    eq(dopo.map(x => x.importo), base.map(x => x.importo), "nessun importo si sposta di riga");
  });

  test("shared: leggiCsv regge quello che un file di banca porta davvero", () => {
    const r = (t) => shell.leggiCsv(t).righe;
    eq(r('a;b\n1;2').length, 2, "due righe");
    eq(r('a;"b\nc";d')[0], ["a", "b\nc", "d"], "a capo dentro le virgolette: una cella sola");
    eq(r('a;"vir""golette";c')[0], ["a", 'vir"golette', "c"], "virgolette raddoppiate");
    eq(r('\uFEFFa;b')[0], ["a", "b"], "il BOM non diventa parte della prima cella");
    eq(r('a;b\r\nc;d').length, 2, "terminatori Windows");
    eq(r('a;b\n\n\nc;d').length, 2, "le righe vuote spariscono");
    eq(shell.leggiCsv("a,b,c\n1,2,3").delim, ",", "separatore deciso sul file: qui la virgola");
    eq(shell.leggiCsv('a;b\n"x,y,z";2').delim, ";",
       "⛔ e le virgole DENTRO le virgolette non votano: se no un file col punto e virgola verrebbe letto a virgole");
    eq(shell.leggiCsv("").righe, [], "testo vuoto");
    eq(shell.leggiCsv(null).righe, [], "niente");
  });
}

/* ══ SHARED · LA RISPOSTA A UN FATTO: UNA REGOLA, NON DUE COPIE ══
   `statoPonte` di Sentinella e `statoRisposta` di Campo erano identiche —
   misurate byte per byte, 806 contro 809 caratteri, differenti solo nel nome.
   Adesso vivono in `shared/dw-ponti.js` e le due app le ri-esportano.
   ⛔ E LA PROVA PRETENDE L'IDENTITÀ, NON IL COMPORTAMENTO: due funzioni che
   oggi rispondono uguale sono due funzioni, e domani sono due comportamenti —
   il giorno in cui una impara a distinguere «in ritardo» da «da chiudere»,
   l'altra resta indietro e le prove di tutt'e due restano verdi. */
{
  test("⛔ shared: la risposta a un fatto è UNA funzione, e le due app la ri-esportano", () => {
    ok(sentinella.statoPonte === ponti.statoPonte,
       "Sentinella deve ESSERE quella di shared, non una copia che si comporta uguale");
    ok(campo.statoRisposta === ponti.statoPonte,
       "e Campo pure: `statoRisposta` è l'alias con cui la sua pagina l'ha sempre chiamata");
    ok(sentinella.azioniDiOrigine === ponti.azioniDiOrigine, "e il filtro delle azioni idem");
  });

  test("⛔ shared: nessuna azione è ROSSA — l'assenza di una risposta non è una risposta buona", () => {
    contiene(ponti.statoPonte([]), { n: 0, cls: "danger", label: "Nessuna azione" }, "elenco vuoto");
    contiene(ponti.statoPonte(null), { n: 0, cls: "danger" }, "e nemmeno l'elenco che non c'è");
    contiene(ponti.statoPonte(undefined), { cls: "danger" }, "idem");
  });

  test("shared: i tre stati della risposta, e il plurale giusto", () => {
    const az = (...st) => st.map(stato => ({ stato }));
    contiene(ponti.statoPonte(az("chiusa")), { cls: "ok", label: "Azione chiusa", daChiudere: 0 }, "una sola, chiusa");
    contiene(ponti.statoPonte(az("chiusa", "chiusa")), { cls: "ok", label: "2 azioni chiuse" }, "due chiuse");
    contiene(ponti.statoPonte(az("in-corso")), { cls: "warn", label: "Azione in corso" }, "una in corso");
    contiene(ponti.statoPonte(az("in-corso", "in-corso")), { cls: "warn", label: "2 azioni in corso" }, "due in corso");
    contiene(ponti.statoPonte(az("aperta")), { cls: "warn", label: "1 azione da chiudere" },
       "aperta ma non in corso: si dice «da chiudere», che è la cosa vera");
    contiene(ponti.statoPonte(az("chiusa", "in-corso")), { cls: "warn", label: "Azione in corso", chiuse: 1 },
       "mista: comanda quella che resta aperta");
  });

  test("shared: `azioniDelFermo` di Campo è quella di shared col tipo fissato", () => {
    const A = [{ origineTipo: "fermo", origineId: "t1", stato: "in-corso" },
               { origineTipo: "fermo", origineId: "t2" },
               { origineTipo: "nc", origineId: "t1" }];
    eq(campo.azioniDelFermo(A, "t1"), ponti.azioniDiOrigine(A, "fermo", "t1"),
       "stessa risposta perché è la stessa funzione, non perché si somigliano");
    eq(campo.azioniDelFermo(A, ""), [], "senza id non si indovina: elenco vuoto");
    eq(ponti.azioniDiOrigine(A, "fermo", "t1", "").length, 1,
       "la voce vuota NON filtra: vuol dire «tutte quelle di questa origine»");
    eq(ponti.azioniDiOrigine([{ origineTipo: "sup", origineId: "p1", origineVoce: "2026-07-01" },
                              { origineTipo: "sup", origineId: "p1", origineVoce: "2026-07-08" }],
                             "sup", "p1", "2026-07-08").length, 1,
       "e con la voce filtra: in Sentinella lo stesso punto supera in più giorni");
  });
}

/* ══ SHARED · LA GRAFFETTA: LA REGOLA DELL'ALLEGATO, UNA SOLA ══
   Stava scritta a mano dentro `apps/scudo/index.html`. Da oggi serve anche a
   Sentinella (il documento consegnato all'ente accanto alla sua scadenza),
   quindi vive in `shared/` — e la versione condivisa copre tre casi che
   quella di casa non guardava. */
{
  const f = (name, size) => ({ name, size });

  test("shared: un allegato dentro il limite passa, e dice quanto pesa", () => {
    eq(shell.controllaAllegato(f("scan.pdf", 120 * 1024)),
       { ok: true, motivo: "", kb: 120, peso: "120 KB", nome: "scan.pdf" }, "file buono");
    /* ⛔ «0 KB» è il numero con cui questa stessa funzione dice «vuoto»:
       trovato provando il modulo davvero, non leggendo il codice. */
    eq(shell.controllaAllegato(f("ricevuta.pdf", 23)).peso, "meno di 1 KB",
       "un file valido di 23 byte non può annunciarsi «0 KB»");
    eq(shell.controllaAllegato(f("x.pdf", 1024)).peso, "1 KB", "da un chilobyte in su si scrive il numero");
    eq(shell.controllaAllegato(f("x.pdf", 0)).peso, "0 KB", "e il vuoto sì, perché è vero");
    eq(shell.controllaAllegato(f("x.pdf", shell.LIMITE_ALLEGATO)).ok, true, "il limite esatto è compreso");
    eq(shell.controllaAllegato(f("x.pdf", shell.LIMITE_ALLEGATO + 1)).motivo, "troppo-grande", "un byte oltre no");
    eq(shell.controllaAllegato(f("  foto.jpg  ", 10)).nome, "foto.jpg", "il nome si ripulisce");
    eq(shell.controllaAllegato(f("x.pdf", 200 * 1024), 100 * 1024).motivo, "troppo-grande", "il limite si può stringere");
  });

  test("⛔ shared: i tre casi che la versione scritta in casa non guardava", () => {
    /* la copia dentro Scudo controllava SOLO `f.size > 400*1024` */
    eq(shell.controllaAllegato(f("x.pdf", 0)).motivo, "vuoto",
       "un file vuoto non è un file piccolo: la graffetta non aprirebbe niente");
    eq(shell.controllaAllegato(f("", 100)).motivo, "senza-nome", "un file senza nome");
    eq(shell.controllaAllegato(f("x.pdf", undefined)).motivo, "dimensione-ignota", "una dimensione illeggibile");
    eq(shell.controllaAllegato(null).motivo, "nessuno", "e nessun file affatto");
  });

  test("shared: ogni motivo di rifiuto ha la sua frase (regola 18)", () => {
    for (const caso of [null, f("", 1), f("x", undefined), f("x", 0), f("x", 9e9)]) {
      const via = shell.controllaAllegato(caso);
      ok(!via.ok, "questo caso deve essere rifiutato");
      ok(shell.testoAllegatoRifiutato(via).length > 10,
         `manca la frase per «${via.motivo}»: la pagina mostrerebbe un errore vuoto`);
    }
    ok(/600 KB/.test(shell.testoAllegatoRifiutato(shell.controllaAllegato(f("x", 600 * 1024)))),
       "e quella del troppo grande dice quanto pesa davvero");
    eq(shell.testoAllegatoRifiutato({ motivo: "" }), "", "un esito buono non ha niente da dire");
  });

  test("shared: un dataURL si scompone, e quello che dataURL non è torna null", () => {
    eq(shell.pezziDataURL("data:application/pdf;base64,AAAA"),
       { mime: "application/pdf", base64: true, contenuto: "AAAA" }, "normale");
    eq(shell.pezziDataURL("data:text/plain;charset=utf-8,ciao"),
       { mime: "text/plain", base64: false, contenuto: "ciao" }, "col charset: il tipo resta quello");
    eq(shell.pezziDataURL("data:;base64,AAAA").mime, "application/octet-stream", "senza tipo, il ripiego");
    eq(shell.pezziDataURL("data:text/csv,a,b,c").contenuto, "a,b,c", "le virgole del contenuto non spezzano");
    for (const brutto of ["https://x/y.pdf", "", null, "data:application/pdf;base64"])
      ok(shell.pezziDataURL(brutto) === null,
         `«${brutto}» non è un dataURL: deve tornare null, non un tipo inventato`);
  });
}

/* ══ L'HARNESS: `mostra` DISTINGUE QUELLO CHE `JSON.stringify` CONFONDEVA ══
   Le prove di uno strumento di prova. Ci sono perché il difetto che
   correggono è stato trovato per caso — una controprova che rispondeva
   «non distingue» pur avendo il difetto rimesso dentro — e uno strumento
   condiviso da tutte le regole non è controllato da nessuna. */
{
  const uguali = (a, b) => mostra(a) === mostra(b);

  test("⛔ harness: i quattro valori che JSON.stringify appiattiva su «null»", () => {
    for (const v of [Infinity, -Infinity, NaN]) {
      ok(JSON.stringify(v) === "null", "il difetto di partenza è ancora quello: JSON.stringify lo scrive «null»");
      ok(!uguali(null, v), `«non calcolabile» e ${mostra(v)} adesso si distinguono`);
    }
    eq(mostra(Infinity), "Infinity", "e si legge, invece di sparire");
    eq(mostra(NaN), "NaN", "idem");
    ok(!uguali(null, undefined), "e «non c'è la chiave» non è «la chiave vale null»");
  });

  test("⛔ harness: il caso vero che ha fatto scoprire il buco", () => {
    /* una variazione percentuale calcolata partendo da zero: la risposta
       giusta è «non esiste», quella sbagliata è Infinity — e le due
       passavano per la stessa prova */
    const giusta = (prima, dopo) => prima === 0 ? null : (dopo - prima) / prima * 100;
    const rotta  = (prima, dopo) => (dopo - prima) / prima * 100;
    eq(giusta(0, 45), null, "da zero la variazione non esiste");
    ok(!uguali(giusta(0, 45), rotta(0, 45)),
       "e la versione rotta NON passa più per quella asserzione: è il difetto che si voleva prendere");
    eq(rotta(0, 45), Infinity, "perché quello che produce è Infinity, non null");
  });

  test("harness: meno zero, e la chiave che vale undefined", () => {
    ok(JSON.stringify(-0) === "0" && JSON.stringify({ a: undefined }) === "{}",
       "i due difetti minori di partenza");
    ok(!uguali(0, -0), "in geometria il meno zero è un lato, non un pareggio");
    ok(!uguali({}, { a: undefined }), "un campo mai messo non è un campo messo vuoto");
    ok(!uguali({ a: null }, { a: NaN }), "e dentro un oggetto la distinzione regge lo stesso");
  });

  test("harness: quello che NON è cambiato, perché 2.389 asserzioni ci poggiano", () => {
    eq(mostra(3.5), "3.5", "numero");
    eq(mostra("ciao"), '"ciao"', "stringa");
    eq(mostra([1, "a", null]), '[1,"a",null]', "array");
    eq(mostra({ b: 1, a: 2 }), '{"b":1,"a":2}', "oggetto: resta l'ordine di INSERIMENTO, non l'alfabeto");
    eq(mostra({ a: [{ b: null }] }), '{"a":[{"b":null}]}', "annidato");
    eq(mostra(new Date("2026-08-01T00:00:00Z")), '"2026-08-01T00:00:00.000Z"', "data, come la scriveva prima");
    ok(uguali({ x: 1 }, { x: 1 }), "e due oggetti uguali restano uguali");
  });

  test("harness: un ciclo non fa più esplodere la prova con un errore che parla d'altro", () => {
    const c = { a: 1 }; c.se = c;
    eq(mostra(c), '{"a":1,"se":[ciclo]}', "si scrive, invece di lanciare");
    eq(mostra(new Date("non è una data")), "Data(non valida)", "e una data non valida si vede");
    ok(!uguali(new Set([1]), {}), "un Set non è un oggetto vuoto");
    ok(!uguali(new Map([["a", 1]]), {}), "e nemmeno una Map");
  });
}

// ── Flotta · il salvataggio che non riesce ────────────────────────────────
// MISURATO il 01/08 col pacchetto `firebase` vero (12.16.0) e la rete chiusa
// (`disableNetwork`): su quattro chiamate, le tre SCRITTURE (`addDoc` di un
// controllo, `addDoc` di una manutenzione, `updateDoc` delle ore) non
// risolvono e non rifiutano — restano pendenti per sempre; la lettura
// risponde in 8 ms dalla cache. Quindi il difetto non è un errore da
// catturare: è una promessa che non torna, e un `try/catch` non la vede.
// Flotta è l'app che si usa davanti alla macchina, dove la rete non c'è: il
// giro macchina e la segnalazione di guasto si fermavano sull'`await`, senza
// toast, senza errore, con la scheda ferma. Queste prove difendono l'unica
// risposta accettabile: SEMPRE una risposta, e quando non è «salvato» non lo
// deve sembrare.
{
  /* ⚠️ `test` è sincrono: passandogli una funzione `async` il suo `try` non
     vede niente e l'esito non viene contato. Qui serve l'attesa vera, quindi
     un aiuto locale che aspetta prima di contare. */
  const provaSalv = async (nome, fn) => {
    try { await fn(); passed++; console.log(`  ✓ ${nome}`); }
    catch (e) { failed++; console.error(`  ✗ ${nome}: ${e.message}`); }
  };
  const mai = () => new Promise(() => {});
  const rompi = (codice) => () => { const e = new Error("x"); e.code = codice; throw e; };
  let nonGestiti = 0;
  const spiaRifiuti = (r) => { nonGestiti++; };
  process.on("unhandledRejection", spiaRifiuti);

  await provaSalv("Flotta · scrittura riuscita: nessun messaggio, esito «fatto»", async () => {
    const r = await flotta.scriviConEsito(async () => 1, { cosa: "il giro macchina", attesa: 60 });
    ok(r.ok === true && r.esito === "fatto", "esito atteso «fatto», ottenuto «" + r.esito + "»");
    eq(r.messaggio, "", "una scrittura riuscita non ha niente da dire");
  });

  await provaSalv("Flotta · scrittura rifiutata: lo dice, col codice del server", async () => {
    const r = await flotta.scriviConEsito(rompi("permission-denied"), { cosa: "il giro macchina", attesa: 60 });
    ok(r.ok === false && r.esito === "errore", "esito atteso «errore», ottenuto «" + r.esito + "»");
    ok(/permission-denied/.test(r.messaggio), "il codice del server sta nel messaggio: " + r.messaggio);
    ok(/ancora qui/.test(r.messaggio), "e dice che quello che ha scritto non è andato perso: " + r.messaggio);
  });

  await provaSalv("Flotta · la scrittura MUTA (il caso vero senza rete) risponde lo stesso", async () => {
    const t0 = Date.now();
    const r = await flotta.scriviConEsito(mai, { cosa: "il giro macchina", attesa: 80, inRete: false });
    ok(r.ok === false && r.esito === "in-sospeso", "esito atteso «in-sospeso», ottenuto «" + r.esito + "»");
    ok(Date.now() - t0 >= 70, "ha aspettato l'attesa dichiarata, non è tornata subito");
    ok(/non ha ricevuto/.test(r.messaggio) && /senza linea/.test(r.messaggio), "messaggio: " + r.messaggio);
  });

  await provaSalv("Flotta · ⛔ un salvataggio non riuscito non dice MAI «salvato»", async () => {
    // il principio del fondatore, nella forma che riguarda questa funzione: la
    // parola tranquilla dove non è stato misurato niente.
    for (const [esito, extra] of [["errore", {}], ["errore", { dettaglio: "unavailable" }],
                                  ["in-sospeso", { inRete: false }],
                                  ["in-sospeso", { inRete: true }], ["in-sospeso", {}]]) {
      const m = flotta.messaggioScrittura(esito, "il giro macchina", extra);
      ok(/non è stato salvato niente/i.test(m), "va detto per esteso che non c'è niente, esito «" + esito + "»: " + m);
      // e l'UNICA volta che compare la parola «salvato» è dentro quella
      // negazione: qualunque altra occorrenza sarebbe la parola tranquilla
      // dove non è stato misurato niente.
      ok(!/salvat/i.test(m.replace(/non è stato salvato niente/i, "")),
         "«salvato» compare fuori dalla negazione, esito «" + esito + "»: " + m);
    }
  });

  await provaSalv("Flotta · la frase regge anche su un soggetto femminile", async () => {
    // il prototipo del 01/08 scriveva «La segnalazione NON risulta salvato»:
    // la stessa frase serve a un giro (maschile) e a una segnalazione
    // (femminile), quindi non può contenere un participio che concorda.
    // La prova vera è che la frase sia la STESSA a meno del soggetto: se da
    // qualche parte restasse un participio che concorda, togliendo i due
    // soggetti i due testi non coinciderebbero.
    let confronti = 0;
    for (const [esito, extra] of [["errore", { dettaglio: "unavailable" }],
                                  ["in-sospeso", { inRete: false }],
                                  ["in-sospeso", { inRete: true }], ["in-sospeso", {}]]) {
      const f = flotta.messaggioScrittura(esito, "la segnalazione del guasto", extra);
      const m = flotta.messaggioScrittura(esito, "il giro macchina", extra);
      ok(f.includes("la segnalazione del guasto"), "il soggetto femminile c'è: " + f);
      ok(m.includes("il giro macchina"), "il soggetto maschile c'è: " + m);
      eq(f.replace("la segnalazione del guasto", "·"), m.replace("il giro macchina", "·"),
         "esito «" + esito + "»: tolto il soggetto le due frasi devono coincidere");
      confronti++;
    }
    eq(confronti, 4, "quattro forme del messaggio messe a confronto");
  });

  await provaSalv("Flotta · tre spiegazioni diverse, e «connesso» non è un'assoluzione", async () => {
    const senza = flotta.messaggioScrittura("in-sospeso", "il giro", { inRete: false });
    const con = flotta.messaggioScrittura("in-sospeso", "il giro", { inRete: true });
    const boh = flotta.messaggioScrittura("in-sospeso", "il giro", {});
    ok(/senza linea/.test(senza), "senza linea: " + senza);
    // `navigator.onLine === true` non vuol dire che c'è internet: la frase lo
    // dichiara («risulta connesso»), non lo dà per buono.
    ok(/risulta connesso/.test(con) && /non ha risposto/.test(con), "connesso ma muto: " + con);
    ok(!/senza linea/.test(boh) && !/risulta connesso/.test(boh), "non sapendolo, non se lo inventa: " + boh);
    ok(new Set([senza, con, boh]).size === 3, "tre casi, tre frasi diverse");
  });

  await provaSalv("Flotta · la scrittura che arriva DOPO la scadenza viene detta", async () => {
    let poi = null, sblocca;
    const lenta = new Promise((r) => { sblocca = r; });
    const r = await flotta.scriviConEsito(() => lenta, { cosa: "il giro", attesa: 40, poi: (x) => { poi = x; } });
    ok(r.esito === "in-sospeso", "prima risposta in-sospeso");
    ok(poi === null, "e finché non arriva non si dice niente");
    sblocca(1);
    await new Promise((r2) => setTimeout(r2, 30));
    ok(poi && poi.ok === true && poi.esito === "fatto", "arrivata dopo: il richiamo lo dice");
  });

  await provaSalv("Flotta · il rifiuto tardivo viene detto e non resta non gestito", async () => {
    const prima = nonGestiti;
    let poi = null, spacca;
    const rotta = new Promise((_, rj) => { spacca = rj; });
    const r = await flotta.scriviConEsito(() => rotta, { cosa: "il giro", attesa: 40, poi: (x) => { poi = x; } });
    ok(r.esito === "in-sospeso", "prima risposta in-sospeso");
    const e = new Error("boom"); e.code = "unavailable"; spacca(e);
    await new Promise((r2) => setTimeout(r2, 30));
    ok(poi && poi.ok === false && /unavailable/.test(poi.messaggio), "il rifiuto tardivo ha una frase: " + (poi && poi.messaggio));
    eq(nonGestiti - prima, 0, "e nessun rifiuto è rimasto non gestito");
  });

  await provaSalv("Flotta · un lancio sincrono finisce fra gli esiti, non sfugge", async () => {
    const r = await flotta.scriviConEsito(() => { throw new Error("sincrono"); }, { cosa: "il giro", attesa: 60 });
    ok(r.ok === false && r.esito === "errore", "esito «errore», ottenuto «" + r.esito + "»");
    ok(/sincrono/.test(r.messaggio), "col motivo dentro: " + r.messaggio);
  });

  await provaSalv("Flotta · nel toast va UNA cosa sola, e la cosa è «non è salvato»", async () => {
    /* Visto sullo SCATTO, non leggendo il codice: col messaggio lungo dentro
       il toast, la pastiglia semitrasparente diventava di nove righe sopra la
       checklist, e nella segnalazione di guasto copriva il bottone «Segnala».
       La regola era già scritta in `guaErrore` dentro Flotta. */
    let visti = 0;
    for (const [esito, extra] of [["errore", { dettaglio: "permission-denied" }],
                                  ["in-sospeso", { inRete: false }],
                                  ["in-sospeso", { inRete: true }], ["in-sospeso", {}]]) {
      const b = flotta.messaggioScritturaBreve(esito, "il giro macchina di Escavatore E1", extra);
      const lungo = flotta.messaggioScrittura(esito, "il giro macchina di Escavatore E1", extra);
      ok(b.length <= 70, `il breve sta in una riga di pastiglia (${b.length} caratteri): ${b}`);
      ok(b.length < lungo.length / 2, "e resta molto più corto della riga sotto il modulo");
      ok(/^Non è stato salvato niente/.test(b), "comincia dalla cosa che conta: " + b);
      visti++;
    }
    eq(visti, 4, "quattro forme del breve guardate");
    eq(flotta.messaggioScritturaBreve("fatto", "il giro"), "", "e una scrittura riuscita non fa toast d'errore");
    // il breve NON nomina la macchina: il nome sta nella riga lunga, dove c'è
    // spazio, e nella pastiglia mangerebbe la metà utile
    ok(!/Escavatore/.test(flotta.messaggioScritturaBreve("errore", "il giro macchina di Escavatore E1", {})),
       "il breve non si porta dietro il nome della macchina");
  });

  await provaSalv("Flotta · scriviConEsito restituisce tutti e due i testi", async () => {
    const r = await flotta.scriviConEsito(rompi("unavailable"), { cosa: "il giro macchina", attesa: 60 });
    ok(typeof r.breve === "string" && r.breve.length > 0, "c'è il breve per il toast: " + r.breve);
    ok(r.messaggio.length > r.breve.length, "e il lungo per la riga sotto il modulo");
    ok(/unavailable/.test(r.messaggio) && !/unavailable/.test(r.breve),
       "il codice del server sta nel lungo, non nella pastiglia");
  });

  await provaSalv("Flotta · l'attesa predefinita è dichiarata e ragionevole", async () => {
    ok(Number.isFinite(flotta.ATTESA_SCRITTURA) && flotta.ATTESA_SCRITTURA >= 3000 && flotta.ATTESA_SCRITTURA <= 20000,
       "un'attesa in secondi, non infinita né istantanea: " + flotta.ATTESA_SCRITTURA);
    // e senza `attesa` fra le opzioni si usa quella: una scrittura riuscita
    // torna subito, quindi la prova resta veloce
    const r = await flotta.scriviConEsito(async () => 1, { cosa: "il giro" });
    ok(r.ok, "il valore predefinito non rompe il caso buono");
  });

  process.off("unhandledRejection", spiaRifiuti);
}

// ── Campo · ponte anomalia → azione ────────────────────────────────────
/* PONTE P4 · «avete registrato il problema, e poi?». Al fronte si registra
   causale e minuti di fermo, e lì la riga moriva: nessun responsabile,
   nessuna data, nessuna chiusura. La macchina che dà seguito a un fatto è
   già in Scudo (azioni correttive), e qui si aggiunge solo la provenienza
   `origineTipo: "fermo"` — il gemello di quella che Sentinella usa per i
   superamenti. Queste prove difendono le tre cose che si possono sbagliare
   in silenzio: che un fermo senza risposta risulti «a posto», che «non lo
   so» diventi «non c'è», e che un tempo non misurato diventi zero. */
{
  const FERMI = [
    { id: "f1", data: "2026-07-30", turno: "Mattina", titolo: "Frantoio primario",
      dettaglio: "tramoggia intasata", squadra: "Squadra C — Impianto",
      stato: "anomalia", causale: "Intasamento impianto", fermoMin: 55 },
    { id: "f2", data: "2026-08-01", turno: "Notte", titolo: "Pala gommata",
      stato: "anomalia", causale: "Guasto meccanico" },                    // senza minuti
    { id: "f3", data: "", turno: "Mattina", titolo: "Nastro trasportatore",
      stato: "anomalia", causale: "", fermoMin: 20 },                      // senza data né causale
    { id: "f4", data: "2026-08-01", turno: "Mattina", titolo: "Perforazione fronte Est",
      stato: "in-corso" },                                                 // non è un fermo
  ];
  const azioneSu = (id, stato) => ({ id: "az-" + id, descrizione: "x", stato: stato || "aperta",
    scadenza: "2026-08-31", origineTipo: "fermo", origineApp: "campo", origineId: id });

  test("Campo: i fermi che chiedono una risposta sono le attività ANCORA in anomalia", () => {
    const f = campo.anomalieAperte(FERMI);
    eq(f.map(x => x.id), ["f3", "f2", "f1"],
       "tre fermi: il senza data in cima, poi dal più recente; l'attività in corso resta fuori");
    eq(f.map(x => x.voce), ["senza-data", "2026-08-01", "2026-07-30"], "la voce dice a che giorno appartiene il fatto");
    eq(campo.anomalieAperte([]).length, 0, "nessuna attività, nessun fermo");
  });

  test("⛔ Campo: un fermo senza minuti NON vale zero minuti", () => {
    const f = campo.anomalieAperte(FERMI);
    const senza = f.find(x => x.id === "f2"), con = f.find(x => x.id === "f1");
    /* `+null` fa 0 e `Number.isFinite(0)` risponde true: senza la guardia
       PRIMA della conversione, «nessuno ha misurato» diventerebbe «zero minuti
       persi», cioè un turno che si è fermato senza perdere tempo. */
    ok(senza.minuti === null, "il fermo senza minuti risponde null, non 0");
    eq(senza.minutiTesto, "senza minuti", "e a parole lo dice");
    eq(con.minutiTesto, "55 min", "mentre quello misurato scrive la misura");
    // lo zero SCRITTO conta come non misurato: in cava un fermo di zero minuti
    // non è un fermo, ed è la stessa convenzione del campo nella pagina
    ok(campo.anomalieAperte([{ id: "z", stato: "anomalia", titolo: "T", fermoMin: 0 }])[0].minuti === null,
       "e nemmeno uno zero scritto a mano diventa una misura");
  });

  test("Campo: una causale fuori dall'elenco standard non si traduce in «Altro»", () => {
    const f = campo.anomalieAperte(FERMI);
    eq(f.find(x => x.id === "f3").causale, "", "la casella non compilata resta vuota");
    eq(f.find(x => x.id === "f1").causale, "Intasamento impianto", "quella scelta resta quella scelta");
    /* «Altro» è una SCELTA che qualcuno ha fatto; il vuoto è una casella che
       nessuno ha toccato. `riepilogoFermi` li accorpa perché deve fare un
       Pareto, qui si distinguono perché la bozza li scrive in modo diverso. */
    eq(campo.riepilogoFermi([FERMI[2]]).map(x => x.causale), ["Altro"],
       "il Pareto invece li accorpa, ed è giusto: lì serve una categoria");
  });

  test("⛔ Campo: un fermo senza azione collegata è SCOPERTO, non «a posto»", () => {
    const c = campo.coperturaFermi(FERMI, []);
    contiene(c, { totale: 3, conAzione: 0, scoperti: 3, daChiudere: 0, leggibile: true },
             "nessuna azione registrata: tutti e tre scoperti");
    eq(c.senzaMinuti, 1, "e uno di loro è anche senza minuti");
    eq(c.senzaCausale, 1, "e uno senza causale");
    const c2 = campo.coperturaFermi(FERMI, [azioneSu("f1")]);
    contiene(c2, { conAzione: 1, scoperti: 2, daChiudere: 1 }, "con un'azione su f1: uno coperto, due scoperti");
    const c3 = campo.coperturaFermi(FERMI, [azioneSu("f1", "chiusa")]);
    eq(c3.daChiudere, 0, "chiusa l'azione, non resta niente da chiudere");
    eq(c3.conAzione, 1, "ma il fermo resta uno di quelli che una risposta l'hanno avuta");
  });

  test("⛔ Campo: se Scudo non si legge, «non lo so» NON diventa «non c'è»", () => {
    const c = campo.coperturaFermi(FERMI, null);
    /* La bandiera `leggibile` esiste per questo: senza, la riga scriverebbe
       «0 con un'azione» anche quando nessuno ha potuto chiedere. */
    ok(c.leggibile === false, "la bandiera dichiara che non si è potuto guardare");
    ok(c.conAzione === null, "quanti hanno un'azione: non si sa");
    ok(c.scoperti === null, "e nemmeno quanti sono scoperti");
    ok(c.daChiudere === null, "né quante restino da chiudere");
    eq(c.totale, 3, "il conto dei fermi però lo sa lo stesso: è roba di Campo");
    ok(c.motivo.length > 40, "e il perché è scritto per chi legge");
    const v = campo.fermiEAzioni(FERMI, null);
    ok(v.every(x => x.azioni === null && x.risposta === null),
       "anche riga per riga: nessuna lista vuota che si leggerebbe «nessuna azione»");
  });

  test("Campo: il semaforo della risposta — «nessuna» è ROSSA", () => {
    contiene(campo.statoRisposta([]), { n: 0, cls: "danger", label: "Nessuna azione" },
             "l'assenza di una risposta non è una risposta buona");
    contiene(campo.statoRisposta([{ stato: "chiusa" }]), { cls: "ok", label: "Azione chiusa" }, "una chiusa");
    contiene(campo.statoRisposta([{ stato: "chiusa" }, { stato: "chiusa" }]),
             { cls: "ok", label: "2 azioni chiuse" }, "due chiuse");
    contiene(campo.statoRisposta([{ stato: "in-corso" }]), { cls: "warn", label: "Azione in corso" }, "una in corso");
    contiene(campo.statoRisposta([{ stato: "chiusa" }, { stato: "aperta" }]),
             { cls: "warn", daChiudere: 1, label: "1 azione da chiudere" }, "una chiusa e una aperta");
  });

  test("Campo: azioniDelFermo non confonde due fermi, e guarda solo le azioni nate da un fermo", () => {
    const azi = [azioneSu("f1"), azioneSu("f2"), { id: "x", origineTipo: "evento", origineId: "f1" }];
    eq(campo.azioniDelFermo(azi, "f1").map(a => a.id), ["az-f1"],
       "l'azione nata da un infortunio con lo stesso id NON è di questo fermo");
    eq(campo.azioniDelFermo(azi, "f9").length, 0, "un fermo senza azioni ne ha zero");
    eq(campo.azioniDelFermo(azi, "").length, 0, "e senza id non si indovina niente");
  });

  test("Campo: la bozza dell'azione porta a Scudo la fotografia del fermo", () => {
    const f = campo.anomalieAperte(FERMI).find(x => x.id === "f1");
    const b = campo.bozzaAzioneFermo(f, { scadenza: "2026-08-31", fmtData: (d) => d.slice(8, 10) + "/" + d.slice(5, 7) });
    contiene(b, { origineTipo: "fermo", origineApp: "campo", origineId: "f1", origineVoce: "2026-07-30",
                  origineData: "2026-07-30", stato: "aperta", esito: "", dataChiusura: null,
                  scadenza: "2026-08-31", responsabileId: null },
             "l'azione nasce aperta e dichiara da dove viene");
    /* Scudo non legge le collezioni di Campo: se l'azione non si portasse
       dietro il TESTO del fatto, l'RSPP leggerebbe «origine: fermo f1». */
    ok(b.origineNota.includes("Frantoio primario") && b.origineNota.includes("Intasamento impianto")
       && b.origineNota.includes("55 min") && b.origineNota.includes("Squadra C"),
       "la nota racconta il fermo in italiano: " + b.origineNota);
    ok(b.origineNota.includes("30/07"), "e la data passa dal formattatore che le si dà");
    ok(campo.bozzaAzioneFermo(null) === null, "senza fermo non si inventa nessuna bozza");
  });

  test("⛔ Campo: quello che MANCA sul fermo è dichiarato nell'azione, non taciuto", () => {
    const f = campo.anomalieAperte(FERMI);
    const senzaMin = campo.bozzaAzioneFermo(f.find(x => x.id === "f2"));
    const senzaCau = campo.bozzaAzioneFermo(f.find(x => x.id === "f3"));
    /* È il testo che finisce davanti a un ispettore: una casella vuota taciuta
       lì diventa un fatto che nessuno rimette più a posto. */
    ok(senzaMin.origineNota.includes("tempo perso: senza minuti"),
       "il fermo non misurato lo dice: " + senzaMin.origineNota);
    ok(!/tempo perso: 0/.test(senzaMin.origineNota), "e non scrive zero al posto del non misurato");
    ok(senzaCau.origineNota.includes("causale: non indicata"),
       "la causale mancante lo dice: " + senzaCau.origineNota);
    eq(senzaCau.origineData, "", "e un fermo senza data non se ne inventa una");
    eq(senzaCau.origineVoce, "senza-data", "la voce usa la convenzione che l'ecosistema ha già");
  });

  test("⛔ Campo: rimettere in marcia il frantoio non chiude l'azione correttiva", () => {
    /* Il caso che il prototipo ha fatto venire fuori: quando l'attività torna
       «in corso» esce da `anomalieAperte`, e con lei sparirebbe dalla vista
       l'azione ancora aperta — che quindi non chiuderebbe più nessuno. */
    const ripartito = FERMI.map(a => a.id === "f1" ? { ...a, stato: "in-corso" } : a);
    ok(campo.anomalieAperte(ripartito).every(x => x.id !== "f1"), "f1 non è più un fermo aperto");
    const aperta = campo.fermiEAzioni(ripartito, [azioneSu("f1")]);
    const riga = aperta.find(x => x.id === "f1");
    ok(riga && riga.chiuso === true, "ma con l'azione ancora da chiudere la riga resta, marcata come ripartita");
    eq(aperta[aperta.length - 1].id, "f1", "e sta in fondo, dopo i fermi ancora in corso");
    ok(campo.fermiEAzioni(ripartito, [azioneSu("f1", "chiusa")]).every(x => x.id !== "f1"),
       "chiusa l'azione, la riga esce di scena");
    ok(campo.fermiEAzioni(ripartito, []).every(x => x.id !== "f1"),
       "e un fermo ripartito senza nessuna azione non torna a chiedere niente");
  });

  test("Campo: prima i fermi SCOPERTI, poi quelli che una risposta l'hanno già avuta", () => {
    const v = campo.fermiEAzioni(FERMI, [azioneSu("f3")]);
    eq(v.map(x => x.id), ["f2", "f1", "f3"], "f3 ha un'azione e scende in fondo");
    contiene(v[0].risposta, { n: 0, cls: "danger" }, "chi non ha nessuna azione resta in cima, e in rosso");
    /* ⚠️ ambra, non verde: l'azione c'è ma è ancora da chiudere. Il verde è
       riservato a chi la causa l'ha davvero tolta. */
    contiene(v[2].risposta, { cls: "warn", daChiudere: 1 }, "un'azione aperta non è «tutto a posto»");
  });

  test("Campo: `dataPiuGiorni` è l'ALIAS di shared/, non una seconda implementazione", () => {
    /* Il test pretende l'IDENTITÀ, non il comportamento: due copie uguali oggi
       divergono domani senza che nessuno lo veda (CLAUDE.md). */
    ok(campo.dataPiuGiorni === shell.dataPiuGiorni, "stessa funzione dello shell");
    ok(campo.dataPiuGiorni === scudo.dataPiuGiorni && campo.dataPiuGiorni === sentinella.dataPiuGiorni,
       "e la stessa che hanno già Scudo e Sentinella");
    eq(campo.dataPiuGiorni(30, new Date(2026, 6, 30)), "2026-08-29", "trenta giorni avanti dal 30/07");
  });

  test("Campo: la provenienza «fermo» è dichiarata una volta sola e finisce nell'azione", () => {
    eq(campo.ORIGINE_FERMO, "fermo", "la parola con cui Scudo riconoscerà queste azioni");
    const f = campo.anomalieAperte(FERMI)[0];
    eq(campo.bozzaAzioneFermo(f).origineTipo, campo.ORIGINE_FERMO, "la bozza usa quella, non una copia scritta a mano");
    /* ⛔ e NON è una delle cinque che Scudo già conosce: se lo fosse, un fermo
       finirebbe raccontato come un infortunio o una non conformità. */
    ok(!["evento", "ispezione", "nc", "superamento", "reclamo"].includes(campo.ORIGINE_FERMO),
       "provenienza nuova, non riciclata da un'altra");
    ok(!scudo.daAmbiente({ origineTipo: campo.ORIGINE_FERMO }),
       "e Scudo non la scambia per un fatto ambientale di Sentinella");
  });

  test("⛔ Campo→Scudo: le due sponde del ponte chiamano il fermo con la STESSA parola", () => {
    /* Scudo non può importare il modulo di Campo (l'isolamento dello SDK è per
       organizzazione E per app), quindi la parola è scritta in tutt'e due i
       moduli. È esattamente la coppia che si stacca in silenzio: qui si
       pretende che coincida, come già si fa per i fronti della dimostrazione. */
    eq(scudo.ORIGINI_CAMPO, [campo.ORIGINE_FERMO],
       "se una delle due cambia, l'azione arriva a Scudo e non viene riconosciuta");
    ok(scudo.daCampo(campo.bozzaAzioneFermo(campo.anomalieAperte(FERMI)[0])),
       "Scudo riconosce come sua un'azione preparata da Campo");
    ok(!scudo.daCampo({ origineTipo: "nc" }) && !scudo.daCampo({ origineTipo: "evento" })
       && !scudo.daCampo({}) && !scudo.daCampo(null),
       "e non si prende quello che non è un fermo");
    /* ⛔ le due famiglie NON si sovrappongono: un fermo non è un fatto
       ambientale e un superamento non è un fermo. */
    ok(!scudo.ORIGINI_CAMPO.some(t => scudo.ORIGINI_AMBIENTE.includes(t)),
       "provenienze distinte, non due nomi per la stessa cosa");
    ok(!scudo.daAmbiente(campo.bozzaAzioneFermo(campo.anomalieAperte(FERMI)[0])),
       "e il riepilogo dell'ambiente non conta i fermi di Campo");
  });
}

// ── Conti · abbinamento dei movimenti bancari ──────────────────────────
// L'estratto conto della banca letto e confrontato con le fatture aperte.
// È l'unico punto in cui Conti chiedeva di ribattere un dato che esiste già
// altrove, e la sua assenza degradava tutto il resto: un sollecito con la mora
// ex D.Lgs 231/2002 mandato su una fattura GIÀ PAGATA non è un dettaglio
// sbagliato, è una lettera sbagliata a un cliente.
{
  const fat = (id, numero, cliente, importo, extra = {}) =>
    ({ id, numero, cliente, importo, emessa: "2026-01-10", scadenza: "2026-02-10",
       incassata: false, ...extra });
  const FB = [
    fat("b1", "2026/001", "Edilcave Srl", 1000, { clienteId: "k1" }),
    fat("b2", "2026/002", "Edilcave Srl", 2000, { clienteId: "k1" }),
    fat("b3", "2026/003", "Edilcave Srl", 3000, { clienteId: "k1" }),
    fat("b4", "2026/004", "Stradesud", 5000),
    fat("b5", "2026/005", "Stradesud", 5000),
    fat("b6", "2026/006", "Cave del Sud", 7000, { incassata: true }),
  ];
  const CLB = [{ id: "k1", ragioneSociale: "Edilcave Srl" }];
  const testa = "Data;Valuta;Descrizione;Importo\n";
  const uno = (causale, importo, data = "10/03/2026", fatture = FB, incassi = [], clienti = CLB) =>
    conti.abbinaMovimenti(
      conti.parseMovimentiCsv(`${testa}${data};${data};${causale};${importo}`),
      fatture, incassi, clienti).righe[0];

  /* ⛔ MISURATO PRIMA DI IRRIGIDIRE. `numIt` da solo legge giusto 9 di questi
     15 formati: i sei che restano non chiedono un secondo lettore di numeri,
     chiedono una pulitura prima. Se un giorno qualcuno "semplificasse"
     `importoBancario` chiamando `numIt` e basta, questi sei tornerebbero NaN —
     cioè righe di estratto conto scartate in silenzio. */
  test("Conti · banca: l'importo letto nei formati che scrivono davvero le banche", () => {
    const c = conti.importoBancario;
    eq(c("1.234,56"), 1234.56, "italiano classico, quello dell'home banking");
    eq(c("-1.234,56"), -1234.56, "addebito col segno davanti");
    eq(c("1234,56"), 1234.56, "italiano senza migliaia");
    eq(c("-1234.56"), -1234.56, "inglese: il punto è il decimale");
    eq(c("1,234.56"), 1234.56, "inglese con le migliaia");
    eq(c("1 234,56"), 1234.56, "spazio normale come separatore delle migliaia");
    eq(c("1 234,56"), 1234.56, "spazio unificatore (U+00A0): è quello che scrive Excel");
    eq(c("1 234,56"), 1234.56, "spazio stretto (U+202F)");
    eq(c("1'234.56"), 1234.56, "apostrofo delle migliaia (export di area svizzera)");
    eq(c("1.234,56-"), -1234.56, "segno DOPO il numero: i gestionali di derivazione mainframe scrivono così");
    eq(c("+1.234,56"), 1234.56, "segno più esplicito");
    eq(c("1.234,56 EUR"), 1234.56, "con la valuta appiccicata");
    eq(c("€ 1.234,56"), 1234.56, "col simbolo davanti");
    eq(c("(1.234,56)"), -1234.56, "parentesi tonde = negativo, stile contabile");
    eq(c("18300"), 18300, "intero secco");
    eq(c("0,00"), 0, "uno zero è un numero, non un'assenza");
    ok(Number.isNaN(c("")), "cella vuota: non è zero");
    ok(Number.isNaN(c("-")), "il trattino di alcuni export non è un meno");
    ok(Number.isNaN(c("EUR")), "solo la valuta, senza cifre");
  });

  /* ⛔ LA FORMA DI UNA DATA NON È LA SUA ESISTENZA — e qui la difesa arriva da
     `shared/`: `dataISOEsiste`. `Date.parse("2026-02-30")` non fallisce, fa
     SCORRERE la data al 2 marzo, e un movimento spostato di due giorni falsa i
     giorni medi di pagamento del cliente senza che nulla si accorga. */
  test("Conti · banca: la data del movimento, e quella che non esiste viene scartata", () => {
    const d = conti.isoDaDataItaliana;
    eq(d("12/07/2026"), "2026-07-12", "GG/MM/AAAA, la forma dell'home banking italiano");
    eq(d("12-07-2026"), "2026-07-12", "col trattino");
    eq(d("12.07.2026"), "2026-07-12", "col punto");
    eq(d("2026-07-12"), "2026-07-12", "già in ISO");
    eq(d("12/07/2026 10:30"), "2026-07-12", "con l'ora nella stessa cella");
    eq(d("31/02/2026"), "", "il 31 febbraio non esiste: si scarta, non si fa scorrere");
    eq(d("2026-02-30"), "", "e nemmeno scritto in ISO: è la trappola di Date.parse");
    eq(d("2026-13-45"), "", "una data che ha la forma giusta e non è una data");
    eq(d("12/07/26"), "", "anno a due cifre: si dichiara illeggibile invece di indovinare il secolo");
    eq(d(""), "", "cella vuota");
    eq(d("bonifico"), "", "testo qualunque");
  });

  /* ⛔ NESSUNA RIGA SPARISCE. La riga con la data rotta esce lo stesso, con il
     motivo scritto: un import muto è il modo migliore per perdere dei soldi
     senza accorgersene. È la stessa regola per cui `run-demo.mjs` distingue il
     dato CORROTTO dal dato ASSENTE. */
  test("Conti · banca: il file letto — una colonna, due colonne, e niente che sparisce", () => {
    const uno = conti.parseMovimentiCsv(
      "Data;Data valuta;Descrizione;Importo\n"
      + "12/07/2026;13/07/2026;BONIFICO DA EDILCAVE SRL FATT 2026/031;18.300,00\n"
      + '15/07/2026;15/07/2026;"ORD: STRADESUD; DES: SALDO FT 34";9.750,00\n'
      + "20/07/2026;;COMMISSIONI SU BONIFICO;-2,50\n"
      + "pippo;;RIGA CON LA DATA ROTTA;123,00\n"
      + "22/07/2026;;RIGA SENZA IMPORTO;\n");
    eq(uno.length, 5, "cinque righe di dati: l'intestazione non si conta e nessuna riga sparisce");
    contiene(uno[0], { data: "2026-07-12", valuta: "2026-07-13", importo: 18300, scarto: "" }, "prima riga");
    eq(uno[1].descrizione, "ORD: STRADESUD; DES: SALDO FT 34",
       "il punto e virgola dentro le virgolette non spezza la causale");
    eq(uno[2].importo, -2.5, "l'uscita resta negativa");
    contiene(uno[3], { importo: 123, scarto: "data non riconosciuta" }, "la riga rotta esce, col motivo");
    ok(uno[4].scarto.startsWith("importo non leggibile"), "e anche quella senza importo");
    eq(uno.map((x) => x.riga), [1, 2, 3, 4, 5], "la numerazione delle righe non salta");

    const due = conti.parseMovimentiCsv(
      "Data;Valuta;Descrizione;Entrate;Uscite\n"
      + "12/07/2026;12/07/2026;BONIFICO EDILCAVE;18.300,00;\n"
      + "13/07/2026;13/07/2026;F24;;2.410,00\n");
    eq(due.map((x) => x.importo), [18300, -2410],
       "due colonne dare/avere: l'uscita diventa negativa anche se nel file è scritta senza segno");
  });

  /* Il numero si cerca DAL VERSO GIUSTO: i numeri delle nostre fatture li
     conosciamo, quindi si cerca il numero nella causale — non si indovina
     quali gruppi di cifre della causale siano un numero di fattura. Il verso
     sbagliato prende per numero il giorno del mese e quello del mandato. */
  test("Conti · banca: il numero della fattura dentro la causale, e i falsi che deve rifiutare", () => {
    const n = conti.numeroInCausale;
    eq(n("2026/031", "BONIFICO DA EDILCAVE SRL FATT 2026/031"), "pieno", "il numero intero");
    eq(n("2026/031", "PAGAMENTO FATTURA 031/2026"), "pieno", "e rovesciato, come lo scrivono in molti");
    eq(n("2026/031", "ns fatt 2026 / 031"), "pieno", "con gli spazi attorno alla barra");
    eq(n("2026/031", "SALDO FT 31"), "progressivo", "solo il progressivo, ma con la parola che dice cos'è");
    eq(n("2026/031", "SALDO FT. N. 31 DEL 07/06"), "progressivo", "con «n.» in mezzo");
    eq(n("2026/031", "BONIFICO 31 LUGLIO"), "",
       "⛔ un «31» nudo NON vale: in una causale il 31 è quasi sempre un giorno");
    eq(n("2026/031", "PAGAMENTO FATT 310"), "", "310 non è 31");
    eq(n("2026/031", "PAGAMENTO 2026/0310"), "", "né 2026/0310 è 2026/031");
    eq(n("2026/031", ""), "", "causale vuota");
    eq(n("", "FATT 2026/031"), "", "fattura senza numero");
  });

  test("Conti · banca: il cliente riconosciuto nella causale, senza i falsi da sigla", () => {
    const c = conti.clienteInCausale;
    ok(c("Edilcave Srl", "BONIFICO DA EDILCAVE SRL FATT 2026/031"), "nome intero");
    ok(c("Edilcave Srl", "BONIFICO DA EDILCAVE S.R.L."), "la punteggiatura non conta: è `chiaveNome`");
    ok(c("Edilcave Srl", "ORD: EDILCAVE - SALDO"), "la banca scrive il nome senza la forma societaria");
    ok(c("Comune di Modica", "BONIFICO COMUNE DI MODICA MANDATO 4412"), "un ente");
    ok(!c("Edilcave Srl", "BONIFICO DA EDIL CAVE"), "«Edil Cave» staccato non è «Edilcave»");
    ok(!c("Srl", "BONIFICO DA PIPPO SRL"),
       "⛔ una chiave corta non è un indizio: «Srl» comparirebbe in mezza rubrica");
    ok(!c("", "qualunque cosa"), "cliente senza nome");
  });

  /* ⛔ DUE COMBINAZIONI CHE TORNANO NON SONO UN ABBINAMENTO, SONO UNA SCELTA. */
  test("Conti · banca: la combinazione di fatture risponde solo quando è UNA sola", () => {
    const ap = (v) => v.map((x, i) => ({ id: "x" + i, aperto: x }));
    eq(conti.combinazioneUnica(ap([1000, 2000, 3000]), 3000).map((x) => x.id), ["x0", "x1"],
       "1000+2000 è l'unica combinazione da due o più che fa 3000");
    ok(conti.combinazioneUnica(ap([1000, 2000, 1000, 2000]), 3000) === null,
       "quattro fatture, due modi di fare 3000: non risponde");
    ok(conti.combinazioneUnica(ap([1000, 2000]), 9999) === null, "nessuna combinazione");
    ok(conti.combinazioneUnica(ap([3000]), 3000) === null,
       "una fattura sola non è una combinazione: quel caso lo tratta l'abbinamento diretto");
    ok(conti.combinazioneUnica(ap(new Array(11).fill(10)), 20) === null,
       "oltre il tetto non si cerca: più fatture ci sono, più è probabile che le risposte siano tante");
    eq(conti.combinazioneUnica(ap([0.1, 0.2, 5]), 0.3).map((x) => x.id), ["x0", "x1"],
       "i conti si fanno in centesimi interi: 0,1+0,2 in virgola mobile non fa 0,3");
  });

  test("Conti · banca: CERTO — il numero in causale e l'importo che torna esatto", () => {
    const r = uno("BONIFICO ORD STRADESUD SALDO FATT 2026/004", "5.000,00");
    contiene(r, { grado: "certo", verso: "entrata" }, "grado massimo");
    eq(r.proposta.map((p) => p.fatturaId), ["b4"], "una proposta sola, sulla fattura nominata");
    eq(r.proposta[0].importo, 5000, "e per tutto il movimento");
    ok(/2026\/004/.test(r.perche), "il motivo nomina la fattura: la proposta si spiega, non si impone");
  });

  test("Conti · banca: PROBABILE — l'acconto dichiarato lascia la fattura aperta", () => {
    const r = uno("FATT 2026/003 ACCONTO", "500,00");
    contiene(r, { grado: "probabile" }, "acconto: non è certo, ma la fattura è nominata");
    eq(r.proposta[0].importo, 500, "entra quello che è arrivato, non il totale della fattura");
    eq(r.proposta[0].aperto, 3000, "e si ricorda quanto restava aperto");
    ok(/acconto/.test(r.perche) && /2\.500/.test(r.perche),
       "il motivo dice che resta scoperto: " + r.perche);
  });

  test("Conti · banca: PROBABILE — nessun numero, ma il cliente e l'importo combaciano", () => {
    const r = uno("BONIFICO DA EDILCAVE SRL", "3.000,00");
    contiene(r, { grado: "probabile" }, "cliente + importo esatto: probabile, non certo");
    eq(r.proposta.map((p) => p.fatturaId), ["b3"], "la sua unica fattura aperta da 3.000");
  });

  test("Conti · banca: CERTO — il bonifico cumulativo che nomina le sue fatture", () => {
    const r = uno("PAGAMENTO FATTURE 2026/001 2026/002 2026/003", "6.000,00");
    contiene(r, { grado: "certo" }, "tre numeri e la somma che torna: non c'è niente da indovinare");
    eq(r.proposta.map((p) => p.fatturaId), ["b1", "b2", "b3"], "tre proposte, una per fattura");
    eq(r.proposta.map((p) => p.importo), [1000, 2000, 3000], "ognuna per il suo aperto");
  });

  test("Conti · banca: PROBABILE — il cumulativo non dichiarato, ma con UNA sola combinazione", () => {
    const r = uno("BONIFICO DA EDILCAVE SRL", "6.000,00");
    contiene(r, { grado: "probabile" }, "il cliente c'è e la combinazione è unica");
    eq(r.proposta.map((p) => p.fatturaId), ["b1", "b2", "b3"], "1000+2000+3000");
    ok(/combinazione/.test(r.perche), "e il motivo lo dice: " + r.perche);
  });

  /* ⛔ UN ABBINAMENTO INCERTO NON È UN ABBINAMENTO. Sotto «probabile» la riga
     NON porta nessuna proposta: porta le alternative, e decide l'utente. Se un
     giorno qualcuno facesse scendere questa soglia, sarebbero questi tre casi
     a cadere — e il danno vero è a valle: una fattura marcata incassata senza
     esserlo esce dal sollecito, e il credito si perde in silenzio. */
  test("Conti · banca: DEBOLE — quello che è incerto resta da decidere a mano, senza proposta", () => {
    const due = uno("BONIFICO STRADESUD", "5.000,00");
    contiene(due, { grado: "debole" }, "due fatture identiche dello stesso cliente");
    eq(due.proposta.length, 0, "nessuna proposta: sceglierne una a caso sarebbe peggio di non scegliere");
    eq(due.alternative.map((a) => a.fatturaId), ["b4", "b5"], "ma le alternative ci sono tutte");

    const soloImporto = uno("BONIFICO A NS FAVORE", "1.000,00");
    contiene(soloImporto, { grado: "debole" }, "solo l'importo torna, la causale non dice niente");
    eq(soloImporto.proposta.length, 0, "l'importo da solo non basta a proporre");
    eq(soloImporto.alternative.map((a) => a.fatturaId), ["b1"], "la candidata si mostra lo stesso");

    const troppo = uno("PAGAMENTO FATT 2026/001", "1.500,00");
    contiene(troppo, { grado: "debole" }, "il numero c'è ma l'importo supera la fattura");
    eq(troppo.proposta.length, 0, "e allora paga anche dell'altro: lo decide l'utente");

    const sommaNo = uno("FATT 2026/001 E FATT 2026/002", "9.999,00");
    contiene(sommaNo, { grado: "debole" }, "due numeri in causale ma la somma non torna");
    eq(sommaNo.alternative.length, 2, "tutt'e due le fatture nominate restano in vista");
  });

  /* ⛔ IL CASO CHE HA FATTO NASCERE QUESTO CANTIERE, girato dall'altra parte:
     la causale nomina una fattura GIÀ SALDATA. Prima di questa risposta la riga
     usciva con «nella causale non si riconosce niente» — che è falso, e manda a
     cercare dalla parte sbagliata. */
  test("Conti · banca: la fattura nominata in causale che risulta già saldata viene DETTA", () => {
    const r = uno("PAGAMENTO FATT 2026/006", "7.000,00");
    contiene(r, { grado: "nessuno", verso: "entrata" }, "niente da proporre: non è più aperta");
    eq(r.proposta.length, 0, "e nessuna proposta");
    ok(/2026\/006/.test(r.perche) && /saldat/.test(r.perche),
       "il motivo nomina la fattura e dice che è già a posto: " + r.perche);
    ok(/doppio/.test(r.perche), "e mette in guardia sul pagamento doppio: " + r.perche);
  });

  /* ⛔ LO STESSO ESTRATTO CONTO CARICATO DUE VOLTE. Si scarica a fine mese e si
     ricarica il mese dopo: i giorni si sovrappongono quasi sempre. */
  test("Conti · banca: un movimento già registrato non si ripropone", () => {
    const inc = [{ id: "z1", fatturaId: "b4", data: "2026-03-10", importo: 5000, metodo: "bonifico" }];
    const r = uno("SALDO FATT 2026/004", "5.000,00", "10/03/2026", FB, inc);
    contiene(r, { grado: "nessuno", giaRegistrato: true }, "riconosciuto e messo da parte");
    ok(/due volte/.test(r.perche), "e detto perché: " + r.perche);
    /* la stessa fattura, ma un giorno diverso: è un movimento nuovo e va proposto */
    const altro = uno("SALDO FATT 2026/004", "5.000,00", "11/03/2026", FB, inc);
    ok(!altro.giaRegistrato, "cambiando giorno non è più lo stesso movimento");
    eq(conti.movimentoGiaRegistrato({ data: "2026-03-10", importo: 5000 }, "b4", inc), true, "l'impronta è fattura+giorno+importo");
    eq(conti.movimentoGiaRegistrato({ data: "2026-03-10", importo: 5000 }, "b5", inc), false, "su un'altra fattura no");
    eq(conti.movimentoGiaRegistrato({ data: "", importo: 5000 }, "b4", inc), false, "senza data non si può dire");
  });

  /* ⛔ DUE BONIFICI UGUALI SULLA STESSA FATTURA. Ogni riga è giudicata da sola
     contro l'aperto di partenza — ed è giusto, perché finché non si conferma
     non è successo niente. Ma uscivano tutt'e due «certo, saldo esatto», e chi
     conferma in blocco registra il doppio. Trovato in scratchpad prima che
     entrasse nel modulo. */
  test("Conti · banca: due movimenti che propongono la stessa fattura scendono TUTTI a debole", () => {
    const r = conti.abbinaMovimenti(conti.parseMovimentiCsv(
      testa + "10/03/2026;;SALDO FATT 2026/004;5.000,00\n11/03/2026;;SALDO FATT 2026/004;5.000,00"),
      FB, [], CLB).righe;
    eq(r.map((x) => x.grado), ["debole", "debole"], "nessuno dei due viene proposto");
    eq(r.every((x) => x.proposta.length === 0), true, "e nessuno porta una proposta");
    ok(/incasso che non c'è/.test(r[0].perche), "il motivo spiega il danno: " + r[0].perche);
    eq(r[0].alternative.map((a) => a.fatturaId), ["b4"], "la fattura contesa resta in vista");
    /* e la guardia NON deve scattare quando i due insieme ci stanno: acconto + saldo
       sulla stessa fattura è il caso normale, non un doppione. */
    const sani = conti.abbinaMovimenti(conti.parseMovimentiCsv(
      testa + "10/03/2026;;FATT 2026/003 ACCONTO;1.000,00\n20/03/2026;;FATT 2026/003 SALDO;2.000,00"),
      FB, [], CLB).righe;
    eq(sani.map((x) => x.grado), ["probabile", "probabile"],
       "acconto + saldo che insieme fanno l'aperto non è un doppione");
  });

  test("Conti · banca: le uscite si elencano e si dichiarano, non si abbinano", () => {
    const r = uno("COMMISSIONI E SPESE DI TENUTA CONTO", "-4,50");
    contiene(r, { grado: "nessuno", verso: "uscita" }, "riconosciuta come uscita");
    ok(/costi/.test(r.perche), "e detto dove si registra: " + r.perche);
  });

  /* ⛔ L'ASSENZA DI UN DATO NON È UN DATO FAVOREVOLE: zero movimenti da
     decidere perché nessun file è mai stato caricato NON è «tutto abbinato».
     La bandiera `misurabile` è quella che la schermata legge per mostrare lo
     stato vuoto invece dei contatori a zero (regola 20 di run-stile.mjs). */
  test("Conti · banca: senza estratto conto il riepilogo si dichiara NON misurabile", () => {
    const v = conti.abbinaMovimenti([], FB, [], CLB);
    eq(v.righe.length, 0, "nessuna riga");
    contiene(v.riepilogo, { misurabile: false, letti: 0, daConfermare: 0, daDecidere: 0 },
       "zero contatori, ma dichiarati non misurati");
    ok(/nessun estratto conto/.test(v.riepilogo.perche), "col perché scritto: " + v.riepilogo.perche);
    /* e con dei movimenti torna misurabile: una bandiera che non sa riaccendersi
       non distingue niente */
    const w = conti.abbinaMovimenti(conti.parseMovimentiCsv(testa + "10/03/2026;;X;1,00"), FB, [], CLB);
    contiene(w.riepilogo, { misurabile: true, perche: "" }, "con un movimento si misura davvero");
  });

  /* `riepilogoAbbinamento` si prova anche DA SOLA e non solo attraverso
     `abbinaMovimenti`: è la funzione che porta la bandiera, e una funzione
     provata solo di rimbalzo è una funzione che nessuno ha guardato. */
  test("Conti · banca: il riepilogo chiamato da solo, sulle righe che gli si danno", () => {
    const r = conti.riepilogoAbbinamento([
      { grado: "certo", verso: "entrata", importo: 100, giaRegistrato: false },
      { grado: "probabile", verso: "entrata", importo: 50, giaRegistrato: false },
      { grado: "debole", verso: "entrata", importo: 70, giaRegistrato: false },
      { grado: "nessuno", verso: "entrata", importo: 30, giaRegistrato: false },
      { grado: "nessuno", verso: "entrata", importo: 20, giaRegistrato: true },
      { grado: "nessuno", verso: "uscita", importo: -5, giaRegistrato: false },
      { grado: "nessuno", verso: "scartato", importo: null, giaRegistrato: false },
    ]);
    contiene(r, { letti: 7, entrate: 5, uscite: 1, scartati: 1, certi: 1, probabili: 1,
                  daConfermare: 2, daDecidere: 1, senzaCandidato: 1, giaRegistrati: 1,
                  importoDaConfermare: 150, misurabile: true, perche: "" },
      "ogni riga in una casella sola");
    eq(conti.riepilogoAbbinamento([]).misurabile, false, "lista vuota: non misurabile");
    eq(conti.riepilogoAbbinamento(null).letti, 0, "e null non fa esplodere niente");
    ok(conti.riepilogoAbbinamento(null).perche.length > 0, "col perché scritto anche lì");
  });

  test("Conti · banca: il riepilogo conta ogni riga del file una volta sola", () => {
    const mov = conti.parseMovimentiCsv(conti.ESTRATTO_ESEMPIO);
    const r = conti.abbinaMovimenti(mov, conti.DEMO.fatture, conti.DEMO.incassi, conti.DEMO.clienti);
    const q = r.riepilogo;
    eq(q.letti, mov.length, "una riga di riepilogo per ogni riga del file");
    eq(q.entrate + q.uscite + q.scartati, q.letti,
       "⛔ le tre categorie coprono TUTTO: se non tornassero, una riga sarebbe sparita");
    eq(q.certi + q.probabili, q.daConfermare, "da confermare = certi + probabili");
    eq(q.daConfermare + q.daDecidere + q.senzaCandidato + q.giaRegistrati + q.uscite + q.scartati,
       q.letti, "e ogni riga finisce in uno degli esiti, nessuna in due");
    ok(q.certi >= 2 && q.probabili >= 2 && q.daDecidere >= 1 && q.giaRegistrati >= 1,
       "l'esempio deve contenere davvero tutti i casi che serve mostrare: " + JSON.stringify(q));
    /* ⚠️ La prima stesura di questa riga filtrava su `proposta.length` e falliva:
       una riga GIÀ REGISTRATA conserva la sua proposta (serve a mostrare su quale
       fattura), ma non è da confermare. Corretta la PROVA, non il modulo — che
       aveva ragione. */
    eq(q.importoDaConfermare,
       conti.round2(r.righe.filter((x) => x.grado === "certo" || x.grado === "probabile")
         .reduce((t, x) => t + x.importo, 0)),
       "il totale da confermare è la somma dei movimenti proposti, non delle fatture");
    ok(q.importoDaConfermare < r.righe.reduce((t, x) => t + Math.max(0, +x.importo || 0), 0),
       "e NON è la somma di tutte le entrate: quella comprenderebbe il già registrato e i non abbinati");
  });

  /* ⚠️ UNA PROVA DI ANDATA E RITORNO RESTA VERDE SE LE DUE METÀ SBAGLIANO
     INSIEME: leggere il nostro esempio col nostro lettore dimostra che vanno
     d'accordo FRA LORO, non che il formato sia quello che esporta una banca.
     Per quello serve un'asserzione sul TESTO. */
  test("Conti · banca: l'estratto d'esempio è scritto come lo scrive una banca italiana", () => {
    const t = conti.ESTRATTO_ESEMPIO;
    ok(t.startsWith("Data;"), "intestazione e separatore punto e virgola, come l'export italiano");
    ok(t.includes(";12.300,00"), "punto per le migliaia e virgola per i decimali, non «12300.00»");
    ok(t.includes("21/07/2026"), "data GG/MM/AAAA, non ISO");
    ok(t.includes(";-4,50"), "e almeno un movimento in uscita, col segno davanti");
    ok(!/\d{4}-\d{2}-\d{2}/.test(t), "nessuna data in ISO: sarebbe il nostro formato, non il suo");
    const mov = conti.parseMovimentiCsv(t);
    eq(mov.length, 8, "otto movimenti");
    eq(mov.filter((m) => m.scarto).length, 0, "e il nostro lettore li legge tutti");
    eq(mov[5].importo, 12300, "12.300,00 letto come dodicimilatrecento");
    eq(mov[5].data, "2026-07-21", "e la data convertita in ISO");
  });

  test("Conti · banca: i gradi dichiarati sono tutti e soli quelli che l'abbinamento sa dire", () => {
    eq(conti.GRADI_ABBINAMENTO, ["certo", "probabile", "debole", "nessuno"], "quattro gradi, dal più sicuro");
    const usati = new Set();
    for (const c of [["SALDO FATT 2026/004", "5.000,00"], ["FATT 2026/003 ACCONTO", "500,00"],
                     ["BONIFICO STRADESUD", "5.000,00"], ["SPESE CONTO", "-4,50"]])
      usati.add(uno(c[0], c[1]).grado);
    eq([...usati].sort(), ["certo", "debole", "nessuno", "probabile"],
       "e tutti e quattro escono davvero: se ne nascesse un quinto, la mappa dei badge della pagina non lo coprirebbe");
    ok(usati.size === conti.GRADI_ABBINAMENTO.length,
       "quanti gradi ha davvero prodotto questa prova: " + usati.size);
  });

  test("Conti · banca: senza nessuna fattura aperta il movimento non si abbina, e lo dice", () => {
    const r = uno("BONIFICO QUALUNQUE", "1.234,00", "10/03/2026", []);
    contiene(r, { grado: "nessuno", verso: "entrata" }, "niente con cui confrontare");
    ok(/nessuna fattura aperta/.test(r.perche), "col perché: " + r.perche);
    eq(conti.abbinaMovimenti(null, null, null, null).riepilogo.misurabile, false,
       "e chiamato con tutto a null non esplode: risponde «non misurabile»");
  });
}

// ── Scudo · la foto come prova ────────────────────────────────────────────
// Il numero che ha deciso «più d'una foto o una sola»: due allegati da 400 KB
// (il limite della SINGOLA, in shared/) fanno il 104,2% del tetto di 1 MB del
// documento Firestore, e la scrittura viene rifiutata portandosi dietro tutto
// il record. Quindi il limite è sul TOTALE, e per l'ispezione il totale è di
// tutta l'ispezione — le voci stanno in un unico documento.
{
  const B64 = (n) => Buffer.alloc(n, 7).toString("base64");
  const foto = (n, extra) => Object.assign({ nome: "f.jpg", dataURL: "data:image/jpeg;base64," + B64(n) }, extra || {});
  const KB = 1024;

  test("Scudo · foto: il numero che ha deciso il limite sul TOTALE", () => {
    // dataURL di un file da N byte = 23 caratteri di prefisso + ceil(N/3)*4
    const dataURL = (n) => "data:image/jpeg;base64,".length + Math.ceil(n / 3) * 4;
    const TETTO = 1024 * 1024;                       // tetto del documento Firestore
    eq(shell.LIMITE_ALLEGATO, 400 * KB, "il limite della singola sta in shared/, non qui");
    ok(dataURL(400 * KB) < TETTO, "una foto da 400 KB ci sta: " + dataURL(400 * KB) + " byte");
    ok(dataURL(400 * KB) * 2 > TETTO,
       "DUE no, ed è il numero che decide: " + (dataURL(400 * KB) * 2) + " byte su " + TETTO);
    eq(scudo.MAX_FOTO, 3, "al massimo tre: a 400 KB in tutto sono 133 KB l'una");
  });

  test("Scudo · foto: il peso di una foto salvata è quello del file, al byte", () => {
    for (const n of [1, 2, 3, 23, 1024, 100000, 409600])
      eq(scudo.pesoFoto(foto(n)), n, "un file da " + n + " byte");
    eq(scudo.pesoFoto({ dataURL: "ciao" }), null, "non è un dataURL");
    eq(scudo.pesoFoto(null), null, "nessuna foto");
    eq(scudo.pesoFoto({ dataURL: "data:text/plain,ciao" }), null, "dataURL non base64");
    eq(scudo.pesoFoto({ dataURL: "data:image/jpeg;base64,@@@@" }), null, "base64 corrotto");
  });

  test("Scudo · foto: il budget è sul totale, e un peso illeggibile NON conta zero", () => {
    const vuoto = scudo.bilancioFoto([]);
    contiene(vuoto, { quante: 0, pieno: false, motivo: "", misurabile: true }, "nessuna foto: si può");
    eq(vuoto.residuo, 400 * KB, "e c'è tutto lo spazio");
    eq(scudo.bilancioFoto([foto(200 * KB)]).residuo, 200 * KB, "una da 200 KB ne lascia 200");
    contiene(scudo.bilancioFoto([foto(200 * KB), foto(200 * KB)]), { pieno: true, motivo: "spazio", residuo: 0 },
             "due da 200 KB chiudono lo spazio: la terza sfonderebbe il documento");
    contiene(scudo.bilancioFoto([foto(10), foto(10), foto(10)]), { pieno: true, motivo: "numero" },
             "tre foto minuscole: pieno per NUMERO, non per spazio");
    contiene(scudo.bilancioFoto([foto(400 * KB - 500)]), { pieno: true, motivo: "spazio" },
             "meno di 1 KB residuo non è spazio: non ci sta nessuna foto");
    contiene(scudo.bilancioFoto([foto(400 * KB - 2000)]), { pieno: false, motivo: "" }, "poco meno di 2 KB sì");
    const rotto = scudo.bilancioFoto([{ dataURL: "boh" }]);
    contiene(rotto, { misurabile: false, pieno: true, motivo: "peso-illeggibile", residuo: 0 },
             "una foto che non si sa pesare ferma il conto invece di contare zero");
  });

  test("Scudo · foto: il residuo diventa il limite del controllo condiviso", () => {
    // ⛔ la regola «questo file va bene?» resta UNA, quella di shared/: qui le
    // si passa solo lo spazio rimasto, così il messaggio parla del residuo
    // vero e non dei 400 KB che non ci sono più.
    const b = scudo.bilancioFoto([foto(300 * KB)]);
    eq(b.residuo, 100 * KB, "restano 100 KB");
    const via = shell.controllaAllegato({ name: "grande.jpg", size: 150 * KB }, b.residuo);
    contiene(via, { ok: false, motivo: "troppo-grande", limiteKb: 100 }, "150 KB non ci stanno più");
    ok(shell.testoAllegatoRifiutato(via).includes("100 KB"),
       "e la frase dice il residuo: " + shell.testoAllegatoRifiutato(via));
    ok(shell.controllaAllegato({ name: "piccola.jpg", size: 90 * KB }, b.residuo).ok, "90 KB sì");
  });

  test("Scudo · foto: nell'ispezione il totale è di TUTTA l'ispezione, non della voce", () => {
    const isp = { voci: [{ id: "v1", testo: "Arginelli" }, { id: "v2", testo: "DPI" }],
      esiti: { v1: { esito: "non-conforme", foto: [foto(150 * KB)] },
               v2: { esito: "non-conforme", foto: [foto(260 * KB)] } } };
    eq(scudo.bilancioFotoVoce(isp, "v1").usati, 410 * KB, "il conto vede le foto di tutte le voci");
    ok(!scudo.bilancioFoto(scudo.fotoDiVoce(isp, "v1")).pieno,
       "guardando la SOLA voce il conto passerebbe: è la trappola");
    contiene(scudo.bilancioFotoVoce(isp, "v1"), { pieno: true, motivo: "spazio" }, "guardando l'ispezione no");
    contiene(scudo.bilancioFotoVoce(isp, "v2"), { pieno: true, motivo: "spazio" }, "e nemmeno per l'altra voce");
    contiene(scudo.bilancioFotoVoce({}, "v1"), { pieno: false, quante: 0 }, "ispezione senza foto: si può");
  });

  test("Scudo · foto: una foto su una voce che il modello non ha più occupa spazio lo stesso", () => {
    const isp = { voci: [{ id: "v1", testo: "Arginelli" }],
      esiti: { v1: { foto: [foto(10)] }, v9: { foto: [foto(300 * KB)] } } };
    eq(scudo.fotoDiIspezione(isp).length, 2, "si scorrono gli ESITI, non le voci");
    eq(scudo.fotoDiIspezione(isp).find(f => f.voceId === "v1").voce, "Arginelli", "col testo della voce");
    eq(scudo.fotoDiIspezione(isp).find(f => f.voceId === "v9").voce, "", "e senza inventarlo quando la voce non c'è più");
    ok(scudo.bilancioFotoVoce(isp, "v1").usati > 300 * KB,
       "la foto orfana pesa nel documento: se non la si contasse il budget direbbe che c'è posto");
  });

  test("Scudo · foto: le foto di un evento, senza contare i buchi", () => {
    eq(scudo.fotoDiEvento({ foto: [foto(10), { nome: "x" }, null] }).length, 1, "senza dataURL non è una foto");
    eq(scudo.fotoDiEvento({}).length, 0, "evento senza foto");
    eq(scudo.fotoDiEvento(null).length, 0, "nessun evento");
    eq(scudo.fotoDiVoce({ esiti: { v1: { foto: [foto(10)] } } }, "v1").length, 1, "voce con una foto");
    eq(scudo.fotoDiVoce({ esiti: { v1: { esito: "conforme" } } }, "v1").length, 0, "voce con esito e senza foto");
  });

  test("Scudo · foto: una frase per OGNI motivo che il bilancio sa dire", () => {
    // regola 18: la mappa copre tutti gli stati della sua funzione
    const motivi = new Set();
    motivi.add(scudo.bilancioFoto([]).motivo);
    motivi.add(scudo.bilancioFoto([foto(10), foto(10), foto(10)]).motivo);
    // ⚠️ 399 KB tondi NON bastano a produrre «spazio»: il residuo è 1024 byte
    // esatti, e la soglia è «meno di 1 KB». La prima stesura di questa riga
    // faceva coincidere due risposte diverse e la prova è caduta subito.
    motivi.add(scudo.bilancioFoto([foto(400 * KB - 500)]).motivo);
    motivi.add(scudo.bilancioFoto([{ dataURL: "boh" }]).motivo);
    eq([...motivi].sort(), ["", "numero", "peso-illeggibile", "spazio"], "quattro motivi, prodotti davvero");
    for (const m of motivi) {
      const s = scudo.testoBilancioFoto({ motivo: m, quante: 3, max: 3, residuo: 100 * KB, limite: 400 * KB });
      ok(typeof s === "string" && s.length > 20, "motivo «" + m + "» ha la sua frase: " + s);
    }
    ok(scudo.testoBilancioFoto(scudo.bilancioFoto([])).includes("400 KB"), "col posto libero dice quanto ne resta");
    ok(/non so dire quanto spazio resta/.test(scudo.testoBilancioFoto(scudo.bilancioFoto([{ dataURL: "boh" }]))),
       "e la non-misurabilità la legge qualcuno, invece di restare una bandiera muta");
  });

  test("Scudo · foto: zero foto NON è un difetto — nessuna pastiglia, nessun colore", () => {
    eq(scudo.pastigliaFoto(0), null, "chi soccorre non fotografa: nessun contatore a zero accanto agli altri badge");
    eq(scudo.pastigliaFoto(undefined), null, "campo assente");
    eq(scudo.pastigliaFoto(NaN), null, "e nemmeno un numero che non è un numero");
    eq(scudo.pastigliaFoto(-3), null, "né un numero impossibile");
    eq(scudo.pastigliaFoto(1).testo, "1 foto", "una foto, al singolare");
    eq(scudo.pastigliaFoto(2).testo, "2 foto", "due");
    for (const n of [1, 2, 3])
      ok(!/danger|warn/.test(scudo.pastigliaFoto(n).classe), "e la classe non è mai d'allarme (" + n + ")");
  });

  test("Scudo · foto: una foto senza contesto lo DICE, non si spaccia per prova", () => {
    eq(scudo.contestoFoto({ didascalia: "arginello mancante" }, "Fascia di rispetto"), "arginello mancante",
       "la didascalia di chi ha scattato viene prima");
    eq(scudo.contestoFoto({}, "Fascia di rispetto al ciglio"), "Fascia di rispetto al ciglio",
       "senza didascalia vale il soggetto a cui la foto è attaccata");
    eq(scudo.contestoFoto({ didascalia: "   " }, ""), null, "una didascalia di soli spazi non è una didascalia");
    eq(scudo.contestoFoto({}, ""), null, "e senza né l'una né l'altro torna null, non stringa vuota");
    eq(scudo.contestoFoto(null, null), null, "chiamata a vuoto");
  });
}


// ── Terra · conformità al progetto ─────────────────────────────────────
/* «Stiamo scavando dove il progetto dice?» — la domanda che un ente fa a una
   cava autorizzata. Terra ne sapeva già misurare tre quarti (`vitaCava`,
   `proiezioneAnnua`, `avanzamentoLotto`, `divarioRecupero`); mancava l'asse
   VERTICALE, cioè il fondo scavo del progetto, che non aveva nemmeno un campo
   dove essere scritto. Quello che queste prove difendono, prima di ogni
   conto, è che senza quel dato la risposta sia «non si sa» e non «conforme». */
{
  const FRO = [{ id: "f1", nome: "Nord", quota: 340 },
               { id: "f2", nome: "Est", quota: 355 },
               { id: "f3", nome: "Sud", quota: 320 }];
  const LOT = [{ id: "l1", nome: "Lotto 1", frontiId: ["f1"], volumeM3: 100, stato: "aperto" },
               { id: "l2", nome: "Lotto 2", frontiId: ["f2"], volumeM3: 100, stato: "aperto" }];
  const ATTO = { quotaFondoM: 300 };

  test("Terra · conformità: senza quota di fondo la risposta è «non si sa», mai «conforme»", () => {
    const c = terra.conformitaProgetto(FRO, LOT, [], {});
    eq(c.misurabile, false, "nessuna misura verticale possibile");
    eq(c.dentro, 0, "e nessun fronte viene dichiarato dentro il progetto");
    eq(c.oltre, 0, "né fuori: non è un giudizio, è un'assenza");
    eq(c.nonMisurabili, 3, "tutti e tre i fronti restano non misurabili, e si contano");
    ok(/non dichiara nessuna quota di fondo/.test(c.perche),
       "la ragione nomina il dato che manca, così si sa cosa fare: «" + c.perche + "»");
    eq(terra.conformitaQuota(FRO[0], null, {}).stato, "non-misurabile", "e vale per il singolo fronte");
  });

  test("Terra · conformità: il fondo del LOTTO vince su quello dell'atto, e si dice da dove viene", () => {
    const f = terra.fondoAutorizzato({ quotaFondoM: 335 }, ATTO);
    eq(f, { m: 335, origine: "lotto", noto: true, perche: "" }, "il settore ha il suo fondo");
    eq(terra.fondoAutorizzato({}, ATTO).origine, "autorizzazione", "senza fondo di settore vale quello generale");
    eq(terra.fondoAutorizzato(null, ATTO).origine, "autorizzazione", "lotto assente: idem");
    eq(terra.fondoAutorizzato({}, {}).noto, false, "e senza né l'uno né l'altro, `noto` è falso");
    // il caso per cui la precedenza esiste: 5 m di margine contro 40
    eq(terra.conformitaQuota(FRO[0], { quotaFondoM: 335 }, ATTO).margineM, 5, "contro il fondo del settore");
    eq(terra.conformitaQuota(FRO[0], {}, ATTO).margineM, 40, "contro quello generale, otto volte tanto");
  });

  test("Terra · conformità: oltre, al limite e dentro sono tre cose diverse", () => {
    eq(terra.statoConformitaQuota(-0.5), "oltre", "sceso sotto il fondo");
    eq(terra.statoConformitaQuota(0), "al-limite", "arrivato esatto: da lì non si scende più");
    eq(terra.statoConformitaQuota(0.5), "dentro", "c'è ancora margine");
    eq(terra.statoConformitaQuota(null), "non-misurabile", "e senza margine non c'è nessuno stato");
    eq(terra.statoConformitaQuota(NaN), "non-misurabile", "un numero che non è un numero non è uno stato");
    eq(terra.statoConformitaQuota(""), "non-misurabile", "né una stringa vuota");
    const c = terra.conformitaProgetto(
      [{ id: "f1", nome: "Nord", quota: 296 }, { id: "f2", nome: "Est", quota: 300 }, FRO[2]], LOT, [], ATTO);
    eq([c.oltre, c.alLimite, c.dentro], [1, 1, 1], "uno per stato");
    eq([c.peggiore.nome, c.peggiore.margineM], ["Nord", -4], "il peggiore è quello sceso di più");
    eq([c.piuVicino.nome, c.piuVicino.margineM], ["Est", 0],
       "e il più vicino al fondo comprende chi ci è arrivato esatto: è il fronte da guardare");
  });

  test("Terra · conformità: quota 0 non è una quota — è quello che il vecchio form scriveva sul campo vuoto", () => {
    // fino al 05/08 il form salvava `rq.ok ? rq.valore : 0` e parseFrontiCsv
    // faceva lo stesso: in archivio lo zero e il «mai inserito» sono uguali
    eq(terra.conformitaQuota({ quota: 0 }, null, ATTO).stato, "non-misurabile",
       "preso per buono direbbe «300 m sotto il fondo» su un fronte mai misurato");
    eq(terra.conformitaQuota({ quota: null }, null, ATTO).stato, "non-misurabile", "quota assente");
    eq(terra.conformitaQuota({ quota: "" }, null, ATTO).stato, "non-misurabile", "stringa vuota");
    eq(terra.conformitaQuota({ quota: "abc" }, null, ATTO).stato, "non-misurabile", "e nemmeno un non-numero");
    eq(terra.fondoAutorizzato({ quotaFondoM: 0 }, ATTO).origine, "autorizzazione",
       "e vale anche per il fondo: uno zero sul lotto non copre quello dell'atto");
    eq(terra.parseFrontiCsv("nome;banco;quota;stato\nFronte X;;;attivo\n")[0].quota, null,
       "l'imboccatura CSV adesso scrive `null`, non uno zero che sembra una misura");
  });

  test("Terra · conformità: una quota negativa è normale (cava in fossa) e non si arrotonda male", () => {
    const c = terra.conformitaQuota({ quota: -5 }, null, { quotaFondoM: -12 });
    eq([c.stato, c.margineM], ["dentro", 7], "sotto il livello del mare si ragiona uguale");
    eq(terra.conformitaQuota({ quota: -15 }, null, { quotaFondoM: -12 }).stato, "oltre", "e si può sforare");
    // `Math.round` sul mezzo tira verso +∞: arrotondare le quote in ingresso
    // darebbe -12,34 al posto di -12,35. Si arrotonda solo il margine.
    eq(terra.conformitaQuota({ quota: -5 }, null, { quotaFondoM: -12.345 }).margineM, 7.35,
       "il margine è arrotondato una volta sola, e nel verso giusto");
    eq(terra.conformitaQuota({ quota: -5 }, null, { quotaFondoM: -12.345 }).fondoM, -12.345,
       "il fondo dichiarato resta quello che l'utente ha scritto");
  });

  test("Terra · conformità: due fronti su tre senza quota NON fanno «tutto a posto»", () => {
    const c = terra.conformitaProgetto(
      [FRO[0], { id: "f2", nome: "Est" }, { id: "f3", nome: "Sud", quota: 0 }], LOT, [], ATTO);
    eq(c.misurabile, true, "una misura c'è");
    eq([c.dentro, c.nonMisurabili], [1, 2], "ma i due che non si sanno si contano, non spariscono");
    ok(/non dichiara la quota raggiunta/.test(c.fronti[1].perche), "e ognuno porta la sua ragione");
    // e quando il fondo c'è ma nessun fronte ha la quota, la ragione cambia:
    // manda a compilare i FRONTI, non l'autorizzazione
    const v = terra.conformitaProgetto([{ id: "x", nome: "X" }], LOT, [], ATTO);
    ok(/Nessuno dei fronti registrati dichiara la quota/.test(v.perche), "ragione giusta: «" + v.perche + "»");
    ok(/Nessun fronte registrato/.test(terra.conformitaProgetto([], LOT, [], ATTO).perche),
       "e senza nemmeno un fronte la ragione è una terza ancora");
  });

  test("Terra · conformità: gli altri due modi di scavare fuori dal progetto (volume e sequenza)", () => {
    const RIL = [{ id: "r1", stato: "elaborato", volumeM3: 130, fronteId: "f1" }];
    const c = terra.conformitaProgetto(FRO, LOT, RIL, ATTO);
    eq(c.volume.oltrePrevisto.map((v) => [v.nome, v.pct]), [["Lotto 1", 130]],
       "130 m³ misurati su 100 previsti dal progetto: è il 130%");
    eq([c.volume.conConfronto, c.volume.senzaConfronto], [1, 1],
       "il lotto senza rilievi non è «allo 0%»: è senza confronto, e si conta");
    eq(terra.conformitaProgetto(FRO, LOT, [], ATTO).volume.misurabile, false,
       "nessun rilievo → il volume NON è misurabile, non «tutto dentro»");
    // il terzo modo: si scava dove il progetto non ha ancora aperto
    const prev = [{ id: "l9", nome: "Lotto 9", frontiId: ["f3"], volumeM3: 500, stato: "previsto" }];
    eq(terra.conformitaProgetto(FRO, prev, [{ id: "r9", stato: "elaborato", volumeM3: 40, fronteId: "f3" }], ATTO)
       .volume.fuoriSequenza.map((v) => v.nome), ["Lotto 9"], "scavo in un lotto ancora «previsto»");
    eq(terra.conformitaProgetto(FRO, prev, [], ATTO).volume.fuoriSequenza.length, 0,
       "ma un lotto previsto e mai toccato non è fuori sequenza");
  });

  test("Terra · conformità: sulla dimostrazione il quadro si legge per intero", () => {
    const D = terra.DEMO;
    const c = terra.conformitaProgetto(D.fronti, D.lotti, D.rilievi, D.autorizzazioni[0]);
    eq(c.misurabile, true, "l'atto d'esempio dichiara la quota di fondo");
    eq([c.dentro, c.oltre, c.alLimite, c.nonMisurabili], [3, 0, 0, 0], "tre fronti, tutti dentro");
    eq([c.piuVicino.nome, c.piuVicino.margineM, c.piuVicino.origineFondo], ["Fronte Nord", 5, "lotto"],
       "il più stretto è il Nord, che ha un fondo di settore suo");
    eq(c.fronti.find((f) => f.nome === "Fronte Est").origineFondo, "autorizzazione",
       "gli altri stanno sul fondo generale");
    eq(c.volume.senzaConfronto, 4, "quattro lotti su sei non hanno un confronto, e la demo lo mostra");
    eq(c.volume.fuoriSequenza.length, 0, "nessuno scava dove il progetto non ha aperto");
  });
}

// ── Campo · riposo fra due turni ───────────────────────────────────────
// D.Lgs 66/2003 art. 7: undici ore consecutive di riposo ogni ventiquattro.
// Il conto poggia sull'appello, che ha TRE risposte, e da lì l'asimmetria che
// queste prove esistono per blindare: con turni non spuntati in mezzo, il
// riposo calcolato è un TETTO — sa ancora accusare, non sa più assolvere.
{
  const IERI = "2026-03-09", OGGI_R = "2026-03-10";
  const dur8 = (data, turno) => ({ data, turno, minuti: 480 });
  const pre = (data, turno, operatoreId, stato) => ({ data, turno, operatoreId, stato });
  const DUR = [dur8(IERI, "Mattina"), dur8(IERI, "Pomeriggio"), dur8(IERI, "Notte")];
  /* La coda che `testoRiposo` aggiunge quando la fine del turno precedente
     viene dalla DURATA DICHIARATA e non dall'ora di uscita. Scritta una volta
     sola: era in sei asserzioni, e sei copie della stessa stringa è il modo di
     avere un giorno cinque asserzioni aggiornate e una no. */
  const FONTE_DURATA = " · stima: manca l'ora di uscita";

  test("Campo · riposo: l'ora d'inizio dei turni sta in un posto solo", () => {
    eq(campo.ORE_INIZIO_TURNO, { Mattina: 6, Pomeriggio: 14, Notte: 22 }, "le tre ore d'inizio");
    // la stessa tabella che `turnoCorrente` legge: se qualcuno la cambiasse,
    // le due letture resterebbero d'accordo invece di divergere in silenzio
    for (const t of campo.TURNI) {
      const h = campo.ORE_INIZIO_TURNO[t];
      eq(campo.turnoCorrente(new Date(2026, 2, 10, h, 30)), t, `alle ${h}:30 è ${t}`);
    }
    eq(campo.RIPOSO_MINIMO_ORE, 11, "la soglia di legge");
    eq(campo.STATI_RIPOSO, ["sotto", "regolare", "non-misurabile"], "i tre stati dichiarati");
  });

  test("Campo · riposo: inizioTurno e fineTurno, e il rifiuto senza durata", () => {
    eq(campo.inizioTurno(OGGI_R, "Mattina"), new Date(2026, 2, 10, 6).getTime(), "la mattina comincia alle 6");
    eq(campo.inizioTurno(OGGI_R, "Notte"), new Date(2026, 2, 10, 22).getTime(), "la notte alle 22");
    // «2026-02-30» non è un refuso da far scivolare al 2 marzo
    eq(campo.inizioTurno("2026-02-30", "Mattina"), null, "un giorno che non esiste non ha un inizio");
    eq(campo.inizioTurno(OGGI_R, "Serale"), null, "un turno che non esiste nemmeno");
    eq(campo.fineTurno(DUR, IERI, "Pomeriggio"), new Date(2026, 2, 9, 22).getTime(),
       "14:00 più otto ore dichiarate");
    // ⛔ il cuore: senza durata dichiarata NON si danno per scontate otto ore
    eq(campo.fineTurno([], IERI, "Pomeriggio"), null, "senza durata dichiarata non si sa quando è finito");
    eq(campo.fineTurno([{ data: IERI, turno: "Pomeriggio", minuti: 0 }], IERI, "Pomeriggio"), null,
       "e nemmeno con una durata di zero minuti");
  });

  test("Campo · riposo: i turni precedenti si contano all'indietro, mese compreso", () => {
    const uno = campo.turniPrecedenti(OGGI_R, "Mattina", 1);
    eq(uno.length, 3, "un giorno indietro sono tre turni");
    eq(uno[0], { data: IERI, turno: "Notte" }, "prima della Mattina c'è la Notte di ieri");
    eq(uno[2], { data: IERI, turno: "Mattina" }, "e tre turni prima la Mattina di ieri");
    eq(campo.turniPrecedenti(OGGI_R, "Mattina", 7).length, 21, "sette giorni sono ventuno turni");
    eq(campo.turniPrecedenti("2026-03-01", "Mattina", 1)[0].data, "2026-02-28", "attraversa il mese");
    eq(campo.turniPrecedenti("2026-02-30", "Mattina", 1), [], "da un giorno che non esiste non si cammina");
    eq(campo.turniPrecedenti(OGGI_R, "Serale", 1), [], "né da un turno che non esiste");
  });

  test("Campo · riposo: otto ore fra pomeriggio e mattina sono sotto la soglia", () => {
    const P = [pre(IERI, "Pomeriggio", "o1", "presente"), pre(IERI, "Notte", "o1", "assente")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", ore: 8, misurabile: true, limite: "", buchi: 0 },
             "22:00 → 06:00 sono otto ore, ed è una misura");
    eq(r.ultimo, { data: IERI, turno: "Pomeriggio" }, "l'ultimo turno lavorato che si conosce");
    eq(campo.testoRiposo(r), "8 h dal turno precedente · sotto le 11 ore" + FONTE_DURATA,
       "e si scrive così — con da dove viene la fine del turno prima");
  });

  test("Campo · riposo: sedici ore sono regolari", () => {
    const P = [pre(IERI, "Mattina", "o1", "presente"), pre(IERI, "Pomeriggio", "o1", "assente"),
               pre(IERI, "Notte", "o1", "assente")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "regolare", ore: 16, misurabile: true, limite: "", buchi: 0 }, "14:00 → 06:00");
    eq(campo.testoRiposo(r), "16 h dal turno precedente" + FONTE_DURATA, "senza nessun allarme");
  });

  test("Campo · riposo: un turno non spuntato in mezzo NON assolve", () => {
    // stessi dati della prova sopra, ma la Notte di ieri nessuno l'ha spuntata:
    // quella persona potrebbe averla lavorata, e allora ha riposato di meno
    const P = [pre(IERI, "Mattina", "o1", "presente"), pre(IERI, "Pomeriggio", "o1", "assente")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "non-misurabile", ore: 16, misurabile: false, limite: "al-piu", buchi: 1 },
             "sedici ore, ma è un TETTO: sopra la soglia non prova niente");
    ok(/appello/.test(r.perche), "e la ragione nomina l'appello: " + r.perche);
    ok(campo.testoRiposo(r).startsWith("Riposo non misurabile"), "la frase lo dice");
  });

  test("Campo · riposo: un turno non spuntato NON scusa, se il tetto è già sotto", () => {
    // l'altra metà dell'asimmetria: i buchi possono solo ACCORCIARE il riposo,
    // quindi un tetto di otto ore resta una violazione certa
    const P = [pre(IERI, "Pomeriggio", "o1", "presente")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", ore: 8, misurabile: true, limite: "al-piu", buchi: 1 },
             "col buco resta sotto le undici ore, e si dice");
    eq(campo.testoRiposo(r), "Al più 8 h dal turno precedente · sotto le 11 ore" + FONTE_DURATA,
       "«al più», non «esattamente»");
  });

  test("Campo · riposo: senza la durata del turno prima non si inventa", () => {
    const P = [pre(IERI, "Pomeriggio", "o1", "presente"), pre(IERI, "Notte", "o1", "assente")];
    const r = campo.riposoPrimaDelTurno("o1", P, [], OGGI_R, "Mattina");
    contiene(r, { stato: "non-misurabile", ore: null, misurabile: false }, "niente denominatore, niente numero");
    ok(/durata/.test(r.perche), "e lo dice: " + r.perche);
    eq(r.ultimo, { data: IERI, turno: "Pomeriggio" }, "il turno di cui manca la durata è nominato");
    // ⛔ LA DATA LA SCRIVE L'INTERFACCIA, come in `riassuntoRiapertura`: la
    // frase mostrata a chi comanda il turno non contiene mai un «2026-03-09»,
    // che è una stringa da macchina in un'app scritta in italiano. Trovato
    // guardando lo scatto, non leggendo il codice.
    ok(!/\d{4}-\d{2}-\d{2}/.test(r.perche), "la ragione non porta dentro nessuna data ISO");
    const dmy = (iso) => iso.slice(8, 10) + "/" + iso.slice(5, 7) + "/" + iso.slice(0, 4);
    eq(campo.testoRiposo(r, dmy),
       "Riposo non misurabile — del turno precedente non si sa quando è finito: manca l'ora di "
       + "uscita di questa persona e manca la durata dichiarata del turno (turno Pomeriggio del 09/03/2026)",
       "col formattatore della pagina la data è quella che si legge in cava");
    ok(campo.testoRiposo(r).includes("2026-03-09"), "senza formattatore la data resta com'è, e non salta niente");
  });

  test("Campo · riposo: nessuna spunta da nessuna parte non è «riposato»", () => {
    const r = campo.riposoPrimaDelTurno("o9", [], DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "non-misurabile", ore: null, misurabile: false, buchi: 21 },
             "ventuno turni muti non fanno un via libera");
    // ⛔ il caso che il principio del fondatore esiste per prendere: qui la
    // risposta comoda sarebbe «riposato da giorni»
    ok(!/regolare/.test(r.stato), "e soprattutto non è «regolare»");
  });

  test("Campo · riposo: chi risulta assente per tutta la finestra ha riposato", () => {
    const P = campo.turniPrecedenti(OGGI_R, "Mattina", 7)
      .map((t) => pre(t.data, t.turno, "o1", "assente"));
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "regolare", misurabile: true, limite: "almeno", buchi: 0, giorni: 7 },
             "spuntato assente ovunque: allora non ha lavorato");
    ok(r.ore > 24 * 6, "e il riposo è almeno la finestra guardata, " + r.ore + " h");
    eq(campo.testoRiposo(r), "Nessun turno lavorato nei 7 giorni prima di questo", "e si scrive così");
  });

  test("Campo · riposo: i casi limite non danno numeri tranquilli", () => {
    eq(campo.riposoPrimaDelTurno("o1", [], DUR, "2026-02-30", "Mattina").stato, "non-misurabile",
       "una data che non esiste");
    eq(campo.riposoPrimaDelTurno("o1", [], DUR, OGGI_R, "Serale").stato, "non-misurabile",
       "un turno che non esiste");
    eq(campo.riposoPrimaDelTurno("o1", [], DUR, OGGI_R, "Mattina", 0).stato, "non-misurabile",
       "zero giorni indietro: non si è guardato niente");
    // due turni che si sovrappongono (durata dichiarata assurda): un riposo
    // negativo è comunque «sotto», e il testo non scrive «-4 h»
    const P = [pre(IERI, "Pomeriggio", "o1", "presente"), pre(IERI, "Notte", "o1", "assente")];
    const r = campo.riposoPrimaDelTurno("o1", P, [{ data: IERI, turno: "Pomeriggio", minuti: 1200 }],
                                        OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", ore: -4 }, "il turno prima finisce dopo che questo è cominciato");
    eq(campo.testoRiposo(r), "Il turno precedente finisce dopo che questo è cominciato · sotto le 11 ore" + FONTE_DURATA,
       "e si dice a parole, non con un «-4 h» che nessuno saprebbe leggere");
    eq(campo.testoRiposo(null), "", "senza riga non si scrive niente");
  });

  test("Campo · riposo: la notte che finisce quando comincia la mattina fa zero", () => {
    const P = [pre(IERI, "Notte", "o1", "presente")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", ore: 0 }, "22:00 + 8 h = 06:00, cioè nessun riposo");
    // ⛔ e NON «0 min»: accanto a «8 h» e «16 h» si leggerebbe come un numero
    // piccolo invece che come il caso peggiore che la funzione sa raccontare
    eq(campo.testoRiposo(r), "Nessun riposo fra questo turno e il precedente · sotto le 11 ore" + FONTE_DURATA,
       "zero ore si scrive a parole");
  });

  test("Campo · riposo: il quadro del turno non somma i dubbi ai regolari", () => {
    const OP = [{ id: "o1", nome: "A", squadra: "Squadra A", stato: "in-forza" },
                { id: "o2", nome: "B", squadra: "Squadra A", stato: "in-forza" },
                { id: "o3", nome: "C", squadra: "Squadra A", stato: "in-forza" },
                { id: "o4", nome: "D", squadra: "Squadra A", stato: "non-disponibile" }];
    const P = [pre(IERI, "Pomeriggio", "o1", "presente"), pre(IERI, "Notte", "o1", "assente"),
               pre(IERI, "Mattina", "o2", "presente"), pre(IERI, "Pomeriggio", "o2", "assente"),
               pre(IERI, "Notte", "o2", "assente")];
    const q = campo.riposoDiTurno(OP, P, DUR, OGGI_R, "Mattina", "");
    contiene(q, { totale: 3, sotto: 1, regolari: 1, nonMisurabili: 1, tuttiInRegola: false },
             "chi non è disponibile resta fuori, o3 non si sa e non diventa regolare");
    eq(q.sotto + q.regolari + q.nonMisurabili, q.totale, "i tre conti coprono tutte le righe");
    eq(campo.riposoDiTurno([], P, DUR, OGGI_R, "Mattina", "").tuttiInRegola, false,
       "senza nessuno in elenco non si dice «tutti a posto»");
  });

  test("Campo · riposo: sulla dimostrazione si vedono tutti gli esiti", () => {
    const D = campo.DEMO, oggi = campo.oggiISO();
    const m = campo.riposoDiTurno(D.operatori, D.presenze, D.durate, oggi, "Mattina", "");
    // o3 è spuntata ASSENTE alla Mattina di oggi: resta fuori, perché il riposo
    // prima di un turno riguarda chi quel turno lo fa
    contiene(m, { totale: 3, sotto: 1, regolari: 1, nonMisurabili: 1 },
             "tre in turno: uno sotto, uno regolare, uno che non si sa");
    const pm = {}; m.righe.forEach((r) => { pm[r.operatore.id] = r; });
    ok(!pm.o3, "chi è spuntato assente non compare fra le righe del riposo");
    /* ⛔ SEI ORE E MEZZA, NON OTTO, ed è il cantiere degli orari che si vede:
       o1 ieri pomeriggio è uscito alle 23:45 mentre la durata dichiarata
       diceva le 22, e stamattina è entrato alle 06:10. Il numero di prima
       (otto ore) non era una misura, era il piano dei turni. */
    contiene(pm.o1, { stato: "sotto", ore: 6.42, limite: "", daInizio: "orario", daFine: "orario" },
             "o1 è uscito davvero alle 23:45 e rientrato alle 06:10");
    contiene(pm.o2, { stato: "regolare", ore: 16.25, limite: "", daFine: "durata" },
             "o2 non ha dichiarato l'uscita: si ripiega sulle 14 dichiarate, e si dice");
    ok(/durata/.test(pm.o4.perche), "o4 era di Notte e della Notte manca la durata: " + pm.o4.perche);
    // il quarto esito — il TETTO che non assolve — la dimostrazione lo mostra
    // al Pomeriggio, dove o3 è presente e ha due turni non spuntati alle spalle
    const p = campo.riposoDiTurno(D.operatori, D.presenze, D.durate, oggi, "Pomeriggio", "");
    const pp = {}; p.righe.forEach((r) => { pp[r.operatore.id] = r; });
    contiene(pp.o3, { stato: "non-misurabile", ore: 24, limite: "al-piu", buchi: 2 },
             "o3 ha due turni non spuntati in mezzo: il tetto non assolve");
    // la dimostrazione deve mostrare la DIFESA, non solo il caso bello
    ok(m.nonMisurabili > 0 && p.nonMisurabili > 0, "e i buchi nei dati d'esempio ci sono apposta");
  });

  test("Campo · riposo: chi è spuntato assente non entra, chi non è spuntato sì", () => {
    const OP = [{ id: "o1", nome: "A", squadra: "Squadra A", stato: "in-forza" },
                { id: "o2", nome: "B", squadra: "Squadra A", stato: "in-forza" }];
    const lavoro = [pre(IERI, "Pomeriggio", "o1", "presente"), pre(IERI, "Notte", "o1", "assente"),
                    pre(IERI, "Pomeriggio", "o2", "presente"), pre(IERI, "Notte", "o2", "assente")];
    // tutti e due sotto le undici ore, ma o1 oggi è spuntato assente
    const q = campo.riposoDiTurno(OP, lavoro.concat([pre(OGGI_R, "Mattina", "o1", "assente")]),
                                  DUR, OGGI_R, "Mattina", "");
    contiene(q, { totale: 1, sotto: 1 }, "chi non è venuto non porta una violazione che non c'è");
    eq(q.righe[0].operatore.id, "o2", "resta solo chi il turno lo fa");
    // ⛔ e chi NON è stato spuntato resta dentro: «non lo so» non è «non c'è»
    const q2 = campo.riposoDiTurno(OP, lavoro, DUR, OGGI_R, "Mattina", "");
    contiene(q2, { totale: 2, sotto: 2 }, "nessuno spuntato oggi: si guardano tutt'e due");
  });
}

// ── Campo · gli orari veri del turno, persona per persona ──────────────
// Il riposo del blocco qui sopra poggiava sulla DURATA DICHIARATA del turno,
// che è quanto il turno doveva durare — non quando la persona se n'è andata.
// Queste prove blindano le tre cose che cambiano: che l'ora vera vinca sulla
// durata, che dove l'ora non c'è si ripieghi DICENDOLO, e che le due letture
// difficili (la mezzanotte, l'uscita prima dell'entrata) non producano numeri
// tranquilli.
{
  const IERI = "2026-03-09", OGGI_R = "2026-03-10";
  const dur8 = (data, turno) => ({ data, turno, minuti: 480 });
  const DUR = [dur8(IERI, "Mattina"), dur8(IERI, "Pomeriggio"), dur8(IERI, "Notte")];
  // una riga d'appello completa: data, turno, chi, se c'era, e i due orari
  const p = (data, turno, id, stato, entrata, uscita) =>
    ({ data, turno, operatoreId: id, stato, entrata, uscita });
  const ore = (o) => (o.minuti === null ? null : Math.round(o.minuti / 6) / 10);

  test("Campo · orari: che cosa è un orario e che cosa no", () => {
    /* ⚠️ MISURATO IN CHROMIUM PRIMA DI SCRIVERE QUESTA FUNZIONE, perché
       l'ipotesi ragionevole è già stata falsa due volte in un giorno. Il
       risultato ha tolto la paura grossa: un `<input type="time">` NORMALIZZA
       da sé, e su «6:00», «0600», «06.00», «24:00», «06:60» e «1,5» il
       `.value` diventa STRINGA VUOTA. Qui non c'è il caso dei campi interi,
       dove «1,5» diventa «15» e `checkValidity()` risponde true.
       Resta che il vuoto è valido — è «non dichiarato», non zero — e che i
       dati non arrivano solo dal campo: archivi vecchi e import passano di
       qui, quindi la forma si controlla lo stesso. */
    eq(campo.minutiOrario("06:00"), 360, "sei del mattino");
    eq(campo.minutiOrario("00:00"), 0, "mezzanotte è zero, e zero è un orario vero");
    eq(campo.minutiOrario("23:59"), 1439, "l'ultimo minuto del giorno");
    eq(campo.minutiOrario("6:00"), 360, "una cifra sola nelle ore si legge lo stesso");
    eq(campo.minutiOrario(" 07:30 "), 450, "e gli spazi attorno non contano");
    eq(campo.minutiOrario("06:00:00"), 360, "coi secondi (che `type=time` può scrivere) si taglia");
    for (const v of ["24:00", "06:60", "-1:00", "06.00", "0600", "6", "1,5", "abc", "", " ", null, undefined])
      eq(campo.minutiOrario(v), null, `«${v}» non è un orario`);
    eq(campo.oraDaMinuti(360), "06:00", "e si riscrive con lo zero davanti");
    eq(campo.oraDaMinuti(1440 + 360), "06:00", "un orario del giorno dopo si scrive uguale");
    // ⛔ `+null` fa zero, e «00:00» sarebbe un'AFFERMAZIONE: un'ora che manca non si scrive
    for (const v of [null, undefined, "", "abc", -1]) eq(campo.oraDaMinuti(v), "", `«${v}» non si scrive`);
  });

  test("Campo · orari: il tetto della durata di un turno non è un numero a parte", () => {
    // ⛔ IDENTITÀ, non uguaglianza di comodo: se un giorno la soglia del riposo
    // cambiasse, un «13» scritto a mano resterebbe indietro in silenzio
    eq(campo.ORE_TURNO_MAX, 24 - campo.RIPOSO_MINIMO_ORE,
       "un turno non può durare più di quello che le undici ore di riposo lasciano");
    eq(campo.ORE_TURNO_MAX, 13, "che oggi fa tredici ore");
  });

  test("Campo · orari: il turno di giorno, e i due orari che mancano", () => {
    const pieno = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "06:05", "14:10"));
    eq(ore(pieno), 8.1, "dalle 06:05 alle 14:10 sono otto ore e cinque minuti");
    eq(pieno.oltre, false, "e non si scavalca nessuna mezzanotte");
    eq(pieno.attendibile, true, "un turno di otto ore è un turno normale");
    const soloE = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "06:05", ""));
    eq(soloE.minuti, null, "con la sola entrata non si sa quanto ha lavorato");
    ok(soloE.entrata !== null && soloE.uscita === null, "ma l'entrata resta, e serve");
    // ⛔ e `attendibile` è `null`, non `true`: non c'è niente da giudicare, e un
    // «sì, sono affidabili» su un dato che non c'è è il numero tranquillo
    eq(soloE.attendibile, null, "senza uscita non c'è niente da giudicare");
    const soloU = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "", "14:10"));
    eq(soloU.minuti, null, "e con la sola uscita nemmeno");
    ok(soloU.uscita !== null, "ma l'uscita c'è, ed è quella che serve al riposo");
    const niente = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "", ""));
    eq([niente.entrata, niente.uscita, niente.minuti, niente.attendibile], [null, null, null, null],
       "nessun orario dichiarato: nessun numero, e nessun giudizio");
    eq(campo.orariPresenza(null).minuti, null, "e senza riga d'appello non si inventa niente");
  });

  test("Campo · orari: LA MEZZANOTTE — il turno di notte finisce il giorno dopo", () => {
    const notte = campo.orariPresenza(p(OGGI_R, "Notte", "o1", "presente", "22:00", "06:00"));
    eq(ore(notte), 8, "dalle 22 alle 6 sono otto ore, non sedici indietro");
    eq(notte.oltre, true, "e il giorno cambia");
    // chi arriva all'una di notte è entrato in RITARDO, non ventun ore prima:
    // l'entrata è l'occorrenza di quell'ora più vicina all'inizio del turno
    /* ⚠️ LA DURATA NON BASTA A PROVARLO, e l'ha detto la controprova: togliendo
       lo spostamento al giorno dopo, «entrato all'una, uscito alle sei» fa
       cinque ore LO STESSO — perché l'uscita si àncora all'entrata, e cinque
       ore restano cinque ore anche traslate indietro di un giorno. I dati
       facevano coincidere la risposta giusta con quella sbagliata (prima
       causa delle cinque). Quello che cambia è l'ISTANTE, ed è l'istante che
       finisce nel conto del riposo: quindi si guarda quello. */
    const tardi = campo.orariPresenza(p(OGGI_R, "Notte", "o1", "presente", "01:00", "06:00"));
    eq(ore(tardi), 5, "entrato all'una, uscito alle sei: cinque ore");
    eq(tardi.entrata, new Date(2026, 2, 11, 1).getTime(),
       "e l'una di notte del turno del 10 è l'una dell'11, non ventun ore prima");
    eq(ore(campo.orariPresenza(p(OGGI_R, "Notte", "o1", "presente", "23:30", "05:30"))), 6,
       "e a cavallo della mezzanotte il conto non salta");
    // l'uscita senza entrata si àncora all'inizio NOMINALE del turno
    const soloU = campo.orariPresenza(p(OGGI_R, "Notte", "o1", "presente", "", "06:00"));
    eq(new Date(soloU.uscita).getTime(), new Date(2026, 2, 11, 6).getTime(),
       "le sei della Notte del 10 sono le sei dell'11");
  });

  test("Campo · orari: L'USCITA PRIMA DELL'ENTRATA si legge come il giorno dopo, e si dichiara", () => {
    /* ⛔ DECISIONE DI MESTIERE, e la ragione è un'asimmetria, non una
       preferenza. Fra le due letture possibili — «è il mattino dopo» e «è un
       refuso» — questa ACCORCIA il riposo del turno seguente. Se è un refuso
       l'app lo dice e qualcuno lo corregge; se è vero l'app accusa. La lettura
       opposta assolverebbe in silenzio, che è il numero tranquillo che il
       principio del fondatore vieta. */
    const rov = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "14:00", "06:00"));
    eq(ore(rov), 16, "dalle 14 alle 6 del giorno dopo sono sedici ore");
    eq(rov.attendibile, false, "e sedici ore sono più di quante un turno possa durarne");
    ok(/13 ore/.test(rov.perche), "la ragione dice quale tetto è stato passato: " + rov.perche);
    ok(/da controllare/.test(campo.testoOrari(rov)), "e la frase in pagina la porta");
    // entrata = uscita: ventiquattro ore, cioè o un refuso o un turno
    // impossibile — in tutt'e due i casi si segnala invece di far finta
    const ug = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "06:00", "06:00"));
    eq(ore(ug), 24, "stessa ora d'entrata e d'uscita fa ventiquattro ore, non zero");
    eq(ug.attendibile, false, "e non è attendibile");
    // la sola uscita, ancorata al turno, ha la stessa guardia
    const soloU = campo.orariPresenza(p(OGGI_R, "Mattina", "o1", "presente", "", "05:00"));
    eq(soloU.attendibile, false, "un'uscita ventitré ore dopo l'inizio del turno va guardata");
    ok(/inizio del turno/.test(soloU.perche), "e la ragione dice a che cosa è stata confrontata");
  });

  test("Campo · orari: IL CAMBIO D'ORA — otto ore di lancette non sono sempre otto ore", () => {
    /* ⛔ LA DIFFERENZA FRA DUE ISTANTI, non fra due orologi. Nella notte in cui
       le lancette vanno avanti, dalle 22 alle 6 ci sono SETTE ore vere; in
       quella in cui tornano indietro, NOVE. Il riposo di legge sono undici ore
       consecutive di riposo vero, quindi è l'istante che conta.
       ⚠️ E la prova si dichiara: il contenitore gira in UTC, dove il cambio
       d'ora NON ESISTE, quindi qui l'asserzione sarebbe sempre «otto» e non
       proverebbe niente. Si guarda se l'orologio dell'ambiente cambia davvero
       in quella notte, e si pretende il numero giusto per l'ambiente in cui si
       sta girando — stampandolo, perché un controllo che non guarda niente non
       deve poter dire «a posto». */
    const casi = [["2026-03-28", 7, "avanti"], ["2026-10-24", 9, "indietro"]];
    let conCambio = 0;
    for (const [giorno, atteso, verso] of casi) {
      const o = campo.orariPresenza(p(giorno, "Notte", "o1", "presente", "22:00", "06:00"));
      const scarto = (new Date(o.entrata).getTimezoneOffset() - new Date(o.uscita).getTimezoneOffset()) / 60;
      if (scarto === 0) { eq(ore(o), 8, `su questo orologio il ${giorno} non cambia niente: otto ore`); continue; }
      conCambio++;
      eq(ore(o), atteso, `la notte in cui le lancette vanno ${verso}: ${atteso} ore vere invece di otto`);
    }
    console.log(`      · notti col cambio d'ora misurate su questo orologio: ${conCambio} su 2`
                + ` (in UTC sono zero, ed è il motivo per cui la suite gira anche con TZ=Europe/Rome)`);
  });

  test("Campo · orari: senza una data o un turno leggibili non si costruisce nessun istante", () => {
    // «2026-02-30» non è un refuso da far scivolare al 2 marzo
    eq(campo.orariPresenza(p("2026-02-30", "Mattina", "o1", "presente", "06:00", "14:00")).minuti, null,
       "un giorno che non esiste");
    eq(campo.orariPresenza(p(OGGI_R, "Serale", "o1", "presente", "06:00", "14:00")).minuti, null,
       "un turno che non esiste");
  });

  test("Campo · orari: le frasi che finiscono in pagina", () => {
    const t = (e, u, turno = "Mattina") => campo.testoOrari(campo.orariPresenza(p(OGGI_R, turno, "o1", "presente", e, u)));
    eq(t("06:00", "14:00"), "Dalle 06:00 alle 14:00 · 8 h", "il turno intero");
    eq(t("22:00", "06:00", "Notte"), "Dalle 22:00 alle 06:00 del giorno dopo · 8 h",
       "e la notte dice a chiare lettere che l'uscita è il giorno dopo");
    eq(t("06:10", ""), "Entrato alle 06:10 · ora di uscita non dichiarata",
       "a metà turno l'uscita non c'è, e non si finge che ci sia");
    eq(t("", "14:00"), "Uscito alle 14:00 · ora di entrata non dichiarata", "e viceversa");
    eq(t("", ""), "", "senza orari la frase è vuota: a dire «non dichiarati» ci pensa la pagina");
    eq(campo.testoOrari(null), "", "e senza riga nemmeno");
  });

  test("Campo · orari: quelli PROPOSTI escono dal turno standard, e l'uscita solo se c'è una durata", () => {
    eq(campo.orariProposti(DUR, IERI, "Mattina"), { entrata: "06:00", uscita: "14:00" },
       "sei più otto ore dichiarate");
    eq(campo.orariProposti(DUR, IERI, "Notte"), { entrata: "22:00", uscita: "06:00" },
       "e la notte scavalca la mezzanotte anche nella proposta");
    /* ⛔ SENZA DURATA DICHIARATA NON SI PROPONE NESSUNA USCITA. Proporne una
       vorrebbe dire inventare l'ora in cui il turno è finito — cioè proprio il
       buco che gli orari esistono per chiudere, riaperto dal lato della
       comodità. */
    eq(campo.orariProposti([], IERI, "Mattina"), { entrata: "06:00", uscita: "" },
       "niente durata, niente uscita proposta");
    eq(campo.orariProposti(DUR, IERI, "Serale"), { entrata: "", uscita: "" }, "e un turno che non esiste non propone niente");
  });

  test("Campo · orari: IL CASO PER CUI QUESTO CANTIERE ESISTE — chi resta due ore in più", () => {
    /* Il Pomeriggio dichiara otto ore: 14:00 → 22:00, e la Mattina dopo
       comincia alle 6. Otto ore di riposo, già sotto la soglia. Ma questa
       persona è rimasta fino a mezzanotte a finire un carico: il riposo vero è
       di SEI ore, e fino a ieri l'app non poteva saperlo. */
    const senza = campo.riposoPrimaDelTurno("o1",
      [p(IERI, "Pomeriggio", "o1", "presente", "", ""), p(IERI, "Notte", "o1", "assente", "", "")],
      DUR, OGGI_R, "Mattina");
    contiene(senza, { stato: "sotto", ore: 8, daInizio: "turno", daFine: "durata", attendibile: null },
             "senza orari: il numero è quello di prima, e adesso dice da dove viene");
    const con = campo.riposoPrimaDelTurno("o1",
      [p(IERI, "Pomeriggio", "o1", "presente", "14:00", "00:00"), p(IERI, "Notte", "o1", "assente", "", "")],
      DUR, OGGI_R, "Mattina");
    contiene(con, { stato: "sotto", ore: 6, daFine: "orario", attendibile: true },
             "con l'ora di uscita vera il riposo scende a sei ore, ed è una MISURA");
    ok(/dagli orari registrati/.test(campo.testoRiposo(con)), "e la frase lo dice: " + campo.testoRiposo(con));
    ok(/stima/.test(campo.testoRiposo(senza)), "mentre l'altra dichiara di essere una stima: " + campo.testoRiposo(senza));
  });

  test("Campo · orari: l'ora vera taglia nei DUE versi, e quello che assolve si dichiara uguale", () => {
    /* ⚠️ Il verso comodo va provato quanto quello scomodo: se l'ora vera
       potesse solo accusare non sarebbe una misura, sarebbe un sospetto. */
    const P = [p(IERI, "Pomeriggio", "o1", "presente", "14:00", "18:00"), p(IERI, "Notte", "o1", "assente", "", "")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "regolare", ore: 12, daFine: "orario" },
             "uscito alle 18 invece che alle 22: dodici ore, e la violazione che il piano faceva vedere non c'era");
  });

  test("Campo · orari: conta anche l'entrata di QUESTO turno", () => {
    const base = [p(IERI, "Pomeriggio", "o1", "presente", "14:00", "22:00"), p(IERI, "Notte", "o1", "assente", "", "")];
    const tardi = campo.riposoPrimaDelTurno("o1",
      base.concat([p(OGGI_R, "Mattina", "o1", "presente", "09:00", "")]), DUR, OGGI_R, "Mattina");
    contiene(tardi, { stato: "regolare", ore: 11, daInizio: "orario" },
             "entrato alle 9 invece che alle 6: undici ore, ed è vero");
    const presto = campo.riposoPrimaDelTurno("o1",
      base.concat([p(OGGI_R, "Mattina", "o1", "presente", "05:00", "")]), DUR, OGGI_R, "Mattina");
    contiene(presto, { stato: "sotto", ore: 7, daInizio: "orario" },
             "entrato alle 5: sette ore, e la violazione che l'orario nominale nascondeva si vede");
  });

  test("Campo · orari: l'ora di uscita basta anche dove la durata non è mai stata dichiarata", () => {
    // ⛔ è il caso in cui il conto passava da «non misurabile» a una misura:
    // prima serviva per forza la durata del turno, adesso basta che qualcuno
    // abbia scritto quando se n'è andato
    const P = [p(IERI, "Pomeriggio", "o1", "presente", "", "22:00"), p(IERI, "Notte", "o1", "assente", "", "")];
    contiene(campo.riposoPrimaDelTurno("o1", P, [], OGGI_R, "Mattina"),
             { stato: "sotto", ore: 8, daFine: "orario" }, "nessuna durata dichiarata, e il numero c'è lo stesso");
    // e senza né l'una né l'altra resta non misurabile, con la ragione che le nomina tutt'e due
    const vuoto = campo.riposoPrimaDelTurno("o1",
      [p(IERI, "Pomeriggio", "o1", "presente", "", ""), p(IERI, "Notte", "o1", "assente", "", "")], [], OGGI_R, "Mattina");
    eq(vuoto.stato, "non-misurabile", "senza uscita e senza durata non si inventa");
    ok(/ora di uscita/.test(vuoto.perche) && /durata dichiarata/.test(vuoto.perche),
       "e la ragione dice quali sono le due strade chiuse: " + vuoto.perche);
  });

  test("Campo · orari: un orario che non regge accusa, ma col dubbio scritto accanto", () => {
    /* Fra «lo uso e lo segnalo» e «lo ignoro e ripiego sulla durata» si è
       scelto il primo: ignorarlo tornerebbe alla stima, cioè al numero più
       tranquillo, proprio nel caso in cui qualcosa non torna. */
    const P = [p(IERI, "Pomeriggio", "o1", "presente", "14:00", "13:00"), p(IERI, "Notte", "o1", "assente", "", "")];
    const r = campo.riposoPrimaDelTurno("o1", P, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", attendibile: false, daFine: "orario" },
             "ventitré ore di turno: il riposo che ne esce è sotto, e va guardato");
    ok(/orari da controllare/.test(campo.testoRiposo(r)), "e la frase porta il dubbio: " + campo.testoRiposo(r));
  });

  test("Campo · orari: le presenze salvate PRIMA di questo cantiere rispondono come rispondevano", () => {
    // ⛔ nessuna organizzazione si ritrova i numeri cambiati dall'oggi al
    // domani: una riga d'appello senza i due campi nuovi non è un dato rotto
    const vecchie = [{ data: IERI, turno: "Pomeriggio", operatoreId: "o1", stato: "presente", ora: "14:03" },
                     { data: IERI, turno: "Notte", operatoreId: "o1", stato: "assente", ora: "22:00" }];
    const r = campo.riposoPrimaDelTurno("o1", vecchie, DUR, OGGI_R, "Mattina");
    contiene(r, { stato: "sotto", ore: 8, misurabile: true, limite: "", buchi: 0, daInizio: "turno", daFine: "durata" },
             "stesso stato e stesso numero di prima");
  });

  test("Campo · orari: il riepilogo del turno non spaccia mezze ore per ore intere", () => {
    const OP = [{ id: "o1", nome: "A", squadra: "Squadra A", stato: "in-forza" },
                { id: "o2", nome: "B", squadra: "Squadra A", stato: "in-forza" },
                { id: "o3", nome: "C", squadra: "Squadra A", stato: "in-forza" },
                { id: "o4", nome: "D", squadra: "Squadra A", stato: "in-forza" },
                { id: "o5", nome: "E", squadra: "Squadra A", stato: "non-disponibile" }];
    const P = [p(OGGI_R, "Mattina", "o1", "presente", "06:00", "14:00"),
               p(OGGI_R, "Mattina", "o2", "presente", "06:30", ""),
               p(OGGI_R, "Mattina", "o3", "presente", "", ""),
               p(OGGI_R, "Mattina", "o4", "assente", "", "")];
    const q = campo.orariDiTurno(OP, P, OGGI_R, "Mattina", "");
    contiene(q, { totale: 3, completi: 1, parziali: 1, senza: 1, daControllare: 0 },
             "chi è assente e chi non è disponibile restano fuori: ore da dichiarare non ne hanno");
    /* ⛔ 480 MINUTI SONO UN PAVIMENTO, NON UN TOTALE. Una sola persona su tre
       ha gli orari interi: presentare la sua somma come «le ore del turno»
       sarebbe la disponibilità calcolata su mezzo denominatore. */
    contiene(q, { minuti: 480, limite: "almeno" }, "e il totale si dichiara un pavimento");
    eq(q.completi + q.parziali + q.senza, q.totale, "i tre conti coprono tutte le righe");
    const tutti = campo.orariDiTurno(OP, [p(OGGI_R, "Mattina", "o1", "presente", "06:00", "14:00")],
                                     OGGI_R, "Mattina", "");
    contiene(tutti, { totale: 1, completi: 1, minuti: 480, limite: "" },
             "quando li hanno tutti, il totale è un totale");
    // ⛔ e senza nessuno il totale è `null`, mai zero: «0 h lavorate» è
    // un'affermazione, e in un turno che nessuno ha spuntato è falsa
    contiene(campo.orariDiTurno(OP, [], OGGI_R, "Mattina", ""),
             { totale: 0, completi: 0, minuti: null, limite: "" }, "nessun presente, nessun numero");
  });

  test("Campo · orari: una riga che non regge esce dal totale, non dalla vista", () => {
    /* ⛔ TROVATO IN UNO SCATTO, non leggendo il codice: la nota diceva «le ore
       lavorate note sono almeno 23 h» e sotto «1 riga ha orari da controllare».
       Le ventitré ore erano proprio quella riga. Un pavimento che contiene ore
       che nessuno ha lavorato non è prudente: è FALSO. */
    const OP = [{ id: "o1", nome: "A", squadra: "Squadra A", stato: "in-forza" },
                { id: "o2", nome: "B", squadra: "Squadra A", stato: "in-forza" }];
    const P = [p(OGGI_R, "Mattina", "o1", "presente", "06:00", "14:00"),
               p(OGGI_R, "Mattina", "o2", "presente", "06:00", "05:00")];
    const q = campo.orariDiTurno(OP, P, OGGI_R, "Mattina", "");
    contiene(q, { totale: 2, completi: 2, daControllare: 1, minuti: 480, limite: "almeno" },
             "le ventitré ore restano contate fra le righe da controllare e fuori dal totale");
    // ⚠️ e il caso in cui l'UNICA riga completa è quella dubbia: allora non
    // c'è nessun totale da dare, e si dice `null` invece di scriverne uno
    const solo = campo.orariDiTurno(OP, [p(OGGI_R, "Mattina", "o1", "presente", "06:00", "05:00")],
                                    OGGI_R, "Mattina", "");
    contiene(solo, { totale: 1, completi: 1, daControllare: 1, minuti: null, limite: "" },
             "nessuna riga che regge: nessun numero");
  });

  test("Campo · orari: sulla dimostrazione si vede la differenza fra la misura e la stima", () => {
    const D = campo.DEMO, oggi = campo.oggiISO();
    const m = campo.riposoDiTurno(D.operatori, D.presenze, D.durate, oggi, "Mattina", "");
    const per = {}; m.righe.forEach((r) => { per[r.operatore.id] = r; });
    // o1: uscita vera alle 23:45 di ieri (la durata dichiarata diceva le 22) e
    // entrata vera alle 06:10 di oggi → sei ore e venticinque
    contiene(per.o1, { stato: "sotto", ore: 6.42, daInizio: "orario", daFine: "orario" },
             "o1 è rimasto oltre, e adesso il riposo lo dice");
    // o2: nessuna uscita dichiarata → si ripiega sulla durata, e la frase lo scrive
    contiene(per.o2, { stato: "regolare", daFine: "durata" }, "o2 non ha dichiarato l'uscita");
    ok(/stima: manca l'ora di uscita/.test(campo.testoRiposo(per.o2, (d) => d)),
       "e chi legge sa che sta guardando una stima: " + campo.testoRiposo(per.o2, (d) => d));
    /* ⛔ LA DIMOSTRAZIONE DEVE CONTENERE ANCHE LA META' CHE MANCA, se no mostra
       una funzione che nella vita vera non si vede mai in quello stato: al
       turno di Mattina, che è IN CORSO, due persone hanno l'entrata e nessuna
       ha l'uscita. */
    const o = campo.orariDiTurno(D.operatori, D.presenze, oggi, "Mattina", "");
    contiene(o, { totale: 2, completi: 0, parziali: 2, senza: 0, minuti: null },
             "turno in corso: entrati sì, usciti non ancora — e nessun totale di ore");
    ok(campo.testoOrari(o.righe[0].orari).includes("non dichiarata"),
       "e la frase lo dice invece di lasciare la riga muta");
  });
}

// ── Flotta · pagella del parco (costo orario × disponibilità)
{
  const D = flotta.DEMO;
  const OGGI = new Date("2026-08-01T09:00:00Z");
  const costi = flotta.costoOrarioMezzo(D.interventi, D.rifornimenti);
  const aff = flotta.affidabilitaFlotta(D.fermi, D.mezzi, 30, OGGI);
  const pag = () => flotta.pagellaMezzi(costi, aff, D.mezzi);
  // righe di costo finte, per costruire i verdetti che la dimostrazione non dà.
  // ⚠️ `spesaInFinestra` è il numeratore del €/h dal 05/08 (la finestra dei
  //    contatori), e `totale` è la spesa DA SEMPRE: qui coincidono perché la
  //    riga finta non ha niente fuori finestra — ma vanno scritti tutt'e due,
  //    o la media della pagella non ha da dove nascere.
  const rc = (mezzo, euroOra, extra = {}) =>
    ({ mezzo, totale: euroOra * 100, spesaInFinestra: euroOra * 100, ore: 100, euroOra,
       da: "2026-07-01", a: "2026-07-31", fuori: { interventi: 0, costo: 0 },
       perche: "", parziale: false, ...extra });

  test("Flotta · pagella: compone senza ricalcolare — €/h e disponibilità sono quelli delle due schermate", () => {
    const p = pag();
    const perNome = {}; [...p.righe, ...p.senzaCosto].forEach((r) => { perNome[r.mezzo] = r; });
    for (const c of costi) {
      if (!perNome[c.mezzo]) continue;
      eq(perNome[c.mezzo].euroOra, c.euroOra, c.mezzo + ": il €/h è quello di costoOrarioMezzo, non un secondo conto");
      eq(perNome[c.mezzo].totale, c.totale, c.mezzo + ": la spesa è quella di costoOrarioMezzo");
    }
    for (const m of aff.mezzi) {
      eq(perNome[m.mezzo].disponibilita, m.pct, m.mezzo + ": la disponibilità è quella di affidabilitaFlotta");
      eq(perNome[m.mezzo].giorniFermo, m.giorni, m.mezzo + ": i giorni di fermo sono quelli di affidabilitaFlotta");
    }
    eq(p.mediaDisponibilita, aff.pct, "il riferimento è la disponibilità del parco già calcolata");
    eq(p.finestra, aff.finestra, "la finestra è quella dei fermi, e riguarda solo la disponibilità");
  });

  test("Flotta · pagella: tutto il parco compare, anche chi non ha né spese né fermi", () => {
    const p = pag();
    const nomi = [...p.righe, ...p.senzaCosto].map((r) => r.mezzo).sort();
    eq(nomi, D.mezzi.map((m) => flotta.nomeBreve(m.nome)).sort(),
       "sei mezzi in parco, sei righe: nessuno sparisce perché non ha dati");
    eq(p.confrontabili + p.senzaCosto.length, D.mezzi.length, "le due liste coprono il parco e non si sovrappongono");
  });

  test("Flotta · pagella: la media della flotta è pesata sulle ore, non la media dei €/h", () => {
    const p = pag();
    const conOre = costi.filter((c) => c.euroOra != null && c.ore > 0);
    /* ⚠️ IL NUMERATORE È `spesaInFinestra`, NON `totale` — corretto il 05/08
       insieme al €/h. Con `totale` la media della dimostrazione veniva 54,25
       €/h mentre le tre righe da mediare stanno fra 28,18 e 38,96: una media
       PIÙ ALTA DI OGNI SUO ADDENDO, e ogni scostamento che ne nasceva era il
       confronto fra la spesa da sempre e un €/h di finestra. */
    const spesa = conOre.reduce((t, c) => t + c.spesaInFinestra, 0);
    const ore = conOre.reduce((t, c) => t + c.ore, 0);
    eq(p.mediaEuroOra, Math.round(100 * spesa / ore) / 100, "tutti i costi diviso tutte le ore");
    eq(p.oreTotali, ore, "le ore su cui la media è calcolata sono dichiarate");
    eq(p.spesaMisurata, Math.round(100 * spesa) / 100, "e anche la spesa");
    const min = Math.min(...conOre.map((c) => c.euroOra)), max = Math.max(...conOre.map((c) => c.euroOra));
    ok(p.mediaEuroOra >= min && p.mediaEuroOra <= max,
       "e la media sta FRA il €/h più basso e il più alto: se ne uscisse fuori (54,25 su un parco fra "
       + min + " e " + max + ") vorrebbe dire che numeratore e denominatore misurano due cose diverse");
    const mediaDeiNumeri = Math.round(100 * conOre.reduce((t, c) => t + c.euroOra, 0) / conOre.length) / 100;
    ok(p.mediaEuroOra !== mediaDeiNumeri,
       "sulla dimostrazione le due medie differiscono: la prova distingue davvero (pesata "
       + p.mediaEuroOra + " ≠ media dei numeri " + mediaDeiNumeri + ")");
  });

  test("Flotta · pagella: la disponibilità di riferimento è la media vera delle righe", () => {
    const p = pag();
    const tutte = [...p.righe, ...p.senzaCosto];
    const media = Math.round(10 * tutte.reduce((t, r) => t + r.disponibilita, 0) / tutte.length) / 10;
    eq(media, p.mediaDisponibilita,
       "il riferimento del parco è esattamente la media dei pct di riga: se divergessero, ogni scostamento sarebbe falso");
  });

  test("Flotta · pagella: senza le ore la macchina esce dalla classifica e dice perché — non «0 €/h»", () => {
    const p = pag();
    const d3 = p.senzaCosto.find((r) => r.mezzo === "Dumper D3");
    ok(d3, "il Dumper D3 non ha nessuna lettura del contatore: sta fra i senza costo orario");
    eq(d3.euroOra, null, "e il suo €/h resta null: uno zero lo farebbe sembrare il più conveniente del parco");
    eq(d3.verdetto, "costo-ignoto", "il verdetto lo dichiara invece di tacere");
    ok(/contatore/.test(d3.perche), "e dice che cosa manca: " + d3.perche);
    eq(p.senzaCosto[0].mezzo, "Dumper D3",
       "in cima ai non giudicabili c'è chi ha speso di più: 5.090 € su cui nessuno può dire se siano tanti");
    ok(d3.totale > Math.max(...p.righe.map((r) => r.totale)),
       "ed è proprio la macchina che ha speso più di ogni altra in classifica");
    // la metà che SI sa non si perde per colpa della metà che non si sa
    eq(d3.disponibilita, aff.mezzi.find((m) => m.mezzo === "Dumper D3").pct,
       "la disponibilità del D3 resta scritta: è misurata, e il costo ignoto non la cancella");
    ok(d3.giorniFermo > 0 && d3.aperti > 0, "con i suoi giorni persi e il fermo ancora aperto");
    ok(p.righe.every((r) => r.euroOra != null), "in classifica non entra nessuno col €/h ignoto");
  });

  test("Flotta · pagella: la banda evita che mezzo parco finisca segnalato ogni giorno", () => {
    const p = pag();
    eq(p.banda, flotta.BANDA_PAGELLA, "la tolleranza è dichiarata, non nascosta nel codice");
    /* ⚠️ I DUE RUOLI SI SONO SCAMBIATI IL 05/08, e non per un ritocco di
       soglia: col €/h calcolato sulla finestra dei contatori il Dumper D1
       scende da 63,03 a 28,61 (portava dentro 2.100 € di gomme cambiate sei
       settimane prima che qualcuno scrivesse il contatore) e RIENTRA nella
       banda; l'Escavatore E1, che di spesa fuori finestra ne ha poca, resta a
       38,96 su una media di 32,38 ed è lui a uscire. La segnalazione era
       puntata sulla macchina sbagliata. */
    const d1 = p.righe.find((r) => r.mezzo === "Dumper D1");
    ok(d1.scostamentoCosto < 0 && Math.abs(d1.scostamentoCosto) < flotta.BANDA_PAGELLA.costo,
       "D1 sta sotto la media ma dentro la banda: " + d1.scostamentoCosto + "%");
    eq(d1.costo, "linea", "quindi sul costo è in linea, non «costa meno»");
    const e1 = p.righe.find((r) => r.mezzo === "Escavatore E1");
    ok(e1.scostamentoCosto > flotta.BANDA_PAGELLA.costo, "E1 supera la banda: " + e1.scostamentoCosto + "%");
    eq(e1.costo, "piu", "e allora si segnala");
    eq(e1.verdetto, "costa", "ma la sua disponibilità è del 100%: costa, non «costa e si ferma»");
    eq(p.righe[0].mezzo, "Escavatore E1", "e in cima alla classifica c'è lui");
  });

  test("Flotta · pagella: «si ferma di più» si dice sui fermi, non sulla percentuale al contrario", () => {
    const p = flotta.pagellaMezzi(
      [rc("Dumper D3", 5), rc("Escavatore E1", 50), rc("Dumper D1", 50)], aff, D.mezzi);
    const d3 = p.righe.find((r) => r.mezzo === "Dumper D3");
    ok(d3.disponibilita < p.mediaDisponibilita, "il D3 è disponibile MENO della media: " + d3.disponibilita + "%");
    ok(d3.scostamentoFermo < 0, "lo scostamento è negativo");
    eq(d3.fermo, "piu", "e la parola dice «si ferma più della media», che è il verso in cui si legge");
    eq(d3.costo, "meno", "sul costo invece sta sotto");
    eq(d3.verdetto, "ferma", "verdetto: si ferma, non costa");
  });

  test("Flotta · pagella: costa E si ferma è il verdetto che va in cima a tutto", () => {
    const p = flotta.pagellaMezzi(
      [rc("Dumper D3", 200), rc("Escavatore E1", 10), rc("Dumper D1", 10)], aff, D.mezzi);
    eq(p.righe[0].mezzo, "Dumper D3", "la macchina che costa e si ferma è la prima da guardare");
    eq(p.righe[0].verdetto, "costa-e-ferma", "e il verdetto lo dice in una parola");
    eq(p.righe[0].costo, "piu", "sopra la media sul costo");
    eq(p.righe[0].fermo, "piu", "e sopra la media sui fermi");
  });

  test("Flotta · pagella: «in linea» si dice solo se hanno parlato tutt'e due gli assi", () => {
    // spesa a zero: le ore ci sono, ma senza media il costo non dice niente
    const zero = flotta.pagellaMezzi(
      [rc("Escavatore E1", 0), rc("Dumper D1", 0)], aff, D.mezzi);
    eq(zero.mediaEuroOra, null, "con spesa zero non c'è una media con cui confrontarsi");
    const e1 = zero.righe.find((r) => r.mezzo === "Escavatore E1");
    eq(e1.costo, null, "e allora il costo non si giudica");
    eq(e1.verdetto, "solo-meta",
       "il verdetto NON è «in linea»: una metà sola letta non è una macchina a posto");
    eq(zero.pochi, true, "e senza media non c'è nemmeno una classifica");
    // senza la finestra dei fermi manca l'altra metà
    const senzaFer = flotta.pagellaMezzi(costi, null, D.mezzi);
    eq(senzaFer.mediaDisponibilita, null, "senza affidabilità non c'è disponibilità di riferimento");
    ok(senzaFer.righe.every((r) => r.fermo === null), "nessuna riga ha un giudizio sui fermi");
    ok(senzaFer.righe.every((r) => r.verdetto !== "in-linea"),
       "e nessuna riga si dichiara «in linea» avendo letto solo il costo");
    eq(senzaFer.misurabile, false, "la non-misurabilità è dichiarata");
    ok(/non è stata calcolata/.test(senzaFer.percheDisponibilita), senzaFer.percheDisponibilita);
  });

  test("Flotta · pagella: nessun fermo registrato non è un parco sano", () => {
    const vuoto = flotta.affidabilitaFlotta([], D.mezzi, 30, OGGI);
    const p = flotta.pagellaMezzi(costi, vuoto, D.mezzi);
    eq(p.mediaDisponibilita, 100, "senza fermi il conto dà 100% a tutte");
    ok(p.righe.every((r) => r.fermo === "linea"), "e nessuna si scosta da nessuna");
    eq(p.misurabile, false,
       "ma la bandiera dice che l'asse non distingue niente: il 100% è l'assenza di dati, non una misura");
    ok(/Nessun fermo registrato/.test(p.percheDisponibilita), p.percheDisponibilita);
    eq(pag().misurabile, true, "mentre con i fermi della dimostrazione la disponibilità misura davvero");
  });

  test("Flotta · pagella: con una macchina sola non c'è una classifica da leggere", () => {
    const p = flotta.pagellaMezzi(costi.filter((c) => c.mezzo === "Escavatore E1"), aff, D.mezzi);
    eq(p.confrontabili, 1, "una sola ha il €/h");
    eq(p.pochi, true, "e allora `pochi` lo dichiara");
    ok(/una sola/.test(p.perchePochi), p.perchePochi);
    eq(p.righe[0].scostamentoCosto, 0, "confrontata con sé stessa lo scostamento è zero: un numero che non vuol dire niente");
    eq(pag().pochi, false, "con tre macchine invece la classifica si legge");
  });

  test("Flotta · pagella: la spesa dei mezzi non più in parco si dichiara, non sparisce", () => {
    const p = flotta.pagellaMezzi([...costi, rc("Pala rottamata", 90)], aff, D.mezzi);
    eq(p.fuoriParco, 1, "una riga di costo non ha un mezzo in parco");
    eq(p.fuoriParcoSpesa, 9000, "e la sua spesa è dichiarata a parte");
    eq(p.mediaEuroOra, pag().mediaEuroOra, "senza entrare nella media, che non avrebbe un denominatore");
    eq(pag().fuoriParco, 0, "sulla dimostrazione non ce ne sono");
  });

  test("Flotta · pagella: la spesa che è un MINIMO resta marcata anche qui", () => {
    const p = flotta.pagellaMezzi([rc("Escavatore E1", 40, { parziale: true, interventiSenzaCosto: 2 }),
                                   rc("Dumper D1", 40)], aff, D.mezzi);
    const e1 = p.righe.find((r) => r.mezzo === "Escavatore E1");
    eq(e1.parziale, true,
       "un intervento senza costo rende il totale un minimo: se si perdesse qui, un «in linea» nascerebbe da una spesa incompleta");
    eq(p.righe.find((r) => r.mezzo === "Dumper D1").parziale, false, "e chi non ne ha non è marcato");
  });

  test("⛔ Flotta · pagella: la finestra del €/h viaggia con la riga, e ogni macchina ha la sua", () => {
    /* I due assi della pagella non coprono lo stesso periodo — la
       disponibilità è la finestra dei fermi (una sola, del parco), il costo è
       quella dei contatori (una PER MACCHINA). La pagella lo scriveva già per
       il primo; se il periodo del secondo non arrivasse fino alla riga, i due
       numeri accanto si leggerebbero come se fossero lo stesso mese. */
    const p = pag();
    const perNome = {}; costi.forEach((c) => { perNome[c.mezzo] = c; });
    let conFinestra = 0;
    for (const r of p.righe) {
      eq([r.da, r.a], [perNome[r.mezzo].da, perNome[r.mezzo].a],
         r.mezzo + ": la finestra è quella di costoOrarioMezzo, non un secondo conto");
      eq(r.fuori, perNome[r.mezzo].fuori, r.mezzo + ": e anche la spesa che ci cade fuori");
      ok(r.da && r.a, r.mezzo + ": chi sta in classifica ha per forza una finestra");
      conFinestra++;
    }
    eq(conFinestra, 3, "tre macchine in classifica, tre finestre dichiarate");
    const finestre = new Set(p.righe.map((r) => r.da + "→" + r.a));
    ok(finestre.size > 1,
       "e non sono la stessa per tutte: sarebbero " + [...finestre].join(", ")
       + " — una finestra sola nel riepilogo sarebbe una bugia su due macchine su tre");
    // chi non ha il €/h non ha nemmeno una finestra da mostrare: non se ne inventa una
    for (const r of p.senzaCosto) eq([r.da, r.a], [null, null], r.mezzo + ": nessuna finestra dove non c'è il costo");
  });

  test("Flotta · pagella: parco vuoto non risponde niente di tranquillo", () => {
    const p = flotta.pagellaMezzi([], flotta.affidabilitaFlotta([], [], 30, OGGI), []);
    eq(p.righe, [], "nessuna riga");
    eq(p.senzaCosto, [], "nessun non giudicabile");
    eq(p.mediaEuroOra, null, "nessuna media del costo");
    eq(p.mediaDisponibilita, null, "nessuna disponibilità: il parco non ha giorni-macchina");
    eq(p.pochi, true, "e la mancanza di confronto è dichiarata");
    eq(p.misurabile, false, "come la mancanza di misura sui fermi");
  });

  test("Flotta · pagella: i verdetti che la funzione sa dire sono sei, e nessun altro", () => {
    const casi = [
      pag(),
      flotta.pagellaMezzi([rc("Dumper D3", 5), rc("Escavatore E1", 50), rc("Dumper D1", 50)], aff, D.mezzi),
      flotta.pagellaMezzi([rc("Dumper D3", 200), rc("Escavatore E1", 10), rc("Dumper D1", 10)], aff, D.mezzi),
      flotta.pagellaMezzi([rc("Escavatore E1", 0), rc("Dumper D1", 0)], aff, D.mezzi),
    ];
    const visti = new Set();
    for (const p of casi) [...p.righe, ...p.senzaCosto].forEach((r) => visti.add(r.verdetto));
    eq([...visti].sort(),
       ["costa", "costa-e-ferma", "costo-ignoto", "ferma", "in-linea", "solo-meta"],
       "tutti e sei escono davvero da questi casi: la mappa della pagina deve coprirli tutti (regola 18)");
  });

  test("⛔ Flotta · pagella: col gasolio della finestra la media SCENDE e un mezzo esce dalla banda", () => {
    /* ⛔ LE PROVE DELLA PAGELLA SONO TUTTE RELATIVE, e questa è la ragione per
       cui ne serviva una assoluta: sono scritte come «la media è la spesa delle
       righe diviso le loro ore», quindi restano verdi con QUALUNQUE numeratore
       — anche col gasolio intero, primo pieno compreso, che è il difetto
       corretto il 05/08. Una prova che deriva il valore atteso dagli stessi
       dati che misura non sa dire che il dato è cambiato.
       Qui i numeri della dimostrazione sono scritti a mano, e accanto c'è il
       parco come sarebbe col difetto rimesso: è il confronto affiancato, dentro
       la suite invece che in uno scratchpad che alla prossima sessione non
       esiste più. */
    const p = pag();
    eq([p.mediaEuroOra, p.spesaMisurata, p.oreTotali], [20.68, 3102, 150],
       "la media pesata del parco: 3.102 € di finestra su 150 ore misurate");
    const asse = Object.fromEntries(p.righe.map((r) => [r.mezzo, [r.euroOra, r.scostamentoCosto, r.costo]]));
    eq(asse, { "Escavatore E1": [26.11, 26.3, "piu"], "Dumper D1": [19.02, -8, "linea"],
               "Pala P1": [14.55, -29.6, "meno"] },
       "€/h, scostamento dalla media e asse del costo, mezzo per mezzo");
    eq(p.righe.map((r) => r.mezzo), ["Escavatore E1", "Dumper D1", "Pala P1"],
       "e l'ordine della classifica, dal peggiore");

    /* IL PARCO COME SAREBBE COL PRIMO PIENO DENTRO (il difetto), costruito
       dalle stesse righe: `officinaInFinestra` più TUTTO il gasolio. Non è una
       seconda implementazione del €/h — è la fotografia di quello che c'era
       scritto prima, e serve a far vedere di quanto si sposta. */
    const conPrimoPieno = costi.map((c) => c.euroOra == null ? c : {
      ...c,
      spesaInFinestra: Math.round(100 * (c.officinaInFinestra + c.carburante)) / 100,
      euroOra: Math.round(100 * (c.officinaInFinestra + c.carburante) / c.ore) / 100,
    });
    const q = flotta.pagellaMezzi(conPrimoPieno, aff, D.mezzi);
    eq(q.mediaEuroOra, 32.38, "col gasolio intero la media del parco era 32,38 €/h, il 56,6% più alta");
    const asseQ = Object.fromEntries(q.righe.map((r) => [r.mezzo, [r.euroOra, r.scostamentoCosto, r.costo]]));
    eq(asseQ, { "Escavatore E1": [38.96, 20.3, "piu"], "Dumper D1": [28.61, -11.6, "linea"],
                "Pala P1": [28.18, -13, "linea"] },
       "e i tre €/h gonfiati, con gli scostamenti che ne uscivano");
    /* ⛔ IL PUNTO CHE VALE PIÙ DEI NUMERI: la Pala P1 stava DENTRO la banda del
       ±15% e ne esce dal lato buono. Il verdetto resta «in-linea» (l'asse del
       costo entra nei verdetti solo quando costa di PIÙ), ma l'asse che la
       pagina scrive accanto alla riga cambia parola: da «in linea con la
       media» a «costa meno della media». Cioè la correzione non sposta solo
       una cifra, sposta una FRASE che qualcuno legge per decidere. */
    eq([asseQ["Pala P1"][2], asse["Pala P1"][2]], ["linea", "meno"],
       "la Pala P1 esce dalla banda: era «in linea», adesso «costa meno»");
    eq(q.righe.map((r) => r.verdetto), p.righe.map((r) => r.verdetto),
       "gli altri verdetti no: sulla dimostrazione nessuno passa a «costa di più» (e va detto, non gonfiato)");
  });
}

// ── Scudo · appaltatori e DUVRI ──────────────────────────────────────
// L'art. 26 D.Lgs 81/08 mette in capo al committente due obblighi che nascono
// insieme: verificare l'idoneità tecnico-professionale dell'impresa, e
// redigere il documento di valutazione dei rischi da interferenze. In cava il
// secondo non è il DUVRI ma il DSS coordinato (art. 9 D.Lgs 624/96), che in
// più vuole la FIRMA dell'appaltatore.
// Le prove sono scritte attorno alla direzione pericolosa: non «sbaglia il
// conto», ma «risponde la cosa tranquilla su un dato che non ha».
{
  const OGGI = new Date("2026-08-01T09:00:00");
  const CAVA = { id: "k1", nome: "Cava Monte Alto", tipo: "cava" };
  const FUORI = { id: "k2", nome: "Cantiere cliente", tipo: "cantiere" };
  const IMPRESA = { id: "a1", ragioneSociale: "Trasporti Rossi" };
  const QUALIFICATA = [
    { id: "d1", appaltatoreId: "a1", tipoQualifica: "cciaa", scadenza: "2027-01-01" },
    { id: "d2", appaltatoreId: "a1", tipoQualifica: "autocert" },
  ];

  test("Scudo · qualifica: un'impresa senza nessun documento NON è idonea, è NON VERIFICATA", () => {
    const q = scudo.qualificaAppaltatore(IMPRESA, [], OGGI);
    eq([q.esito, q.noto], ["non-verificato", false],
       "zero documenti: l'esito ha un nome suo e la bandiera è giù");
    ok(/non lo sappiamo/i.test(q.perche), "e la ragione dice la differenza: «" + q.perche + "»");
    ok(/Non lo sappiamo/.test(scudo.descriviQualifica(q)),
       "chi consuma la bandiera dentro il modulo antepone il dubbio (regola 20)");
  });

  test("Scudo · qualifica: i due documenti dell'art. 26 bastano, il DURC da solo no", () => {
    eq(scudo.qualificaAppaltatore(IMPRESA, QUALIFICATA, OGGI).esito, "verificato",
       "certificato camerale + autocertificazione ex art. 47 DPR 445/2000");
    eq(scudo.qualificaAppaltatore(IMPRESA, [QUALIFICATA[0]], OGGI).mancanti,
       ["Autocertificazione dei requisiti"], "manca il secondo dei due, e viene detto per nome");
    eq(scudo.qualificaAppaltatore(IMPRESA,
         [{ id: "x", appaltatoreId: "a1", tipoQualifica: "durc", scadenza: "2027-01-01" }], OGGI).esito,
       "incompleto",
       "il DURC non è nell'elenco dell'art. 26: averlo non copre i due che lo sono");
    eq(scudo.tipoDocAppaltatore("durc").obbligatorio, false,
       "e infatti non è dichiarato obbligatorio: dirlo tale sarebbe citare male una norma");
  });

  test("Scudo · qualifica: scaduto, senza data e «di un altro» sono tre cose diverse", () => {
    eq(scudo.qualificaAppaltatore(IMPRESA,
         [{ ...QUALIFICATA[0], scadenza: "2026-01-01" }, QUALIFICATA[1]], OGGI).esito, "scaduto",
       "la scadenza la giudica statoScadenza, che è statoScadenzaHSE di shared/ — non una seconda copia");
    const sd = scudo.qualificaAppaltatore(IMPRESA, [{ ...QUALIFICATA[0], scadenza: null }, QUALIFICATA[1]], OGGI);
    eq([sd.esito, sd.noto], ["senza-data", false], "una data illeggibile non è una scadenza a posto");
    eq(scudo.qualificaAppaltatore(IMPRESA,
         [{ id: "z", appaltatoreId: "a9", tipoQualifica: "cciaa", scadenza: "2027-01-01" }], OGGI).esito,
       "non-verificato", "i documenti di un'ALTRA impresa non qualificano questa");
  });

  test("Scudo · in cava il documento è il DSS coordinato, non il DUVRI", () => {
    const c = scudo.duvriDovuto({ uominiGiorno: 1 }, CAVA);
    eq([c.sigla, c.norma, c.serve, c.sottoscrizione],
       ["DSS coordinato", "art. 9 D.Lgs 624/96", true, true],
       "un solo uomo-giorno in cava: il DSS coordinato serve lo stesso, e vuole la firma");
    const f = scudo.duvriDovuto({ uominiGiorno: 8 }, FUORI);
    eq([f.sigla, f.norma, f.sottoscrizione],
       ["DUVRI", "art. 26 c.3 D.Lgs 81/08", false], "fuori dalla cava vale la regola generale");
  });

  test("Scudo · DUVRI: «non lo so» non è «non serve» — la durata mai scritta", () => {
    const senza = scudo.duvriDovuto({}, FUORI);
    eq([senza.serve, senza.noto], [null, false],
       "⛔ uominiGiorno assente sarebbe finito a zero (`+null` fa 0, e 0 ≤ 5): "
       + "l'appalto di cui nessuno ha scritto niente sarebbe uscito ESENTE");
    ok(/non si può dire/.test(senza.perche), "e lo dice: «" + senza.perche + "»");
    eq(scudo.duvriDovuto({ uominiGiorno: 8 }, FUORI).serve, true, "sopra i cinque uomini-giorno serve");
    eq(scudo.duvriDovuto({ uominiGiorno: 3, rischiValutati: true }, FUORI).serve, false,
       "sotto i cinque, e con i rischi particolari guardati, non serve (art. 26 c.3-bis)");
    eq(scudo.duvriDovuto({ uominiGiorno: 3 }, FUORI).serve, null,
       "ma finché nessuno ha guardato i rischi l'esclusione non si può concedere: il c.3-bis dice «sempre che»");
    /* ⛔ QUESTA RIGA L'HA CHIESTA LA CONTROPROVA, ed è la combinazione che morde
       davvero: chi compila con diligenza spunta «rischi guardati» e si dimentica
       la durata. Togliendo la guardia su `uominiGiorno`, `+undefined` non è più
       un numero e l'appalto scivola fino all'ultima riga della funzione, che
       dichiara l'esclusione. Con solo `duvriDovuto({})` il difetto NON si vedeva:
       la prova c'era e il caso difeso no. */
    eq(scudo.duvriDovuto({ rischiValutati: true }, FUORI).serve, null,
       "aver guardato i rischi non rende esente un appalto di cui non si sa la durata");
  });

  test("Scudo · DUVRI: i casi esclusi contano quanto quelli inclusi", () => {
    eq(scudo.duvriDovuto({ natura: "fornitura", rischiValutati: true }, FUORI).serve, false,
       "una mera fornitura di materiali è esclusa: dirla obbligatoria farebbe fare lavoro inutile");
    eq(scudo.duvriDovuto({ natura: "intellettuale", rischiValutati: true }, FUORI).serve, false,
       "e così un servizio di natura intellettuale");
    eq(scudo.duvriDovuto({ uominiGiorno: 2, rischiValutati: true, rischiParticolari: ["esplosive"] }, FUORI).serve,
       true, "ma con atmosfere esplosive nessuna esclusione tiene, nemmeno per due giorni");
    eq(scudo.rischioParticolare("amianto").nome, "Amianto", "i cinque rischi del c.3-bis sono in elenco");
  });

  test("Scudo · costi da interferenze: un campo vuoto non è «zero euro dichiarati»", () => {
    eq([scudo.costiInterferenze({ costiSicurezza: "" }).indicati,
        scudo.costiInterferenze({ costiSicurezza: "" }).importo], [false, null],
       "⛔ `+\"\"` fa 0: senza questa guardia un campo mai compilato assolveva l'art. 26 c.5");
    eq(scudo.costiInterferenze({}).indicati, false, "e nemmeno il campo che non c'è");
    const zero = scudo.costiInterferenze({ costiSicurezza: 0 });
    eq([zero.indicati, zero.importo], [true, 0],
       "zero DICHIARATO invece è una posizione che qualcuno si è preso");
    eq(scudo.costiInterferenze({ costiSicurezza: 1200 }).importo, 1200, "e un importo si legge");
    ok(/nullità/i.test(scudo.costiInterferenze({}).perche),
       "la ragione cita la conseguenza vera: l'art. 26 c.5 li vuole indicati a pena di nullità");
  });

  test("Scudo · il DUVRI non è un allegato, è una decisione: chi, quando, per quale appalto", () => {
    const B = { uominiGiorno: 10, dataInizio: "2026-03-01" };
    eq(scudo.statoCoordinamento(B, FUORI, OGGI).stato, "non-redatto", "dovuto e non risulta redatto");
    eq(scudo.statoCoordinamento({ ...B, coordRedattore: "Ing. Bianchi" }, FUORI, OGGI).stato, "senza-data",
       "un documento di coordinamento senza data non copre nessun periodo");
    eq(scudo.statoCoordinamento({ ...B, coordData: "2026-02-20" }, FUORI, OGGI).stato, "senza-redattore",
       "e uno senza redattore non attribuisce a nessuno una responsabilità che il committente non delega");
    eq(scudo.statoCoordinamento({ ...B, coordRedattore: "Ing. Bianchi", coordData: "2026-02-20" }, FUORI, OGGI).stato,
       "in-vigore", "con tutt'e due, e datato prima dell'avvio, è in vigore");
  });

  test("Scudo · coordinamento: il documento datato DOPO l'avvio non copriva l'avvio", () => {
    const B = { uominiGiorno: 10, dataInizio: "2026-03-01", coordRedattore: "Ing. Bianchi" };
    eq(scudo.statoCoordinamento({ ...B, coordData: "2026-04-10" }, FUORI, OGGI).stato, "tardivo",
       "l'art. 26 c.3 lo vuole allegato al contratto: un mese dopo, i primi giorni erano scoperti");
    /* ⛔ IL DIFETTO CHE IL PROTOTIPO HA PRESO PRIMA DEL MODULO: confrontando le
       stringhe intere «2026-03-01T08:00» è maggiore di «2026-03-01», e un
       documento firmato LO STESSO GIORNO dell'avvio veniva dichiarato tardivo —
       un ritardo inventato da un'ora attaccata alla data. Si confrontano i giorni. */
    eq(scudo.statoCoordinamento({ ...B, coordData: "2026-03-01T08:00" }, FUORI, OGGI).stato, "in-vigore",
       "firmato lo stesso giorno, con l'ora attaccata: non è un ritardo");
    eq(scudo.statoCoordinamento({ ...B, dataInizio: null, coordData: "2026-04-10" }, FUORI, OGGI).stato, "in-vigore",
       "senza una data d'inizio leggibile il confronto non si fa: non si inventa un ritardo");
  });

  test("Scudo · in cava il DSS coordinato senza la firma dell'impresa non la impegna", () => {
    const B = { uominiGiorno: 10, dataInizio: "2026-03-01", coordRedattore: "Ing. Bianchi", coordData: "2026-02-20" };
    eq(scudo.statoCoordinamento(B, CAVA, OGGI).stato, "da-sottoscrivere",
       "art. 9 c.2 D.Lgs 624/96: è con la sottoscrizione che l'appaltatore diventa responsabile "
       + "della parte di sua competenza");
    eq(scudo.statoCoordinamento({ ...B, coordSottoscritto: true }, CAVA, OGGI).stato, "in-vigore", "firmato: in vigore");
    eq(scudo.statoCoordinamento(B, FUORI, OGGI).stato, "in-vigore",
       "il DUVRI dell'art. 26 la firma non la chiede: la differenza fra i due documenti è questa");
  });

  test("Scudo · la riga dell'appalto tiene separati i problemi dai buchi", () => {
    const SANO = { id: "p1", appaltatoreId: "a1", cantiereId: "k1", uominiGiorno: 10,
      dataInizio: "2026-03-01", coordRedattore: "Ing. Bianchi", coordData: "2026-02-20",
      coordSottoscritto: true, costiSicurezza: 900 };
    eq(scudo.statoAppalto(SANO, CAVA, IMPRESA, QUALIFICATA, OGGI).esito, "a-posto", "tutto in ordine");
    const mai = scudo.statoAppalto(SANO, CAVA, IMPRESA, [], OGGI);
    eq([mai.esito, mai.noto, mai.problemi.length, mai.ignoti.length], ["non-verificato", false, 0, 1],
       "⛔ documento perfetto ma impresa mai verificata: NON è «da sistemare» e NON è «a posto». "
       + "Sommarlo ai problemi direbbe una colpa che non è stata accertata; ignorarlo darebbe il verde");
    eq(scudo.statoAppalto({ ...SANO, costiSicurezza: "" }, CAVA, IMPRESA, QUALIFICATA, OGGI).esito,
       "da-sistemare", "i costi non indicati sono un problema vero, non un dubbio");
    eq(scudo.statoAppalto({ id: "p2", appaltatoreId: "a1", cantiereId: "k2", uominiGiorno: 2, rischiValutati: true },
         FUORI, IMPRESA, QUALIFICATA, OGGI).esito, "a-posto",
       "ma dove il documento non è dovuto i costi da interferenze non si contestano");
    eq(scudo.statoAppalto({ ...SANO, cantiereId: "kX" }, undefined, IMPRESA, QUALIFICATA, OGGI).coordinamento.sigla,
       "DUVRI", "un cantiere che non si trova non diventa una cava con le sue regole");
  });

  test("Scudo · nessun appalto registrato non è «nessuna impresa in cava»", () => {
    const vuoto = scudo.riepilogoAppalti([], [CAVA], [IMPRESA], QUALIFICATA, OGGI);
    eq([vuoto.quanti, vuoto.noto], [0, false],
       "un registro vuoto non dimostra la conformità: dimostra che non è stato compilato");
    ok(/non dimostra niente/.test(vuoto.testo), "e il testo lo dice: «" + vuoto.testo + "»");
  });

  test("Scudo · il riepilogo degli appalti conta i buchi a parte, e la demo li mostra tutti", () => {
    const D = scudo.DEMO;
    const r = scudo.riepilogoAppalti(D.appalti, D.cantieri, D.appaltatori, D.documenti, OGGI);
    eq([r.quanti, r.aPosto, r.daSistemare, r.nonVerificati, r.noto], [4, 1, 2, 1, false],
       "quattro appalti attivi, e i non verificati non finiscono né fra i buoni né fra i cattivi");
    eq([...new Set(r.righe.map((x) => x.esito))].sort(), ["a-posto", "da-sistemare", "non-verificato"],
       "la dimostrazione contiene tutti e tre gli esiti: quello che il prodotto sa dire, si vede");
    eq(r.righe.find((x) => x.appalto.id === "pa2").esito, "non-verificato",
       "⛔ l'appalto con le atmosfere esplosive ha il documento perfetto e l'impresa mai verificata: "
       + "è la riga per cui questo modulo esiste");
    eq(scudo.riepilogoAppalti([{ ...D.appalti[0], stato: "chiuso" }], D.cantieri, D.appaltatori, D.documenti, OGGI).quanti,
       0, "un appalto chiuso non pesa più");
  });

  test("Scudo · le imprese da verificare, e i due indici per appaltatore e per cantiere", () => {
    const D = scudo.DEMO;
    eq(scudo.appaltatoriDaVerificare(D.appaltatori, D.documenti, OGGI).map((r) => r.esito).sort(),
       ["non-verificato", "scaduto"], "due imprese su tre hanno qualcosa da sistemare, e per ragioni diverse");
    eq(scudo.appaltatoriDaVerificare([IMPRESA], QUALIFICATA, OGGI).length, 0, "chi è a posto non compare");
    eq(scudo.appaltatoriDaVerificare([{ ...IMPRESA, attivo: false }], [], OGGI).length, 0,
       "e un'impresa non più attiva non si va a cercare");
    eq(scudo.appaltiDiCantiere(D.appalti, "k1").map((a) => a.id), ["pa1", "pa2", "pa4"], "gli appalti della cava");
    eq(scudo.appaltiDiAppaltatore(D.appalti, "ap1").map((a) => a.id), ["pa1", "pa4"], "e quelli di un'impresa");
    eq([scudo.appaltiDiCantiere(D.appalti, null).length, scudo.appaltiDiAppaltatore(D.appalti, "").length], [0, 0],
       "senza un id non si restituisce «tutto»: si restituisce niente");
  });

  test("Scudo · gli stati del coordinamento sono tutti raggiungibili (regola 18)", () => {
    const B = { uominiGiorno: 10, dataInizio: "2026-03-01", coordRedattore: "R", coordData: "2026-02-20" };
    const visti = new Set([
      scudo.statoCoordinamento({ dataInizio: "2026-03-01" }, FUORI, OGGI).stato,
      scudo.statoCoordinamento({ uominiGiorno: 2, rischiValutati: true }, FUORI, OGGI).stato,
      scudo.statoCoordinamento({ uominiGiorno: 10 }, FUORI, OGGI).stato,
      scudo.statoCoordinamento({ ...B, coordData: null }, FUORI, OGGI).stato,
      scudo.statoCoordinamento({ ...B, coordRedattore: "" }, FUORI, OGGI).stato,
      scudo.statoCoordinamento({ ...B, coordData: "2026-04-10" }, FUORI, OGGI).stato,
      scudo.statoCoordinamento(B, CAVA, OGGI).stato,
      scudo.statoCoordinamento(B, FUORI, OGGI).stato,
    ]);
    eq([...visti].sort(), [...scudo.STATI_COORDINAMENTO].sort(),
       "tutti e otto escono da questi casi: la mappa dei badge della pagina deve coprirli tutti");
  });
  test("Scudo · gli elenchi che la pagina offre e quelli che il modulo capisce sono gli stessi", () => {
    /* Una tendina che offre una scelta che la funzione non sa leggere è la
       forma silenziosa del difetto: l'utente sceglie «mera fornitura», il
       modulo non riconosce la chiave e risponde come se non l'avesse detto. */
    eq(scudo.NATURE_APPALTO.map((n) => n.chiave), ["", "intellettuale", "fornitura"],
       "le tre nature che la pagina propone");
    for (const n of scudo.NATURE_APPALTO.filter((x) => x.chiave))
      eq(scudo.duvriDovuto({ natura: n.chiave, rischiValutati: true }, FUORI).serve, false,
         "«" + n.chiave + "» è una chiave che duvriDovuto riconosce come esclusione");
    eq(scudo.duvriDovuto({ natura: "inventata", rischiValutati: true, uominiGiorno: 9 }, FUORI).serve, true,
       "e una natura che non esiste non esclude niente");

    eq(scudo.TIPI_DOC_APPALTATORE.filter((t) => t.obbligatorio).map((t) => t.chiave), ["cciaa", "autocert"],
       "gli obbligatori sono i due e soli due che l'art. 26 c.1 lett. a) elenca");
    ok(scudo.TIPI_DOC_APPALTATORE.every((t) => t.fonte && t.nome),
       "e ogni riga porta scritta la sua provenienza, così «obbligatorio» non si gonfia");
    eq(scudo.tipoDocAppaltatore("boh"), null, "una chiave sconosciuta non inventa un tipo");

    eq(scudo.RISCHI_PARTICOLARI.length, 5, "i cinque rischi che il c.3-bis mette al riparo dalle esclusioni");
    for (const r of scudo.RISCHI_PARTICOLARI)
      eq(scudo.duvriDovuto({ uominiGiorno: 1, rischiValutati: true, rischiParticolari: [r.chiave] }, FUORI).serve,
         true, "«" + r.chiave + "» da solo basta a rendere dovuto il documento");

    eq(scudo.documentoCoordinamento({ tipo: "cava" }).sigla, "DSS coordinato", "in cava");
    eq(scudo.documentoCoordinamento({ tipo: "cantiere" }).sigla, "DUVRI", "fuori");
    eq(scudo.documentoCoordinamento(null).sigla, "DUVRI",
       "e senza cantiere si sceglie la regola generale, non quella speciale: non si applica alla cieca "
       + "una norma di settore a un luogo che non si conosce");

    const D = scudo.DEMO;
    eq(scudo.docDiAppaltatore(D.documenti, "ap1").map((d) => d.tipoQualifica), ["cciaa", "autocert", "durc"],
       "i documenti di qualifica stanno nel registro documenti di Scudo, non in un secondo archivio");
    eq([scudo.docDiAppaltatore(D.documenti, "ap3").length, scudo.docDiAppaltatore(D.documenti, null).length], [0, 0],
       "l'impresa non verificata non ne ha nessuno, e senza id non si restituisce tutto");
  });
}

/* ════════════════════════════════════════════════════════════════════════
   CONTI — PREVENTIVO E CONFERMA D'ORDINE (N9)
   ────────────────────────────────────────────────────────────────────────
   Prima di oggi il ciclo di Conti partiva dalla PESATA. Queste prove
   difendono le tre cose che il pezzo nuovo esiste per dire:
   · un preventivo scaduto o rifiutato NON è venduto;
   · quanto è stato consegnato a volte NON è un numero, e allora non è «0%»;
   · il prezzo e l'IVA si calcolano UNA volta sola (imponibileRiga,
     totaliDaRighe), non due, se no il preventivo e la fattura non tornano.
   ════════════════════════════════════════════════════════════════════════ */
{
  const PROD_T = { id: "p1", nome: "Stabilizzato 0/30", unitaPrezzo: "t", prezzo: 8.5, densita: 1.9, iva: 22 };
  const PROD_M = { id: "p3", nome: "Sabbia lavata 0/4", unitaPrezzo: "m3", prezzo: 22, densita: 1.6, iva: 22 };
  const PROD_ND = { id: "p5", nome: "Misto di cava", unitaPrezzo: "t", prezzo: 6.5, densita: null, iva: 22 };
  const CL5 = { id: "c1", sconto: 5 };
  const OGGI = new Date("2026-08-01T12:00:00");
  const ordine = (id, stato, righe, extra) =>
    ({ id, clienteId: "c1", data: "2026-06-01", validoAl: "2026-08-31", stato, righe, ...extra });
  const ddt = (id, o, extra) => ({ id, numero: id, ordineId: o, clienteId: "c1",
    prodottoId: "p1", data: "2026-07-01", unitaVendita: "t", quantita: 100, netto: 100, ...extra });

  test("Conti · preventivo: la riga fotografa listino e sconto, e l'imponibile passa da imponibileRiga", () => {
    const r = conti.rigaPreventivo(PROD_T, 300, CL5);
    eq(r.imponibile, conti.imponibileRiga(300, 8.5, 5),
       "il preventivo NON rifà il conto dell'imponibile: usa la funzione della pesata e della fattura");
    contiene(r, { prodottoId: "p1", quantita: 300, unita: "t", prezzoUnitario: 8.5, scontoPct: 5, aliquota: 22 },
       "prezzo di listino e sconto del cliente viaggiano separati, come su un DDT italiano");
  });

  test("Conti · preventivo: la quantità vuota resta null, non zero", () => {
    /* `+null` fa 0 e `Number.isFinite(0)` risponde true: la trappola che questo
       ecosistema ha già pagato tre volte. Qui produrrebbe un'offerta di zero
       tonnellate, che sembra un documento valido. */
    for (const v of [null, undefined, "", "   ", "abc"])
      eq(conti.rigaPreventivo(PROD_T, v, CL5).quantita, null,
         "quantità «" + String(v) + "» non è un numero: la riga non ne inventa uno");
    eq(conti.rigaPreventivo(PROD_T, "", CL5).imponibile, null,
       "e senza quantità non c'è un imponibile: zero euro sarebbe un prezzo dichiarato");
    eq(conti.rigaPreventivo(PROD_T, 0, CL5).quantita, 0,
       "ma uno ZERO scritto davvero resta zero: è una quantità dichiarata, non un'assenza");
  });

  test("Conti · preventivo: ordinare in un'unità diversa dal listino converte col prezzo, non a occhio", () => {
    eq(conti.rigaPreventivo(PROD_T, 100, CL5, "m3").prezzoUnitario, conti.prezzoPerMetroCubo(PROD_T),
       "€/t → €/m³ passa dalla stessa formula del listino, non da una seconda");
    eq(conti.rigaPreventivo(PROD_M, 100, CL5, "t").prezzoUnitario, conti.prezzoPerTonnellata(PROD_M),
       "e nell'altro verso lo stesso");
    eq(conti.rigaPreventivo(PROD_ND, 100, CL5, "m3").prezzoUnitario, null,
       "senza densità il prezzo convertito NON esiste: meglio nessun numero che un numero falso");
    eq(conti.rigaPreventivo(PROD_ND, 100, CL5, "m3").imponibile, null,
       "e senza prezzo non c'è imponibile");
  });

  test("Conti · preventivo: i totali passano da totaliDaRighe, con il riepilogo per aliquota", () => {
    const o = { righe: [conti.rigaPreventivo(PROD_T, 300, CL5), conti.rigaPreventivo(PROD_M, 50, CL5)] };
    const t = conti.totaliPreventivo(o);
    const atteso = conti.totaliDaRighe(o.righe);
    eq([t.imponibile, t.ivaImporto, t.totale], [atteso.imponibile, atteso.ivaImporto, atteso.totale],
       "preventivo e fattura devono tornare al centesimo: è la prima cosa che il cliente controlla");
    eq(t.perAliquota.length, 1, "un'aliquota sola in questo caso, e il riepilogo la porta");
  });

  test("Conti · preventivo: la riga senza importo non entra nel totale e si CONTA a parte", () => {
    /* Stessa regola delle gare senza base d'asta: un totale che esclude
       qualcosa senza dirlo è un totale che inganna chi lo legge. */
    const t = conti.totaliPreventivo({ righe: [conti.rigaPreventivo(PROD_T, 300, CL5), conti.rigaPreventivo(PROD_T, "", CL5)] });
    eq(t.imponibile, conti.imponibileRiga(300, 8.5, 5), "il totale è solo quello che si può sommare");
    eq([t.righe, t.senzaImporto], [2, 1], "e dichiara che una delle due righe è rimasta fuori");
  });

  /* ── GLI STATI ─────────────────────────────────────────────────────── */
  test("Conti · preventivo: «scaduto» lo dice il calendario, non un campo salvato", () => {
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: "2026-08-10" }, OGGI).stato, "inviato",
       "inviato e ancora nei termini");
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: "2026-07-20" }, OGGI).stato, "scaduto",
       "nessuno l'ha toccato e non è più valido: lo stato salvato dice ancora «inviato»");
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: "2026-08-01" }, OGGI).stato, "inviato",
       "l'ultimo giorno di validità vale ancora — chi firma oggi ha firmato in tempo");
  });

  test("Conti · preventivo: l'accettazione ferma l'orologio della validità", () => {
    /* Un ordine confermato a giugno non «scade» a luglio perché l'offerta
       durava trenta giorni: quello è un impegno preso, e va consegnato.
       Senza questa regola un ordine vivo sarebbe uscito dal portafoglio da solo. */
    eq(conti.statoPreventivo({ stato: "accettato", validoAl: "2026-01-01" }, OGGI).stato, "accettato",
       "accettato resta accettato anche mille giorni dopo la validità dell'offerta");
    eq(conti.ordineConfermato({ stato: "accettato", validoAl: "2026-01-01" }, OGGI), true,
       "e resta un ordine vero");
  });

  test("Conti · preventivo: senza data di validità NON è «valido» — è uno stato suo", () => {
    /* Il principio del fondatore sulla data che manca: un'offerta senza
       scadenza è un prezzo bloccato per sempre, e gli inerti si muovono col
       gasolio. È lo stesso disegno di `statoScadenzaFattura`. */
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: null }, OGGI).stato, "senza-validita", "null");
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: "" }, OGGI).stato, "senza-validita", "stringa vuota");
    eq(conti.statoPreventivo({ stato: "inviato", validoAl: "2026-02-30" }, OGGI).stato, "senza-validita",
       "e una data che non esiste non è una data");
    eq(conti.statoPreventivo({ stato: "bozza", validoAl: null }, OGGI).stato, "bozza",
       "una BOZZA invece resta bozza: non è stata mandata a nessuno, non c'è promessa da datare");
  });

  test("Conti · ordine: solo l'accettato è venduto — scaduto, rifiutato e annullato no", () => {
    const casi = [["accettato", true], ["inviato", false], ["bozza", false],
                  ["rifiutato", false], ["annullato", false]];
    for (const [st, atteso] of casi)
      eq(conti.ordineConfermato({ stato: st, validoAl: "2026-08-31" }, OGGI), atteso,
         "«" + st + "» è un ordine? " + atteso);
    eq(conti.ordineConfermato({ stato: "inviato", validoAl: "2026-01-01" }, OGGI), false,
       "e un preventivo scaduto non diventa un ordine per il fatto di essere invecchiato");
  });

  test("Conti · ordine: ogni stato che statoPreventivo sa dire ha la sua voce in STATI_PREVENTIVO o è calcolato", () => {
    /* Regola 18 applicata a mano: una mappa che non copre uno stato uccide la
       pagina al disegno, senza nessun errore di sintassi da leggere. */
    const salvati = conti.STATI_PREVENTIVO.map((s) => s.id);
    eq(salvati, ["bozza", "inviato", "accettato", "rifiutato", "annullato"], "i cinque stati salvabili");
    for (const id of salvati)
      ok(conti.statoPreventivoLabel(id).id === id, "«" + id + "» ha la sua etichetta");
    eq(conti.statoPreventivoLabel("inventato").id, "bozza",
       "e una chiave sconosciuta ripiega senza far cadere la pagina");
    const calcolati = new Set();
    for (const st of salvati) for (const v of ["2026-08-31", "2026-01-01", null])
      calcolati.add(conti.statoPreventivo({ stato: st, validoAl: v }, OGGI).stato);
    eq([...calcolati].sort(), ["accettato", "annullato", "bozza", "inviato", "rifiutato", "scaduto", "senza-validita"],
       "sette stati in uscita: i cinque salvati più i due che li calcola il calendario");
  });

  /* ── L'AVANZAMENTO, E IL PRINCIPIO DEL FONDATORE ───────────────────── */
  test("Conti · ordine: quanto è consegnato viene dai DDT agganciati, e solo da quelli", () => {
    const o = ordine("o1", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const a = conti.avanzamentoOrdine(o, [ddt("a", "o1", { quantita: 100, netto: 100 }),
                                          ddt("b", "o1", { quantita: 50, netto: 50 }),
                                          ddt("c", "altro", { quantita: 900, netto: 900 })]);
    eq([a.percentuale, a.misurabile], [50, true], "150 su 300 è il 50%, e il DDT di un altro ordine non entra");
    eq([a.prodotti[0].consegnato, a.prodotti[0].residuo], [150, 150], "restano 150 t da consegnare");
    eq(a.prodotti[0].ddt, ["a", "b"], "e la riga porta i numeri dei DDT che l'hanno consumata");
  });

  test("Conti · ordine: ⛔ un ordine di cui non si sa quanto è consegnato NON è «0% consegnato»", () => {
    /* Il principio del fondatore su una barra di avanzamento, che è il posto
       dove uno zero mente meglio di tutti: «0%» racconta «non ancora
       cominciato», che è una cosa che si sa. */
    const chiamata = ordine("o5", "accettato", [conti.rigaPreventivo(PROD_T, "", CL5)]);
    const a = conti.avanzamentoOrdine(chiamata, []);
    eq(a.percentuale, null, "fornitura a chiamata: non esiste una frazione da calcolare");
    eq(a.misurabile, false, "e la bandiera lo dichiara");
    ok(/chiamata/.test(a.perche), "con il perché scritto in italiano: «" + a.perche + "»");

    const mc = ordine("o6", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const b = conti.avanzamentoOrdine(mc, [ddt("x", "o6", { unitaVendita: "m3", quantita: 20, densita: null, netto: null })]);
    eq([b.percentuale, b.misurabile], [null, false],
       "DDT a metro cubo senza densità su una riga a tonnellate: il consegnato non si sa");

    const senzaNetto = conti.avanzamentoOrdine(mc, [ddt("y", "o6", { quantita: null, netto: null })]);
    eq([senzaNetto.percentuale, senzaNetto.misurabile], [null, false],
       "e un DDT senza quantità né netto non è una consegna di ZERO tonnellate");
  });

  test("Conti · ordine: e uno ZERO vero resta zero — le due cose non si confondono", () => {
    /* L'altra metà del principio, che è quella che si dimentica: se l'ordine ha
       una quantità e nessun camion è partito, lo zero è un FATTO. La stessa
       asimmetria dichiarata in canonePeriodo fra venduto e scavato. */
    const o = ordine("o7", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const a = conti.avanzamentoOrdine(o, []);
    eq([a.percentuale, a.misurabile, a.daAgganciare], [0, true, 0],
       "nessun DDT di quel cliente: nessuno ha consegnato, ed è misurato");
  });

  test("Conti · ordine: lo zero sospetto si distingue dallo zero certo con un FATTO, non con un'inferenza", () => {
    const o = ordine("o8", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const sciolti = [ddt("s1", null, { data: "2026-06-20" }), ddt("s2", null, { data: "2026-06-22" })];
    const a = conti.avanzamentoOrdine(o, sciolti);
    eq([a.percentuale, a.daAgganciare], [0, 2],
       "zero agganciati, ma due DDT di quel cliente e di quel prodotto senza ordine: probabilmente una svista");
    eq(conti.avanzamentoOrdine(o, [ddt("s3", null, { clienteId: "c9" })]).daAgganciare, 0,
       "il DDT di un ALTRO cliente non è un candidato");
    eq(conti.avanzamentoOrdine(o, [ddt("s4", null, { prodottoId: "p9", prodotto: "Altro" })]).daAgganciare, 0,
       "né quello di un altro prodotto");
    eq(conti.avanzamentoOrdine(o, [ddt("s5", null, { data: "2026-05-01" })]).daAgganciare, 0,
       "né uno consegnato PRIMA che il preventivo esistesse");
    eq(conti.ddtDaAgganciare(o, sciolti).map((p) => p.id), ["s1", "s2"],
       "e la pagina se li fa dare per collegarli, in ordine di data");
  });

  test("Conti · ordine: due righe dello stesso prodotto sono UN prodotto, non due barre", () => {
    /* In cava è la norma: 300 t del primo lotto a un prezzo, 200 t del secondo
       a un altro. Un DDT non dice a quale riga appartiene: attribuendolo alla
       prima si otteneva il 133% su una e lo 0% sull'altra. Trovato in
       prototipo, prima di scrivere la funzione. */
    const o = ordine("o9", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5),
                                         conti.rigaPreventivo({ ...PROD_T, prezzo: 8 }, 200, CL5)]);
    const a = conti.avanzamentoOrdine(o, [ddt("z", "o9", { quantita: 400, netto: 400 })]);
    eq(a.prodotti.length, 1, "un prodotto solo");
    eq([a.prodotti[0].righe, a.prodotti[0].ordinato], [2, 500], "che porta due righe e 500 t ordinate");
    eq(a.percentuale, 80, "400 su 500 = 80%");
  });

  test("Conti · ordine: il consegnato per prodotto porta i DDT che l'hanno formato", () => {
    /* `consegnatoOrdine` si prova anche da sola e non solo attraverso
       `avanzamentoOrdine`: è lei che la pagina chiama per disegnare la riga
       prodotto per prodotto, con il residuo accanto. */
    const o = ordine("o14", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5),
                                          conti.rigaPreventivo(PROD_M, 40, CL5)]);
    const c = conti.consegnatoOrdine(o, [ddt("t1", "o14", { quantita: 120, netto: 120 }),
      ddt("t2", "o14", { prodottoId: "p3", prodotto: "Sabbia lavata 0/4", unitaVendita: "m3", quantita: 10, densita: 1.6, netto: null })]);
    eq(c.ddtAgganciati, 2, "due DDT agganciati");
    eq(c.prodotti.map((g) => [g.descrizione, g.ordinato, g.consegnato, g.residuo]),
       [["Stabilizzato 0/30", 300, 120, 180], ["Sabbia lavata 0/4", 40, 10, 30]],
       "ogni prodotto col suo ordinato, consegnato e residuo, nell'unità in cui è stato ordinato");
    eq(c.prodotti.map((g) => g.ddt), [["t1"], ["t2"]], "e i numeri dei DDT accanto, per andarli a cercare");
    eq(c.fuoriOrdine, [], "niente fuori ordine qui");
    eq(conti.consegnatoOrdine(null, null).prodotti, [], "e senza ordine non si inventa niente");
  });

  test("Conti · ordine: un DDT di un prodotto non ordinato non consuma l'ordine", () => {
    const o = ordine("o10", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const a = conti.avanzamentoOrdine(o, [ddt("f", "o10", { prodottoId: "p3", prodotto: "Sabbia lavata 0/4" })]);
    eq(a.fuoriOrdine.map((p) => p.id), ["f"], "si tiene a parte e si dice, invece di sparire");
    eq(a.percentuale, 0, "e non sposta l'avanzamento di un punto");
  });

  test("Conti · ordine: consegnato più dell'ordinato si dice, non si tronca a 100", () => {
    /* L'ultimo camion carica un po' di più: succede, e un residuo bloccato a
       zero lo nasconderebbe proprio a chi deve fatturarlo. */
    const o = ordine("o11", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const a = conti.avanzamentoOrdine(o, [ddt("e", "o11", { quantita: 315, netto: 315 })]);
    eq([a.percentuale, a.prodotti[0].residuo], [105, -15], "105% e quindici tonnellate in più");
    ok(/più dell'ordinato/.test(conti.descriviAvanzamento(a)), "e la frase lo dice: «" + conti.descriviAvanzamento(a) + "»");
  });

  test("Conti · ordine: la conversione fra unità passa da convertiQuantita, con la densità del DDT", () => {
    const o = ordine("o12", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    const a = conti.avanzamentoOrdine(o, [ddt("m", "o12", { unitaVendita: "m3", quantita: 100, densita: 1.9, netto: null })]);
    eq(a.prodotti[0].consegnato, conti.convertiQuantita(100, "m3", "t", 1.9),
       "100 m³ a densità 1,9 fanno 190 t, e il conto è quello del listino");
  });

  test("Conti · ordine: la frase dell'avanzamento è scritta nel modulo, una volta sola", () => {
    /* Regola 7: «come si racconta una non-misurabilità» è una decisione sola.
       Scritta nella pagina, il giorno che serve al report se ne scriverebbe
       una seconda, diversa. */
    const o = ordine("o13", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]);
    ok(/non si può misurare/.test(conti.descriviAvanzamento({ misurabile: false, perche: "prova" })),
       "non misurabile: lo dice");
    eq(conti.descriviAvanzamento(conti.avanzamentoOrdine(o, [ddt("q", "o13", { quantita: 300, netto: 300 })])),
       "Ordine consegnato per intero.", "al 100%");
    ok(/ce n'è 1\b/.test(conti.descriviAvanzamento({ misurabile: true, percentuale: 0, daAgganciare: 1 })),
       "e al singolare si scrive «ce n'è 1», non «ce ne sono 1»");
    ok(/ce ne sono 3\b/.test(conti.descriviAvanzamento({ misurabile: true, percentuale: 0, daAgganciare: 3 })),
       "al plurale il plurale");
  });

  /* ── IL PORTAFOGLIO ────────────────────────────────────────────────── */
  test("Conti · portafoglio: nel venduto entra solo il confermato", () => {
    const righe = [conti.rigaPreventivo(PROD_T, 300, CL5)];
    const val = conti.totaliPreventivo({ righe }).imponibile;
    const lista = [ordine("a1", "accettato", righe), ordine("a2", "accettato", righe),
                   ordine("r1", "rifiutato", righe), ordine("b1", "bozza", righe),
                   ordine("s1", "inviato", righe, { validoAl: "2026-01-01" })];
    const p = conti.portafoglioOrdini(lista, [], OGGI);
    eq([p.quanti, p.valore], [2, conti.round2(val * 2)],
       "due ordini: il rifiutato, la bozza e lo scaduto non sono materiale che uscirà dal piazzale");
  });

  test("Conti · portafoglio: dichiara quanti ordini non sa misurare e quanti valgono in parte", () => {
    const lista = [ordine("a1", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)]),
                   ordine("a2", "accettato", [conti.rigaPreventivo(PROD_T, "", CL5)]),
                   ordine("a3", "accettato", [conti.rigaPreventivo(PROD_T, 300, CL5)])];
    const p = conti.portafoglioOrdini(lista, [{ id: "k", numero: "k", ordineId: "a3", clienteId: "c1",
      prodottoId: "p1", data: "2026-07-01", unitaVendita: "t", quantita: 300, netto: 300 }], OGGI);
    contiene(p, { quanti: 3, daConsegnare: 1, completati: 1, nonMisurabili: 1, senzaImporto: 1 },
       "tre ordini: uno a metà, uno finito, uno che non si sa — e il valore è parziale, e lo dice");
  });

  test("Conti · portafoglio: senza ordini le risposte sono zeri, non numeri inventati", () => {
    contiene(conti.portafoglioOrdini([], [], OGGI), { quanti: 0, valore: 0, daConsegnare: 0, nonMisurabili: 0, senzaImporto: 0 },
       "nessun ordine è un fatto: zero ordini valgono zero euro");
    contiene(conti.portafoglioOrdini(null, null, OGGI), { quanti: 0, valore: 0 }, "e niente cade su null");
  });

  test("Conti · preventivi: quelli che chiedono una mossa, dal più urgente", () => {
    const righe = [conti.rigaPreventivo(PROD_T, 300, CL5)];
    const lista = [ordine("v1", "inviato", righe, { numero: "V1", validoAl: "2026-08-30" }),
                   ordine("v2", "inviato", righe, { numero: "V2", validoAl: "2026-08-04" }),
                   ordine("v3", "inviato", righe, { numero: "V3", validoAl: "2026-07-01" }),
                   ordine("v4", "inviato", righe, { numero: "V4", validoAl: null }),
                   ordine("v5", "accettato", righe, { numero: "V5", validoAl: "2026-07-01" })];
    const d = conti.preventiviDaSeguire(lista, OGGI);
    eq(d.map((x) => x.ordine.numero), ["V3", "V4", "V2"],
       "prima lo scaduto (il prezzo è già morto), poi quello senza validità, poi quello che scade fra tre giorni");
    eq(d.map((x) => x.stato), ["scaduto", "senza-validita", "inviato"], "con lo stato accanto");
    ok(!d.some((x) => x.ordine.numero === "V1"), "quello che scade fra un mese non chiede niente oggi");
    ok(!d.some((x) => x.ordine.numero === "V5"), "e un ordine già accettato non è un'offerta da richiamare");
  });

  /* ── I DATI D'ESEMPIO ──────────────────────────────────────────────── */
  test("Conti · ordini d'esempio: gli importi salvati tornano col calcolo, al centesimo", () => {
    /* Un dato d'esempio scritto a mano che non torna col conto dell'app è una
       bugia che si vede solo in dimostrazione — cioè proprio dove la guarda
       chi non conosce il prodotto. */
    let righe = 0;
    for (const o of conti.DEMO.ordini) for (const r of o.righe) {
      righe++;
      if (r.quantita == null) { eq(r.imponibile, null, o.numero + ": senza quantità niente imponibile"); continue; }
      eq(r.imponibile, conti.imponibileRiga(r.quantita, r.prezzoUnitario, r.scontoPct),
         o.numero + " · " + r.descrizione + ": l'imponibile scritto è quello che calcola l'app");
    }
    eq(righe, 9, "righe d'esempio controllate");
  });

  test("Conti · ordini d'esempio: la dimostrazione contiene i casi che il prodotto esiste per raccontare", () => {
    /* Stessa ragione per cui la fattura senza scadenza è entrata in DEMO il
       01/08: un campione di soli casi sani non mostra niente. */
    const D = conti.DEMO, stati = D.ordini.map((o) => conti.statoPreventivo(o, OGGI).stato);
    for (const atteso of ["accettato", "inviato", "scaduto", "rifiutato", "senza-validita"])
      ok(stati.includes(atteso), "in dimostrazione c'è almeno un preventivo «" + atteso + "»");
    const avanz = D.ordini.map((o) => conti.avanzamentoOrdine(o, D.pesate));
    ok(avanz.some((a) => !a.misurabile), "e almeno un ordine di cui il consegnato NON è misurabile");
    ok(avanz.some((a) => a.misurabile && a.percentuale > 0 && a.percentuale < 100), "uno a metà consegna");
    ok(avanz.some((a) => a.percentuale === 0 && a.daAgganciare > 0), "e uno a zero con dei DDT da collegare");
  });

  test("Conti · ordini d'esempio: i DDT agganciati puntano a un ordine che esiste", () => {
    const ids = new Set(conti.DEMO.ordini.map((o) => o.id));
    const agg = conti.DEMO.pesate.filter((p) => p.ordineId);
    ok(agg.length > 0, "almeno un DDT d'esempio è agganciato, se no la funzione non si vede mai");
    for (const p of agg) ok(ids.has(p.ordineId), "il DDT " + p.numero + " punta all'ordine " + p.ordineId);
    for (const p of agg) {
      const o = conti.DEMO.ordini.find((x) => x.id === p.ordineId);
      eq(String(p.clienteId || ""), String(o.clienteId || ""),
         "e il DDT " + p.numero + " è dello stesso cliente dell'ordine: un ordine non si consegna a un altro");
    }
  });

  test("Conti · ordini: la numerazione dei preventivi è una serie sua, e non tocca quella delle fatture", () => {
    const numeri = conti.DEMO.ordini.map((o) => o.numero);
    eq(conti.prossimoNumero(numeri, 2026, 3, "PREV/"), "PREV/2026/009", "il prossimo preventivo");
    eq(conti.prossimoNumero(conti.DEMO.ordini.map((o) => o.numeroOrdine).filter(Boolean), 2026, 3, "ORD/"),
       "ORD/2026/005", "e il prossimo ordine, che è un registro a parte");
    eq(conti.prossimoNumero([...numeri, ...conti.DEMO.fatture.map((f) => f.numero)], 2026, 3, ""),
       conti.prossimoNumero(conti.DEMO.fatture.map((f) => f.numero), 2026, 3, ""),
       "e i preventivi non fanno saltare il numero della prossima fattura");
  });

  // ══════════════════════════════════════════════════════════════════
  // CONTI · PREZZI A SCAGLIONI DI QUANTITÀ (N9)
  // ══════════════════════════════════════════════════════════════════
  {
    const PZ = { id: "sx1", nome: "Pietrisco 8/12", unitaPrezzo: "t", prezzo: 12, densita: 1.5, iva: 22,
      scaglioni: [{ da: 500, prezzo: 10.5 }, { da: 100, prezzo: 11.2 }] };  // apposta fuori ordine
    const SC = { id: "sx2", nome: "Stabilizzato", unitaPrezzo: "t", prezzo: 10, densita: 1.9, iva: 22,
      scaglioni: [{ da: 200, sconto: 8 }] };
    const ND = { id: "sx3", nome: "Misto", unitaPrezzo: "t", prezzo: 6.5, densita: null, iva: 22,
      scaglioni: [{ da: 100, prezzo: 6 }] };
    const NUDO = { id: "sx4", nome: "Sabbia", unitaPrezzo: "m3", prezzo: 22, densita: 1.6, iva: 22 };
    const C5 = { sconto: 5 };

    test("Conti · scaglioni: la scala si ordina da sé e la banda base è il listino, scritta", () => {
      const v = conti.validaScaglioni(PZ);
      ok(v.ok, "la scala è valida");
      eq(v.tipo, "prezzo", "tipo dedotto dalle righe");
      eq(v.quanti, 2, "due scaglioni scritti");
      eq(v.scala.map((s) => s.da), [0, 100, 500], "ordinati, anche se scritti al contrario");
      eq(v.scala.map((s) => s.a), [100, 500, null], "e ogni banda sa dove finisce (l'ultima è aperta)");
      /* ⛔ la banda base NON è un'inferenza nascosta: è una riga della scala,
         marcata `implicita`, così la pagina la disegna come le altre. */
      eq(v.scala[0].implicita, true, "la banda base è marcata implicita");
      eq(v.scala[0].prezzo, 12, "e vale il prezzo di listino");
      eq(v.scala[1].implicita, false, "gli scaglioni scritti no");
      /* ⛔ i buchi e le sovrapposizioni sono IMPOSSIBILI per costruzione con la
         forma «da»: ogni banda comincia dove finisce la precedente. */
      for (let i = 1; i < v.scala.length; i++)
        eq(v.scala[i].da, v.scala[i - 1].a, "nessun buco fra la banda " + (i - 1) + " e la " + i);
    });

    test("Conti · scaglioni: una scala che non è una scala viene rifiutata, e dice perché", () => {
      const dop = conti.validaScaglioni({ ...PZ, scaglioni: [{ da: 100, prezzo: 11 }, { da: 100, prezzo: 10 }] });
      ok(!dop.ok, "due righe dalla stessa quantità: rifiutata");
      ok(/sovrappongono/.test(dop.problemi[0]), "e il motivo è la sovrapposizione: " + dop.problemi[0]);
      const mix = conti.validaScaglioni({ ...PZ, scaglioni: [{ da: 100, prezzo: 11 }, { da: 500, sconto: 8 }] });
      ok(!mix.ok && /mescola/.test(mix.problemi[0]), "prezzi e sconti nella stessa scala: rifiutata");
      /* stessa regola dell'import del listino: uno zero fa sembrare gratis un
         prodotto che non lo è, e da lì finisce in un DDT e poi in fattura. */
      ok(!conti.validaScaglioni({ ...PZ, scaglioni: [{ da: 100, prezzo: 0 }] }).ok, "prezzo zero rifiutato");
      ok(!conti.validaScaglioni({ ...PZ, scaglioni: [{ da: -5, prezzo: 11 }] }).ok, "soglia negativa rifiutata");
      ok(!conti.validaScaglioni({ ...SC, scaglioni: [{ da: 100, sconto: 140 }] }).ok, "sconto oltre 100 rifiutato");
      const nulla = conti.validaScaglioni(NUDO);
      ok(nulla.ok, "un prodotto senza scaglioni NON è un errore");
      eq(nulla.quanti, 0, "ha zero scaglioni");
      eq(nulla.scala, [], "e nessuna banda: la scala vuota non si inventa una base");
    });

    test("Conti · scaglioni: la soglia appartiene allo scaglione più alto", () => {
      eq(conti.scaglionePer(PZ, 99.999, "t").prezzoScala, 12, "99,999 t: banda base");
      eq(conti.scaglionePer(PZ, 100, "t").prezzoScala, 11.2, "100 t esatte: SECONDA banda, non la prima");
      eq(conti.scaglionePer(PZ, 499.9, "t").prezzoScala, 11.2, "499,9 t: ancora la seconda");
      eq(conti.scaglionePer(PZ, 500, "t").prezzoScala, 10.5, "500 t esatte: terza banda");
      eq(conti.scaglionePer(PZ, 1e6, "t").indice, 2, "e sopra l'ultima soglia resta l'ultima banda");
      eq(conti.scaglionePer(PZ, 0, "t").prezzoScala, 12, "zero cade nella banda base");
    });

    test("Conti · scaglioni: la quantità si converte nell'unità della scala", () => {
      const a = conti.scaglionePer(PZ, 70, "m3");   // 70 m³ × 1,5 = 105 t
      ok(a.calcolabile, "70 m³ di un prodotto listinato a tonnellata: calcolabile");
      eq(a.quantitaListino, 105, "convertiti in 105 t");
      eq(a.prezzoScala, 11.2, "quindi seconda banda, non la base");
      /* ⛔ IL PRINCIPIO DEL FONDATORE. Senza densità NON si sceglie «la più
         bassa per prudenza» e nemmeno il listino pieno: non si sa, e si dice. */
      const b = conti.scaglionePer(ND, 70, "m3");
      eq(b.calcolabile, false, "senza densità la banda NON si sceglie");
      eq(b.motivo, "densita-mancante", "e il motivo è leggibile da chi chiama");
      eq(b.prezzoScala, null, "nessun prezzo di ripiego");
      eq(b.banda, null, "e nessuna banda scelta di nascosto");
      ok(/densità/.test(b.perche), "il perché lo dice a parole: " + b.perche);
      /* la stessa cosa senza quantità: la fornitura a chiamata */
      const c = conti.scaglionePer(PZ, null, "t");
      eq(c.calcolabile, false, "quantità assente: non calcolabile");
      eq(c.motivo, "quantita-assente", "e si distingue dal caso della densità");
      eq(conti.scaglionePer(PZ, "", "t").motivo, "quantita-assente", "la stringa vuota si comporta uguale");
      /* ⛔ `+null` fa 0 e `Number.isFinite(0)` risponde true: senza la guardia
         una quantità assente prenderebbe la banda base, cioè il prezzo PIÙ
         CARO spacciato per scelta. */
      ok(conti.scaglionePer(PZ, null, "t").prezzoScala !== 12, "e NON ripiega sulla banda base");
      /* una scala rotta non fa comunque scegliere una banda a caso */
      const d = conti.scaglionePer({ ...PZ, scaglioni: [{ da: 100, prezzo: 11 }, { da: 100, prezzo: 9 }] }, 300, "t");
      eq(d.calcolabile, false, "scala non valida: non calcolabile");
      eq(d.motivo, "scala-non-valida", "e lo dice");
      /* un prodotto senza scala è calcolabile: non c'è niente da scegliere */
      const e = conti.scaglionePer(NUDO, 5000, "m3");
      ok(e.calcolabile, "prodotto senza scaglioni: calcolabile");
      eq(e.motivo, "nessuna-scala", "con il motivo che lo dice");
      eq(e.prezzoScala, null, "e nessuna banda");
    });

    test("Conti · scaglioni: sconto cliente e scaglione si SOMMANO, in un posto solo", () => {
      /* scala a PREZZI: la banda cambia il prezzo, lo sconto cliente resta suo */
      const a = conti.applicaScaglione(PZ, 5000, "t", C5);
      eq(a.prezzoUnitario, 10.5, "il prezzo scende alla banda");
      eq(a.scontoScaglione, 0, "una scala a prezzi non produce percentuali");
      eq(a.scontoPct, 5, "e lo sconto resta quello del cliente");
      eq(conti.imponibileRiga(5000, a.prezzoUnitario, a.scontoPct), 49875, "5000 × 10,50 − 5%");
      /* scala a SCONTI: il prezzo resta il listino e le due percentuali si sommano */
      const b = conti.applicaScaglione(SC, 500, "t", C5);
      eq(b.prezzoUnitario, 10, "il prezzo di listino non si tocca");
      eq(b.scontoScaglione, 8, "la banda dà 8%");
      eq(b.scontoPct, 13, "5% cliente + 8% quantità = 13%, non 12,6% a cascata");
      eq(b.scontoCliente, 5, "e le due metà restano leggibili separatamente");
      /* ⛔ perché NON si piega la percentuale dentro il prezzo: l'errore di
         arrotondamento ai centesimi si moltiplica per la quantità. La misura
         sta nel commento di `applicaScaglione`; qui si prova che il risultato
         è quello dritto, non quello piegato. */
      const dritto = Math.round(2230 * 12.34 * 0.92 * 100) / 100;
      const piegato = Math.round(2230 * (Math.round(12.34 * 0.92 * 100) / 100) * 100) / 100;
      ok(dritto - piegato > 6, "piegare la % nel prezzo perderebbe " + Math.round((dritto - piegato) * 100) / 100 + " € su 2.230 t");
      const c = conti.applicaScaglione(SC, 500, "t", { sconto: 0 });
      eq(c.scontoPct, 8, "senza sconto cliente resta solo quello della quantità");
      /* il tetto: `imponibileRiga` lo impone comunque, ma la somma lo dichiara */
      eq(conti.applicaScaglione({ ...SC, scaglioni: [{ da: 0, sconto: 97 }] }, 10, "t", { sconto: 20 }).scontoPct,
         100, "la somma si ferma a 100");
    });

    test("Conti · scaglioni: nessuna regressione sui prodotti che non ne hanno", () => {
      /* la prova che conta di più: chi non usa gli scaglioni deve vedere
         esattamente i numeri di ieri. */
      for (const p of conti.DEMO.prodotti.filter((x) => !x.scaglioni)) {
        const a = conti.applicaScaglione(p, 5000, p.unitaPrezzo, C5);
        eq(a.prezzoUnitario, conti.round2(p.prezzo), p.nome + ": prezzo di listino intatto");
        eq(a.scontoPct, 5, p.nome + ": solo lo sconto del cliente");
      }
      const senza = { ...PZ, scaglioni: undefined };
      eq(conti.applicaScaglione(senza, 5000, "t", C5).prezzoUnitario, 12, "e togliere la scala riporta al listino");
      /* e la conversione del prezzo fra unità è ancora quella di prima */
      eq(conti.applicaScaglione(PZ, 5000, "m3", C5).prezzoUnitario, conti.round2(10.5 * 1.5),
         "la banda in €/t si converte in €/m³ con la densità, come il listino");
      eq(conti.applicaScaglione(ND, 10, "m3", C5).prezzoUnitario, null,
         "e senza densità il prezzo in un'altra unità resta null, come prima");
    });

    test("Conti · scaglioni: la riga di preventivo li applica e dice quale ha usato", () => {
      const r = conti.rigaPreventivo(PZ, 800, C5, "t");
      eq(r.prezzoUnitario, 10.5, "prezzo della banda");
      eq(r.scontoPct, 5, "sconto del cliente");
      eq(r.imponibile, 7980, "800 × 10,50 − 5%");
      /* ⛔ un prezzo che cambia senza dire perché è un prezzo che il cliente
         contesta: la banda si FOTOGRAFA sulla riga, come il prezzo. */
      eq(r.scaglione.da, 500, "la riga porta la soglia usata");
      eq(r.scaglione.tipo, "prezzo", "e di che forma era la scala");
      eq(r.scaglione.prezzo, 10.5, "e il prezzo di quella banda");
      const base = conti.rigaPreventivo(PZ, 50, C5, "t");
      eq(base.prezzoUnitario, 12, "sotto la prima soglia: listino pieno");
      eq(base.scaglione, null, "e la banda base non si racconta come uno scaglione applicato");
      const s = conti.rigaPreventivo(SC, 500, C5, "t");
      eq(s.scontoPct, 13, "scala a sconti: le due percentuali sommate finiscono in una sola colonna");
      eq(s.scontoCliente, 5, "e la riga tiene le due metà separate, per chi deve rifare il conto");
      eq(s.scontoScaglione, 8, "");
      eq(s.imponibile, conti.imponibileRiga(500, 10, 13), "l'imponibile passa da imponibileRiga, non da un secondo conto");
    });

    test("Conti · scaglioni: quando il prezzo non si sa, la riga non se lo inventa", () => {
      /* fornitura a chiamata su un prodotto a scaglioni: il prezzo unitario
         DIPENDE dalla quantità, e la quantità non c'è. Un prezzo di listino
         scritto lì sarebbe una promessa che non è stata fatta. */
      const a = conti.rigaPreventivo(PZ, "", C5, "t");
      eq(a.quantita, null, "quantità assente");
      eq(a.prezzoUnitario, null, "e prezzo NON determinato");
      eq(a.imponibile, null, "quindi nessun imponibile");
      eq(a.motivoSenzaPrezzo, "quantita-assente", "e chi chiama sa che è un'offerta legittima, non un errore");
      /* ma su un prodotto SENZA scaglioni la fornitura a chiamata ha ancora il
         suo prezzo: è quello che faceva prima, e deve continuare a farlo */
      const b = conti.rigaPreventivo(NUDO, "", C5, "m3");
      eq(b.prezzoUnitario, 22, "prodotto senza scala: il prezzo bloccato resta");
      eq(b.motivoSenzaPrezzo, "", "e non c'è niente da spiegare");
      /* densità mancante: il motivo deve restare quello vecchio, se no la
         pagina manda a scrivere la cosa sbagliata */
      const c = conti.rigaPreventivo({ ...NUDO, densita: null }, 10, C5, "t");
      eq(c.prezzoUnitario, null, "prodotto a m³ senza densità ordinato a tonnellata");
      eq(c.motivoSenzaPrezzo, "densita-mancante", "il motivo è la densità, non «nessuna scala»");
    });

    test("Conti · scaglioni: le etichette e la frase, scritte una volta sola", () => {
      const v = conti.validaScaglioni(PZ);
      eq(v.scala.map((b) => conti.etichettaScaglione(b, v.unita)),
         ["fino a 100 t", "da 100 t", "da 500 t in su"], "come si chiamano le tre bande");
      /* ⚠️ il formattatore si passa da fuori: `toLocaleString("it-IT")` su
         1500 dà «1500» in Node e «1.500» in Chromium, quindi un'etichetta che
         formatta da sé sarebbe una prova verde su una stringa che l'utente non
         vede mai (docs/MIGLIAIA_NODE_CONTRO_CHROMIUM.md). */
      eq(conti.etichettaScaglione({ da: 1500, a: null }, "t", (n) => "«" + n + "»"),
         "da «1500» t in su", "e il formato del numero lo decide chi chiama");
      eq(conti.etichettaScaglione({ da: 0, a: null }, "m3"), "qualunque quantità",
         "una scala di una riga sola che parte da zero non ha soglie da nominare");
      /* la frase LEGGE la bandiera `calcolabile`: una non-misurabilità che non
         legge nessuno non protegge niente (regola 20 di run-stile). */
      ok(/non si può applicare/.test(conti.descriviScaglione(conti.scaglionePer(PZ, null, "t"))),
         "senza quantità la frase lo dice");
      ok(/densità/.test(conti.descriviScaglione(conti.scaglionePer(ND, 10, "m3"))),
         "e senza densità nomina la densità");
      ok(/listino pieno/.test(conti.descriviScaglione(conti.scaglionePer(PZ, 10, "t"))),
         "sotto la prima soglia dice che si paga il listino");
      ok(/non ha scaglioni/.test(conti.descriviScaglione(conti.scaglionePer(NUDO, 10, "m3"))),
         "e un prodotto senza scala lo dice invece di tacere");
      ok(/8/.test(conti.descriviScaglione(conti.scaglionePer(SC, 500, "t"))),
         "la scala a sconti nomina la percentuale");
    });

    test("Conti · scaglioni: la dimostrazione contiene tutt'e tre le forme", () => {
      const P = conti.DEMO.prodotti;
      const conScala = P.filter((p) => conti.validaScaglioni(p).quanti > 0);
      ok(conScala.length >= 2, "almeno due prodotti d'esempio hanno una scala");
      const tipi = new Set(conScala.map((p) => conti.validaScaglioni(p).tipo));
      ok(tipi.has("prezzo") && tipi.has("sconto"), "e ci sono tutt'e due le forme: " + [...tipi].join(", "));
      for (const p of P) ok(conti.validaScaglioni(p).ok, p.nome + ": la scala d'esempio è valida");
      /* ⛔ e c'è il caso che il prodotto esiste per raccontare: una scala su un
         prodotto SENZA densità, ordinato nell'altra unità. */
      const senzaDens = P.find((p) => !p.densita && conti.validaScaglioni(p).quanti > 0);
      ok(!!senzaDens, "in dimostrazione c'è un prodotto a scaglioni senza densità");
      eq(conti.scaglionePer(senzaDens, 300, "m3").motivo, "densita-mancante",
         "e ordinato a metro cubo dice che non lo sa");
      /* l'ordine d'esempio che arriva alla banda alta */
      const o8 = conti.DEMO.ordini.find((o) => o.id === "o8");
      ok(!!o8 && o8.righe[0].scaglione, "e c'è un ordine d'esempio con lo scaglione fotografato");
      const rifatta = conti.rigaPreventivo(P.find((p) => p.id === "p2"), 800, conti.DEMO.clienti[0], "t");
      eq(rifatta.prezzoUnitario, o8.righe[0].prezzoUnitario, "e rifacendola oggi il prezzo torna");
      eq(rifatta.imponibile, o8.righe[0].imponibile, "e l'imponibile pure");
      eq(rifatta.scaglione.da, o8.righe[0].scaglione.da, "e la banda pure");
    });
  }

  // ══════════════════════════════════════════════════════════════════
  // CONTI · IL DDT EREDITA IL PREZZO DELL'ORDINE (A3)
  // ------------------------------------------------------------------
  // Il difetto, misurato sui dati di dimostrazione prima di scrivere una
  // riga: ORD/2026/004 concorda 800 t di Pietrisco a 10,50 €/t col 5% di
  // Edilcave, e ogni bolla rifaceva il conto dal listino del giorno (12,00).
  // Su un camion di 25,6 t: 291,84 € invece di 255,36, cioè 36,48 € in più —
  // il 14,3% — e circa 1.167 € sull'ordine intero. Il cliente firma
  // un'offerta e riceve una fattura che dice un'altra cosa.
  // Queste prove difendono tre cose che si possono rompere una per volta:
  // che il pattuito VINCA, che chi non usa gli ordini NON cambi comportamento,
  // e che quando il pattuito non si sa non si ripieghi su niente.
  // ══════════════════════════════════════════════════════════════════
  {
    const PIE = { id: "a3p", nome: "Pietrisco 8/12", unitaPrezzo: "t", prezzo: 12, densita: 1.5, iva: 22 };
    const CLI5 = { sconto: 5 };
    // l'ordine: 10,50 €/t concordati, 5% di sconto, in tonnellate
    const ORD = { id: "a3o", numero: "PREV/2026/900", numeroOrdine: "ORD/2026/900",
      stato: "accettato", decisoIl: "2026-07-24", clienteId: "c1",
      righe: [{ prodottoId: "a3p", descrizione: "Pietrisco 8/12", quantita: 800, unita: "t",
        densita: 1.5, prezzoUnitario: 10.5, scontoPct: 5, aliquota: 22, imponibile: 7980 }] };
    const DDT = { prodottoId: "a3p", prodotto: "Pietrisco 8/12", unitaVendita: "t", densita: 1.5 };

    test("⛔ A3 · il DDT agganciato usa il PATTUITO, non il listino del giorno", () => {
      const pr = conti.prezzoDaOrdine(ORD, DDT);
      eq(pr.fonte, "ordine", "il prezzo viene dall'ordine");
      eq(pr.calcolabile, true, "e si è potuto determinare");
      eq(pr.prezzoUnitario, 10.5, "10,50 €/t concordati, non i 12,00 di listino");
      eq(pr.scontoPct, 5, "e lo sconto pattuito viaggia col prezzo, come sempre in questo file");
      /* LA MISURA DEL DIFETTO, scritta come asserzione perché non torni: il
         valore giusto e quello che usciva prima devono restare DIVERSI. */
      eq(conti.imponibileRiga(25.6, pr.prezzoUnitario, pr.scontoPct), 255.36, "un camion di 25,6 t");
      eq(conti.imponibileRiga(25.6, 12, 5), 291.84, "quanto avrebbe scritto il listino");
      eq(conti.imponibileRiga(800, pr.prezzoUnitario, pr.scontoPct), 7980, "e l'ordine intero torna con l'offerta firmata");
    });

    test("⛔ A3 · e lo DICE: la provenienza è fotografata sul DDT, non dedotta", () => {
      const pr = conti.prezzoDaOrdine(ORD, DDT);
      eq(pr.ordine.numeroOrdine, "ORD/2026/900", "quale ordine ha deciso il prezzo");
      ok(conti.descriviPrezzoOrdine(pr).includes("ORD/2026/900"),
         "e la frase lo nomina: chi vede 10,50 dove il listino dice 12,00 deve capire perché");
      ok(/non è il listino di oggi/.test(conti.descriviPrezzoOrdine(pr)),
         "e dice a chiare lettere che non è il listino");
    });

    test("⛔ A3 · una pesata NON agganciata continua a usare il listino", () => {
      const pr = conti.prezzoDaOrdine(null, DDT);
      eq(pr.fonte, "listino", "senza ordine il prezzo è quello di sempre");
      eq(pr.calcolabile, true, "e non è una non-misurabilità: è il caso normale");
      eq(pr.motivo, "senza-ordine", "detto per nome, così la pagina non deve indovinarlo");
      eq(conti.prezzoDaOrdine({ righe: [] }, DDT).fonte, "listino", "e nemmeno un ordine senza id cambia niente");
      /* la stessa promessa vista dal lato di `rigaPesata`, che è dove il
         comportamento di chi non usa gli ordini si romperebbe davvero. */
      const senza = conti.rigaPesata(PIE, 39.4, 13.8, CLI5);
      eq(senza.prezzoUnitario, 12, "il listino");
      eq(senza.scontoPct, 5, "e lo sconto del cliente, come dal 03/08");
      eq(senza.valore, 291.84, "e il valore di prima, identico");
      eq(senza.fontePrezzo, "listino", "dichiarato, non lasciato intendere");
    });

    test("⛔ A3 · rigaPesata: il quinto parametro è un SOPRAINSIEME", () => {
      const senza = conti.rigaPesata(PIE, 39.4, 13.8, CLI5);
      const con = conti.rigaPesata(PIE, 39.4, 13.8, CLI5, ORD);
      eq(con.netto, senza.netto, "il netto non c'entra col prezzo e non cambia");
      eq(con.quantita, senza.quantita, "e nemmeno la quantità");
      eq(con.aliquotaIva, senza.aliquotaIva, "e nemmeno l'IVA");
      eq(con.prezzoUnitario, 10.5, "cambia solo il prezzo: quello concordato");
      eq(con.valore, 255.36, "e quindi il valore della consegna");
      eq(con.fontePrezzo, "ordine", "con la provenienza scritta");
      eq(con.ordineNumero, "ORD/2026/900", "e il numero dell'ordine, per la riga di fattura");
      eq(con.listino, 12, "il listino resta scritto accanto: chi riceve il documento deve poter rifare il conto");
    });

    /* ⛔ IL PRINCIPIO DEL FONDATORE, CASO PER CASO. Nessuno di questi cinque
       ripiega: né sul prezzo dell'ordine «più o meno giusto», né sul listino
       di nascosto. `calcolabile: false` e la ragione scritta. */
    test("⛔ A3 · prodotto che nell'ordine NON c'è: non determinabile, e detto", () => {
      const sabbia = { prodottoId: "a3s", prodotto: "Sabbia lavata 0/4", unitaVendita: "m3", densita: 1.6 };
      const pr = conti.prezzoDaOrdine(ORD, sabbia);
      eq(pr.fonte, "non-determinabile", "un carico di sabbia su un ordine di pietrisco non ha un prezzo pattuito");
      eq(pr.calcolabile, false, "la bandiera lo dichiara");
      eq(pr.motivo, "prodotto-fuori-ordine", "e dice quale dei casi è");
      eq(pr.prezzoUnitario, null, "nessun ripiego sul prezzo dell'ordine");
      ok(pr.perche.includes("Sabbia lavata 0/4"), "e nomina il prodotto: " + pr.perche);
      ok(conti.descriviPrezzoOrdine(pr).includes("non si può applicare"), "la frase legge la bandiera");
      /* e il ripiego NASCOSTO sul listino è quello che si vede peggio: qui si
         pretende che `rigaPesata` non produca nessun numero. */
      const r = conti.rigaPesata({ ...PIE, id: "a3s", nome: "Sabbia lavata 0/4" }, 39.4, 13.8, CLI5, ORD);
      eq(r.prezzoUnitario, null, "e rigaPesata non tira fuori il listino di nascosto");
      eq(r.valore, null, "né un valore");
      eq(r.motivoPrezzo, "prodotto-fuori-ordine", "e porta con sé il motivo");
      ok(r.perchePrezzo.length > 0, "e la ragione da scrivere sullo schermo");
    });

    test("⛔ A3 · due righe dello stesso prodotto a condizioni diverse: non determinabile", () => {
      /* il caso che `consegnatoOrdine` dichiara essere la norma in cava: «500 t
         a 12 più 300 t del secondo lotto a 11». Un DDT è un camion e non dice
         a quale delle due righe appartiene. */
      const due = { ...ORD, righe: [
        { prodottoId: "a3p", descrizione: "Pietrisco 8/12", quantita: 500, unita: "t", prezzoUnitario: 12, scontoPct: 0 },
        { prodottoId: "a3p", descrizione: "Pietrisco 8/12", quantita: 300, unita: "t", prezzoUnitario: 11, scontoPct: 0 }] };
      const pr = conti.prezzoDaOrdine(due, DDT);
      eq(pr.fonte, "non-determinabile", "non si sceglie la più bassa per prudenza né la più alta per cautela");
      eq(pr.motivo, "piu-prezzi", "detto per nome");
      eq(pr.prezzoUnitario, null, "e nessun numero");
      /* ma se le due righe dicono la STESSA cosa non c'è nessuna ambiguità:
         una regola troppo severa qui bloccherebbe un ordine perfettamente sano. */
      const uguali = { ...due, righe: due.righe.map((r) => ({ ...r, prezzoUnitario: 12 })) };
      const ok2 = conti.prezzoDaOrdine(uguali, DDT);
      eq(ok2.fonte, "ordine", "due righe alle stesse condizioni non sono un'ambiguità");
      eq(ok2.prezzoUnitario, 12, "e il prezzo è quello");
      eq(ok2.righe, 2, "e la funzione dice su quante righe ha guardato");
    });

    test("⛔ A3 · unità diverse fra ordine e DDT: il prezzo si converte con la formula dei PREZZI", () => {
      /* ordine in metri cubi (18 €/m³), DDT in tonnellate, densità 1,5.
         ⚠️ Questa prova esiste per un centesimo, e il centesimo l'ha trovato il
         prototipo: convertendo con `convertiQuantita(1,"t","m3",1.5)` — che
         arrotonda a 0,667 — usciva 12,01 invece di 12,00. Otto euro su 800 t,
         su un documento fiscale. */
      const oM3 = { ...ORD, righe: [{ prodottoId: "a3p", descrizione: "Pietrisco 8/12",
        quantita: 100, unita: "m3", densita: 1.5, prezzoUnitario: 18, scontoPct: 0 }] };
      const pr = conti.prezzoDaOrdine(oM3, DDT);
      eq(pr.fonte, "ordine", "si converte, non si rinuncia");
      eq(pr.prezzoUnitario, 12, "18 €/m³ con densità 1,5 fanno 12,00 €/t esatti, non 12,01");
      eq(pr.unita, "t", "e il prezzo esce nell'unità del DDT");
      /* la densità è quella del DDT, non quella fotografata sull'offerta: è la
         stessa con cui `consegnatoOrdine` converte la quantità, e le due devono
         essere la stessa o gli euro non corrispondono all'ordinato consumato. */
      const senzaDens = conti.prezzoDaOrdine(oM3, { ...DDT, densita: null });
      eq(senzaDens.fonte, "non-determinabile", "senza la densità del DDT non si converte");
      eq(senzaDens.motivo, "densita-mancante", "detto per nome");
      eq(senzaDens.prezzoUnitario, null, "e non si ripiega sui 18 €/m³ letti come se fossero €/t");
    });

    test("⛔ A3 · un documento che non è un ordine accettato non ha nessun pattuito", () => {
      for (const st of ["bozza", "inviato", "rifiutato", "annullato"]) {
        const pr = conti.prezzoDaOrdine({ ...ORD, stato: st }, DDT);
        eq(pr.fonte, "non-determinabile", st + ": nessun prezzo è stato concordato");
        eq(pr.motivo, "ordine-non-confermato", st + ": detto per nome");
      }
      eq(conti.prezzoDaOrdine({ ...ORD, stato: "accettato" }, DDT).fonte, "ordine",
         "e l'accettato invece sì, se no la prova qui sopra passerebbe per il motivo sbagliato");
    });

    test("⛔ A3 · riga d'ordine senza prezzo: non se ne inventa uno", () => {
      const senzaP = { ...ORD, righe: [{ prodottoId: "a3p", descrizione: "Pietrisco 8/12",
        quantita: 100, unita: "t", prezzoUnitario: null, scontoPct: 0 }] };
      const pr = conti.prezzoDaOrdine(senzaP, DDT);
      eq(pr.motivo, "riga-senza-prezzo", "l'offerta è stata salvata senza prezzo");
      eq(pr.prezzoUnitario, null, "e nessuno lo inventa");
    });

    test("A3 · la fornitura a chiamata ha il prezzo bloccato e la quantità no", () => {
      /* l'accordo quadro: «prezzo bloccato fino a fine anno, quantità a
         chiamata». La quantità mancante rende non misurabile l'AVANZAMENTO
         (`consegnatoOrdine` lo dice già), ma il PREZZO è stato concordato
         eccome — è tutto il senso di un accordo quadro. Le due cose sono
         indipendenti e questa prova impedisce di confonderle. */
      const quadro = { ...ORD, righe: [{ prodottoId: "a3p", descrizione: "Pietrisco 8/12",
        quantita: null, unita: "t", densita: 1.5, prezzoUnitario: 11.5, scontoPct: 5, imponibile: null }] };
      const pr = conti.prezzoDaOrdine(quadro, DDT);
      eq(pr.fonte, "ordine", "il prezzo c'è");
      eq(pr.prezzoUnitario, 11.5, "ed è quello bloccato");
      eq(conti.avanzamentoOrdine(quadro, []).misurabile, false,
         "mentre quanto è stato consegnato resta non misurabile: sono due domande diverse");
    });

    test("⛔ A3 · la riga di fattura non mescola prezzi pattuiti e prezzi di listino", () => {
      /* stessa ragione per cui lo sconto entra già nella chiave: unire le due
         vorrebbe dire scegliere quale delle due storie raccontare, e la riga
         direbbe una cosa vera per metà dei DDT che la compongono. */
      const base = { prodottoId: "a3p", prodotto: "Pietrisco 8/12", unitaVendita: "t",
        quantita: 10, prezzoUnitario: 10.5, scontoPct: 5, aliquotaIva: 22 };
      const r = conti.righeDaPesate([
        { ...base, id: "x1", numero: "1", fontePrezzo: "ordine", ordineId: "a3o" },
        { ...base, id: "x2", numero: "2", fontePrezzo: "listino" }]);
      eq(r.length, 2, "stesso prodotto, stesso prezzo, stessa aliquota: restano due righe");
      eq(r.map((x) => x.fontePrezzo), ["ordine", "listino"], "e ognuna dice da dove viene");
      eq(r[0].ordineIds, ["a3o"], "quella pattuita porta il riferimento d'ordine, che la fattura stampa");
      eq(r[1].ordineIds, [], "l'altra no");
      /* ⛔ e l'ASSENZA è una terza chiave, non un sinonimo di «listino»: i DDT
         salvati prima di oggi non dichiarano niente, e spacciarli per listino
         sarebbe esattamente il numero tranquillo dove non è stato deciso nulla. */
      const con3 = conti.righeDaPesate([
        { ...base, id: "x1", numero: "1", fontePrezzo: "ordine", ordineId: "a3o" },
        { ...base, id: "x2", numero: "2", fontePrezzo: "listino" },
        { ...base, id: "x3", numero: "3" }]);
      eq(con3.length, 3, "tre provenienze diverse, tre righe");
      eq(con3.map((x) => x.fontePrezzo), ["ordine", "listino", null], "e la terza dichiara di non sapere");
      /* mentre due DDT dello stesso ordine si uniscono, come devono */
      const uniti = conti.righeDaPesate([
        { ...base, id: "x1", numero: "1", fontePrezzo: "ordine", ordineId: "a3o" },
        { ...base, id: "x2", numero: "2", fontePrezzo: "ordine", ordineId: "a3o" }]);
      eq(uniti.length, 1, "stesso ordine e stesse condizioni: una riga sola");
      eq(uniti[0].quantita, 20, "con le quantità sommate");
      eq(uniti[0].ordineIds, ["a3o"], "e il riferimento scritto una volta");
    });

    test("⛔ A3 · gli euro del DDT e l'ordinato che consuma parlano dello stesso ordine", () => {
      /* l'anello che chiude: la quantità che `consegnatoOrdine` scala
         dall'ordine e il prezzo che il DDT eredita devono venire dalla stessa
         riga. Se un giorno le due funzioni riconoscessero «lo stesso prodotto»
         in due modi diversi, un DDT consumerebbe l'ordine senza ereditarne il
         prezzo — e nessuna delle due prove di sopra se ne accorgerebbe. */
      const r = conti.rigaPesata(PIE, 39.4, 13.8, CLI5, ORD);
      const ddt = { id: "z1", numero: "2026/900", ordineId: "a3o", clienteId: "c1",
        prodottoId: "a3p", prodotto: "Pietrisco 8/12", unitaVendita: r.unitaVendita,
        quantita: r.quantita, netto: r.netto, densita: r.densita,
        prezzoUnitario: r.prezzoUnitario, scontoPct: r.scontoPct, fontePrezzo: r.fontePrezzo };
      const c = conti.consegnatoOrdine(ORD, [ddt]);
      eq(c.fuoriOrdine.length, 0, "il DDT consuma l'ordine");
      eq(c.prodotti[0].consegnato, 25.6, "per 25,6 t");
      eq(conti.valorePesata(ddt), 255.36, "e vale quanto quelle 25,6 t costano SULL'ORDINE");
      eq(conti.imponibileRiga(25.6, ORD.righe[0].prezzoUnitario, ORD.righe[0].scontoPct), 255.36,
         "cioè esattamente il conto rifatto dalla riga d'ordine");
    });

    test("A3 · la dimostrazione contiene il caso, e anche quello che non si sa", () => {
      const D = conti.DEMO;
      const d8 = D.pesate.find((p) => p.id === "d8");
      ok(!!d8, "c'è un DDT d'esempio agganciato all'ordine con lo scaglione");
      eq(d8.fontePrezzo, "ordine", "e dichiara di portare il prezzo dell'ordine");
      const o8 = D.ordini.find((o) => o.id === "o8");
      const p2 = D.prodotti.find((p) => p.id === "p2");
      eq(d8.prezzoUnitario, o8.righe[0].prezzoUnitario, "che è davvero quello dell'ordine");
      eq(d8.scontoPct, o8.righe[0].scontoPct, "sconto compreso");
      ok(d8.prezzoUnitario < p2.prezzo,
         "e si vede la differenza col listino: " + d8.prezzoUnitario + " contro " + p2.prezzo);
      eq(conti.valorePesata(d8), 255.36, "255,36 € invece dei 291,84 che avrebbe scritto il listino");
      /* e rifacendola oggi con la funzione, la fotografia torna */
      const rifatta = conti.rigaPesata(p2, d8.lordo, d8.tara, D.clienti.find((c) => c.id === "c1"), o8);
      eq(rifatta.prezzoUnitario, d8.prezzoUnitario, "rifacendo il DDT oggi il prezzo torna");
      eq(rifatta.valore, conti.valorePesata(d8), "e il valore pure");
      /* ⛔ IL CASO CHE NON SI SA: un DDT agganciato salvato prima che Conti
         sapesse rispondere. Senza questa riga in dimostrazione, «provenienza
         non dichiarata» non lo vedrebbe mai nessuno. */
      const vecchio = D.pesate.find((p) => p.ordineId && p.fontePrezzo == null);
      ok(!!vecchio, "c'è anche il DDT agganciato che la provenienza non la dichiara");
      eq(conti.righeDaPesate([vecchio])[0].fontePrezzo, null,
         "e la riga di fattura non lo spaccia per listino");
    });
  }
}

// ══════════════════════════════════════════════════════════════════════
// TERRA · DA DOVE VIENE LA DENSITÀ
// ----------------------------------------------------------------------
// La densità è il fattore che fa parlare tonnellate e metri cubi, e da lei
// passano due numeri che escono dall'azienda. Queste prove difendono una cosa
// sola: che un valore tipico di manuale e un certificato di laboratorio NON
// finiscano sullo schermo con la stessa faccia — e che una densità di cui non
// si sa niente si dichiari tale invece di ricadere su «a mano».
// ══════════════════════════════════════════════════════════════════════
{
  console.log("\n— Terra: la provenienza della densità —");

  test("Terra · densitaDichiarata: un `da` fuori vocabolario NON viene corretto a indovinare, ricade su «non dichiarata»", () => {
    for (const da of [undefined, "", "regione", "istat", "campo", "non dichiarata", 42]) {
      const o = terra.densitaDichiarata({ densita: 1.9, da });
      eq(o.da, terra.DENS_NON_DICHIARATA, "con da=" + mostra(da));
      eq(o.noto, false, "e `noto` è false con da=" + mostra(da));
    }
    eq(terra.densitaDichiarata({ densita: 1.9, da: "  ATTO " }).da, terra.DENS_ATTO,
       "mentre spazi e maiuscole non fanno perdere una fonte vera");
  });

  test("Terra · densitaDichiarata: una densità assente NON torna indietro come zero", () => {
    for (const v of [undefined, null, ""]) {
      const o = terra.densitaDichiarata({ densita: v, da: "atto" });
      eq(o.densita, null, "densita=" + mostra(v) + ": `+null` fa zero e Number.isFinite(0) dice true");
      eq(o.leggibile, true, "e non è «illeggibile»: non c'è niente da leggere");
      eq(o.grezza, "", "e non resta nessun valore grezzo");
    }
  });

  test("Terra · densitaDichiarata: CORROTTO e ASSENTE non sono lo stesso stato", () => {
    const testo = terra.densitaDichiarata({ densita: "1,9", da: "atto" });   // virgola italiana: JS non la legge
    eq(testo.leggibile, false, "«1,9» salvato come testo non si legge come numero");
    eq(testo.grezza, "1,9", "e il valore grezzo si conserva, per poterlo mostrare a chi l'ha scritto");
    const zero = terra.densitaDichiarata({ densita: 0, da: "atto" });
    eq(zero.leggibile, true, "«0» invece È un numero");
    eq(zero.densita, null, "ma non è una densità");
    eq(terra.densitaDichiarata({ densita: -1.9 }).densita, null, "e nemmeno una negativa");
    eq(terra.densitaDichiarata({ densita: "1.9", da: "atto" }).densita, 1.9,
       "col punto, invece, si legge: il modulo non riscrive `numeroDaCampo`");
  });

  test("Terra · densitaDichiarata: è idempotente, se no rileggendo il proprio dato l'errore sparisce", () => {
    const casi = [null, {}, { densita: 0, da: "atto" }, { densita: "1,9" }, { densita: 1.9 },
      { densita: 1.9, da: "preset", etichetta: "E", fonte: "F" },
      { densita: 2.1, da: "laboratorio", quando: "2026-03-04", riferimento: "Cert. 118/26" }];
    for (const c of casi) {
      const a = terra.densitaDichiarata(c), b = terra.densitaDichiarata(a);
      eq(b, a, "secondo giro su " + mostra(c));
      eq(terra.descriviDensita(a), terra.descriviDensita(c), "e la frase non cambia su " + mostra(c));
    }
  });

  test("Terra · densitaPerEnte: un valore tipico non regge davanti a chi lo chiede, un certificato sì", () => {
    eq(terra.densitaPerEnte({ densita: 1.9, da: "preset", etichetta: "Sabbia e ghiaia" }).perEnte, false,
       "il preset è letteratura, non una misura di questo materiale");
    eq(terra.densitaPerEnte({ densita: 1.9, da: "manuale" }).perEnte, false, "«a mano» dice chi, non da dove");
    eq(terra.densitaPerEnte({ densita: 1.9 }).perEnte, false, "e senza provenienza non regge di sicuro");
    eq(terra.densitaPerEnte({ densita: 1.95, da: "atto" }).perEnte, true, "il numero prescritto dall'atto regge");
    eq(terra.densitaPerEnte({ densita: 2.1, da: "laboratorio", quando: "2026-03-04" }).perEnte, true,
       "e una prova di laboratorio con la sua data");
  });

  test("Terra · densitaPerEnte: una prova di laboratorio senza data non regge — l'assenza non è un dato favorevole", () => {
    const nuda = terra.densitaPerEnte({ densita: 2.1, da: "laboratorio" });
    eq(nuda.perEnte, false, "dichiarata e basta: non c'è niente da esibire");
    ok(/né la sua data né il riferimento/.test(nuda.perche), "e il motivo dice che cosa manca: " + nuda.perche);
    const soloRif = terra.densitaPerEnte({ densita: 2.1, da: "laboratorio", riferimento: "Cert. 118/26" });
    eq(soloRif.perEnte, false, "col solo riferimento non si sa a quando risalga");
    ok(/non la data/.test(soloRif.perche), "e il motivo lo dice: " + soloRif.perche);
  });

  test("Terra · densitaPerEnte: il 30 febbraio non scivola al 2 marzo, e non si confonde con «data mancante»", () => {
    const finta = terra.densitaPerEnte({ densita: 2.1, da: "laboratorio", quando: "2026-02-30" });
    eq(finta.perEnte, false, "una data che non esiste non vale come data");
    ok(/non è un giorno che esiste/.test(finta.perche), "e il motivo NON dice che la data manca: " + finta.perche);
    ok(!/né la sua data/.test(finta.perche),
       "dire «non risulta la data» a chi l'ha scritta è una bugia dell'app: " + finta.perche);
  });

  test("Terra · descriviDensita: senza provenienza la frase non somiglia a una tracciatura", () => {
    const f = terra.descriviDensita({ densita: 1.9 });
    ok(/provenienza non è dichiarata/.test(f), "lo dice in chiaro: " + f);
    ok(/non è riconducibile a nessun documento/.test(f), "e dice perché conta: " + f);
    ok(/1,90 t\/m³/.test(f), "il numero c'è lo stesso: il calcolo si fa, la sua debolezza si dichiara");
  });

  test("Terra · descriviDensita: quattro provenienze, quattro frasi diverse", () => {
    const frasi = [
      terra.descriviDensita({ densita: 1.95, da: "atto", riferimento: "Atto n. 128 del 2021" }),
      terra.descriviDensita({ densita: 2.1, da: "laboratorio", quando: "2026-03-04", riferimento: "Cert. 118/26" }),
      terra.descriviDensita({ densita: 1.9, da: "preset", etichetta: "Sabbia e ghiaia (deposito)", fonte: "Geostru" }),
      terra.descriviDensita({ densita: 1.7, da: "manuale" }),
    ];
    eq(new Set(frasi).size, 4, "quattro frasi distinte, se no le fonti si presentano uguali");
    ok(/Atto n\. 128 del 2021/.test(frasi[0]), "l'atto nomina il documento: " + frasi[0]);
    ok(/Cert\. 118\/26/.test(frasi[1]) && /04\/03\/2026/.test(frasi[1]), "il laboratorio nomina certificato e data: " + frasi[1]);
    ok(/fonte: Geostru/.test(frasi[2]) && /confermata con una prova di laboratorio/.test(frasi[2]),
       "il valore tipico cita la fonte E dice che va confermato: " + frasi[2]);
    ok(/non risulta il documento da cui viene/.test(frasi[3]), "«a mano» dice il suo limite: " + frasi[3]);
    for (const f of frasi) ok(/in banco/.test(f), "e tutte dicono che è il peso di volume IN BANCO: " + f);
  });

  test("Terra · descriviDensita: «non impostata», «testo» e «zero» sono tre frasi diverse", () => {
    const niente = terra.descriviDensita(null);
    const testo = terra.descriviDensita({ densita: "1,9" });
    const zero = terra.descriviDensita({ densita: 0 });
    eq(new Set([niente, testo, zero]).size, 3, "tre stati, tre frasi");
    ok(/non impostata/.test(niente), niente);
    ok(/come testo/.test(testo) && /«1,9»/.test(testo), "e mostra quello che c'è scritto: " + testo);
    ok(/non può pesare zero/.test(zero), zero);
    ok(!/non impostata/.test(zero), "uno «0» scritto da qualcuno non è un campo vuoto: " + zero);
  });

  test("Terra · descriviDensita: fonte dichiarata ma numero assente si dice, non si tace", () => {
    const f = terra.descriviDensita({ da: "laboratorio", quando: "2026-03-04" });
    ok(/non impostata/.test(f), f);
    ok(/risulta dichiarata la provenienza/.test(f), "e dice che la metà scritta c'è: " + f);
  });

  test("Terra · densitaDellaCava: dal materiale dell'atto esce un valore tipico, dichiarato tale", () => {
    const d = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", numeroAtto: "Atto n. 128" });
    eq(d.da, terra.DENS_PRESET, "il ripiego è il preset del litotipo…");
    eq(d.densita, 1.9, "…col suo numero");
    eq(terra.densitaPerEnte(d).perEnte, false, "…e non regge davanti a chi lo chiede");
    eq(terra.densitaDellaCava({ materiale: "Materiale che non esiste" }).da, terra.DENS_NON_DICHIARATA,
       "un materiale che nessun preset riconosce non si indovina");
    eq(terra.densitaDellaCava(null).densita, null, "e senza atto non c'è niente");
  });

  test("Terra · densitaDellaCava: un numero SENZA fonte non diventa «a mano» — resta «non dichiarata»", () => {
    const d = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", densita: 1.95 });
    eq(d.densita, 1.95, "il numero scritto dall'utente vince sul preset");
    eq(d.da, terra.DENS_NON_DICHIARATA, "ma nessuno ha detto da dove viene, e l'app non lo inventa");
    eq(d.noto, false, "quindi `noto` è false");
  });

  test("Terra · densitaDellaCava: un valore impossibile NON viene sostituito di nascosto dal preset", () => {
    const zero = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", densita: 0 });
    eq(zero.densita, null, "«0» non diventa 1,9: l'errore di chi scrive resta visibile");
    eq(zero.grezza, "0", "e si conserva per poterglielo mostrare");
    const testo = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", densita: "mille", densitaFonte: "atto" });
    eq(testo.leggibile, false, "e nemmeno un testo diventa un preset");
    const soloFonte = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", densitaFonte: "laboratorio" });
    eq(soloFonte.da, terra.DENS_LABORATORIO, "chi ha dichiarato la fonte senza il numero non si vede sostituire la fonte");
    eq(soloFonte.densita, null, "e il numero resta mancante");
  });

  test("Terra · densitaDellaCava: dichiarata «dall'atto», il documento da esibire è l'atto stesso", () => {
    const d = terra.densitaDellaCava({ materiale: "Sabbia e ghiaia", densita: 1.95,
                                       densitaFonte: "atto", numeroAtto: "Atto n. 128 del 2021" });
    eq(d.riferimento, "Atto n. 128 del 2021", "il numero d'atto fa da riferimento se non ce n'è uno più preciso");
    ok(/Atto n\. 128 del 2021/.test(terra.descriviDensita(d)), "e finisce nella frase");
    const preciso = terra.densitaDellaCava({ densita: 1.95, densitaFonte: "atto",
                                             numeroAtto: "Atto n. 128", densitaRiferimento: "art. 7 del disciplinare" });
    eq(preciso.riferimento, "art. 7 del disciplinare", "ma un riferimento scritto a mano vince");
  });

  test("Terra · FONTI_DENSITA: la mappa copre tutte le parole del vocabolario, e solo «non dichiarata» è gialla", () => {
    const voc = [terra.DENS_ATTO, terra.DENS_LABORATORIO, terra.DENS_PRESET,
                 terra.DENS_MANO, terra.DENS_NON_DICHIARATA];
    eq(Object.keys(terra.FONTI_DENSITA).length, voc.length, "nessuna voce in più né in meno");
    for (const v of voc) ok(terra.FONTI_DENSITA[v] && terra.FONTI_DENSITA[v].label, "manca la voce «" + v + "»");
    const gialle = voc.filter((v) => terra.FONTI_DENSITA[v].cls === "warn");
    eq(gialle, [terra.DENS_NON_DICHIARATA],
       "«a mano» è una pratica legittima: un badge giallo su ogni densità battuta a mano si impara a non guardare");
    /* ⚠️ `label` è la voce di una TENDINA, e a 320 px Chromium taglia oltre i
       ~30 caratteri: le prime stesure finivano in «Prova di laboratorio sul
       mate…», cioè il taglio si portava via proprio la differenza fra le due
       fonti forti. Trovato con uno scatto, tenuto chiuso qui. */
    for (const v of voc)
      ok(terra.FONTI_DENSITA[v].label.length <= 30,
         `«${terra.FONTI_DENSITA[v].label}» è lunga ${terra.FONTI_DENSITA[v].label.length}: a 320 px la tendina la taglia`);
  });

  /* La regola del `shared/` pretende l'IDENTITÀ, non il comportamento: due
     copie uguali oggi divergono domani senza che nessuno lo veda. Qui serve
     due volte — `terra-data.js` ri-esporta questi tre nomi E li importa per
     usarli dentro `densitaDellaCava`, e un `export … from` non crea un nome
     locale: la doppia scrittura è il punto in cui una seconda copia potrebbe
     entrare senza far cadere niente. */
  test("Terra · le densità di riferimento sono LO STESSO oggetto di shared/, non una copia", () => {
    ok(terra.densitaDelMateriale === ponti.densitaDelMateriale, "densitaDelMateriale");
    ok(terra.DENSITA_PRESET === ponti.DENSITA_PRESET, "DENSITA_PRESET");
    ok(terra.presetDensita === ponti.presetDensita, "presetDensita");
  });

  /* ⚠️ TRE PROVENIENZE NELL'ECOSISTEMA, E NON SONO LA STESSA IDEA. `origineDi`
     dice COME è stato calcolato un volume, `provenienzaMisura` di Sentinella
     dice PER CHE STRADA è entrato un numero già misurato, e questa dice CHI
     RISPONDE di un fattore di conversione mai misurato in cava. La prova non è
     una dichiarazione: è lo stesso oggetto passato a due delle tre, che
     rispondono cose diverse — se un giorno diventassero la stessa cosa, questa
     cade e il duplicato va in `shared/`. */
  test("Terra · la provenienza della densità NON è la provenienza del volume", () => {
    const r = { origine: { da: "visore", cella: 0.5 }, densita: 1.9 };
    eq(terra.origineDi(r).da, "visore", "per il VOLUME l'origine è il visore…");
    eq(terra.densitaDichiarata(r).da, terra.DENS_NON_DICHIARATA,
       "…e per la DENSITÀ, sullo stesso identico oggetto, non risulta niente");
    ok(terra.origineDi !== terra.densitaDichiarata, "e non sono la stessa funzione");
    for (const n of ["densitaDichiarata", "densitaPerEnte", "descriviDensita", "densitaDellaCava", "FONTI_DENSITA"])
      ok(!(n in sentinella), "il nome «" + n + "» non collide con Sentinella: due idee diverse, due nomi diversi");
  });

  test("Terra · la densità dell'atto d'esempio è quella con cui sono stati costruiti i rapportini", () => {
    const a = terra.autorizzazioneVigente(terra.DEMO.autorizzazioni);
    const d = terra.densitaDellaCava(a);
    eq(d.densita, 1.9, "se cambia, il 2,4% di scostamento della dimostrazione non è più quello");
    eq(d.da, terra.DENS_PRESET, "e la dimostrazione mostra proprio lo stato del primo giorno: un valore tipico da confermare");
  });

  /* ⛔ IL TRASLOCO IN `shared/` (01/08), E LA PROVA CHE PRETENDE L'IDENTITÀ.
     Il vocabolario, `densitaDichiarata` e `densitaDellaCava` vivevano in
     `terra-data.js` e adesso stanno in `shared/dw-ponti.js`, perché Campo legge
     la stessa autorizzazione. Qui non si confronta il COMPORTAMENTO ma
     l'oggetto: due copie che oggi si comportano uguale divergono domani senza
     che nessuno lo veda, ed è la regola vincolante del `shared/`. Serve doppio,
     come per `densitaDelMateriale` qui sopra: `terra-data.js` ri-esporta questi
     nomi E ne importa una parte per usarli dentro `densitaPerEnte` e
     `descriviDensita`, e un `export … from` non crea un nome locale — la doppia
     scrittura è il punto esatto in cui una seconda copia entrerebbe senza far
     cadere niente. */
  test("Terra · la provenienza della densità è LO STESSO oggetto di shared/, non una copia", () => {
    for (const n of ["DENS_ATTO", "DENS_LABORATORIO", "DENS_PRESET", "DENS_MANO",
                     "DENS_NON_DICHIARATA", "FONTI_DENSITA", "densitaDichiarata", "densitaDellaCava"])
      ok(terra[n] === ponti[n], n + ": Terra ri-esporta quella di shared/, non ne riscrive una sua");
    /* E le due rimaste in Terra ci devono RESTARE: rispondono a domande che pone
       solo Terra (regge davanti all'ente? che riga scrivo sotto il campo?), e
       `shared/` non è un cassetto dove si mette per ordine. Se un giorno servissero
       a una seconda app, questa riga cade e vanno spostate — non copiate. */
    for (const n of ["densitaPerEnte", "descriviDensita"])
      ok(typeof terra[n] === "function" && !(n in ponti),
         n + " resta di Terra: nessuna seconda app la chiama");
  });

  /* ⛔ LA PROVA CHE CONTA DAVVERO, ed è quella che il difetto avrebbe fatto
     cadere. Terra e Campo costruiscono la STESSA `riconciliazioneTurni` sulla
     STESSA autorizzazione: se il fattore che converte tonnellate in metri cubi
     non è lo stesso numero, le due schermate mostrano due scostamenti diversi
     per la stessa cava e lo stesso mese — e nessuna delle due sbaglia da sola,
     quindi nessuno se ne accorge.
     Misurato prima di correggere: Campo chiamava `densitaDelMateriale(vig.materiale)`
     e rispondeva **1,90** dove Terra rispondeva **1,95**. */
  test("Terra e Campo · con la stessa autorizzazione, la stessa densità", () => {
    const aut = { stato: "vigente", materiale: "Sabbia e ghiaia", numeroAtto: "DET. 412/2024",
                  densita: 1.95, densitaFonte: "laboratorio",
                  densitaQuando: "2026-03-11", densitaRiferimento: "Cert. lab. 88/2026" };
    // la chiamata di Terra e quella di Campo passano dalla stessa funzione
    eq(terra.densitaDellaCava(aut).densita, ponti.densitaDellaCava(aut).densita,
       "lo stesso numero, se no due scostamenti sulla stessa cava");
    eq(ponti.densitaDellaCava(aut).densita, 1.95,
       "ed è quella di laboratorio scritta nell'atto…");
    ok(ponti.densitaDellaCava(aut).densita !== ponti.densitaDelMateriale(aut.materiale).densita,
       "…NON il valore tipico del litotipo, che è quello che Campo usava e che vale 1,9");
    eq(ponti.densitaDellaCava(aut).da, terra.DENS_LABORATORIO,
       "e la provenienza arriva fino a Campo insieme al numero");
  });

  /* ⛔ NESSUN RIPIEGO SILENZIOSO, ed è la metà della regola che il trasloco non
     doveva rompere: se l'atto non porta nessuna densità, la risposta è quella
     di prima — il valore tipico del litotipo, DICHIARATO valore tipico — e se
     nemmeno il materiale si riconosce non si inventa un numero. */
  test("Terra e Campo · senza densità nell'atto resta il preset, e resta detto che è un preset", () => {
    const nudo = { stato: "vigente", materiale: "Sabbia e ghiaia" };
    const d = ponti.densitaDellaCava(nudo);
    eq(d.densita, ponti.densitaDelMateriale(nudo.materiale).densita,
       "il ripiego è lo stesso di prima: Campo non cambia numero nel caso comune");
    eq(d.da, terra.DENS_PRESET, "…e non si spaccia per una misura");
    eq(ponti.densitaDellaCava({ materiale: "Materiale che non esiste" }).densita, null,
       "materiale non riconosciuto: niente, non un numero inventato");
    eq(ponti.densitaDellaCava(null).densita, null, "e senza atto nemmeno");
  });

  /* ⛔ E LA METÀ CHE LE PROVE QUI SOPRA NON GUARDAVANO — misurata, non temuta.
     L'identità (`terra.X === ponti.X`) difende il lato `shared/`: nessuno può
     riscrivere la regola in Terra. Ma il difetto vero non stava lì: stava nella
     PAGINA di Campo, che chiamava `densitaDelMateriale(vig.materiale)`. E
     rimettendo quel difetto sul disco — import compreso — `run-kpi`, `run-stile`,
     `nomi-doppi` e `copertura-funzioni` restano **tutte e quattro verdi**: le
     suite `node` non aprono le pagine, quindi il lato dove il difetto è nato era
     scoperto. È la guardia scollegata: la regola c'è, e non la legge nessuno.

     Due controlli, e servono tutt'e due — il secondo perché il primo da solo non
     vede la regressione più probabile, cioè l'import lasciato lì e l'argomento
     riportato al preset (misurato: la guardia 1 passa, la 2 no).

     ⚠️ E si guarda il CODICE, non il testo: `mascheraCodice` toglie commenti e
     contenuto delle stringhe. Senza, questo controllo accuserebbe **il commento
     che documenta la correzione** dentro la pagina di Campo — è esattamente
     l'inciampo su cui è già caduta la regola 6 di `run-stile.mjs`.

     Le superfici si SCOPRONO leggendo chi chiama `riconciliazioneTurni`: un
     elenco scritto a mano non contiene l'app che nascerà domani, e allora il
     controllo risponde «pulito» dopo aver guardato quelle che conosceva già. */
  {
    const { readFileSync, readdirSync } = await import("node:fs");
    const { mascheraCodice } = await import("./tokenizza.mjs");
    const APPS = join(HERE, "../..");

    /* quante volte `ago` compare nel codice VERO di `src` */
    const volteNelCodice = (src, ago) => {
      const vivo = mascheraCodice(src);
      let n = 0, i = 0;
      while ((i = src.indexOf(ago, i)) >= 0) {
        let tutto = true;
        for (let k = i; k < i + ago.length; k++) if (!vivo[k]) { tutto = false; break; }
        if (tutto) n++;
        i += ago.length;
      }
      return n;
    };

    const superfici = [];
    for (const nome of readdirSync(APPS)) {
      let src;
      try { src = readFileSync(join(APPS, nome, "index.html"), "utf8"); } catch { continue; }
      if (volteNelCodice(src, "riconciliazioneTurni(") > 0) superfici.push({ nome, src });
    }

    test("Terra e Campo · le superfici che riconciliano sono quelle attese, e sono più di una", () => {
      /* il numero stampato è la difesa contro il controllo che non guarda dove
         crede: uno «zero violazioni» su zero soggetti si legge uguale. */
      ok(superfici.length >= 2,
         `superfici che costruiscono riconciliazioneTurni: ${superfici.length} (${superfici.map(s => s.nome).join(", ") || "nessuna"}) — se scendono a una, questa regola non ha più due app da tenere insieme`);
      eq(superfici.map(s => s.nome).sort(), ["campo", "terra"],
         "se ne nasce una terza va guardata anche lei: l'elenco si scopre, non si scrive");
    });

    for (const { nome, src } of superfici) {
      test(`${nome} · la densità della riconciliazione la decide densitaDellaCava, non la pagina`, () => {
        ok(volteNelCodice(src, "densitaDellaCava") > 0,
           `${nome}/index.html costruisce riconciliazioneTurni ma non nomina mai densitaDellaCava nel suo codice: sta decidendo da sé quale densità vale`);
        eq(volteNelCodice(src, "densitaDelMateriale("), 0,
           `${nome}/index.html chiama densitaDelMateriale( per conto suo: il valore tipico è UNO dei quattro casi, e a sceglierlo è densitaDellaCava — che il preset lo consulta già`);
      });
    }

    /* ⚠️ UNA PROVA CHE NON SA FALLIRE NON DIMOSTRA NIENTE: il difetto vero,
       rimesso nel TESTO (non sul disco, che le pagine se lo caricano). */
    test("Terra e Campo · la controprova: il difetto rimesso in Campo viene visto", () => {
      const campoSrc = superfici.find(s => s.nome === "campo").src;
      const rotto = campoSrc
        .replace("periodoFraUltimiRilievi, densitaDellaCava }", "periodoFraUltimiRilievi, densitaDelMateriale }")
        .replace("const dens = densitaDellaCava(vig);", "const dens = densitaDelMateriale(vig && vig.materiale);");
      ok(rotto !== campoSrc, "l'iniezione non ha iniettato niente: il testo da sostituire è cambiato, la controprova va riscritta");
      eq(volteNelCodice(rotto, "densitaDellaCava"), 0, "col difetto rimesso, la guardia 1 deve cadere");
      ok(volteNelCodice(rotto, "densitaDelMateriale(") > 0, "…e anche la guardia 2");
      /* e la forma più probabile della regressione: l'import resta, l'argomento no.
         Qui la guardia 1 passa ancora — è la ragione per cui la 2 esiste. */
      const subdolo = campoSrc.replace("const dens = densitaDellaCava(vig);",
                                       "const dens = densitaDelMateriale(vig && vig.materiale) || {};");
      ok(subdolo !== campoSrc, "seconda iniezione: nessun carattere cambiato");
      ok(volteNelCodice(subdolo, "densitaDellaCava") > 0, "la guardia 1 da sola NON la vede…");
      ok(volteNelCodice(subdolo, "densitaDelMateriale(") > 0, "…e la vede solo la 2");
      /* e la prova che il tokenizzatore serve: nel testo grezzo di Campo
         `densitaDelMateriale(` c'è (nel commento che racconta la correzione),
         nel codice no. Senza `mascheraCodice` la guardia 2 sarebbe rossa oggi. */
      ok((campoSrc.match(/densitaDelMateriale\(/g) || []).length > 0,
         "il commento che documenta la correzione c'è ancora");
      eq(volteNelCodice(campoSrc, "densitaDelMateriale("), 0,
         "…ma è un commento, non una chiamata: è mascheraCodice a distinguerli");
    });
  }
}

// ────────────────────────────────────────────────────────────────────────
console.log("\n— Scudo: il ciclo di vita del DSS (D.Lgs 624/96 art. 6) —");
// Il DSS c'era già come TIPO di documento con uno stato messo a mano; quello
// che non c'era è il CICLO. Il cuore di queste prove è il terzo stato: un DSS
// senza data di revisione non è «aggiornato» e non è «scaduto», è NON
// DATABILE — il principio del fondatore sul documento che un ispettore chiede
// per primo in una cava.
{
  const OGGI_DSS = new Date(2026, 7, 1);          // 01/08/2026, ora locale
  const INF_DSS = [
    { id: "x1", data: "2026-02-03", tipo: "infortunio", gravita: "lieve" },
    { id: "x2", data: "2025-09-12", tipo: "infortunio", gravita: "lieve" },
    { id: "x3", data: "2026-05-18", tipo: "near-miss", gravita: "lieve" },
  ];
  const conGrave = INF_DSS.concat([{ id: "xg", data: "2026-06-10", tipo: "infortunio", gravita: "grave" }]);
  const dss = (extra) => ({ id: "c4", titolo: "DSS", tipo: "DSS", cantiereId: "k1", ...extra });

  test("Scudo · cicloDss: senza documento è «assente», e lo dice invece di tacere", () => {
    const c = scudo.cicloDss(null, INF_DSS, OGGI_DSS);
    eq(c.stato, "assente");
    eq(c.noto, false, "un DSS che non vediamo non è un DSS che non esiste");
    eq(c.presente, false);
    ok(/da qui non lo vediamo/.test(scudo.descriviCicloDss(c)),
       "la frase deve dire che è Scudo a non saperlo, non che il documento manchi");
  });

  /* ⛔ LA PROVA PER CUI ESISTE TUTTO IL RESTO. */
  test("Scudo · cicloDss: senza data di revisione NON è «aggiornato» né «scaduto», è NON DATABILE", () => {
    const c = scudo.cicloDss(dss({ stato: "valido" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "non-databile");
    eq(c.noto, false);
    eq(c.giorniDaRevisione, null, "senza revisione non c'è nessuna età da scrivere");
    eq(c.scadenzaCertificazione, null, "e nessuna scadenza da calcolare");
    eq(c.statoCertificazione, "senza data");
    ok(scudo.etichettaCicloDss(c.stato).cls !== "ok",
       "il badge non può essere verde: è il numero tranquillo dove non è stato misurato niente");
    ok(scudo.descriviCicloDss(c).startsWith("Non lo sappiamo — "),
       "la bandiera `noto` deve arrivare fino alla frase");
  });

  test("Scudo · cicloDss: lo stato «valido» digitato a mano non rende databile il DSS", () => {
    // due documenti identici salvo lo stato del registro: il ciclo non cambia,
    // perché quello dice cos'ha digitato qualcuno, questo cosa risulta
    for (const st of ["valido", "da-rivedere", "scaduto", ""])
      eq(scudo.cicloDss(dss({ stato: st }), INF_DSS, OGGI_DSS).stato, "non-databile",
         "stato del registro «" + st + "»: il ciclo si legge dalle date, non dal badge");
  });

  test("Scudo · cicloDss: una data di revisione ROTTA vale come assente (2026-02-30 non esiste)", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-02-30" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "non-databile", "Date.parse la farebbe scivolare al 2 marzo: `dataISOEsiste` no");
    eq(c.revisione, null);
  });

  test("Scudo · cicloDss: un infortunio GRAVE dopo la revisione lo rende «da aggiornare»", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-03-01", dssMotivo: "periodica" }), conGrave, OGGI_DSS);
    eq(c.stato, "da-aggiornare");
    eq(c.graviDopo, 1);
    eq(c.noto, true, "qui sappiamo: l'evento è nel registro");
    eq(scudo.etichettaCicloDss(c.stato).cls, "danger");
  });

  test("Scudo · cicloDss: un infortunio grave PRIMA della revisione non la fa scattare", () => {
    // il DSS rivisto DOPO l'evento è il DSS che ha fatto la cosa giusta
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-07-01" }), conGrave, OGGI_DSS);
    eq(c.stato, "regolare", "l'evento del 10/06 è già dentro la revisione del 01/07");
    eq(c.graviDopo, 0);
    eq(c.graviRegistrati, 1, "ma resta scritto che un grave c'è stato");
  });

  test("Scudo · cicloDss: l'evento dello STESSO giorno della revisione si considera già dentro", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-06-10" }), conGrave, OGGI_DSS);
    eq(c.graviDopo, 0, "con `>=` una cava che rivede il DSS il giorno dell'incidente resterebbe rossa");
    eq(c.stato, "regolare");
  });

  test("Scudo · cicloDss: i near-miss NON fanno scattare l'aggiornamento del DSS", () => {
    const soloNm = [{ id: "n1", data: "2026-07-20", tipo: "near-miss", gravita: "grave" }];
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-03-01" }), soloNm, OGGI_DSS);
    eq(c.graviDopo, 0, "un mancato infortunio non è l'incidente dell'art. 6");
    eq(c.stato, "regolare");
  });

  test("Scudo · cicloDss: dopo dodici mesi la certificazione annuale è scaduta", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2025-01-10" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "certificazione-scaduta");
    eq(c.scadenzaCertificazione, "2026-01-10");
    eq(c.statoCertificazione, "scaduta");
    eq(scudo.etichettaCicloDss(c.stato).cls, "danger");
  });

  test("Scudo · cicloDss: entro trenta giorni dai dodici mesi è «in scadenza»", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2025-08-20" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "certificazione-in-scadenza");
    eq(c.scadenzaCertificazione, "2026-08-20");
    eq(scudo.etichettaCicloDss(c.stato).cls, "warn");
  });

  /* La periodicità NON è un numero nuovo: è quella del preset `dss-certif`.
     Se un giorno cambia là, questa prova cade — ed è quello che deve fare. */
  test("Scudo · cicloDss: i dodici mesi vengono dal preset «dss-certif», non da un numero scritto due volte", () => {
    eq(scudo.presetScadenza("dss-certif").mesi, 12, "il preset è la fonte della periodicità");
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-01-15" }), [], OGGI_DSS);
    eq(c.scadenzaCertificazione, scudo.dataDaPeriodicita(12, new Date("2026-01-15T00:00:00")),
       "e la data la calcola `dataDaPeriodicita`, la stessa che precompila i preset");
  });

  test("Scudo · cicloDss: il 31 non scivola al mese dopo (31/08 + 12 mesi)", () => {
    eq(scudo.cicloDss(dss({ dssRevisione: "2025-08-31" }), [], OGGI_DSS).scadenzaCertificazione, "2026-08-31");
    eq(scudo.cicloDss(dss({ dssRevisione: "2025-02-28" }), [], OGGI_DSS).scadenzaCertificazione, "2026-02-28");
  });

  /* ⛔ Una data di revisione nel FUTURO dava il verde per un anno intero: è la
     famiglia dello 0% di `avanzamentoLotto`, un numero tranquillo prodotto da
     un dato sbagliato. */
  test("Scudo · cicloDss: una revisione datata nel FUTURO non è «regolare», è da correggere", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2027-03-01" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "revisione-futura");
    eq(c.noto, false, "su una data falsa non si può dire niente");
    ok(c.giorniDaRevisione < 0, "l'età del documento è negativa: è il segno del refuso");
    ok(scudo.etichettaCicloDss(c.stato).cls !== "ok");
  });

  /* ⛔ IL SECONDO CORNO DEL PRINCIPIO: «nessun infortunio grave registrato»
     non vuol dire «non serve aggiornarlo». Le modifiche delle lavorazioni
     Scudo non le vede, e lo deve DIRE anche quando è tutto verde. */
  test("Scudo · cicloDss: anche da «regolare» dichiara che le modifiche delle lavorazioni non le vede", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-03-01" }), INF_DSS, OGGI_DSS);
    eq(c.stato, "regolare");
    eq(c.graviRegistrati, 0);
    const t = scudo.descriviCicloDss(c);
    ok(/modifiche delle lavorazioni/.test(t) && /non le vede/.test(t),
       "un verde che tace su quello che non ha guardato è il difetto che questo modulo esiste per non fare");
    ok(/Scudo non ha registrato nessun infortunio grave/.test(t),
       "e dice «non ne ho registrati», non «non ce ne sono stati»");
  });

  test("Scudo · descriviTrasmissioneDss: senza invio non diventa mai un sì", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-03-01" }), INF_DSS, OGGI_DSS);
    eq(c.trasmissioneAllineata, null, "manca una delle due date: non lo sappiamo");
    ok(/non ne resta traccia/.test(scudo.descriviTrasmissioneDss(c)));
  });

  test("Scudo · descriviTrasmissioneDss: un invio anteriore alla revisione è un «no» che si sa", () => {
    const c = scudo.cicloDss(dss({ dssRevisione: "2026-03-01", dssTrasmissione: "2025-11-02" }), INF_DSS, OGGI_DSS);
    eq(c.trasmissioneAllineata, false, "la versione in vigore non è quella trasmessa");
    ok(/non risulta trasmessa/.test(scudo.descriviTrasmissioneDss(c)));
    const b = scudo.cicloDss(dss({ dssRevisione: "2026-03-01", dssTrasmissione: "2026-03-05" }), INF_DSS, OGGI_DSS);
    eq(b.trasmissioneAllineata, true);
    ok(/dopo l'ultima revisione/.test(scudo.descriviTrasmissioneDss(b)));
    eq(scudo.descriviTrasmissioneDss(scudo.cicloDss(null, [], OGGI_DSS)), "",
       "senza documento non c'è nessuna trasmissione da raccontare");
  });

  /* Regola 18, ma dal lato giusto: `etichettaCicloDss` è uno `switch` con
     `default`, quindi non può uccidere la pagina — e la prova pretende che
     ogni stato che `cicloDss` sa dire abbia la sua etichetta. */
  test("Scudo · etichettaCicloDss: ogni stato che il ciclo sa dire ha la sua etichetta", () => {
    const stati = ["assente", "non-databile", "revisione-futura", "da-aggiornare",
                   "certificazione-scaduta", "certificazione-in-scadenza", "regolare"];
    for (const s of stati) {
      const e = scudo.etichettaCicloDss(s);
      ok(e && e.label && e.cls, "manca l'etichetta di «" + s + "»");
    }
    eq(stati.filter((s) => scudo.etichettaCicloDss(s).cls === "ok"), ["regolare"],
       "un solo stato può essere verde, ed è quello in cui si è guardato e va bene");
    eq(scudo.etichettaCicloDss("stato-mai-visto").label, "Stato non indicato",
       "il `default` esiste perché una mappa senza ripiego ucciderebbe la pagina al disegno");
  });

  /* ⛔ Nata da uno SCATTO: nella riga del Quadro `descriviCicloDss` finiva
     tagliata da `-webkit-line-clamp:2` a metà di «non è…», cioè proprio dove
     il principio del fondatore vuole essere letto. La forma corta è una frase
     INTERA, e la prova pretende che stia dentro il taglio. */
  test("Scudo · sintesiCicloDss: una frase intera e corta per ogni stato, che la riga del Quadro non tagli", () => {
    const stati = ["assente", "non-databile", "revisione-futura", "da-aggiornare",
                   "certificazione-scaduta", "certificazione-in-scadenza", "regolare"];
    for (const s of stati) {
      const t = scudo.sintesiCicloDss(s);
      ok(t && t.length <= 46, "«" + s + "» → «" + t + "» (" + (t || "").length + " caratteri): due righe a 430px non lo reggono");
      ok(!/…|\.\.\./.test(t), "«" + s + "»: una sintesi non finisce con i puntini, è una frase intera");
    }
    eq(new Set(stati.map((s) => scudo.sintesiCicloDss(s))).size, stati.length,
       "due stati diversi non possono leggersi uguale nella riga del Quadro");
    eq(scudo.sintesiCicloDss("stato-mai-visto"), "Stato del ciclo non indicato",
       "il ripiego c'è, e non è una frase tranquilla");
  });

  test("Scudo · MOTIVI_REVISIONE_DSS: quattro motivi, ognuno con il suo riferimento", () => {
    eq(scudo.MOTIVI_REVISIONE_DSS.map((m) => m.chiave),
       ["prima-stesura", "periodica", "dopo-evento", "dopo-modifica"]);
    for (const m of scudo.MOTIVI_REVISIONE_DSS) {
      ok(m.nome && m.riferimento, "il motivo «" + m.chiave + "» non porta la sua fonte");
      ok(/624\/96/.test(m.riferimento), "il riferimento deve nominare la norma, non alludervi");
    }
    eq(scudo.motivoRevisioneDss("dopo-evento").nome, "Dopo un infortunio o un incidente");
    eq(scudo.motivoRevisioneDss("inventato"), null, "una chiave sconosciuta non inventa un motivo");
    eq(scudo.motivoRevisioneDss(""), null);
  });

  test("Scudo · dssDiCantiere: solo i DSS di quella cava, dal più recente", () => {
    const docs = [
      { id: "a", tipo: "DSS", cantiereId: "k1", dssRevisione: "2025-01-10" },
      { id: "b", tipo: "DSS", cantiereId: "k1", dssRevisione: "2026-03-01" },
      { id: "c", tipo: "DVR", cantiereId: "k1" },
      { id: "d", tipo: "DSS", cantiereId: "k2" },
    ];
    eq(scudo.dssDiCantiere(docs, "k1").map((x) => x.id), ["b", "a"]);
    eq(scudo.dssDiCantiere(docs, "k2").map((x) => x.id), ["d"]);
    eq(scudo.dssDiCantiere(docs, null), [], "senza cava non si indovina");
    eq(scudo.dssDiCantiere(null, "k1"), []);
  });

  /* ⛔ Un DSS in archivio ma appeso a niente farebbe dire «non registrato» su
     una cava che il suo DSS ce l'ha: un allarme falso manda a rifare un
     documento che c'è, ed è il modo più veloce per farlo spegnere. */
  test("Scudo · dssScollegati: i DSS senza cava si contano a parte, non spariscono", () => {
    const docs = [
      { id: "a", tipo: "DSS", cantiereId: "k1" },
      { id: "b", tipo: "DSS" },
      { id: "c", tipo: "DSS", cantiereId: "" },
      { id: "d", tipo: "DVR" },
    ];
    eq(scudo.dssScollegati(docs).map((x) => x.id), ["b", "c"]);
    eq(scudo.dssScollegati([]), []);
  });

  test("Scudo · dssDaSeguire: solo le cave attive, e i rossi davanti", () => {
    const cant = [
      { id: "k1", nome: "Cava A", tipo: "cava", stato: "attivo" },
      { id: "k2", nome: "Cantiere", tipo: "cantiere", stato: "attivo" },
      { id: "k3", nome: "Cava chiusa", tipo: "cava", stato: "chiuso" },
      { id: "k4", nome: "Cava B", tipo: "cava", stato: "attivo" },
    ];
    const docs = [
      { id: "a", tipo: "DSS", cantiereId: "k1" },                            // non databile → warn
      { id: "b", tipo: "DSS", cantiereId: "k4", dssRevisione: "2025-01-10" }, // certif. scaduta → danger
    ];
    const r = scudo.dssDaSeguire(docs, cant, INF_DSS, OGGI_DSS);
    eq(r.map((x) => x.cantiere.id), ["k4", "k1"], "prima il rosso, poi il «non lo sappiamo»");
    eq(r.map((x) => x.stato), ["certificazione-scaduta", "non-databile"]);
    ok(!r.some((x) => x.cantiere.id === "k2"), "un cantiere esterno non ha un DSS di cava");
    ok(!r.some((x) => x.cantiere.id === "k3"), "una cava chiusa non ha lavorazioni da valutare");
  });

  test("Scudo · dssDaSeguire: una cava attiva SENZA nessun DSS collegato ci entra", () => {
    const cant = [{ id: "k1", nome: "Cava A", tipo: "cava", stato: "attivo" }];
    const r = scudo.dssDaSeguire([], cant, INF_DSS, OGGI_DSS);
    eq(r.length, 1, "è la riga più silenziosa di tutte: non produce niente di rosso, produce un elenco corto");
    eq(r[0].stato, "assente");
    eq(scudo.dssDaSeguire([{ id: "a", tipo: "DSS", cantiereId: "k1", dssRevisione: "2026-03-01" }],
       cant, INF_DSS, OGGI_DSS), [], "e un ciclo regolare non affolla il Quadro");
  });

  test("Scudo · la dimostrazione contiene il caso per cui il ciclo esiste", () => {
    const D = scudo.DEMO;
    const doc = scudo.dssDiCantiere(D.documenti, "k1")[0];
    ok(doc, "la cava della dimostrazione ha il suo DSS in archivio");
    eq(doc.stato, "valido", "e il registro lo dice pure «valido»: tre cose rassicuranti");
    const c = scudo.cicloDss(doc, D.infortuni, OGGI_DSS);
    eq(c.stato, "non-databile",
       "…e nessuna delle tre è una data leggibile: è il punto di partenza vero di una cava che carica l'archivio");
    eq(scudo.dssScollegati(D.documenti), [], "nessun DSS della dimostrazione è appeso a niente");
  });
}

if (inVolo.length) await Promise.all(inVolo);   // si aspetta PRIMA di contare
console.log(`\nRisultato KPI app: ${passed} passati, ${failed} falliti${inVolo.length ? `  ·  ${inVolo.length} prove asincrone aspettate` : ""}`);
process.exit(failed > 0 ? 1 : 0);
